/* l=泳道 s=文明圈 v=色深(0基础 1浅 2深) k=[[年,影响力]] b=一句话 f=速览 d=详述 */
const CIVS = [
/* 欧洲 */
{ l:'eu', s:'west', v:1, n:'米诺斯·迈锡尼', k:[[-2700,0],[-2000,.35],[-1450,.45],[-1250,.35],[-1100,0]], b:'爱琴海青铜文明,宫殿与线形文字,毁于青铜时代大崩溃。',
  e:{ n:'Minoan–Mycenaean', b:'Bronze Age palace civilizations of the Aegean, undone by the great collapse.', d:'Crete built Europe\'s first palace civilization, trading with Egypt and the Levant; mainland Mycenae inherited and conquered it — the world behind the Trojan legends. The systemic collapse around 1200 BCE buried it for three millennia until archaeology recovered it.', f:{ 'Peak':'c. 1450 BCE', 'Center':'Knossos, Mycenae', 'Legacy':'Linear A/B, palace economy' } },
  f:{ '鼎盛':'约前1450年', '中心':'克诺索斯、迈锡尼', '成就':'线形文字A/B、宫殿经济' },
  qh:{ born:['学生学走了老师的制度,然后接管了他','The student learned the system, then took over the teacher'],
       rule:['东西先入库,再由宫殿统一分出去','Everything came into the store, and the palace gave it out'],
       money:['地不够种,财富只能向海上讨','Too little land, so the wealth had to come from the sea'],
       power:['特洛伊战争的传说,背景就是这个时代','The Trojan War legend is set in this very age'],
       fall:['宫殿烧了,文字没了,贸易断了','Palaces burned, writing lost, trade broken'],
       legacy:['破译之后才知道,他们说的就是希腊语','Once deciphered, the tablets turned out to be Greek'] },
  q:{ born:['克里特岛扼守爱琴海航路,米诺斯人靠海上贸易联通埃及与近东,建起欧洲最早的宫殿文明;数百年后,希腊本土的迈锡尼人学走宫殿制度与文字,约前1450年反客为主,接管了克里特。','Crete sat astride the Aegean sea lanes, and the Minoans built Europe\'s first palace civilization on trade with Egypt and the Near East. Centuries later the Mycenaeans of mainland Greece, who had learned palace administration and writing from them, turned the tables and took over Crete around 1450 BC.'],
      rule:['两个文明都以宫殿为国家中枢:粮食、油和羊毛先集中入库,再由宫殿统一分配,书吏用线形文字把每一笔都记在泥板上。米诺斯的统治者面目至今模糊;迈锡尼则由称作「瓦纳克斯」的国王坐镇设防的城堡。','Both civilizations ran palace states: grain, oil and wool flowed into central storerooms and were redistributed, with scribes recording every transaction on clay tablets in Linear script. Minoan rulers remain shadowy figures to this day; Mycenaean kings, called wanax, ruled from fortified citadels.'],
      money:['爱琴海土地有限,财富要向海上讨:橄榄油、葡萄酒、彩绘陶器和纺织品装船外销,换回埃及与近东的金属和奢侈品。宫殿既是仓库也是工场,握着大宗贸易的进出。','With little farmland, wealth had to come from the sea: olive oil, wine, painted pottery and textiles were shipped out in exchange for metals and luxuries from Egypt and the Near East. The palaces were warehouse and workshop in one, controlling the major flows of trade.'],
      power:['米诺斯的强大在海上,后世希腊人传说它曾是海上霸主;迈锡尼的强大在武力,青铜武器、战车与厚墙城堡使其称雄爱琴海。特洛伊战争的传说,正是以这个尚武的时代为背景。','Minoan strength lay at sea — later Greeks remembered them as masters of the waves — while Mycenaean strength lay in arms: bronze weapons, chariots and thick-walled citadels. The legend of the Trojan War is set in this warrior age.'],
      fall:['前1200年前后,东地中海各文明几乎同时崩塌:宫殿焚毁,文字失传,贸易网断裂,史称青铜时代大崩溃。原因尚无定论,干旱、地震、「海上民族」的劫掠与贸易体系连锁断裂等假说并存;一般认为是多重打击叠加,而非单一灾难。','Around 1200 BC civilizations across the eastern Mediterranean crashed almost together: palaces burned, writing was lost, trade networks snapped — the Bronze Age Collapse. Its cause remains unsettled; drought, earthquakes, raids by the \'Sea Peoples\' and cascading trade failures are all proposed, and most scholars see several blows landing at once rather than one single disaster.'],
      legacy:['迷宫与米诺牛、特洛伊战争——这段被遗忘的历史化作希腊神话流传下来。线形文字B被破译后,证明迈锡尼人说的正是最早留下文字记录的希腊语;19世纪末到20世纪初的考古发掘,让湮没三千年的宫殿重见天日。','The forgotten age survived as Greek myth — the labyrinth, the Minotaur, the Trojan War. When Linear B was deciphered, it proved the Mycenaeans spoke the earliest recorded Greek; excavations in the late 19th century brought the palaces back to light after three thousand years.'] },
  d:'克里特岛的米诺斯人建起欧洲最早的宫殿文明,以海上贸易联通埃及与近东;其后希腊本土的迈锡尼人继承并征服之,特洛伊战争传说即以这个时代为背景。前1200年前后的系统性大崩溃使其湮没三千年,直到19世纪末才被考古重新发现。' },
{ l:'eu', s:'west', v:0, n:'古希腊', k:[[-1100,0],[-1020,.09],[-776,.15],[-490,.55],[-430,.85],[-338,.6],[-146,0]], b:'城邦、民主、哲学与科学的源头;希腊化浪潮远及中亚。',
  e:{ n:'Ancient Greece', b:'City-states that invented democracy, philosophy and drama; Hellenism reached Central Asia.', d:'Hundreds of rival city-states produced astonishing originality in philosophy, science, art and politics. After repelling Persia came the golden age; after the Peloponnesian War, Macedon absorbed them — and Alexander spread Greek culture to Egypt and Central Asia.', f:{ 'Peak':'5th c. BCE (Age of Pericles)', 'Center':'Athens, Sparta', 'Figures':'Socrates, Plato, Aristotle, Sappho, Hippocrates', 'Legacy':'Democracy, philosophy, drama, Olympics' } },
  f:{ '鼎盛':'前5世纪(伯里克利时代)', '中心':'雅典、斯巴达', '人物':'苏格拉底、柏拉图、亚里士多德、萨福、希波克拉底', '成就':'民主制、哲学、戏剧、奥运会' },
  co:[ { n:['雅典','Athens'], c:['阿提卡','Attica'], g:['本土主要城邦','Leading mainland poleis'], x:['希腊人建立的城邦以百计,这里只列最常被提到的几个;没有哪一个能长期压住其余','The Greeks founded poleis by the hundred; only the most-cited are listed here, and none held the rest down for long'] },
       { n:['斯巴达','Sparta'], c:['拉科尼亚','Laconia'], g:['本土主要城邦','Leading mainland poleis'] },
       { n:['科林斯','Corinth'], c:['科林斯地峡','the Isthmus of Corinth'], g:['本土主要城邦','Leading mainland poleis'] },
       { n:['底比斯(希腊)','Thebes (Greece)'], c:['中希腊','central Greece'], g:['本土主要城邦','Leading mainland poleis'] },
       { n:['阿尔戈斯','Argos'], c:['阿尔戈利斯','the Argolid'], g:['本土主要城邦','Leading mainland poleis'] },
       { n:['米利都','Miletus'], c:['小亚细亚西岸','western Asia Minor'], g:['海外与殖民城邦','Overseas and colonial poleis'], x:['殖民地从西班牙一直撒到黑海沿岸','colonies were scattered from Spain to the shores of the Black Sea'] },
       { n:['以弗所','Ephesus'], c:['小亚细亚西岸','western Asia Minor'], g:['海外与殖民城邦','Overseas and colonial poleis'] },
       { n:['叙拉古','Syracuse'], c:['西西里','Sicily'], g:['海外与殖民城邦','Overseas and colonial poleis'] },
       { n:['马赛利亚','Massalia'], c:['今法国马赛','Marseille today'], g:['海外与殖民城邦','Overseas and colonial poleis'] },
       { n:['马其顿','Macedon'], y:[null,-168], c:['希腊北部','northern Greece'], g:['北方的王国','The kingdom to the north'], x:['前338年以武力压服了大部分希腊城邦(斯巴达除外),前168年败于罗马','forced most of the Greek poleis into line in 338 BCE (Sparta excepted), and was defeated by Rome in 168 BCE'] } ],
  qh:{ born:['山把统一挡住了,却挡出几百个城邦','The mountains blocked unity, and produced hundreds of city-states'],
       rule:['法律高于统治者个人','The law stood above the ruler'],
       money:['种不了粮,就种橄榄和葡萄去换粮','Unable to grow grain, they grew olives and traded for it'],
       power:['盾牌保卫的是自己的城,所以扛得住','The shield defended their own city, so it held'],
       fall:['赢了外战,输给了自己','It won the foreign war and lost to itself'],
       legacy:['被俘虏的希腊,反过来俘虏了征服者','Captive Greece took its rough conqueror captive'] },
  q:{ born:['青铜崩溃后的黑暗时代里,希腊人在群山分割的贫瘠半岛上重新起步。地形挡住了统一,却催生出数百个自治城邦;土地养不活的人口驾船出海,把殖民地撒遍地中海与黑海沿岸。','After the Bronze Age Collapse, the Greeks started over on a poor peninsula carved up by mountains. The terrain blocked unification but bred hundreds of self-governing city-states, and the land\'s limits pushed people to sea, scattering colonies along the Mediterranean and Black Sea coasts.'],
      rule:['城邦的公民自己管理自己,但方案各不相同:雅典发展出抽签与投票的民主制(妇女与奴隶除外),斯巴达靠双王与长老会治国。共同点是法律高于统治者个人——这在当时的世界是少有的实验。','Each polis governed itself, but differently: Athens developed democracy by lot and vote (excluding women and slaves), while Sparta ran on dual kings and a council of elders. What they shared was the idea that law stood above any ruler — a rare experiment in that world.'],
      money:['土地贫瘠种不好粮食,就改种橄榄和葡萄:油、酒与彩陶外销,换回黑海沿岸的谷物;雅典还坐拥劳里昂银矿,银币「猫头鹰」通行地中海。海上贸易是城邦的命脉——而命脉这个词是字面意思。雅典吃的粮大半从黑海运来,要穿过赫勒斯滂那道窄海峡。前 405 年,斯巴达的莱山德在羊河边一举打掉雅典舰队,180 艘船只逃出 9 艘,粮道就此掐断;十一个月后,城里已经有人饿死在街上,雅典投降。仗打了二十七年,最后输的不是一场海战,是一条运粮的路。','Too poor for grain, the land grew olives and vines instead: oil, wine and pottery paid for wheat from the Black Sea coasts. Athens also mined silver at Laurion, and its \'owl\' coins circulated across the Mediterranean. Maritime trade was the lifeline of the polis, and lifeline is the literal word. Most of what Athens ate came from the Black Sea and had to pass the narrow water of the Hellespont. In 405 BC the Spartan Lysander destroyed the Athenian fleet at Aegospotami — of a hundred and eighty ships, nine got away — and the grain road was shut. Eleven months later people were dying of hunger in the streets and the city surrendered. After twenty-seven years of war, what beat Athens in the end was not a sea battle but a route.'],
      power:['公民既是选民也是士兵:方阵里并肩持盾的重装步兵、战舰上的桨手,保卫的是自己的城邦——希波战争中,这套体制挡住了波斯大军。雅典借提洛同盟把盟邦的贡金变成自家舰队,同盟一步步变成帝国。','Citizens were soldiers as well as voters: hoplites standing shield to shield and rowers pulling the triremes defended their own city — a system that stopped the Persian invasions. Athens turned its navy into the Delian League, an alliance verging on empire.'],
      fall:['城邦制度赢得了战争,却输给了自己:谁也不肯让渡主权,伯罗奔尼撒战争等长期内耗拖垮了黄金时代,北方的马其顿趁虚整合了希腊。亚历山大死后,继承者王国互相攻伐;前146年希腊本土并入罗马治下,余下的希腊化王国也被罗马逐一吞并。','The polis system won its wars but lost to itself: no city would yield sovereignty, and conflicts like the Peloponnesian War bled the golden age dry, letting Macedon impose unity from the north. After Alexander\'s death his successor kingdoms fought one another; Greece itself passed under Roman rule in 146 BC, and the remaining Hellenistic kingdoms were absorbed by Rome one by one.'],
      legacy:['民主、哲学、几何、戏剧、奥运会,今天的许多基本观念都能追溯到希腊;亚历山大东征把希腊语和希腊学问播到埃及与中亚。罗马人自己也承认:被俘虏的希腊,反过来俘虏了野蛮的征服者。','Democracy, philosophy, geometry, drama, the Olympics — many of our basic ideas trace back to Greece, and Alexander\'s campaigns carried Greek language and learning to Egypt and Central Asia. As the Romans themselves admitted, captive Greece took her rough conqueror captive.'] },
  d:'数百个独立城邦在贫瘠半岛上竞争共生,却在哲学、科学、艺术与政治制度上完成惊人的原创;希波战争挡住波斯后迎来黄金时代,伯罗奔尼撒战争内耗后被马其顿整合。亚历山大东征把希腊文化播撒到埃及与中亚;罗马虽征服其地,却"被俘虏的希腊俘虏了野蛮的征服者"。' },
{ l:'eu', s:'west', v:2, n:'罗马共和国', k:[[-509,0],[-264,.3],[-146,.55],[-50,.7],[-28,0]], b:'元老院与人民:一个城邦用五百年把地中海变成"我们的海"。',
  e:{ n:'Roman Republic', w:'Roman Republic', b:'Senate and People: five centuries turning one city into master of the Mediterranean.', d:'After driving out their last king in 509 BCE, the Romans laid down a rule: power must be divided and must expire. Two consuls served one year at a time, the Senate held the purse and foreign affairs, and a single tribune could veto anything that harmed the plebs. On that constitution and an army of citizen-soldiers, Rome won three Punic Wars, destroyed Carthage and made the Mediterranean its own lake. But a constitution built for a city could not hold three continents — generals came home with armies loyal to themselves, Caesar crossed the Rubicon, and five centuries of the Republic were over.', f:{ 'Peak':'After the Punic Wars (2nd c. BCE)', 'Center':'Rome', 'Figures':'Caesar, Cicero, Lucretius, Tiberius Gracchus', 'Legacy':'The republican constitution, the citizen legions, the widening of citizenship' } },
  f:{ '鼎盛':'布匿战争之后(前2世纪)', '中心':'罗马城', '人物':'凯撒、西塞罗、卢克莱修、提比略·格拉古', '成就':'共和政制、公民兵军团、公民权扩张' },
  qh:{ born:['共和不是出于理想,是出于怕国王','The republic came less from ideals than from fear of kings'],
       rule:['权力被切开,谁也不能独大','Power cut into pieces, so no one could hold it all'],
       money:['战争本身,成了最大的生意','War itself became the biggest business'],
       power:['可以输掉战役,很难输掉战争','It could lose battles, but hardly ever a war'],
       fall:['军队开始效忠将军,不是国家','The army came to serve its generals, not the state'],
       legacy:['美国参议院那个词,直接来自元老院','The word Senate comes straight from the Roman one'] },
  q:{ born:['罗马人赶走最后一个国王后,最怕的就是权力再集中到一个人手里,于是设计出一套互相牵制的制度——共和与其说源于理想,不如说源于对国王的恐惧。','After expelling their last king the Romans feared one-man rule above all, so they built a system of mutual checks — the Republic was born less of ideals than of fear of kings.'],
      rule:['执政官管行政,两人一组一年一换;元老院大部分时候约三百人,管钱和外交;十名保民官由平民选出,任何一人都能一票否决伤害平民的决议。前 287 年起平民会议的决议对全体罗马人有效。权力被切开,谁也不能独大。','Two consuls ran the state a year at a time; a Senate of usually about three hundred held the purse and foreign policy; ten tribunes elected by the plebs could each veto any act that harmed them, and from 287 BC the decisions of the plebeian assembly bound all Romans. Power was cut into pieces so that no one could hold it all.'],
      money:['早期靠自耕农的农业;扩张后靠行省税收、战利品和奴隶庄园——战争本身成了最大的生意。','At first, the farms of citizen smallholders; with expansion came provincial taxes, war booty and slave estates — war itself became the biggest business.'],
      power:['公民兵为自己的土地打仗;更关键的是对战败者的处理:不斩尽杀绝,而是分等级给公民权,把对手变成兵源——罗马可以输掉战役,却很难输掉战争。','Citizen-soldiers fought for their own land; more decisive was how Rome treated the defeated — tiers of citizenship instead of destruction, turning enemies into recruits. Rome could lose battles yet rarely lost wars.'],
      fall:['一般认为,扩张反噬了根基:小农常年出征,回来发现田地被奴隶庄园挤垮,公民兵随之枯竭;改行募兵后,士兵指望将军给他们土地和战利品,军队效忠将军而不是国家——百年内战里,凯撒渡河只是最著名的一步。','By the usual account, expansion ate its own base: smallholders came home from long wars to find their farms undercut by slave estates, and the citizen levy dried up. Once armies were recruited for pay, soldiers looked to their generals for land and plunder, and served them rather than the state — in the century of civil war that followed, the Rubicon was only the most famous step.'],
      legacy:['分权、任期、否决权——后世共和国的制度原型;美国参议院 Senate 这个词就直接来自元老院。它的法律条文被后来的罗马法一路继承,它的语言拉丁语变成了意大利语、法语、西班牙语。','Divided powers, fixed terms and the veto — the template of later republics; the very word Senate comes from the Roman Senatus. Its law was carried on into later Roman law, and its language, Latin, became Italian, French and Spanish.'] },
  d:'前509年赶走最后一个国王后,罗马人立了一条规矩:权力必须分开、必须有任期。执政官两人一组、一年一换,元老院管钱和外交,保民官可以一个人否决伤害平民的决议。靠这套制度和公民组成的军团,罗马打赢三次布匿战争灭掉迦太基,把地中海变成自己的内湖。但一套为城邦设计的制度撑不住横跨三洲的疆域——将军们带着只效忠自己的军队回国,凯撒渡过卢比孔河,五百年的共和走到了头。',
  gl:[ { a:-287, b:-133, k:'thought', t:['共和政制','The republican constitution'], d:['这套制度运转得最好的是前 3 到前 2 世纪:贵族与平民的两百年争斗以前 287 年平民会议决议对全体有效收场,元老院说话算数,罗马靠它打赢了三次布匿战争。前 133 年保民官格拉古死在集会上之后它开始失灵——政治分歧第一次用杀人解决,此后一百年里越来越常见。','It worked best in the third and second centuries BC: two hundred years of struggle between patricians and plebs ended in 287 BC when the plebeian assembly\'s decisions bound everyone, the Senate\'s word carried, and with this machinery Rome won the three Punic Wars. It began to fail after 133 BC, when the tribune Gracchus was killed in the assembly — the first time a political quarrel was settled by killing, and far from the last in the century that followed.'] },
       { a:-451, b:-449, k:'thought', t:['十二铜表法','The Twelve Tables'], d:['前 451—449 年,十人委员会把习惯法写成十二块法表立在广场上,罗马公民的权利和义务从此白纸黑字——欠债怎么办、伤人怎么赔,都在上面。原表据说是铜的,高卢人焚城时(约前 390 年)可能已毁,条文靠后人引用留下;西塞罗说他小时候学童还要背诵。','In 451–449 BC a board of ten men wrote the customary law down as twelve tables and set them up in the Forum, so that a Roman citizen\'s rights and duties were there in black and white — what happens to a debtor, what an injury costs. The originals, said to be bronze, may have been lost when the Gauls burned Rome (c. 390 BC); the text survives through later quotation, and Cicero says that in his boyhood schoolchildren still learned it by heart.'] },
       { a:-312, b:-28, k:'tech', t:['大道与水道','Roads and aqueducts'], d:['前 312 年监察官阿庇乌斯·克劳狄乌斯开修阿庇亚大道:从罗马到卡普亚约 195 公里,前 264 年前后延到东南端的港口布林迪西,全长约 540 公里;路面是嵌得严丝合缝的大石块,罗马城外那一段今天还能走上去。同一年他还修了罗马第一条引水道,16 公里长,大半埋在地下。','In 312 BC the censor Appius Claudius began the Appian Way: about 195 km from Rome to Capua, extended around 264 BC to the port of Brundisium in the south-east for some 540 km in all; its surface of tight-fitting stone blocks can still be walked on outside Rome today. The same year he built Rome\'s first aqueduct, 16 km long and mostly underground.'] },
       { a:-211, b:-28, k:'econ', t:['第纳里乌斯银币','The denarius'], d:['前 211 年罗马开始铸第纳里乌斯银币,起初每枚约 4.5 克白银、值十枚铜阿斯;它当了四百多年的标准银币。今天意大利语、西班牙语里的「钱」(denaro / dinero),还有英国 1971 年以前便士的缩写 d,都是它留下的。','From 211 BC Rome struck the denarius, at first about 4.5 g of silver worth ten bronze asses; it stayed the standard silver coin for more than four hundred years. The Italian and Spanish words for money (denaro, dinero) and the d that stood for pence in Britain until 1971 all descend from it.'] } ] },
{ l:'eu', s:'west', v:1, n:'罗马帝国', k:[[-27,0],[117,1],[235,.8],[378,.5],[476,0]], b:'两百年罗马和平;法律、拉丁语与教会塑造了整个欧洲。',
  e:{ n:'Roman Empire', w:'Roman Empire', b:'Two centuries of Pax Romana; its law, Latin and Church shaped all of Europe.', d:'Octavian never called himself king — his titles were princeps and Augustus, so the Republic kept its name while the power passed to one man. Two centuries of Pax Romana followed: the Mediterranean traded as one, roads, aqueducts and baths covered the provinces, and by 212 every free man in the empire was a Roman citizen. After the 3rd-century crisis the empire split east and west; in 476 a Germanic general deposed the last western emperor — but Roman law, Latin and the Church shaped all later Europe.', f:{ 'Peak':'117 CE (Trajan)', 'Center':'Rome', 'Figures':'Augustus, Trajan, Vitruvius, Galen, Tacitus, Hypatia', 'Legacy':'Roman law, Latin, roads & aqueducts' } },
  f:{ '鼎盛':'117年(图拉真,版图最大)', '中心':'罗马城', '人物':'奥古斯都、图拉真、维特鲁威、盖伦、塔西佗、希帕蒂娅', '成就':'罗马法、拉丁语、道路与引水渠' },
  qh:{ born:['用自由,换来了和平','Freedom traded away for peace'],
       rule:['后来干脆给所有自由民发公民权','In the end it gave citizenship to every free man'],
       money:['埃及和北非的粮船,喂饱了罗马城','Grain ships from Egypt and Africa fed the city'],
       power:['道路和引水渠,把征服变成了秩序','Roads and aqueducts turned conquest into order'],
       fall:['分家之后,穷的那一半先撑不住','After the split, the poorer half gave way first'],
       legacy:['教会接过它的骨架,又延续了一千年','The church took over its skeleton for another thousand years'] },
  q:{ born:['百年内战证明,为一座城设计的共和制度管不住横跨三洲的疆土;屋大维保留共和的名义、收走实际的权力,精疲力竭的社会接受了这笔交易。这笔交易他自己写下来过:公元 14 年 8 月去世前一个月,他写完《功业录》,铜柱立在自己陵前,各省照着翻刻——最完整的一份留在今天的安卡拉,拉丁文与希腊文并列。开篇第一句是「我十九岁时自筹经费组建军队,把共和国从一个派系的专制下解放出来」。他说的是恢复自由,做的是收走权力。','A century of civil war showed that a constitution built for one city could not govern three continents. Octavian kept the forms of the Republic and took the substance of power, and an exhausted society accepted the bargain. He wrote the bargain down himself: a month before his death in August AD 14 he finished the Res Gestae, set it on bronze pillars before his own mausoleum, and had it copied out in the provinces — the fullest surviving version stands at Ankara, in Latin and Greek side by side. Its first sentence runs: at the age of nineteen, on my own initiative and at my own expense, I raised an army by which I restored liberty to the republic, oppressed by the tyranny of a faction. What he says is that he gave freedom back. What he did was take the power.'],
      rule:['皇帝之下,行省总督治民、职业军团守边;罗马法给整个地中海一套统一的裁判标准;对行省精英开放公民权换忠诚,212 年干脆给了所有自由民。守边这件事被奥古斯都定成了常数:军团固定为 28 个(条顿堡森林一战没了三个,此后长期是 25 个),每团约五千人,外加大致同等的辅助兵。士兵签的是二十五年,期满退伍领三千第纳里乌斯或一块好地——这是一支不打仗也要养的常备军——后来拖垮财政的几股力量里,这笔常年开销是分量最重的一项。','Under the emperor, governors ran the provinces and professional legions held the frontiers; Roman law gave the whole Mediterranean one standard of judgment. Citizenship bought the loyalty of provincial elites — and in 212 it went to every free man. Augustus fixed the frontier garrison as a constant: twenty-eight legions (three were lost in the Teutoburg Forest and the number stood near twenty-five thereafter), about five thousand men each, with roughly as many auxiliaries again. A man signed for twenty-five years and left with three thousand denarii or a good piece of land — a standing army that had to be paid whether or not it fought — and of the several pressures that later wore down the finances, that permanent bill was the heaviest.'],
      money:['地中海变成内湖后,贸易连成一张网:埃及和北非的粮船喂饱罗马城,行省税和统一银币把整个经济接在一起。那枚银币后来讲了另一个故事:奥古斯都时第纳里乌斯含银 97% 到 98%,尼禄在 64 年降到 94.5%,三世纪初从 78.5% 一路掺到 50%,到公元 300 年只剩 5%——最后不过是铜片外面镀一层银。名字没变、面值没变、退伍金也还是「三千第纳里乌斯」,可那已经不是同一枚钱了。','With the Mediterranean an inner lake, trade ran as one system: grain fleets from Egypt and Africa fed Rome, while provincial taxes and a single silver coinage wired the economy together. That coin went on to tell another story. Under Augustus the denarius was 97 to 98 per cent silver; Nero brought it down to 94.5 in AD 64; through the early third century it fell from 78.5 per cent to 50; by AD 300 it was five. In the end it was a copper disc with a wash of silver. The name did not change, the face value did not change, and a discharged soldier was still promised three thousand denarii — but it was no longer the same coin.'],
      power:['帝国的强大不再来自继续扩张,而来自消化:道路、引水渠、城市把征服变成秩序,和平本身就是生产力。转折点看得见:117 年图拉真把版图推到最大,五年后哈德良就在不列颠北端动工修墙——117.5 公里长、高约 3.7 米,三个军团一万五千人修了六年,沿线每三分之一英里一座望楼、隔一段一座能驻六百人的堡,满员时守墙的约一万人。一个帝国最强的证据,不是又打下了哪里,是它决定在哪儿停下来。','Its strength came not from further conquest but from digestion: roads, aqueducts and cities turned conquest into order, and peace itself became productive. The turn is visible on the ground: Trajan pushed the frontier to its furthest in 117, and five years later Hadrian began a wall across the north of Britain — 117.5 kilometres of it, about 3.7 metres high, built in six years by three legions and fifteen thousand men, with a turret every third of a mile and forts along it holding six hundred apiece; some ten thousand soldiers manned it when it was full. The proof that an empire is at its strongest is not what it takes next, but where it decides to stop.'],
      fall:['主流看法是多因叠加而非单一原因:边防开支压垮财政,银币掺假引发通胀,瘟疫削减人口,迁徙的民族不断叩边;东西分治后,税基薄弱的西部先撑不住。收场那一幕出奇地平静:476 年 9 月 4 日奥多亚克废掉末代皇帝罗慕路斯·奥古斯图路斯,没有杀他,给了每年六千索利都斯的年金,打发到那不勒斯附近的一座城堡去住;西部的皇帝信物被打包送往君士坦丁堡,附一句话——帝国有一个皇帝就够了。「476 年西罗马灭亡」是后人追认的分界,当时的人未必觉得那天有什么特别。','The mainstream view is death by many causes, not one: frontier costs crushed the treasury, debased coinage bred inflation, plagues cut the population, and migrating peoples pressed the borders. After the east-west split, the poorer west gave way first. The last scene was oddly quiet: on 4 September 476 Odoacer deposed the last emperor, Romulus Augustulus, did not kill him, settled a pension of six thousand solidi on him and sent him to a castle near Naples; the western regalia were packed off to Constantinople with the message that one emperor was enough for the empire. The fall of Rome in 476 is a dividing line drawn afterwards — the people alive that year need not have thought the day remarkable.'],
      legacy:['罗马法是大陆法系的底本;拉丁语生出法语、意大利语、西班牙语;教会接过帝国的行政骨架,把罗马的秩序又延续了一千年。「接过骨架」不是比喻:今天说的「教区」,英文 diocese、拉丁文 dioecesis,原本是希腊语「管理」一词,晚期帝国拿它称呼几个行省合成的大行政区。313 年基督教合法之后,教会照着这张官府的图划自己的图,连名字一起搬了过来——帝国的行政区没了,它的分区办法留在了教会里。','Roman law underlies the civil-law world; Latin fathered French, Italian and Spanish; and the Church inherited the imperial framework, carrying Roman order on for another thousand years. Inheriting the framework is not a figure of speech. The word diocese, Latin dioecesis, is Greek for administration, and the late empire used it for a grouping of provinces. After Christianity was legalised in 313 the churches drew their map on the state map and took the name with it — the imperial districts are gone, and their way of dividing the ground survives inside the Church.'] },
  d:'屋大维没有称王,他给自己的头衔是"元首"和"奥古斯都"——共和的名义保留着,权力已经归了一个人。此后两百年是"罗马和平":地中海贸易连成一片,道路、引水渠和浴场铺满行省,212年境内所有自由民都成了罗马公民。3世纪危机之后帝国东西分治,476年日耳曼将领废掉西部末代皇帝;但罗马法、拉丁语和基督教会,塑造了此后整个欧洲。' },
{ l:'eu', s:'west', v:0, n:'拜占庭', k:[[395,0],[420,.5],[555,.7],[700,.5],[1000,.55],[1204,.25],[1453,0]], b:'东罗马延续千年,保存希腊罗马典籍,东正教文明中心。',
  e:{ n:'Byzantium', w:'Byzantine Empire', b:'The eastern empire endured a thousand years, preserving classical learning.', d:'After the west fell, the eastern empire lasted another millennium; Justinian briefly retook the western Mediterranean and codified Roman law. Squeezed by Persians, Arabs and Turks, sacked by the Fourth Crusade in 1204, it fell in 1453 — its Greek manuscripts fed the Renaissance, its Orthodoxy passed to Russia.', f:{ 'Peak':'6th c. (Justinian)', 'Center':'Constantinople', 'Figures':'Justinian, Basil II, Theodora, Anthemius of Tralles', 'Legacy':'Corpus Juris Civilis, Hagia Sophia' } },
  f:{ '鼎盛':'6世纪(查士丁尼)', '中心':'君士坦丁堡', '人物':'查士丁尼、巴西尔二世、狄奥多拉、安提米乌斯', '成就':'《查士丁尼法典》、圣索菲亚大教堂' },
  qh:{ born:['西边倒了之后,它又独自活了一千年','After the west fell, it lived on alone for a thousand years'],
       rule:['皇帝被当作上帝在人间的代理人','The emperor was God on earth by proxy'],
       money:['一枚金币,几百年成色不变','One gold coin, unchanged in fineness for centuries'],
       power:['三重城墙,加上一种烧不灭的火','Three walls, and a fire that would not go out'],
       fall:['1453年那一炮,只是最后一页','The cannon of 1453 was only the last page'],
       legacy:['莫斯科后来自称「第三罗马」','Moscow later called itself the third Rome'] },
  q:{ born:['罗马帝国分治后,更富庶、城市更密集的东半部以君士坦丁堡为都活了下来。这座城扼守欧亚之间的海峡,一面是三重城墙,一面是黄金商路;西罗马倾覆后,它又独自延续了一千年。','When the Roman Empire split, its richer, more urbanized eastern half survived, centred on Constantinople. The city commanded the strait between Europe and Asia — triple walls on one side, golden trade routes on the other — and carried on for a thousand years after the West fell.'],
      rule:['皇帝被视为上帝在人间的代理人,基督教会与罗马式的官僚机器共同支撑皇权。法律上它是罗马的继承者,查士丁尼把千年罗马法编成大全;语言与文化上则日渐希腊化。','The emperor was seen as God\'s deputy on earth, his power propped up by the Christian church and a Roman-style bureaucracy. In law the empire was Rome\'s heir — Justinian codified a millennium of Roman law — while in language and culture it grew ever more Greek.'],
      money:['帝国坐在欧亚贸易的十字路口收税,君士坦丁堡的关税滚滚而来;金币索利都斯成色稳定数百年,是地中海贸易信得过的硬通货。据记载,养蚕技术从东方偷运而来后,丝绸更成了帝国的垄断产业。','The empire taxed the crossroads of Eurasian trade, and customs revenue poured through Constantinople. Its gold solidus held its value for centuries, the Mediterranean\'s trusted currency; and after silkworms were smuggled in from the East, as the old account goes, silk became an imperial monopoly.'],
      power:['会打仗,更会周旋:三重城墙与秘方「希腊火」一次次守住都城;外交上惯于扶此抑彼、花钱买盟友。军区制让边地农民亦兵亦农,支撑帝国挺过阿拉伯扩张的狂潮。','It fought well but maneuvered better: the triple walls and the secret weapon \'Greek fire\' saved the capital again and again, while its diplomats played rivals off against each other and paid for allies. The theme system, settling soldier-farmers on the frontiers, helped the empire ride out the storm of Arab expansion.'],
      fall:['衰亡是几百年的慢过程:1071年曼齐刻尔特战败丢掉小亚细亚腹地,税源与兵源同时枯竭;1204年第四次十字军攻陷并洗劫君士坦丁堡,帝国从此元气不复。之后只剩围绕都城的残躯,1453年奥斯曼大炮轰开城墙,不过是漫长终章的最后一页。','The fall took centuries. Defeat at Manzikert in 1071 cost the Anatolian heartland, draining taxes and soldiers at once; the Fourth Crusade\'s sack of Constantinople in 1204 broke the empire beyond real recovery. What remained was a rump around the capital, and the Ottoman cannon of 1453 merely wrote the last page of a long ending.'],
      legacy:['它保存的希腊罗马典籍西传后滋养了文艺复兴;《查士丁尼法典》成为欧陆法律的源头;东正教连同西里尔字母传给斯拉夫世界,莫斯科后来以「第三罗马」自居。','The Greek and Roman texts it preserved flowed west to feed the Renaissance, and Justinian\'s Code became the fountainhead of continental European law. Orthodox Christianity, along with the Cyrillic alphabet, passed to the Slavic world — Moscow would later style itself the \'Third Rome\'.'] },
  d:'西罗马倾覆后,东部帝国又延续了整整一千年;查士丁尼一度光复地中海西岸,并把罗马法编成大全。此后在波斯、阿拉伯、突厥的轮番冲击下节节收缩,1204年惨遭第四次十字军洗劫,1453年城破国亡。它保存的希腊典籍滋养了文艺复兴,东正教传统则由俄罗斯接续。' },
{ l:'eu', s:'west', v:1, n:'中世纪西欧', k:[[480,0],[800,.45],[920,.32],[1100,.42],[1300,.55],[1500,0]], b:'法兰克—神圣罗马—封建诸国;教会、骑士与大学的时代。',
  e:{ n:'Medieval West', w:'Middle Ages', b:'Church and Germanic kingship assemble a new order; knights, cathedrals, universities.', d:'On Roman ruins, Germanic kingship and the Church assembled a new order — Charlemagne\'s coronation revived the imperial idea. Amid feudal fragmentation Europe slowly accumulated: land clearance, reviving towns, universities and Gothic cathedrals, banking five centuries of potential.', f:{ 'Peak':'13th century', 'Center':'Paris, Rome', 'Figures':'Charlemagne, Aquinas', 'Legacy':'Universities, Gothic architecture, the manor and knighthood' } },
  f:{ '鼎盛':'13世纪', '中心':'巴黎、罗马', '人物':'查理曼、阿奎那', '成就':'大学、哥特建筑、庄园骑士制' },
  ct:['各时期的主要王国','Major kingdoms, period by period'],
  co:[ { n:['法兰克王国','Frankish kingdom'], y:[481,843], c:['巴黎→亚琛','Paris, later Aachen'], m:1, g:['蛮族王国(5—9世纪)','Barbarian kingdoms (5th–9th c.)'], x:['西罗马的行省一块块变成日耳曼王国——西哥特人最早是罗马境内的同盟者,先都图卢兹,后来才退入伊比利亚改都托莱多;法兰克笑到最后,800年查理曼加冕为帝','the provinces of the western empire became Germanic kingdoms one by one — the Visigoths began as federates inside Roman territory, ruling first from Toulouse and only later from Toledo in Iberia; the Franks outlasted them all, and Charlemagne was crowned emperor in 800'] },
       { n:['西哥特王国','Visigothic kingdom'], y:[418,711], c:['托莱多','Toledo'], g:['蛮族王国(5—9世纪)','Barbarian kingdoms (5th–9th c.)'] },
       { n:['伦巴第王国','Lombard kingdom'], y:[568,774], c:['帕维亚','Pavia'], g:['蛮族王国(5—9世纪)','Barbarian kingdoms (5th–9th c.)'] },
       { n:['韦塞克斯王国','Wessex'], c:['温切斯特','Winchester'], g:['蛮族王国(5—9世纪)','Barbarian kingdoms (5th–9th c.)'] },
       { n:['神圣罗马帝国','Holy Roman Empire'], c:['无固定都城','no fixed capital'], g:['封建诸国(10—15世纪)','Feudal kingdoms (10th–15th c.)'], x:['查理曼的帝国三分之后,西欧再没统一过;王国与教会长期并立、互相牵制','after Charlemagne\'s empire was split three ways western Europe was never unified again, and kingdoms and church stood side by side, each checking the other'] },
       { n:['法兰西王国','Kingdom of France'], c:['巴黎','Paris'], g:['封建诸国(10—15世纪)','Feudal kingdoms (10th–15th c.)'] },
       { n:['英格兰王国','Kingdom of England'], c:['温切斯特→伦敦','Winchester, later London'], g:['封建诸国(10—15世纪)','Feudal kingdoms (10th–15th c.)'] },
       { n:['卡斯蒂利亚王国','Kingdom of Castile'], c:['布尔戈斯→托莱多','Burgos, later Toledo'], g:['封建诸国(10—15世纪)','Feudal kingdoms (10th–15th c.)'] },
       { n:['教皇国','Papal States'], c:['罗马','Rome'], g:['封建诸国(10—15世纪)','Feudal kingdoms (10th–15th c.)'] } ],
  qh:{ born:['国王要教会的字,教会要国王的刀','The king needed letters; the church needed swords'],
       rule:['我的附庸的附庸,不是我的附庸','The vassal of my vassal is not my vassal'],
       money:['换了犁,换了轮作,粮食就多了','A better plough and a new rotation, and the grain came'],
       power:['真正的积蓄不在城堡,在制度里','The real reserve was not the castle but the institutions'],
       fall:['不是灭亡,是旧秩序自己解体了','Not destruction: the old order came apart'],
       legacy:['民族国家是从这里慢慢长出来的','The nation state grew slowly out of this'] },
  q:{ born:['西罗马崩塌后,日耳曼人的王权、基督教会和残存的罗马遗产在废墟上互相拼接:国王需要教会的文字与合法性,教会需要国王的刀剑护持,查理曼的加冕把这场结盟推向顶点。','After the Western Roman collapse, Germanic kingship, the Christian church and the remnants of Rome were pieced together on the ruins: kings needed the church\'s literacy and legitimacy, the church needed royal swords, and Charlemagne\'s coronation sealed the alliance.'],
      rule:['缺钱又缺官的国王把土地分给领主,换取效忠与骑士,领主再层层分封——封建制把权力摔成一地碎片,「我的附庸的附庸,不是我的附庸」。教会则是另一套平行权力,垄断读写,连国王也惧怕破门令。','Kings short of cash and officials granted land to lords in exchange for loyalty and knights, and lords subdivided in turn — feudalism shattered power into fragments: \'my vassal\'s vassal is not my vassal\'. The church ran a parallel power structure, monopolizing literacy; even kings feared excommunication.'],
      money:['早期是自给自足的庄园经济:农奴耕种领主的土地,交租服役,商业近乎停摆。公元1000年后,重犁与三圃轮作让粮食增产,人口大增,城市、集市与行会复兴,意大利与佛兰德的商人重新把欧洲缝进贸易网。','Early on, the self-sufficient manor was the economy: serfs worked the lord\'s land for rent and labor services, and commerce nearly stopped. After the year 1000, the heavy plow and three-field rotation raised yields, population swelled, towns, fairs and guilds revived, and Italian and Flemish merchants stitched Europe back into trade networks.'],
      power:['大学训练出法律与行政人才,国王靠税收和王室法庭一点点收回权力;十字军、垦荒与商路扩张,则把这股力量向外释放。','Universities trained lawyers and administrators, and kings slowly clawed back power through taxes and royal courts. Crusades, land clearance and expanding trade routes turned that energy outward.'],
      fall:['与其说灭亡,不如说旧秩序解体:14世纪黑死病夺走欧洲约三分之一人口,劳力奇缺动摇了庄园与农奴制;火炮攻破城堡,常备军和税收官取代骑士封臣;印刷术、文艺复兴与远洋航路,把中世纪送进了近代。','Less a fall than a dissolution: the Black Death killed roughly a third of Europe in the 14th century, and the labor shortage shook manor and serfdom alike. Cannon breached the castles, standing armies and tax collectors replaced knightly vassals, and printing, the Renaissance and the ocean routes carried the medieval world into the modern one.'],
      legacy:['大学、议会、行会、特许城市——近代欧洲的制度骨架多在这几百年里搭起,哥特大教堂至今仍矗立在城市中心。民族国家,正是从封建王权的缓慢集权中孕育出来的。','Universities, parliaments, guilds, chartered towns — much of modern Europe\'s institutional skeleton was framed in these centuries, and Gothic cathedrals still crown its city centres. The nation-state itself grew out of feudal monarchy\'s slow centralization.'] },
  d:'罗马废墟之上,日耳曼王权与基督教会共同拼装出新秩序,查理曼加冕一度重现"帝国"想象。封建割据中却在缓慢积蓄:垦荒、城市复兴、大学兴起、哥特大教堂拔地而起——为近代欧洲蓄力五百年。' },
{ l:'eu', s:'mideast', v:0, n:'后倭马亚·安达卢斯', k:[[756,0],[850,.35],[961,.55],[1002,.5],[1009,.45],[1031,0]], b:'伊比利亚的伊斯兰政权:科尔多瓦是当时欧洲最大的城市之一。',
  e:{ n:'Umayyad al-Andalus', w:'Caliphate of Córdoba', b:'The Islamic state in Iberia; Córdoba was among the largest cities in Europe.', d:'After the Umayyads were destroyed at Damascus, a surviving prince crossed to Iberia and took Córdoba in 756. In 929 its ruler claimed the caliphate, making three in the Islamic world alongside Baghdad and the Fatimids of North Africa. Irrigation techniques brought from the east turned dry Andalusia into gardens and carried citrus, rice and sugarcane west; the great mosque of Córdoba and the palace city of Madinat al-Zahra are its two monuments. Civil war from 1009 ran for two decades, the caliphate was abolished in 1031, and al-Andalus broke into more than twenty small kingdoms.', f:{ 'Peak':'the 10th c. (Abd al-Rahman III to al-Mansur)', 'Center':'Córdoba', 'Figures':'Abd al-Rahman III, al-Zahrawi', 'Legacy':'The great mosque of Córdoba, irrigation and new crops, Madinat al-Zahra' } },
  f:{ '鼎盛':'10世纪(阿卜杜拉赫曼三世至曼苏尔)', '中心':'科尔多瓦', '人物':'阿卜杜拉赫曼三世、扎赫拉维', '成就':'科尔多瓦大清真寺、灌溉与新作物、麦地那·扎赫拉' },
  qh:{ born:['东边被灭门,西边又活了三百年','Wiped out in the east, it lived three centuries in the west'],
       rule:['以当时的标准算宽容,但不是平等','Tolerant by the standards of the day, but not equal'],
       money:['西班牙语里的水利词,还是阿拉伯语','Spanish still uses Arabic words for irrigation'],
       power:['军权交到外族军团手上,埋了伏笔','The armies were foreign, and that was the fuse'],
       fall:['二十年内战,碎成二十几个小国','Twenty years of civil war, into twenty small kingdoms'],
       legacy:['那座清真寺,后来又当了主教座堂','The great mosque later became a cathedral too'] },
  q:{ born:['750年阿拔斯家族在大马士革推翻倭马亚王朝、几乎屠尽其宗室,少年阿卜杜拉赫曼一路西逃,穿过北非,755年渡海进入伊比利亚,次年入科尔多瓦自立为埃米尔。他没有称哈里发,只用「埃米尔」这个头衔——争名分那一步要等一百七十年后。这条色带因此从一场失败开始:一个王朝在东方被消灭,却在大陆最西端的半岛上又活了将近三百年。','In 750 the Abbasids overthrew the Umayyads at Damascus and killed nearly the whole house; a young survivor, Abd al-Rahman, fled west across North Africa, crossed into Iberia in 755 and the next year made himself emir at Córdoba. He did not claim the caliphate, taking only the title of emir; contesting the name itself would wait another hundred and seventy years. So this band begins with a defeat: a dynasty destroyed in the east that went on living for nearly three centuries at the far western end of the continent.'],
      rule:['前一百七十年称埃米尔,929年阿卜杜拉赫曼三世正式称哈里发,与巴格达的阿拔斯、北非(今突尼斯一带)的法蒂玛并立——10世纪的伊斯兰世界因此同时有三个哈里发;法蒂玛要到四十年后才迁都开罗。治下人口成分复杂:阿拉伯人、柏柏尔人、改宗的本地人,以及保持基督教与犹太教信仰的居民。最后这一类是「齐米」(受保护民),可以保有信仰、用自己的法庭,但要缴纳人头税,在法律与社会地位上低一等。这套安排以当时的标准算宽容,但不是平等,不同时期的松紧也差别很大。','For its first hundred and seventy years its rulers were emirs; in 929 Abd al-Rahman III took the title of caliph, standing alongside the Abbasids in Baghdad and the Fatimids in North Africa, so that the tenth-century Islamic world had three at once; the Fatimids would not move to Cairo for another forty years. The population was mixed: Arabs, Berbers, local converts, and those who stayed Christian or Jewish. The latter were dhimmis — protected, free to keep their faith and their own courts, but paying a poll tax and holding a lower legal and social standing. By the standards of the day this was tolerant; it was not equality, and how tightly it was applied varied a great deal from reign to reign.'],
      money:['灌溉是底层技术:在罗马留下的水网上扩建,并引入东方的水车、暗渠与分水规矩,把安达卢西亚的旱地变成园圃。柑橘与甘蔗是这一时期引入的,稻米与棉花此前已有、这时才大规模种开——今天西班牙语里一批农业与水利词汇仍是阿拉伯语借词。科尔多瓦的皮革与丝织、托莱多的刀剑是名产;929年起开铸的金第纳尔成色精良,在地中海西部广泛流通。','Irrigation was the underlying technology: the Roman water network was extended and eastern practice — waterwheels, underground channels, rules for dividing water — added to it, turning dry Andalusian ground into gardens. Citrus and sugarcane arrived in this period; rice and cotton were already known and only now came to be grown at scale — a whole set of Spanish farming and water words are still Arabic loans. Córdoba leather and silk and Toledo blades were famous; the gold dinars it struck from 929 were of good quality and circulated widely in the western Mediterranean.'],
      power:['军队以柏柏尔人与买来的斯拉夫奴隶兵为主,对北方的基督教诸国是长期拉锯而非一举征服。976年后实权落在宰相曼苏尔手里,他连年北伐,997年一度攻入圣地亚哥·德孔波斯特拉,把教堂的钟运回科尔多瓦——两百多年后基督徒收复该城时又把钟运了回去。这类劫掠式的战争带来威望与战利品,却也把军权彻底交到了外族军团手上,这是后来崩盘的伏笔。','Its army was mainly Berber troops and purchased Slavic slave soldiers, and its dealings with the Christian kingdoms in the north were a long back-and-forth rather than a conquest. After 976 real power lay with the chamberlain al-Mansur, who raided north year after year and in 997 reached Santiago de Compostela, carrying the church bells back to Córdoba — more than two centuries later, when Christians took the city, the bells were carried back. Raiding of this kind brought prestige and plunder, but it also handed military power entirely to foreign corps, which is what later broke the state.'],
      fall:['曼苏尔1002年去世后,继承者压不住局面。1009年起爆发长达二十余年的内战(菲特纳):柏柏尔军团、斯拉夫兵团与各地方势力互相攻杀,宫城麦地那·扎赫拉在1010年被劫掠焚毁,前后只用了七十来年。1031年哈里发之位被正式废除,安达卢斯碎成二十余个小王国(泰法),此后再没有出现本地的统一政权——后来两次重新统一(穆拉比特1090年代、穆瓦希德12世纪中)都是北非的柏柏尔帝国从外面完成的。北方基督教诸国的推进也从此加速。','After al-Mansur died in 1002 his successors could not hold things together. From 1009 a civil war ran for more than twenty years: Berber corps, Slavic troops and local powers fought one another, and the palace city of Madinat al-Zahra was sacked and burned in 1010, some seventy years after work on it began. In 1031 the caliphate was formally abolished and al-Andalus broke into more than twenty small kingdoms and never again produced a united state of its own — the two later reunifications, by the Almoravids in the 1090s and the Almohads in the mid-twelfth century, were both imposed from outside by Berber empires from North Africa. The advance of the Christian kingdoms in the north also picked up speed from then on.'],
      legacy:['科尔多瓦大清真寺至今仍在,1236年科尔多瓦被卡斯蒂利亚攻下后改为主教座堂,这重双重身份保留到了今天;麦地那·扎赫拉的遗址已列入世界遗产。扎赫拉维在这里写成三十卷的医学总集,最后一卷讲外科与手术器械,译成拉丁文后在欧洲医学院沿用了数百年。需要说清楚的是:把古希腊著作经阿拉伯文译回拉丁世界的那一波高峰,发生在1085年托莱多易手之后、由基督教治下的译者完成,与这条色带并不重合——它留给后来的,是那批书、那些人和那套技术,不是翻译运动本身。','The great mosque of Córdoba still stands, and after Castile took the city in 1236 it became a cathedral as well, a double identity it keeps today; the ruins of Madinat al-Zahra are a World Heritage site. It was here that al-Zahrawi compiled a thirty-volume medical work whose last book, on surgery and instruments, was translated into Latin and used in European medical schools for centuries. One thing should be stated plainly: the great wave of translating Greek works from Arabic into Latin came after Toledo changed hands in 1085 and was done by translators under Christian rule, so it does not overlap with this band — what this state handed on was the books, the people and the techniques, not the translation movement itself.'] },
  d:'倭马亚王朝在大马士革被灭后,逃出的王孙在伊比利亚重建政权,756年立于科尔多瓦。929年正式称哈里发,与巴格达、北非的法蒂玛三分伊斯兰世界。靠东来的灌溉技术把安达卢西亚变成园圃,柑橘稻米甘蔗随之西传;科尔多瓦大清真寺与麦地那·扎赫拉是它的两件作品。1009年起的内战二十余年,1031年哈里发废除,碎成二十余个泰法小国。' },
{ l:'eu', s:'west', v:2, n:'维京·北欧', k:[[793,0],[850,.22],[900,.34],[1000,.3],[1066,0]], b:'划着长船的北欧人:一边劫掠一边做买卖,一边把冰岛、格陵兰、诺曼底住了下来。',
  e:{ n:'The Vikings', w:'Vikings', b:'Northmen in longships — raiders and traders at once, who settled Iceland, Greenland and Normandy along the way.', d:'The Viking Age is usually counted from the raid on the monastery of Lindisfarne in 793 to the battle of Stamford Bridge in 1066. Out of Norway, Denmark and Sweden came shallow-draught longships that could cross the North Sea and row up a river; their crews raided monasteries and towns, but just as often traded, and in the end settled — the Danelaw in England, Dublin, Normandy (granted to Rollo in 911), Iceland from 874 by tradition, Greenland from 986, and a brief camp in North America around 1000. Swedes going east down the Russian rivers reached Constantinople and Baghdad and gave the state at Novgorod and Kiev its first princes. At home the three kingdoms formed and turned Christian around 1000, and the raids faded into ordinary medieval kingdoms. Runes, sagas written down in Iceland two centuries later, and the ships dug out of burial mounds are what remains.', f:{ 'Peak':'9th-10th c.', 'Centre':'Denmark, Norway, Sweden; Dublin, York, Normandy, Iceland', 'Figures':'Erik the Red, Leif Erikson, Cnut the Great', 'Legacy':'the longship, runes and sagas, the settling of Iceland, the first Europeans in America' } },
  f:{ '鼎盛':'9—10世纪', '中心':'丹麦、挪威、瑞典;都柏林、约克、诺曼底、冰岛', '人物':'红发埃里克、莱夫·埃里克森、克努特大帝', '成就':'长船、卢恩文字与萨迦、定居冰岛、最早到达美洲的欧洲人' },
  qh:{ born:['793 年,一群人从海上来,抢了修道院','In 793 men came from the sea and sacked a monastery'],
       rule:['没有维京国王,只有一船一船的首领','There was no Viking king, only chieftains, ship by ship'],
       money:['抢完就卖,卖不掉就住下','Raid, then trade; when trade failed, settle'],
       power:['一条船,既能过大海也能划进小河','One ship that could cross the sea and row up a stream'],
       fall:['1066 年,挪威国王死在英格兰,时代结束','In 1066 Norway\'s king died in England; the age ended'],
       legacy:['哥伦布之前五百年,他们已经到过美洲','Five hundred years before Columbus, they had been to America'] },
  q:{ born:['那是英格兰东北海岸的林迪斯法恩,岛上有座富有的修道院——这是第一次让整个欧洲震动的北方来袭,维京时代通常就从这一年算起。他们来自今天的挪威、丹麦和瑞典,那里农田少、海岸线长,人们本来就靠海吃饭;8 世纪后期造船技术成熟,加上西欧修道院有钱又没有防备,出海劫掠就成了一条路。','The place was Lindisfarne on the north-east coast of England, an island with a rich monastery — the first raid from the north to shake the whole of Europe, and the year the Viking Age is usually counted from. They came from what is now Norway, Denmark and Sweden, where farmland was scarce and coastlines long and people already lived from the sea; by the late eighth century their shipbuilding was mature, and the monasteries of western Europe were rich and unguarded, so raiding became a way to make a living.'],
      rule:['维京人从来不是一个国家:出海的是一船一船的首领带着自己的人,回到家乡各归各的部落与小王。抢来的钱和名声让一些首领做大,丹麦、挪威、瑞典三个王国就是在 9—11 世纪从这些首领里长出来的,丹麦的哈拉尔「蓝牙」约 965 年受洗,是第一个让整个王国改信基督教的北欧国王。冰岛没有国王,930 年起由全岛自由民的集会「阿尔庭」立法断案,这个议会今天还在,常被说成世界上最古老的议会之一。','The Vikings were never one state: those who sailed were chieftains with their own crews, ship by ship, and at home each answered to his own tribe or petty king. Plunder and fame let some chieftains grow, and the three kingdoms of Denmark, Norway and Sweden grew out of them between the ninth and eleventh centuries — Harald Bluetooth of Denmark, baptised around 965, was the first Norse king to make his whole kingdom Christian. Iceland had no king at all: from 930 the assembly of free men, the Althing, made its laws and judged its cases, and it still meets today, often called one of the oldest parliaments in the world.'],
      money:['劫掠只是一半。瑞典人顺着俄罗斯的河流南下,把毛皮、蜜蜡和奴隶运到拜占庭和阿拉伯世界,换回来的阿拉伯银币在瑞典出土了几万枚——他们被斯拉夫人叫作「罗斯」,今天「俄罗斯」这个名字就是从这来的。都柏林、约克、海泽比这些城镇是他们的贸易站,英格兰王国还一次次交「丹麦金」买平安。抢不到、卖不掉的时候,他们就带着家人上船,去冰岛、法罗群岛、格陵兰种地放羊。','Raiding was only half of it. Swedes went south down the rivers of Russia carrying furs, wax and slaves to Byzantium and the Arab world, and tens of thousands of Arab silver coins have been dug up in Sweden in return — the Slavs called them the Rus, which is where the name Russia comes from. Dublin, York and Hedeby were their trading towns, and the kings of England paid Danegeld again and again to buy peace. When there was nothing to take or sell they put their families on board and went to farm and herd in Iceland, the Faroes and Greenland.'],
      power:['维京人的本钱是船。长船用叠板法造,又轻又结实,吃水不到一米,能横渡北海也能划进塞纳河去围巴黎(845 年、885 年两次);船头船尾对称,不用掉头就能后退。挪威奥塞贝格和戈克斯塔德出土的两条 9 世纪长船至今完整,1893 年有人照戈克斯塔德船造了复制品,横渡大西洋去了芝加哥。他们的军队规模不大,靠的是来去无踪:抢完就走,等对方集结好,船早已在几十公里外。','Their capital was the ship. Longships were built clinker-fashion, light and strong, drawing less than a metre of water, able to cross the North Sea and to row up the Seine to besiege Paris (in 845 and again in 885); bow and stern were alike, so they could back off without turning. Two ninth-century longships dug out of mounds at Oseberg and Gokstad in Norway survive whole, and in 1893 a copy of the Gokstad ship was sailed across the Atlantic to Chicago. Their forces were never large; what they had was speed — take and go, and by the time a defence gathered the ships were far down the coast.'],
      fall:['劫掠时代在 11 世纪走到头。一方面北欧三国自己变成了基督教王国,国王更愿意收税而不是放船出去;另一方面西欧各国学会了修城堡、建舰队。丹麦的克努特 1016 年做了英格兰国王,一度兼领丹麦与挪威,是维京时代的顶点;1066 年挪威国王哈拉尔·哈德拉达在英格兰的斯坦福桥战死,几星期后诺曼底的威廉——本身就是维京人的后代——征服了英格兰。这一年通常被当作维京时代的终点。','The age of raiding ran out in the eleventh century. On one side the three Norse lands had become Christian kingdoms whose kings preferred to collect taxes rather than send ships out; on the other, the countries of western Europe had learned to build castles and fleets. Cnut of Denmark became king of England in 1016 and for a time held Denmark and Norway as well — the high point of the age; in 1066 King Harald Hardrada of Norway fell at Stamford Bridge in England, and a few weeks later William of Normandy, himself of Viking descent, conquered the country. That year is usually taken as the end of the Viking Age.'],
      legacy:['维京人是最早到达美洲的欧洲人:红发埃里克 986 年前后带人到格陵兰定居,他儿子莱夫·埃里克森约 1000 年到了「文兰」——纽芬兰岛的兰塞奥兹牧草地遗址 1960 年被发现,是格陵兰以外美洲唯一确证的维京聚落,比哥伦布早近五百年。冰岛人在 13 世纪把口传的萨迦写成书,北欧神话(奥丁、雷神托尔)靠这些书传到今天;英语里的星期四(Thursday)就是「托尔的日子」。诺曼底、都柏林、俄罗斯,名字里都留着他们。','The Vikings were the first Europeans to reach America: Erik the Red led settlers to Greenland around 986, and his son Leif Erikson reached Vinland around 1000 — the site at L\'Anse aux Meadows in Newfoundland, found in 1960, is the only confirmed Norse settlement in the Americas outside Greenland, nearly five hundred years before Columbus. Icelanders wrote the oral sagas down in the thirteenth century, and Norse mythology — Odin, Thor and the rest — comes to us through those books; Thursday in English is Thor\'s day. Normandy, Dublin and Russia all carry their name.'] },
  d:'793 年林迪斯法恩遭劫起,到 1066 年斯坦福桥止:挪威、丹麦、瑞典的北欧人靠吃水浅的长船横渡北海、划进内河,劫掠、贸易与定居并行——英格兰的丹麦法区、都柏林、诺曼底(911)、冰岛(传统年份 874)、格陵兰(986)、约 1000 年短暂到过北美;瑞典人顺俄罗斯河流南下到君士坦丁堡与巴格达,给罗斯带去第一批王公。三国约 1000 年前后成形并改信基督教,劫掠淡出。留下长船、卢恩文字与萨迦。' },
{ l:'eu', s:'west', v:2, n:'北欧诸王国', k:[[1066,0],[1200,.2],[1349,.12],[1397,.3],[1523,.2],[1660,.25],[1720,.18],[1814,0]], b:'维京时代之后的三个北欧王国:一位女王把它们合成过一个国家,一场瘟疫又让其中一个再没缓过来。',
  e:{ n:'the Nordic kingdoms', w:'Kalmar Union', b:'The three northern kingdoms after the Viking age: one queen joined them into a single state, and one plague left one of them permanently diminished.', d:'After the raiding stopped, Norway, Denmark and Sweden settled into Christian kingdoms with bishops, law codes and cathedrals, and thirteenth-century Norway ruled Iceland and the Norse settlements in Greenland. The Black Death of 1349 killed something like half of Norway\'s people and broke the machinery of its church and nobility; it never regained the standing it had. In 1397 Queen Margaret, who already ruled Denmark and Norway, had her great-nephew crowned king of all three at Kalmar — one monarch over the largest state Europe\'s north has ever had. Sweden broke away under Gustav Vasa in 1523, and from 1537 Norway was governed as part of Denmark, an arrangement that lasted until 1814. The money came from dried cod shipped out of Bergen, which fed Catholic Europe through Lent and was handled for centuries by German merchants of the Hanseatic League, and from the Sound Dues that Denmark levied on every ship passing into or out of the Baltic. When Denmark backed the losing side in the Napoleonic wars, the Treaty of Kiel in 1814 handed Norway to Sweden — Norwegians wrote their own constitution that year and 17 May is still the national day, but the union with Sweden was imposed all the same. What this age left that is most its own are the stave churches of the Norwegian valleys, built of upright planks without a single iron nail, of which twenty-eight survive.', f:{ 'Peak':'1397–1523 (the Kalmar Union)', 'Center':'Copenhagen, Oslo, Bergen', 'Figures':'Margaret I', 'Legacy':'the Kalmar Union, the stave churches, the dried-cod trade' } },
  f:{ '鼎盛':'1397—1523年(卡尔马联盟)', '中心':'哥本哈根、奥斯陆、卑尔根', '人物':'玛格丽特一世', '成就':'卡尔马联盟、木板教堂、鳕鱼干贸易' },
  qh:{ born:['不再出海抢劫,改在自己家里盖教堂','The raiding stopped and they built churches at home'],
       rule:['一位女王把三个国家合成了一个','One queen joined three kingdoms into one'],
       money:['欧洲人斋期吃的鱼干,从卑尔根运出去','The dried fish Europe ate in Lent left from Bergen'],
       power:['丹麦握着波罗的海的那道门','Denmark held the door to the Baltic'],
       fall:['一场黑死病,挪威从此再没缓过来','One plague, and Norway never fully recovered'],
       legacy:['木头盖的教堂,站了快九百年','Churches built of wood, standing nearly nine hundred years'] },
  q:{ born:['劫掠停下来之后,北欧慢慢定型成三个基督教王国:挪威、丹麦、瑞典。教会带来了主教区、石头教堂和写在羊皮纸上的法典,1103 年隆德设立大主教区,北欧从此有了自己的教省,不再归德意志的汉堡-不来梅管。13 世纪是挪威最强的时候:它管着冰岛(1262 年冰岛人接受挪威国王)、法罗群岛,还有格陵兰岛上那几处北欧人的定居点,国王在卑尔根有王宫,商船一直开到英格兰和佛兰德。','Once the raiding stopped, the north settled into three Christian kingdoms — Norway, Denmark and Sweden. The church brought dioceses, stone cathedrals and law codes written on parchment, and when an archbishopric was founded at Lund in 1103 the north had a province of its own and no longer answered to Hamburg-Bremen in Germany. The thirteenth century was Norway\'s strongest: it held Iceland, whose people accepted the Norwegian king in 1262, along with the Faroes and the Norse settlements in Greenland, its kings kept a hall at Bergen, and its ships traded as far as England and Flanders.'],
      rule:['1397 年,已经统治丹麦和挪威的玛格丽特女王在卡尔马为她的甥孙加冕,三个王国从此有了同一位国王——这是北欧有史以来最大的一个国家。丹麦与挪威那两份靠的是继承与联姻,瑞典那一份是打下来的:1389 年她的军队在奥斯勒之战击败并俘虏了在位的阿尔贝特国王,把他关了六年。联盟维持了一百多年,但三国各有自己的议会与贵族,矛盾一直在:1520 年丹麦国王在斯德哥尔摩处死了近百名瑞典贵族,史称「斯德哥尔摩惨案」,三年后古斯塔夫·瓦萨领着瑞典脱离出去,联盟散了。丹麦和挪威留在一起,1537 年宗教改革之后挪威被当作丹麦的一部分来治理,一直到 1814 年。','In 1397 Queen Margaret, who already ruled Denmark and Norway, had her great-nephew crowned at Kalmar, and the three kingdoms shared one monarch — the largest state the north has ever had. Denmark and Norway came to her by inheritance and marriage; Sweden was taken by force, her army beating and capturing the reigning King Albert at Åsle in 1389 and holding him for six years. The union lasted over a century, but each kingdom kept its own council and nobility and the friction never went away: in 1520 the Danish king had some ninety Swedish nobles executed in Stockholm, and three years later Gustav Vasa led Sweden out and the union was finished. Denmark and Norway stayed together, and after the Reformation of 1537 Norway was governed as part of Denmark, which it remained until 1814.'],
      money:['最重要的一样出口货是鳕鱼干。北挪威的鳕鱼晾在木架上风干,不用盐也能存好几年,运到卑尔根,再由汉萨同盟的德国商人卖到欧洲各地——天主教的斋期一年有一百多天不能吃肉,鱼干就是那时候的蛋白。汉萨商人在卑尔根有自己的一片商站(布吕根),几百年里几乎垄断了这条生意。丹麦的钱来得更省力:所有进出波罗的海的船都要走厄勒海峡,丹麦在海峡上架炮收「海峡税」(1658 年丢掉斯科讷之前两岸都是它的),从 1429 年一直收到 19 世纪,长期是王室最大的一笔进项。瑞典出铁和铜,法伦的铜矿一度供应了欧洲大半的铜。','The great export was dried cod. Cod from northern Norway was hung on wooden racks and wind-dried until it kept for years without salt, shipped to Bergen and sold on across Europe by German merchants of the Hanseatic League — Catholic Europe had well over a hundred meatless days a year, and this was the protein that filled them. The Hansa kept their own quarter at Bergen, the Bryggen, and held a near-monopoly on the trade for centuries. Denmark\'s money came more easily: every ship entering or leaving the Baltic had to pass the Sound, where Denmark mounted guns to collect the Sound Dues — both shores were hers until Scania was lost in 1658 — from 1429 into the nineteenth century, for long stretches the crown\'s largest single revenue. Sweden sold iron and copper, and the mine at Falun at one point supplied most of Europe\'s copper.'],
      power:['力量来自水:挪威的船、丹麦的海峡、瑞典的矿。三国的海岸线加起来比欧洲任何地方都长,冬天结冰、夏天化开,航路决定了谁能收谁的税。丹麦握着波罗的海的门,瑞典想出海就得跟它打——两国从 16 到 18 世纪打了十来场仗,丹麦一路失地,斯科讷、哈兰、布莱金厄这几块今天属于瑞典的南部土地,都是那几百年里丢掉的。1611—1721 年瑞典一度成为北欧的强权,那一段在站里另有一条「瑞典帝国」的色带。','Its strength was water: Norwegian ships, the Danish strait, Swedish ore. Between them the three had more coastline than anywhere else in Europe, freezing in winter and opening in summer, and the sea lanes decided who could tax whom. Denmark held the door to the Baltic and Sweden had to fight it to get out — the two went to war a dozen times between the sixteenth and eighteenth centuries, Denmark losing ground each time, and Scania, Halland and Blekinge, the southern provinces that are Swedish today, were all lost in those centuries. Sweden\'s own spell as a great power, 1611 to 1721, has a band of its own in this chart.'],
      fall:['按冰岛年代记的说法,1349 年黑死病随一条英格兰来的船进了卑尔根(奥斯陆可能还更早几个月),一年之内传遍全境。挪威死了大约一半人,也有估到六成以上的;村子空掉,耕地退回森林,收租的教会和贵族体系散了架,连王室的行政都难以维持。这不是一次可以缓过来的打击——挪威从此再没恢复到 13 世纪的地位,一百多年后被当作丹麦的一部分来治理,与此直接有关。终点来得也不体面:拿破仑战争里丹麦站在法国一边,战败后 1814 年的《基尔条约》把挪威割给瑞典;挪威人当年自己开了制宪会议、通过了宪法(5 月 17 日至今是挪威国庆),但还是被迫与瑞典结成联合王国,直到 1905 年才和平分手。','The Icelandic annals have the Black Death come into Bergen on an English ship in 1349 — Oslo may have been struck months earlier — and it swept the country within a year. Something like half of Norway\'s people died, by some estimates three fifths or more; villages emptied, farmland went back to forest, the church and noble structures that collected the rents fell apart, and even royal administration became hard to keep up. This was not a blow to be recovered from — Norway never regained its thirteenth-century standing, and its being governed as part of Denmark a century and a half later followed directly from it. The end was undignified too: Denmark took France\'s side in the Napoleonic wars, and the Treaty of Kiel handed Norway to Sweden in 1814. Norwegians held their own constituent assembly and passed a constitution that year — the seventeenth of May is still the national day — but were forced into a union with Sweden all the same, and only parted from it, peacefully, in 1905.'],
      legacy:['挪威山谷里的木板教堂是这段时间留下的最特别的东西:整座教堂用立起来的木板搭成,不用一根铁钉,屋脊上刻着龙头——基督教的教堂,做工和纹样却还是维京人的。中世纪建过上千座,今天还剩 28 座,最老的乌尔内斯教堂立了快九百年,是世界遗产。冰岛人在这几百年里把萨迦写了下来,北欧神话能传到今天靠的就是那批手稿。厄勒海峡两岸的炮台和收税站还在,鳕鱼干至今是挪威的出口货——意大利、葡萄牙、尼日利亚都在买。给孩子最容易记住的一件事:欧洲人过斋期时餐桌上的鱼,是从北极圈边上吹风吹干、再一路运过来的。','What this age left that is most its own are the stave churches in the Norwegian valleys: whole churches built of upright planks without a single iron nail, with dragon heads carved along the roof ridges — Christian buildings whose craft and ornament are still Viking. A thousand or more were built in the Middle Ages and twenty-eight survive; the oldest, at Urnes, has stood nearly nine hundred years and is on the World Heritage list. It was in these centuries that Icelanders wrote the sagas down, and the Norse myths reach us today through those manuscripts. The forts and toll houses still stand on both sides of the Sound, and dried cod is still a Norwegian export, bought in Italy, Portugal and Nigeria. The easiest thing for a child to remember: the fish on European tables through Lent was wind-dried at the edge of the Arctic and carried the whole way south.'] },
  d:'维京时代之后北欧定型为挪威、丹麦、瑞典三个基督教王国,13 世纪的挪威管着冰岛,以及格陵兰岛上那几处北欧人的定居点。1349 年黑死病夺去挪威约一半人口,它从此再没缓过来。1397 年玛格丽特女王在卡尔马把三国合于一位君主,是北欧史上最大的国家;1523 年瑞典脱离,1537 年后挪威被当作丹麦的一部分治理。财富靠卑尔根输出的鳕鱼干(经汉萨同盟卖往全欧)与丹麦在厄勒海峡收的过路税。1814 年《基尔条约》把挪威割给瑞典,挪威人当年自己开制宪会议、通过了宪法(5 月 17 日至今是国庆),仍被迫与瑞典结成联合王国。留下的最特别的东西是挪威山谷里的木板教堂:整座用立起来的木板搭成、不用一根铁钉,屋脊刻着龙头,现存 28 座。' },
{ l:'eu', s:'west', v:0, n:'文艺复兴意大利', k:[[1300,0],[1450,.38],[1520,.42],[1620,0]], b:'城邦商业繁荣孕育文艺复兴,近代欧洲的思想引擎。',
  e:{ n:'Renaissance Italy', w:'Italian Renaissance', b:'Merchant city-states bankroll the rediscovery of the classical world.', d:'City-states fattened on Mediterranean trade spent their wealth on art and learning, rediscovering antiquity; humanism turned the gaze from God to man. Politically fragmented, Italy became the battlefield of France and Spain while the Atlantic powers took the lead.', f:{ 'Peak':'c. 1500', 'Center':'Florence, Venice', 'Figures':'The Medici, Leonardo, Michelangelo', 'Legacy':'Humanism, perspective, double-entry bookkeeping' } },
  f:{ '鼎盛':'15—16世纪之交', '中心':'佛罗伦萨、威尼斯', '人物':'美第奇家族、达·芬奇、米开朗基罗', '成就':'人文主义、透视法、复式记账' },
  co:[ { n:['佛罗伦萨','Florence'], c:['托斯卡纳','Tuscany'], g:['意大利五强','The five powers'], x:['1454年洛迪和约后,五强的均势维持了四十年,直到1494年法军入侵','after the Peace of Lodi in 1454 the balance among the five held for forty years, until the French invasion of 1494'] },
       { n:['威尼斯','Venice'], c:['亚得里亚海北岸','the northern Adriatic'], g:['意大利五强','The five powers'] },
       { n:['米兰','Milan'], c:['伦巴第','Lombardy'], g:['意大利五强','The five powers'] },
       { n:['教皇国','the Papal States'], c:['罗马与中部','Rome and the centre'], g:['意大利五强','The five powers'] },
       { n:['那不勒斯王国','the Kingdom of Naples'], c:['半岛南部','the southern peninsula'], g:['意大利五强','The five powers'] },
       { n:['热那亚','Genoa'], c:['利古里亚','Liguria'], g:['没能挤进五强的城邦与小宫廷','States and small courts outside the big five'], x:['热那亚有钱(圣乔治银行向全欧君主放贷),输在政局动荡、屡次落入外国控制;小宫廷则靠赞助艺术换声望','Genoa had the money — its Bank of Saint George lent to monarchs across Europe — but lost ground to political turmoil and repeated spells of foreign control; the little courts bought prestige by paying for art instead'] },
       { n:['锡耶纳','Siena'], c:['托斯卡纳','Tuscany'], g:['没能挤进五强的城邦与小宫廷','States and small courts outside the big five'] },
       { n:['曼图亚','Mantua'], c:['波河平原','the Po plain'], g:['没能挤进五强的城邦与小宫廷','States and small courts outside the big five'] },
       { n:['费拉拉','Ferrara'], c:['波河下游','the lower Po'], g:['没能挤进五强的城邦与小宫廷','States and small courts outside the big five'] },
       { n:['乌尔比诺','Urbino'], c:['马尔凯','the Marche'], g:['没能挤进五强的城邦与小宫廷','States and small courts outside the big five'] } ],
  qh:{ born:['皇帝和教皇争不下,城市就自治了','Emperor and pope deadlocked, and the cities ran themselves'],
       rule:['美,是权力的广告','Beauty was the advertisement of power'],
       money:['复式记账,让账第一次真算得清','Double-entry books made the accounts add up at last'],
       power:['打不起大仗,就发明了常驻大使','Unable to afford a war, they invented the resident ambassador'],
       fall:['财富还在,主导权已经移去大西洋','The wealth stayed; the initiative moved to the Atlantic'],
       legacy:['伽利略在这里,把实验立成了标准','Here Galileo made the experiment the standard'] },
  q:{ born:['地中海贸易把财富堆进意大利城市,而皇帝与教皇的长期相争让这些城市得以自治。富起来的市民脚下就踩着罗马的废墟——重新发现古典世界,几乎是顺理成章的下一步。','Mediterranean trade piled wealth into Italian cities, while the long contest between emperor and pope left them free to govern themselves. These prosperous townsmen literally walked on Roman ruins — rediscovering the classical world was almost the natural next step.'],
      rule:['城邦各行其是:威尼斯是贵族共和国,米兰是公爵领,佛罗伦萨名义共和,实由美第奇家族以财富与人脉在幕后掌舵。统治靠的不是头衔,而是银行账本与艺术赞助——美,是权力的广告。','Each state went its own way: Venice an aristocratic republic, Milan a duchy, Florence a nominal republic steered from behind the scenes by Medici money and connections. Rule rested less on titles than on bank ledgers and artistic patronage — beauty was power\'s advertisement.'],
      money:['意大利商人是东西方贸易的中间人,香料与丝绸经威尼斯转手欧洲;佛罗伦萨靠毛纺与银行业发家,美第奇银行的分号开遍欧洲,复式记账法让账目第一次真正算得清楚。','Italian merchants brokered trade between East and West, spices and silk passing through Venice into Europe. Florence grew rich on wool and banking — Medici branches spread across the continent — and double-entry bookkeeping made accounts truly add up for the first time.'],
      power:['小国靠巧劲:意大利人发明了常驻大使与均势外交,用谈判和联姻代替打不起的大战,雇佣兵队长代行征战。财富与文化本身就是威望——欧洲各国宫廷争相延请意大利的艺术家与学者。','Small states survived on finesse: Italians invented the resident ambassador and balance-of-power diplomacy, substituting negotiation and marriage for wars they could not afford, while condottieri captains did the fighting for hire. Wealth and culture were prestige in themselves — courts across Europe competed for Italian artists and scholars.'],
      fall:['分裂的账单最终到账:1494年法军入侵揭开意大利战争,半岛沦为法国与西班牙争霸的战场,1527年罗马城惨遭洗劫;大西洋航路兴起后,地中海的枢纽地位也逐渐旁落。城邦的财富还在,主导权已移向大西洋沿岸的君主国。','The bill for disunity came due: the French invasion of 1494 opened the Italian Wars, the peninsula became the battleground of France and Spain, and Rome itself was sacked in 1527. As Atlantic routes rose, the Mediterranean slowly lost its central place; the city-states kept their wealth but ceded leadership to the monarchies of the Atlantic seaboard.'],
      legacy:['人文主义把目光从神转回人,透视法改写了绘画,伽利略在这里把实验立为科学的标准;复式记账与银行技术成为现代商业的地基。文艺复兴由此扩散,点亮整个欧洲。','Humanism turned attention from heaven back to humanity, perspective transformed painting, and here Galileo made experiment the standard of science. Double-entry bookkeeping and banking techniques laid the foundations of modern business, and from Italy the Renaissance spread to light up all of Europe.'] },
  d:'地中海贸易养肥的城邦以财富赞助艺术与学问,重新发现古典世界,人文主义把目光从神转回人。但政治上四分五裂,沦为法国与西班牙争霸的战场,风头最终让给了大西洋沿岸的新兴国家。' },
{ l:'eu', s:'west', v:1, n:'波兰-立陶宛', k:[[1385,0],[1500,.32],[1570,.4],[1650,.32],[1720,.15],[1795,0]], b:'一度是欧洲面积最大的国家之一,却由贵族选举国王、一票可以否决议会。',
  e:{ n:'the Polish-Lithuanian Commonwealth', w:'Polish–Lithuanian Commonwealth', b:'Once among the largest countries in Europe, with an elected king and a parliament any one member could dissolve.', d:'A royal marriage in 1385 joined Lithuania to Poland, and the Union of Lublin in 1569 made them one commonwealth of nearly a million square kilometres. The king was elected by the nobility and the diet had the liberum veto — one deputy\'s objection voided the whole session, a design meant to stop absolutism that ended by stopping government. Grain down the Vistula fed western Europe and built a powerful landed class, and with it the second serfdom. Sobieski led the army that relieved Vienna in 1683; then came the Cossack rising, the Swedish Deluge, and partition in 1772, 1793 and 1795 — Russia and Prussia every time, Austria in the first and third — and off the map for a hundred and twenty-three years.', f:{ 'Peak':'late 16th to early 17th c.', 'Center':'Kraków → Warsaw', 'Figures':'John III Sobieski', 'Legacy':'A nobles\' republic, the Warsaw Confederation on religion, the winged hussars' } },
  f:{ '鼎盛':'16世纪末—17世纪初', '中心':'克拉科夫→华沙', '人物':'扬三世·索别斯基', '成就':'贵族共和制、宗教宽容令、翼骑兵' },
  qh:{ born:['一场联姻,把两个国家接成了一个','One marriage joined two countries into one'],
       rule:['一个人反对,整届议案就全作废','One man objecting voided the entire session'],
       money:['西欧农奴松绑时,这里反而绑得更紧','As serfdom loosened in the west, it tightened here'],
       power:['翼骑兵很能打,可议会不肯拨款','The winged hussars could fight; the diet would not pay'],
       fall:['被瓜分三次,从地图上消失123年','Partitioned three times, and off the map for 123 years'],
       legacy:['王权真的被限住了,国家也真的转不动','The crown really was limited, and the state really stopped working'] },
  q:{ born:['1385年立陶宛大公约盖拉与波兰女王雅德维加联姻,两国由此共主;1569年《卢布林联合》把君合国变成一个共同体,有共同的议会、货币与外交,而各自保留军队与法律。这个组合把波兰的农业与立陶宛在东欧的广袤领土接在一起,面积一度接近一百万平方公里。','In 1385 Grand Duke Jogaila of Lithuania married Queen Jadwiga of Poland and the two came under one crown; the Union of Lublin in 1569 turned a personal union into a single commonwealth with a shared parliament, currency and foreign policy, while each kept its own army and law. The combination joined Polish farmland to Lithuania\'s vast holdings in eastern Europe, and at one point covered close to a million square kilometres.'],
      rule:['国王由贵族选举产生,而不是世袭——候选人常来自外国王室,当选前要签一份限制王权的条件书。议会实行「自由否决权」:任何一名议员反对,整届议案作废、会期解散。这套设计初衷是防止专制,长期运行下来却让中央几乎无法决策。贵族占人口约一成,比同期欧洲多数国家高得多,这也是它被称为「贵族共和国」的原因。','The king was elected by the nobility rather than inheriting — candidates often came from foreign royal houses and had to sign a charter limiting the crown before taking it. The parliament had the liberum veto: one deputy\'s objection voided the entire session\'s legislation and dissolved it. The design was meant to prevent absolutism, and over time it left the centre almost unable to decide anything. Nobles made up roughly a tenth of the population, far more than in most of contemporary Europe, which is why it is called a nobles\' republic.'],
      money:['底盘是粮食:维斯瓦河把内陆的黑麦与小麦运到但泽出海,西欧的城市吃它的粮。这条生意造就了强大的地主阶层,也强化了「二次农奴制」——东欧的农民在西欧农奴制瓦解的同一时期反而被束缚得更紧。粮价高时国家富庶,17世纪中叶粮价回落与连年战争叠加,财政就撑不住了。','Grain was the base: the Vistula carried rye and wheat down to Danzig and out to sea, and the cities of western Europe ate it. The trade built a powerful landowning class and reinforced the second serfdom — eastern European peasants were bound more tightly in the same centuries that serfdom was dissolving in the west. High grain prices meant a rich country; when prices fell in the mid-seventeenth century and wars came one after another, the finances gave way.'],
      power:['翼骑兵是它最著名的兵种:重甲长矛,背后装一对羽翼,冲锋时以密集队形正面凿穿对手。1683年扬三世·索别斯基率军解维也纳之围,是它在欧洲舞台上最后一次高光。但军队规模长期偏小——议会不肯拨款,常备军人数远低于同期的法国或俄国,战时靠贵族自带部曲。','The winged hussars are its best-known troops: heavy lance-armed cavalry with a pair of feathered wings behind, charging home in close order. In 1683 John III Sobieski led the army that relieved the siege of Vienna, its last moment on the European stage. But the army was chronically small — parliament would not vote the money, the standing force was far below France\'s or Russia\'s, and in war it leaned on nobles bringing their own retainers.'],
      fall:['17世纪中叶是转折:1648年哥萨克起义、1655年起瑞典入侵(波兰史称「大洪水」),人口损失极重。此后自由否决权被邻国收买的议员反复使用,国家陷入长期瘫痪。1772、1793、1795年三次被瓜分——俄国与普鲁士三次都在,奥地利参加了第一次和第三次——国家从地图上消失一百二十三年。1791年通过的《五三宪法》试图取消自由否决权、加强王权,是欧洲第一部成文的现代国家宪法之一,但两年后就随第二次瓜分作废。','The mid-seventeenth century was the turn: a Cossack rising in 1648 and a Swedish invasion from 1655 — the Deluge, in Polish history — cost enormous numbers of lives. Afterwards the liberum veto was used again and again by deputies bought by neighbouring powers, and the state was paralysed for decades. It was partitioned in 1772, 1793 and 1795 — Russia and Prussia in all three, Austria in the first and the third — and vanished from the map for a hundred and twenty-three years. The Constitution of 3 May 1791, which tried to abolish the veto and strengthen the crown, was among the first written constitutions of a modern state in Europe — and was void two years later with the second partition.'],
      legacy:['它是近代欧洲少见的、把「限制王权」推到极端的实验,结果同时展示了这条路的两面:王权确实被限制住了,而国家也确实没法运转。1573年的《华沙联盟协约》在宗教战争席卷欧洲时承诺贵族间的宗教和平,当时相当罕见。国家消失的一百二十三年间,波兰人靠语言、文学与教会维持认同,1918年复国——这段经验此后成为东欧民族主义的一个范本。','It was a rare early-modern experiment in pushing the limitation of monarchy to its extreme, and it demonstrated both sides of that at once: the crown really was held in check, and the state really could not function. The Warsaw Confederation of 1573 promised religious peace among the nobility while religious war was sweeping Europe, which was very unusual at the time. Through the hundred and twenty-three years of its absence Poles held their identity together with language, literature and the church, and the country returned in 1918 — an experience that became a model for nationalism across eastern Europe.'] },
  d:'1385年立陶宛大公与波兰女王联姻,1569年《卢布林联合》合为一体,面积一度近百万平方公里。国王由贵族选举,议会有「自由否决权」——一人反对全届作废,初衷是防专制,结果是无法决策。粮食经维斯瓦河出海养起强大的地主阶层,也强化了二次农奴制。1683年索别斯基解维也纳之围是最后的高光;1648年哥萨克起义与1655年瑞典「大洪水」重创之后,1772、1793、1795年三次被瓜分(俄普三次都在,奥地利参加了第一、第三次),从地图上消失一百二十三年。' },
{ l:'eu', s:'west', v:2, n:'西班牙·葡萄牙帝国', k:[[1415,0],[1500,.5],[1560,.8],[1650,.5],[1750,.28],[1820,0]], b:'大航海先行者,首个"日不落"殖民帝国,美洲白银流入。',
  e:{ n:'the Spanish and Portuguese Empires', w:'Spanish Empire', b:'First movers of the Age of Sail; the first global empire.', d:'Forged by the Reconquista, the two Iberian kingdoms sailed first: Portugal around Africa to India, Spain into the Americas — a papal line divided the globe between them. American silver poured in without becoming productive power; after the Armada\'s defeat, hegemony passed to the Dutch and English.', f:{ 'Peak':'late 16th c. (Philip II)', 'Center':'Lisbon, Madrid', 'Figures':'Henry the Navigator, Columbus, Magellan, Miguel de Cervantes', 'Legacy':'New sea routes, first global empire' } },
  f:{ '鼎盛':'16世纪后期(腓力二世)', '中心':'里斯本、马德里', '人物':'恩里克王子、哥伦布、麦哲伦、塞万提斯', '成就':'开辟新航路、首个全球帝国' },
  qh:{ born:['仗打完了,骑士和野心得找个新出口','The wars ended, and the knights needed somewhere to go'],
       rule:['拿教皇背书,一条线把地球分了','With papal backing, one line divided the globe'],
       money:['钱从手心流过,落进了别人口袋','The money ran through their hands into other pockets'],
       power:['几条航线,连起了第一个全球帝国','A few sea routes made the first global empire'],
       fall:['优势不是一战丢的,是几十年慢慢丢的','The lead was not lost in one battle but over decades'],
       legacy:['全球化的第一页,是这两个国家翻开的','These two turned the first page of globalisation'] },
  q:{ born:['数百年收复失地运动锻造出两个尚武而虔诚的王国,战争结束时,骑士与野心都需要新的出口。香料贸易被中间商层层加价,葡萄牙便沿非洲海岸寻找绕行之路;西班牙资助哥伦布向西横渡,一头撞上美洲。','Centuries of Reconquista forged two militant, devout kingdoms, and when that war ended, knights and ambitions needed a new outlet. With the spice trade marked up by layers of middlemen, Portugal probed down the African coast for a route of its own, while Spain backed Columbus sailing west — straight into the Americas.'],
      rule:['王权与教会捆绑统治:两国凭教皇背书以《托尔德西里亚斯条约》一线分球,海外由副王代国王牧民,传教士与总督同船而行。本土则走向集权,腓力二世靠批阅文书统治四大洲的领地。','Crown and church ruled in tandem: with papal sanction the two kingdoms divided the globe along the Tordesillas line, viceroys governed overseas in the monarch\'s name, and missionaries sailed with the governors. At home power centralized — Philip II ran domains on four continents from his writing desk.'],
      money:['葡萄牙靠垄断绕非洲的香料航线抽利;西班牙靠美洲金银,波托西的白银经塞维利亚流入欧洲。但巨量白银推高物价、松懈了本国产业,金山银海未转化为生产力——钱从手心流过,落进了外国银行家与工场主的口袋。','Portugal profited from its monopoly on the spice route around Africa; Spain lived on American treasure, silver from Potosí flowing through Seville into Europe. But the flood of bullion drove up prices and slackened home industry — the wealth passed through Spanish hands into the pockets of foreign bankers and manufacturers.'],
      power:['强在远洋技术与远征组织:卡拉维尔帆船配上舰炮开出航路,几条航线连起第一个全球帝国;16世纪的西班牙方阵步兵称雄欧洲战场,哈布斯堡联姻更把半个欧洲揽入版图。','Its strength lay in ocean navigation and expeditionary organization: caravels and shipboard cannon opened the sea lanes that linked the first global empire. In the 16th century the Spanish tercios dominated European battlefields, and Habsburg marriages folded half of Europe into the dynasty\'s holdings.'],
      fall:['一般认为是多因叠加:同时与荷兰、英国、法国缠斗,战费远超白银收入,王室屡次宣告破产;通胀与产业空心化侵蚀根基;1588年无敌舰队折戟,但西班牙很快重建舰队,海上优势的转移是此后几十年一点点发生的。拿破仑1808年入侵伊比利亚后,美洲大陆领地在1820年代尽数独立(古巴、菲律宾等要到1898年才脱手)。','The mainstream view is cumulative causes: fighting the Dutch, English and French at once cost far more than the silver brought in, bankrupting the crown repeatedly, while inflation and a hollowed-out economy ate at the base. The Armada\'s destruction in 1588 marked the passing of naval supremacy; after Napoleon invaded Iberia in 1808, the American colonies broke away one after another, and the empire dissolved in the 1820s.'],
      legacy:['西班牙语和葡萄牙语成为数亿人的母语,天主教扎根拉丁美洲;新旧大陆的作物、牲畜与人口第一次大交换,重塑了两个半球的餐桌与命运。全球化的第一页,由这两个国家翻开。','Spanish and Portuguese became the mother tongues of hundreds of millions, and Catholicism took root across Latin America. The first great exchange of crops, animals and peoples between the hemispheres reshaped diets and destinies on both sides — these two kingdoms turned the first page of globalization.'] },
  d:'收复失地运动锻造的两个铁血王国率先驶向大洋:葡萄牙沿非洲绕到印度,西班牙一头撞上美洲,教皇子午线干脆瓜分了地球。美洲金银滚滚流入却未转化为生产力,无敌舰队折戟后,海上优势在此后几十年间逐步让给荷兰与英国。' },
{ l:'eu', s:'west', v:0, n:'奥地利·哈布斯堡', k:[[1526,0],[1620,.4],[1700,.45],[1780,.45],[1815,.4],[1870,.3],[1918,0]], b:'靠联姻攒起来的中欧王朝:统治十几个民族,最后被民族主义拆散。',
  e:{ n:'Habsburg Austria', w:'Habsburg monarchy', b:'A Central European dynasty assembled by marriage, ruling a dozen peoples until nationalism pulled it apart.', d:'When the king of Hungary died at Mohács in 1526 his brother-in-law was a Habsburg, and Austria, Bohemia and what was left of Hungary came into one family\'s hands — let others wage war, went the saying; you, happy Austria, marry. It ruled Germans, Hungarians, Czechs, Poles, Croats and more with no group in the majority, and governed by bargaining with each region rather than assimilating it. Vienna was relieved in 1683 by a Polish and imperial army, and Hungary was taken back in the decades after, lost Silesia to Prussia in 1740, and was knocked out of Germany at Königgrätz in 1866. The 1867 compromise with Hungary admitted a single centre could not hold; four years of war finished it in 1918.', f:{ 'Peak':'the 18th c. (Maria Theresa to Joseph II)', 'Center':'Vienna', 'Figures':'Maria Theresa', 'Legacy':'Machinery for governing many peoples at once, the music and architecture of Vienna' } },
  f:{ '鼎盛':'18世纪(玛丽亚·特蕾莎至约瑟夫二世)', '中心':'维也纳', '人物':'玛丽亚·特蕾莎', '成就':'多民族共治的行政机制、维也纳的音乐与建筑' },
  qh:{ born:['版图是结婚攒出来的,不是打出来的','The map was assembled by marriage, not by war'],
       rule:['不搞同化,和各地分别谈条件','No assimilation: it bargained with each land separately'],
       money:['它长期缺的东西,是海','What it lacked, all along, was the sea'],
       power:['军官得去学手下士兵的语言','Officers had to learn the languages of their men'],
       fall:['最禁不起「每个民族该有自己的国家」','Nothing hurt it more than one nation, one state'],
       legacy:['多民族的政治体,能不能长期存在','Can a multinational polity last? It left the question'] },
  q:{ born:['1526年莫哈奇之战,匈牙利国王阵亡于奥斯曼军前,而他的姐夫正是哈布斯堡家的斐迪南——奥地利、波希米亚与匈牙利残部由此归入同一家族。后来有一句话专门用来形容它:「让别人去打仗,你,幸福的奥地利,去结婚。」这句是后人总结的——完整的出处最早只见于18世纪,不是1526年就有的说法——但它说得没错:它的版图确实主要靠婚姻与继承而不是征服攒起来的,而这也决定了它的性质——不是一个民族国家,而是若干王国凑在同一个王冠下。要说清楚的是:这个家族当时分成两支,西班牙那一支管着西班牙与美洲(1700年绝嗣),奥地利这一支管中欧;本条讲的是奥地利这一支。','At Mohács in 1526 the king of Hungary died in front of an Ottoman army, and his brother-in-law was Ferdinand of Habsburg — so Austria, Bohemia and what was left of Hungary came into one family\'s hands. A line was later coined for it: let others wage war; you, happy Austria, marry. It is a later summary — the couplet cannot be traced back beyond the eighteenth century, not to 1526 — but it is accurate: the realm really was assembled by marriage and inheritance rather than conquest, and that settled what it was: not a nation-state but a set of kingdoms gathered under one crown. One thing to be clear about: the family had split in two, the Spanish line holding Spain and the Americas until it died out in 1700, the Austrian line holding central Europe — this band is the Austrian line.'],
      rule:['它统治的是德意志人、匈牙利人、捷克人、波兰人、克罗地亚人、意大利人、罗马尼亚人等等,没有一个占多数。这决定了它的治理方式:不追求同化,而是与各地贵族分别谈条件——匈牙利保留自己的议会与法律,波希米亚有自己的传统。18世纪玛丽亚·特蕾莎与约瑟夫二世推行中央集权改革(统一税制、废除农奴人身依附、德语行政),提高了效率,也第一次激起了各民族的反弹。','It ruled Germans, Hungarians, Czechs, Poles, Croats, Italians, Romanians and more, with no group in the majority. That decided how it governed: not by assimilation but by bargaining separately with each region\'s nobility — Hungary kept its own diet and law, Bohemia its own traditions. In the eighteenth century Maria Theresa and Joseph II pushed centralising reforms — a uniform tax system, the end of personal serfdom, German-language administration — which raised efficiency and provoked the first national backlash.'],
      money:['波希米亚的手工业与矿产、匈牙利的粮食与牲畜、奥地利本土的手工业与过境贸易,构成三块底盘。多瑙河是它的动脉,维也纳卡在河上,既是首都也是转口市场。它长期缺的是海——海岸线只有亚得里亚海北端一小段,主要出海口是的里雅斯特与阜姆(今里耶卡),通不到大西洋,所以在海外殖民的时代它基本缺席,这与同期的西班牙、荷兰、英国完全不同。','Bohemian crafts and mines, Hungarian grain and cattle, and Austria\'s own manufactures and transit trade made three foundations. The Danube was its artery and Vienna sat on it, capital and entrepôt at once. What it lacked was sea: a short stretch of coast at the head of the Adriatic with Trieste and Fiume (today Rijeka) as its outlets, and no way to the Atlantic, which is why it was essentially absent from the age of overseas colonies, quite unlike contemporary Spain, the Netherlands or Britain.'],
      power:['东面对奥斯曼、西面对法国,两线是它的常态。1683年维也纳第二次被围,解围后的几十年里它反过来收复了整个匈牙利。但它很少能独力打赢大国战争:1740年普鲁士夺走西里西亚,此后与普鲁士争夺德意志领导权百余年,1866年在克尼格雷茨败北,彻底出局。军队是多民族的,解法是三层:全军统一用八十来个德语口令、人人都得背;日常各团讲各团的话;军官反倒要去学手下士兵的语言。这套办法转得起来,但代价很大——这是它军事效率的长期问题。','The Ottomans to the east and France to the west were its permanent two fronts. Vienna was besieged a second time in 1683, and in the decades after the relief it took back the whole of Hungary. But it seldom won a great-power war on its own: Prussia took Silesia in 1740, and after a century of contesting the leadership of Germany it was beaten decisively at Königgrätz in 1866 and out of the running. Its army was multi-ethnic and the answer came in three layers: eighty-odd German words of command that every soldier had to learn by heart; the language of the recruiting district for daily use in each regiment; and officers required to learn the language of their own men. It worked, but it cost a great deal — a standing problem for its military efficiency.'],
      fall:['19世纪的民族主义对它是致命的:一个由十几个民族拼成的国家,恰恰最禁不起「每个民族应有自己的国家」这个观念。1867年与匈牙利妥协,改组为奥匈二元帝国,等于承认无法维持单一中央。1914年萨拉热窝的枪声由此而来,而四年战争打光了它最后的黏合力——1918年帝国解体,分成奥地利、匈牙利、捷克斯洛伐克等国,另有大片领土划给邻国。','Nineteenth-century nationalism was fatal to it: a state made of a dozen peoples is exactly the kind least able to survive the idea that every people should have a state. The compromise with Hungary in 1867 turned it into the dual monarchy of Austria-Hungary, which was an admission that a single centre could not hold. The shots at Sarajevo in 1914 came out of that, and four years of war used up what cohesion was left — in 1918 the empire came apart into Austria, Hungary, Czechoslovakia and others, with large areas going to neighbours.'],
      legacy:['维也纳在18—19世纪成了欧洲音乐的中心,海顿、莫扎特、贝多芬、舒伯特、勃拉姆斯、马勒都在这里工作过;19世纪末到20世纪初的维也纳又是精神分析、现代建筑与逻辑实证主义的发源地之一。它留下的另一样东西是一个反复被讨论的问题:一个多民族的政治体能不能长期存在、靠什么维持?后来的欧盟讨论中常有人回头看它,既当范例也当教训。','Vienna became the centre of European music through the eighteenth and nineteenth centuries — Haydn, Mozart, Beethoven, Schubert, Brahms and Mahler all worked there — and Vienna from the 1890s into the 1920s was one of the birthplaces of psychoanalysis, modern architecture and logical positivism. The other thing it left is a question people keep returning to: whether a multinational polity can last, and on what. Discussions of the European Union look back at it often, as both precedent and warning.'] },
  d:'1526年莫哈奇之战后,奥地利、波希米亚与匈牙利残部归入同一家族——「让别人去打仗,你,幸福的奥地利,去结婚」不全是玩笑:版图主要靠婚姻与继承攒起来。它统治十几个民族而没有一个占多数,治理方式是与各地贵族分别谈条件。1683年波兰与帝国联军解维也纳之围,此后收复匈牙利,1740年被普鲁士夺走西里西亚,1866年克尼格雷茨败北退出德意志。1867年改组为奥匈二元帝国,1918年在民族主义与四年大战之下解体。' },
{ l:'eu', s:'west', v:1, n:'荷兰共和国', k:[[1580,0],[1650,.5],[1700,.4],[1795,.2],[1815,0]], b:'17世纪的"海上马车夫",股份公司与现代金融的发明者。',
  e:{ n:'Dutch Republic', b:'The 17th-century "wagoner of the seas", pioneer of the publicly traded company.', d:'The seven provinces that broke from Spain ruled the 17th century through shipping and financial innovation: the VOC was the first company to sell freely tradable shares to the public and Amsterdam the world\'s money center. Naval primacy passed to England, but Dutch commercial institutions were inherited by everyone.', f:{ 'Peak':'mid-17th c. (Golden Age)', 'Center':'Amsterdam', 'Figures':'Grotius, Rembrandt', 'Legacy':'VOC, stock exchange' } },
  f:{ '鼎盛':'17世纪中(黄金时代)', '中心':'阿姆斯特丹', '人物':'格劳秀斯、伦勃朗', '成就':'东印度公司(首家公开发行股票的公司)、证券交易所' },
  qh:{ born:['打出了一个没有国王的商人共和国','It fought its way to a merchant republic with no king'],
       rule:['商人治国,国策围着账本转','Merchants governed, and policy followed the ledger'],
       money:['把远洋的风险,切成股份卖给公众','It cut the risk of a voyage into shares and sold them'],
       power:['一家公司,在亚洲行使着半个主权','One company exercised half a sovereignty in Asia'],
       fall:['对手学会了它的打法,体量还更大','Rivals learned its methods, and were simply bigger'],
       legacy:['纽约的前身,就叫新阿姆斯特丹','New York began life as New Amsterdam'] },
  q:{ born:['尼德兰低地的城市富庶而自治,西班牙的重税与宗教迫害逼出一场起义;北方七省联合抵抗,打出一个没有国王的商人共和国。安特卫普陷落后,资本与工匠涌向阿姆斯特丹。','The prosperous, self-governing towns of the Low Countries were driven to revolt by Spanish taxes and religious persecution. Seven northern provinces banded together and fought their way to a merchants\' republic without a king; when Antwerp fell, capital and craftsmen poured north into Amsterdam.'],
      rule:['七省联合的松散共和国,实权握在各城市的商人寡头手里,另设「执政」统领军队,权柄随战和起落,甚至两度长期空缺;宗教上相对宽容,犹太人与新教难民带着资本与手艺前来落脚。商人治国,国策围着账本转。','A loose federation of seven provinces, with real power held by urban merchant oligarchs and a stadtholder commanding the armies, his power waxing and waning with war and peace. Its relative religious tolerance drew Jews and Protestant refugees with their capital and skills — a state run by merchants, its policy built around the ledger.'],
      money:['先靠鲱鱼捕捞与波罗的海转运起家,当上欧洲的「海上马车夫」;1602年,东印度公司把远洋冒险的风险切成股份卖给公众——史上第一家把股票公开卖给公众、可自由转让的公司,连同最早的股票交易所之一诞生,阿姆斯特丹银行让汇兑清算通行欧洲。','It rose first on herring and the Baltic carrying trade, becoming Europe\'s \'wagoner of the seas\'. In 1602 the East India Company sliced the risk of ocean ventures into shares sold to the public — history\'s first company to sell freely tradable shares to the public, paired with one of the earliest stock exchanges — while the Bank of Amsterdam made payments clear smoothly across Europe.'],
      power:['它是第一个「公司国家」:东印度公司获特许可以开战、缔约、筑堡,一家公司在亚洲行使着半个主权。金融让小国迸发大能量——低息借贷使荷兰能长期供养舰队,与远大于自己的对手周旋。','Here was the first \'company-state\': the East India Company was chartered to wage war, sign treaties and build forts — a corporation exercising half a sovereignty across Asia. Finance gave a small country outsized power: cheap credit sustained its fleets for decades against far larger rivals.'],
      fall:['小国的底盘终究有限:与英国先后四次海战(1780年代的第四次几乎打断了它的海运)、与法国陆上缠斗,人口与财力被长期战争摊薄;英法两国学会了它的金融与航运打法,又以更大的体量压了过来;18世纪资本转向食利,借钱给外国比投资本国更划算。1795年法军占领,共和国落幕。','A small base could stretch only so far: four naval wars with England — the fourth, in the 1780s, nearly broke its shipping — and land wars with France thinned out its people and purse, while both rivals adopted Dutch finance and shipping methods at far greater scale. In the 18th century capital turned rentier, lending abroad rather than investing at home; French occupation in 1795 brought the republic\'s story to a close.'],
      legacy:['股份公司、证券交易所、中央银行的雏形——现代资本主义的工具箱多在这里定型;格劳秀斯的「海洋自由」学说开国际法之先河。纽约的前身,就叫新阿姆斯特丹。','The joint-stock company, the stock exchange, the prototype of a central bank — much of modern capitalism\'s toolkit was forged here, and Grotius\'s doctrine of the freedom of the seas opened the path to international law. New York began life as New Amsterdam.'] },
  d:'从西班牙治下独立的七省联合共和国,以商船队与金融创新称雄17世纪:东印度公司是史上第一家把股票公开卖给公众的公司,阿姆斯特丹是世界金融中心,伦勃朗与惠更斯同城而居。英荷战争后海权渐让于英国,但其商业制度被全世界继承。' },
{ l:'eu', s:'west', v:0, n:'法兰西', k:[[1600,0],[1680,.5],[1760,.55],[1812,.7],[1830,.5],[1870,.45],[1940,.32],[1950,.3],[2025,.3]], b:'从太阳王到拿破仑两度称霸欧陆;启蒙与大革命输出观念。',
  e:{ n:'France', b:'Twice master of the continent; exporter of Enlightenment and revolution.', d:'The Sun King\'s Versailles set the model for European courts and the philosophes\' salons incubated revolution; 1789 and Napoleon exported liberty, equality and the Code across Europe. Twice broken by Germany, France remained the political-cultural core of Europe and now co-drives the EU.', f:{ 'Peak':'1812 (Napoleon)', 'Center':'Paris', 'Figures':'Louis XIV, Voltaire, Napoleon, de Gaulle', 'Legacy':'Enlightenment, Napoleonic Code' } },
  f:{ '鼎盛':'1812年(拿破仑)', '中心':'巴黎', '人物':'路易十四、伏尔泰、拿破仑、戴高乐', '成就':'启蒙运动、《拿破仑法典》' },
  qh:{ born:['地好、人多,1700年是英格兰的三倍','Good land and, by 1700, three times the people of England'],
       rule:['一共有过五个共和国,两个帝国','Five republics and two empires, so far'],
       money:['奢侈品是被有意做成国家产业的','Luxury was deliberately built into a national industry'],
       power:['拿破仑能动员起同时代没人凑得出的军队','Napoleon could raise armies no contemporary could match'],
       fall:['殖民帝国收摊,改把力气押在一体化上','The empire closed, and the bet moved to integration'],
       legacy:['三权分立、社会契约,都从这里出去','Separation of powers and the social contract went out from here'] },
  q:{ born:['西欧最大的一块连片好地:气候温和、河流四通、耕地充足,养得起当时欧洲最多的人口。中世纪的封建割据在几百年里被王权一点点收拢,到路易十四时已是一个中央集权的大国——1700年前后法国人口约两千万,是英格兰的三倍多。','The largest single block of good land in western Europe: a mild climate, rivers running in every direction, farmland enough to feed the biggest population on the continent. Centuries of feudal fragmentation were slowly gathered up by the crown, and by the reign of Louis XIV it was a centralised great power — around 1700 France had some twenty million people, more than three times England\'s.'],
      rule:['两套制度先后主导。旧制度下是绝对君主制:王权大到近乎与国家等同——后人用「朕即国家」概括它,虽然这句话很可能不是他本人说的;凡尔赛把贵族集中到眼皮底下,行政交给出身平民的总督。1789年大革命推翻它之后,法国在共和、帝制、复辟之间反复了近百年,直到1870年后共和制才稳定下来;到今天为止,法国一共有过五个共和国和两个帝国。这段反复本身就是它给世界的教材。','Two systems, one after the other. Under the old regime it was absolute monarchy: royal power so nearly identical with the state that later writers summed it up as \'I am the state\' — a line he probably never said; a Versailles that kept the nobility under his eye, and administration handed to intendants of common birth. After the Revolution of 1789 swept that away, France swung between republic, empire and restoration for close to a century before the republic settled after 1870 — five republics and two empires in all. That very oscillation is part of what it taught the world.'],
      money:['底盘是农业,长期是欧洲的粮仓。近代以来加上三样:奢侈品与时尚(路易十四时期就有意识地把它做成国家产业)、殖民地贸易(法国是大西洋奴隶贸易的主要参与国之一,海地曾是它最赚钱的殖民地),以及19世纪后的工业。今天仍是农产品出口大国,同时靠航空航天、核电、奢侈品与旅游立足——巴黎是全世界游客最多的城市之一。','Farming was the base, and for centuries France was Europe\'s granary. To that the modern era added three things: luxury goods and fashion, deliberately built into a state industry as early as Louis XIV; colonial trade — France was one of the main participants in the Atlantic slave trade, and Haiti was its most profitable colony — and, from the nineteenth century, industry. It remains a major agricultural exporter while living on aerospace, nuclear power, luxury goods and tourism — Paris is among the most visited cities on earth.'],
      power:['人口与国家能力。大革命发明了全民征兵,拿破仑因此能动员起同时代任何君主都凑不出的军队,1812年法国势力覆盖了大半个欧洲。观念是另一种力量:自由、平等、博爱与《拿破仑法典》随军队传播,法典至今仍是欧洲、拉美与非洲许多国家民法的底本。','Population and state capacity. The Revolution invented mass conscription, which let Napoleon put armies in the field that no contemporary monarch could match, and by 1812 French power reached across most of Europe. Ideas were the other kind of strength: liberty, equality and fraternity travelled with the armies, as did the Napoleonic Code, still the basis of civil law in much of Europe, Latin America and Africa.'],
      fall:['1962年阿尔及利亚独立,是法国殖民帝国事实上的终结(海外领地至今仍在),也是国内政治的转折——为处理这场战争,戴高乐在1958年重建了权力更集中的第五共和国,这套体制沿用至今。同一时期它转向另一条路:与联邦德国和解、共同创办欧洲共同体,把国家安全与影响力寄托在一体化上,而不再是海外领地。','Algerian independence in 1962 ended the French colonial empire, and it also turned domestic politics: to deal with that war de Gaulle rebuilt the state in 1958 as a Fifth Republic with power concentrated in the presidency, and that constitution still stands. In the same years the country took another road — reconciliation with West Germany and the founding of the European Communities, placing its security and its influence in integration rather than in overseas possessions.'],
      legacy:['启蒙运动的主要现场:孟德斯鸠的三权分立、卢梭的社会契约、伏尔泰的宗教宽容,都从这里扩散出去。《人权和公民权宣言》是后世许多宪法的蓝本;《拿破仑法典》则把「法律统一、财产明确、法律面前平等」写成可以照抄的条文。米制、公制单位与米其林指南也都是法国的输出。','It was the main stage of the Enlightenment: the separation of powers, the social contract and the argument for religious tolerance all spread from here. The Declaration of the Rights of Man became a template for later constitutions, and the Napoleonic Code turned unified law, clear property rights and equality before the law into text other countries could copy. The metric system and the Michelin guide are French exports too.'] },
  d:'太阳王的凡尔赛是欧洲宫廷的样板,启蒙哲人的沙龙是革命思想的温床;1789年大革命与拿破仑战争把"自由平等"与法典输出到全欧。此后虽两度被德国击溃,仍始终居于欧洲政治文化核心,今日与德国同为欧盟双引擎。' },
{ l:'eu', s:'west', v:1, n:'瑞典帝国', k:[[1611,0],[1632,.3],[1660,.4],[1700,.33],[1721,0]], b:'一个百来万人口的北方国家,当了一百年波罗的海的主人。',
  e:{ n:'the Swedish Empire', w:'Swedish Empire', b:'A northern country of barely a million people that ran the Baltic for a century.', d:'Gustavus Adolphus inherited an empty treasury and enemies on three sides in 1611, and answered with parish conscription, copper and iron exports, and a reformed army: lighter guns that moved with the infantry, musket and pike in smaller brigades, cavalry charging home. Breitenfeld in 1631 turned the Thirty Years\' War; he died at Lützen the next year. Sweden went on to hold Finland, Estonia, Livonia and footholds in Germany. But a million people cannot sustain great-power war: Charles XII lost his army to Peter I at Poltava in 1709, and the Treaty of Nystad handed the eastern Baltic to Russia in 1721.', f:{ 'Peak':'mid-17th c.', 'Center':'Stockholm', 'Figures':'Gustavus Adolphus', 'Legacy':'Early-modern military reform, copper and iron, parish literacy' } },
  f:{ '鼎盛':'17世纪中叶', '中心':'斯德哥尔摩', '人物':'古斯塔夫二世·阿道夫', '成就':'近代早期的军事改革、铜与铁的出口、教区识字' },
  qh:{ born:['一百万人口,把人力用到极致','A million people, and every one of them counted'],
       rule:['农民自己坐在议会里,不是被代表','Peasants sat in the diet themselves, not represented'],
       money:['军队靠占领区养活,一停就撑不住','The army fed off occupied land, so it could never stop'],
       power:['把炮做轻,让它跟得上步兵','Lighter guns, so they could keep up with the infantry'],
       fall:['三百万人,要同时对付三个大国','Three million people, against three larger states at once'],
       legacy:['1814年以后,它再没有打过仗','Since 1814 it has not fought a war'] },
  q:{ born:['1611年古斯塔夫二世·阿道夫即位时,瑞典人口约一百万出头,财政拮据,三面受敌。他做的是把有限的人力用到极致:征兵按教区分摊、常年服役,不靠临时招募的雇佣兵;同时靠铜矿与铁矿的出口换现金,再用荷兰的资本与技术把矿冶做大。','When Gustavus Adolphus came to the throne in 1611 Sweden had a population of a little over a million, an empty treasury and enemies on three sides. What he did was use limited manpower to the utmost: conscription apportioned by parish with men serving long terms, rather than mercenaries hired for a campaign; and copper and iron exports brought in the cash, with Dutch capital and technique used to build the mining up.'],
      rule:['它是当时欧洲少见的、农民在议会里有独立等级的国家——瑞典议会分贵族、教士、市民、农民四个等级,农民不是被代表而是自己出席。这不等于民主,但它让征税与征兵的负担有一个可以谈判的渠道,王权因此能动员出超出国力的资源。路德宗是国教,教区同时承担登记人口、征兵与办学。','It was one of the few states in Europe where peasants formed an estate of their own in the diet — the Riksdag had four estates, nobles, clergy, burghers and peasants, and the peasants sat for themselves rather than being represented. This was not democracy, but it gave taxation and conscription a channel where they could be negotiated, and let the crown mobilise more than the country\'s size suggested. Lutheranism was the state church, and the parish did the work of registering people, raising soldiers and running schools.'],
      money:['法伦的铜矿一度供应欧洲大部分的铜,瑞典铁则以质量著称,长期是英国钢铁工业的原料来源。但它的战争开支远超本国财政,三十年战争期间绝大部分靠占领区的「战争供养」——军队在占领地征粮征税自己养自己,这是当时的通行做法;法国每年也给一笔补贴(约四十万塔勒,抵得上瑞典本国财政的四分之一,但与德意志战场的开支比只是零头),也意味着一旦停止扩张,财政就难以为继。','The copper at Falun supplied much of Europe at one point, and Swedish iron was known for its quality and long fed the English iron industry. But its wars cost far more than the country could pay: through the Thirty Years\' War much the greater part came from contributions levied on occupied territory — armies fed themselves off the land they held, the normal practice of the time — while the French subsidy, about four hundred thousand thalers a year, was worth a quarter of Sweden\'s own revenue but small beside what the German war actually cost, and it meant that once expansion stopped the finances could not hold.'],
      power:['古斯塔夫二世的军事改革被后世反复研究:更轻的火炮可以随步兵机动、火枪兵与长矛兵混编成小方阵、骑兵恢复冲击而不是骑马放枪。1631年布赖滕费尔德一战击溃帝国军,把三十年战争的走向改了过来;他本人1632年战死于吕岑。此后瑞典在波罗的海周边取得芬兰、爱沙尼亚、利沃尼亚与德意志北部的据点,波罗的海一度接近「瑞典的内湖」。','Gustavus Adolphus\'s military reforms have been studied ever since: lighter guns that could move with the infantry, musket and pike combined in smaller brigades, cavalry charging home rather than firing from the saddle. At Breitenfeld in 1631 he broke the imperial army and turned the course of the Thirty Years\' War; he was killed at Lützen the next year. Sweden went on to hold Finland, Estonia, Livonia and footholds in northern Germany, and the Baltic came close to being a Swedish lake.'],
      fall:['根本问题是体量:到1700年瑞典全帝国约三百万人,而俄国有两千万、波兰有九百多万,它还得同时对付俄国、丹麦与萨克森-波兰三家。1700年起的大北方战争里,卡尔十二世前期连战连捷,1709年在波尔塔瓦被彼得一世击溃,野战主力尽失;此后节节败退,1721年《尼斯塔德和约》割让波罗的海东岸各省给俄国。俄国由此获得出海口,而瑞典退回北欧,从此不再是大国。','The underlying problem was size: by 1700 the whole Swedish empire had about three million people against Russia\'s twenty million and Poland\'s nine, and it had to face Russia, Denmark and Saxony-Poland at once. In the Great Northern War from 1700 Charles XII won repeatedly at first, then lost his field army to Peter I at Poltava in 1709; the retreat went on until the Treaty of Nystad in 1721 handed the eastern Baltic provinces to Russia. Russia got its outlet to the sea, and Sweden went back to being a northern country rather than a power.'],
      legacy:['军事上的那套改革被普鲁士与后来的欧洲各国吸收,是近代军队的源头之一。更长远的是教区办学:17世纪起路德宗教会要求教民能自己读《教理问答》,由教区逐户查验,到18世纪瑞典能读的人口比例已高于欧洲多数地区——这与后来北欧的教育与社会模式有直接关系。但1721年并没有立刻带来和平:此后瑞典1741、1788、1808年三次对俄开战,1809年丢掉芬兰——那是它领土的三分之一。真正的分水岭是1814年,从那以后它再没有打过仗,是近代欧洲和平持续最久的国家;长期奉行的不结盟到2024年结束,瑞典加入了北约。','Its military reforms were absorbed by Prussia and by Europe generally, and are one of the sources of the modern army. Longer-lasting was the parish school: from the seventeenth century the Lutheran church required people to be able to read the catechism for themselves, and checked household by household, so that by the eighteenth century the share of Swedes who could read was above most of Europe — which bears directly on later Nordic education and social models. But 1721 did not bring peace at once: Sweden went to war with Russia again in 1741, 1788 and 1808, and in 1809 lost Finland — a third of its territory. The real dividing line is 1814, after which it has not fought at all, the longest unbroken peace of any country in modern Europe; the non-alignment that followed ended in 2024, when Sweden joined NATO.'] },
  d:'1611年古斯塔夫二世即位时瑞典只有一百万出头的人口。他按教区征兵、以铜铁出口换现金,并推行军事改革——轻型火炮随步兵机动、火枪长矛混编小方阵。1631年布赖滕费尔德击溃帝国军,改变三十年战争走向,他本人次年战死。此后瑞典握有芬兰、爱沙尼亚、利沃尼亚与德意志北部据点。但体量终究撑不住:1709年波尔塔瓦败于彼得一世,1721年《尼斯塔德和约》把波罗的海东岸割给俄国。' },
{ l:'eu', s:'west', v:2, n:'大英帝国·英国', k:[[1585,0],[1620,.15],[1700,.4],[1763,.6],[1815,.85],[1870,1],[1914,.9],[1945,.5],[1960,.3],[2025,.25]], b:'工业革命发源地,19世纪的全球霸主,统治世界四分之一人口。',
  e:{ n:'British Empire', b:'Cradle of the Industrial Revolution; the 19th century\'s global hegemon.', d:'The island state rose through navy, commerce and parliament, defeating Spain, Holland and France to command the oceans; it lit the Industrial Revolution and became the world\'s workshop and the empire on which the sun never set. Two world wars drained it, yet English, common law and its trade-finance rules remain the world\'s base protocols.', f:{ 'Peak':'1870–1914', 'Center':'London', 'Figures':'Elizabeth I, Watt, Victoria, Churchill, William Shakespeare, Florence Nightingale', 'Legacy':'Industrial Revolution, parliamentary politics, a global financial system' } },
  f:{ '鼎盛':'1870—1914年', '中心':'伦敦', '人物':'伊丽莎白一世、瓦特、维多利亚、丘吉尔、莎士比亚、南丁格尔', '成就':'工业革命、议会政治、全球金融体系' },
  qh:{ born:['这个帝国是生意做出来的','This empire was built as a business'],
       rule:['几千名文官,管着三亿人的印度','A few thousand officials ran India of three hundred million'],
       money:['全球贸易的账,记在英镑上','World trade was kept in pounds sterling'],
       power:['三样凑齐,一个小岛撬动了全球','Three things together let one island move the world'],
       fall:['1956年苏伊士,确认霸权已经易手','Suez in 1956 confirmed the crown had changed hands'],
       legacy:['议会制被广泛移植,还有足球','Parliaments were transplanted widely, and so was football'] },
  q:{ born:['岛国土地有限,机会在海上;击败无敌舰队后,先出海的不是军队而是私掠船和特许公司。1600 年 12 月 31 日,东印度公司拿到女王的特许状,垄断好望角以东、麦哲伦海峡以西的英国贸易——差不多半个地球。它一开始只是一门生意,1609 年续状里还写着一条:要是连续三年不赚钱,特权就取消。国家是后来才跟上去的。','A small island with limited land looked to the sea, and after the Armada was beaten it was not armies that went first but privateers and chartered companies. On 31 December 1600 the East India Company received its charter: a monopoly of English trade everywhere east of the Cape of Good Hope and west of the Straits of Magellan — something close to half the world. It began as a business and nothing more; the renewal of 1609 still carried a clause voiding its privileges if the trade failed to pay for three years running. The state came up behind it.'],
      rule:['本土是议会主权;海外分级而治:直辖殖民地、保护国、自治领各不相同,靠当地精英代理。印度那一头,印度文官系统的正式官员只有一千出头,管着三亿多人——平均一个人管三十万。1853 年起改成考试录用,听上去公平,但考场只设在伦敦、每年八月考一次:要当印度的官,先得漂洋过海去英国。到 1947 年分治时,980 名文官里印度人已有 512 名。','At home, parliamentary sovereignty; abroad, a graded empire of crown colonies, protectorates and dominions run through local elites. In India the covenanted Indian Civil Service numbered a little over a thousand men and administered more than three hundred million people — about three hundred thousand each. From 1853 entry was by competitive examination, which sounds fair until you notice the examination was held only in London, once a year in August: to govern India you first had to cross the world to England. By partition in 1947, 512 of the 980 officers were Indian.'],
      money:['先是大西洋贸易与转口;工业革命后出口制成品、进口原料;伦敦金融城的保险、汇票和国债,把全球贸易的账记在英镑上。路线转弯的标志是 1846 年:1815 年起的《谷物法》给进口粮食加税,护住了地主的收成,代价是全国人的饭都变贵、工厂也难做;爱尔兰大饥荒逼到眼前,首相皮尔顶着自己党内的反对把它废掉——英国从此走上自由贸易这条路。','First the Atlantic and carrying trades; after industrialisation, manufactures out and raw materials in; and the City of London — insurance, bills and bonds — kept the books of world trade in sterling. The turn came in 1846. The Corn Laws of 1815 had taxed imported grain, protecting the rents of landowners at the cost of dearer food for everyone and a harder time for manufacturing; with the Irish famine at the door, Prime Minister Robert Peel forced repeal through against his own party, and Britain set out on free trade.'],
      power:['工业革命的先发优势(煤与蒸汽机)、皇家海军的制海权、能比对手多借几倍钱的国债体系,三样合起来,小岛撬动了全球。还有一件今天听着不可思议的事:力量并不都握在国家手里。1670 年前后,查理二世把筑城、统兵、结盟、宣战媾和乃至审案判刑的权力一并给了东印度公司;它鼎盛时养着三个管区的军队、约二十六万人,有些年份是英国正规军的两倍。','First-mover industry in coal and steam, naval command of the seas, and a bond market that could borrow several times more than any rival: together they let a small island lever the globe. And one thing that sounds impossible now — not all of that power was held by the state. Around 1670 Charles II granted the East India Company the right to hold forts and troops, to make alliances, to make war and peace, and to try and sentence men in its own courts; at its height it kept three presidency armies of some 260,000 soldiers, in certain years twice the size of the British Army.'],
      fall:['帝国的落幕:两次世界大战把最大的债权国打成债务国;殖民地独立运动风起云涌,1947 年印度独立抽走基石;1956 年苏伊士危机确认霸权已经易手。债务这件事有个很具体的尾巴:1946 年英国向美国借了 37.5 亿美元、年息 2%,分五十年还,结果中间几年还不上停付过,最后一笔拖到 2006 年 12 月 29 日才付清——那一天离二战结束已经六十一年。','The end of the empire: two world wars turned the great creditor into a debtor; independence movements swept the colonies, and the loss of India in 1947 pulled the keystone; Suez in 1956 confirmed that command had passed elsewhere. The debt had a very concrete tail: in 1946 Britain borrowed 3.75 billion dollars from the United States at two per cent over fifty years, suspended payment in several years when it could not manage, and made the last one on 29 December 2006 — sixty-one years after the war ended.'],
      legacy:['英语成为全球通用语;世界约三分之一的人生活在普通法体系下;议会制被广泛移植;还有工业革命本身。以及足球:1863 年 12 月,英格兰足球总会在伦敦把各家学校各踢各的规矩统一成一套成文规则,由首任秘书莫利执笔。当时最大的分歧是能不能踢对方小腿、能不能抱球跑——主张能踢的那一派在最后一次会上没来,足球和橄榄球就此分了家。','English as the global tongue; the common law under which a third of the world lives; parliamentary government widely transplanted; and the Industrial Revolution itself. And football: in December 1863 the Football Association in London settled the differing rules of the various schools into one written code, drafted by its first secretary, Ebenezer Morley. The sharpest disagreements were over whether you might kick an opponent in the shins and whether you might run holding the ball — the party in favour of kicking did not turn up to the final meeting, and football and rugby went their separate ways from there.'] },
  d:'岛国以海军、商业与议会制度后来居上:先后击败西班牙、荷兰、法国而独占海洋;18世纪中叶率先点燃工业革命,一个世纪内成为"世界工厂"与日不落帝国。两次大战耗尽国力、殖民地纷纷独立,但英语、普通法与其建立的贸易金融规则,至今仍是世界的底层协议。' },
{ l:'eu', s:'west', v:1, n:'勃兰登堡·普鲁士', k:[[1415,0],[1500,.08],[1618,.12],[1648,.06],[1701,.18],[1740,.28],[1786,.36],[1815,.42],[1864,.46],[1866,0]], b:'欧洲最穷的一块沙地,靠收留别人赶走的人一点点变强,最后由它把德意志拼成一个国家。',
  d:'勃兰登堡的土是沙,人称它「神圣罗马帝国的沙罐」——没有矿、没有海港、没有大河出海口,1415 年霍亨索伦家族买下这块选侯领时,它在帝国里排不上号。三十年战争(1618—1648)又把这里打空,部分地区人口损失过半。转机来自两件事:一是 1685 年的波茨坦敕令——法国把新教徒赶出国境,勃兰登堡张开手接住,几年里两万多胡格诺难民进来,他们带来纺织、玻璃、金银细工的手艺,到 1700 年前后,柏林有五分之一的人是法国后裔;二是把国家办成一支军队的后勤部:税收、文官、征兵三件事绑在一起,养出与国土面积极不相称的常备军。1701 年选侯自称「在普鲁士的国王」,1740 年起腓特烈二世三夺西里西亚,把这个邦推成欧洲五强之一;1866 年普奥战争之后,德意志的重心彻底落到柏林这一边。',
  e:{ n:'Brandenburg-Prussia', w:'Brandenburg-Prussia', b:'The poorest sandy corner of Europe grew strong by taking in the people others drove out — and ended up assembling Germany.', d:'The soil of Brandenburg is sand, and the country was known as the sandbox of the Holy Roman Empire — no ore, no seaport, no river mouth. When the Hohenzollerns bought the electorate in 1415 it counted for little. The Thirty Years\' War then emptied it, with some districts losing more than half their people. Two things turned it around. One was the Edict of Potsdam in 1685: as France expelled its Protestants, Brandenburg opened its doors, and more than twenty thousand Huguenots arrived within a few years, bringing textiles, glass and fine metalwork — by about 1700 a fifth of Berlin had French ancestry. The other was running the state as the supply department of an army: taxation, civil service and conscription tied into one machine, supporting the fourth largest standing army in Europe, wildly out of proportion to a state ranked thirteenth in population. In 1701 the elector styled himself King in Prussia; from 1740 Frederick II took Silesia three times over and pushed the state into the first rank of European powers; and after the war of 1866 the centre of gravity in Germany lay decisively with Berlin.', f:{ 'Peak':'Frederick II (1740—1786)', 'Center':'Berlin; Konigsberg', 'Figures':'Frederick II', 'Legacy':'The Edict of Potsdam; a state run as an army\'s commissariat' } },
  f:{ '鼎盛':'腓特烈二世(1740—1786)', '中心':'柏林、柯尼斯堡', '人物':'腓特烈二世', '成就':'波茨坦敕令收容难民、把国家办成军队的后勤部' },
  qh:{ born:['一块没有矿也没有海港的沙地','A patch of sand with no ore and no harbour'],
       rule:['税收、文官、征兵,拧成同一台机器','Taxes, clerks and conscription, geared into one machine'],
       money:['别人赶走的手艺人,这里全要','The craftsmen others expelled were all taken in'],
       power:['国土配不上这支军队,反过来也一样','An army too big for its country, and it knew it'],
       fall:['它没有亡,是把自己装进了德国','It did not fall; it packed itself into Germany'],
       legacy:['最穷的那个邦,最后拼起了德意志','The poorest of them was the one that assembled Germany'] },
  q:{ born:['勃兰登堡在中欧的沙质平原上,没有矿藏、没有海港、没有通海的大河,当时的人叫它「神圣罗马帝国的沙罐」。1415 年霍亨索伦家族花钱买下这块选侯领,在帝国的几十个诸侯里毫不起眼。三十年战争把它彻底打空:1618 到 1648 年间,部分地区人口损失过半,村庄整片消失。它的起点不是资源,是一片需要重新填人的空地。','Brandenburg lay on the sandy plain of central Europe with no ore, no seaport and no river running to the sea; contemporaries called it the sandbox of the Holy Roman Empire. The Hohenzollerns bought the electorate in 1415, and among the empire\'s scores of princes it counted for nothing. The Thirty Years\' War then emptied it: between 1618 and 1648 some districts lost more than half their people and whole villages disappeared. Its starting point was not resources but empty ground that needed refilling.'],
      rule:['做法是把国家办成军队的后勤部:税收、文官与征兵绑成一台机器,官员按能力而不是出身选拔,土地贵族(容克)则被吸收进军官团——你出人当兵、当官,我保住你在乡下的地位。这套安排让一个中等大小的邦,养得起一支欧洲第四大的常备军;后来有人反过来说,不是这个国家有一支军队,是这支军队有一个国家。','The method was to run the state as the commissariat of an army: taxation, civil service and conscription geared into one machine, officials chosen on competence rather than birth, and the landed nobility — the Junkers — absorbed into the officer corps in a bargain that kept their standing in the countryside. It let a state thirteenth in Europe by population keep the fourth largest army on the continent. It was later said that this was not a country with an army but an army with a country.'],
      money:['缺人比缺钱更要命,所以它做的是把人请进来。1685 年法国废除南特敕令、驱赶新教徒,勃兰登堡当年就发布波茨坦敕令,承诺免税、给房、承认行会资格;几年内两万多胡格诺人迁入,带来纺织、染色、玻璃与金银细工,到 1700 年前后占了柏林人口的五分之一。此后波希米亚人、萨尔茨堡人、荷兰的排水工也一批批被招来——这个国家最重要的一笔投资,是别人赶走的人。','Short of people more than of money, it set about importing them. When France revoked the Edict of Nantes in 1685 and drove out its Protestants, Brandenburg issued the Edict of Potsdam that same year, promising tax relief, housing and recognition of guild qualifications; more than twenty thousand Huguenots came within a few years, bringing weaving, dyeing, glass and fine metalwork, and by about 1700 a fifth of Berlin had French ancestry. Bohemians, Salzburgers and Dutch drainage engineers followed in later waves. The state\'s single best investment was the people other countries expelled.'],
      power:['军队与国土的比例长期失衡,这既是它的本钱也是它的处境:打得起仗,却经不起一场大败。1740 年腓特烈二世即位后立刻夺取奥地利的西里西亚,又在七年战争里以一国对多国,几次濒临崩溃,靠对手内部的变故脱身。他本人白天调兵、晚上吹长笛写法文诗,和伏尔泰通信多年后闹翻——一个把「开明」与「军营」同时做到极致的人。','The permanent mismatch between army and territory was both its capital and its predicament: it could afford to fight, but not to lose badly. Frederick II seized Silesia from Austria immediately on his accession in 1740, then in the Seven Years\' War held out alone against several great powers, more than once close to collapse and saved by a change of ruler among his enemies. He drilled troops by day and played the flute and wrote French verse by night, and corresponded with Voltaire for years before they fell out — a man who pushed both enlightenment and the barracks to their limits.'],
      fall:['这条带的结束不是灭亡,是并入。1806 年耶拿一役被拿破仑打垮,几乎亡国,随后是彻底改革:废农奴、改军制、办柏林大学。1815 年它拿到莱茵兰,重新排进欧洲五强;1866 年普奥战争把奥地利排除出德意志事务,1871 年德意志帝国在凡尔赛宣告成立,普鲁士国王成了德意志皇帝——这个邦把自己装进了一个更大的国家,而那个国家的首都还是柏林。','This band ends not in destruction but in absorption. Crushed by Napoleon at Jena in 1806 and nearly extinguished, the state remade itself: serfdom abolished, the army reorganised, the University of Berlin founded. In 1815 it gained the Rhineland and was back among the great powers; the war of 1866 shut Austria out of German affairs, and in 1871 the German Empire was proclaimed at Versailles with the king of Prussia as its emperor. The state packed itself into a larger country — whose capital was still Berlin.'],
      legacy:['两样东西留了下来,而且方向相反。一样是把行政当成专业:考试选官、档案留痕、按章办事,这套后来被许多国家学去,今天所谓「官僚体系」的底子里有它的一份。另一样是把军队摆在国家中心的传统,20 世纪把德国与欧洲拖进了两场灾难;1947 年盟国管制委员会下令正式取消普鲁士这个邦,理由写的是它「历来是德国军国主义与反动的载体」。一个从沙地上起家、靠收留难民壮大的邦,最后是被人用法令从地图上抹掉的。','Two legacies survive, pointing opposite ways. One is administration as a profession — entry by examination, decisions on record, business by the rulebook — a model many states later copied, and part of the foundation of what is now simply called bureaucracy. The other is the habit of placing the army at the centre of the state, which in the twentieth century helped drag Germany and Europe into two catastrophes. In 1947 the Allied Control Council formally abolished Prussia as a state, giving as its reason that it had long been a bearer of militarism and reaction. A country that began on sand and grew by taking in refugees was in the end wiped off the map by decree.'] } },
{ l:'eu', s:'west', v:1, n:'德意志', k:[[1866,0],[1880,.4],[1914,.6],[1919,.3],[1941,.6],[1945,.08],[1975,.35],[2025,.35]], b:'统一后钢铁与科学冠绝欧洲,两次大战的策源地,战后经济中枢。',
  e:{ n:'Germany', b:'Unified in 1871; industry and science supreme, twice the epicenter of world war.', d:'Bismarck unified Germany through three wars; the new empire\'s steel, chemicals and universities led Europe. The bid for "a place in the sun" ignited two world wars and two defeats; postwar manufacturing rebuilt it into the EU\'s economic core.', f:{ 'Peak':'early 20th c.', 'Center':'Berlin', 'Figures':'Bismarck, Einstein (German science)', 'Legacy':'Modern university, chemical industry, social insurance' } },
  f:{ '鼎盛':'20世纪初(工业与科学)', '中心':'柏林', '人物':'俾斯麦、爱因斯坦(德语科学圈)', '成就':'现代大学、化学工业、社会保险制度' },
  qh:{ born:['统一是自上而下、用打仗完成的','Unification came from the top, and by war'],
       rule:['后来特意设计了防止重蹈覆辙的机制','Later it deliberately designed safeguards against repeating itself'],
       money:['一堆中小企业,在极窄的领域做世界第一','Many small firms, each first in the world at one narrow thing'],
       power:['1933年之后,这个中心自己散掉了','After 1933 that centre scattered itself'],
       fall:['1990年,墙倒了,两边合成了一个','In 1990 the wall was gone, and the two became one'],
       legacy:['今天全世界约一半人,靠一项化学反应吃饭','About half the world is fed by one chemical reaction'] },
  q:{ born:['中欧长期是几百个邦国的拼图,神圣罗马帝国有名无实。19世纪工业化与铁路把这片市场连成一体,关税同盟先做了经济统一;1864至1871年普鲁士打了三场战争(对丹麦、奥地利、法国),1871年在凡尔赛宫宣布德意志帝国成立。统一是自上而下、用军事完成的,这一点影响了此后几十年的走向。','Central Europe was for centuries a patchwork of hundreds of states under a Holy Roman Empire that existed mostly on paper. In the nineteenth century industry and railways knitted the market together and a customs union achieved economic unification first; then Prussia fought three wars between 1864 and 1871 — against Denmark, Austria and France — and the German Empire was proclaimed at Versailles in 1871. Unification came from above and by force of arms, and that shaped the decades that followed.'],
      rule:['帝国时期是君主制加议会的混合体:有男性普选产生的国会,但首相只对皇帝负责。1918年战败后建立魏玛共和国,是当时最先进的宪法之一,却在经济崩溃与街头暴力中失效,1933年被纳粹政权取代。纳粹把这套体制推向系统性的迫害与侵略战争:约六百万犹太人在大屠杀中遇难,二战造成数千万人死亡。1949年后西德重建为联邦制议会民主国家,并特意设计了防止重蹈覆辙的机制;如何面对这段历史本身,后来成了德国国民教育的一部分;1990年两德统一后沿用这套体制。','The empire mixed monarchy with parliament: a Reichstag elected by universal male suffrage, but a chancellor answerable only to the emperor. After defeat in 1918 the Weimar Republic was founded on one of the most advanced constitutions of its day, and it failed amid economic collapse and street violence, giving way to Nazi rule in 1933. The Nazi state drove that system into systematic persecution and a war of aggression: some six million Jews were murdered in the Holocaust, and the Second World War killed tens of millions. From 1949 West Germany was rebuilt as a federal parliamentary democracy with safeguards designed expressly against a repeat, and how to face that history became part of German schooling in its own right, and that framework carried over when the country reunited in 1990.'],
      money:['以制造业为核心,一百多年没变过:化学、机械、汽车、电机。它的特点是「隐形冠军」——大量中小企业在极窄的细分领域做到世界第一,而不是只有几家巨头。双元制职业教育(学生一半时间在企业、一半在学校)支撑着这套产业结构,也是许多国家想学的对象。','Manufacturing has been the core for more than a century: chemicals, machinery, cars, electrical equipment. Its distinguishing feature is the hidden champion — a great many mid-sized firms that lead the world in a very narrow niche, rather than a handful of giants. The dual system of vocational training, in which students split their time between a company and a school, underpins that structure and is widely studied abroad.'],
      power:['19世纪末它把科学变成了产业:世界上第一批研究型大学在这里成型,化学与物理长期领先,1901至1932年间德语区拿到的诺贝尔奖数量居世界之首——1933年后大批犹太裔与异见学者被驱逐或流亡,这个中心也随之散掉了。俾斯麦在1880年代建立的疾病、工伤与养老保险,是世界上最早的国家社会保险制度,后来被各国广泛效仿。','At the end of the nineteenth century it turned science into industry: the first research universities took shape here, chemistry and physics led the world, and between 1901 and 1932 the German-speaking world took more Nobel prizes than anywhere else — and after 1933 the expulsion and flight of Jewish and dissenting scholars scattered that centre. The sickness, accident and old-age insurance Bismarck introduced in the 1880s was the world\'s first state social insurance, and was widely copied afterwards.'],
      fall:['1990年10月两德统一,是最近一次大的转折。前一年柏林墙被推倒,东德在几个月内并入联邦德国;此后是长达数十年、耗资上万亿欧元的东部重建,以及两边生活水平与政治态度长期存在的落差。同时,统一后的德国成为欧盟事实上的经济中心,欧元区的许多规则由此定型。','Reunification in October 1990 was the last great turning point. The Berlin Wall had come down the year before, and within months East Germany joined the Federal Republic; what followed was decades of reconstruction in the east costing well over a trillion euros, and a gap in living standards and political attitudes that has persisted. Reunified Germany also became the effective economic centre of the European Union, and much of the euro area\'s rulebook was shaped accordingly.'],
      legacy:['现代研究型大学的模式出自这里,今天全世界的博士制度、实验室与学术研讨课都能追到19世纪初的柏林。合成染料与化肥开启了现代化学工业——哈伯—博施法合成氨,今天全世界约一半的人靠它生产的化肥养活;同一项技术也让炸药可以大规模制造。国家社会保险、双元制职业教育同样被反复借鉴。','The modern research university comes from here; the doctorate, the laboratory and the seminar as they exist worldwide trace back to early nineteenth-century Berlin. Synthetic dyes and fertilisers opened the modern chemical industry — the Haber-Bosch process for fixing nitrogen feeds roughly half the world\'s people today through the fertiliser it makes — and the same chemistry made explosives producible at scale. State social insurance and dual vocational training have likewise been borrowed again and again.'] },
  d:'俾斯麦以三场战争完成统一,新帝国的钢铁、化工与大学迅速冠绝欧洲;但为争夺"阳光下的地盘"两度引爆世界大战,也两度战败分裂。战后西德以制造业重新崛起,统一后的德国是欧盟的经济中枢。' },
{ l:'eu', s:'west', v:2, n:'现代欧洲诸国', k:[[1815,0],[1848,.22],[1900,.32],[1945,.28],[1990,.4],[2025,.4]], b:'维也纳会议之后的欧洲民族国家:意大利、西班牙、荷兰、北欧、中东欧……今天多数是欧盟成员。',
  e:{ n:'Modern European states', w:'History of Europe', b:'The nation-states of Europe after the Congress of Vienna — Italy, Spain, the Netherlands, the Nordics, Central and Eastern Europe — most of them now in the European Union.', d:'This band gathers the European states that do not have a band of their own: after 1815 the map of Europe was redrawn again and again — Belgium (1830), a united Italy (1861), Norway (1905), and in 1918 a whole row of new republics from the wreck of the Austrian, Russian and German empires. Between the wars several turned to dictatorship, and the Second World War left the continent divided; the west rebuilt on the Rome treaties of 1957 and the east lived under Soviet-backed rule until 1989. The European Union of 1993 and its enlargement to the east in 2004 knit most of the continent into one economic and political space, and the euro is now the money of twenty-one of its members (as of 2026). Britain, France, Germany and Russia keep their own bands; this one is for everybody else.', f:{ 'Peak':'20th c. to today', 'Centre':'Rome, Madrid, Vienna, Stockholm, Warsaw, Amsterdam', 'Figures':'Giuseppe Garibaldi, Marie Curie, Alfred Nobel', 'Legacy':'the nation-state map of Europe, the European Union, the euro, the Nobel Prizes' } },
  f:{ '鼎盛':'20世纪至今', '中心':'罗马、马德里、维也纳、斯德哥尔摩、华沙、阿姆斯特丹', '人物':'加里波第、玛丽·居里、诺贝尔', '成就':'欧洲的民族国家地图、欧洲联盟、欧元、诺贝尔奖' },
  qh:{ born:['1815 年之后,地图一次次重画','After 1815 the map was redrawn again and again'],
       rule:['二十七个国家,一张桌子上做决定','Twenty-seven countries deciding at one table'],
       money:['二十一个国家用同一种钱','Twenty-one countries use the same money'],
       power:['两次大战都在这里打,打完就联合','Two world wars fought here, then union'],
       fall:['南斯拉夫打散了,捷克斯洛伐克和平分手','Yugoslavia broke up in war, Czechoslovakia in peace'],
       legacy:['每年十二月,斯德哥尔摩发奖','Every December, prizes are handed out in Stockholm'] },
  q:{ born:['拿破仑战争之后,此后一百年里民族国家一个个冒出来:1830 年比利时独立,1861 年意大利统一,1871 年德国统一,1905 年挪威和平脱离瑞典。1918 年第一次世界大战结束,奥匈、俄罗斯、德意志三个欧洲帝国倒下,1917—1918 年间波兰、捷克斯洛伐克、芬兰、波罗的海三国等一整排新国家出现在地图上。这条色带收的是没有自己色带的欧洲国家:意大利、西班牙、荷兰、北欧、中东欧、巴尔干与希腊。','In the century after Napoleon nation-states appeared one after another: Belgium in 1830, a united Italy in 1861, a united Germany in 1871, Norway leaving Sweden peacefully in 1905. When the First World War ended in 1918 the Austrian, Russian and German empires of Europe fell, and in 1917-1918 a whole row of new states — Poland, Czechoslovakia, Finland, the three Baltic republics — came onto the map. This band gathers the European countries without a band of their own: Italy, Spain, the Netherlands, the Nordics, Central and Eastern Europe, the Balkans and Greece.'],
      rule:['这些国家今天大多是议会民主国家,但走到这一步都不容易:意大利 1922 年起被墨索里尼统治二十年,西班牙经过 1936—1939 年的内战之后佛朗哥独裁到 1975 年,葡萄牙的独裁持续到 1974 年,希腊 1967—1974 年是军政府;中东欧各国 1945 年后在苏联的控制下,直到 1989 年才纷纷改变。1957 年六国签订《罗马条约》建立欧洲经济共同体,1993 年变成欧洲联盟,2004 年一次接纳十个中东欧与地中海国家——今天二十七个成员国把关税、农业、竞争规则和一部分外交事务放到布鲁塞尔的一张桌子上决定,这是历史上少见的主权自愿让渡。','Most of these countries are parliamentary democracies today, but few got there easily: Italy was ruled by Mussolini for twenty years from 1922, Spain came out of the civil war of 1936-1939 into Franco\'s dictatorship until 1975, Portugal\'s dictatorship lasted until 1974, Greece had a military junta from 1967 to 1974; the countries of Central and Eastern Europe lived under Soviet control after 1945 and changed only in 1989. In 1957 six states signed the Treaty of Rome and set up the European Economic Community, which became the European Union in 1993 and took in ten Central European and Mediterranean countries at once in 2004 — today twenty-seven members decide tariffs, farming, competition rules and part of their foreign policy at one table in Brussels, a rare voluntary pooling of sovereignty.'],
      money:['这一片是工业革命之后世界上最富的地区之一,但富得不平均:荷兰、比利时、北欧和意大利北部很早就工业化,伊比利亚、巴尔干和中东欧要晚得多。二战后西欧靠马歇尔计划与共同市场重建,「经济奇迹」的说法在意大利、西德都用过;北欧走出一条高税收、高福利的路,瑞典、丹麦、挪威长期排在人类发展指数的前列。1999 年欧元问世、2002 年纸币硬币开始流通,到 2026 年有二十一个国家用同一种钱(保加利亚 2026 年初刚加入)——但不是全部二十七国,丹麦、瑞典、波兰、捷克等还用自己的货币。','This is one of the richest parts of the world since the industrial revolution, but unevenly so: the Netherlands, Belgium, the Nordics and northern Italy industrialised early, Iberia, the Balkans and Central-Eastern Europe much later. After the war the west rebuilt on the Marshall Plan and the common market, and Italy and West Germany both spoke of an economic miracle; the Nordics took a road of high taxes and generous welfare, and Sweden, Denmark and Norway have long stood near the top of the human development index. The euro was born in 1999 and its notes and coins came into use in 2002; twenty-one countries use it as of 2026, Bulgaria having joined at the start of that year — not all twenty-seven, for Denmark, Sweden, Poland and the Czech Republic among others keep their own currencies.'],
      power:['两次世界大战都以这片土地为主战场,几乎每个国家都被打过或占领过——比利时两次被德军穿过,波兰 1939 年被德苏瓜分,荷兰、挪威、希腊、南斯拉夫都在 1940—1941 年间沦陷。战后西欧各国选择用条约把彼此绑在一起,让战争在成员之间「不只是不可想象,而且在物质上不可能」,这句话出自 1950 年的舒曼宣言。1949 年成立的北约把大多数西欧国家和美国拴在一个防御同盟里,冷战结束后中东欧各国也陆续加入。','Both world wars were fought mainly on this ground, and almost every country was invaded or occupied — Belgium was crossed by German armies twice, Poland was partitioned between Germany and the Soviet Union in 1939, and the Netherlands, Norway, Greece and Yugoslavia all fell in 1940-1941. After the war the western states chose to bind themselves together by treaty so that war between members would be, in the words of the Schuman Declaration of 1950, not merely unthinkable but materially impossible. NATO, founded in 1949, tied most of Western Europe to the United States in one defensive alliance, and after the Cold War the Central and Eastern European states joined it too.'],
      fall:['1989 年柏林墙倒塌后,东欧的政权在几个月里接连更替,1991 年南斯拉夫解体引发了当时欧洲二战后最惨烈的战争(波黑战争 1992—1995),捷克斯洛伐克则在 1993 年和平地一分为二。2020 年英国离开欧盟,是第一个退出的成员国;2022 年俄乌战争爆发,芬兰、瑞典放弃了长期的中立,先后加入北约。','After the Berlin Wall fell in 1989 the governments of Eastern Europe changed one after another within months; the break-up of Yugoslavia from 1991 brought what was then the worst war in Europe since 1945, in Bosnia in 1992-1995, while Czechoslovakia split peacefully in two in 1993. In 2020 Britain left the European Union, the first member ever to do so; after the war in Ukraine began in 2022, Finland and Sweden gave up their long neutrality and joined NATO.'],
      legacy:['今天世界地图上「一个民族一个国家」的画法,大半是这两百年在欧洲定型、再传到各大洲去的。诺贝尔 1895 年立遗嘱设奖,1901 年起每年十二月在斯德哥尔摩(和平奖在奥斯陆)颁发;玛丽·居里生于华沙、成名于巴黎,是第一个两次获诺贝尔奖的人。这一片留给世界的还有:奥运会的复兴(1896 年雅典)、国际红十字会(日内瓦)、以及从威尼斯到布拉格那些整座列入世界遗产的老城。','The way the world map is drawn today — one nation, one state — largely took shape in Europe over these two centuries and was carried to every continent. Alfred Nobel wrote his will in 1895, and since 1901 the prizes have been handed out every December in Stockholm, the peace prize in Oslo; Marie Curie, born in Warsaw and famous in Paris, was the first person to win two. The region also gave the world the revived Olympic Games (Athens, 1896), the International Red Cross (Geneva), and the old towns from Venice to Prague that are listed whole as World Heritage.'] },
  d:'维也纳会议后重画的欧洲:比利时 1830、意大利 1861 独立与统一,1918 年三大帝国倒下后一排新国家出现。两次大战后西欧以 1957 年罗马条约起步走向一体化,东欧 1989 年转向,1993 年欧盟成立、2004 年东扩;2026 年时二十一国用欧元。英、法、德、俄各有自己的色带,这一条收其余的欧洲国家。' },
{ l:'eu', s:'west', v:0, n:'俄罗斯·苏联', k:[[1480,0],[1721,.4],[1815,.55],[1917,.42],[1945,.8],[1980,.85],[1991,.4],[2025,.35]], b:'横跨欧亚的陆上帝国;苏联时期与美国两极对峙近半个世纪。',
  e:{ n:'Russia / USSR', w:'Soviet Union', b:'The Eurasian land empire; superpower rival of America for half a century.', d:'Muscovy shed the Golden Horde and expanded to the Pacific; Peter the Great forced westernization. After 1917 the planned economy industrialized at speed, broke the Nazi war machine, and split the world with America for forty years until the 1991 collapse.', f:{ 'Peak':'1945–1980', 'Center':'Moscow, St. Petersburg', 'Figures':'Peter the Great, Catherine II, Lenin, Stalin, Dmitri Mendeleev', 'Legacy':'First satellite, first human in space' } },
  f:{ '鼎盛':'1945—1980年(超级大国)', '中心':'莫斯科、圣彼得堡', '人物':'彼得大帝、叶卡捷琳娜、列宁、斯大林、门捷列夫', '成就':'首颗人造卫星、首次载人航天' },
  qh:{ born:['从别人的附庸起家,一路推到太平洋','It began as a vassal and ended at the Pacific'],
       rule:['动员战争高效,做消费品长期低效','Superb at mobilising for war, poor at making goods'],
       money:['油价一涨就好过,一跌就难过','When oil rose it was comfortable; when it fell, not'],
       power:['拿破仑和希特勒,都在这片土地上耗光了','Both Napoleon and Hitler burned their armies on this land'],
       fall:['1991年,十五个共和国各走各的','In 1991 fifteen republics went their own way'],
       legacy:['国际空间站至今还在用它的飞船','The space station still flies its spacecraft'] },
  q:{ born:['莫斯科大公国从蒙古金帐汗国的附庸起家,1476 年停止向汗纳贡,1480 年乌格拉河对峙后再无人能约束它,自此向四方扩张。东面几乎没有对手:西伯利亚人口稀少,毛皮商队与哥萨克在一百多年里推进到太平洋。彼得大帝在18世纪初强行按西欧样式改造国家、建新都、办海军,把一个几乎没有不冻出海口的国家拉到了欧洲政治的桌上。','The Grand Duchy of Moscow began as a tributary of the Mongol Golden Horde and, having stopped paying tribute in 1476 and faced down the Horde on the Ugra in 1480, expanded in every direction. Eastward there was almost no one to stop it: Siberia was thinly peopled, and fur traders and Cossacks reached the Pacific within little more than a century. In the early eighteenth century Peter the Great forcibly remade the state on western European lines, built a new capital and a navy, and pulled a country with almost no ice-free outlet to the sea into the councils of Europe.'],
      rule:['权力高度集中是贯穿始终的特征,形式换过几次:沙皇专制、苏联的一党体制、1991年后的联邦总统制。苏联时期的特点是国家掌握全部生产资料并用五年计划配置资源——这套办法在工业化与战争动员上效率极高,在消费品与农业上长期低效,两者是同一套机制的两面。','Concentrated power runs through all of it, in changing forms: tsarist autocracy, the Soviet one-party state, and a federal presidency after 1991. What marked the Soviet era was state ownership of the means of production and the allocation of resources by five-year plan — highly effective for industrialisation and for mobilising a war economy, and persistently poor at consumer goods and farming. The two are the same mechanism seen from different sides.'],
      money:['幅员与资源:粮食、木材、金属,20世纪之后是石油与天然气。苏联时期靠计划体制在三十年内完成了工业化,代价包括农业集体化引发的大饥荒。1970年代油价高涨支撑了经济,1980年代油价下跌则加剧了困境;今天的俄罗斯经济仍高度依赖能源出口。','Size and resources: grain, timber, metals, and from the twentieth century oil and gas. Under the Soviet plan the country industrialised within thirty years, at a cost that included the famines that followed the collectivisation of agriculture. High oil prices propped up the economy in the 1970s and falling prices deepened its troubles in the 1980s; Russia\'s economy still leans heavily on energy exports.'],
      power:['纵深与人力。拿破仑与希特勒都在这片土地上耗尽了军队,1941至1945年苏联承受了二战欧洲战场最大的一块伤亡,也因此成为战后两极之一。冷战期间它在军事与航天上与美国并驾齐驱:1957年送上第一颗人造卫星,1961年加加林成为第一个进入太空的人。','Depth and manpower. Both Napoleon and Hitler exhausted their armies on this ground, and between 1941 and 1945 the Soviet Union absorbed most of the casualties of the European war, which is why it emerged as one of two poles afterwards. Through the Cold War it matched the United States in arms and in space: the first artificial satellite in 1957, and in 1961 the first human being to leave the atmosphere.'],
      fall:['1991年12月苏联解体,十五个加盟共和国各自独立,这是20世纪后期影响最大的一次政治变动。此前几年是经济停滞、加盟共和国离心与改革失控的叠加。解体之后的十年里,俄罗斯经历了产出大幅下滑与国有资产私有化,人均寿命一度下降;此后随油价回升逐步恢复。','The Soviet Union dissolved in December 1991 and its fifteen republics went their own ways — the largest political change of the late twentieth century. It followed several years in which economic stagnation, centrifugal pressure from the republics and a reform programme that ran out of control compounded one another. In the decade after, Russia went through a steep fall in output and the privatisation of state assets, with life expectancy falling for a time before recovering as oil prices rose.'],
      legacy:['文学与音乐是它最没有争议的输出:托尔斯泰、陀思妥耶夫斯基、契诃夫、柴可夫斯基、肖斯塔科维奇。科学上,门捷列夫的元素周期表、朗道学派的理论物理、以及整套航天工程——今天国际空间站仍在用联盟号飞船。西伯利亚大铁路把一个横跨十一个时区的国家连成整体,至今是世界最长的铁路线。','Literature and music are its least disputed exports: Tolstoy, Dostoevsky, Chekhov, Tchaikovsky, Shostakovich. In science, Mendeleev\'s periodic table, the Landau school in theoretical physics, and an entire tradition of spaceflight — Soyuz craft still carry crews to the International Space Station. The Trans-Siberian Railway tied a country spanning eleven time zones into one piece and is still the longest railway line in the world.'] },
  d:'莫斯科公国摆脱金帐汗国后向东一路扩张到太平洋,彼得大帝强行西化建起海军。1917年革命后以计划经济速成工业化,二战中击败纳粹主力,与美国平分世界四十余年;1991年联盟解体,俄罗斯仍是幅员最大的国家。' },
/* 中东·北非 */
{ l:'me', s:'mideast', v:0, n:'苏美尔·阿卡德', k:[[-3500,0],[-3300,.5],[-2334,.6],[-2004,0]], b:'最早的城市与楔形文字诞生于两河流域;阿卡德是首个"帝国"。',
  e:{ n:'Sumer & Akkad', w:'Sumer', b:'First cities and writing; Akkad, the first empire.', d:'The Sumerians invented writing, cities, schools and proto-law — practically defining "civilization"; Sargon of Akkad first welded the city-states into an empire. Their legacy persists in every hour of sixty minutes.', f:{ 'Peak':'24th c. BCE (Sargon)', 'Center':'Uruk, then Akkad, then Ur', 'Figures':'Sargon, Ur-Nammu', 'Legacy':'Cuneiform, the wheel, base-60, Gilgamesh' } },
  f:{ '鼎盛':'前24世纪(萨尔贡)', '中心':'乌鲁克→阿卡德→乌尔', '人物':'萨尔贡、乌尔纳姆', '成就':'楔形文字、车轮、六十进制、《吉尔伽美什》' },
  qh:{ born:['文字的起点是账本,不是诗歌','Writing began as bookkeeping, not poetry'],
       rule:['用宗教,把征服来的城市绑在一起','Religion tied the conquered cities together'],
       money:['缺木头缺石头,逼出了长途贸易','No timber, no stone: the long-distance trade was forced'],
       power:['养得起一支不用回家种地的军队','It could feed an army that never went home to farm'],
       fall:['苏美尔语从此只活在学堂里','Sumerian survived only in the schoolroom'],
       legacy:['一小时六十分,是他们那套算法','Sixty minutes to the hour is still their arithmetic'] },
  q:{ born:['两河下游是冲积平原,土地肥沃却几乎不下雨,要种地就得挖渠引水;开渠、分水、记账都需要很多人长期配合,协作的组织自己长成了城市。乌鲁克等城邦围绕神庙建立,最早的楔形文字就是为了记录谁交了多少大麦而发明的——文字的起点是账本,不是诗歌。','Southern Mesopotamia is a fertile floodplain with almost no rain, so farming meant digging canals. Building them, sharing the water and keeping track of it all required many people to cooperate for years, and that organization grew into cities. City-states like Uruk formed around temples, and the earliest cuneiform was invented to record who had delivered how much barley — writing began as bookkeeping, not poetry.'],
      rule:['早期的苏美尔城邦由神庙和王共治:神庙拥有大片土地和作坊,王(卢伽尔)最初是战时统帅,后来变成常设的君主。萨尔贡建立阿卡德后改为帝国式统治——派亲信当各城总督,让女儿恩赫杜安娜出任乌尔的月神女祭司,用宗教把征服来的城市绑在一起。','Early Sumerian city-states were run jointly by temple and king: temples owned vast land and workshops, while the lugal, at first a wartime commander, hardened into a permanent monarch. After Sargon founded Akkad he switched to imperial rule — installing loyalists as governors of conquered cities and making his daughter Enheduanna high priestess of the moon god at Ur, using religion to bind the conquests together.'],
      money:['经济的骨架是灌溉农业和再分配:神庙与王宫收进大麦和羊毛,再按工种发给劳动者,银按重量充当计价尺度而非流通硬币。两河平原缺木材、石头和金属,所以要用粮食和纺织品换来自伊朗高原、安纳托利亚甚至印度河的原料——长途贸易网就是这样被资源短缺逼出来的。','The backbone was irrigated farming plus redistribution: temples and palaces took in barley and wool and paid it back out to workers, with silver weighed as a unit of account rather than minted as coin. The plain had no timber, stone or metal, so grain and textiles were traded for materials from the Iranian plateau, Anatolia and even the Indus — long-distance trade networks were forced into being by what the land lacked.'],
      power:['强大来自三样东西的叠加:运河把产量抬起来,青铜武器和成建制的常备军把力量集中起来,文字让命令和税册能传到远处。据记载萨尔贡每天有五千四百人在他面前进食,这句夸耀的意思是——他养得起一支不用回家种地的军队。','Strength came from three things stacking up: canals raised the harvest, bronze weapons and a standing army concentrated force, and writing let orders and tax rolls travel. Sargon\'s inscriptions boast that 5,400 men ate before him each day; the boast really means he could feed an army that never had to go home to farm.'],
      fall:['阿卡德帝国维持了不到两百年就散了,主流看法是多因叠加:各城邦的独立传统从未消失,叛乱不断,东北山地的库提人反复南下,另有研究认为公元前2200年前后的一场长期干旱加剧了危机(这个气候解释仍在争论中)。之后乌尔第三王朝一度重建秩序,公元前2004年被东边的埃兰人攻破乌尔,苏美尔语从此退出日常口语,只留在学堂和经典里。','Akkad\'s empire lasted under two centuries. The mainstream view is that several causes converged: the old city-states never lost their taste for independence and kept rebelling, the Gutians pressed down from the northeastern hills, and some researchers argue a long drought around 2200 BCE deepened the crisis — though that climate explanation is still debated. The Third Dynasty of Ur later restored order until Elamites from the east sacked Ur in 2004 BCE, after which Sumerian survived only in schools and scriptures, no longer as a spoken tongue.'],
      legacy:['楔形文字、成文法的雏形(乌尔纳姆法典比汉谟拉比早约三百年)、六十进制,都从这里流出去:我们今天把一小时切成六十份、把圆周切成三百六十份,用的还是苏美尔人那套算法。《吉尔伽美什》里的大洪水是已知最早的洪水故事之一,恩赫杜安娜署名的神庙赞美诗则常被称为已知最早的具名作品。','Cuneiform, the first written law codes (Ur-Nammu\'s predates Hammurabi\'s by about three centuries) and base-60 arithmetic all flow from here: our sixty-minute hour and 360-degree circle are still Sumerian mathematics. The flood in the Epic of Gilgamesh is among the earliest flood stories known, and Enheduanna\'s signed temple hymns are often called the earliest works attributed to a named author.'] },
  d:'两河下游的苏美尔人发明了文字、城市、学校与成文法的雏形,几乎定义了"文明"本身;阿卡德的萨尔贡首次把诸城邦捏合成帝国。其文学与数学的影响绵延至今——我们的一小时六十分、一圈三百六十度,都是苏美尔的遗产。' },
{ l:'me', s:'mideast', v:2, n:'古埃及', k:[[-3100,0],[-2600,.6],[-2181,.4],[-1550,.55],[-1250,.7],[-1069,.4],[-664,.3],[-332,.15],[-30,0]], b:'尼罗河馈赠的三千年文明:金字塔、法老与象形文字。',
  e:{ n:'Ancient Egypt', b:'Three millennia of pharaohs along the Nile.', d:'The Nile\'s regular flood gave Egypt rare stability: thirty dynasties without losing its character. The pyramids were more ancient to Cleopatra than she is to us. Persia, Greece and Rome took it in turn until the Ptolemies\' final curtain.', f:{ 'Peak':'New Kingdom (1550–1069 BCE)', 'Center':'Memphis, later Thebes', 'Figures':'Khufu, Ramesses II, Cleopatra, Imhotep', 'Legacy':'Pyramids, hieroglyphs, solar calendar' } },
  f:{ '鼎盛':'新王国(前1550—前1069)', '中心':'孟菲斯→底比斯', '人物':'胡夫、拉美西斯二世、克娄巴特拉、伊姆霍特普', '成就':'金字塔、象形文字、太阳历' },
  ct:['先后的王国时期','Successive kingdoms'],
  co:[ { n:['古王国','Old Kingdom'], y:[-2686,-2181], c:['孟菲斯','Memphis'], x:['王国之间隔着分裂的间歇期','with intermediate periods of division between them'] },
       { n:['中王国','Middle Kingdom'], y:[-2055,-1650], c:['底比斯','Thebes'] },
       { n:['新王国','New Kingdom'], y:[-1550,-1069], c:['底比斯','Thebes'], m:1 } ],
  q:{ born:['尼罗河的泛滥是全世界少有的可预测事件:每年夏末涨水,退去后留下一层肥泥,不必修复杂的堤坝就能种出余粮。两侧是沙漠、北面是海,外敌不易进来,河流本身又是南北通行的高速路——粮食稳定、边界安全、交通顺畅这三件事同时具备,统一的王权在公元前3100年前后出现,此后虽三度分裂又三度重整,这套框架延续了三千年。','The Nile\'s flood was one of the few truly predictable events in the ancient world: it rose each late summer and left a layer of fertile silt, yielding surplus grain without elaborate dikes. Desert on both sides and sea to the north kept invaders out, while the river itself was a north-south highway. Stable food, safe borders and easy transport arrived together, and a unified kingship emerged around 3100 BCE and lasted three thousand years.'],
      rule:['法老不是被神选中的人,他本身就被视为神在人间的形态——维持宇宙秩序(玛阿特)是他的职责,所以反对他等于放任世界失序。真正让这套神学落地的是书吏:他们识字、会算、掌管粮仓与土地登记,构成一个不靠血统而靠考试般训练进入的官僚层,王朝换了三十多次而这套班子始终在。','Pharaoh was not a man chosen by the gods; he was regarded as divinity in human form, charged with maintaining maat, cosmic order — so opposing him meant letting the world slide into chaos. What made that theology work in practice was the scribes: literate, numerate, running granaries and land registers, they formed a bureaucracy entered through training rather than birth, and it survived through more than thirty changes of dynasty.'],
      money:['埃及三千年间基本没有铸币(硬币要到很晚才随波斯和希腊人进来),经济靠国家计量与实物调拨运转:粮食是工资,谷仓是国库,大工程的工人领的是面包和啤酒。洪水每年抹掉田界,于是国家每年重新丈量土地并据此定税,埃及的几何学就是从这件年年要办的差事里长出来的。','For most of three thousand years Egypt had no coinage — coins arrived late, with the Persians and Greeks. The economy ran on state measurement and payment in kind: grain was the wage, granaries were the treasury, and workers on the great projects were paid in bread and beer. Each flood erased the field boundaries, so the state re-surveyed the land every year and set taxes from it, and Egyptian geometry grew out of that annual chore.'],
      power:['埃及的强大更多是「组织能力」而非常备武力:能在农闲时把成千上万人调去采石、运石、建陵墓的国家,同样能把他们调去打仗。新王国时期从西亚学来马拉战车和复合弓后转为进攻姿态,向南控制努比亚金矿、向北进入叙利亚-巴勒斯坦。','Egypt\'s power was organizational more than military: a state that could move tens of thousands of people in the farming off-season to quarry, haul and build tombs could move them to war just as easily. In the New Kingdom, after adopting the chariot and composite bow from West Asia, Egypt turned outward — taking the Nubian goldfields to the south and pushing into Syria-Palestine to the north.'],
      fall:['埃及没有一个「灭亡之日」,而是被一次比一次大的外部帝国逐层吸收。主流看法是多因叠加:公元前12世纪的地中海东部普遍动荡切断了贸易与属地,阿蒙神庙的祭司集团积累了大量土地与人力、与王权分权,王位继承争斗使国家周期性分裂;此后利比亚人、库施人、亚述人、波斯人先后入主,公元前332年亚历山大到来,托勒密王朝之末公元前30年埃及并入罗马。','Egypt has no single date of death; it was absorbed layer by layer by ever larger outside empires. The mainstream view is convergent causes: the wide upheaval across the eastern Mediterranean in the twelfth century BCE cut trade and stripped away dependencies, the priesthood of Amun accumulated so much land and manpower that it shared power with the throne, and succession fights split the country periodically. Libyans, Kushites, Assyrians and Persians ruled in turn, Alexander arrived in 332 BCE, and with the end of the Ptolemies Egypt became Roman in 30 BCE.'],
      legacy:['一年365天的太阳历经罗马改造成为今天公历的骨架;象形文字借罗塞塔石碑在1822年被商博良破译,让人类重新读懂一个已经沉默一千多年的文明。金字塔、纸莎草文书、医学与数学纸草留下的不只是奇观,还有一个证明:高度组织的国家可以在青铜时代、在没有铸币的条件下运转两千多年。','The 365-day solar calendar, reworked by Rome, is the skeleton of the calendar we still use. Hieroglyphs were deciphered by Champollion in 1822 with the help of the Rosetta Stone, letting humanity read a civilization that had been silent for more than a thousand years. The pyramids, papyrus archives and medical and mathematical texts left more than wonders — they proved that a highly organized state could run for three millennia without iron and without money.'] },
  /* qh = 六问钩子句(v134 样板)。同唐:全部从 q 正文提取,不新增事实。 */
  qh:{ born:['河水每年准时来,粮食就有富余','The flood came on time, and there was grain to spare'],
       rule:['法老是神,真正管事的是书吏','Pharaoh was a god; the scribes ran the country'],
       money:['工钱发的是面包和啤酒','Wages were paid in bread and beer'],
       power:['能调人建陵墓,就能调人打仗','Move men to build tombs, or to war'],
       fall:['没有灭亡之日,是被一层层吸收掉的','No day of extinction — absorbed one empire at a time'],
       legacy:['今天公历的骨架,是埃及的太阳历','The calendar we use is built on the Egyptian solar year'] },
  d:'尼罗河年复一年的泛滥给了埃及罕见的稳定:三千年间王朝更迭三十余次而文明底色不改。金字塔属于古王国,卡尔纳克神庙和图坦卡蒙属于新王国——两者相隔一千多年。一个常被忽略的时间感:金字塔建成之时距克娄巴特拉,比她距今天还要遥远。埃及先后被波斯、希腊、罗马接管,最终随托勒密王朝谢幕并入罗马版图。' },
{ l:'me', s:'mideast', v:1, n:'赫梯', k:[[-1650,0],[-1350,.5],[-1180,0]], b:'安纳托利亚的战车强国,最早大规模冶铁的文明之一。',
  e:{ n:'Hittites', b:'Anatolian chariot power; early masters of iron.', d:'The Hittites fought Egypt to a draw at Kadesh and signed the oldest surviving peace treaty. When the Bronze Age collapse destroyed the kingdom, its ironworking scattered — opening the Iron Age.', f:{ 'Peak':'14th c. BCE', 'Center':'Hattusa', 'Figures':'Muwatalli II', 'Legacy':'Ironworking, first international treaty' } },
  f:{ '鼎盛':'前14世纪', '中心':'哈图沙', '人物':'穆瓦塔里二世', '成就':'铁器冶炼、现存最早的国际和约' },
  qh:{ born:['高原本身,就是一座天然堡垒','The highland was itself a fortress'],
       rule:['不吞并,用写下来的条约绑住你','Not annexation: a written treaty that bound you'],
       money:['那部法典,同时也是一份物价表','The law code doubles as a price list'],
       power:['战车坐三个人,比埃及的两人车能冲','Three men to a chariot, against Egypt with two'],
       fall:['铁器是在它崩溃之后,才普及开的','Iron spread only after the collapse'],
       legacy:['现存最早的和约,复制品挂在联合国','The oldest surviving peace treaty hangs at the UN'] },
  q:{ born:['安纳托利亚高原不像两河那样有大河灌溉,但有草场、木材和铜银矿,还卡在黑海与地中海、爱琴海与两河之间的路口。说印欧语的赫梯人在这里把分散的城邦收拢起来,约公元前1650年以哈图沙为都建国——高地本身就是一座天然堡垒。','The Anatolian plateau has no great irrigating river, but it has pasture, timber and copper and silver ore, and it sits at the crossroads between the Black Sea and the Mediterranean, the Aegean and Mesopotamia. Indo-European-speaking Hittites gathered its scattered towns into one state around 1650 BCE with a capital at Hattusa — the highland itself was a natural fortress.'],
      rule:['赫梯王是大王、最高祭司与最高法官,但早期还有一个贵族会议(潘库斯)对王位有发言权,王后(塔瓦南娜)也拥有独立的宗教与政治地位——这在当时的近东相当特别。对外它不搞直接吞并,而是用成文的封臣条约把附属国绑住:条约写明进贡、出兵、不得另投他主的义务,双方各存一份并请神明作证。','The Hittite king was great king, chief priest and supreme judge, but early on a council of nobles, the panku, had a say in the succession, and the queen, the tawananna, held religious and political standing of her own — unusual in the Near East of that age. Abroad the Hittites annexed less than they bound: written vassal treaties spelled out tribute, military service and the ban on switching allegiance, with each side keeping a copy and the gods called as witnesses.'],
      money:['财政来自高原的谷物与畜牧、王室掌握的银铜矿,以及东西向商路的过境收益。赫梯法典的特点是大量条文在给物品定价、给伤害定赔偿额——那既是法律也是一份物价表,今天成了了解青铜时代经济的珍贵材料。','Revenue came from the plateau\'s grain and herds, from royal control of silver and copper, and from traffic along the east-west trade roads. What stands out in the Hittite laws is how many clauses set prices for goods and compensation for injuries — at once a legal code and a price list, and today a precious window onto the Bronze Age economy.'],
      power:['军事上的看家本领是轻型战车:赫梯战车一般载三人(御者、持盾者、战士),比埃及的两人车更能近战冲击,机动性换取了冲击力。铁在赫梯确实已被加工,但常见的「赫梯垄断冶铁并严守秘密」说法学界并不认可——当时的铁仍是稀有贵重品,还没有取代青铜成为兵器主材。','Their signature weapon was the light chariot: a Hittite car usually carried three men — driver, shield-bearer and fighter — trading some speed for shock power in close combat, where Egyptian cars carried two. Iron was worked in Hittite lands, but the familiar claim that the Hittites monopolized ironworking and guarded it as a secret is not accepted by scholars: iron was still a rare, precious material and had not replaced bronze in weapons.'],
      fall:['公元前1200年前后,整个地中海东部的宫廷体系接连崩塌,赫梯是其中一环。主流看法是多因叠加:多年歉收与饥荒(赫梯档案里有向埃及求粮的信)、附庸国纷纷叛离、王室内斗,再加上被统称为「海上民族」的迁徙群体冲击;约公元前1180年哈图沙被弃并遭焚毁。冶铁的工匠随之流散,铁器反而在崩溃之后普及开来。','Around 1200 BCE the palace systems across the eastern Mediterranean collapsed one after another, and the Hittites were one of them. The mainstream view is convergent causes: years of failed harvests and famine (Hittite archives include letters begging Egypt for grain), vassals breaking away, feuds inside the royal house, and the pressure of the migrating groups lumped together as the Sea Peoples. Hattusa was abandoned and burned around 1180 BCE. Metalworkers scattered, and iron spread more widely after the collapse than before it.'],
      legacy:['赫梯与埃及在卡迭石会战(约公元前1274年)后于公元前1259年缔结的和约,是现存最早的国际和平条约文本,埃及与赫梯两个版本都保存了下来,复制品挂在联合国总部。赫梯语的泥板还让语言学家第一次读到有文字记录的最古老印欧语,把整个印欧语系的谱系往前推了一大截。','The treaty the Hittites and Egypt concluded in 1259 BCE, after the battle of Kadesh around 1274, is the earliest international peace treaty whose text survives — both the Egyptian and the Hittite versions are preserved, and a copy hangs at the United Nations. Hittite tablets also gave linguists their first look at the oldest recorded Indo-European language, pushing the whole family tree back by centuries.'] },
  d:'安纳托利亚高原的赫梯人以战车与铁器称雄,与埃及在卡迭石会战后签订了现存最早的国际和平条约。青铜时代大崩溃中王国覆灭,冶铁技术随工匠流散四方——铁器时代自此开启。' },
{ l:'me', s:'mideast', v:1, n:'古巴比伦', k:[[-1894,0],[-1792,.4],[-1750,.5],[-1650,.28],[-1595,0]], b:'汉谟拉比把 282 条法律刻在一根黑石柱上,立在人人看得见的地方。',
  e:{ n:'Old Babylon', w:'First Babylonian dynasty', b:'Hammurabi had 282 laws carved on a black pillar and set it up where everyone could see.', d:'Babylon began as an unremarkable town on the Euphrates; Hammurabi spent thirty years welding southern Mesopotamia into one state. What he is remembered for is not the wars but the pillar: 282 laws cut into two metres of basalt and raised in public — law made open, fixed, and binding on the king himself. The kingdom faded quickly after his death, and in 1595 BCE a Hittite raid ended it.', f:{ 'Peak':'Hammurabi (1792–1750 BCE)', 'Center':'Babylon', 'Figures':'Hammurabi', 'Legacy':'The Code of Hammurabi, the written-law tradition' } },
  f:{ '鼎盛':'汉谟拉比(前1792—前1750)', '中心':'巴比伦', '人物':'汉谟拉比', '成就':'《汉谟拉比法典》、成文法传统' },
  qh:{ born:['本来是不起眼的一座城,胜在位置','An unremarkable town that happened to sit at the crossroads'],
       rule:['把规矩刻在石头上,立给所有人看','The rules cut into stone, standing where all could see'],
       money:['放贷是合法的,但利率有上限','Lending was legal, and the interest rate was capped'],
       power:['掐住上游的渠,下游就得听话','Hold the upstream canal and the downstream harvest is yours'],
       fall:['靠一个人的威望撑着,人一死就散','Held together by one man, and gone when he was'],
       legacy:['「以眼还眼」这句话,出自那根石柱','An eye for an eye comes off that stone pillar'] },
  q:{ born:['乌尔第三王朝崩溃后,两河流域碎成十几个说阿摩利语的小王国,巴比伦本是幼发拉底河边不起眼的一座城。它的位置恰在南北之间的枢纽上,汉谟拉比(前1792—前1750在位)用外交与战争交替的三十年,先后收拾了拉尔萨、马里和埃什嫩那,把两河南部合成一个国家。','After the Third Dynasty of Ur fell, Mesopotamia broke into a dozen small Amorite kingdoms, and Babylon was an unremarkable town on the Euphrates. But it sat at the hinge between north and south, and over thirty years of alternating diplomacy and war Hammurabi (r. 1792–1750 BCE) took down Larsa, Mari and Eshnunna and welded southern Mesopotamia into one state.'],
      rule:['汉谟拉比的做法是把「王是正义的守护者」这件事做成可以看见的东西:282条法律被刻上一根高逾两米的玄武岩柱,立在公共场所,人人都能看见规矩长什么样,连国王也被这套说法约束。不过学界一般认为,这根石柱更接近国王向神明与后世交出的正义宣言与判例汇编,当时法庭的实际判决文书极少援引它。','Hammurabi turned the claim that the king guards justice into something you could see: 282 laws carved on a basalt stele over two metres tall and set up in public, so anyone could see what the rules looked like — and the king was bound by the claim too. Scholars generally read the stele less as a working statute book than as a declaration of the king\'s justice to the gods and to posterity, a collection of exemplary judgments: surviving court records almost never cite it.'],
      money:['财富来自灌溉农业:大麦是主粮也是工资,枣椰、羊毛和芝麻油是主要商品,银按重量作为计价标准。神庙和商人放贷给农民,利率有法定上限;巴比伦位于南北与东西商路的交叉点,过境与转口本身就是收入。','Wealth came from irrigated farming: barley was both staple and wage, with dates, wool and sesame oil as the main commodities and silver weighed as the standard of value. Temples and merchants lent to farmers at rates the law capped. Sitting where the north-south and east-west trade routes crossed, Babylon also earned simply from goods passing through.'],
      power:['汉谟拉比的强项是耐心的外交:先与强邻结盟打弱邻,再回头收拾昨天的盟友,几乎每次战争前都已经先在外交上孤立了对手。水利工程既是生产手段也是战争手段——控制上游的渠道就能决定下游城市的收成。','Hammurabi\'s real strength was patient diplomacy: ally with a strong neighbour to crush a weak one, then turn on yesterday\'s ally, so that each war began with the enemy already isolated. Waterworks were both a means of production and a weapon — controlling an upstream canal meant deciding a downstream city\'s harvest.'],
      fall:['衰落几乎在汉谟拉比死后立刻开始,而且是多重原因:他的国家靠个人威望与联盟维系,缺乏能自我延续的制度;继位的萨姆苏伊卢那时期南部诸城反叛并独立出海国王朝,东北的加喜特人持续渗透,南方灌溉区盐碱化使产量下降。公元前1595年赫梯王穆尔西里一世远征洗劫巴比伦城,古巴比伦王国就此终结,加喜特人接手了这座城。','Decline began almost the moment Hammurabi died, and from several causes at once: his state rested on personal prestige and alliances rather than institutions that could renew themselves. Under his son Samsu-iluna the southern cities revolted and broke away as the Sealand dynasty, Kassites pressed in from the northeast, and salinization cut yields in the southern irrigated zone. In 1595 BCE the Hittite king Mursili I raided and sacked Babylon; the Old Babylonian kingdom ended there, and the Kassites took over the city.'],
      legacy:['那根石柱1901年在伊朗被发现,现藏卢浮宫,「以眼还眼」这句话就出自其中——它让「法律要公开、要固定」成为一种可以被后人继承的想法。巴比伦的数学也走得很远:六十进制的乘法表、平方根近似值、勾股数表(普林顿322号泥板)都出自这一传统,而阿卡德语从此成为整个近东几百年的外交通用语。','The stele was found in Iran in 1901 and now stands in the Louvre; \'an eye for an eye\' comes from it. Its real bequest was the idea that law should be public and fixed — something later societies could inherit. Babylonian mathematics travelled far too: base-60 multiplication tables, square-root approximations and the Pythagorean triples of the Plimpton 322 tablet all belong to this tradition, and Akkadian went on to serve as the diplomatic language of the whole Near East for centuries.'] },
  d:'巴比伦本是幼发拉底河边一座不起眼的城,汉谟拉比用三十年把两河南部合成一个国家。他最有名的不是打仗,是把 282 条法律刻在两米多高的玄武岩石柱上、立在人人看得见的地方——法律第一次成为公开、固定、连国王也要认的东西。他死后王国迅速衰落,前1595 年赫梯人洗劫巴比伦,古巴比伦王国就此终结。',
  gl:[ { a:-1792, b:-1750, k:'thought', t:['成文法传统','The written-law tradition'], d:['把王的裁决刻上石柱,让所有人看见。','The king\'s judgments carved where all can see.'] },
       { a:-1750, b:-1595, k:'tech', t:['泥板上的数学','Mathematics on clay'], d:['同一批泥板里有大量数学练习:开方、求面积、解二次问题。最有名的一块编号 YBC 7289,画着一个正方形和它的对角线,旁边用六十进制写着二的平方根,准到小数点后约六位——比毕达哥拉斯早一千多年。这块泥板现藏耶鲁大学。另一块「普林顿 322」列着十五组直角三角形的边长,至今学者还在争论它是干什么用的。','The same tablets carry a great deal of mathematics: square roots, areas, quadratic problems. The most famous, YBC 7289, shows a square and its diagonal with the square root of two written beside it in base sixty, good to about six decimal places — a thousand years before Pythagoras. That tablet is at Yale. Another, Plimpton 322, lists fifteen sets of right-triangle sides, and scholars still argue over what it was for.'] },
       { a:-1894, b:-1595, k:'art', t:['几支故事合成一部长诗','Gilgamesh takes its shape'], d:['苏美尔人流传的几支吉尔伽美什故事,在这几百年里被编成一部完整的长诗,用阿卡德语写定。它写一个国王失去挚友后满世界找长生不死,最后空手而归——已知最早的关于「人终有一死」的长篇作品。后来通行的标准本 1853 年在尼尼微的图书馆里出土,却要到 1872 年才被读通;其中大洪水那一段与《创世记》的挪亚故事高度相似,那一年在欧洲引起轰动。','The separate Sumerian tales of Gilgamesh were worked in these centuries into one long poem, written down in Akkadian. It tells of a king who loses his friend, searches the world for a life without death, and comes home empty-handed — the earliest sustained work we have on the fact that people die. The standard version that came down later was dug out of the library at Nineveh in 1853, but no one could read it until 1872; its flood story, so like Noah\'s in Genesis, caused a sensation in Europe that year.'] } ] },
{ l:'me', s:'mideast', v:2, n:'加喜特巴比伦', k:[[-1595,0],[-1450,.28],[-1350,.38],[-1225,.22],[-1155,0]], b:'赫梯人抢完就走,山里来的加喜特人留了下来——统治巴比伦四百年,是这座城最长的一个王朝。',
  d:'前 1595 年赫梯王沿幼发拉底河长途奔袭,洗劫巴比伦后立刻退走——那么远的地方他拿不住。权力空出来,东边扎格罗斯山区的加喜特人接手了这座城和两河下游。他们统治了四百多年,比汉谟拉比那一支久得多,是巴比伦历史上延续最长的王朝。这批外来人几乎全盘接受了本地的一切:说阿卡德语、用楔形文字、供奉马尔杜克,自己的语言只剩下一些人名。他们与埃及、赫梯、亚述的君主互称「兄弟」,通信讨价还价;《吉尔伽美什史诗》今天通行的那个版本,也是在这几百年里编定的。前 1155 年埃兰人攻入,王朝结束。',
  e:{ n:'Kassite Babylonia', w:'Kassite dynasty', b:'The Hittites sacked Babylon and left; the Kassites from the hills stayed — and ruled it for four centuries, its longest dynasty.', d:'In 1595 BC a Hittite king raided far down the Euphrates, sacked Babylon and immediately withdrew — he could not hold anything that distant. Into the vacuum came the Kassites from the Zagros hills to the east, who took the city and the lower rivers with it. They ruled for over four hundred years, far longer than Hammurabi\'s line, and theirs is the longest dynasty in Babylon\'s history. These outsiders adopted virtually everything local: they wrote Akkadian in cuneiform and worshipped Marduk, and of their own language little survives beyond personal names. They addressed the kings of Egypt, Hatti and Assyria as "brother" and haggled with them by letter; the standard version of the Epic of Gilgamesh — the one read today — was fixed in these centuries. Elamites broke in about 1155 BC and the dynasty ended.', f:{ 'Peak':'14th century BC', 'Center':'Babylon; Dur-Kurigalzu', 'Figures':'Burnaburiash II', 'Legacy':'Kudurru boundary stones; the standard Gilgamesh' } },
  f:{ '鼎盛':'前14世纪', '中心':'巴比伦、杜尔-库瑞加尔祖', '人物':'布尔纳布里亚什二世', '成就':'库杜鲁界石、《吉尔伽美什史诗》标准版' },
  qh:{ born:['赫梯人抢完就走,山里来的人留下了','The Hittites sacked and left; the hill people stayed'],
       rule:['外来的王,学会了本地的一切','Foreign kings who learned everything local'],
       money:['写信给法老:你送的金子成色不对','A letter to pharaoh: your gold is not what you promised'],
       power:['四百年没有大扩张,也没有大崩溃','Four centuries with no great conquest and no great collapse'],
       fall:['埃兰人从东边来,搬走了能搬的一切','The Elamites came from the east and carried off what they could'],
       legacy:['今天读的《吉尔伽美什》,是那时候定下的','The Gilgamesh read today was fixed in those years'] },
  q:{ born:['前 1595 年赫梯王穆尔西里一世沿幼发拉底河奔袭上千公里,洗劫巴比伦后立刻掉头回国——他拿不住这么远的地方,这更像一次远征而不是征服。权力空了出来,东边扎格罗斯山区的加喜特人接手了这座城。他们原本给巴比伦人当雇佣兵和农工,渗透了一两百年,最后成了这里的王。','In 1595 BC the Hittite king Mursili I raided a thousand kilometres down the Euphrates, sacked Babylon and turned straight back — he had no way to hold anything so far off, and it was a raid rather than a conquest. Into the vacuum came the Kassites from the Zagros hills to the east. They had been serving Babylonians as soldiers and farmhands for a century or two, and ended as its kings.'],
      rule:['他们说阿卡德语、用楔形文字、供奉马尔杜克,自己的语言只留下一些人名和少量词汇。他们最有代表性的东西叫「库杜鲁」——一块刻着神的符号的界石,记录国王把哪块地封给了谁,并写明谁动这块地就要受神的诅咒。同类的土地授予石更早就有,而加喜特人把它做成了成套的制度——「这地是谁的」从此不靠人的记忆,靠石头。','They wrote Akkadian in cuneiform and worshipped Marduk, and of their own language little more than names survives. Their signature object is the kudurru — a boundary stone carved with divine emblems, recording which land the king had granted to whom and cursing in the gods\' names anyone who moved it. Stones granting land existed earlier, but the Kassites made them a standing institution — after this, who owned what rested on stone rather than on memory.'],
      money:['靠两河下游的大麦、椰枣与羊毛,加上转口:东边山区的马、波斯湾来的货,都要经过这里。而它在国际上最抢手的出口是马与青金石。埃及阿马尔那出土的泥板信里,加喜特国王与法老平起平坐地讨价还价——抱怨对方送来的黄金成色不足、使者被扣得太久,同时开口再要一批。同一批信里,叙利亚那些小邦写给法老的是求援,而巴比伦写的是生意。','It lived on the barley, dates and wool of the lower rivers, plus transit: horses from the eastern hills and goods from the Gulf all came through. Its most sought-after exports were horses and lapis lazuli. In the clay letters found at Amarna in Egypt, the Kassite king bargains with pharaoh as an equal — complaining that the gold sent was not the promised quality and that his envoys had been detained too long, while asking for more. In the same archive the small Syrian states write to pharaoh for rescue; Babylon writes about business.'],
      power:['四百年里既没有大扩张,也没有大崩溃——这在青铜时代晚期少见。它与埃及、赫梯、米坦尼、亚述并列,君主之间互称「兄弟」,靠联姻、通信与礼物往来维持均势。真正的压力来自北边:亚述逐渐强大,前 1225 年前后一度攻入巴比伦,把马尔杜克的神像掳走,连巴比伦王本人都被戴上镣铐押了回去。','For four hundred years there was neither great conquest nor great collapse — unusual for the late Bronze Age. Babylon stood alongside Egypt, Hatti, Mitanni and Assyria, whose rulers addressed one another as "brother" and kept the balance by marriage, letters and gifts. The real pressure came from the north: Assyria grew steadily stronger and around 1225 BC broke into Babylon, carried off the statue of Marduk and led the Babylonian king away in chains.'],
      fall:['北边的亚述反复削弱它,东边的埃兰人给了最后一击:前 1155 年前后埃兰军队攻入巴比伦,王朝结束。埃兰人把能搬的都搬回了苏萨——站内那根汉谟拉比法典石柱,正是这一次被搬走的;它在苏萨地下埋了三千年,1901 年才被挖出来。','Assyria wore it down from the north and Elam finished it from the east: around 1155 BC an Elamite army broke into Babylon and the dynasty ended. The Elamites carried off whatever could be moved, back to Susa — and the stele of Hammurabi\'s laws, which this site tells you about elsewhere, went in exactly this haul. It lay under Susa for three thousand years and was dug up in 1901.'],
      legacy:['巴比伦在这四百年里从一座被洗劫的城变回两河的学术与宗教中心。《吉尔伽美什史诗》的标准版本大致在这几百年里由祭司整理定型(确切年代学界仍有争论)——今天读到的那个版本来自这一次编定,而不是更早的苏美尔散篇。库杜鲁界石留下大量土地与法律记录。而「大国之间互相写信、称兄道弟、为一批黄金讨价还价」这套做法,是目前已知最早的一整套外交档案。','Over these four centuries Babylon went from a sacked city back to the scholarly and religious centre of Mesopotamia. Priests gave the Epic of Gilgamesh its standard shape somewhere in these centuries (the exact date is still debated) — the text read today descends from here rather than from the older, scattered Sumerian poems. The kudurru stones preserve a mass of legal and land records. And the practice of great powers writing to one another, calling each other brother and haggling over a shipment of gold, is the earliest full diplomatic archive we have.'] } },
{ l:'me', s:'mideast', v:0, n:'弗里吉亚', k:[[-1180,0],[-900,.18],[-750,.3],[-720,.28],[-696,.1],[-676,0]], b:'点石成金那位迈达斯王真的存在过:传说里他碰什么都变成金子,亚述的档案里他只是个不好打交道的邻国国王。',
  d:'赫梯灭亡之后,安纳托利亚中部的高原上兴起了弗里吉亚,都城在今天安卡拉西南不远的戈尔迪翁。它最有名的国王叫迈达斯——希腊人讲他碰到什么什么就变成金子,最后连食物也不能吃;而亚述的泥板档案里,同一时期确实有一位「穆什基人的米塔」,与亚述往来、缔约又交恶,前 696 年前后死于辛梅里安人的入侵。戈尔迪翁城中传说有一个谁也解不开的绳结,前 333 年亚历山大经过时一剑把它砍断——「戈尔迪之结」从此成了「快刀斩乱麻」的代名词。弗里吉亚人戴的那种向前弯折的软帽,在希腊罗马的图像里本来是「外国人」的记号;两千年后欧洲人把它和罗马释放奴隶时戴的另一种帽子(pileus)认混了,于是它反过来成了自由的象征,今天还印在好几个国家的国徽上。',
  e:{ n:'Phrygia', w:'Phrygia', b:'King Midas of the golden touch was a real person — in Assyrian records he is simply a difficult neighbour.', d:'After the Hittites fell, Phrygia rose on the central Anatolian plateau with its capital at Gordium, not far southwest of today\'s Ankara. Its best-known king was Midas — to the Greeks, the man whose touch turned everything to gold until he could no longer eat; in the Assyrian tablets of the same years, a certain Mita of Mushki who dealt with Assyria, made treaties and fell out with them, and died around 696 BC in the Cimmerian invasions. Gordium was said to hold a knot no one could untie, and when Alexander passed through in 333 BC he cut it with his sword — the Gordian knot has meant a problem solved by force ever since. And the soft forward-curling cap the Phrygians wore marked a foreigner in Greek and Roman art; two thousand years later Europeans confused it with the pileus, the cap given to freed Roman slaves, and it became instead an emblem of liberty — it still appears on several national coats of arms.', f:{ 'Peak':'Midas (c. 738—696 BC)', 'Center':'Gordium', 'Figures':'Midas', 'Legacy':'The Gordian knot; the Phrygian cap' } },
  f:{ '鼎盛':'迈达斯王(约前738—前696)', '中心':'戈尔迪翁', '人物':'迈达斯', '成就':'戈尔迪之结、弗里吉亚帽' },
  qh:{ born:['赫梯倒了以后,高原上补进来一批新人','After the Hittites fell, newcomers filled the plateau'],
       rule:['一个国王,两套记载,对不太上','One king, two sets of records, and they barely match'],
       money:['羊毛、马匹,还有一条东西向的大道','Wool, horses, and one great road running east to west'],
       power:['靠的是地利:谁去东边都得从这里过','Geography did the work: everyone going east came through'],
       fall:['北边草原上的骑手南下,城破国亡','Riders came down off the northern steppe and the city fell'],
       legacy:['他们的帽子,后来成了自由的记号','Their cap later became the badge of liberty'] },
  q:{ born:['前 1200 年前后赫梯帝国崩溃,安纳托利亚中部空了出来。此后两三百年,一支被亚述人称作「穆什基」的人群在这片高原上聚成一个王国,希腊人叫它弗里吉亚,都城戈尔迪翁就在今天安卡拉西南不远。它不是赫梯的延续,而是在废墟上另起的一摊。','The Hittite empire collapsed around 1200 BC and central Anatolia was left open. Over the next two or three centuries a people the Assyrians called the Mushki gathered into a kingdom on that plateau — Phrygia to the Greeks — with its capital at Gordium, a short way southwest of today\'s Ankara. It was not a continuation of the Hittites but something started fresh on their ruins.'],
      rule:['关于同一位国王,留下了两套对不上的记载。希腊人写的是神话:迈达斯向神许愿,碰到什么什么就变成金子,结果连饭都吃不成,只好求神收回;他还因为在一场音乐比赛里投错票被阿波罗变出一对驴耳朵。亚述的泥板写的是外交:「穆什基人的米塔」占了几座边城、与亚述缔约、又反悔。同一个人,一边被写成寓言,一边被记成对手。','Two irreconcilable records survive of the same king. The Greeks wrote myth: Midas asked the gods that everything he touched turn to gold, could then not eat, and had to beg for the gift to be taken back; he was also given donkey\'s ears by Apollo for voting the wrong way in a music contest. The Assyrian tablets wrote diplomacy: Mita of Mushki seized several border towns, made a treaty with Assyria, and broke it. One man, written up as a fable on one side and filed as an opponent on the other.'],
      money:['高原产羊毛与马,弗里吉亚的纺织与镶嵌木器在近东很有名气。但真正的底子是位置:从爱琴海岸往东进入亚洲,大体只有这一条走廊,后来的波斯御道、罗马大道乃至今天的公路都沿着它走。戈尔迪翁城下的大墓里出土过整套青铜器与镶嵌家具,还有锅底残留的食物——分析出来是烤羊肉配扁豆和蜂蜜酒。','The plateau produced wool and horses, and Phrygian textiles and inlaid woodwork were well known across the Near East. But the real asset was position: going east from the Aegean into Asia there is essentially one corridor, and the Persian Royal Road, the Roman highway and the modern motorway all follow it. A great tumulus at Gordium yielded a full set of bronze vessels and inlaid furniture, and residues in the pots — analysed as roast lamb with lentils and a honeyed drink.'],
      power:['弗里吉亚从来不是军事强权,它的分量来自地利:谁要从西边进入亚洲腹地,都得经过这条走廊。城里那个传说中谁也解不开的绳结,据说系在一辆旧牛车上,神谕说解开它的人将统治亚洲——这句神谕本身就是「谁控制这里谁就控制通道」的另一种说法。前 333 年亚历山大到此,拔剑砍断了它。','Phrygia was never a military power; its weight came from geography, since anyone entering the Asian interior from the west had to pass along this corridor. The knot in the city, said to be tied to an old ox-cart and impossible to untie, came with an oracle that whoever loosed it would rule Asia — which is another way of saying that whoever held this place held the road. Alexander arrived in 333 BC and cut it with his sword.'],
      fall:['前 7 世纪初,来自黑海北岸草原的辛梅里安骑手南下,攻破戈尔迪翁。希腊的传说讲迈达斯在城破时饮牛血自尽。考古这边反而更不确定:发掘方现在把那一层焚毁定在更早的约前 800 年,并认为是失控的意外火灾而不是入侵,另一派仍守旧说——同一层灰,两种读法。王国随即散掉,高原上剩下一些各自为政的小邦;约前 625 年被西边的吕底亚吸收,再往后随吕底亚一起并入波斯。','Early in the seventh century BC Cimmerian riders came down from the steppe north of the Black Sea and stormed Gordium. Greek tradition says Midas killed himself by drinking bull\'s blood as the city fell. Archaeology is the less settled side: the excavators now date that destruction layer considerably earlier, to about 800 BC, and read it as an accidental fire rather than an invasion, while others hold to the older view — one layer of ash, two readings. The kingdom came apart into small local polities; Lydia absorbed them around 625 BC, and they passed with Lydia into the Persian empire.'],
      legacy:['两样东西活得比这个王国久得多。一是「戈尔迪之结」:亚历山大那一剑之后,这个词在欧洲语言里一直用到今天,意思是「与其慢慢解,不如快刀斩」。二是弗里吉亚人戴的那种顶部向前弯折的软帽。在希腊罗马的图像里,它本来是用来标示「这个人是外国人」的;罗马释放奴隶时戴的是另一种帽子(pileus)。两千年后欧洲人把这两顶帽子认混了,于是法国大革命拿弗里吉亚帽当自由的象征戴上街头,今天它仍印在法国、阿根廷、哥伦比亚等国的国徽或标志上——一个记号的意思,可以在两千年后被彻底改写。一个亡于公元前七世纪的王国,把一顶帽子和一句成语留给了后来的世界。','Two things outlived the kingdom by far. One is the Gordian knot: after Alexander\'s stroke the phrase entered European languages and is still in use, meaning a tangle better cut than picked apart. The other is the soft forward-curling cap. In Greek and Roman images it marked its wearer as a foreigner; the cap Romans gave to freed slaves was a different one, the pileus. Two thousand years later Europeans conflated the two, so the French Revolution put the Phrygian cap on as the emblem of liberty, and it still appears on the arms or insignia of France, Argentina and Colombia among others. What a symbol means can be rewritten entirely, two millennia after the fact. A kingdom that ended in the seventh century BC left the world a hat and a figure of speech.'] } },
{ l:'me', s:'mideast', v:0, n:'亚述', k:[[-1365,0],[-1225,.35],[-883,.45],[-705,.6],[-670,.7],[-612,.15],[-609,0]], b:'铁器军队与攻城塔踏平两河;也留下了三万块泥板。',
  e:{ n:'Assyria', w:'Neo-Assyrian Empire', b:'Iron armies and siege towers flattened Mesopotamia — and left 30,000 clay tablets.', d:'The Assyrians turned war into an engineering discipline: iron weapons, siege towers, sapper corps, victories cut into stone reliefs and circulated empire-wide, conquered cities deported whole. On that machine Assyria built the first empire to hold both Mesopotamia and Egypt at once. Yet the same king, Ashurbanipal, ordered a copy made of every tablet that could be found and stored in his palace at Nineveh — the collection that is now our key to reading Mesopotamia at all. In 612 BCE a Median-Babylonian coalition stormed Nineveh, and three years later the empire was gone.', f:{ 'Peak':'7th c. BCE (Ashurbanipal)', 'Center':'Nineveh', 'Figures':'Ashurbanipal, Sennacherib, Shammuramat, Nabu-zuqup-kenu', 'Legacy':'The library of Nineveh, siegecraft and iron armies' } },
  f:{ '鼎盛':'前7世纪(亚述巴尼拔)', '中心':'尼尼微', '人物':'亚述巴尼拔、辛那赫里布、萨米-拉马特、纳布-祖库普-凯努', '成就':'尼尼微图书馆、铁器军队与攻城术' },
  qh:{ born:['不吃掉别人,就被别人吃掉','Eat, or be eaten'],
       rule:['把被征服的人整族搬走,连根打散','Whole peoples moved away, and their roots broken'],
       money:['帝国的收入表,就是战报','The revenue ledger was the war report'],
       power:['有了攻城塔和地道,城墙不再保险','With siege towers and tunnels, walls stopped working'],
       fall:['扩张停下的那天,倒计时就开始了','The day expansion stopped, the clock started'],
       legacy:['读懂两河文明的钥匙,埋在一座图书馆里','The key to Mesopotamia lay in one buried library'] },
  q:{ born:['两河北部无险可守、四面强邻,底格里斯河上游的亚述人把军事化当成了生存方式——不吃掉别人,就被别人吃掉。','Northern Mesopotamia had no natural walls and strong neighbours on every side; the Assyrians of the upper Tigris made militarism a way of survival — eat or be eaten.'],
      rule:['王直辖的行省取代附庸国,驿道传递军情;最狠的一招是强制迁徙——把被征服民族整体搬走,打散一切反抗的根。','Royal provinces replaced vassal kings and post roads carried intelligence; the harshest tool was mass deportation — whole peoples moved wholesale, uprooting any base for revolt.'],
      money:['战争经济:贡赋、掠夺,加上对商路的控制。帝国的收入表就是战报。','A war economy: tribute, plunder and control of the trade roads. The imperial balance sheet was a war report.'],
      power:['最早的常备军、普及的铁兵器、专业的攻城工程——攻城塔与地道让城墙不再保险。战争技术领先所有邻居一个身位。','The first standing army, iron weapons in quantity and professional siegecraft — towers and tunnels made city walls unsafe. In the technology of war Assyria stood a full step ahead of every neighbour.'],
      fall:['战争经济必须不停打仗才能自转,而靠恐惧的统治换不来认同;亚述巴尼拔死后即起内战,被压制的米底与巴比伦联手攻陷尼尼微,三年后帝国最后的残余也被抹掉——扩张停止之日,就是倒计时开始之时。','A war economy must keep fighting to keep running, and rule by terror wins no loyalty. Civil war followed the death of Ashurbanipal; the subjugated Medes and Babylonians joined forces and took Nineveh, and within three more years the last remnant was gone. The day expansion stopped, the countdown began.'],
      legacy:['尼尼微图书馆的三万块泥板,是今天读懂两河文明的钥匙;它发明的行省直辖制,被波斯继承并放大。','The thirty thousand tablets of Nineveh remain the key to reading Mesopotamia, and its system of directly ruled provinces was inherited and enlarged by Persia.'] },
  d:'亚述人把战争做成了一门工程:铁制兵器、攻城塔、工兵编制,战果刻成石板传遍全境,被征服的城市整族迁走。靠这套机器,亚述建起第一个同时管住两河与埃及的帝国。但同一个王亚述巴尼拔,又下令把两河流域能找到的泥板全抄一份收进尼尼微王宫——这批泥板后来成了今人读懂美索不达米亚的钥匙。前612 年米底与巴比伦联军攻陷尼尼微,帝国三年后彻底消失。',
  gl:[ { a:-883, b:-612, k:'tech', t:['攻城术与铁器军队','Siegecraft and iron armies'], d:['攻城塔、地道与工兵编制,当时最专业的战争机器。','Siege towers, sapping and engineer corps — the most professional war machine of its day.'] },
       { a:-668, b:-627, k:'thought', t:['尼尼微泥板图书馆','The library at Nineveh'], d:['约三万块泥板,《吉尔伽美什史诗》靠它传世。','Some 30,000 tablets; the Epic of Gilgamesh survives because of it.'] } ] },
{ l:'me', s:'mideast', v:1, n:'腓尼基', k:[[-1200,0],[-900,.3],[-600,.2],[-300,0]], b:'地中海商船民族,字母文字经其传入欧洲。',
  e:{ n:'Phoenicia', b:'Mediterranean traders whose alphabet became the West\'s.', d:'The Levantine port cities traded across the whole Mediterranean and planted Carthage; their 22 bookkeeping letters, once the Greeks added vowels, became nearly every Western script — including the one you are reading.', f:{ 'Peak':'1000–800 BCE', 'Center':'Tyre, Sidon', 'Figures':'Hiram I', 'Legacy':'The alphabet, purple dye, the Mediterranean sea routes' } },
  f:{ '鼎盛':'前1000—前800年', '中心':'推罗、西顿', '人物':'希兰一世', '成就':'22个字母、紫色染料、地中海航路' },
  ct:['城邦与海外据点','City-states and overseas footholds'],
  co:[ { n:['推罗','Tyre'], c:['今黎巴嫩南部','southern Lebanon today'], m:1, g:['黎凡特的母城','Mother cities on the Levantine coast'], x:['各城独立、轮流领头,谁也管不了谁;推罗最盛时把据点一直建到直布罗陀以外','the cities were independent and led by turns, none commanding the rest; at its height Tyre planted footholds beyond Gibraltar'] },
       { n:['西顿','Sidon'], c:['今黎巴嫩南部','southern Lebanon today'], g:['黎凡特的母城','Mother cities on the Levantine coast'] },
       { n:['比布鲁斯','Byblos'], c:['今贝鲁特以北','north of Beirut today'], g:['黎凡特的母城','Mother cities on the Levantine coast'] },
       { n:['阿尔瓦德','Arwad'], c:['今叙利亚外海小岛','an island off Syria today'], g:['黎凡特的母城','Mother cities on the Levantine coast'] },
       { n:['加迪尔','Gadir'], c:['今西班牙加的斯','Cádiz in Spain today'], g:['西边的据点','Footholds in the west'], x:['最大的一支是北非的迦太基,后来强到自成一方霸主——它在本图上另有一条色带','the largest was Carthage in North Africa, which grew strong enough to stand on its own — it has a band of its own on this chart'] },
       { n:['乌提卡','Utica'], c:['今突尼斯北部','northern Tunisia today'], g:['西边的据点','Footholds in the west'] },
       { n:['摩提亚','Motya'], c:['西西里西部','western Sicily'], g:['西边的据点','Footholds in the west'] },
       { n:['帕诺尔莫斯','Panormus'], c:['今巴勒莫','Palermo today'], g:['西边的据点','Footholds in the west'] } ],
  qh:{ born:['地少港好,地理逼着人下海','Little land, good harbours: the coast pushed them to sea'],
       rule:['它是一张网络,不是一个帝国','It was a network, not an empire'],
       money:['卖的与其说是货,不如说是「运到」','What they sold was less the goods than the delivery'],
       power:['夜里认北极星,所以敢开远洋','They steered by the pole star, so they dared go far'],
       fall:['没被一次打垮,是被一个个收编掉的','Never broken at a blow: absorbed one empire at a time'],
       legacy:['今天的字母表,起点是他们那22个','The alphabet you are reading starts from their twenty-two'] },
  q:{ born:['黎凡特海岸是一条背靠高山、面朝大海的窄地,耕地少得养不活多少人,却有雪松林和天然良港——这样的地理几乎是在逼当地人下海。公元前1200年前后迈锡尼与埃及的海上势力退潮,地中海贸易出现真空,推罗、西顿、比布鲁斯这些城邦顺势填了进去。','The Levantine coast is a narrow strip with mountains behind and sea in front — too little farmland to feed many people, but cedar forests and good natural harbours. The geography all but pushed its people onto the water. When Mycenaean and Egyptian sea power receded around 1200 BCE, a vacuum opened in Mediterranean trade, and city-states like Tyre, Sidon and Byblos moved into it.'],
      rule:['腓尼基从来不是一个统一国家,而是一串各自独立的商业城邦,由国王与商人贵族的议事会共同治理,城与城之间既合作又竞争。海外据点也不是行政意义上的殖民地,母城与子城主要靠共同的神祇、家族与商业信用维系——是网络,不是帝国。','Phoenicia was never one state but a string of independent commercial city-states, each governed by a king together with a council of merchant nobles, cooperating and competing by turns. Its overseas footholds were not administrative colonies either: mother city and daughter city were held together mainly by shared gods, family ties and commercial credit — a network, not an empire.'],
      money:['赚钱靠三样别处买不到的东西加一样别人做不到的事:黎巴嫩雪松(埃及和两河都缺大木材)、从骨螺提炼的紫色染料(极费工、极昂贵,后来成了帝王专用色)、玻璃器,以及把这一切在整个地中海之间倒手的转口贸易。他们卖的与其说是货,不如说是「运到」这项服务。','They sold three things nobody else had and one thing nobody else could do: Lebanese cedar (Egypt and Mesopotamia had no large timber), purple dye extracted from murex shells (so laborious and costly it became the colour of royalty), glassware — and the carrying trade that moved all of it around the Mediterranean. What they really sold was less cargo than delivery.'],
      power:['力量不在陆军而在航海:深水船体、夜间靠北极星定位、沿岸链式据点让远航能补给。据希罗多德记载,埃及法老尼科曾派腓尼基船队环航非洲,历时三年——真假仍有争论,但这个故事本身说明当时人相信腓尼基人做得到。','Their power lay in seamanship, not armies: deep-water hulls, navigation by the pole star at night, and a chain of coastal stations that let long voyages resupply. Herodotus records that Pharaoh Necho sent a Phoenician fleet around Africa over three years; whether it happened is still argued, but the story itself shows that people then believed Phoenicians could do it.'],
      fall:['腓尼基城邦从未被一次击垮,而是被一个接一个的大陆帝国逐个收编:亚述、巴比伦、波斯先后要求纳贡,波斯时期腓尼基舰队干脆成了波斯海军的主力。公元前332年亚历山大围攻推罗七个月并将其攻破,东地中海的商业重心转向希腊化城市,西边的接力棒则早已交给了迦太基。','The Phoenician cities were never broken at a stroke; they were absorbed one by one by successive land empires — Assyria, Babylon and Persia each demanded tribute, and under Persia the Phoenician fleet effectively became the Persian navy. Alexander besieged Tyre for seven months and took it in 332 BCE, after which commercial gravity in the eastern Mediterranean shifted to the Hellenistic cities, while in the west the baton had long since passed to Carthage.'],
      legacy:['最大的遗产是22个辅音字母。字母的雏形出现得更早(西奈半岛一带的原始迦南文字),但腓尼基人把它标准化并随商船带到各处,希腊人加上元音,再经伊特鲁里亚人传给罗马,最终成为今日西方各种文字的共同祖先。地中海一圈城市——加的斯、巴勒莫、卡塔赫纳、突尼斯——的起点也在这张商网上。','The great bequest is a 22-letter consonantal alphabet. Its ancestor is older — the proto-Canaanite script of the Sinai region — but the Phoenicians standardized it and carried it everywhere by ship; the Greeks added vowels, the Etruscans passed it to Rome, and it became nearly every Western script in use today. A ring of Mediterranean cities — Cádiz, Palermo, Cartagena, Tunis — also began as nodes on that trading web.'] },
  d:'黎凡特海岸的城邦商人把生意做遍地中海,在北非建立迦太基;他们为记账发明的22个辅音字母,经希腊人加上元音,演化成今天几乎所有西方文字——你此刻读到的拉丁字母,源头就在腓尼基的账本上。' },
{ l:'me', s:'mideast', v:2, n:'新巴比伦', k:[[-626,0],[-605,.4],[-570,.6],[-562,.55],[-539,0]], b:'伊什塔尔门与空中花园传说;八十七年后不战而降。',
  e:{ n:'Neo-Babylon', w:'Neo-Babylonian Empire', b:'The Ishtar Gate and the legend of the Hanging Gardens; eighty-seven years later it surrendered without a fight.', d:'With Assyria gone, Babylon rose again. Nebuchadnezzar II reigned forty-three years and rebuilt Babylon into the largest city of its day: the blue-glazed Ishtar Gate, a bridge across the Euphrates, and the fabled Hanging Gardens — whose site has never been found. He destroyed the kingdom of Judah and deported its people, an exile that entered the Bible. Meanwhile Babylon\'s priests were doing something else: recording the sky night after night for centuries, compiling the data Greek astronomy would later be built on. In 539 BCE Cyrus of Persia arrived and the city opened its gates.', f:{ 'Peak':'Nebuchadnezzar II (605–562 BCE)', 'Center':'Babylon', 'Figures':'Nebuchadnezzar II', 'Legacy':'The Ishtar Gate, Babylonian astronomy, the legend of the Hanging Gardens' } },
  f:{ '鼎盛':'尼布甲尼撒二世(前605—前562)', '中心':'巴比伦', '人物':'尼布甲尼撒二世', '成就':'伊什塔尔门、巴比伦天文、空中花园传说' },
  qh:{ born:['不是白手起家,是接盘','It did not start from nothing; it took over'],
       rule:['神庙既是信仰,也是金库和法庭','The temple was faith, treasury and court at once'],
       money:['粮仓加商路,神庙还兼放贷','A granary on a trade road, with the temple lending'],
       power:['一千多年的威望,本身就是资本','A thousand years of prestige was itself capital'],
       fall:['堡垒是从里面打开的','The fortress was opened from the inside'],
       legacy:['几百年逐夜记录的星象,成了地基','Centuries of nightly star records became the foundation'] },
  q:{ born:['亚述崩盘留下真空,巴比伦联合米底瓜分了遗产——它不是白手起家,是接盘。','The collapse of Assyria left a vacuum; Babylon and the Medes divided the estate. It did not start from nothing — it inherited.'],
      rule:['沿用亚述的行省框架,但更倚重神庙:马尔杜克祭司集团既是信仰中心,也是金库和法庭。','It kept the Assyrian provincial frame but leaned on the temples: the priesthood of Marduk was faith, treasury and court in one.'],
      money:['灌溉农业撑起的两河粮仓,加上波斯湾到地中海的商路枢纽;神庙同时经营放贷。','The irrigated granary of Mesopotamia plus the crossroads of trade from the Gulf to the Mediterranean; the temples also ran the lending business.'],
      power:['接收了亚述的制度机器,又有巴比伦一千多年的文化威望;尼布甲尼撒的大建设把财富和人才都吸进城里。','It took over the institutional machinery of Assyria and added a thousand years of Babylonian prestige; the great building programme of Nebuchadnezzar drew wealth and talent into the city.'],
      fall:['只强盛了一代人。据流传下来的记载(多出自胜利者波斯之手),末代王纳波尼德冷落马尔杜克祭司集团,城内精英对王室离心;波斯军在城外打赢关键一战后,巴比伦城门不战而开——堡垒是从里面打开的。','The brilliance lasted one generation. The surviving accounts — written mostly by the Persian victors — say the last king, Nabonidus, alienated the priesthood of Marduk, and the city elite drifted from the crown; after Persia won a decisive battle outside the walls, the city gates opened without a fight. The fortress was unlocked from within.'],
      legacy:['几百年逐夜积累的天文记录,成了希腊天文学的地基;伊什塔尔门立在柏林;「巴比伦」从此成为大城的代名词。','Centuries of nightly sky records became the foundation of Greek astronomy; the Ishtar Gate stands in Berlin; and Babylon itself became a byword for the great city.'] },
  d:'亚述一倒,巴比伦重新翻身。尼布甲尼撒二世在位四十三年,把巴比伦修成当时世界最大的城:蓝釉砖砌的伊什塔尔门、横跨幼发拉底河的大桥,以及传说中的空中花园——不过本地泥板从未提过它,遗址也一直没有找到。他灭掉犹大国、把居民掳往巴比伦,这段"巴比伦之囚"写进了《圣经》。与此同时,巴比伦的祭司在做另一件事:逐夜记录星象,几百年不断,那批数据后来成了希腊天文学的地基。前539 年波斯的居鲁士兵临城下,巴比伦不战而降。',
  gl:[ { a:-626, b:-539, k:'tech', t:['巴比伦天文','Babylonian astronomy'], d:['连续观测数百年,周期预测成为希腊天文的底本。','Centuries of records — the base Greek astronomy built on.'] },
       { a:-605, b:-562, k:'art', t:['伊什塔尔门与空中花园','The Ishtar Gate and the Hanging Gardens'], d:['蓝釉砖浮雕的城门今在柏林;空中花园只见于后世记载,本地泥板无载,遗址也未找到。','The blue-glazed gate now stands in Berlin; the gardens are known only from texts.'] } ] },
{ l:'me', s:'mideast', v:0, n:'迦太基', k:[[-814,0],[-500,.4],[-264,.5],[-146,0]], b:'腓尼基人的北非殖民城,西地中海霸主,与罗马三战而亡。',
  e:{ n:'Carthage', b:'Phoenician colony turned western Mediterranean hegemon; destroyed by Rome.', d:'Hannibal crossed the Alps and annihilated Rome\'s army at Cannae — Rome\'s deepest terror. Three Punic Wars later the city was razed; "Carthago delenda est" became the byword for no mercy.', f:{ 'Peak':'early 3rd c. BCE', 'Center':'Carthage', 'Figures':'Hannibal', 'Legacy':'Western Mediterranean trade empire' } },
  f:{ '鼎盛':'前3世纪初', '中心':'迦太基城', '人物':'汉尼拔', '成就':'西地中海商业霸权' },
  qh:{ born:['所有东西向的航线,都得从门口过','Every east-west route had to pass its door'],
       rule:['打了败仗的将军,可能被自己人处死','A general who lost could be executed by his own'],
       money:['自己铸钱,却拿钱去雇别人的军队','It minted its own coin, and hired other people to fight'],
       power:['汉尼拔带的,是一支多语言的军队','Hannibal led an army of many languages'],
       fall:['兵是买来的,不是长出来的','Its soldiers were bought, not born'],
       legacy:['为了打赢它,罗马被迫学会了海战','To beat it, Rome had to learn the sea'] },
  q:{ born:['据传说公元前814年推罗的移民在突尼斯湾建城,选址正对西西里岛与非洲之间最窄的海峡——所有东西向的地中海航线都要从门口经过。母城推罗被亚述和巴比伦削弱后,这个「分店」逐渐独立并接手了整个西地中海的腓尼基商网。','Tradition dates the founding to 814 BCE, when settlers from Tyre built a city on the Gulf of Tunis, facing the narrowest channel between Sicily and Africa — every east-west route in the Mediterranean passed its door. As Assyria and Babylon weakened the mother city of Tyre, the branch office grew independent and took over the whole western Phoenician trading network.'],
      rule:['迦太基是商人寡头共和国:两名「苏菲特」由选举产生、任期一年,元老院掌握实权,还有一个104人法庭专门审查将领——打了败仗的统帅可能被处死。亚里士多德在《政治学》里专门讨论过迦太基政制并给予好评,认为它在王制、贵族制与民主之间取得了平衡。','Carthage was a merchant oligarchy: two suffetes elected for one-year terms, a senate holding the real power, and a court of 104 that audited generals — a commander who lost could be executed. Aristotle discussed the Carthaginian constitution approvingly in the Politics, judging that it balanced monarchy, aristocracy and democracy.'],
      money:['收入有三块:地中海转口贸易(锡、银、奴隶、谷物、织物),北非内陆的大型农庄(迦太基人马戈写的农书后来被罗马元老院下令译成拉丁文,可见其技术之先进),以及西班牙的银矿。它铸自己的钱,却常年用铸币去雇别人的军队。','Income came in three streams: the carrying trade of the Mediterranean (tin, silver, enslaved people, grain, cloth), large estates in the North African interior — the Carthaginian Mago wrote a farming manual so advanced that the Roman senate later ordered it translated into Latin — and the silver mines of Spain. Carthage minted its own coin, and spent much of it hiring other people\'s armies.'],
      power:['海军是国家的主力:多列桨战船、专业船坞(考古发现的圆形军港可同时容纳上百艘船)、以及一串从西西里到西班牙的港口据点。陆军则主要靠雇佣与征募的联军——利比亚步兵、努米底亚骑兵、伊比利亚剑士、巴利阿里投石手,汉尼拔翻越阿尔卑斯山时带的正是这样一支多语言的军队。','The navy was the state\'s main arm: multi-banked warships, professional shipyards (the excavated circular naval harbour could hold well over a hundred vessels at once), and a chain of ports from Sicily to Spain. The army was largely mercenary and allied — Libyan infantry, Numidian cavalry, Iberian swordsmen, Balearic slingers — and it was such a multilingual force that Hannibal led over the Alps.'],
      fall:['三次布匿战争打掉了迦太基,但原因不是「罗马太强」这么简单。结构性劣势有三层:一个海权商业国家要在陆上长期消耗,兵源是买来的而非再生的,罗马却能从意大利同盟中一批批征召公民兵,输得起更多次;第一次战争失去西西里并背上巨额赔款后,付不出军饷的雇佣兵反过来叛乱几乎摧毁国家;汉尼拔在意大利屡胜十余年,本土的寡头集团却始终不肯下重注增援,梅陶罗河边援军被歼后大势已去。公元前202年扎马战败,公元前146年城破被毁。','Three Punic Wars destroyed Carthage, but not simply because Rome was stronger. Three structural weaknesses stack up. A maritime commercial state had to fight a long attrition war on land, and its soldiers were bought rather than reproduced, while Rome could call up citizen levies from its Italian allies batch after batch and afford to lose more often. After the first war cost Sicily and imposed a crushing indemnity, unpaid mercenaries revolted and nearly destroyed the state from within. And though Hannibal won victory after victory in Italy for more than a decade, the oligarchs at home never committed to reinforcing him; once the relief army was destroyed at the Metaurus the cause was lost. Defeat at Zama came in 202 BCE, and the city fell and was razed in 146 BCE.'],
      legacy:['汉尼拔在坎尼的两翼包抄至今仍是军校课堂上的标准范例,「迦太基必须毁灭」成了不留余地的代名词。更长远的影响是:为了打赢迦太基,原本没有海军传统的罗马被迫学会造船和海战,由此走上了成为地中海主人的路;而迦太基留下的北非农业区,后来成了罗马城的粮仓之一。','Hannibal\'s double envelopment at Cannae is still taught as the model of its kind in military academies, and \'Carthage must be destroyed\' became shorthand for leaving no room for compromise. The longer consequence is this: to beat Carthage, a Rome with no naval tradition was forced to learn shipbuilding and sea warfare — which set it on the road to mastering the Mediterranean. And the North African farmland Carthage developed later became one of Rome\'s granaries.'] },
  d:'汉尼拔率战象翻越阿尔卑斯山、在坎尼全歼罗马大军,是罗马史上最深的恐惧;但三次布匿战争后城市被夷为平地。老加图那句在元老院重复了无数遍的"迦太基必须毁灭",成了不留余地的代名词。' },
{ l:'me', s:'mideast', v:0, n:'波斯(阿契美尼德)', k:[[-550,0],[-539,.7],[-480,1],[-400,.8],[-330,0]], b:'首个横跨三洲的超级帝国,从印度河到爱琴海。',
  e:{ n:'Achaemenid Persia', w:'Achaemenid Empire', b:'The first superpower spanning three continents.', d:'Cyrus founded the empire on tolerance, freeing the Babylonian captives; Darius ran it from the Indus to the Aegean through satrapies, royal roads and coinage — the largest empire yet seen. Twice checked in Greece, it fell to Alexander, but its statecraft was copied by every successor.', f:{ 'Peak':'Darius I (522–486 BCE)', 'Center':'Persepolis, Susa', 'Figures':'Cyrus, Darius, Atossa, Parnaka, Scylax of Caryanda, Ctesias', 'Legacy':'Satrapies, Royal Road, tolerance' } },
  f:{ '鼎盛':'大流士一世(前522—前486)', '中心':'波斯波利斯、苏萨', '人物':'居鲁士、大流士、阿托莎、帕尔纳卡、斯基拉克斯、克特西亚斯', '成就':'行省制、御道驿传、宗教宽容' },
  qh:{ born:['投降的成本,比抵抗低得多','Surrender cost far less than resistance'],
       rule:['不要你变成波斯人,只要你纳税出兵','You need not become Persian, only pay and serve'],
       money:['一条两千七百公里的路,几天送到','A road of 2,700 kilometres, and letters in days'],
       power:['靠治理术省下的力气,比军队还多','Good governance saved more strength than any army'],
       fall:['输给希腊没伤到根,内斗才伤到了','The Greek wars did not break it; the infighting did'],
       legacy:['这套治理工具箱,后来被反复借用','This toolkit of rule was borrowed again and again'] },
  q:{ born:['伊朗高原西南的波斯人本是米底王国的属部,公元前550年居鲁士二世反过来推翻了米底,随后十余年内连灭吕底亚与巴比伦。它兴起得这么快,一半原因是打法:居鲁士对被征服者不毁其庙、不废其俗,还释放了巴比伦的犹太人让他们回耶路撒冷重建圣殿——投降的成本因此比抵抗低得多。','The Persians of the southwestern Iranian plateau began as subjects of Media; in 550 BCE Cyrus II turned the tables and overthrew it, then took Lydia and Babylon within little more than a decade. Half the reason for that speed was method: Cyrus left conquered peoples their temples and customs and released the Judean exiles in Babylon to rebuild their temple in Jerusalem — which made surrender far cheaper than resistance.'],
      rule:['大流士把帝国划成二十来个行省(萨特拉庇),总督管民政、另设将领管军队、再派「王之眼」巡查——三权互相牵制,是后世无数帝国抄过的作业。中央用阿拉美语作行政通用语,地方保留自己的法律、宗教和语言;帝国不要求你变成波斯人,只要求你纳税和出兵。','Darius divided the empire into about twenty satrapies, with a governor over civil affairs, a separate commander over troops, and travelling inspectors known as the king\'s eyes — three powers checking one another, a design later empires copied endlessly. Aramaic served as the administrative lingua franca while provinces kept their own laws, religions and languages: the empire did not ask you to become Persian, only to pay taxes and send soldiers.'],
      money:['各行省按固定额度缴纳贡赋(希罗多德留下一份清单,属单方记载,数额未必准确),大流士铸造金币「大流克」与银币,使跨区域交易有了统一尺度。真正的经济基础设施是御道:从苏萨到萨迪斯约两千七百公里,沿途设驿站换马,王室急件几天可达——道路降低的不只是行军时间,还有收税与做生意的成本。','Each satrapy paid a fixed tribute — Herodotus preserves a schedule, but it is a single source and the figures need caution — and Darius minted the gold daric and silver coins that gave cross-regional trade one standard. The real economic infrastructure was the Royal Road: some 2,700 kilometres from Susa to Sardis, with posting stations to change horses, so royal dispatches crossed it in days. Roads cut more than marching time; they cut the cost of taxing and of trading.'],
      power:['军事上靠三层结构:王室常备的精锐(希罗多德记载有一支员额恒为一万、缺一即补的王室精锐并称之为「不死军」,这属单方记载),各行省征调的多民族部队,以及腓尼基与伊奥尼亚人提供的海军。但更省力的是治理术——保留地方精英与信仰,让统治成本低到能撑起一个约五百五十万平方公里、一千七百多万人口(约占当时全世界的百分之十七)的帝国。','Militarily it worked in three layers: a royal elite corps Herodotus called the Immortals, kept always at ten thousand by immediate replacement; multi-ethnic levies raised from the satrapies; and a navy supplied by Phoenicians and Ionians. But governance did more of the work than force. Keeping local elites and local faiths in place kept the cost of rule low enough to hold roughly 5.5 million square kilometres and over 17 million people — about seventeen percent of humanity then alive.'],
      fall:['两次远征希腊受挫并未动摇帝国的根基,真正的问题在内部,而且是几股力量同时作用:公元前4世纪宫廷弑君与继承争斗频发,埃及数度独立,西部几个大总督接连叛乱,中央对边缘的控制力下滑。公元前334年亚历山大东征,格拉尼库斯、伊苏斯、高加米拉三战击垮波斯野战军,大流士三世逃亡途中被自己的总督所杀,帝国二百二十年而终。','The failed expeditions against Greece did not shake the empire\'s foundations; the real trouble was internal, and several forces worked at once. Through the fourth century BCE the court saw repeated assassinations and succession fights, Egypt broke away more than once, several western satraps revolted in turn, and the centre\'s grip on the periphery slipped. Alexander invaded in 334 BCE and destroyed the Persian field armies at the Granicus, Issus and Gaugamela; Darius III was killed in flight by one of his own satraps, and the empire ended after 220 years.'],
      legacy:['行省制、驿传、多语言行政与宗教宽容这套治理工具箱,被亚历山大、塞琉古、罗马乃至后来的伊斯兰帝国反复取用。阿拉美字母沿着帝国的公文体系向东扩散,后来演化出多种亚洲文字;波斯波利斯的浮雕上,各族使者带着本地物产依次朝贡的画面,是一份关于多民族帝国如何自我想象的图像档案。','The toolkit — provinces, relay posts, multilingual administration, religious tolerance — was picked up again and again by Alexander, the Seleucids, Rome and later the Islamic empires. The Aramaic script spread eastward along the empire\'s paperwork and gave rise to several Asian writing systems. And the reliefs at Persepolis, showing delegation after delegation bringing local produce as tribute, are a pictorial archive of how a multi-ethnic empire imagined itself.'] },
  d:'居鲁士以宽容立国,释放巴比伦之囚;大流士以二十行省、御道与统一铸币治理从印度河到爱琴海的疆域——此前人类史上最大的帝国。两次远征希腊受挫,二百年后亡于亚历山大,但其治理术被后继帝国反复沿用。' },
{ l:'me', s:'west', v:0, n:'希腊化王朝', k:[[-331,0],[-300,.6],[-150,.4],[-30,0]], b:'亚历山大身后的塞琉古与托勒密:希腊文化统治近东三百年。',
  e:{ n:'Hellenistic States', w:'Hellenistic period', b:'Alexander\'s successors; Greek culture rules the Near East for three centuries.', d:'Alexander\'s generals carved up his empire, Ptolemies in Egypt and Seleucids in Syria the strongest; Alexandria\'s Library and Museum were the ancient world\'s intellectual hub — Euclid and Archimedes belong to this age. All fell in turn to Rome.', f:{ 'Peak':'3rd c. BCE', 'Center':'Alexandria, Antioch', 'Figures':'Ptolemy I, Euclid, Archimedes', 'Legacy':'Library of Alexandria, Hellenistic science' } },
  f:{ '鼎盛':'前3世纪', '中心':'亚历山大里亚、安条克', '人物':'托勒密一世、欧几里得、阿基米德', '成就':'亚历山大图书馆、希腊化科学' },
  qh:{ born:['合法性不来自血统,来自打下来的地','Legitimacy came not from blood but from conquest'],
       rule:['对希腊人当国王,对埃及人当法老','A king to the Greeks, a pharaoh to the Egyptians'],
       money:['连油和麻布都由国家专卖','Even oil and linen were a state monopoly'],
       power:['真正的力量投送方式,是建城','The real way it projected power was founding cities'],
       fall:['请罗马来仲裁王位,等于抵押了主权','Asking Rome to judge the succession pawned the sovereignty'],
       legacy:['希腊的雕法遇上佛教,佛像有了衣纹','Greek carving met Buddhism, and the Buddha got drapery'] },
  q:{ born:['公元前323年亚历山大在巴比伦骤逝,没有能立刻接位的继承人,几位大将随即开打——四十年的「继业者战争」之后,格局大致定型为埃及的托勒密、亚洲的塞琉古与马其顿的安提柯。这些王朝的合法性不来自血统或本地传统,而来自「我是亚历山大的战友、我的枪打下了这块地」。','Alexander died suddenly at Babylon in 323 BCE with no successor able to take over, and his generals went to war. After forty years of fighting among the Diadochi the map settled into three main blocs: the Ptolemies in Egypt, the Seleucids in Asia and the Antigonids in Macedon. Their legitimacy rested not on descent or local tradition but on the claim: I marched with Alexander, and my spear won this land.'],
      rule:['统治的基本形态是希腊-马其顿少数人管理东方多数人:希腊语是行政语言,新建的移民城市与军事屯垦点是政权的骨架,国王本人就是最高法源,并普遍推行统治者崇拜。托勒密在埃及则采取双重面孔——对希腊人是马其顿国王,对埃及人则以法老形象出现、供养本地祭司集团(罗塞塔石碑正是一份祭司敕令)。','The basic form was a Greek-Macedonian minority administering an eastern majority: Greek was the language of government, newly founded settler cities and military colonies formed the skeleton of the state, the king was himself the supreme source of law, and ruler cults were widespread. In Egypt the Ptolemies wore two faces — Macedonian king to the Greeks, and to Egyptians a pharaoh who endowed the native priesthood (the Rosetta Stone is itself a priestly decree).'],
      money:['托勒密埃及是当时管得最细的经济体:土地登记、按户征税、油和麻布等商品由国家专卖,尼罗河的粮食则是出口硬通货。塞琉古地域辽阔却松散,主要靠城市税与东西商路的过境收益。此外,亚历山大打开波斯国库释放出的大量金银涌入流通,推动了整个地中海东部的货币化。','Ptolemaic Egypt was the most minutely managed economy of its day: land registers, household taxation, state monopolies on goods such as oil and linen, and Nile grain as the hard-currency export. The Seleucid realm was vast but loose, living mainly on city taxes and the traffic of the east-west trade roads. On top of that, the Persian treasuries Alexander opened poured gold and silver into circulation and monetized the whole eastern Mediterranean.'],
      power:['军事上是马其顿方阵加上新学来的战象(塞琉古从印度换得),外加雇佣兵与移民兵源。但这些王朝真正的力量投送方式是建城:亚历山大里亚、安条克、塞琉西亚这些新城既是驻军点、税收点,也是希腊语与希腊生活方式的扩散器,亚历山大留下的疆域约五百二十万平方公里,继业诸国瓜分的正是这份遗产。','Militarily it was the Macedonian phalanx plus a new arm, war elephants, which the Seleucids obtained from India, backed by mercenaries and settler levies. But the real way these kingdoms projected power was founding cities: Alexandria, Antioch and Seleucia were garrisons and tax nodes and, at the same time, diffusers of the Greek language and Greek ways of living. The empire Alexander left behind covered some 5.2 million square kilometres, and that inheritance was what the successor kingdoms carved up.'],
      fall:['衰落是内耗与外压同时作用:继业诸国之间几乎每代人都要打一场,消耗了兵源与财政;塞琉古东部被帕提亚和巴克特里亚割走,西部在公元前190年马格尼西亚败于罗马后被迫收缩;托勒密后期宫廷内斗成风,竟需请罗马仲裁王位,等于把主权抵押出去。最终诸王朝相继被罗马吞并,公元前30年埃及成为罗马行省。','Decline came from exhaustion within and pressure without. The successor kingdoms fought each other almost every generation, draining manpower and treasuries. The Seleucids lost their east to Parthia and Bactria, and after defeat by Rome at Magnesia in 190 BCE had to contract in the west. Late Ptolemaic Egypt was consumed by palace feuds and ended up asking Rome to arbitrate its succession — effectively mortgaging its sovereignty. One by one the kingdoms were annexed, and in 30 BCE Egypt became a Roman province.'],
      legacy:['希腊语成为东地中海几百年的通用语,新约最初就是用这种通用希腊语写的。亚历山大里亚的图书馆与缪斯宫把学者集中供养起来,欧几里得的《几何原本》、阿基米德的力学、埃拉托色尼对地球周长的测算都出自这个时代;而希腊雕塑技法东传后与佛教相遇,催生了犍陀罗风格的佛像,把希腊化的写实衣纹与面容带进了佛教艺术。','Greek became the common language of the eastern Mediterranean for centuries; the New Testament was first written in that koine. The Library and Museum of Alexandria kept scholars on salary in one place, and this age produced Euclid\'s Elements, Archimedes\' mechanics and Eratosthenes\' measurement of the earth\'s circumference. Greek sculptural technique travelling east met Buddhism and produced the Gandharan Buddha image, bringing Hellenistic realism in drapery and features into Buddhist art.'] },
  d:'亚历山大骤逝后部将瓜分帝国,埃及的托勒密与叙利亚的塞琉古最强;亚历山大里亚的图书馆与缪斯宫是古代世界的学术中枢,欧几里得的几何与阿基米德的力学皆产于这个时代。诸王朝最终相继被罗马吞并,末代君主是克娄巴特拉。' },
{ l:'me', s:'west', v:1, n:'罗马治下近东', k:[[-64,0],[100,.5],[400,.42],[636,0]], b:'近东七百年在罗马治下;基督教在此诞生并扩散。',
  e:{ n:'Roman Near East', b:'Seven Roman centuries; the cradle of Christianity.', d:'After Pompey\'s conquests the Near East became Rome\'s richest provinces; Christianity was born in Roman Palestine and spread along Roman roads until it captured the empire itself. It remained the Greco-Roman world\'s eastern half until the Arabs came.', f:{ 'Peak':'2nd century', 'Center':'Antioch, Alexandria', 'Figures':'Herod, Zenobia', 'Legacy':'Provincial prosperity, cradle of Christianity' } },
  f:{ '鼎盛':'2世纪', '中心':'安条克、亚历山大里亚', '人物':'希律王、芝诺比娅', '成就':'行省城市繁荣、基督教的摇篮' },
  qh:{ born:['不是打进一个强国,是填了一个空','Not conquest of a strong state, but filling a vacuum'],
       rule:['「罗马人」从族群变成了一种法律身份','Roman stopped being an ethnicity and became a legal status'],
       money:['埃及的粮养着罗马,叙利亚是东方入口','Egypt fed Rome; Syria was the door to the east'],
       power:['和平本身,就是最大的基础设施','Peace itself was the greatest infrastructure'],
       fall:['和波斯打到两败,近东就换了人','It and Persia fought each other empty, and the east changed hands'],
       legacy:['一个行省的边缘信仰,成了西方的宗教','A fringe faith in one province became the religion of the west'] },
  q:{ born:['公元前64年庞培东征,把已经空壳化的塞琉古王国收进版图,设立叙利亚行省——罗马不是打进了一个强国,而是填补了希腊化王朝崩解后留下的权力真空。此后近七百年,从安纳托利亚南缘到埃及的这一整片,成为罗马世界人口最密、城市最多、税收最厚的部分。','In 64 BCE Pompey campaigned east and folded the hollowed-out Seleucid kingdom into Roman territory, creating the province of Syria — Rome did not fight its way into a strong state so much as fill the vacuum left by the collapse of the Hellenistic kingdoms. For nearly seven centuries afterwards, the belt from southern Anatolia to Egypt was the most densely populated, most urbanized and most lucrative part of the Roman world.'],
      rule:['罗马的做法是能省则省:先用附庸王过渡(希律王就是这样的角色),条件成熟再改设总督直辖;希腊式城市保留自己的议会与法律,只要按时纳税、维持治安。公元212年卡拉卡拉敕令把罗马公民权授予帝国境内几乎所有自由民,「罗马人」从此不再是一个族群而是一种法律身份。','Rome economized wherever it could: client kings served as a transitional layer — Herod was one — and direct governorship followed once conditions allowed. Greek-style cities kept their own councils and laws so long as taxes arrived and order held. In 212 CE the Antonine Constitution granted Roman citizenship to almost every free inhabitant of the empire, and \'Roman\' ceased to be an ethnicity and became a legal status.'],
      money:['香料、丝绸、宝石从波斯湾与红海上岸,经帕尔米拉与佩特拉的商队转运,再由地中海航线西行。地方产业也很硬——叙利亚的玻璃、腓尼基的紫染、加利利与北非的橄榄油与酒,都是跨行省的畅销货。','Spices, silk and gems landed from the Persian Gulf and Red Sea, moved by the caravans of Palmyra and Petra, and went west by Mediterranean shipping. Local industry was solid too — Syrian glass, Phoenician purple, and the olive oil and wine of Galilee and North Africa all sold across provinces.'],
      power:['叙利亚是帝国对帕提亚-萨珊的前线大军区,常年驻扎多个军团,道路网既是行军路也是商路。而地中海制海权带来的低运费,才是那种「一个行省的橄榄油能卖到另一个行省」的繁荣的真正原因——和平本身就是最大的基础设施。','Syria was the empire\'s frontline command against Parthia and then Sasanian Persia, with several legions permanently stationed, and its road network carried both armies and cargo. But the deeper cause of the prosperity — the kind where one province\'s olive oil sells in another — was the cheap freight that came with command of the Mediterranean. Peace itself was the largest piece of infrastructure.'],
      fall:['近东脱离罗马是长期损耗的结果:3世纪帝国危机中帕尔米拉的芝诺比娅一度自立,与萨珊的战争几百年反复消耗边境;541年起的查士丁尼瘟疫大幅削减人口与税基;基督教内部围绕基督神人二性的分歧使叙利亚、埃及的教会与君士坦丁堡长期对立,一般认为这削弱了帝国在这些行省的凝聚力。602至628年罗马与波斯的总体战让双方同时精疲力竭,636年雅尔穆克战役后,近东转入阿拉伯人之手。','The Near East left Rome through long attrition. During the third-century crisis Zenobia\'s Palmyra broke away for a time; centuries of war with Sasanian Persia ground down the frontier; the plague that began under Justinian in 541 cut population and tax base sharply; and the dispute over the nature of Christ set the churches of Syria and Egypt against Constantinople for generations, which is generally thought to have weakened the empire\'s hold on those provinces. The total war of 602–628 exhausted Rome and Persia together, and after the battle of Yarmuk in 636 the region passed to the Arabs.'],
      legacy:['基督教诞生在罗马治下的巴勒斯坦,沿着罗马的道路与航线传遍地中海,4世纪末成为帝国国教——一个行省的边缘信仰变成了整个西方世界的宗教框架。同时,叙利亚的学者把希腊哲学与医学典籍译成叙利亚语,这批译本后来又被译成阿拉伯语,成为巴格达翻译运动的直接源头之一。','Christianity was born in Roman Palestine, spread along Roman roads and shipping lanes, and by the end of the fourth century was the empire\'s official religion — a provincial faith became the religious framework of the entire West. At the same time Syrian scholars translated Greek philosophy and medicine into Syriac, and those versions were later rendered into Arabic, making them one of the direct sources of the translation movement in Baghdad.'] },
  d:'庞培东征后,近东成为罗马最富庶的行省群;基督教正是在罗马治下的巴勒斯坦诞生,沿罗马的道路与航线传遍帝国,最终反客为主成为国教。7世纪阿拉伯人到来之前,这里一直是希腊-罗马世界的东半壁。' },
{ l:'me', s:'mideast', v:1, n:'帕提亚·萨珊', k:[[-247,0],[-100,.45],[224,.5],[550,.6],[651,0]], b:'与罗马缠斗数百年的波斯王朝,丝路中段的把关人。',
  e:{ n:'Parthia & Sasanids', w:'Sasanian Empire', b:'Persian dynasties that fought Rome for centuries and kept the Silk Road\'s middle gate.', d:'Parthian horse-archers annihilated Crassus at Carrhae; the Sasanids claimed Persia\'s mantle and battled Rome-Byzantium for four hundred years, once capturing an emperor. The long wars bled both sides — the rising Arabs uprooted it in a few years.', f:{ 'Peak':'6th c. (Khosrow I)', 'Center':'Ctesiphon', 'Figures':'Shapur I, Khosrow I', 'Legacy':'Heavy cavalry, Zoroastrian state church' } },
  f:{ '鼎盛':'6世纪(库思老一世)', '中心':'泰西封', '人物':'沙普尔一世、库思老一世', '成就':'重装骑兵、琐罗亚斯德教国教化' },
  qh:{ born:['用一个更古老的名字,给新政权背书','An older name borrowed to vouch for a new regime'],
       rule:['前一朝松散,后一朝集权,正好相反','The first was loose, the second centralised: opposites'],
       money:['不让罗马人直通东方,自己抽成','Rome was not allowed through; they took the cut'],
       power:['俘虏过一位罗马皇帝,还刻在崖壁上','It captured a Roman emperor, and carved it on a cliff'],
       fall:['和拜占庭对打到两败,阿拉伯人才来','Both sides fought each other empty, and then the Arabs came'],
       legacy:['它的官制,被后来的哈里发整套接手','Its bureaucracy was taken over whole by the caliphs'] },
  q:{ born:['这一条覆盖前后两个波斯王朝。公元前247年,阿萨息斯家族率领的游牧部族在塞琉古的帕提亚行省起事,趁塞琉古忙于西线,一步步把伊朗高原与美索不达米亚收入囊中。公元224年,法尔斯地方贵族阿尔达希尔一世在霍尔木兹德甘击败帕提亚末王,建立萨珊王朝,并自称阿契美尼德的正统继承者——用一个更古老的名字为新政权背书。','This entry covers two Persian dynasties in sequence. In 247 BCE a nomadic group led by the Arsacid house rebelled in the Seleucid province of Parthia and, while the Seleucids were busy in the west, took over the Iranian plateau and Mesopotamia piece by piece. In 224 CE Ardashir I, a noble from Fars, defeated the last Parthian king at Hormozdgan and founded the Sasanian dynasty, proclaiming himself heir to the Achaemenids — using an older name to underwrite a new regime.'],
      rule:['两朝的统治方式几乎相反。帕提亚松散:大贵族家族拥有自己的领地与私兵,国王由贵族会议在王室成员中推举,境内还留着一堆半独立的小王,中央弱而地方强。萨珊则刻意集权:琐罗亚斯德教被立为国教,祭司集团与文官系统并行,库思老一世更改革税制,把按收成分成改为按土地面积与作物定额征税,让财政收入变得可预测——中央从此养得起不依赖贵族的常备军。','The two dynasties ruled in almost opposite ways. Parthia was loose: great noble houses held their own lands and private armies, the king was chosen from the royal family by a council of nobles, and a scatter of semi-independent vassal kings remained — a weak centre and strong regions. The Sasanians deliberately centralized: Zoroastrianism became the state religion, a priestly hierarchy ran alongside a civil bureaucracy, and Khosrow I reformed taxation from a share of each harvest to fixed assessments on land area and crop type, making revenue predictable — which let the centre pay for an army that did not depend on the nobility.'],
      money:['两朝的钱袋子都挂在同一条腰带上:美索不达米亚的灌溉农业是税基,横贯东西的丝路中段是外快。帕提亚人不让罗马商人直通东方,自己当中间商抽成;萨珊的银币德拉克马做工精良、成色稳定,在从中亚到中国的商路上被当作硬通货流通,中国境内的墓葬里就出土过不少。','Both dynasties hung their purse on the same belt: irrigated Mesopotamian agriculture as the tax base, and the middle stretch of the Silk Road as the bonus. The Parthians kept Roman merchants from dealing directly with the East and took a cut as middlemen. Sasanian silver drachms, finely struck and consistent in purity, circulated as hard currency along the routes from Central Asia to China — a good many have been excavated from Chinese tombs.'],
      power:['看家本领是重甲具装骑兵配马上弓手:重骑正面冲击,轻骑边退边射,「帕提亚回马箭」这个词就是这么来的。公元前53年卡莱一战,帕提亚人几乎全歼克拉苏的罗马军团;公元260年萨珊的沙普尔一世在埃德萨俘虏了罗马皇帝瓦莱里安,并把这一幕刻在崖壁上作纪念。萨珊还在此基础上加了边境要塞体系与战象。','The signature combination was armoured cataphracts plus horse archers: heavy cavalry charged, light cavalry shot while retreating — which is where the phrase \'Parthian shot\' comes from. At Carrhae in 53 BCE the Parthians nearly annihilated Crassus\' legions, and in 260 CE the Sasanian Shapur I captured the Roman emperor Valerian at Edessa and had the scene carved into a cliff face. The Sasanians added a system of frontier fortresses and war elephants on top of all this.'],
      fall:['帕提亚的问题是结构性的:贵族割据使中央无法长期集中资源,与罗马的拉锯中泰西封数度被攻陷,内战频发,最终被地方崛起的萨珊取代。萨珊的崩溃则是多因叠加:602至628年与拜占庭的总体战把双方都打空,628年库思老二世被弑后四年间换了十余位君主,洪水破坏了美索不达米亚的灌溉系统,瘟疫削减人口。等阿拉伯军队到来时,它面对的是一个刚打完仗、正在内乱的国家——636年卡迪西亚、642年尼哈万德接连战败,651年末代君主被杀。','Parthia\'s weakness was structural: entrenched nobles kept the centre from concentrating resources for long, Ctesiphon fell to Rome several times in the seesaw wars, civil war was frequent, and in the end a rising regional house, the Sasanians, replaced it. The Sasanian collapse was a pile-up of causes: the total war with Byzantium from 602 to 628 emptied both sides; after Khosrow II was killed in 628 more than ten rulers came and went in four years; floods wrecked the Mesopotamian irrigation system; and plague thinned the population. What the Arab armies met was a state fresh from war and in the middle of its own civil strife — defeats at Qadisiyya in 636 and Nahavand in 642, and the last king killed in 651.'],
      legacy:['萨珊的官僚制度、宫廷礼仪与行政术语被倭马亚和阿拔斯大量继承,阿拔斯的维齐尔制度就带着明显的波斯烙印。琐罗亚斯德教在伊斯兰化后仍有信众延续,一部分教徒迁往印度成为帕西人。波斯的银器、织锦纹样与狩猎图案沿丝路两头扩散,日本正仓院至今藏有这一路的器物;而这段历史后来被菲尔多西写进《列王纪》,成了伊朗人的民族记忆。','Sasanian bureaucracy, court ceremonial and administrative vocabulary were taken over wholesale by the Umayyads and Abbasids — the Abbasid office of vizier bears an unmistakable Persian stamp. Zoroastrianism continued after Islamization, and some of its adherents migrated to India as the Parsis. Persian silverwork, brocade patterns and hunting motifs spread in both directions along the Silk Road, and objects from that current are still kept in the Shosoin repository in Japan. Ferdowsi later wrote this whole era into the Shahnameh, where it became Iran\'s national memory.'] },
  d:'帕提亚的铁甲骑射手在卡莱全歼罗马军团;继起的萨珊自命波斯正统,与罗马-拜占庭缠斗四百年互有胜负,甚至俘虏过罗马皇帝。但长期战争两败俱伤,新兴的阿拉伯人在几年之内将其连根拔起。' },
{ l:'me', s:'mideast', v:1, n:'法蒂玛王朝', k:[[909,0],[969,.3],[1000,.45],[1100,.28],[1171,0]], b:'什叶派的哈里发国:建了开罗与爱资哈尔,与巴格达分庭抗礼。',
  e:{ n:'the Fatimid Caliphate', b:'A Shia caliphate: it built Cairo and al-Azhar and stood against Baghdad.', d:'An Ismaili Shia movement founded a state in North Africa, took Egypt in 969, laid out Cairo and began al-Azhar, and set itself against the Abbasids of Baghdad — so that the tenth-century Islamic world had three rival caliphs at once. It pulled the Indian Ocean trade from the Persian Gulf to the Red Sea, and Cairo grew rich on it. Famine and a war among its own army corps in the 1060s broke its strength, and in 1171 Saladin deposed the last caliph and returned Egypt to Sunni rule.', f:{ 'Peak':'around 1000 (al-Aziz to al-Hakim)', 'Center':'Cairo', 'Figures':'al-Muizz, Jawhar, Ibn al-Haytham', 'Legacy':'Cairo, al-Azhar, the Red Sea trade route' } },
  f:{ '鼎盛':'10世纪末—11世纪初', '中心':'开罗', '人物':'穆仪兹、昭海尔、伊本·海赛姆', '成就':'开罗城、爱资哈尔、印度洋—红海商路' },
  qh:{ born:['开罗这座城,是它建的','Cairo is the city it built'],
       rule:['那时候,同时有三个人自称哈里发','Three men called themselves caliph at the same time'],
       money:['把商路从波斯湾,拉到了红海','It pulled the trade route from the Gulf to the Red Sea'],
       power:['军队是买来的,后来自己人先打起来','The army was bought, and it turned on itself'],
       fall:['尼罗河连年不涨,饿出一场大灾变','The Nile failed for years, and famine did the rest'],
       legacy:['一个什叶派政权,留给逊尼派一所大学','A Shia regime left the Sunnis their most famous school'] },
  q:{ born:['伊斯兰世界因继承问题长期分裂,什叶派中的伊斯玛仪派认为哈里发之位应归阿里与法蒂玛的后裔。909年该派在北非的宣教获得成功,推举出自称法蒂玛后裔的赛义德为哈里发,建国于今突尼斯一带,国号即取自这一世系主张。969年大将昭海尔征服埃及,随即在旧城以北筑新都,取名开罗(意为"胜利者"),第二年动工建造爱资哈尔清真寺。','The Islamic world had long been split over the succession, and among Shia Muslims the Ismailis held that the caliphate belonged to the descendants of Ali and Fatima. In 909 the movement\'s mission in North Africa succeeded, a man claiming that descent was raised up as caliph, and a state was founded in what is now Tunisia, its name asserting the lineage. In 969 its general conquered Egypt and at once laid out a new capital north of the old city, naming it Cairo, "the victorious"; work on the al-Azhar mosque began the year after.'],
      rule:['与巴格达的阿拔斯王朝并立,双方互不承认对方的哈里发身份;10世纪的伊斯兰世界因此同时存在三个自称哈里发的政权(另一个是西班牙的后倭马亚)。统治集团是什叶派少数,治下人口多数是逊尼派与科普特基督徒,因此在宗教上采取相对宽容的实用做法,行政大量任用逊尼派与基督徒官员。政权还向境外派遣宣教士(达伊),这套秘密组织网络是它区别于其他王朝的地方。','It stood against the Abbasid caliphate in Baghdad, each refusing to recognise the other\'s caliph, so that the tenth-century Islamic world had three rulers claiming the title at once — the third being the Umayyads of Spain. The ruling group was a Shia minority over a population mostly Sunni and Coptic Christian, so in practice it was religiously pragmatic and staffed the administration heavily with Sunnis and Christians. It also sent missionaries abroad, and that covert network is what set it apart from other dynasties.'],
      money:['埃及的尼罗河农业加上一条被它重新激活的商路:印度洋来的香料与东方货物,原本多走波斯湾到巴格达,法蒂玛把重心拉到红海一线,经埃及转往地中海。开罗与亚历山大因此成为东西贸易的枢纽,意大利城邦的商人也在此往来。开罗的富庶在当时的记载中屡被提及,福斯塔特的犹太社区文书(开罗藏经库文书)保存了大量这一时期的商业信件,是研究中世纪地中海贸易最重要的原始材料之一。','Nile agriculture plus a trade route it revived: Indian Ocean spices and eastern goods had largely moved through the Persian Gulf to Baghdad, and the Fatimids pulled the traffic to the Red Sea and across Egypt to the Mediterranean. Cairo and Alexandria became the hinge of east-west trade, with Italian merchants working there. Contemporary accounts return again and again to Cairo\'s wealth, and the documents of the Jewish community of Fustat — the Cairo Geniza — preserve a large body of commercial letters from this period, among the most important raw material for the study of medieval Mediterranean trade.'],
      power:['军队不靠本族部落,而是买来的和招募的:柏柏尔人、突厥人、苏丹黑人各成一军。这在早期提供了灵活性,后期却成了祸根——各族军团之间反复火并,朝廷被迫在其间取舍。海军实力是另一个支柱,舰队控制着地中海东部与红海,西西里、马耳他一度在其治下。全盛时的疆域自今突尼斯延伸到叙利亚,并领有麦加、麦地那两圣城的宗主权。','Its army was not tribal but bought and recruited: Berbers, Turks and Sudanese each formed separate corps. That gave flexibility early on and became the poison later, as the corps fought one another repeatedly and the court was forced to take sides. Sea power was the other pillar, its fleets controlling the eastern Mediterranean and the Red Sea, with Sicily and Malta under its rule for a time. At its height the state reached from present-day Tunisia to Syria and held suzerainty over Mecca and Medina.'],
      fall:['多因叠加。1060年代尼罗河连年低水位造成大饥荒,同时各族军团内战,史称"大灾变",国力伤到根本;此后实权长期落在军人出身的维齐尔手里,哈里发形同虚设。外部则先失叙利亚于塞尔柱突厥,1099年十字军又攻占耶路撒冷。1171年,受命前来援助的库尔德将领萨拉丁掌握开罗大权,废去末代哈里发、宣布奉巴格达的阿拔斯为正朔,王朝告终,埃及回到逊尼派统治。','Causes stacked. In the 1060s a run of low Nile floods brought famine while the army corps fought a civil war — a compound disaster that broke the state\'s strength — and thereafter real power lay with military viziers while the caliph was a figurehead. Outside, Syria was lost to the Seljuks and the crusaders took Jerusalem in 1099. In 1171 the Kurdish commander Saladin, sent to help defend Egypt, took control of Cairo, deposed the last caliph and proclaimed allegiance to Baghdad; the dynasty ended and Egypt returned to Sunni rule.'],
      legacy:['开罗此后一直是伊斯兰世界最大的城市之一,爱资哈尔后来在逊尼派手中转型为伊斯兰世界最负盛名的学府——中间被压制了近百年,拜伯尔斯时期才复兴,前后已逾千年——这是一个什叶派政权留给逊尼派的机构。伊斯玛仪派本身并未消失,今天的尼扎里派(其精神领袖称阿迦汗)与穆斯塔里派都源出这一分裂。埃及从此稳定地成为逊尼派地区,但法蒂玛时代建立的红海商路格局延续到了马穆鲁克时期。','Cairo has been one of the largest cities of the Islamic world ever since, and al-Azhar, once in Sunni hands, later became its most prestigious centre of learning — suppressed for the better part of a century in between, revived under the Mamluks, and running for more than a thousand years all told — an institution left by a Shia state to its Sunni successors. The Ismailis themselves did not disappear: today\'s Nizaris, whose spiritual leader is the Aga Khan, and the Mustalis both descend from this split. Egypt settled into being a Sunni country, but the Red Sea trade pattern the Fatimids established carried on into the Mamluk period.'] },
  d:'什叶派伊斯玛仪派在北非建国,969年取埃及,筑开罗、建爱资哈尔,与巴格达的阿拔斯分庭抗礼——10世纪的伊斯兰世界一度有三个哈里发。把印度洋商路从波斯湾拉到红海,开罗因此暴富。1060年代饥荒与军团内战伤及根本,1171年萨拉丁废其末代哈里发,埃及回归逊尼派。' },
{ l:'me', s:'mideast', v:2, n:'阿拉伯哈里发', k:[[622,0],[661,.7],[800,1],[945,.6],[1100,.4],[1258,0]], b:'百年内从西班牙扩至中亚;巴格达是当时世界的学术之都。',
  e:{ n:'Arab Caliphates', w:'Abbasid Caliphate', b:'Spain to Central Asia in a century; Baghdad, the world\'s house of learning.', d:'Under Islam\'s banner the Arabs built an empire from Spain to Central Asia within a century; the Abbasid House of Wisdom translated Greek, Persian and Indian learning — algebra and "Arabic numerals" spread west from here. Turkic soldiers took real power from the 10th century; the Mongols ended it at Baghdad in 1258.', f:{ 'Peak':'Harun al-Rashid (786–809)', 'Center':'Damascus → Baghdad', 'Figures':'Muhammad, Harun al-Rashid, al-Khwarizmi, Hunayn ibn Ishaq, Al-Razi, Zubaida bint Ja\'far', 'Legacy':'Algebra, translation movement, House of Wisdom' } },
  f:{ '鼎盛':'哈伦·拉希德(786—809)', '中心':'大马士革→巴格达', '人物':'穆罕默德、哈伦·拉希德、花剌子米、侯奈因·伊本·伊斯哈格、拉齐、祖拜达', '成就':'代数、翻译运动、智慧宫' },
  qh:{ born:['两个老帝国刚打空,它就来了','Two old empires had just fought each other empty'],
       rule:['哈里发不能随便解释经典','The caliph could not interpret scripture as he pleased'],
       money:['一头连地中海,一头直抵广州','One end on the Mediterranean, the other at Guangzhou'],
       power:['只要纳税不逼改宗,反抗的人就少','Pay the tax, keep your faith, and few chose to resist'],
       fall:['后来禁卫军能随手废立哈里发','In time the guards could make and unmake caliphs'],
       legacy:['代数和算法这两个词,都从这里来','Algebra and algorithm are both words from here'] },
  q:{ born:['7世纪初的时机极其关键:罗马与萨珊刚打完二十多年的总体战,两大帝国的边境防线与财政都已被掏空。与此同时,穆罕默德在麦地那把原本互相仇杀的部落整合进一个以信仰为纽带的共同体,622年的迁徙(希吉拉)成为伊斯兰纪元元年。部落的战斗力第一次有了统一的方向,叙利亚、埃及、伊朗在一代人之内易主。','The timing of the early seventh century was decisive: Rome and Sasanian Persia had just finished more than two decades of total war, and both empires\' frontier defences and finances were hollow. At the same moment, Muhammad in Medina welded feuding tribes into a single community bound by faith, and the hijra of 622 became year one of the Islamic era. For the first time tribal fighting power had one direction, and Syria, Egypt and Iran changed hands within a single generation.'],
      rule:['六百年里统治方式变了两次。倭马亚朝(661—750,都大马士革)本质上是阿拉伯部族贵族的统治,非阿拉伯裔穆斯林地位低一等,行政则大量沿用拜占庭与萨珊留下的旧官吏,直到阿卜杜勒-马利克推行公文阿拉伯语化和统一铸币。阿拔斯朝(750—1258,都巴格达)改成了波斯式的官僚帝国:维齐尔总揽政务,宗教学者(乌理玛)独立发展出几大教法学派,哈里发不能随意解释经典——政权与教法从此互相制约。','The way of ruling changed twice over six hundred years. The Umayyads (661–750, capital Damascus) were essentially a rule of Arab tribal aristocracy, with non-Arab Muslims holding second-class standing, and the administration ran largely on inherited Byzantine and Sasanian officials until Abd al-Malik Arabized the paperwork and unified the coinage. The Abbasids (750–1258, capital Baghdad) became a Persian-style bureaucratic empire: a vizier ran the government, while religious scholars developed the major schools of law independently, so that the caliph could not simply reinterpret scripture at will — state and law now checked each other.'],
      money:['财政两根支柱贯穿两朝:土地税(哈拉吉)与非穆斯林缴纳的人头税(吉兹亚)。金第纳尔与银迪尔汗构成双本位,汇票与合伙契约等商业工具让长途生意可以不带现金上路;巴士拉与巴格达的商人网络一头连着地中海,一头经海路直抵中国广州——一个横跨两洋的贸易区被同一套货币与商业规则连了起来。','Two fiscal pillars ran through both dynasties: the land tax kharaj and the jizya paid by non-Muslims. Gold dinars and silver dirhams formed a bimetallic standard, while instruments such as transferable bills and partnership contracts meant long-distance business no longer had to travel with the cash. Merchant networks out of Basra and Baghdad reached the Mediterranean at one end and, by sea, Guangzhou in China at the other — a trading zone spanning two oceans was tied together by one currency and one set of commercial rules.'],
      power:['早期靠的是机动性与低统治成本:骆驼与骑兵在半干旱地带来去自如,而对被征服者只要求纳税、不强制改宗,抵抗的动力因此大大降低。阿拔斯时期兵源换成呼罗珊军,再后来大量使用突厥奴隶出身的骑兵——战斗力上去了,却也埋下了军人干政的种子。版图在8世纪20年代的倭马亚朝达到顶点,约一千一百万平方公里、三千四百万人口,约占当时世界的六分之一。','Early strength lay in mobility and cheap rule: camels and cavalry moved freely across semi-arid ground, and conquered peoples were asked for taxes rather than conversion, which sharply lowered the incentive to resist. Under the Abbasids the army came first from Khorasan and later relied heavily on cavalry of Turkish slave origin — more effective troops, but also the seed of military interference in politics. Territory peaked under the Umayyads in the 720s at some 11 million square kilometres and about 34 million people, roughly a sixth of the world at the time.'],
      fall:['解体是渐进的、多因的。帝国过大而通讯有限,各地总督逐渐世袭化,西班牙的后倭马亚、北非与埃及的法蒂玛早已各行其是;9世纪起突厥禁卫军可以废立哈里发;945年白益王朝进入巴格达,哈里发从此只剩宗教象征,实权归于军人;伊拉克核心区的灌溉系统年久失修,加上大规模劳工起义,税基萎缩。1258年旭烈兀攻破巴格达并杀死末代哈里发,阿拔斯朝五百年的政治框架就此终结。','Disintegration was gradual and multi-causal. The empire was too large for its communications, governors turned hereditary, and the Umayyads of Spain and the Fatimids of North Africa and Egypt were long since going their own way. From the ninth century Turkish guard troops could make and unmake caliphs. In 945 the Buyids entered Baghdad and the caliph became a religious figurehead while soldiers held real power. In the Iraqi heartland the irrigation works fell into disrepair and a massive labour revolt shrank the tax base. In 1258 Hulagu stormed Baghdad and killed the last caliph, ending a five-century political framework.'],
      legacy:['巴格达的智慧宫把希腊、波斯、印度的典籍系统译成阿拉伯语并加以推进,这批学问后经西班牙与西西里回流欧洲,是文艺复兴的重要前提之一。花剌子米的书名 al-jabr 变成了 algebra(代数),他名字的拉丁转写则变成了 algorithm(算法);印度记数法经阿拉伯人西传,欧洲人至今称之为「阿拉伯数字」;伊本·西那的《医典》在欧洲医学院当了几百年教材。阿拉伯语则成了从大西洋到中亚通用的学术语言。','Baghdad\'s House of Wisdom systematically translated Greek, Persian and Indian works into Arabic and pushed them further; that body of learning later flowed back into Europe through Spain and Sicily and became one of the preconditions of the Renaissance. Al-Khwarizmi\'s title al-jabr became \'algebra\', and the Latin form of his name became \'algorithm\'. Indian numerals travelled west through Arab hands, and Europeans still call them Arabic numerals. Ibn Sina\'s Canon of Medicine served as a European medical textbook for centuries. And Arabic became the common language of scholarship from the Atlantic to Central Asia.'] },
  d:'伊斯兰旗帜下的阿拉伯人一百年内建立起从西班牙到中亚的帝国;阿拔斯迁都巴格达后,"智慧宫"把希腊、波斯、印度典籍译成阿拉伯语,代数(algebra 一词即来自阿拉伯语)与"阿拉伯数字"由此西传。10世纪后大权旁落突厥军人,1258年蒙古屠巴格达,黄金时代落幕。' },
{ l:'me', s:'steppe', v:0, n:'塞尔柱突厥', k:[[1037,0],[1071,.5],[1150,.4],[1194,0]], b:'草原突厥人入主西亚,一战重创拜占庭,引来十字军。',
  e:{ n:'Seljuks', w:'Seljuk Empire', b:'Steppe Turks take over West Asia; Manzikert brings on the Crusades.', d:'Steppe Turks converted to Islam and became its sword; at Manzikert in 1071 they captured the Byzantine emperor, and Anatolia turned Turkish — the origin of today\'s Turkey and, indirectly, of the Crusades.', f:{ 'Peak':'Malik-Shah (1072–1092)', 'Center':'Isfahan', 'Figures':'Alp Arslan, Nizam al-Mulk', 'Legacy':'Manzikert, madrasa system' } },
  f:{ '鼎盛':'马利克沙(1072—1092)', '中心':'伊斯法罕', '人物':'阿尔普·阿尔斯兰、尼扎姆·穆勒克', '成就':'曼齐刻尔特大捷、经学院体系' },
  qh:{ born:['哈里发管宗教,苏丹管实权','The caliph kept the faith; the sultan kept the power'],
       rule:['税收权直接给军官,省掉一整层财政','Tax rights handed to officers, skipping a whole layer'],
       money:['农业税不经国库,直接变成军费','The land tax became pay without passing the treasury'],
       power:['改变这片土地的不是那一战,是人口迁入','Not the battle changed the land, but the migration after'],
       fall:['帝国被当成家产,子侄各分一块','The empire was treated as family property, and divided'],
       legacy:['今天的土耳其,起点在这里','Turkey today starts here'] },
  q:{ born:['中亚草原的乌古斯突厥人中,塞尔柱家族皈依了逊尼派伊斯兰,于是「草原武力」与「宗教正当性」装进了同一个身体。1040年丹丹纳干之战击败伽色尼王朝取得呼罗珊,1055年图格里勒率军进入巴格达,替早已被什叶派白益王朝架空的哈里发解围,哈里发回赠的是「苏丹」称号——从此形成一种分工:哈里发管宗教权威,苏丹管实际权力。','Among the Oghuz Turks of the Central Asian steppe, the Seljuk house converted to Sunni Islam, so that steppe fighting power and religious legitimacy sat in the same body. Victory at Dandanaqan in 1040 took Khorasan from the Ghaznavids, and in 1055 Tughril marched into Baghdad and freed the caliph from the Shia Buyids who had long reduced him to a figurehead. The caliph\'s return gift was the title sultan — establishing a division of labour that lasted: the caliph held religious authority, the sultan held actual power.'],
      rule:['帝国的运转靠两套制度。一是伊克塔:把某片土地的税收权分配给军官,军官以此自养并按需出兵——国家不必先收税再发饷,省了一整层财政环节,但代价是军官与土地的关系越来越紧。二是尼扎姆·穆勒克设计的经学院(尼采米亚)体系,由国家出资培养教法学者与官僚,让逊尼派的教法教育有了国家出资的制度化产线;他写的《治国策》是波斯-伊斯兰政治学的经典。','Two institutions made the empire run. One was the iqta: the right to collect a district\'s taxes was assigned to an officer, who supported himself from it and brought troops when called — sparing the state a whole layer of fiscal machinery, at the price of officers growing ever more attached to their land. The other was the madrasa system founded by Nizam al-Mulk, the Nizamiyya, state-funded schools that trained jurists and officials and gave Sunni legal education a state-funded institutional pipeline. His Book of Government remains a classic of Persian-Islamic political thought.'],
      money:['收入的主体是伊朗与美索不达米亚的农业税,通过伊克塔直接转成军费;此外是丝路与麦加朝觐路线上的过境与市场税,伊斯法罕、内沙布尔等城市的手工业与集市也是稳定财源。鼎盛时控制的疆域约三百九十万平方公里。','The bulk of revenue was agricultural tax from Iran and Mesopotamia, converted directly into military pay through the iqta. On top of that came transit and market dues along the Silk Road and the pilgrimage routes to Mecca, while the crafts and bazaars of cities like Isfahan and Nishapur provided steady income. At its height the empire controlled some 3.9 million square kilometres.'],
      power:['军事优势来自两种兵的组合:游牧部落随时可动员的骑射手,加上奴隶出身、只忠于苏丹的职业禁军。1071年曼齐刻尔特之战不仅击败拜占庭军,还俘虏了皇帝本人;此战之后拜占庭在安纳托利亚的防御体系瓦解,大批突厥部落随即迁入高原放牧定居——真正改变这片土地的不是那一战,而是战后几十年的人口迁移。','Military strength came from combining two kinds of soldier: tribal horse archers who could be mobilized at short notice, and professional guards of slave origin loyal only to the sultan. At Manzikert in 1071 the Seljuks not only beat the Byzantine army but captured the emperor himself. Byzantine defences in Anatolia unravelled afterwards, and Turkish tribes moved onto the plateau to graze and settle in large numbers — what really changed that land was not the battle but the migration of the following decades.'],
      fall:['草原的继承传统把帝国看作家族共有的财产,而不是一个不可分割的国家:1092年马利克沙去世后,诸子与叔侄各拥军队互相攻伐,同年尼扎姆·穆勒克遇刺,行政中枢也断了。各地的阿塔贝格(受托辅佐幼主的将领)趁机变成割据势力,十字军自西面到来,东面的花剌子模崛起;1194年末代苏丹战败身亡,大塞尔柱帝国结束,只余罗姆等旁支延续。','Steppe custom treated the empire as family property rather than an indivisible state. After Malik-Shah died in 1092 his sons, uncles and nephews raised armies against one another, and the assassination of Nizam al-Mulk the same year cut out the administrative brain as well. Atabegs — generals appointed as guardians of young princes — turned themselves into local dynasts, crusaders arrived from the west and Khwarazm rose in the east. The last sultan was defeated and killed in 1194, ending the Great Seljuk empire; only side branches such as the Sultanate of Rum carried on.'],
      legacy:['安纳托利亚的突厥化与伊斯兰化从这里开始,经罗姆苏丹国一路通向奥斯曼,再通向今天的土耳其——这是塞尔柱最长远的一笔。经学院制度让逊尼派的教法教育成为可复制的体系,影响一直延续到近代。曼齐刻尔特之败迫使拜占庭皇帝向西方求援,一般认为这是十字军东征形成的重要一环(但不是唯一原因,西欧内部的宗教与社会动力同样关键)。','The Turkification and Islamization of Anatolia begins here and runs through the Sultanate of Rum to the Ottomans and to today\'s Turkey — the longest-lasting Seljuk consequence. The madrasa made Sunni legal education a reproducible system whose influence lasted into modern times. The defeat at Manzikert pushed the Byzantine emperor to appeal west for help, generally seen as an important link in the chain leading to the Crusades — though not the only cause, since religious and social forces inside western Europe mattered just as much.'] },
  d:'草原来的突厥人皈依伊斯兰后,反而成了它的武力担当;1071年曼齐刻尔特之战俘虏拜占庭皇帝,安纳托利亚从此突厥化——今日土耳其的起点,也是间接引发十字军东征的导火索。' },
{ l:'me', s:'mideast', v:0, n:'阿尤布王朝', k:[[1171,0],[1190,.5],[1220,.4],[1250,.2],[1260,0]], b:'萨拉丁建立的王朝:合埃及与叙利亚为一体,1187年收复耶路撒冷。',
  e:{ n:'the Ayyubids', w:'Ayyubid dynasty', b:'Saladin\'s dynasty: Egypt and Syria joined in one hand, and Jerusalem retaken in 1187.', d:'A Kurdish commander sent to help defend Fatimid Egypt deposed its last caliph instead, then spent a decade bringing Syria under the same hand. At Hattin in 1187 he all but destroyed the field army of the kingdom of Jerusalem and took the city back after eighty-eight years; the Third Crusade fought him to a draw and the 1192 treaty split coast from Holy City. When he died in 1193 the family branches turned on one another, and in 1250 the dynasty\'s own slave soldiers took the throne.', f:{ 'Peak':'1187–1193 (Saladin\'s last years)', 'Center':'Cairo, Damascus', 'Figures':'Saladin', 'Legacy':'Hattin and the recovery of Jerusalem, a network of madrasas, the Cairo citadel' } },
  f:{ '鼎盛':'1187—1193年(萨拉丁晚期)', '中心':'开罗、大马士革', '人物':'萨拉丁', '成就':'哈丁战役与收复耶路撒冷、经学院网络、开罗城堡' },
  qh:{ born:['先拿埃及的钱粮,再取叙利亚的兵','First the grain of Egypt, then the soldiers of Syria'],
       rule:['不是一个国家,是一个家族的分封联合','Not one state, but a family holding shares'],
       money:['打得最凶的年份,生意照做','Even in the worst years of war, the trade went on'],
       power:['一战几乎全歼对手,收回了耶路撒冷','One battle wiped out the enemy army, and Jerusalem came back'],
       fall:['真正终结它的,是它自己的军队','What ended it was its own army'],
       legacy:['他在敌人那边的名声,出奇地好','His reputation among his enemies was unusually good'] },
  q:{ born:['法蒂玛王朝末期实权落在军人维齐尔手里,富庶的埃及成了十字军与叙利亚赞吉政权争夺的目标。赞吉的努尔丁三次派兵入埃及,随军的库尔德将领萨拉丁在第三次留了下来,1169年出任维齐尔,1171年废去末代法蒂玛哈里发、宣布奉巴格达的阿拔斯为正朔。1174年努尔丁去世后,他又花了十余年把大马士革、阿勒颇等叙利亚城市并入麾下——先拿到埃及的钱粮、再取叙利亚的兵源——这个顺序决定了此后它能同时应付两条战线。','In the last Fatimid years real power lay with military viziers, and rich Egypt became the prize contested between the crusader states and the Zangids of Syria. Nur al-Din sent three expeditions into Egypt, and on the third the Kurdish commander Saladin stayed: vizier in 1169, and in 1171 he deposed the last Fatimid caliph and proclaimed allegiance to Baghdad. After Nur al-Din died in 1174 he spent more than a decade bringing Damascus, Aleppo and the other Syrian cities under his own hand — Egypt\'s revenue first, then Syria\'s manpower — an order that let the state work two fronts at once.'],
      rule:['萨拉丁把埃及、大马士革、阿勒颇、哈马等地分给兄弟子侄,各自称王(al-Malik),苏丹的名号归家族之长,名义上奉开罗为尊。这套安排在他生前靠个人威望撑着,他一死就变成各支互相攻伐。宗教上是逊尼派的复兴:广建经学院(马德拉沙),把法蒂玛两百年的什叶派官学扭回逊尼派,爱资哈尔一度停止讲授。','Saladin parcelled out Egypt, Damascus, Aleppo and Hama to brothers and nephews, each styled al-Malik, \'king\', with the title of sultan held by the head of the family, and all nominally deferring to Cairo. His personal standing held it together while he lived, and it fell to fighting among the branches as soon as he died. In religion it was a Sunni restoration: madrasas were founded widely, two centuries of Fatimid Shia teaching were reversed, and al-Azhar stopped giving lessons for a time.'],
      money:['尼罗河农业加上红海—印度洋商路,这套底盘承自法蒂玛、后来又原样传给马穆鲁克,是埃及在中世纪长期富庶的原因。1174年萨拉丁之弟图兰沙南下取也门,等于把这条商路的另一端也攥在手里——亚丁是印度洋来船进红海的第一站。值得一提的是战争并没有切断贸易:即使在十字军战事最激烈的年份,意大利城邦的商船仍在亚历山大装卸货物,双方都需要这笔生意——教廷屡次禁止对穆斯林贸易,禁令屡次落空。','Nile agriculture plus the Red Sea and Indian Ocean route — a foundation inherited from the Fatimids and handed on intact to the Mamluks, and the reason Egypt stayed rich through the Middle Ages. In 1174 Saladin\'s brother Turanshah took Yemen, putting the far end of that route in the same hands — Aden was the first call for ships coming into the Red Sea from the Indian Ocean. Worth noting that war did not stop trade: even in the fiercest crusading years Italian ships were still loading at Alexandria, because both sides wanted the business, and repeated papal bans on trading with Muslims repeatedly failed.'],
      power:['军队核心是库尔德与突厥骑兵,另有成建制购入的马穆鲁克(奴隶兵)。1187年7月哈丁战役几乎全歼耶路撒冷王国的野战军,同年10月收复耶路撒冷——这座城此前被十字军占据八十八年。随之而来的第三次十字军(1189—1192)有三位君主出兵,后期由英王理查一世主导,双方在阿卡与雅法一带反复拉锯,谁也吃不掉谁,1192年订约:耶路撒冷归穆斯林,沿海一条走廊归十字军,基督徒可自由前往圣墓朝圣。','Its core was Kurdish and Turkish cavalry plus purchased mamluk slave soldiers. At Hattin in July 1187 it all but destroyed the field army of the kingdom of Jerusalem, and that October took Jerusalem itself, which the crusaders had held for eighty-eight years. The Third Crusade that followed (1189–1192), fought by three monarchs and led in its later stages by Richard I of England, ground back and forth around Acre and Jaffa without either side breaking the other, and ended in a treaty: Jerusalem stayed Muslim, a coastal strip went to the crusaders, and Christian pilgrims were free to visit the Holy Sepulchre.'],
      fall:['1193年萨拉丁病逝于大马士革,家族随即为争位打了七年;他的弟弟阿迪勒1200年重新把各支合起来,此后两代人大体撑住了局面——阿迪勒之子卡米勒还在1229年与神圣罗马皇帝订约,把耶路撒冷让回十字军十几年。真正终结它的却是自己的军队:1249年埃及苏丹在抵抗第七次十字军途中去世,次年继位的图兰沙与马穆鲁克禁卫军闹翻被杀,奴隶兵自己当了家。叙利亚各支撑到1260年蒙古军南下时被扫平;只有哈马一支作为附庸又存续了约八十年,已无力量可言。','Saladin died at Damascus in 1193, and the branches fought over the succession for seven years; his brother al-Adil pulled them back together in 1200 and the confederation broadly held for two more generations — al-Adil\'s son al-Kamil even made terms with the Holy Roman emperor in 1229, handing Jerusalem back to the crusaders for fifteen years. What actually ended it was its own army: the sultan of Egypt died in 1249 while resisting the Seventh Crusade, his successor Turanshah fell out with the mamluk guard and was killed the next year, and the slave soldiers took the throne themselves. The Syrian branches lasted until the Mongols swept south in 1260; only the line at Hama survived another eighty years or so as a vassal, with no power to speak of.'],
      legacy:['耶路撒冷此后一直在穆斯林治下直到二十世纪,中间只有1229—1244年间几度经条约短暂归还十字军。萨拉丁本人在欧洲留下的形象罕见地正面——但丁把他放在地狱边缘那一层的"高贵异教徒"之列,司各特的小说《护身符》又把这个形象带给了近代读者;他在阿拉伯世界成为民族符号则是十九世纪以后才被重新塑造起来的,与中世纪的记载不是一回事。开罗城堡自1176年始建,建成后成为埃及的权力所在,一直到1874年。','Jerusalem stayed under Muslim rule until the twentieth century, interrupted only by a few short spells between 1229 and 1244 when treaties returned it to the crusaders. Saladin\'s reputation in Europe is unusually favourable — Dante places him among the noble pagans in the first circle, and Walter Scott\'s The Talisman carried that image to modern readers; his standing as a national symbol in the Arab world, by contrast, was rebuilt in the nineteenth century and is not the same thing as the medieval record. The Cairo citadel he began in 1176 became the seat of power in Egypt once finished, and stayed so until 1874.'] },
  d:'库尔德将领萨拉丁受命援埃及,反手废掉法蒂玛末代哈里发,再用十余年把叙利亚并入,合两地为一体。1187年哈丁大胜、收复被十字军占据八十八年的耶路撒冷;第三次十字军与理查一世打成平手,1192年订约分治沿海与圣城。1193年他一死,家族各支互斗,1250年被自己的奴隶兵取代。' },
{ l:'me', s:'mideast', v:1, n:'马穆鲁克', k:[[1250,0],[1260,.4],[1330,.55],[1400,.4],[1517,0]], b:'奴隶兵建立的王朝;1260年在阿音扎鲁特挡住了蒙古。',
  e:{ n:'the Mamluk Sultanate', b:'A dynasty of slave soldiers; at Ain Jalut in 1260 they stopped the Mongols.', d:'Boys bought as slaves on the steppe were trained into elite cavalry, and in 1250 they overthrew their masters and ruled in their own right. They checked the Mongol advance at Ain Jalut in 1260 and took the last crusader stronghold in the Levant in 1291. The state lived on the spice transit tax between the Red Sea, Cairo and Alexandria; plague and then the Cape route pulled away its people and its revenue, and its reluctance to adopt firearms left it beaten by the Ottomans in 1517.', f:{ 'Peak':'first half of the 14th c.', 'Center':'Cairo', 'Figures':'Baybars, Qutuz, Ibn al-Nafis', 'Legacy':'Halting the Mongols, the courier network, the mosques and colleges of Cairo' } },
  f:{ '鼎盛':'14世纪前期(纳绥尔·穆罕默德朝)', '中心':'开罗', '人物':'拜巴尔、忽都斯、伊本·纳菲斯', '成就':'挡住蒙古、驿传制度、开罗的清真寺与经学院' },
  qh:{ born:['买来的奴隶兵,自己当了主人','The slave soldiers made themselves the masters'],
       rule:['当苏丹靠资历,不靠是谁的儿子','The sultanate went by seniority, not by birth'],
       money:['香料必须过它的手,直到好望角被绕过','Spices had to pass through, until the Cape was rounded'],
       power:['蒙古人在西亚,第一次被明确挡住','In western Asia the Mongols were stopped here first'],
       fall:['精锐骑兵看不上火枪,转型就慢了','Elite cavalry despised the gun, and fell behind'],
       legacy:['今天开罗老城,主体是那时候盖的','Old Cairo today is largely what they built'] },
  q:{ born:['马穆鲁克本义是"被占有的人":从钦察草原与高加索买来的少年奴隶,自幼受骑射与伊斯兰教育,成年后获释并编入军队,是中东各政权最精锐的部队。1249年埃及阿尤布王朝的苏丹去世,次年继位的图兰沙与这批禁卫军闹翻,他们索性把他杀掉、自己当家。奴隶兵变成统治者,这是伊斯兰世界少见的一次。','Mamluk means "owned": boys bought as slaves from the Kipchak steppe and the Caucasus, raised on horsemanship and Islam, freed on reaching adulthood and enrolled as troops, they were the finest soldiers any Middle Eastern state could field. The Ayyubid sultan of Egypt died in 1249, his successor fell out with the guard the next year, and they killed him and took power themselves. Slave soldiers becoming rulers was a rare turn even in Islamic history.'],
      rule:['继承不靠血统而靠资历与实力:苏丹多由马穆鲁克将领推举或夺取,儿子往往坐不稳位子,新的一批奴隶兵不断从草原买进来补充。这套制度使权力顶层长期动荡,却也让军队始终由久经训练的职业军人构成。为给统治找合法性,他们把1258年巴格达陷落后逃出的阿拔斯家族成员迎到开罗,立为哈里发——有名分而无实权,苏丹借他的名义号令。','Succession ran on seniority and force rather than blood: sultans were raised up or seized power among the Mamluk commanders, sons rarely held the throne, and fresh cohorts of slave soldiers were continually bought from the steppe. It kept the top of the state unstable, but it also kept the army in the hands of long-trained professionals. For legitimacy they brought a surviving member of the Abbasid house to Cairo after Baghdad fell in 1258 and installed him as caliph — a title without power, in whose name the sultan issued his commands.'],
      money:['埃及的农业底子加上一条别人绕不开的商路:印度洋来的香料、丝绸与瓷器在红海上岸,经陆路运到亚历山大与开罗,再由威尼斯、热那亚商人买走运往欧洲。国家对这条转口贸易课重税,是财政的支柱。此外还有叙利亚的棉与糖。这条垄断一直维持到15世纪末葡萄牙人绕过好望角,直接打通了海路。','Egyptian agriculture plus a trade route no one could go around: spices, silk and porcelain from the Indian Ocean were landed on the Red Sea, carried overland to Alexandria and Cairo, and bought there by Venetian and Genoese merchants for Europe. The state taxed this transit trade heavily and lived on it, alongside Syrian cotton and sugar. The monopoly held until the Portuguese rounded the Cape at the end of the fifteenth century and opened the sea route direct.'],
      power:['核心是重装骑兵,长年操练弓马与枪法,战术水平在当时的地中海世界少有对手。1260年阿音扎鲁特之战,忽都斯与拜巴尔击败蒙古的西征军——这是蒙古扩张在西亚方向第一次被明确挡住,此后伊尔汗国多次试图夺取叙利亚都未能站稳。他们还建立了覆盖埃及与叙利亚的驿传网,情报四天可从开罗传到大马士革,并在1291年攻陷阿卡,结束了十字军在黎凡特的据点。','Its core was heavy cavalry, drilled for years in archery, horsemanship and the lance, with few tactical equals in the Mediterranean world of the time. At Ain Jalut in 1260 Qutuz and Baybars defeated a Mongol expeditionary force — the first clear check on Mongol expansion in western Asia, after which the Ilkhanate repeatedly tried and failed to hold Syria. They also built a courier network across Egypt and Syria that could carry intelligence from Cairo to Damascus in four days, and in 1291 took Acre, ending the crusader foothold in the Levant.'],
      fall:['多因叠加。1347年起黑死病反复袭来,埃及人口锐减,农业与税基长期没有恢复;马穆鲁克集团内部争夺苏丹之位的内战频繁,财政被军费与赏赐掏空;1497年达伽马绕过好望角、次年抵达印度,香料贸易改走海路,过境税这根支柱被抽掉。技术上他们并非完全不用火器(攻城有炮,末代苏丹还编过火枪队),但精锐骑兵集团对手持火器抵触很强,转型远慢于已经用上火炮与火枪的奥斯曼军队。1516至1517年两战皆败,埃及并入奥斯曼帝国。','Causes stacked. Plague returned repeatedly from 1347, cutting Egypt\'s population sharply, and neither agriculture nor the tax base recovered for a long time. Civil wars over the sultanate were frequent among the Mamluk factions, and military pay and donatives drained the treasury. After da Gama rounded the Cape in 1497 the spice trade moved to the sea, pulling out the transit-tax pillar. And while they were not wholly without firearms — they had siege cannon, and the last sultan raised a musket corps — the elite cavalry resisted carrying guns themselves, so they converted far more slowly than the Ottoman army with its cannon and arquebuses. Two battles lost in 1516 and 1517 brought Egypt into the Ottoman Empire.'],
      legacy:['开罗因此成为伊斯兰世界的文化中心之一:马穆鲁克苏丹与将领竞相修建清真寺、经学院与医院,这批建筑今天仍是开罗老城的主体,苏丹哈桑清真寺是其中最著名的一座。他们庇护了从蒙古兵锋下逃来的学者。一个多世纪之后,从突尼斯来的伊本·赫勒敦也在开罗度过晚年,任教并多次出任法官。阿音扎鲁特之战则长期被视为一个转折点——尽管现代研究指出蒙古当时因大汗去世而主力东撤,这一战的战略意义仍有争论。','Cairo became one of the cultural centres of the Islamic world: Mamluk sultans and commanders competed in building mosques, colleges and hospitals, and that stock still forms the body of the old city, the mosque of Sultan Hassan being the most famous. They sheltered scholars who had fled the Mongol advance. More than a century later Ibn Khaldun, who came from Tunis, also spent his last years in Cairo, teaching and serving repeatedly as a judge. Ain Jalut has long been treated as a turning point, though modern scholarship notes that the main Mongol force had withdrawn east after the death of the Great Khan, and the battle\'s strategic weight is still debated.'] },
  d:'从草原买来的奴隶少年练成精兵,1250年反过来推翻主君自立;1260年阿音扎鲁特挡住蒙古西征,1291年拔除十字军在黎凡特的最后据点。靠红海—开罗—亚历山大的香料转口税立国,黑死病与好望角航路先后抽走人口与税基,又迟迟不肯用火器,1517年败于奥斯曼。' },
{ l:'me', s:'steppe', v:2, n:'伊尔汗国', k:[[1256,0],[1260,.5],[1300,.4],[1335,0]], b:'蒙古西征的产物,攻陷巴格达,终结阿拔斯哈里发。',
  e:{ n:'Ilkhanate', b:'Mongol Persia; the end of the Abbasids.', d:'Hülegü\'s westward campaign destroyed the Abbasids; the Mongols ruled Persia for eighty years, later converting to Islam. Tabriz became the east-west entrepôt where Chinese painting met the Persian miniature.', f:{ 'Peak':'Ghazan (1295–1304)', 'Center':'Tabriz', 'Figures':'Hulagu, Rashid al-Din', 'Legacy':'East-West exchange in art and astronomy' } },
  f:{ '鼎盛':'合赞汗(1295—1304)', '中心':'大不里士', '人物':'旭烈兀、拉施特丁', '成就':'东西天文历法与绘画交流' },
  qh:{ born:['后来变成蒙古人打蒙古人','In the end, Mongols fighting Mongols'],
       rule:['征服者,最后被被征服者改写了','The conquerors were rewritten by the conquered'],
       money:['纸币照抄来了,信用抄不来','They copied the paper money; they could not copy the trust'],
       power:['情报跑得比敌人快,本身就是武器','News that outran the enemy was itself a weapon'],
       fall:['改革随着人一起没了','The reforms died with the men who made them'],
       legacy:['青花瓷身上,有这条通道的影子','Blue-and-white porcelain still carries this route'] },
  q:{ born:['蒙哥汗派其弟旭烈兀西征,任务很明确:清除伊朗的割据势力与山中的伊斯玛仪派据点。1256年攻破阿剌模忒等堡垒,1258年攻陷巴格达并处死末代阿拔斯哈里发。此后蒙古帝国自身分裂,旭烈兀一系就在伊朗自立为汗,与信奉伊斯兰的金帐汗国长期为高加索交恶——蒙古人打蒙古人。','Möngke Khan sent his brother Hulagu west with a clear brief: clear out Iran\'s local powers and the Ismaili strongholds in the mountains. The fortresses including Alamut fell in 1256, and Baghdad was stormed in 1258 and the last Abbasid caliph put to death. As the Mongol empire then split apart, Hulagu\'s line set itself up as khans in Iran, feuding for decades with the Muslim Golden Horde over the Caucasus — Mongols fighting Mongols.'],
      rule:['最初是双轨制:蒙古军事贵族在上,波斯官僚在下办事,两套逻辑互不相通,征服者用草原习惯法,被征服者用伊斯兰法。转折点是1295年合赞汗即位——他自己改宗伊斯兰,承认伊斯兰法,整顿吏治,还宣布蒙古人也要遵守当地规矩。征服者最终被被征服者的文明改写,这是伊尔汗国最值得记住的一点。','It began as a two-track system: Mongol military aristocrats on top, Persian bureaucrats doing the work below, the two logics barely touching — the conquerors under steppe custom, the conquered under Islamic law. The turning point came in 1295 when Ghazan took the throne: he converted to Islam himself, recognized Islamic law, overhauled the administration and declared that Mongols too would live by local rules. In the end the conquerors were rewritten by the civilization they had conquered — the thing most worth remembering about the Ilkhanate.'],
      money:['早期是竭泽而渔:层层包税,谁出价高谁去收,伊拉克与伊朗的农业因此凋敝。1294年乞合都汗照抄元朝的做法发行纸币,市场完全不接受,几周就宣告失败——制度可以照搬,信用不能。合赞汗与拉施特丁的改革改为固定税额、重修水利与驿站,大不里士随之成为欧亚商路的枢纽,热那亚与威尼斯商人都在那里设点。','At first it was extraction to exhaustion: tax farms auctioned to the highest bidder, layer upon layer, which ruined agriculture in Iraq and Iran. In 1294 Khan Gaykhatu copied the Yuan dynasty and issued paper money; the market refused it outright and the experiment collapsed within weeks — institutions can be copied, credit cannot. The reforms of Ghazan and Rashid al-Din replaced this with fixed assessments and rebuilt irrigation and the postal relay, after which Tabriz became a hub of Eurasian trade with Genoese and Venetian merchants keeping agents there.'],
      power:['军事上是蒙古骑兵加上从东西两头吸收来的攻城技术,再配以覆盖全境的驿站情报网——情报跑得比敌人快,本身就是武器。但扩张有明确的天花板:1260年阿音扎鲁特败于埃及马穆鲁克后,伊尔汗国屡次试图夺取叙利亚都未能站稳,甚至曾试图与欧洲君主结盟夹击马穆鲁克,始终没能成事。','Militarily it was Mongol cavalry plus siege techniques absorbed from both east and west, tied together by a relay network covering the realm — intelligence that outran the enemy was itself a weapon. But expansion had a hard ceiling: after defeat by the Egyptian Mamluks at Ain Jalut in 1260, repeated Ilkhanid attempts on Syria never held, and even efforts to ally with European monarchs against the Mamluks came to nothing.'],
      fall:['崩解来得很快,原因也不止一条:1335年不赛因汗去世且无子嗣,宗王与将领各拥其主,继承危机直接引爆分裂;蒙古军事贵族与波斯官僚集团之间的张力从未真正消解,合赞的改革人亡政息(拉施特丁本人于1318年被政敌处死);1340年代的黑死病与经济衰退,又让已经碎裂的地方局面雪上加霜。汗国碎成札剌亦儿等数个地方政权,后来被帖木儿一一收拾。','The collapse was fast and had several causes. Abu Sa\'id died without an heir in 1335, princes and generals backed rival claimants, and the succession crisis detonated the split. The tension between Mongol military aristocrats and Persian officials had never really been resolved, and Ghazan\'s reforms did not outlive their authors — Rashid al-Din himself was executed by rivals in 1318. Plague and economic decline in the same period deepened the loss of control. The khanate broke into regional powers such as the Jalayirids, which Timur later swept up one by one.'],
      legacy:['拉施特丁主持编纂的《史集》把蒙古、中国、印度、突厥与法兰克的历史写进同一部书,常被称为最早的世界史尝试之一。马拉盖天文台的观测与《伊尔汗历表》影响了后世的天文计算。而东西两端的手艺人在大不里士相遇:中国的构图与用笔进入波斯细密画,中国瓷器所用的钴蓝颜料则大量来自波斯——今天我们看到的青花瓷,身上有这条通道的影子。','The Compendium of Chronicles, compiled under Rashid al-Din, put Mongol, Chinese, Indian, Turkic and Frankish history into a single book and is often called one of the earliest attempts at a world history. Observations at the Maragheh observatory and the resulting Ilkhanid astronomical tables shaped later calculation. And craftsmen from both ends met at Tabriz: Chinese composition and brushwork entered Persian miniature painting, while much of the cobalt blue used on Chinese porcelain came from Persia — the blue-and-white ware we know today carries traces of that channel.'] },
  d:'旭烈兀西征灭阿拔斯,蒙古人统治波斯八十年;后期皈依伊斯兰并推行改革,大不里士成为东西商路枢纽——中国的绘画技法与波斯细密画正是在此相遇。' },
{ l:'me', s:'mideast', v:0, n:'奥斯曼帝国', k:[[1299,0],[1453,.6],[1550,.9],[1683,.7],[1800,.4],[1918,0]], b:'攻陷君士坦丁堡,横跨三洲六百年,一战后解体。',
  e:{ n:'Ottoman Empire', b:'Took Constantinople; three continents for six centuries.', d:'Mehmed II\'s great guns opened the thousand-year capital in 1453; under Suleiman the armies stood before Vienna and the eastern Mediterranean was Ottoman. Conservatism set in; the "sick man" was dismembered after WWI — today\'s Middle East map is largely the parceling of its estate.', f:{ 'Peak':'Suleiman (1520–1566)', 'Center':'Istanbul', 'Figures':'Mehmed II, Suleiman, Mimar Sinan, Piri Reis, Hurrem Sultan', 'Legacy':'Tri-continental administration' } },
  f:{ '鼎盛':'苏莱曼大帝(1520—1566)', '中心':'伊斯坦布尔', '人物':'穆罕默德二世、苏莱曼大帝、米马尔·希南、皮里·雷斯、许蕾姆苏丹', '成就':'横跨三洲的行政与米利特体系' },
  qh:{ born:['正好卡在拜占庭衰弱的那个方向上','It sat exactly where Byzantium was weakening'],
       rule:['征来基督徒少年,养成只忠于苏丹的人','Christian boys taken and raised to serve only the sultan'],
       money:['拿下那座城之后,过路钱都归它','Once it took the city, the tolls were its own'],
       power:['大炮轰开了君士坦丁堡的城墙','Cannon broke the walls of Constantinople'],
       fall:['近卫军从利刃,变成挡住改革的人','The guards went from blade to blockage'],
       legacy:['今天中东的版图,是它解体时画的','The map of the Middle East was drawn as it broke up'] },
  q:{ born:['塞尔柱帝国碎掉后,安纳托利亚满地小侯国;奥斯曼这一支起于西北角的小城瑟于特(传统上从 1299 年算起),恰好卡在拜占庭衰弱的方向上,靠边境圣战聚拢战士,越打越大——1326 年拿下布尔萨做第一个都城,1354 年跨过海峡踏上欧洲,1453 年二十一岁的穆罕默德二世攻下君士坦丁堡。','When the Seljuk realm shattered, Anatolia was a floor of petty emirates; the house of Osman began at the small town of Söğüt in the north-west (1299 by tradition), happened to face a fading Byzantium, gathered frontier fighters under the banner of holy war, and grew with every campaign — Bursa taken as first capital in 1326, the straits crossed into Europe in 1354, and Constantinople itself in 1453 under the twenty-one-year-old Mehmed II.'],
      rule:['德夫希尔梅征募基督徒少年,培养成只忠于苏丹的近卫军与官僚;米利特制让各宗教社群自治纳税;蒂玛封地把骑兵和土地税绑在一起。','The devshirme levy took Christian boys and raised them into janissaries and officials loyal to the sultan alone; the millet system let each faith govern itself and pay its tax; timar fiefs tied cavalry service to the land revenue.'],
      money:['1453 年拿下君士坦丁堡后,东西方商路的过路钱进了奥斯曼的口袋——穆罕默德二世随即在城里建起大巴扎,几千间铺子的屋顶集市至今还在营业;银币阿克切是日常货币。蒂玛体系是另一根支柱:骑兵拿一块封地的税收,自备马匹兵器出征。','After Constantinople fell in 1453, the tolls of east-west trade flowed into Ottoman hands — Mehmed II at once built the Grand Bazaar in the city, a roofed market of thousands of shops still trading today; the silver akçe was the everyday coin. The timar system was the other pillar: a cavalryman drew the taxes of a fief and brought his own horse and arms to war.'],
      power:['火药帝国的先行者:轰开君士坦丁堡的乌尔班巨炮、常备的耶尼切里军团都领先欧洲;宗教宽容降低了统治多民族的成本。','An early gunpowder empire: the great cannon that breached Constantinople and the standing janissary corps were both ahead of Europe, while religious tolerance kept the cost of ruling many peoples low.'],
      fall:['主流看法是几重挤压:大航海之后,商路的分量逐渐转向大洋;欧洲军事革命反超;耶尼切里从利刃变成阻挡改革的既得利益集团;多民族帝国撞上民族主义时代;一战站错边,帝国被肢解。','The mainstream account is a squeeze from several sides: trade shifted gradually toward the ocean routes, the European military revolution overtook it, the janissaries turned from blade into a vested interest that blocked reform, nationalism cracked a multi-ethnic realm — and the wrong side in the First World War brought the partition.'],
      legacy:['伊斯坦布尔这座城;今日中东的版图大体是帝国解体时画下的;咖啡与郁金香也是经它传入欧洲的——1554 年前后伊斯坦布尔开出它最早的咖啡馆,十六世纪末郁金香球茎从这里传到荷兰。','The city of Istanbul; the map of the modern Middle East, drawn largely at the moment of imperial break-up; and coffee and tulips, which reached Europe through Ottoman hands — Istanbul\'s first coffee-houses opened around 1554, and tulip bulbs travelled from here to the Netherlands late in the sixteenth century.'] },
  d:'1453年穆罕默德二世以巨炮轰开千年帝都;苏莱曼时代兵临维也纳,地中海东半尽入其手。此后渐趋保守,19世纪沦为列强口中的"西亚病夫",一战站错队后帝国解体——今日中东的版图,多是其遗产被英法分割的结果。' },
{ l:'me', s:'mideast', v:1, n:'萨法维·波斯', k:[[1501,0],[1600,.5],[1722,.3],[1850,.2],[1925,0]], b:'什叶派波斯的定型者,与奥斯曼东西对峙。',
  e:{ n:'Safavid Persia', w:'Safavid dynasty', b:'Made Persia Shia; Isfahan, "half the world".', d:'The Safavids established Shia Islam as state religion, splitting Persia from its Sunni neighbors — the root of today\'s sectarian map; Abbas the Great\'s Isfahan was among the most splendid capitals of the 17th century.', f:{ 'Peak':'Abbas I (1588–1629)', 'Center':'Isfahan', 'Figures':'Ismail I, Abbas I', 'Legacy':'Shia state, Isfahan ensemble' } },
  f:{ '鼎盛':'阿拔斯大帝(1588—1629)', '中心':'伊斯法罕', '人物':'伊斯玛仪一世、阿拔斯一世', '成就':'什叶派国教化、伊斯法罕建筑群' },
  qh:{ born:['一次自上而下的强制转宗','A conversion imposed from the top down'],
       rule:['输了一仗,神圣光环就换成了制度','One defeat cost the aura, and institutions took over'],
       money:['生丝改走海路,等于断了对手一笔财','Silk went by sea, and cut the rival out of the toll'],
       power:['当地谚语说,伊斯法罕就是半个世界','Isfahan, the local saying went, is half the world'],
       fall:['继位的人在后宫长大,没历练过','The heirs grew up in the harem, untried'],
       legacy:['伊朗从逊尼派国家,变成了什叶派国家','Iran went from a Sunni country to a Shia one'] },
  q:{ born:['萨法维家族本是阿尔达比勒的一个苏非教团首领,信徒中包括一批说突厥语的部落骑兵,因头戴红帽被称为「红头」。这些骑兵对教主的忠诚是宗教性的而非契约性的,战斗意志极强。1501年少年伊斯玛仪一世率红头攻占大不里士称沙,随即宣布十二伊玛目什叶派为国教——这是一次自上而下的强制转宗,在此之前伊朗多数人口是逊尼派。','The Safavid family led a Sufi order at Ardabil whose followers included Turkic-speaking tribal cavalry, called Qizilbash for their red caps. Their loyalty to the master was religious rather than contractual, which made them formidable fighters. In 1501 the teenage Ismail I took Tabriz at their head, proclaimed himself shah, and declared Twelver Shiism the state religion — a conversion imposed from above, since most of Iran\'s population had until then been Sunni.'],
      rule:['沙的权威建立在三重身份上:国王、苏非教团宗师、什叶派的守护者。1514年查尔迪兰之战败给装备火器的奥斯曼军后,沙「不可战胜」的神圣光环受损,王朝转而依靠制度性的宗教权威——延请黎巴嫩等地的什叶派学者建立教法体系与宗教法庭。阿拔斯一世更进一步削弱红头部落,改用出身高加索、只效忠王室的古拉姆担任禁军与省督,把兵权从部落手里收回宫廷。','The shah\'s authority rested on three identities at once: king, master of a Sufi order, and protector of Shiism. After the Ottomans, equipped with firearms, defeated him at Chaldiran in 1514, the aura of invincibility was damaged, and the dynasty shifted toward institutional religious authority, importing Shia scholars from Lebanon and elsewhere to build a system of law and religious courts. Abbas I went further, curbing the Qizilbash tribes and staffing the guard and the provinces with ghulams of Caucasian origin who owed loyalty to the crown alone — pulling military power out of tribal hands and into the palace.'],
      money:['生丝是最大的出口品,阿拔斯一世把它收归王室专卖,并借助从亚美尼亚迁来、安置在新朱尔法的商人网络,绕开奥斯曼的陆路,改由波斯湾海运直销欧洲与印度——这既是生意也是外交,等于给死对头断了一笔过境财。地毯、丝织与陶器同样是出口大项,陆海商路的过境税则是稳定收入。','Raw silk was the great export. Abbas I made it a royal monopoly and used the Armenian merchant network he resettled at New Julfa to bypass the Ottoman overland route, shipping instead through the Persian Gulf to Europe and India — commerce and diplomacy in one move, since it also cut his chief rival\'s transit income. Carpets, silk textiles and ceramics were major exports too, and transit dues on both land and sea routes gave steady revenue.'],
      power:['阿拔斯一世的军事改革是全面的:引进火枪与炮兵(据记载有英国人协助训练)、建立直属王室的常备军、迁都伊斯法罕并大兴土木,把首都本身建成国力的展示。凭这套改革他从奥斯曼与乌兹别克手中夺回失地,鼎盛时疆域约二百九十万平方公里,伊斯法罕的规模与富丽让当时到访的欧洲人惊叹,当地谚语称它「半个世界」。','Abbas I\'s military reform was thorough: muskets and artillery introduced (English advisers are recorded as helping train them), a standing army reporting directly to the crown, and a new capital at Isfahan built up on a lavish scale so that the city itself displayed the state\'s power. With this he recovered territory from the Ottomans and the Uzbeks; at its height the realm covered some 2.9 million square kilometres, and Isfahan so impressed visiting Europeans that a local saying called it \'half the world\'.'],
      fall:['17世纪后期问题逐渐累积:继位者多在后宫长大、缺乏统治历练,宫廷派系斗争消耗决策力;对逊尼派与其他教派的强制政策使阿富汗、库尔德与高加索边疆离心;欧洲商人开辟的新航路分流了丝绸贸易的利润。1722年阿富汗吉尔扎伊部围攻并攻陷伊斯法罕,萨法维实亡。此后纳迪尔沙、赞德、恺加相继掌权,19世纪伊朗在俄英两强夹击下丧失高加索与中亚领土,1925年恺加王朝终结。','Problems accumulated through the later seventeenth century: shahs raised in the harem came to the throne without experience of rule, and court factions ate up decision-making; coercive policies toward Sunnis and other communities pushed the Afghan, Kurdish and Caucasian frontiers away; and new sea routes opened by European merchants siphoned off silk profits. In 1722 Ghilzai Afghans besieged and took Isfahan, and the Safavid state was effectively finished. Nader Shah, the Zands and then the Qajars held power in turn; in the nineteenth century Iran lost the Caucasus and Central Asian territory under Russian and British pressure, and the Qajar dynasty ended in 1925.'],
      legacy:['最深远的后果是宗教地图:伊朗从一个多数逊尼派的地区变成什叶派国家,今日中东逊尼-什叶格局的直接源头就在这里,而由此形成的独立宗教学者阶层,在几百年后仍深刻影响伊朗政治。伊斯法罕的伊玛目广场与蓝色瓷砖清真寺群是世界文化遗产,萨法维时期的细密画与地毯则被视为波斯艺术的高峰之一。','The deepest consequence is the religious map: Iran went from a largely Sunni region to a Shia state, and today\'s Sunni-Shia configuration in the Middle East traces directly here — while the independent class of religious scholars this created still shapes Iranian politics centuries later. Isfahan\'s Naqsh-e Jahan square and its blue-tiled mosques are a World Heritage site, and Safavid miniature painting and carpets are regarded as one of the summits of Persian art.'] },
  d:'萨法维把什叶派立为国教,从此波斯与逊尼派邻国分道扬镳——今日中东教派格局的源头即在于此;阿拔斯大帝的伊斯法罕号称"半个世界",是17世纪最华丽的都城之一。' },
{ l:'me', s:'mideast', v:2, n:'摩洛哥诸王朝', k:[[1269,0],[1350,.25],[1465,.12],[1591,.3],[1700,.25],[1830,.15],[1912,0]], b:'马格里布唯一没有被并入奥斯曼帝国的地方:土军打进来过,却没能留下。',
  e:{ n:'the Moroccan dynasties', w:'History of Morocco', b:'The one part of the Maghreb that never became an Ottoman province: their troops got in, but never stayed.', d:'The Marinids finished off the Almohads in 1269 and ruled from Fez, which under them became one of the great learning cities of the Muslim world; the traveller Ibn Battuta, born in Tangier, came back here after nearly thirty years on the road and dictated his book at Fez. The Ottomans took all of North Africa as far west as Algiers but never Morocco: in 1578 at the Battle of the Three Kings the Saadians destroyed a Portuguese invasion and killed its young king, and in 1591 they sent an army across the Sahara and broke the Songhai empire on the Niger. The Alaouites have reigned since the 1660s and reign still — the king in Rabat today belongs to the same family. European pressure closed in through the nineteenth century, and in 1912 France made the country a protectorate, with Spain holding the north; independence came in 1956. Its wealth was the trans-Saharan trade — gold coming north and slabs of salt going south — and the walled old city of Fez, with no cars in it, is still one of the largest living medieval cities anywhere.', f:{ 'Peak':'1578–1603 (the Saadians)', 'Centre':'Fez, Marrakesh, Meknes', 'Figures':'Ibn Battuta, Moulay Ismail', 'Legacy':'the Battle of the Three Kings, the trans-Saharan roads, the old city of Fez' } },
  f:{ '鼎盛':'1578—1603年(萨阿德王朝)', '中心':'非斯、马拉喀什、梅克内斯', '人物':'伊本·白图泰、穆莱·伊斯玛仪', '成就':'三王之战、跨撒哈拉商路、非斯老城' },
  qh:{ born:['白图泰走了近三十年,回非斯口述成书','Ibn Battuta came back to Fez and dictated his book'],
       rule:['今天的国王,和 1660 年代那位是一家','Today\'s king is of the same family as in the 1660s'],
       money:['黄金往北走,盐往南走','Gold went north and salt went south'],
       power:['奥斯曼拿下了整个北非,唯独没拿下这里','The Ottomans took all of North Africa except this'],
       fall:['1912 年法国来了,1956 年走了','France came in 1912 and left in 1956'],
       legacy:['非斯老城里到今天开不进汽车','No car can get into the old city of Fez even now'] },
  q:{ born:['1269 年马林人攻下马拉喀什,统治了一百多年的穆瓦希德王朝结束,摩洛哥从此有了自己的中心。马林人把都城定在非斯,在老城旁边另建新城,一座接一座地盖起学院——非斯由此成为伊斯兰世界最重要的学问城市之一。丹吉尔人伊本·白图泰 1325 年从家乡动身去麦加朝觐,一走将近三十年,到过东非、印度、中国;回来后正是在非斯,奉素丹之命把一路见闻口述成书,他是中世纪走得最远的旅行家之一。','The Marinids took Marrakesh in 1269, ending the Almohad dynasty that had ruled for over a century, and from then on Morocco had a centre of its own. They made Fez their capital, built a new town beside the old one and put up college after college, and Fez became one of the great cities of learning in the Muslim world. Ibn Battuta set out from his native Tangier for Mecca in 1325 and was gone nearly thirty years, reaching East Africa, India and China; it was at Fez, on the sultan\'s orders, that he dictated the book of his travels on his return — among the furthest-travelled men of the Middle Ages.'],
      rule:['统治者称素丹,但真正让人服气的不是官职,是血统与信仰:萨阿德和阿拉维两个王朝都自称先知的后裔(谢里夫),这在部落林立的地方比军队更管用,苏菲教团则把王权的影响一直伸进乡村。山里的柏柏尔部落长期只认松散的臣属,中央能直接收税的地方叫「政府地」,收不上税的叫「化外地」,两者的边界几百年里来回移动。阿拉维王朝从 1660 年代坐到今天——今天在拉巴特的国王,和当年那位是同一个家族,这是世界上延续最久的王朝之一。','The ruler was called sultan, but what commanded obedience was not the office so much as descent and faith: both the Saadians and the Alaouites claimed descent from the Prophet, which counted for more than an army in a land of tribes, while the Sufi brotherhoods carried the throne\'s influence into the countryside. The Berber tribes of the mountains acknowledged only a loose allegiance, and the land the government could actually tax was distinguished from the land it could not, the boundary between them shifting back and forth for centuries. The Alaouites have held the throne since the 1660s — the king in Rabat today is of that same family, one of the longest-reigning dynasties in the world.'],
      money:['财富来自穿过撒哈拉的商路:黄金和盐是两头最重要的货,黄金从尼日尔河一带往北运,撒哈拉中部盐矿的盐板往南运,骆驼队走上两个月;同一条路上还有被卖过沙漠的人,这桩买卖在这一带持续了好几百年。非斯和马拉喀什是这些商路的北端市场,皮革、铜器、织物在这里加工;非斯的染坊今天还在用几百年前的石头染缸。大西洋沿岸的港口另有一条线,与欧洲做糖、织物和武器的生意。1591 年萨阿德的军队跨过沙漠打垮桑海帝国,一个直接的动机就是想把产金地攥在自己手里。','Its wealth came from the roads across the Sahara: gold and salt were the two great cargoes, gold carried north from the Niger country and slabs of salt from the mines of the central desert carried south, the camel caravans taking two months; the same roads carried enslaved people across the desert, a trade that went on here for centuries. Fez and Marrakesh were the northern markets of these roads, where leather, copperware and cloth were worked; the tanneries of Fez still use stone vats laid out centuries ago. The Atlantic ports ran a second line of trade with Europe in sugar, cloth and weapons. When a Saadian army crossed the desert in 1591 and broke the Songhai empire, one plain motive was to get hold of the goldfields themselves.'],
      power:['奥斯曼帝国 16 世纪拿下了埃及、的黎波里、突尼斯和阿尔及尔,整条北非海岸只剩摩洛哥没进去——阿特拉斯山、沙漠和一支肯打硬仗的军队把它挡在了特莱姆森以东。1578 年葡萄牙国王塞巴斯蒂昂带兵渡海而来,想扶植一位被废的素丹,双方在马哈赞河边会战,葡军大败,塞巴斯蒂昂本人战死,这一仗因为一天里死了三位君主而被称作「三王之战」;葡萄牙两年后被西班牙合并,和这场败仗直接相关。土军并非没有进来过——1554 年他们一度攻入非斯、立了一位听命于自己的素丹,四个月后被萨阿德赶走;1576 年又扶了一位承认奥斯曼哈里发的素丹上台。但摩洛哥始终没有变成奥斯曼的一个行省,这在马格里布是唯一的。','In the sixteenth century the Ottomans took Egypt, Tripoli, Tunis and Algiers, and of the whole North African coast only Morocco stayed outside — the Atlas mountains, the desert and an army willing to fight held them east of Tlemcen. In 1578 King Sebastian of Portugal shipped an army across to put a deposed sultan back on the throne; the two sides met by the Makhazin river, the Portuguese were destroyed and Sebastian himself was killed, and because three rulers died in a single day it is remembered as the Battle of the Three Kings. Portugal was absorbed by Spain two years later, a direct consequence. Ottoman troops did get in — in 1554 they briefly took Fez and installed a sultan of their own choosing, driven out four months later, and in 1576 they backed another who acknowledged the Ottoman caliph. But Morocco never became an Ottoman province, and in the Maghreb it was alone in that.'],
      fall:['挡住了奥斯曼,没挡住 19 世纪的欧洲。1844 年败于法国、1859—1860 年败于西班牙之后,赔款与借款让财政落进外国银行手里,海关也被抵押出去。1906 年的国际会议把摩洛哥的门户「开放」给列强,1912 年法国正式设立保护国,西班牙分得北部一条和南部一块,丹吉尔另划为国际共管区。1953 年法国废黜并流放了素丹穆罕默德五世(先送科西嘉,次年转马达加斯加),反而点燃了全国抗议,1955 年他被迎回,1956 年摩洛哥独立——从保护国到独立只用了四十四年,王朝没有中断。','It held off the Ottomans but not nineteenth-century Europe. After defeats by France in 1844 and Spain in 1859-60, indemnities and loans put the treasury in the hands of foreign banks and the customs revenue was pledged away. An international conference in 1906 opened the country to the powers, and in 1912 France declared a protectorate, Spain taking a strip in the north and a zone in the south while Tangier was placed under international administration. When the French deposed and deported Sultan Mohammed V in 1953 — first to Corsica, then to Madagascar the following year — the country erupted in protest; he was brought back in 1955 and Morocco became independent in 1956 — forty-four years from protectorate to independence, with the dynasty unbroken.'],
      legacy:['非斯老城是今天世界上最大的、还住着人的中世纪城区之一,巷子窄到汽车开不进去,运货靠驴;它和马拉喀什、梅克内斯的老城都在世界遗产名录上。非斯的卡鲁因清真寺附属的学校创办于 859 年,常被称作世界上持续办学时间最长的大学。伊本·白图泰的游记至今是了解 14 世纪亚非世界最重要的一手材料之一。还有一件容易被忘掉的事:1777 年摩洛哥宣布美国船只可以自由进出它的港口,常被算作第一个承认美国独立的国家,1786 年签约以来两国的条约关系一直没断过,常被称作美国持续时间最长的一段。','The old city of Fez is one of the largest medieval quarters anywhere still lived in, its lanes too narrow for cars so that goods move by donkey; it stands on the World Heritage list along with the old cities of Marrakesh and Meknes. The school attached to the Qarawiyyin mosque in Fez was founded in 859 and is often called the longest continuously operating university in the world. Ibn Battuta\'s travel book remains one of the most important first-hand sources for the fourteenth-century world of Asia and Africa. And one thing easily forgotten: in 1777 Morocco declared American ships free to enter its ports, which is generally counted as the first recognition of American independence, and the treaty relationship begun in 1786 has never lapsed since — often called the longest unbroken one the United States has.'] },
  d:'1269 年马林人灭穆瓦希德、定都非斯,把它建成伊斯兰世界的学问重镇,伊本·白图泰从这里出发走了近三十年。16 世纪奥斯曼拿下整条北非海岸,唯独摩洛哥没进去:1578 年三王之战大败葡萄牙,1591 年跨撒哈拉远征打垮桑海。阿拉维王朝自 1660 年代在位至今——今天在拉巴特的国王就是这一家。财富靠黄金与盐的跨撒哈拉商路,那条路上也贩人;非斯老城至今窄得开不进汽车,是世界上最大的、还住着人的中世纪城区之一。19 世纪败于法国与西班牙,1912 年成为法国保护国(西班牙分得南北两块),1956 年独立。' },
{ l:'me', s:'mideast', v:1, n:'海湾诸邦', k:[[1258,0],[1400,.24],[1500,.3],[1622,.24],[1800,.26],[1900,.3],[1918,0]], b:'石油之前,这片海最值钱的东西是珍珠;守着海峡的那些小邦,就是今天海湾各国的前身。',
  e:{ n:'the Gulf principalities', w:'History of the United Arab Emirates', b:'Before oil, the most valuable thing in this sea was pearls; the small states that watched the strait are the ancestors of today\'s Gulf countries.', d:'After the Mongols destroyed Baghdad in 1258 the trade of the Gulf shifted to Hormuz, whose kings sat on an island at the mouth of the sea and taxed everything that passed; Ibn Battuta saw the island city in the 1330s and Marco Polo, earlier, the older town on the mainland; an old saying held that if the world were a ring, Hormuz would be the jewel in it. The Portuguese took Hormuz in 1507 and held it until 1622, when Safavid Persia and the English East India Company together drove them out. What lay along the southern shore was not one country but a row of small ports, each under its own sheikh and each living off the sea: pearl diving from June to September, divers going down ten metres and more on a single breath with a nose-clip of horn, and the dhows carrying dates and cloth to India and East Africa. Britain signed a general treaty with the sheikhs in 1820 and a permanent truce in 1853 — which is why they became known as the Trucial States — and took charge of their foreign relations in 1892. Dubai, a place named in writing since the eleventh century, broke away from Abu Dhabi in 1833 under Maktoum bin Butti. The pearl trade collapsed in the 1930s when Japanese cultured pearls reached the market; oil came to Bahrain in 1932 but to this stretch of coast only decades later.', f:{ 'Peak':'c. 1300–1500 (the kingdom of Hormuz)', 'Centre':'Hormuz, Sharjah, Dubai', 'Figures':'Maktoum bin Butti', 'Legacy':'pearl diving, the dhow, the Strait of Hormuz' } },
  f:{ '鼎盛':'约1300—1500年(霍尔木兹王国)', '中心':'霍尔木兹、沙迦、迪拜', '人物':'马克图姆·本·布蒂', '成就':'采珍珠、单桅帆船、霍尔木兹海峡' },
  qh:{ born:['巴格达一倒,海上的买卖挪到了霍尔木兹','When Baghdad fell, the sea trade moved to Hormuz'],
       rule:['谁能护住采珠船,谁就是这里的头人','Whoever could protect the pearling boats was the chief here'],
       money:['石油之前,这里最值钱的是珍珠','Before oil, the most valuable thing here was pearls'],
       power:['海峡最窄处,只有几十公里宽','At its narrowest the strait is a few tens of kilometres'],
       fall:['珍珠先垮了,石油还没来','The pearls collapsed before the oil arrived'],
       legacy:['今天的七个酋长国,就是当年那些小港','Today\'s seven emirates are those old ports'] },
  q:{ born:['1258 年蒙古人毁掉巴格达,两河流域那条走了几百年的商路断了,海上的买卖挪到波斯湾口的霍尔木兹。霍尔木兹的国王把王城搬到海峡口的一座小岛上,岛上不产淡水也不长庄稼,全靠对过往船只收税和转口贸易——伊本·白图泰 1330 年代到过岛上这座新城;更早的马可·波罗看到的还是大陆上的老霍尔木兹——迁到岛上是他之后的事。有句老话说,如果世界是一枚戒指,霍尔木兹就是上面那颗宝石。','When the Mongols destroyed Baghdad in 1258 the caravan road through Mesopotamia, used for centuries, was cut, and the trade went by sea to Hormuz at the mouth of the Gulf. The kings of Hormuz moved their capital to a small island in the strait, an island with no fresh water and no crops, living entirely on the tax it took from passing ships and on entrepôt trade — Ibn Battuta saw this island city in the 1330s; Marco Polo, earlier, saw the older Hormuz on the mainland — the move to the island came after him. An old saying had it that if the world were a ring, Hormuz would be the jewel set in it.'],
      rule:['南岸从来不是一个国家,是一排各管各的小港:科威特、巴林、多哈、阿布扎比、沙迦、迪拜……每个港由一个部落的谢赫(酋长)统着,权力来自能不能护住采珠船和商队,而不是能收多少地税——这一带内陆是沙漠,没有农业可收税。港与港之间常年争夺珠场和水源,也常年通婚结盟。迪拜这个地名 11 世纪就见于记载,到 1822 年已是个七八百人的小镇;1833 年马克图姆·本·布蒂带阿勒布法拉萨部落的八百来人从阿布扎比脱离出来,在迪拜溪边自立,今天的迪拜王室就是这一支。','The southern shore was never one country but a row of ports each looking after itself: Kuwait, Bahrain, Doha, Abu Dhabi, Sharjah, Dubai. Each was held by the sheikh of a tribe whose power rested on whether he could protect the pearling boats and the caravans, not on how much land tax he could collect — the interior is desert and there was no farming to tax. The ports quarrelled endlessly over pearl banks and wells, and married into one another just as endlessly. Dubai is named in writing as early as the eleventh century and was a town of seven or eight hundred people by 1822; in 1833 Maktoum bin Butti led some eight hundred of the Al Bu Falasah out of Abu Dhabi to set up on their own by the creek, and the ruling family of Dubai today is that line.'],
      money:['石油之前,这片海最值钱的东西是珍珠。每年六月到九月是采珠季,几百条船出海,一去就是三四个月:采珠人脚上系一块石头沉到十几米深,鼻子上夹一只龟甲做的鼻夹,不带任何呼吸装备,一口气一分多钟,一天下潜几十次,靠船上的人拉绳子拽上来。采珠人挣的常常还不够还船主先垫的钱,欠债一年年滚下去,有的还传给儿子;船上也有从非洲被卖过来的人。珠子分等级卖到印度,再从印度进入欧洲。除珍珠外还有单桅帆船跑的转口生意:椰枣、布匹、马匹运去印度和东非。1930 年代日本养殖珍珠上市,海湾天然珍珠几年之内卖不动了,整片海岸陷入萧条。石油来得早晚不一:巴林 1932 年就出油,而南岸这一段要再等上二三十年。','Before oil, the most valuable thing in this sea was pearls. The season ran from June to September, when hundreds of boats went out for three or four months at a time: a diver went down ten metres and more with a stone tied to his foot and a nose-clip of turtle shell, carrying no breathing gear at all, a minute or so on one breath, dozens of dives a day, hauled up on a rope by the men in the boat. What a diver earned was often less than what the captain had advanced him, and the debt rolled on from year to year and sometimes passed to his sons; there were also people aboard who had been bought and brought from Africa. The pearls were graded and sold into India, and from India into Europe. Alongside the pearls the dhows ran an entrepôt trade, carrying dates, cloth and horses to India and East Africa. When Japanese cultured pearls reached the market in the 1930s the natural pearl of the Gulf became unsellable within a few years and the whole coast fell into depression. Oil came at very different times: Bahrain struck it in 1932, while this stretch of the southern shore had another twenty or thirty years to wait.'],
      power:['进出这片海只有一道门:霍尔木兹海峡,最窄处只有几十公里。谁守着这道门,谁就能对整片海的贸易说话——所以海峡口的那座小岛在几百年里被反复争夺。1507 年葡萄牙人阿尔布克尔克带舰队攻占霍尔木兹,在岛上筑城,把波斯湾变成葡萄牙印度洋网络的一环;1622 年波斯的萨法维王朝与英国东印度公司联手,把葡萄牙人赶了出去。此后荷兰、英国、波斯、阿曼和本地的卡瓦西姆部落在这片海上反复较量,英国人把卡瓦西姆的船队称作「海盗」;海湾这边的史家后来提出,这个罪名多半是英国人为了控制这条贸易线做出来的。','There is only one door in and out of this sea: the Strait of Hormuz, a few tens of kilometres across at its narrowest. Whoever holds that door has a say over the trade of the whole Gulf, which is why the little island at its mouth was fought over for centuries. In 1507 Afonso de Albuquerque took Hormuz for Portugal and built a fort on the island, making the Gulf one link in the Portuguese network across the Indian Ocean; in 1622 Safavid Persia and the English East India Company drove the Portuguese out together. After that the Dutch, the English, the Persians, Oman and the local Qawasim tribe contended over these waters for two centuries — the British called the Qawasim fleet pirates, while historians from the Gulf side have since argued that the charge was largely manufactured to justify controlling the trade.'],
      fall:['1819 年英国舰队打掉卡瓦西姆的船队,次年与南岸各酋长签了一份总条约,1853 年又签「永久休战条约」——「休战诸国」这个名字就是这么来的。1892 年的排他协定把各邦的外交权交给英国:不得与第三国往来,不得把土地让与他人。换来的是英国保护,失去的是对外的手脚。这条带到 1918 年为止,此后的故事在「现代中东」里:1971 年英国从苏伊士以东撤军,同年六个酋长国合成阿联酋,第七个哈伊马角第二年加入,卡塔尔和巴林各自独立。','A British squadron destroyed the Qawasim fleet in 1819, and in 1820 Britain signed a general treaty with the sheikhs of the southern shore, followed in 1853 by a permanent maritime truce — which is where the name Trucial States comes from. The exclusive agreement of 1892 handed their foreign relations to Britain: no dealings with any third power, no ceding of territory to anyone else. What they got was British protection; what they lost was any hand of their own abroad. This band ends in 1918 and the rest of the story belongs to the modern Middle East: Britain withdrew from east of Suez in 1971, and in the same year six of the emirates joined into the United Arab Emirates, the seventh following in 1972, while Qatar and Bahrain each went their own way.'],
      legacy:['今天海湾那几个国家,就是当年那一排小港长成的:迪拜、沙迦、阿布扎比这些名字在采珠时代就已经在了。采珠业留下的东西不只是记忆——「船长」(nokhitha)、拉绳人、潜水人那套分工至今有人讲得出,采珠船上唱的劳动号子(巴林的「菲吉里」)已列入联合国教科文组织的人类非物质文化遗产。单桅帆船还在造,只是改用发动机跑短途货运。迪拜溪两岸的老市场保留着当年金银与香料的行当。给孩子最容易记住的一件事:一个今天以最高的楼出名的地方,一百年前全城的钱都来自一群不带任何装备、一口气潜到十几米深的人。','The countries of the Gulf today grew out of that row of ports: Dubai, Sharjah and Abu Dhabi were all names in the pearling age. What pearling left is more than a memory — the division of work between captain, hauler and diver is still remembered, and the work songs sung aboard the boats — Bahrain\'s fjiri — are on the UNESCO list of intangible heritage of humanity. Dhows are still built, though they run short cargo trips under engines now. The old markets along both banks of Dubai creek still deal in gold and spices. The easiest thing for a child to remember: a place now known for the tallest building on earth got all of its money, a hundred years ago, from men who went ten metres down on one breath with no equipment at all.'] },
  d:'1258 年巴格达陷落后海上贸易转到波斯湾口的霍尔木兹。那座靠收过路税富起来的岛城,伊本·白图泰 1330 年代到过,更早的马可·波罗见到的还是大陆上的老霍尔木兹;有句老话说,如果世界是一枚戒指,霍尔木兹就是上面那颗宝石。1507 年葡萄牙人来夺、1515 年才站稳,1622 年萨法维与英国东印度公司联手把他们赶走。南岸不是一个国家,是一排由部落谢赫统治的小港,靠采珍珠与单桅帆船的转口贸易为生:每年六月到九月出海,采珠人脚上系石头下潜十几米、鼻子夹一只龟甲鼻夹,不带任何呼吸装备。迪拜这个地名 11 世纪就见于记载,1833 年阿勒布法拉萨部落从阿布扎比脱离出来在迪拜溪边自立。1820 年起英国与各酋长签约,1853 年永久休战、1892 年交出外交权,史称「休战诸国」。1930 年代日本养殖珍珠上市,天然珍珠生意崩溃;石油在巴林 1932 年就出了,南岸这一段还要再等二三十年。' },
{ l:'me', s:'mideast', v:0, n:'现代中东', k:[[1918,0],[1950,.35],[1973,.5],[2025,.45]], b:'奥斯曼解体后的民族国家格局;石油改写地缘权重。',
  e:{ n:'Modern Middle East', w:'Middle East', b:'Nation-states from the Ottoman estate; oil rewrites the weights.', d:'British and French mandates cut today\'s states from the Ottoman corpse; Israel\'s founding brought repeated wars, and oil made the Gulf suddenly rich. Sect, nation and great-power play still intersect here.', f:{ 'Oil turn':'1973 oil crisis', 'Peak':'the 1970s (petrodollars)', 'Center':'Cairo, Riyadh, Tehran, Istanbul', 'Figures':'Atatürk, Nasser', 'Legacy':'OPEC, Suez nationalization' } },
  f:{ '石油拐点':'1973年石油危机', '鼎盛':'1970年代(石油美元)', '中心':'开罗、利雅得、德黑兰、伊斯坦布尔', '人物':'凯末尔、纳赛尔', '成就':'OPEC、苏伊士运河国有化' },
  qh:{ born:['边界大多是直线,和实际住的人对不上','Borders drawn straight, and not matching who lived there'],
       rule:['收入靠卖资源,不靠收税','Revenue from selling resources, not from taxing people'],
       money:['石油输出国组织,第一次让产油国能定价','OPEC let the producers influence the price for the first time'],
       power:['两条咽喉:苏伊士运河和霍尔木兹','Two chokepoints: Suez and Hormuz'],
       fall:['1979年一年里,发生了三件大事','Three things happened in the single year 1979'],
       legacy:['希腊的书,是从阿拉伯语转回欧洲的','The Greek books came back to Europe by way of Arabic'] },
  q:{ born:['奥斯曼帝国在一战中战败解体,英法按事先的协定划分了它的阿拉伯行省,新边界大多是直线,与部族和教派的实际分布对不上。1923年凯末尔在安纳托利亚建立土耳其共和国;此后三十年间,阿拉伯各国陆续独立,1948年以色列建国。今天中东的国家格局与许多争端,都可以追到这一次划分。','The Ottoman Empire lost the First World War and broke up, and Britain and France divided its Arab provinces along lines agreed in advance — mostly straight ones, drawn without much regard to where tribes and sects actually lived. Atatürk founded the Turkish Republic in Anatolia in 1923; over the next thirty years the Arab states became independent one by one, and Israel was founded in 1948. The map of the region today, and many of its disputes, trace back to that partition.'],
      rule:['形式差别很大:君主制(沙特、约旦、海湾各国)、共和制(埃及、土耳其)、教士主导的体制(1979年后的伊朗)。石油国家有一个共同特点——政府收入主要来自资源出口而非税收,这改变了国家与民众之间的关系(通常被称为「食利国家」),也让经济多元化成为各国长期议程。','The forms vary widely: monarchies in Saudi Arabia, Jordan and the Gulf; republics in Egypt and Turkey; a clerically led system in Iran after 1979. The oil states share one feature — government income comes mainly from selling a resource rather than from taxing citizens, which changes the relationship between state and society, and makes diversifying the economy a standing item on every agenda.'],
      money:['世界已探明石油储量的约一半在这一带。1960年成立的石油输出国组织让产油国第一次能共同影响价格,1973年油价暴涨把巨额财富转入这一区域,也把「石油美元」变成国际金融体系的一部分。近二十年海湾国家大力投向航空、物流、金融与旅游,试图在石油之外再建一根支柱。','About half the world\'s proven oil reserves lie in this region. The Organization of the Petroleum Exporting Countries, founded in 1960, let producers act together on price for the first time, and the price shock of 1973 moved enormous wealth into the region and made the petrodollar part of the international financial system. Over the past twenty years the Gulf states have invested heavily in aviation, logistics, finance and tourism, trying to build a second pillar beside oil.'],
      power:['位置与资源。三大洲的交汇处、苏伊士运河与霍尔木兹海峡两条咽喉,让这里在任何时代都是必争之地——1956年埃及把苏伊士运河国有化,是战后殖民力量退场的标志性事件之一。此外,它是犹太教、基督教与伊斯兰教三大宗教的共同发源地,耶路撒冷的地位问题至今是争端核心。','Position and resources. Sitting where three continents meet, holding both the Suez Canal and the Strait of Hormuz, it has been contested in every era — Egypt\'s nationalisation of the canal in 1956 was among the defining moments of the retreat of colonial power after the war. It is also the common birthplace of Judaism, Christianity and Islam, and the status of Jerusalem remains at the centre of the region\'s disputes.'],
      fall:['1979年是最近一次影响全局的转折,同一年发生了三件事:伊朗革命推翻巴列维王朝、建立了教士主导的体制;苏联出兵阿富汗;沙特麦加大清真寺遭武装占领。此后区域格局沿着教派与阵营重新划线,后来数十年的许多冲突都能追到这一年。','The year 1979 was the last turning point to reshape the whole region, and three things happened in it: revolution in Iran overthrew the monarchy and installed a clerically led system; the Soviet Union sent troops into Afghanistan; and armed men seized the Grand Mosque in Mecca. The region realigned along sectarian and bloc lines afterwards, and a great many of the conflicts of the decades since can be traced to that year.'],
      legacy:['这里是农业与城市最早出现的地方,也是字母文字的源头。中世纪的阿拉伯语学术把希腊典籍系统翻译、注释并推进,再经西班牙与西西里传回欧洲,是文艺复兴的重要前提。今天的一神教三大宗教有数十亿信徒;而阿拉伯数字、代数与化学这些词本身,就是那段学术传统留下的痕迹。','This is where farming and cities first appeared, and where alphabetic writing began. Medieval Arabic scholarship systematically translated, annotated and advanced the Greek inheritance, which returned to Europe through Spain and Sicily and was a precondition of the Renaissance. The three monotheisms born here have billions of adherents today, and the words algebra, alchemy and the Arabic numerals themselves are traces of that scholarly tradition.'] },
  d:'奥斯曼解体后由英法委任统治切割出今日诸国;以色列建国引发数次战争,石油让海湾国家骤富,OPEC一度扼住世界经济的咽喉。教派、民族与大国博弈在此交织,至今仍是世界地缘最敏感的地带。' },
/* 草原·中亚 */
{ l:'st', s:'steppe', v:1, n:'斯基泰', k:[[-900,0],[-600,.4],[-300,.3],[-200,0]], b:'最早见于记载的骑马游牧民,黑海草原的黄金艺术。',
  e:{ n:'Scythians', b:'The first recorded horse nomads; gold art of the steppe.', d:'Herodotus\' unconquerable riders — "no cities to take, no crops to burn" — outlasted even Darius\' invasion; their goldwork is the peak of steppe art, and they set the nomad-vs-sown pattern for two millennia.', f:{ 'Peak':'7th-4th c. BCE', 'Center':'Pontic steppe', 'Figures':'Ateas', 'Legacy':'Mounted archery, animal-style gold' } },
  f:{ '鼎盛':'前7—前4世纪', '中心':'黑海北岸草原', '人物':'阿提亚斯', '成就':'骑射战术、动物纹黄金艺术' },
  qh:{ born:['马、弓、大车凑齐,草场就变成骑兵','Horse, bow and wagon together turned pasture into cavalry'],
       rule:['没有城,没有文字,也没有官僚','No cities, no writing, no bureaucracy'],
       money:['草原的品味,希腊的手艺','Steppe taste, Greek workmanship'],
       power:['大流士带大军追了半天,追了个空','Darius chased them across the steppe and caught nothing'],
       fall:['从东边挤过来的,是说同一种语的亲戚','Those pushing in from the east spoke a language close to theirs'],
       legacy:['动物纹黄金,从草原一路传到两头','Animal-style gold travelled the steppe in both directions'] },
  q:{ born:['草原喂不饱定居国家,却能喂饱马。当马的驯乘、复合弓与带篷大车凑齐,黑海北岸的部落第一次可以带着全部家当移动,把草场直接换成骑兵。这套组合在公元前9世纪前后于黑海到阿尔泰一线成形,斯基泰是其中有系统文字记载的最早一批。','Grassland cannot feed a city, but it can feed horses. Once riding, the composite bow and the covered wagon came together, the tribes north of the Black Sea could move with everything they owned and turn pasture directly into cavalry. This package took shape between the Black Sea and the Altai around the 9th century BC, and the Scythians are the earliest such people described at length in writing.'],
      rule:['据希罗多德记载,他们分成若干部落,以“王族斯基泰”为尊,没有城,没有文字,也没有官僚。统治靠血缘与战功:巨大的库尔干墓里国王与侍从、马匹一同下葬,等级极森严。因为主要史料出自希腊人之手,这套制度的内部细节我们其实知道得很少。','Herodotus reports a set of tribes headed by the \'Royal Scythians\', with no cities, no writing and no bureaucracy. Authority rested on kinship and war record: in the huge kurgan tombs a king was buried together with attendants and horses, which shows a very steep hierarchy. Since our main source is Greek, we actually know little about how the system worked from the inside.'],
      money:['牲畜是本钱,现金流来自谷物与黄金。黑海北岸的希腊殖民城邦(如奥尔比亚)把粮食运回雅典,斯基泰控制着产粮的属民与商路,收保护费与过境税。换来的财富变成希腊工匠为他们定制的动物纹金器——草原的品味,希腊的手艺。','Herds were the capital; the cash came from grain and gold. Greek colonies on the north Black Sea coast such as Olbia shipped grain to Athens, and the Scythians controlled both the farming subjects and the routes, taking protection payments and transit dues. The wealth came back as animal-style gold made to order by Greek craftsmen: steppe taste, Greek hands.'],
      power:['强在“打不着”。全民骑射,没有城可攻、没有仓可烧,遇强敌就退,退中回身放箭。前513年前后大流士率波斯大军北征,追着他们在草原上空转,最后无功而返——定居帝国拿骑马民族没办法,从这里就开始了。','Their strength was being unhittable. Everyone rode and shot; there was no city to storm and no granary to burn, so they withdrew before a strong enemy and shot backwards as they went. Around 513 BC Darius marched a Persian army north, chased them in circles across the steppe and went home with nothing, and the trouble settled empires have in fighting nomads starts here.'],
      fall:['不是被谁一战打垮,而是被两头挤没的。东边同属伊朗语的萨尔马提亚人自前3世纪起不断西进,西边有色雷斯人与凯尔特人;失去大草场后他们退缩到克里米亚一隅,史称“小斯基泰”。此后在本都、罗马与哥特人的轮番冲击下作为政治体消失,人则融入了后来的族群。','No single battle ended them; they were squeezed from both sides. From the 3rd century BC the Sarmatians, another Iranian-speaking people, pushed west, while Thracians and Celts pressed from the other direction; losing the open pasture, they shrank into Crimea, the \'Lesser Scythia\' of the sources. Later blows from Pontus, Rome and the Goths ended them as a polity, and the people were absorbed into those who came after.'],
      legacy:['他们定下了此后两千年的剧本:草原骑射者与定居农耕帝国长期对峙,谁也吃不掉谁。留下的实物是动物纹黄金——鹿、豹、格里芬扭成一团,这套图案沿草原一路传到中国北方与欧洲。希罗多德为他们写的那几十页,至今仍是我们能读到的、关于欧亚草原民族最早的详细民族志。','They set the script for the next two thousand years: mounted steppe archers and settled farming empires locked in a standoff neither could win outright. The physical legacy is animal-style gold, deer and panthers and griffins twisted together, a visual language that travelled along the steppe to northern China and to Europe. And the dozens of pages Herodotus wrote about them are still the earliest detailed ethnography of any Eurasian steppe people that we can read.'] },
  d:'希罗多德笔下"无城可攻、无粮可焚"的骑马民族,大流士倾波斯之力远征也无功而返;其墓葬出土的黄金饰品是草原艺术的巅峰,也开启了此后两千年游牧与定居世界对峙的基本格局。' },
{ l:'st', s:'steppe', v:0, n:'匈奴', k:[[-300,0],[-200,.6],[-50,.4],[100,.3],[200,0]], b:'首个草原帝国,迫汉和亲修长城,与汉缠斗三百年。',
  e:{ n:'Xiongnu', b:'The first steppe empire; three centuries sparring with Han China.', d:'Modu unified the tribes and besieged the Han founder at Baideng, extracting tribute for decades; Emperor Wu\'s counteroffensives broke them into southern submission and northern flight. Some scholars link the later European Huns to their descendants — still debated.', f:{ 'Peak':'Modu Chanyu (209–174 BCE)', 'Center':'Mongolian steppe', 'Figures':'Modu Chanyu', 'Legacy':'The steppe-empire model' } },
  f:{ '鼎盛':'冒顿单于(前209—前174)', '中心':'漠北单于庭', '人物':'冒顿单于', '成就':'首创草原帝国体制' },
  qh:{ born:['南边整合到什么程度,北边就跟到什么程度','However far the south unified, the north had to match'],
       rule:['黏合剂是亲缘、战功和分赃','The glue was kinship, war merit and a share of the loot'],
       money:['收入线,就是权力线','The line of income was the line of power'],
       power:['打得赢就抢,打不赢就谈','Win and raid; lose and negotiate'],
       fall:['牧场和税源一断,分配体系就失血','Cut the pastures and the tax, and the sharing system bled out'],
       legacy:['和亲、互市、长城,这三件套定型了','Marriage, markets and the wall became the standard set'] },
  q:{ born:['草原上部落分散才是常态,要凑成帝国得有外力。秦统一后北筑长城、蒙恬夺河南地,把散居的部落挤到一起;前209年冒顿统一诸部,建起单于—左右贤王的架子。有学者认为草原帝国本就是中原统一帝国的“影子”:南边整合到什么程度,北边就得整合到什么程度。','Scattered tribes are the steppe\'s normal state; it takes outside pressure to fuse them into an empire. After Qin unified China it walled the north and Meng Tian drove the tribes out of the Ordos, pushing them together; in 209 BC Modu unified the tribes and built the framework of a chanyu with Kings of the Left and Right. Some scholars see the steppe empire as the shadow of a unified China: the more the south consolidated, the more the north had to.'],
      rule:['单于之下分左右两翼,再往下是二十四长,军政合一,按十进制编成十长、百长、千长、万骑。核心职位由呼衍、兰、须卜等几个贵族氏族世袭,单于与它们通婚。没有文书官僚,统治的黏合剂是亲缘、战功和分赃。','Below the chanyu the realm split into a left and a right wing, and under them twenty-four chiefs who were both commanders and governors, with troops organised by tens, hundreds, thousands and ten-thousands. The top posts were hereditary in a few noble clans, Huyan, Lan and Xubu, into which the chanyu married. There was no paperwork bureaucracy; kinship, war record and the sharing of spoils held it together.'],
      money:['牲畜只够活命,帝国得靠三条外部收入:和亲带来的絮缯酒米、边境关市的贸易,以及西域的赋税——匈奴专设“僮仆都尉”向绿洲城邦征收。有学者认为,关键在于单于把这些中原物资再分给各部首领,谁听话谁有份;收入线就是权力线。','Herds kept people alive, but the empire ran on three outside incomes: the silk, grain and wine that came with Han marriage treaties, trade at the frontier markets, and taxes from the oasis states of the Western Regions, for which the Xiongnu kept a special commandant. The point was redistribution: the chanyu handed these Chinese goods down to loyal chiefs, so the revenue line and the chain of command were the same line.'],
      power:['全民骑射、来去自如是底子,真正的杠杆是“打得赢就抢、打不赢就谈”。前200年白登之围围住汉高祖,换来数十年的和亲纳贡;军事压力越大,岁赐越厚,岁赐越厚,单于对内越有分配权。','Universal mounted archery and sheer mobility were the base, but the real lever was a two-track policy: raid when you can win, negotiate when you cannot. The encirclement of the Han founding emperor at Baideng in 200 BC bought decades of treaty payments; the more military pressure they applied, the richer the annual gifts, and the richer the gifts, the more the chanyu had to hand out at home.'],
      fall:['多重因素叠加。汉武帝反击夺去河西与漠南牧场,又切断西域税源,分配体系失血;继位没有明确规则,前1世纪出现五单于并立,呼韩邪南下称臣;公元48年分为南北,南匈奴内附,北匈奴在鲜卑与汉军夹击、加上史载的连年灾疫下溃散西迁。','Several causes stacked up. Han counteroffensives under Emperor Wu took the Hexi and southern desert pastures and cut off the Western Regions revenue, bleeding the redistribution system dry; succession had no fixed rule, so by the 1st century BC five rival chanyus were in the field and Huhanye submitted to Han. In AD 48 the state split, the southern branch moving inside the Han frontier while the northern one broke up and drifted west under attack from the Xianbei and Han forces, amid the famines and epidemics the sources record.'],
      legacy:['它第一次回答了“草原能不能变成帝国”这道题,单于—二十四长的架子被后来的柔然、突厥、蒙古反复借用。和亲、互市、长城三件套,成了此后一千多年农耕与游牧关系的固定模式。至于西迁的北匈奴是不是后来横扫欧洲的匈人,学界至今没有定论。','They produced the first working answer to the question of whether the steppe could become an empire, and the chanyu-plus-chiefs framework was borrowed again and again by the Rouran, the Turks and the Mongols. Marriage treaties, frontier markets and the Wall became the standing template for farmer-nomad relations for the next thousand years. Whether the northern Xiongnu who moved west became the Huns of Europe remains unsettled among scholars.'] },
  d:'冒顿以"鸣镝"(响箭)号令部众射杀父亲夺位,统一诸部,白登之围迫使汉朝和亲纳贡数十年;汉武帝倾国反击后由盛转衰,南匈奴内附、北匈奴西遁。有学者认为几百年后横扫欧洲的匈人即其后裔——若然,这是一次改写两端历史的远距离多米诺。' },
{ l:'st', s:'mideast', v:0, n:'粟特', k:[[-100,0],[200,.25],[600,.4],[750,.3],[800,0]], b:'丝绸之路的实际经营者;撒马尔罕的商人网络铺满欧亚。',
  e:{ n:'Sogdia', w:'Sogdia', b:'The people who actually ran the Silk Road.', d:'Nomad empires came and went; the road itself was worked by these Iranian-speaking city merchants. They kept colonies in Chang\'an, Luoyang, the Mongolian steppe and Byzantium — the "Hu merchants" of Chinese sources are mostly them. Their script was borrowed by the Uyghurs, passed to the Mongols, then to the Manchus, and stayed in use into the twentieth century. An Lushan was of Sogdian descent. Turkicization and Islam ended them as a people, but the network they laid down remained.', f:{ 'Peak':'6th–8th c.', 'Center':'Samarkand, Bukhara', 'Figures':'Divashtich', 'Legacy':'The Sogdian script; a trans-Eurasian trade network' } },
  f:{ '鼎盛':'6—8世纪', '中心':'撒马尔罕、布哈拉', '人物':'迪瓦什提奇', '成就':'粟特文字、跨欧亚商业网络' },
  qh:{ born:['靠网络存在,不靠领土存在','A people that existed by network, not by territory'],
       rule:['真正的组织不在家里,在境外','The real organisation was abroad, not at home'],
       money:['聚落是节点,亲族就是信用','The colonies were nodes; kinship was the credit'],
       power:['谁当霸主都得用他们,这就是安全','Whoever ruled needed them; that was the safety'],
       fall:['712年之后,他们连姓都改了','After 712, many even changed their surnames'],
       legacy:['粟特文传给回鹘,回鹘传给蒙古和满洲','Sogdian script passed to Uighur, then Mongol, then Manchu'] },
  q:{ born:['泽拉夫尚河谷的绿洲城邦(撒马尔罕、布哈拉、片治肯特)土地肥沃但块头太小,四周先后是波斯、希腊、贵霜、嚈哒、突厥。打不过任何人,却正好卡在东西南北四条路的中点。于是他们放弃建国这条路,改行做搬运与中介——一个靠网络而不是靠领土存在的民族。','The oasis city-states of the Zarafshan valley, Samarkand, Bukhara and Panjikent, had rich soil but were far too small, and were ruled in turn by Persians, Greeks, Kushans, Hephthalites and Turks. They could not beat anyone, yet they sat exactly where the east-west and north-south roads crossed. So they gave up on building a state and went into carrying and brokering instead: a people that existed as a network rather than a territory.'],
      rule:['没有统一政权,每座城有自己的王,撒马尔罕的君主名义上居首,实际各管各的,对外一律向当时最强的霸主称臣纳贡。真正的组织在境外:从长安、洛阳到蒙古草原、克里米亚,他们建有侨居聚落,由称作“萨保”的首领管理侨民、商队与祆祠;隋唐甚至把萨保纳入官品。','There was never one Sogdian state. Each city had its own king, with the ruler of Samarkand nominally senior, and all of them paid tribute to whichever power was strongest at the time. The real organisation lay abroad: from Chang\'an and Luoyang to the Mongolian steppe and Crimea they planted resident colonies, each run by a headman, the sabao, who managed the community, its caravans and its fire temples; Sui and Tang China even made sabao a ranked official post.'],
      money:['长途贩运:丝绸、麝香、宝石、马匹、奴隶,兼做放贷与代理。聚落是节点,亲族是信用,粟特语成了丝路的通用商业语言。敦煌以西烽燧下出土的“粟特古信札”(约公元4世纪初)是一批真实的商业家书,里面有账目、行情和“洛阳被烧了”这样的坏消息。','Long-distance carrying: silk, musk, gems, horses and slaves, plus moneylending and agency work. The colonies were the nodes, kinship was the credit rating, and Sogdian became the commercial lingua franca of the Silk Road. The Ancient Letters found under a watchtower west of Dunhuang, written around the early 4th century, are real business mail, with accounts, prices and the bad news that Luoyang had been burned.'],
      power:['他们几乎不打仗,力量来自不可替代。突厥可汗把外交与财政交给粟特人办:568年正是粟特商人马尼亚赫替突厥出使拜占庭,想绕开波斯卖丝。在唐朝,粟特人做译语、经商,也从军为将。谁当霸主都需要他们,这就是他们的安全。','They barely fought; their power was being irreplaceable. Turk khagans handed them diplomacy and finance: in 568 it was the Sogdian merchant Maniakh who went to Byzantium on the khagan\'s behalf, trying to sell silk around Persia. In Tang China Sogdians served as interpreters, merchants and army officers. Whoever ruled needed them, and that was their security.'],
      fall:['不是被灭国,而是被溶解。712年阿拉伯军攻下撒马尔罕,河中逐步伊斯兰化;此后突厥人大量迁入,语言换成突厥语与波斯语。安史之乱后在中国做粟特人变得危险,许多人改姓易族。到10世纪,粟特作为独立群体已不复存在。','They were not conquered so much as dissolved. In 712 an Arab army took Samarkand and Transoxiana was gradually Islamised; Turkic settlers then poured in and the language of the land shifted to Turkic and Persian. After the An Lushan rebellion it became dangerous to be Sogdian in China, and many changed surnames and identity. By the 10th century they had ceased to exist as a distinct people.'],
      legacy:['那张网留了下来。粟特文字被回鹘借去,回鹘文再传给蒙古,蒙古文又改成满文,一路用到二十世纪。片治肯特的壁画保存了他们的商队、宴饮与史诗场面;塔吉克山谷里的雅格诺比语,是粟特语活到今天的直系后代。祆教、摩尼教、景教东传入华,很大程度上也搭的是他们的车。','The network outlived them. The Sogdian script was borrowed by the Uyghurs, passed from Uyghur to Mongolian and from Mongolian to Manchu, and stayed in use into the twentieth century. The murals of Panjikent preserve their caravans, banquets and epic scenes, and Yaghnobi, still spoken in a Tajik valley, is Sogdian\'s living descendant. Zoroastrianism, Manichaeism and Church of the East Christianity reached China largely by riding with them.'] },
  d:'游牧帝国来了又走,商路却一直由这群说伊朗语的城邦商人在经营。他们在长安、洛阳、蒙古草原、拜占庭都设有聚落,汉文史料里的"胡商"多半是他们;粟特文字被回鹘借去,再传给蒙古、又传给满洲,一路用到二十世纪。安禄山就是粟特人后裔。突厥化与伊斯兰化之后,这个民族不再作为独立群体存在,但它铺的那张网留了下来。' },
{ l:'st', s:'steppe', v:2, n:'柔然', k:[[330,0],[410,.4],[500,.35],[555,0]], b:'"可汗"称号自它定型,突厥原是它的锻奴属部。',
  e:{ n:'Rouran', w:'Rouran Khaganate', b:'They invented the title "khagan"; the Turks were their smiths.', d:'For a century and a half they faced down Northern Wei, who called them by a deliberately insulting name. Their leader Shelun was the first to style himself khagan — a title every steppe sovereign would use for the next thousand years, from Turks and Uyghurs to Mongols and Manchus. The Turkic tribes of the Altai forged iron for them as vassals; in 552 those smiths turned and destroyed them in a single war.', f:{ 'Peak':'5th c.', 'Center':'Mongolian steppe', 'Figures':'Shelun Khagan', 'Legacy':'The title "khagan"' } },
  f:{ '鼎盛':'5世纪', '中心':'漠北', '人物':'社崙可汗', '成就':'"可汗"称号的定型' },
  qh:{ born:['「可汗」这个称号,是从这里开始的','The title khagan starts here'],
       rule:['打铁这件事,外包给了突厥人','The ironworking was outsourced to the Turks'],
       money:['牧业靠天,能调度的钱在绿洲和劫掠','Herds depend on weather; the usable money came from oases and raids'],
       power:['兵器是别人给的,矿也是别人的','Someone else made the weapons, and owned the ore'],
       fall:['打铁的属部反过来,一战就把它打垮','The smiths turned, and one battle finished it'],
       legacy:['把关键技术外包出去,命门就在别人手里','Outsource the key craft, and hand over your throat'] },
  q:{ born:['4世纪鲜卑各部大举南下入主中原、建立北魏,漠北反而空了出来。留在草原的部落由社崙整合起来,402年他自称丘豆伐可汗——一般认为,“可汗”作为草原君主的正式称号是从这里开始的。柔然的出现,正是中原化的鲜卑与留守草原者分道扬镳的结果。','In the 4th century the Xianbei tribes moved south in force and founded the Northern Wei, which left the Mongolian steppe empty. The tribes who stayed were welded together by Shelun, who in 402 styled himself qaghan; this is generally taken to be the point at which qaghan became the formal title of a steppe ruler. The Rouran were what happened when the sinicised Xianbei and those who stayed on the grass parted ways.'],
      rule:['可汗之下按千人编军、置将统领,是草原上较早的成建制军事编组。属部各有分工:阿尔泰山南麓的突厥人世代为柔然锻铁,被称作“锻奴”。这种“核心部落打仗、属部专供某一样东西”的安排效率很高,但也等于把武器生产交到了别人手里。','Under the qaghan troops were organised in units of a thousand, each with an appointed commander, one of the earlier formal military structures on the steppe. Subject tribes were assigned specialities: the Turks on the southern slopes of the Altai forged iron for the Rouran for generations and were known as their smith slaves. Making the core tribe fight while a subject tribe supplied one particular good was efficient, but it also handed weapons production to somebody else.'],
      money:['牧业之外有三条进项:南下劫掠北魏边地、与北魏的和市贸易,以及西域的过路与贡赋——它一度控制高昌,扶植阚氏为王,把塔里木的绿洲收入纳入囊中。牧业收入靠天,劫掠与绿洲税才是可以调度的钱。','Beyond herding there were three incomes: raiding the Northern Wei frontier, trading at the licensed border markets with the Wei, and tolls and tribute from the Western Regions. For a time they controlled Gaochang, installing the Kan family as puppet kings and taking the Tarim oasis revenue. Herds depend on the weather; raids and oasis taxes were money you could actually direct.'],
      power:['骑兵之外的关键是铁。突厥属部提供的兵器与阿尔泰的铁矿,让它能与北魏对峙一个半世纪;北魏为此修六镇、屡次出塞远征,并蔑称其为“蠕蠕”。','Besides cavalry the key was iron. Weapons from the subject Turks and Altai ore let the Rouran hold off the Northern Wei for a century and a half; the Wei answered by building the six frontier garrisons and mounting repeated expeditions into the steppe, while calling them Ruru, a deliberately insulting name.'],
      fall:['多因叠加:北魏太武帝429年长驱漠北,重创其主力;高昌等西域收入先后失去;可汗继承屡起内讧,6世纪初阿那瓌一度出逃投奔北魏。最后一击来自内部——土门因求婚被拒(约546年)与柔然决裂,552年举兵反戈,柔然一战崩溃,残部三年内被彻底扫平。','The causes stacked. In 429 Emperor Taiwu of Northern Wei drove deep into the steppe and shattered their main force; the Gaochang and other Western Regions revenues were lost one after another; succession quarrels kept breaking out, and in the early 6th century the qaghan Anagui had to flee to the Wei for refuge. The final blow came from inside: in 552, refused a marriage alliance, the Turk leader Bumin revolted, the Rouran collapsed in a single campaign, and the remnants were finished off within three years.'],
      legacy:['最耐久的遗产是一个词:可汗。此后一千多年,突厥、回鹘、契丹、蒙古、满洲的君主都用它,连“可敦”(皇后)也一并沿用。它还留下一个反面教训:把关键技术外包给属部,属部就掌握了你的命门。柔然残部是否西迁成为欧洲的阿瓦尔人,学界尚无定论。','The most durable legacy is a word: qaghan. For more than a thousand years afterwards Turk, Uyghur, Khitan, Mongol and Manchu rulers used it, along with khatun for their queens. They also left a cautionary lesson: outsource your critical technology to a subject tribe and that tribe holds your throat. Whether Rouran remnants moved west and became the Avars of Europe remains unsettled.'] },
  d:'与北魏对峙一百五十年,北魏蔑称其为"蠕蠕"。一般认为,可汗作为草原君主的正式称号自首领社崙始,此后一千多年,从突厥、回鹘到蒙古、满洲,草原君主一律用它。它世代役使阿尔泰山南麓的突厥人为其锻铁,552年这群"锻奴"反戈,一战把它灭了。' },
{ l:'st', s:'steppe', v:1, n:'匈人', k:[[350,0],[440,.5],[470,0]], b:'阿提拉兵临罗马,搅动整个欧洲的民族大迁徙。',
  e:{ n:'Huns', b:'Attila at the gates; the migration cascade that broke Rome.', d:'The "Scourge of God" extorted both Romes and swept the Balkans and Gaul; checked at the Catalaunian Plains, dead within two years, his empire dissolved — but the Germanic migrations he set moving could not be stopped.', f:{ 'Peak':'Attila (434–453)', 'Center':'Pannonia', 'Figures':'Attila' } },
  f:{ '鼎盛':'阿提拉(434—453)', '中心':'潘诺尼亚', '人物':'阿提拉' },
  qh:{ born:['欧洲民族大迁徙的第一块骨牌','The first domino of the great migrations'],
       rule:['宫廷里雇着罗马人替他们写文书','Romans were hired to write its letters'],
       money:['必须一直可怕,不然钱就断了','It had to stay terrifying, or the money stopped'],
       power:['光靠骑兵放箭,是攻不下城墙的','Arrows alone never took a city wall'],
       fall:['全部黏合力都系在一个人身上','All the glue rested on one man'],
       legacy:['自己不到一百年就没了,余波停不下来','It lasted under a century; the aftershocks did not stop'] },
  q:{ born:['370年代,一支骑马民族从伏尔加河以东进入黑海草原,击垮阿兰人与东哥特人,376年逼得西哥特人渡多瑙河进入罗马境内——欧洲民族大迁徙的第一块骨牌就此推倒。他们从哪里来仍无定论:有学者据粟特文书对匈奴的称呼推断匈人即匈奴西支,也有学者认为两者只是名号相近,并无直接传承。','In the 370s a mounted people came out of the lands east of the Volga into the Black Sea steppe, smashed the Alans and the Ostrogoths, and in 376 pushed the Visigoths across the Danube into Roman territory: the first domino of Europe\'s great migrations. Where they came from is still unsettled. Some scholars argue from the way Sogdian documents name the Xiongnu that the Huns were a western branch of them, while others hold that similar names prove nothing about descent.'],
      rule:['与其说是国家,不如说是征服者与被征服者拼起来的联盟:哥特人、阿兰人、格皮德人各留其王,向匈人首领效忠。上层曾由布莱达与阿提拉兄弟共治,后阿提拉独掌。据449年亲赴其营地的东罗马使臣普里斯库斯记载,阿提拉的宫廷里雇着罗马人做文书,处理与两个罗马的往来。','It was less a state than a coalition of conquerors and conquered: Goths, Alans and Gepids kept their own kings and swore to the Hun ruler. At the top Bleda and Attila ruled jointly before Attila took sole power. Priscus, an East Roman envoy who visited the camp in 449, records that Attila kept Roman secretaries at his court to handle correspondence with the two empires.'],
      money:['主要收入不是贸易,而是勒索。几次城下之盟后,君士坦丁堡缴纳的年贡涨到原来的数倍,还要按人头赎回俘虏;其余来自劫掠所得与属部的贡赋。这套收入模式有个致命特点:必须持续可怕,一旦打不动了,钱就断了。','Their main income was not trade but extortion. After a run of forced treaties the annual gold Constantinople paid rose to several times its original level, on top of ransoms charged per captive; the rest came from plunder and tribute from subject peoples. This model had a fatal feature: it required staying terrifying, and the moment they could no longer strike, the money stopped.'],
      power:['骑射机动是底子,但真正让他们能拿下巴尔干设防城市的,是麾下日耳曼与阿兰属部提供的步兵与攻城手段——441至447年,他们连破多瑙河沿线诸城。单靠骑兵放箭,是攻不下城墙的。','Mounted archery and mobility were the base, but what let them take fortified cities in the Balkans was the infantry and siege capability supplied by their Germanic and Alan subjects: between 441 and 447 they broke one Danube city after another. Horse archers alone do not bring down walls.'],
      fall:['453年阿提拉暴卒(据记载死于新婚之夜),权力结构随即散架:儿子们把帝国当牲口一样分割争夺,属部趁机反叛,据记载,454年格皮德人牵头的联军在内道河大败匈人。这个政权从来没有官僚、税册与继承法,全部黏合力都系在一个人的威名上,人一走,黏合力归零。','Attila died suddenly in 453, the sources say on the night of his wedding, and the structure came apart at once: his sons quarrelled over the empire as if dividing a herd, the subject peoples revolted, and in 454 a Gepid-led coalition crushed the Huns at the river Nedao. The state had never had a bureaucracy, tax rolls or a law of succession; all its cohesion rested on one man\'s name, and when he was gone there was none left.'],
      legacy:['他们本身不到一百年就消失了,推动的连锁反应却停不下来:被挤压的日耳曼各族涌入罗马境内,加速了西罗马的解体——但主流看法是西罗马之亡另有财政、军事、政治多重原因,匈人只是其中一环。“匈人”这个名字后来在欧洲成了野蛮的代名词,阿提拉则以埃策尔王的形象活在《尼伯龙根之歌》里。','The Huns themselves lasted less than a century, but the chain reaction they set off could not be stopped: displaced Germanic peoples poured into Roman territory and hastened the Western Empire\'s breakup, though the mainstream view is that Rome fell for many fiscal, military and political reasons of which the Huns were only one. Their name became a European byword for barbarism, and Attila lives on as King Etzel in the Nibelungenlied.'] },
  d:'"上帝之鞭"阿提拉勒索东西两罗马、横扫巴尔干与高卢;沙隆一战受挫,暴亡后帝国立散。但他推动的多米诺——日耳曼各族涌入罗马境内——再也停不下来了。' },
{ l:'st', s:'steppe', v:0, n:'嚈哒·白匈奴', k:[[440,0],[500,.4],[560,0]], b:'同时压住萨珊波斯与笈多印度的中亚强权。',
  e:{ n:'Hephthalites', w:'Hephthalites', b:'Pressed Sasanian Persia and Gupta India at the same time.', d:'Where they came from is still argued — whether they were a Xiongnu branch has been debated for a century. What is certain is that for one century they held down Sasanian Persia to the west and Gupta India to the south at once: the Persian king Peroz died fighting them, and the Gupta golden age never recovered from their invasions. Around 560 the Turks and Sasanians closed on them from both sides, and they vanished as abruptly as they had appeared.', f:{ 'Peak':'early 6th c.', 'Center':'Bactria (northern Afghanistan)', 'Figures':'Toramana', 'Legacy':'Killed a Persian king, broke a Indian golden age' } },
  f:{ '鼎盛':'6世纪初', '中心':'巴克特里亚(今阿富汗北部)', '人物':'头罗曼', '成就':'击杀萨珊国王、重创笈多' },
  qh:{ born:['来历争了一百多年,至今没定论','Their origin has been argued over for a century'],
       rule:['不砸城,直接接管现成的行政班子','They did not wreck the cities; they took over the offices'],
       money:['最肥的一笔,是波斯赔的钱','The fattest income was Persian reparations'],
       power:['西边压波斯,南边打印度,两头同时','Pressing Persia to the west and India to the south'],
       fall:['被萨珊和突厥南北夹着,分掉了','Caught between Persia and the Turks, and split'],
       legacy:['史料太薄,本身就是它最真实的样子','The thinness of the record is itself the truest picture'] },
  q:{ born:['5世纪中叶,一支来自北方草原的骑马集团南下,从此前控制巴克特里亚(今阿富汗北部)的寄多罗人手里夺下了这片地。他们的来历学界争了一百多年:与匈奴以及其他“匈”系人群的关系至今没有定论,连他们说什么语言,也只能从零星钱币铭文推测。','In the early 5th century, with the Kushans gone, Bactria, northern Afghanistan today, was a power vacuum, and a mounted group out of the northern steppe filled it. Their origins have been argued over for more than a century: their relationship to the Xiongnu and to the other Hun groups is still unresolved, and even the language they spoke can only be guessed from scattered coin legends.'],
      rule:['老实说,我们对他们的内部制度知道得很少。可以确认的是他们并不摧毁绿洲城市,而是接管现成的行政:沿用巴克特里亚语文书与萨珊式银币(常在缴获的波斯钱上加打自己的印记),让本地贵族继续收税。中国僧人宋云等人的记述提到他们仍逐水草而居、以毡帐为宫,与被统治的城市生活并存。','Honestly, we know very little about how they governed. What is clear is that they did not wreck the oasis cities but took over the administration already there: they kept the Bactrian-language paperwork and Sasanian-style silver coinage, often overstriking captured Persian coins with their own mark, and left local nobles to collect the taxes. Chinese pilgrims such as Song Yun describe rulers who still moved with the seasons and held court in felt tents while the cities under them carried on.'],
      money:['巴克特里亚的灌溉农业是底盘,过境丝路的关税是流水,最肥的一笔是战争赔款:484年萨珊国王卑路斯战死之后,波斯连年向他们缴纳贡金。一个骑马集团能长期养兵,靠的正是把定居区的税基与邻国的赔款一并接到手里。','Irrigated Bactrian farming was the base, Silk Road transit dues were the cash flow, and the richest single stream was war indemnity: after the Sasanian king Peroz was killed in battle in 484, Persia paid them tribute for years. What let a mounted group keep a standing force in the field was precisely plugging into a settled tax base and a defeated neighbour\'s payments.'],
      power:['骑兵加上巴克特里亚的钱粮,使他们能同时向西、向南用兵:西面压制萨珊,南面越过兴都库什冲击笈多印度,头罗曼、米希拉古罗父子在印度西北建立统治。不过南下印度的那几支“白匈奴”与巴克特里亚的嚈哒是否同一集团,钱币学界仍有争论。','Cavalry plus Bactrian revenue let them fight west and south at once: they held down the Sasanians on one side and crossed the Hindu Kush to strike Gupta India on the other, where Toramana and his son Mihirakula ruled the northwest. Whether the White Huns who went into India were the same group as the Hephthalites of Bactria is, however, still debated among numismatists.'],
      fall:['南北两线同时失手。在印度,528年前后被以耶输陀曼为首的诸王联军击败,势力退回西北;在中亚,557至561年前后萨珊的库思老一世与西突厥的室点密南北夹击,以阿姆河为界瓜分其地。此后嚈哒残余作为吐火罗斯坦的小邦又存在了一两百年,再无力量可言。','They lost both fronts at once. In India a coalition of kings under Yashodharman defeated them around 528 and pushed them back to the northwest; in Central Asia, between roughly 557 and 561, Khusrau I of Persia and Istami of the Western Turks attacked from south and north and divided their lands along the Oxus. Hephthalite remnants survived another century or two as petty principalities in Tokharistan, but never again as a power.'],
      legacy:['他们最大的影响是替别人清了场:萨珊被拖入长期消耗,笈多的盛世被打断(笈多之亡另有王朝内争与地方割据等多重原因,不能全记在他们头上),中亚则从此进入突厥时代。留下的实物主要是钱币和几批巴克特里亚语文书——史料之薄,本身就是这个条目最真实的样子。','Their largest effect was clearing the field for others: the Sasanians were drawn into a long war of attrition, the Gupta golden age was cut short (though the Gupta collapse also had dynastic strife and regional breakaways behind it and cannot be laid on them alone), and Central Asia passed into its Turkic era. What they left is mainly coins and a few caches of Bactrian documents; the thinness of the record is itself the honest picture of them.'] },
  d:'来历至今没有定论——是不是匈奴的一支,学界争了一百年。可以确定的是它在一个世纪里同时压制了西边的萨珊波斯与南边的笈多印度:萨珊国王卑路斯战死在它手里,笈多王朝被它打断了脊梁。560年前后,突厥与萨珊南北夹击,它消失得和出现时一样突然。' },
{ l:'st', s:'steppe', v:0, n:'突厥汗国', k:[[552,0],[580,.6],[630,.4],[744,0]], b:'控扼草原丝路东西六千里;后裔西迁重塑西亚。',
  e:{ n:'Türk Khaganate', w:'First Turkic Khaganate', b:'Six thousand li of steppe road; their descendants remade West Asia.', d:'The Ashina rose in the Altai to rule from Manchuria to the Caspian; split east-west, both halves fell to Tang. The Orkhon inscriptions — regret at trusting Tang honey — are the steppe\'s first written self-account; the westward drift of Turkic peoples later remade West Asia.', f:{ 'Peak':'late 6th c.', 'Center':'Orkhon valley', 'Figures':'Bumin Khagan, Bilge Khagan', 'Legacy':'Orkhon script, steppe Silk Road' } },
  f:{ '鼎盛':'6世纪末', '中心':'鄂尔浑河谷', '人物':'布民可汗、毗伽可汗', '成就':'突厥文碑铭(最早的草原文字之一)、草原丝路' },
  qh:{ born:['铁匠推翻了主人','The smiths overthrew their masters'],
       rule:['继承没有硬规则,每代都可能内战','No fixed succession, and a civil war risk each generation'],
       money:['分裂的中国,就是它的财政来源','A divided China was its treasury'],
       power:['不吞城只收贡,所以扩张得快','It took tribute, not cities, and so it spread fast'],
       fall:['两次亡国,两次都亡在内讧上','It fell twice, and twice from within'],
       legacy:['草原民族第一次用自己的字写自己的史','The steppe first told its own history in its own script'] },
  q:{ born:['阿史那部世代在阿尔泰山为柔然锻铁,掌握着草原上最稀缺的技术。552年首领土门因求婚被拒起兵,一举灭柔然;此后不到二十年,东至辽海、西抵里海的草原走廊被打通。铁匠推翻主人,是这个汗国最贴切的出身说明。','The Ashina clan had forged iron in the Altai for the Rouran for generations, holding the scarcest skill on the steppe. In 552 their leader Bumin, refused a marriage alliance, revolted and destroyed the Rouran; within twenty years the whole grassland corridor from the Liao river to the Caspian was theirs. A smith overthrowing his master is the most accurate account of where this khaganate came from.'],
      rule:['大可汗坐镇鄂尔浑河谷的于都斤山,那里被认为是草原的中心;西面由小可汗(叶护)分治,形成东西两大块。继承在阿史那家族内部按兄终弟及与父子相承交替,没有硬规则——这既让最能打的人有机会上位,也保证了每一代都有一次内战风险。','The great qaghan sat in the Otuken highlands of the Orkhon valley, held to be the centre of the steppe, while a junior qaghan, the yabghu, governed the west, giving the realm two halves. Succession alternated between brothers and sons within the Ashina house with no fixed rule, which let the ablest man rise and guaranteed a risk of civil war in every generation.'],
      money:['牧业之外,他们做了一件前人没做透的事:把丝路商业外包给粟特人,自己收保护费与关税,并由粟特使者代为出使拜占庭,试图绕开波斯直销丝绸。更大的一笔在南边——北周与北齐争相拉拢,岁输缯帛,据史书记载,一位可汗曾说只要南边两个“孝顺儿子”在,就不愁没有东西用。分裂的中国,就是突厥的财政来源。','Beyond herding they did something no predecessor had done so thoroughly: they outsourced Silk Road commerce to the Sogdians and took protection money and tolls, even sending Sogdian envoys to Byzantium to sell silk around Persia. The bigger stream came from the south, where the rival Northern Zhou and Northern Qi courts bid for Turk favour with annual silk; the histories record a qaghan remarking that as long as his two filial sons in the south held out he would never want for anything. A divided China was the Turk treasury.'],
      power:['铁器、骑兵、粟特人的商业与外交,三样凑齐。加上他们不吞并绿洲城邦而只收贡,统治成本低、扩张速度快——这是草原政权少见的轻装打法。','Iron, cavalry, and Sogdian commerce and diplomacy, all three together. And because they took tribute from the oasis states rather than annexing them, the cost of rule stayed low and expansion stayed fast, an unusually light-footed approach for a steppe power.'],
      fall:['两度覆亡,原因相似。第一汗国因阿史那内部争位,581年后分裂为东西两部,隋唐又用和亲、封号、粮食离间铁勒诸部,东突厥630年被唐所灭,西突厥657年亡。第二汗国(682—744)重蹈内讧,744年被回鹘、葛逻禄、拔悉密联手推翻。鄂尔浑碑铭把败因归结为部众贪图中原的甘言与丝绸而离散——那是他们对自己的诊断,不是全部原因。','They fell twice, for much the same reasons. Ashina succession fights split the first khaganate into eastern and western halves after 581, while Sui and Tang courts used marriages, titles and grain to peel off the Tiele tribes; the Eastern Turks were destroyed by Tang in 630 and the Western in 657. The second khaganate, from 682 to 744, repeated the internal feuding and was overthrown by a coalition of Uyghurs, Karluks and Basmyls. The Orkhon inscriptions blame the collapse on people scattering after Chinese sweet words and soft silk, but that is their own diagnosis, not the whole story.'],
      legacy:['鄂尔浑河谷的阙特勤碑与毗伽可汗碑立于8世纪30年代,是现存最早的一批成规模突厥语文献(与稍早的暾欲谷碑同属一组),也是草原民族用自己的文字讲述自身历史的最早实例之一。“突厥/Türk”这个名字随部众西迁传遍中亚与西亚,后来的塞尔柱、奥斯曼都自认这一脉;阿史那开创的可汗传统,则被回鹘直到蒙古一路继承。','The Kul Tegin and Bilge Qaghan stelae in the Orkhon valley, raised in the 730s, are among the earliest substantial texts surviving in a Turkic language and among the earliest cases of a steppe people telling its own history in its own script. The name Turk travelled west with migrating tribes across Central and Western Asia, and the later Seljuks and Ottomans claimed the lineage; the qaghanate tradition the Ashina began was inherited by everyone from the Uyghurs to the Mongols.'] },
  d:'阿史那氏崛起于金山(阿尔泰),疆域东抵辽海西至里海;分裂为东西两部后先后被唐所灭。鄂尔浑碑铭里关于轻信南朝甘言、终致亡国的自省,是草原民族最早的文字自述之一;其部众西迁的余波,数百年后彻底重塑了西亚。' },
{ l:'st', s:'steppe', v:1, n:'回鹘', k:[[744,0],[790,.35],[840,0]], b:'助唐平安史之乱;西迁后由游牧转农耕。',
  e:{ n:'Uyghur Khaganate', b:'Saved the Tang; turned farmer after the fall.', d:'They helped Tang crush the An Lushan rebellion for lucrative silk-horse trade and built rare steppe cities; smashed by the Kyrgyz in 840, they migrated to Gansu and the Tarim, turned agricultural — direct ancestors of today\'s Uyghurs.', f:{ 'Peak':'late 8th c.', 'Center':'Karabalghasun', 'Figures':'Kutluk Bilge Kul', 'Legacy':'First steppe capital city, Manichaeism' } },
  f:{ '鼎盛':'8世纪后期', '中心':'哈拉巴拉嘎斯', '人物':'骨力裴罗', '成就':'草原最早的定居都城、摩尼教国教' },
  qh:{ born:['能做生意的草原政权,比只会抢的走得远','A steppe power that could trade outlasted one that only raided'],
       rule:['草原上修了城墙,把王庭固定下来','It built walls on the steppe and fixed the court in place'],
       money:['把军事债权,变成了长期贸易特权','It turned a war debt into a lasting trade privilege'],
       power:['草原上少见的,不靠抢也能富','A rare steppe power that grew rich without raiding'],
       fall:['牲畜先死,内讧再起,外人被引了进来','The herds died, the court split, and outsiders were let in'],
       legacy:['一个草原政权,主动坐下来种地','A steppe power that chose to sit down and farm'] },
  q:{ born:['744年,回纥(后称回鹘)联合葛逻禄、拔悉密推翻第二突厥汗国,骨力裴罗自立为可汗。它的机会来自两件事:突厥内讧不止,而南边的唐正处在盛期——一个能与唐做生意的草原政权,比一个只会劫掠的更有前途。','In 744 the Uyghurs, allied with the Karluks and Basmyls, overthrew the second Turk khaganate and Kutlug Bilge Kol made himself qaghan. Their opening came from two things: the Turks would not stop fighting each other, and to the south the Tang was at its height. A steppe state that could do business with Tang had better prospects than one that could only raid.'],
      rule:['与历代草原政权不同,他们在鄂尔浑河边修了一座有城墙的都城(哈拉巴拉嘎斯),把王庭固定下来。762年前后牟羽可汗在洛阳接触摩尼教,回国后奉为国教——这既让可汗获得独立于部落萨满的权威,也把与粟特商人的关系变成了教友关系。行政文书用粟特文与后来的回鹘文,书吏多是粟特人。','Unlike earlier steppe powers they built a walled capital, Ordu-Baliq, on the Orkhon and fixed the court in one place. Around 762 the qaghan Bogu encountered Manichaeism in Luoyang and made it the state religion on his return, which gave him authority independent of the tribal shamans and turned his relationship with the Sogdian merchants into a bond between co-religionists. Administration ran on Sogdian and later Uyghur script, and most of the clerks were Sogdians.'],
      money:['核心是绢马贸易的垄断价。安史之乱中回鹘两次出兵助唐,唐从此欠着人情又急需战马,交换比例便由政治定:唐朝记载中一匹马可换绢四十匹,每年动辄数万匹马入境,唐廷叫苦而不敢拒。回鹘再把这些绢经粟特商路卖向西方。把军事债权变成长期贸易特权,是它最独到的一手。','The core was a monopoly price on the horse-for-silk trade. Having twice sent troops to help Tang during the An Lushan rebellion, the Uyghurs held a debt of gratitude while Tang badly needed warhorses, so the exchange rate was set politically: Tang records give forty bolts of silk for one horse, with tens of thousands of horses arriving in some years, which the court complained about but dared not refuse. The Uyghurs then resold the silk westward along Sogdian routes. Turning a military IOU into a permanent trading privilege was their most distinctive move.'],
      power:['骑兵仍是本钱,但真正的支柱是三重结合:唐朝的战略需求、粟特人的商业与文书能力、摩尼教提供的意识形态。它是草原上少见的、不靠抢也能富的政权。','Cavalry remained the capital, but the real support was a triple combination: Tang\'s strategic need for them, Sogdian commercial and clerical skill, and the ideological frame Manichaeism supplied. It was that rare steppe state that could get rich without raiding.'],
      fall:['多因叠加:9世纪30年代末连年严冬与牲畜疫病,牧业根基受损;可汗之位数度被权臣废立,内讧不断;一名失势将领引黠戛斯入境,840年都城被攻破。此外唐自身衰弱,绢马贸易这条命脉本已难以为继,843年唐廷禁摩尼教又切断了它在中原的网络。','Several causes at once: at the end of the 830s severe winters and livestock disease wrecked the pastoral base; the throne was repeatedly made and unmade by powerful ministers amid constant infighting; and a general who had lost out brought the Kirghiz in, so that in 840 the capital was stormed. Beyond that, Tang itself was weakening and the silk-for-horses lifeline was already faltering, and the Tang ban on Manichaeism in 843 cut their network inside China.'],
      legacy:['溃败后西迁河西与塔里木,在高昌、龟兹一带由游牧改营绿洲农耕,信仰也从摩尼教、景教逐步转向佛教,后来又伊斯兰化;这批人与当地原有居民融合,是今日维吾尔族的主要先民。回鹘文由粟特文改造而来,后被蒙古借用,再传满洲。一个草原政权主动坐下来务农,并把文字传给后来者,在草原史上并不多见。','After the defeat they moved west into the Hexi corridor and the Tarim basin, turning from herding to oasis farming around Gaochang and Kucha, and shifting from Manichaeism and Christianity to Buddhism and later to Islam; merging with the existing population, they became the main ancestors of today\'s Uyghurs. Their script, adapted from Sogdian, was later borrowed by the Mongols and passed on to the Manchus. A steppe power that chose to settle down and farm, and handed its writing to those who came after, is not a common thing in steppe history.'] },
  d:'助唐平定安史之乱,换来绢马贸易的丰厚利润,并在草原上建起罕见的定居都城;被黠戛斯击溃后西迁河西与塔里木,由游牧转农耕,是今日维吾尔族的直系先民。' },
{ l:'st', s:'mideast', v:0, n:'萨曼王朝', k:[[819,0],[900,.45],[960,.5],[999,0]], b:'布哈拉的波斯语复兴;伊本·西那与比鲁尼的摇篮。',
  e:{ n:'Samanid Empire', w:'Samanid Empire', b:'Persian reborn at Bukhara; the cradle of Ibn Sina and al-Biruni.', d:'Two centuries after the Arab conquest, the Persian language — now in Arabic script — came back to life in the Bukhara court, and Ferdowsi\'s Shahnameh caught the whole of Persian memory as it fell. On the same soil Ibn Sina wrote the Canon of Medicine, a European medical-school textbook for the next six hundred years, and al-Biruni calculated the radius of the Earth and wrote an account of India still cited today. For this century and a half the intellectual centre of Islam was not Baghdad but Central Asia.', f:{ 'Peak':'10th c.', 'Center':'Bukhara', 'Figures':'Ibn Sina, al-Biruni, Ferdowsi', 'Legacy':'New Persian literature; the Canon of Medicine' } },
  f:{ '鼎盛':'10世纪', '中心':'布哈拉', '人物':'伊本·西那、比鲁尼、菲尔多西', '成就':'新波斯语文学复兴、《医典》' },
  qh:{ born:['名义上顺从,换来事实上的自治','Nominal obedience bought real autonomy'],
       rule:['伊斯兰世界较早的一套成熟官僚班子','One of the earliest mature bureaucracies in Islam'],
       money:['它的银币,埋在维京人的窖藏里','Its silver ended up in Viking hoards'],
       power:['一边买草原人当兵,一边向草原推进','It bought steppe men as soldiers, and pushed into the steppe'],
       fall:['买来的将领,后来自己开了张','The generals it bought went into business for themselves'],
       legacy:['波斯语换了字母,重新成为文学语言','Persian changed alphabet and became a literary language again'] },
  q:{ born:['萨曼家族是巴尔赫一带皈依伊斯兰教的波斯裔地主(迪赫坎),9世纪初被阿拔斯哈里发任命管理河中各城。哈里发的中央权力衰落后,他们既不造反也不宣布独立,而是继续在钱币与主麻日祷词里尊奉巴格达,实际自行其是——名义上的顺从,换来事实上的自治。','The Samanids were Persian landowning gentry, dihqans, from around Balkh who had become Muslims, and in the early 9th century the Abbasid caliph appointed them to govern the cities of Transoxiana. As the caliphate\'s central power faded they neither rebelled nor declared independence, but went on honouring Baghdad on their coins and in Friday prayers while doing as they pleased: nominal obedience bought real autonomy.'],
      rule:['以布哈拉为都,建立起分科的迪万(部)行政:财政、军务、驿传、司法各有其司,官员是识字的波斯文官,这是伊斯兰世界较早成熟的一套官僚班子。地方仍由迪赫坎地主掌握,军队则大量使用买来的突厥奴隶兵(古拉姆)。合法性来自两处:哈里发的册封,以及自称萨珊名将巴赫拉姆·楚宾之后。','Ruling from Bukhara, they built a departmental administration of divans, with separate offices for finance, army, post and justice, staffed by literate Persian officials: one of the earlier mature bureaucracies in the Islamic world. The countryside stayed in the hands of the dihqan landlords, while the army relied heavily on purchased Turkic slave soldiers, the ghulams. Legitimacy came from two places: the caliph\'s investiture, and a claimed descent from the Sasanian general Bahram Chubin.'],
      money:['三条腿:河中绿洲的灌溉农业、东西过境贸易,以及最赚钱的两项——兴都库什的潘杰希尔银矿,和从草原贩运突厥奴隶到伊斯兰世界各地。萨曼银币因此大量流向北方:今天瑞典与俄罗斯的维京时代窖藏里,成千上万枚银币铸于布哈拉,换回的是毛皮、蜂蜜与北方的奴隶。','Three legs: irrigated oasis farming in Transoxiana, east-west transit trade, and the two most profitable lines of all, the Panjhir silver mines in the Hindu Kush and the traffic in Turkic slaves from the steppe to the rest of the Islamic world. Samanid silver therefore flowed north in quantity: Viking-age hoards in Sweden and Russia hold thousands of coins struck in Bukhara, paid out for furs, honey and northern slaves.'],
      power:['白银给钱,古拉姆给兵,边境的“加齐”(为信仰而战者)传统提供源源不断的人手与士气。它对草原是攻守兼备:一边买草原上的人当兵,一边以圣战之名向草原推进。','Silver paid, ghulams fought, and the frontier tradition of the ghazi, the warrior for the faith, supplied a steady stream of manpower and morale. Towards the steppe they were both buyer and aggressor: purchasing its people as soldiers while pushing into it in the name of holy war.'],
      fall:['多因叠加:一般认为潘杰希尔的银产在10世纪后期下滑,财政吃紧;买来的突厥将领日益尾大不掉,先是阿尔普特勤割据加兹尼,其部属继而另立门户,即后来的加兹尼王朝;迪赫坎地主也与中央离心。999年喀喇汗军队几乎兵不血刃进入布哈拉,河中归喀喇汗,阿姆河以南归加兹尼,萨曼被两家瓜分。','Causes stacked: silver output from Panjhir is generally thought to have fallen off late in the 10th century, straining the treasury; the purchased Turkic commanders grew too big to control, with Alp Tigin setting himself up in Ghazna and his successors founding what became the Ghaznavid dynasty; and the dihqan landlords drifted away from the centre. In 999 a Karakhanid army entered Bukhara almost without a fight, and the state was partitioned, Transoxiana to the Karakhanids and everything south of the Oxus to the Ghaznavids.'],
      legacy:['阿拉伯征服两个世纪之后,波斯语改用阿拉伯字母,在布哈拉的宫廷里重新成为文学语言:鲁达基是这一脉的开山,菲尔多西在萨曼末年动笔写《列王纪》,完稿时朝代已换,只好献给加兹尼的马哈茂德。布哈拉的图书馆养出了少年伊本·西那,他日后写的《医典》此后数百年是欧洲医学院的课本。这套“波斯文化 + 突厥武力 + 伊斯兰法统”的组合,被加兹尼、塞尔柱、奥斯曼、莫卧儿一路继承。','Two centuries after the Arab conquest, Persian, now written in Arabic script, became a literary language again in the courts of Bukhara: Rudaki founded the tradition, and Ferdowsi began the Shahnameh in the dynasty\'s last years, finishing it only after the dynasty had fallen and presenting it instead to Mahmud of Ghazna. The library at Bukhara educated the young Ibn Sina, whose Canon of Medicine was a European medical textbook for centuries afterwards. The combination they assembled, Persian culture with Turkic arms and Islamic legitimacy, was inherited in turn by the Ghaznavids, Seljuks, Ottomans and Mughals.'] },
  d:'阿拉伯征服两百年后,波斯语改用阿拉伯字母,在布哈拉的宫廷里重新活了过来——菲尔多西的《列王纪》把波斯的记忆整个接住。同一片土地上,伊本·西那写出《医典》,此后几百年一直是欧洲医学院的教科书;比鲁尼算出了地球半径,还写了一部至今仍被引用的印度志。这一百多年里,伊斯兰世界的学术中心不在巴格达,在中亚。' },
{ l:'st', s:'steppe', v:0, n:'喀喇汗王朝', k:[[840,0],[960,.3],[1050,.45],[1141,.25],[1212,0]], b:'突厥人集体皈依伊斯兰的转折点。',
  e:{ n:'Kara-Khanid Khanate', w:'Kara-Khanid Khanate', b:'The moment the Turks became Muslims.', d:'Among the first Turkic dynasties to adopt Islam — before this, Turks were shamanists, Manichaeans and Buddhists. It turned Central Asia from an Iranian-speaking world into a Turkic-speaking one: the language map running from Turkey to Xinjiang today starts here. The Kutadgu Bilig and the Diwan Lughat al-Turk are the two earliest substantial books in Turkic, the latter an encyclopedia complete with a world map.', f:{ 'Peak':'11th c.', 'Center':'Kashgar, Balasagun', 'Figures':'Satuq Bughra Khan, Mahmud al-Kashgari', 'Legacy':'Turkic Islam; the first Turkic books' } },
  f:{ '鼎盛':'11世纪', '中心':'喀什噶尔、八剌沙衮', '人物':'萨图克·博格拉汗、麻赫穆德·喀什噶里', '成就':'突厥人的伊斯兰化、《突厥语大词典》与《福乐智慧》' },
  qh:{ born:['王族一个人先入教,后面跟着一片','One prince converted, and a great many followed'],
       rule:['教法叠上去了,草原的分封没被改掉','Islamic law was laid on top; the steppe partition stayed'],
       money:['1127年立的那座塔,至今还站着','The minaret raised in 1127 is still standing'],
       power:['既是草原的,又是伊斯兰的','Both of the steppe and of Islam'],
       fall:['最后一百多年,一直是别人的属国','It spent its final century as a vassal of others'],
       legacy:['从此突厥语世界和伊斯兰世界基本重合','From here the Turkic and Islamic worlds largely coincided'] },
  q:{ born:['回鹘汗国840年崩溃后,葛逻禄等突厥部落在七河与喀什噶尔一带重新聚合,形成喀喇汗。转折发生在10世纪中叶:王族成员萨图克皈依伊斯兰教,取名阿卜杜·凯里姆。阿拉伯史家记载,10世纪中后期草原上有“二十万帐”突厥人集体入教——这个数字出自编年史,不宜当作精确统计。','After the Uyghur khaganate collapsed in 840, Karluk and other Turkic tribes regrouped around Semirechye and Kashgar and formed the Karakhanids. The turning point came in the mid-10th century, when a member of the ruling house, Satuq, converted to Islam and took the name Abd al-Karim. Arab chroniclers report that in the middle and later 10th century two hundred thousand tents of Turks accepted the faith on the steppe, a chronicler\'s figure rather than a census.'],
      rule:['沿用草原的共治与分封:大可汗(阿尔斯兰汗)与小可汗(博格拉汗)分治东西,王族子弟各据一城为封地。伊斯兰教叠在这套结构之上,可汗兼用苏丹称号,城中有教法官、经学院与瓦克夫(宗教地产)。草原的分封逻辑并没有被教法改掉,反而让王朝在11世纪40年代顺势裂成东西两个汗国。','They kept the steppe habits of co-rulership and appanage: a senior Arslan Khan and a junior Bughra Khan divided east and west, and princes of the house held cities as their portions. Islam was layered on top; the khans also used the title sultan, and the cities had qadis, madrasas and waqf endowments. Sharia never replaced the appanage logic, which is why the dynasty split into eastern and western khanates in the 1040s.'],
      money:['河中与费尔干纳的灌溉农业、喀什噶尔一线的东西贸易,加上草原的畜牧与马匹。它铸行自己的钱币,并把收入投进砖砌建筑:布哈拉的卡扬宣礼塔(1127年)就是喀喇汗时期的手笔,至今仍立在原地。','Irrigated farming in Transoxiana and Ferghana, east-west trade along the Kashgar road, and herds and horses from the steppe. They struck their own coinage and put the proceeds into brickwork: the Kalyan minaret in Bukhara, built in 1127, is a Karakhanid commission and still stands where it was raised.'],
      power:['草原提供源源不断的骑兵人力,伊斯兰身份则提供了在定居区的合法性——999年他们进入布哈拉时,当地教法学者并未号召抵抗。既是草原的,又是伊斯兰的,这个双重身份是它取代萨曼的关键。','The steppe supplied endless cavalry manpower and their Muslim identity supplied legitimacy in the settled lands: when they entered Bukhara in 999 the local jurists did not call for resistance. Being at once of the steppe and of Islam was what let them replace the Samanids.'],
      fall:['分封制先把它切成两半;1089年后西喀喇汗成为塞尔柱的附庸;1141年卡特万之战后又整体臣服于西辽;13世纪初再被花剌子模与乃蛮势力反复摆布,东西两支分别于1211年、1212年终结。也就是说,它的最后一百多年一直是别人的属国,亡国只是形式上的收尾。','The appanage system cut it in two first; after 1089 the western khanate became a Seljuk vassal; after the battle of Qatwan in 1141 the whole dynasty submitted to the Kara Khitai; and in the early 13th century it was pushed about by Khwarazm and the Naiman until the eastern and western lines ended in 1211 and 1212. Its last century and more was spent as somebody else\'s vassal, and the formal end was only bookkeeping.'],
      legacy:['中亚的语言与信仰在这里换了方向:此前突厥人多信萨满、摩尼教与佛教,此后突厥语世界与伊斯兰世界基本重合。更早皈依的突厥政权也有(如伏尔加保加利亚),但把伊斯兰带进中亚突厥腹地并让它扎下根的是喀喇汗。1069年前后的《福乐智慧》与1070年代的《突厥语大词典》是伊斯兰时代突厥语最早的两部大书,后者还附有一幅圆形世界地图。','This is where Central Asia\'s language and faith changed direction: before it, Turks were largely shamanists, Manichaeans and Buddhists; after it, the Turkic and Islamic worlds broadly overlapped. Other Turkic polities had converted earlier, Volga Bulgaria among them, but it was the Karakhanids who brought Islam into the Turkic heartland of Central Asia and made it take root. The Kutadgu Bilig of about 1069 and Mahmud al-Kashgari\'s Compendium of the Turkic Dialects from the 1070s are the two earliest major books in Turkic from the Islamic period, and the second even carries a round map of the world.'] },
  d:'把伊斯兰带进中亚突厥腹地并让它扎根的王朝(更早皈依的突厥政权也有,如伏尔加保加利亚)——在此之前突厥人信萨满、摩尼教和佛教。它把中亚从伊朗语世界变成突厥语世界:今天从土耳其一路到新疆的语言版图,起点在这里。《福乐智慧》与《突厥语大词典》是伊斯兰时代突厥语最早的两部大书,后者还是一部带地图的百科全书。' },
{ l:'st', s:'mideast', v:0, n:'花剌子模', k:[[1077,0],[1200,.5],[1220,.3],[1231,0]], b:'一个刚拼起来的帝国,撞上成吉思汗西征。',
  e:{ n:'Khwarazmian Empire', w:'Khwarazmian Empire', b:'Killed Genghis Khan\'s envoys and brought him west.', d:'It began as a single Seljuk governorship and within a century was the strongest state in Central Asia; its last ruler styled himself a second Alexander. In 1218 his frontier governor seized a Mongol caravan and executed it, then the envoys sent to complain were killed too. Genghis Khan came west with everything he had: within three years Urgench, Samarkand and Bukhara were rubble, and the irrigation works took centuries to recover. Central Asia\'s prosperity ended at a stroke, over an avoidable diplomatic incident.', f:{ 'Peak':'Muhammad II (1200–1220)', 'Center':'Urgench, later Samarkand', 'Figures':'Muhammad II, Jalal al-Din', 'Keywords':'A diplomatic incident that brought catastrophe' } },
  f:{ '鼎盛':'摩诃末(1200—1220)', '中心':'玉龙杰赤→撒马尔罕', '人物':'摩诃末二世、扎兰丁', '关键词':'一次外交事故引发的浩劫' },
  qh:{ born:['最后二十年才真正成型的帝国','An empire that only took shape in its final twenty years'],
       rule:['太后手里那批将领,几乎是另一个朝廷','The queen mother held enough generals to be a second court'],
       money:['关税收得越重,边境那座城越要紧','The heavier the toll, the more the border town mattered'],
       power:['它的强大,有一半是邻居太弱','Half its strength was its neighbours being weak'],
       fall:['一个刚拼起来的帝国,经不起一次失误','A newly assembled empire could not absorb one mistake'],
       legacy:['被毁的水渠,中亚几百年没修回来','The canals it lost took centuries to come back'] },
  q:{ born:['起点是一个职位:1077年前后,突厥奴隶出身的阿努什的斤被塞尔柱苏丹派去管花剌子模。塞尔柱衰落后,这个总督府一代代变成王朝,靠在塞尔柱、西辽、古尔王朝之间来回站队而扩张,到摩诃末二世手上,1210年代吞下整个河中。它是一个只用了一百多年、最后二十年才真正成型的帝国。','It began as a job: around 1077 a Seljuk sultan sent Anushtegin, a man of Turkic slave origin, to administer Khwarazm. As Seljuk power decayed the governorship turned, generation by generation, into a dynasty, expanding by switching sides among the Seljuks, the Kara Khitai and the Ghurids until, under Muhammad II, it swallowed all of Transoxiana in the 1210s. It was an empire barely a century old whose final shape was only twenty years old.'],
      rule:['上层是钦察突厥军事贵族,下层行政交给波斯文官,两套人马语言不同、利益也不同。更要命的是宫廷分裂:苏丹的母亲秃儿罕可敦出身钦察,握有军中大部分将领的效忠,几乎是另一个朝廷。新征服的城市由钦察将领分驻,当地贵族与教法学者并不认这个新主人。','The top layer was a Kipchak Turkic military aristocracy, the administration was left to Persian civil servants, and the two spoke different languages and wanted different things. Worse, the court itself was split: the sultan\'s mother, Terken Khatun, came from the Kipchaks and held the loyalty of most of the army\'s commanders, running what amounted to a second government. Newly conquered cities were garrisoned by Kipchak officers whom the local nobility and jurists never accepted as their masters.'],
      money:['阿姆河下游的大型灌溉绿洲是粮仓,河中诸城的手工业与市税是现金,再加上三个方向的过境贸易:北通钦察草原与伏尔加,东接中国,西南通伊朗。商队关税收得越重,边境关卡城市的地位就越关键——1218年出事的讹答剌,正是这样一座城。','The great irrigated oases of the lower Amu Darya were the granary, the crafts and market taxes of the Transoxianan cities were the cash, and on top came transit trade in three directions: north to the Kipchak steppe and the Volga, east to China, southwest to Iran. The heavier the caravan dues, the more important the frontier tollgate towns became, and Otrar, where everything went wrong in 1218, was exactly such a town.'],
      power:['钦察骑兵数量庞大,又赶上周边同时塌方:塞尔柱已亡,古尔王朝崩解,西辽被乃蛮人屈出律篡夺而自乱。它的强大有很大一部分来自邻居太弱,这一点在遇到一个组织度更高的对手时立刻现形。','Kipchak cavalry were numerous, and the neighbourhood happened to be collapsing all at once: the Seljuks were gone, the Ghurids had fallen apart, and the Kara Khitai had been usurped from within by the Naiman prince Kuchlug. A large part of its strength was simply weak neighbours, which showed the moment it met a better-organised enemy.'],
      fall:['使者被杀是导火索,不是原因。真正的原因至少有四条:帝国太新,新征服区的城市与教界并不为它效死,苏丹又与巴格达哈里发交恶而失去宗教支持;军权把持在母系钦察将领手中,摩诃末不敢把大军集中一处,只能分兵守城,被蒙古逐个拔除;蒙古在攻城技术与战役协同上明显占优;最后苏丹本人西逃至里海小岛病死,抵抗只剩扎兰丁一人苦撑。战争中被毁的灌溉系统,中亚数百年未能恢复。','Killing the envoys was the trigger, not the cause. There were at least four real causes: the empire was too new, so the cities and clergy of its recent conquests would not die for it, while the sultan\'s quarrel with the caliph in Baghdad cost him religious cover; military power lay with his mother\'s Kipchak commanders, so Muhammad dared not mass his army in one place and instead split it among city garrisons the Mongols removed one by one; the Mongols were plainly better at siegecraft and at coordinating campaigns; and in the end the sultan fled west to die on an island in the Caspian, leaving only his son Jalal al-Din still fighting. The irrigation works destroyed in that war took Central Asia centuries to recover from.'],
      legacy:['它成了一个被反复引用的反面案例:一个刚拼起来、内部互不信任的帝国,经不起一次外交失误。战争的后果远超中亚本身——蒙古西征的通道由此打开,此后二十年里罗斯诸公国与伊朗先后被卷入。中亚的政治与经济重心从此长期偏移,撒马尔罕要再等一百五十年,才由帖木儿重建起来。','It became a cautionary case quoted again and again: an empire freshly stitched together, whose parts did not trust each other, could not survive a single diplomatic blunder. The consequences went far beyond Central Asia, since the road for the Mongol westward campaigns opened here and within twenty years the Rus principalities and Iran had been drawn in as well. The centre of gravity of Central Asian politics and wealth shifted for a long time afterwards, and Samarkand had to wait a century and a half for Timur to rebuild it.'] },
  d:'从塞尔柱的一个总督府起家,百余年间做到中亚最强,末代君主摩诃末自比"第二亚历山大"。1218年他的边将扣留并处死了蒙古商队,继而杀掉来交涉的使节——成吉思汗倾国西征,三年之内玉龙杰赤、撒马尔罕、布哈拉尽成废墟,灌溉系统被毁后数百年未能恢复。中亚繁华的终结,导火索是一桩外交事故,但一个刚拼起来、内部互不信任的帝国本就撑不住这一击。' },
{ l:'st', s:'steppe', v:1, n:'西辽·哈剌契丹', k:[[1124,0],[1141,.35],[1180,.3],[1218,0]], b:'契丹西迁重建国;一战震动整个伊斯兰世界。',
  e:{ n:'Qara Khitai', w:'Qara Khitai', b:'Khitans rebuilt in the west; one battle shook all Islam.', d:'After the Liao fell to the Jin, Yelu Dashi led a remnant ten thousand li west and rebuilt the state in Central Asia. At Qatwan in 1141 he routed the Seljuk sultan Sanjar; the news reached Europe garbled into a report that an eastern Christian king — Prester John — was crushing the Muslims from behind, and the crusaders waited a full century for the relief army that was never coming. The state itself was Buddhist while ruling a largely Muslim population, and was notably tolerant.', f:{ 'Peak':'Yelu Dashi (1124–1143)', 'Center':'Balasagun', 'Figures':'Yelu Dashi', 'Legacy':'Qatwan; multi-faith rule' } },
  f:{ '鼎盛':'耶律大石(1124—1143)', '中心':'虎思斡耳朵', '人物':'耶律大石', '成就':'卡特万之战击败塞尔柱、多信仰共治' },
  qh:{ born:['以受邀的保护者身份,取代了主人','Invited in as protector, it replaced the host'],
       rule:['王位都留着,只派人在旁边盯着','The thrones stayed; it just sent men to watch'],
       money:['税刻意压得不重,让人过得下去','Taxes kept deliberately light, so life stayed liveable'],
       power:['佛教政权管穆斯林,不逼人改信','A Buddhist state over Muslim subjects, and no forced conversion'],
       fall:['靠宽容立国,亡在不再宽容之后','Founded on tolerance, and destroyed when it stopped'],
       legacy:['统治多信仰的人,最省力的办法是别管','The cheapest way to rule many faiths is to leave them alone'] },
  q:{ born:['一个被打垮的王朝在异地重开。1125年辽亡于金,前一年耶律大石已率残部北走可敦城,再从那里西行数千里;东喀喇汗的君主正被葛逻禄、康里部落逼得没有办法,请他入境助战——他进来之后就没有再走,以八剌沙衮(虎思斡耳朵)为都建国。以受邀的保护者身份取代主人,是它建国的确切方式。','A beaten dynasty reopened somewhere else. A year before the Liao fell to the Jin in 1125, the imperial kinsman Yelu Dashi led what was left of his men north to Khatun City, and from there thousands of kilometres west; the ruler of the eastern Karakhanids, hard pressed by Karluk and Kangli tribes, invited him in to help, and once in he stayed, founding a state with its capital at Balasagun. Coming in as an invited protector and replacing the host is precisely how it was founded.'],
      rule:['它把契丹与中原的一整套制度搬了过来:皇帝与“古儿汗”两个称号并用,有汉式年号、印玺与文书。对外则是间接统治——喀喇汗、高昌回鹘、花剌子模等原有王朝一律保留王位、按期纳贡,由西辽派“少监”驻在监督。据志费尼记载,赋税按户征收,大致每户一第纳尔,且不把土地封给军人,以防将领坐大变成地方势力。','It carried the whole Khitan and Chinese apparatus with it: the ruler used both emperor and gurkhan, with Chinese-style reign titles, seals and documents. Outward rule was indirect. The Karakhanids, the Gaochang Uyghurs, Khwarazm and others kept their thrones and paid regular tribute under the eye of a resident Khitan supervisor. Juvayni records that tax was levied per household, roughly a dinar each, and that land was deliberately not granted to soldiers so that commanders could not turn into landed powers.'],
      money:['属国贡赋是主项,户税是稳定项,七河与塔里木一线的过境商路是流水,加上自有牧地。它刻意把税收压得不重——一个人数很少的统治集团,靠的是被统治者觉得日子还过得下去。','Vassal tribute was the main item, the household tax the steady one, transit trade through Semirechye and the Tarim the flow, plus its own pastures. It deliberately kept taxes light: a very small ruling group survived by making sure the ruled felt life was still bearable.'],
      power:['一支纪律严整的契丹核心部队,加上属国的兵源;1141年卡特万之战大败塞尔柱苏丹桑贾尔后,它的威名本身就成了武器,很多地方不必打就归附。此外它对宗教一概宽容:一个佛教政权统治着以穆斯林为主的人口,不强制改宗,也不设宗教歧视税——这在当时的中亚极少见。','A disciplined Khitan core, backed by vassal levies; after routing the Seljuk sultan Sanjar at Qatwan in 1141 its reputation was itself a weapon, and many places submitted without a fight. It was also uniformly tolerant in religion: a Buddhist dynasty ruling a mostly Muslim population, with no forced conversion and no discriminatory religious tax, a rarity in the Central Asia of that day.'],
      fall:['多因叠加:耶律大石之后国政长期由太后与幼主执掌,权威递减;属国坐大,花剌子模停止纳贡并反戈相向;最后是自毁——1211年被它收容的乃蛮王子屈出律篡位,一反宽容旧制,在喀什噶尔、和田压迫穆斯林。1218年蒙古哲别军至,当地人视之为解脱,西辽几乎没有抵抗就结束了。一个靠宽容立国的政权,恰恰亡在它不再宽容之后。','Causes stacked: after Yelu Dashi the state was long run by dowagers and child rulers, and authority thinned; the vassals grew strong, and Khwarazm stopped paying tribute and turned against it. The last blow was self-inflicted, for in 1211 the Naiman prince Kuchlug, whom the state had sheltered, seized the throne, reversed the policy of tolerance and persecuted Muslims in Kashgar and Khotan. When the Mongol general Jebe arrived in 1218 the local population treated it as a deliverance, and Kara Khitai ended with almost no resistance. A state founded on tolerance fell precisely after it stopped being tolerant.'],
      legacy:['它证明了一件事:草原与中原式的制度可以在四千公里外照样运转,而统治多信仰人口最省力的办法,是不管人家信什么。蒙古后来在中亚沿用的间接统治与宗教宽容,与它一脉相承。还有一个不易察觉的遗产:因为它,中亚与俄语世界至今用“契丹”一词称呼中国(俄语 Китай,英语旧称 Cathay)。','It proved a point: a Khitan and Chinese style of government could run perfectly well four thousand kilometres from home, and the cheapest way to rule a mixed-faith population is not to mind what people believe. The indirect rule and religious tolerance the Mongols later practised in Central Asia followed the same line. And there is a quieter legacy: because of them, Central Asia and the Russian-speaking world still call China by the Khitan name, Kitai in Russian and the old English Cathay.'] },
  d:'辽亡于金之后,耶律大石率残部万里西行,在中亚重建政权。1141年卡特万之战大败塞尔柱苏丹桑贾尔,消息辗转传到欧洲,被附会成东方有位基督教君主"祭司王约翰"正在夹击穆斯林——十字军因此盼了整整一个世纪的东方援军。它本身是佛教政权,却统治着大批穆斯林臣民,宗教上相当宽容。' },
{ l:'st', s:'steppe', v:2, n:'蒙古帝国', k:[[1206,0],[1227,.8],[1260,1],[1294,.9],[1368,.3],[1400,0]], b:'史上最大陆地帝国,从太平洋到多瑙河;蒙古治世重通商路。',
  e:{ n:'Mongol Empire', b:'The largest land empire in history, Pacific to Danube.', d:'Genghis Khan reorganized the steppe; three generations conquered from the Pacific to the Danube. Destruction and connection in one: countless cities razed, yet the roads ran safe — Marco Polo and papal envoys came east on them. The four khanates localized and the tide receded, but Eurasia was never fully severed again.', f:{ 'Peak':'c. 1260', 'Center':'Karakorum', 'Figures':'Genghis, Kublai, Batu, Yelü Chucai, Sorghaghtani Beki', 'Legacy':'Largest land empire, the yam post system' } },
  f:{ '鼎盛':'1260年前后', '中心':'哈拉和林', '人物':'成吉思汗、忽必烈、拔都、耶律楚材、唆鲁禾帖尼', '成就':'史上最大陆地帝国、驿站系统' },
  qh:{ born:['忠诚从跟着部落,改成跟着大汗','Loyalty moved from the tribe to the khan'],
       rule:['近卫军既是精锐,也是人质营','The guard was both an elite corps and a hostage camp'],
       money:['路一通,过路费就成了长期财源','Once the roads were safe, tolls became lasting income'],
       power:['谁的本事好就用谁,不问出处','Whoever was good at something got used'],
       fall:['分裂是设计进去的','The split was designed in'],
       legacy:['火药西传,走的就是这条路','Gunpowder went west along this very road'] },
  q:{ born:['铁木真花了二十年打服草原各部,1206 年在斡难河源被推为成吉思汗。他把全体牧民编成九十五个千户,不按血缘按军令,把忠诚从「跟着本部落」改成「跟着大汗」——草原第一次拧成一股绳。1204 年他让畏兀儿人塔塔统阿用回鹘字母拼写蒙古语,蒙古人从此有了自己的文字。','Temujin spent twenty years bringing the steppe tribes to heel and in 1206, at the source of the Onon river, was acclaimed Genghis Khan. He organised every herding family into ninety-five units of a thousand, by command rather than by clan, shifting loyalty from tribe to khan — for the first time the steppe pulled as one rope. In 1204 he had the Uighur scribe Tatatonga write Mongolian in the Uighur alphabet, and the Mongols had a script of their own.'],
      rule:['千户制编组全民;一万人的怯薛近卫由各级首领的子弟充任,既是精锐也是人质营;《大札撒》立法。征服区用当地人管当地事,蒙古人只派达鲁花赤抓兵权与税权;办事的凭证是一块金属牌子——持金牌、银牌的人沿途驿站必须供马供粮,今天博物馆里还能看到刻着八思巴文的银牌。','The thousands organised the whole nation; the ten-thousand-strong kheshig guard, drawn from the sons of commanders at every level, was elite corps and hostage camp in one; the Yassa laid down the law. Conquered lands were run by local administrators, with a Mongol darughachi keeping the army and the tax; authority travelled as a metal tablet — whoever carried a gold or silver paiza had to be given horses and food at every post station, and silver ones inscribed in Phags-pa script survive in museums today.'],
      money:['从掠夺到贡赋,再到保护商路收税——「蒙古和平」让丝路空前畅通,过路费成了长期财源。窝阔台起用契丹人耶律楚材,在汉地按户按地定税,不再一抢了之;伊儿汗国后来也学着发纸币,几个月就作废了;元朝的中统钞则全国通行、白银为本。','From plunder to tribute to tolls: the Pax Mongolica made the Silk Road safer than ever, and the passage fees became a standing revenue. Ögedei took on the Khitan minister Yelü Chucai, who set fixed taxes on households and land in north China instead of one-off plunder; the Ilkhanate later tried paper money too and gave it up within months, while the Yuan Zhongtong note circulated across the whole realm backed by silver.'],
      power:['骑兵的机动、铁的纪律、先于对手的情报,加上对一切有用之物的吸收:1273 年攻襄阳,是两名西域工匠造的配重投石机(回回炮)砸开了守了五年的城;汉地工匠、畏兀儿文书、波斯的天文学家,谁的本事好就用谁。每个骑兵带三四匹换乘的马,一天能走别人几天的路。','Cavalry mobility, iron discipline and better intelligence, plus total willingness to absorb whatever worked: at Xiangyang in 1273 it was counterweight trebuchets built by two engineers from the Muslim west that broke a city which had held out for five years; Chinese artisans, Uighur scribes and Persian astronomers were all taken on — whoever had the skill was used. Each rider led three or four spare horses and covered in a day what others took days to ride.'],
      fall:['死穴是继承制度:每逢大汗去世,四方远征一律停下回师争位;帝国本身按家族分成四大汗国,分裂是设计进去的;黑死病又沿商路蔓延,把各汗国的贸易税基也摧毁了。','The fatal flaw was succession: each time a great khan died, the campaigns stopped and the princes rode home to contest the throne. The empire was parcelled among the family into four khanates — division was built in. Then the Black Death ran down the trade roads and destroyed the toll base of the khanates themselves.'],
      legacy:['欧亚大陆第一次被打通:马可·波罗的游记、西传的火药走的都是这条路;驿站系统被后世帝国沿用;今日的蒙古国是它的直系后裔。它留下来的最早的一部书是《蒙古秘史》——用汉字给蒙古语注音抄下来的成吉思汗家族史,是蒙古人自己讲的自己的来历。','Eurasia was opened end to end for the first time — Marco Polo and westbound gunpowder both travelled this road; the relay-post system outlived the empire; and modern Mongolia is its direct heir. The oldest Mongolian book that survives is the Secret History of the Mongols — the story of Genghis Khan\'s family, preserved in Mongolian spelled out with Chinese characters: the Mongols\' own account of where they came from.'] },
  d:'成吉思汗整编草原诸部,子孙三代打下从太平洋到多瑙河的疆域。毁灭与联通并行:屠城无数,却也让驿路畅通、商旅无阻,马可·波罗与教皇使节皆循此东来。四大汗国分立后各自本地化,帝国如潮水退去——但欧亚大陆从此再未彻底隔绝。' },
{ l:'st', s:'steppe', v:0, n:'帖木儿帝国', k:[[1370,0],[1405,.6],[1450,.4],[1507,0]], b:'从德里到安卡拉无役不胜;撒马尔罕的辉煌。',
  e:{ n:'Timurids', w:'Timurid Empire', b:'Victor from Delhi to Ankara; Samarkand\'s splendor.', d:'Timur, self-styled heir of Genghis, won from Delhi to Ankara and captured the Ottoman sultan, dying en route to invade Ming China. His grandson Ulugh Beg\'s star tables amazed later European astronomers; his fifth-generation descendant Babur founded the Mughals.', f:{ 'Peak':'c. 1400', 'Center':'Samarkand', 'Figures':'Timur, Ulugh Beg', 'Legacy':'Samarkand ensemble, observatory' } },
  f:{ '鼎盛':'1400年前后', '中心':'撒马尔罕', '人物':'帖木儿、兀鲁伯', '成就':'撒马尔罕建筑群、兀鲁伯天文台' },
  qh:{ born:['不是成吉思后裔,所以必须一直打赢','Not a Chinggisid, so he had to keep on winning'],
       rule:['生前是分工,死后就是现成的裂缝','A division of labour in life, a ready-made crack after'],
       money:['城破之后,连工匠也整批搬回撒马尔罕','After a city fell, its craftsmen were carted to Samarkand'],
       power:['制造恐惧,本身就是他的军事手段','Manufacturing fear was part of the military system'],
       fall:['帝国是一个人的作品,没有继承法','One man made the empire, and left no law of succession'],
       legacy:['孙子造了天文台,五世孙开了莫卧儿','A grandson built an observatory; a descendant founded the Mughals'] },
  q:{ born:['14世纪中叶察合台汗国分崩离析,河中成了各突厥化蒙古部族角逐的场子。巴鲁剌思部出身的帖木儿从一支小队伍打起,1370年控制河中。但他不是成吉思汗后裔,按草原法统不能称汗,只能自称异密,娶成吉思系公主而号“驸马”,并在名义上另立傀儡汗。一般认为,合法性上的这个缺口是他必须不断打胜仗的原因之一。','In the mid-14th century the Chagatai khanate broke up and Transoxiana became a free-for-all among Turkicised Mongol tribes. Timur of the Barlas fought his way up from a small band and controlled Transoxiana by 1370. But he was not a descendant of Chinggis Khan, so by steppe law he could not call himself khan: he took the title amir, married a Chinggisid princess to style himself guregen, royal son-in-law, and kept puppet khans on the throne. That gap in legitimacy is why he had to keep winning.'],
      rule:['统治的核心是他本人和那支随他移动的军队,行政则交给波斯文官打理定居区。诸子孙分封各地为省,这在他生前是分工,在他死后就是现成的裂缝。','The centre of government was the man himself and the army that moved with him, while Persian officials ran the settled provinces. Sons and grandsons were given regions to govern, which was a division of labour while he lived and a ready-made set of fault lines once he was dead.'],
      money:['战利品就是财政制度。1398年德里、1400至1401年阿勒颇与大马士革,城破之后不仅取财,还成批掳走工匠——石匠、织工、铸匠、造纸匠——统统迁往撒马尔罕。他还用军事手段改道贸易:1390年代摧毁金帐汗国的萨莱与顿河口商埠,把北线丝路的生意逼回撒马尔罕这条南线。','Plunder was the fiscal system. Delhi in 1398, Aleppo and Damascus in 1400 and 1401: when a city fell he took not only its wealth but its craftsmen in bulk, masons, weavers, metalworkers and papermakers, and deported them to Samarkand. He also rerouted trade by force, wrecking Sarai and the Don-mouth ports of the Golden Horde in the 1390s so that the northern Silk Road business had to come back to the southern line through Samarkand.'],
      power:['草原骑兵的机动加上定居帝国的攻城与后勤,两套长处集于一身;从德里到安卡拉几乎无役不胜,1402年连奥斯曼苏丹巴耶塞特都成了他的俘虏。他也刻意以屠城立威,使许多城市望风而降——制造恐惧是他军事体系的一部分。','He combined steppe cavalry mobility with the siegecraft and logistics of a settled empire, and from Delhi to Ankara he scarcely lost a battle; in 1402 even the Ottoman sultan Bayezid became his prisoner. He also made deliberate examples of cities that resisted so that many others surrendered on his approach: producing fear was part of the system.'],
      fall:['多因叠加,而且都是内生的:1405年他在东征明朝途中病死于讹答剌,诸王立刻内战;沙哈鲁虽在赫拉特重建了一个较小的核心,河中与伊朗已各自为政;军队的忠诚建立在不断有仗打、有财分之上,征服一停,凝聚力就散。15世纪后期,西边被黑羊、白羊两个土库曼联盟蚕食,东边1500至1507年被昔班尼率领的乌兹别克人夺去河中与呼罗珊。','The causes stacked and all of them were internal: when he died at Otrar in 1405 on his way to invade Ming China the princes went straight to war; Shahrukh rebuilt a smaller core at Herat, but Transoxiana and Iran had gone their own ways; and an army whose loyalty rested on constant campaigns and shares of loot came apart when the conquering stopped. In the later 15th century the Qara Qoyunlu and Aq Qoyunlu Turkmen confederations ate away at the west, and between 1500 and 1507 Shibani Khan\'s Uzbeks took Transoxiana and Khorasan.'],
      legacy:['撒马尔罕与赫拉特的建筑、细密画与察合台语文学,构成了所谓“帖木儿文艺复兴”。其孙兀鲁伯在撒马尔罕建大型天文台,1437年前后编成的星表精度极高,后来传入欧洲被反复引用;而他1449年被自己的儿子所杀,恰是这个王朝继承问题的缩影。五世孙巴布尔南下印度开创莫卧儿王朝——莫卧儿人自称的是帖木儿之后,不是蒙古之后。','The architecture of Samarkand and Herat, miniature painting and Chagatai literature make up what is called the Timurid renaissance. His grandson Ulugh Beg built a great observatory at Samarkand whose star catalogue, completed around 1437, was extraordinarily accurate and was later cited again and again in Europe; that he was murdered in 1449 on his own son\'s orders is this dynasty\'s succession problem in miniature. His great-great-grandson Babur went south into India and founded the Mughal empire, whose rulers called themselves heirs of Timur rather than of the Mongols.'] },
  d:'瘸子帖木儿自认成吉思汗的继承者,从德里到安卡拉无役不胜,连奥斯曼苏丹也做了他的俘虏;正欲远征明朝时病逝军中。其孙兀鲁伯的天文表精确得令后世欧洲天文学家叹服,五世孙巴布尔南下印度,开创了莫卧儿王朝。' },
{ l:'st', s:'steppe', v:1, n:'北元·蒙古诸部', k:[[1368,0],[1400,.18],[1450,.12],[1510,.28],[1570,.3],[1600,.15],[1635,0]], b:'元朝被赶回草原之后又活了二百七十年;最后一位大汗死后第二年,他儿子把传国玉玺交给了东边新起来的政权。',
  d:'1368 年明军进入大都,元朝的朝廷退回草原却没有改国号,史称北元。1388 年一场大败之后,蒙古分成东边的鞑靼与西边的瓦剌,两百年里谁也压不住谁——大汗的位子按规矩只有成吉思汗的后代能坐,瓦剌的也先没有这个出身,自立两年就被杀。达延汗 1480 年即位时还是个孩子,到 1510 年前后才真正压服各部,并把地盘分封给自己的儿子们;他的孙子俺答汗 1571 年与明朝议和、沿长城开了互市,1578 年又给了藏传佛教格鲁派的索南嘉措「达赖喇嘛」这个称号。最后一位大汗林丹汗 1634 年死在西去青海的路上,第二年他的儿子把元朝的传国玉玺献给皇太极——再过一年,皇太极改国号为清。',
  e:{ n:'Northern Yuan & Mongol Tribes', w:'Northern Yuan', b:'Driven back to the steppe, the Yuan lasted another 270 years — and its last khan\'s seal ended up founding somebody else\'s empire.', d:'When Ming armies took Dadu in 1368 the Yuan court withdrew north and went on calling itself the Yuan. After 1388 it broke into the Tatars and the Oirats, and for two centuries no one could hold the whole steppe: the throne was reserved by custom for descendants of Chinggis, and an Oirat who seized it without that descent was killed within two years. Dayan Khan came to the title in 1480 as a child and only subdued the tribes around 1510, parcelling them out among his sons; his grandson Altan Khan took the Ming to the negotiating table in 1571 and gave the title "Dalai Lama" to a Tibetan monk in 1578. The last khan, Ligdan, died in 1634, and in 1635 his son handed the imperial seal to Hong Taiji — who declared the Qing the following year.', f:{ 'Peak':'Dayan Khan to Altan Khan (1480—1582)', 'Center':'Guihua (today\'s Hohhot)', 'Figures':'Dayan Khan; Altan Khan; Ligdan Khan', 'Legacy':'The Longqing border markets; the title "Dalai Lama"' } },
  f:{ '鼎盛':'达延汗到俺答汗(1480—1582)', '中心':'归化城(今呼和浩特)', '人物':'达延汗、俺答汗、林丹汗', '成就':'隆庆和议的互市、「达赖喇嘛」称号的由来' },
  qh:{ born:['朝廷被赶走了,国号带着一起走','The court was driven out and took the dynasty\'s name along'],
       rule:['大汗的位子,只有成吉思汗的后代能坐','Only a descendant of Chinggis could sit as khan'],
       money:['抢和做买卖,是同一件事的两种做法','Raiding and trading were two ways of doing one thing'],
       power:['骑兵还是快,可是墙上架了火炮','The horsemen were still fast; the wall now had guns'],
       fall:['想统一蒙古,反而把各部推给了对手','He tried to reunite the Mongols and pushed them to his rival'],
       legacy:['「达赖喇嘛」这个称号,是这时候给出去的','The title "Dalai Lama" was conferred in these years'] },
  q:{ born:['1368 年明军进入大都,元顺帝北走,朝廷退回草原却没有改国号,史称北元——它认为自己仍是元朝。1388 年被明军击溃后,大汗的权威一路衰落,蒙古分成东边的鞑靼与西边的瓦剌两大块,此后两百年谁也压不住谁。','Ming armies entered Dadu in 1368 and the Yuan emperor withdrew north. The court kept the dynastic name — it considered itself still the Yuan — but after a crushing defeat in 1388 the khan\'s authority drained away, and the Mongols split into the Tatars in the east and the Oirats in the west. For two centuries neither could hold the other down.'],
      rule:['瓦剌的也先不是黄金家族出身,1453 年自立为大汗,两年后就被杀——这条规矩管了两百多年。达延汗 1480 年即位时还是个孩子,要到 1510 年前后才真正压服各部,再把地盘分封给儿子们——蒙古从此按血缘切成几十个单位,统一靠的是同一个祖宗,而不是同一个朝廷。','The Oirat leader Esen, who had no descent from Chinggis, declared himself khan in 1453 and was killed within two years — the rule held for over two centuries. Dayan Khan received the title in 1480 as a child and only subdued the tribes around 1510, then parcelled them out among his sons — from then on the Mongols were divided by blood into dozens of units, held together by a common ancestor rather than a common court.'],
      money:['草原缺铁、缺布、缺茶,而这些都在南边。抢和买是两种办法,两种都用过:1449 年土木堡一战俘虏了明朝皇帝;1571 年隆庆和议之后在长城沿线开了互市,用马换茶、换布、换锅。开市之后边境安静了几十年——打和做买卖,原是同一件事的两种做法。','The steppe lacked iron, cloth and tea, and all of it lay to the south. Raiding and trading were both used: in 1449 the Mongols captured a Ming emperor at Tumu, and in 1571 a settlement opened licensed markets along the Great Wall, trading horses for tea, cloth and cooking pots. The border stayed quiet for decades afterwards — raiding and trading were two ways of doing the same thing.'],
      power:['骑兵仍然快,但对手变了:明朝沿长城布置火铳与炮台,骑兵冲不进砖石与火器组成的线;而蒙古自己又分成几十股,谁也号令不了谁。两百年里最大的一次胜利(土木堡)之后,他们并没有能力接着南下——赢一仗和占一片地,是两回事。','The horsemen were as fast as ever, but the opponent had changed: the Ming lined the Great Wall with handguns and cannon, and cavalry could not break a line of masonry and gunpowder. The Mongols themselves were split into dozens of factions that no one could command. Even after their greatest victory at Tumu they could not follow it up — winning a battle and holding ground are different things.'],
      fall:['林丹汗想把蒙古重新捏成一个,手段强硬,结果把不服的各部一个个推向东边新起的后金。1634 年他病死在西去青海的途中;第二年,他的儿子把元朝的传国玉玺献给皇太极。1636 年皇太极称帝,改国号为清——蒙古各部从此成了这个新王朝的一部分,而不是它的对手。','Ligdan Khan tried to force the Mongols back into one state, and his methods drove tribe after tribe into the arms of the rising Jurchen power in the east. He died on the road west to Qinghai in 1634, and the next year his son presented the Yuan imperial seal to Hong Taiji. In 1636 Hong Taiji proclaimed himself emperor and renamed his state the Qing — and the Mongol tribes entered it as a part rather than as an enemy.'],
      legacy:['最深的变化是信仰。1578 年俺答汗在青海与藏传佛教格鲁派的索南嘉措会面,给了他「达赖喇嘛」这个称号——这个称号从那次会面用到今天,而索南嘉措被追认为三世,前面两世是往回补的。此后喇嘛教传遍蒙古各部,寺院取代了萨满,蒙古文的佛经也是这一时期译出来的。','The deepest change was religious. In 1578 Altan Khan met Sonam Gyatso of the Tibetan Gelug school in Qinghai and gave him the title "Dalai Lama" — the title has been in use ever since that meeting, and Sonam Gyatso was counted the third, the first two being assigned backwards. Lamaism spread through the Mongol tribes afterwards, monasteries displaced the shamans, and the Mongolian Buddhist canon was translated in these years.'] } },
{ l:'st', s:'steppe', v:0, n:'东察合台·叶尔羌', k:[[1348,0],[1400,.18],[1514,.24],[1570,.28],[1650,.18],[1705,0]], b:'成吉思汗的后代在天山南北当汗当到 1705 年,比在蒙古本土还久;开国的赛义德汗、写《拉失德史》的海答儿、在印度建莫卧儿的巴布尔,是同一个外公的三个外孙。',
  d:'1348 年秃黑鲁帖木儿在这一带被拥立为汗,察合台的后人从此在天山南北自成一支,史称东察合台汗国,也叫蒙兀儿斯坦。1514 年赛义德汗以叶尔羌(今莎车)为都建国,喀什噶尔与和田都在治下,丝路南道的玉石与商队从这里过。汗的位子按规矩只有成吉思汗的后代能坐,而这一支坐到了 1705 年——比蒙古本土还久。「蒙兀儿」是波斯语对「蒙古」的叫法。开国的赛义德汗、写下《拉失德史》的米尔咱·海答儿,以及南下印度建起莫卧儿帝国的巴布尔,三个人是同一个外公——东察合台汗羽奴思汗——的外孙:一个往东建了叶尔羌,一个往南建了莫卧儿,一个把这段历史写成了书。莫卧儿(Mughal)这个名字本身就是「蒙古」,来的正是这层关系。',
  e:{ n:'Moghulistan & Yarkand', w:'Moghulistan', b:'Chinggisid khans ruled here until 1705 — longer than in Mongolia itself; and the founder of India\'s Mughal empire was a first cousin of the man who founded this one.', d:'In 1348 Tughlugh Timur was raised as khan in this country, and the line of Chagatai went its own way across the Tian Shan — the Eastern Chagatai Khanate, or Moghulistan. In 1514 Sultan Said Khan founded a state with its capital at Yarkand, holding Kashgar and Khotan, astride the jade and caravan roads of the southern Silk Route. By custom only a descendant of Chinggis could be khan, and this line held the title until 1705 — longer than in Mongolia itself. "Moghul" is simply the Persian for "Mongol". Sultan Said Khan who founded this state, Mirza Haidar who wrote the Tarikh-i-Rashidi, and Babur who went south and founded the Mughal empire in India were all grandsons of one man, the Moghul khan Yunus. One built eastward, one built southward, and one wrote the history. The name Mughal is the word "Mongol", and it travelled by that family tie.', f:{ 'Peak':'Sultan Said to Rashid Khan (1514—1560)', 'Center':'Almaliq; Yarkand', 'Figures':'Tughlugh Timur; Sultan Said Khan', 'Legacy':'The Tarikh-i-Rashidi; the jade road of the southern Silk Route' } },
  f:{ '鼎盛':'赛义德汗到拉失德汗(1514—1560)', '中心':'阿力麻里、叶尔羌', '人物':'秃黑鲁帖木儿、赛义德汗', '成就':'《拉失德史》、丝路南道的玉石商路' },
  qh:{ born:['察合台的后人分了家,东边这一半在天山','Chagatai\'s line split; this half kept the Tian Shan'],
       rule:['汗必须姓成吉思,可管事的常常不是他','The khan was a Chinggisid; the ruler often was not'],
       money:['和田的玉,往东进嘉峪关,往西去撒马尔罕','Khotan jade went east to the Wall and west to Samarkand'],
       power:['沙漠把地盘切成一串绿洲,谁也吞不掉谁','The desert cut the realm into oases; none could swallow another'],
       fall:['请准噶尔人来帮忙,请进来就没走','They invited the Dzungars in, and the Dzungars stayed'],
       legacy:['三个表兄弟:一个建叶尔羌,一个建莫卧儿,一个写书','Three cousins: one built Yarkand, one the Mughals, one the history'] },
  q:{ born:['察合台汗国在 14 世纪中叶裂成东西两半。1348 年秃黑鲁帖木儿在东边被异密们拥立为汗,后来皈依伊斯兰教,史书说他带着部众一起改了宗。这一支占着天山南北的绿洲与草场,波斯语的史料把这片地方叫作蒙兀儿斯坦——「蒙古人的地方」。','The Chagatai Khanate split in two in the middle of the fourteenth century. In 1348 the emirs raised Tughlugh Timur as khan in the eastern half; he later converted to Islam, and the chronicles say his followers converted with him. This line held the oases and pastures on both sides of the Tian Shan, and Persian sources called the country Moghulistan — the land of the Mongols.'],
      rule:['名分与权力分开了两三百年:汗的位子按规矩只有成吉思汗的后代能坐,而真正调兵征税的常常是异密(贵族),到后期则是和卓——从中亚来的宗教世家。汗还在,拿主意的换了人,这个格局一直维持到最后。','Title and power came apart for two or three centuries: by custom only a descendant of Chinggis could sit as khan, while the men who actually raised troops and collected taxes were the emirs, and later the khojas — religious families out of Central Asia. The khan remained; the decisions moved elsewhere, and stayed there to the end.'],
      money:['靠的是丝路南道:和田的玉、于阗一带的丝、吐鲁番的葡萄干,往东出嘉峪关进中原,往西过帕米尔去撒马尔罕。玉是这里最硬的通货——明代宫廷用的玉,大半从这条路来。绿洲之间隔着沙漠,商队走的是一串水井,谁控制水井谁抽税。','Its living came from the southern Silk Route: jade from Khotan, silk from the oases, raisins from Turfan, going east through the Jiayu Pass into China and west over the Pamirs to Samarkand. Jade was the hardest currency here — most of the jade used at the Ming court came along this road. Desert lay between the oases, so caravans moved from well to well, and whoever held the wells took the toll.'],
      power:['骑兵仍然能打,可地盘被塔克拉玛干沙漠切成一串绿洲,每座城各管各的水源,谁也吞不掉谁——分裂因此是常态而不是意外。1516 年吐鲁番的满速儿汗亲率骑兵打到嘉峪关下,明朝的反应不是出兵,而是一步步往里收,到 1528 年索性把嘉峪关关上。','The cavalry could still fight, but the Taklamakan cut the realm into a string of oases, each city holding its own water, and none able to swallow another — division was the normal state, not an accident. When Mansur Khan of Turfan rode up to the Jiayu Pass in 1516, the Ming did not march out; they drew inward step by step, and in 1528 shut the pass altogether.'],
      fall:['和卓家族坐大,白山派与黑山派互斗不休,最后一派请准噶尔人入境助战——请进来就没有再走。1680 年前后准噶尔控制了这一带,1705 年最后一位汗被废黜。成吉思汗的血脉在天山南北当了三百五十多年的汗,到此为止。','The khoja families grew strong, the White Mountain and Black Mountain factions fought without end, and one of them finally invited the Dzungars in to help — who then did not leave. The Dzungars took control around 1680, and in 1705 the last khan was deposed. The Chinggisid line had held the title here for over three hundred and fifty years, and there it ended.'],
      legacy:['这三百年的事几乎全靠一本书留下来:米尔咱·海答儿流亡克什米尔时写的《拉失德史》,没有它,这一段近乎空白。而「蒙兀儿」这个词往南走得更远。海答儿的表哥巴布尔——两人同一个外公,东察合台汗羽奴思汗——南下印度建起的帝国,被波斯语称作 Mughal,汉语译作「莫卧儿」。那个统治了印度三百年的名字,本义就是「蒙古」;它不是从这片土地带走的,是顺着一门亲戚关系传过去的。','Almost everything known about these three centuries comes from one book: the Tarikh-i-Rashidi, written by Mirza Haidar in exile in Kashmir — without it the period is close to blank. And the word "Moghul" travelled further south. Haidar\'s cousin Babur — the two shared a grandfather, the Moghul khan Yunus — went down into India and founded the empire Persian called Mughal. The name that ruled India for three centuries simply means "Mongol"; it travelled not with the territory but along a family tie.'] } },
{ l:'st', s:'steppe', v:2, n:'哈萨克汗国', k:[[1465,0],[1520,.3],[1680,.25],[1750,.15],[1847,0]], b:'"脱离者"自立门户,三个玉兹构成今日哈萨克民族。',
  e:{ n:'Kazakh Khanate', w:'Kazakh Khanate', b:'"The ones who left" — and the three hordes that became a nation.', d:'In 1465 two sultans led their followers away from the Uzbek khanate and moved east; "Kazakh" means the ones who broke away, the free. The division into Great, Middle and Little Hordes survives to this day as the substrate of Kazakh society. Caught between the Dzungars to the east and Russia to the north, the 1723 Dzungar surprise attack — remembered as the Great Disaster — drove the hordes to seek Russian help one by one, and onto the road to annexation.', f:{ 'Peak':'Kasym Khan (early 16th c.)', 'Center':'Turkestan city', 'Figures':'Ablai Khan', 'Legacy':'The Kasym law code; the three-horde structure' } },
  f:{ '鼎盛':'哈斯木汗(16世纪初)', '中心':'突厥斯坦城', '人物':'阿布赉汗', '成就':'哈斯木汗法典、三玉兹格局' },
  qh:{ born:['民族的名字,就是「脱离出去」','The name of the people means those who broke away'],
       rule:['汗得出自成吉思系,权力却要商量','The khan had to be a Chinggisid; the power was negotiated'],
       money:['牧民必须进城,才能换到粮和铁','The herders had to enter the towns for grain and iron'],
       power:['打不过就散开,让对方找不到决战','Outmatched, they scattered, and left no battle to fight'],
       fall:['东边的压力刚没,北边的就压上来','The pressure from the east lifted, and the north moved in'],
       legacy:['今天很多人还能背出自己七代祖先','Many still recite seven generations of ancestors'] },
  q:{ born:['1465年前后,朮赤系的两位苏丹贾尼别克与克烈脱离乌兹别克汗阿布海尔,率部东迁到七河一带另立门户。“哈萨克”一词的意思就是脱离者、自由人:一个民族的名字,直接来自它的建国动作。','Around 1465 two Jochid sultans, Janibek and Kerei, broke away from the Uzbek khan Abu\'l-Khayr and led their followers east into Semirechye to set up on their own. The word Qazaq means one who breaks away, a free man: the people\'s name comes straight from the act that founded them.'],
      rule:['汗必须出自成吉思系,但汗权是协商出来的。社会真正的骨架是大、中、小三个玉兹——每个玉兹是一组部落,各有固定的夏牧场、冬营地与迁徙路线;部落内部由“比”(长老兼法官)按习惯法裁断。哈斯木汗的法典与17世纪末头克汗的《七项法典》把习惯法成文化,管的是牧场、牲畜、血亲赔偿这类真问题。','The khan had to be a Chinggisid, but his authority was negotiated. The real skeleton of society was the three zhuz, Great, Middle and Little, each a grouping of tribes with its own summer pastures, winter camps and migration routes, and inside each tribe the biys, elders who judged by customary law. Qasim Khan\'s code and Tauke Khan\'s Seven Charters at the end of the 17th century wrote that customary law down, and what it governed were the real questions: pasture, livestock and compensation between kin.'],
      money:['牧业按季节在夏牧场与冬营地之间循环。真正的战略资产是锡尔河沿岸的商队城市——突厥斯坦(亚西)、锡格纳克、萨乌兰:牧民必须在那里用牲畜与皮毛换粮食、布匹和铁器。它与河中的乌兹别克政权打了一个多世纪,争的基本就是这几座城。','Herding cycled with the seasons between summer pasture and winter camp. The strategic asset was the caravan towns along the Syr Darya, Turkestan (Yasi), Sighnaq and Sauran, where herders had to exchange animals and hides for grain, cloth and iron. Their century-long wars with the Uzbek states of Transoxiana were, at bottom, about those towns.'],
      power:['人力与空间。三个玉兹合起来能出很大规模的骑兵,遇强敌又可以向草原深处散开,让对方找不到决战的对象;1720年代末的安拉凯之战,是三玉兹少有的联合作战并取胜的例子。','Manpower and space. The three zhuz together could put a very large body of cavalry in the field, and against a stronger enemy they could disperse deep into the steppe so that there was nothing to bring to battle; the victory at Anrakay in the late 1720s was one of the rare occasions when all three fought as one.'],
      fall:['被两头夹住。1723年准噶尔突然大举来袭,牧场与迁徙路线被打乱,部众西逃,史称“大灾难之年”;小玉兹汗阿布勒海尔1731年向俄国求保护,中玉兹随后跟进。1755至1758年清朝灭准噶尔,东边的压力没了,北边的压力却压了上来:俄国的堡垒线、哥萨克移民与土地圈占逐年南推,1822年、1824年两部法令取消了中玉兹与小玉兹的汗位;1837至1847年克涅萨雷起义失败,汗国的历史到此为止。','They were caught between two sides. In 1723 a sudden large Dzungar attack broke up their pastures and migration routes and drove people west, in what is remembered as the Great Disaster; in 1731 Abulkhair, khan of the Little Zhuz, sought Russian protection, and the Middle Zhuz followed. When the Qing destroyed the Dzungars between 1755 and 1758 the eastern pressure vanished, but the northern pressure arrived: Russian fort lines, Cossack settlement and land seizures pushed south year by year, and statutes of 1822 and 1824 abolished the khanship in the Middle and Little Zhuz. The failure of Kenesary\'s revolt between 1837 and 1847 closed the khanate\'s history.'],
      legacy:['三玉兹与部落谱系至今仍是哈萨克社会的底层结构,许多人能背出自己的七代祖先。哈斯木、头克两部法典是游牧社会习惯法的少见样本(两部法典都没有完整传世,靠背诵与援引流传);阿肯弹唱与英雄史诗保存了没有文字的年代里的历史记忆。今天哈萨克斯坦的民族与语言,直接由这个汗国而来。','The three zhuz and the tribal genealogies are still the underlying structure of Kazakh society, and many people can recite seven generations of ancestors. The codes of Qasim and Tauke are rare written specimens of nomadic customary law, and the songs of the aqyns and the heroic epics preserved historical memory through centuries without writing. The nation and language of today\'s Kazakhstan come directly from this khanate.'] },
  d:'1465年两位苏丹率部脱离乌兹别克汗国东迁,"哈萨克"一词意为脱离者、自由人——一个民族的名字就是它的建国方式。大、中、小三个玉兹的划分延续至今,仍是哈萨克社会的底层结构。夹在东边的准噶尔与北边的沙俄之间,1723年准噶尔突袭造成的"大灾难之年"迫使它逐部向俄国求援,也就此走上被吞并的路。' },
{ l:'st', s:'mideast', v:0, n:'布哈拉·希瓦·浩罕三汗国', k:[[1500,0],[1600,.3],[1700,.2],[1800,.25],[1876,0]], b:'乌兹别克三汗国;丝路萧条后中亚最后的本土政权。',
  e:{ n:'Uzbek Khanates', w:'Khanate of Bukhara', b:'Three khanates; Central Asia\'s last native states.', d:'Shaybani brought the Uzbeks south and finished the Timurids, after which Central Asia was governed for three centuries by the khanates of Bukhara, Khiva and Kokand. Once sea routes opened, the overland Silk Road withered and the khanates turned inward — though Bukhara remained one of the most madrasa-dense cities in the Muslim world. In the nineteenth century they became the board on which Britain and Russia played the Great Game, and were annexed one after another: the last page of native rule in Central Asia.', f:{ 'Peak':'16th c. and early 19th c.', 'Center':'Bukhara, Khiva, Kokand', 'Figures':'Muhammad Shaybani', 'Keywords':'The chessboard of the Great Game' } },
  f:{ '鼎盛':'16世纪与19世纪初', '中心':'布哈拉、希瓦、浩罕', '人物':'昔班尼汗', '关键词':'"大博弈"的棋盘' },
  ct:['三个汗国','The three khanates'],
  co:[ { n:['布哈拉','Bukhara'], y:[1500,1920], c:['泽拉夫尚河谷','the Zarafshan valley'], x:['三块灌溉绿洲各养得起一支军队,中间隔着沙漠与山地,谁也吞不下谁;三家也不是同时出现的,浩罕晚了两百年,布哈拉后期改称埃米尔国。色带止于1876年——那年浩罕被俄国直接并入;布哈拉与希瓦已先后成了保护国,名义上又存续到1920年','each of the three irrigated oases could feed an army of its own, with desert and mountain in between, so none could swallow the others; nor did the three appear together — Kokand came two centuries later, and Bukhara later restyled itself an emirate. The band stops at 1876, the year Russia annexed Kokand outright; Bukhara and Khiva had already become protectorates and lasted in name until 1920'] },
       { n:['希瓦','Khiva'], y:[1511,1920], c:['阿姆河下游三角洲','the lower Amu Darya delta'] },
       { n:['浩罕','Kokand'], y:[1709,1876], c:['费尔干纳盆地','the Ferghana basin'] } ],
  qh:{ born:['三块绿洲各养一支军队,谁也吞不下谁','Three oases, three armies, and none could swallow another'],
       rule:['没有成吉思血统,就改个称号来立威','No Chinggisid blood, so they changed the title instead'],
       money:['东西的路淡了,南北的路反而旺了','The east-west road faded; the north-south road grew'],
       power:['谁也压不倒谁,于是谁都不改革军队','None could beat another, so none reformed its army'],
       fall:['自己打了几百年,外面盯上了棉花','They fought each other for centuries, while others wanted the cotton'],
       legacy:['中亚近代知识分子,从这些城里长出来','Modern Central Asian intellectuals grew out of these cities'] },
  q:{ born:['1500至1507年昔班尼率乌兹别克人南下,终结了帖木儿王朝在河中与呼罗珊的统治。三家并不是同时出现的:布哈拉与希瓦立于16世纪初,浩罕晚到18世纪初。那为什么长期是三家而不是一家?地理给了答案:泽拉夫尚河谷、阿姆河下游三角洲、费尔干纳盆地,三块灌溉绿洲各自能养活一支军队,彼此之间隔着沙漠与山地,谁也吞不下谁。三个汗国分别在这三块地上定型。','Between 1500 and 1507 Shibani Khan led the Uzbeks south and ended Timurid rule in Transoxiana and Khorasan. Why was Central Asia then three states rather than one for centuries? Geography answers: the Zarafshan valley, the lower Amu Darya delta and the Ferghana basin are three irrigated blocks, each able to feed an army and each separated from the others by desert and mountain, so none could swallow the rest. The three khanates hardened onto those three blocks.'],
      rule:['乌兹别克部落贵族掌兵,成吉思系血统一度是称汗的门槛;18世纪后期布哈拉的曼吉特家族没有这个血统,索性不称汗而称埃米尔,改用伊斯兰教法与护教者的身份立威。宗教势力极重:经学院与瓦克夫地产规模惊人,教法学者的意见常常比宫廷更管用。劳动力中有一部分是被土库曼部落掳掠贩卖的波斯人奴隶,这在19世纪成了俄国出兵的公开理由之一。','Uzbek tribal nobles held the troops, and Chinggisid blood was for a time the price of the title khan; when the Manghit house of Bukhara lacked that blood in the later 18th century, they simply stopped calling themselves khan, took the title emir, and based their authority on Islamic law and the role of defender of the faith instead. Religious institutions weighed heavily: the madrasas and waqf estates were enormous and the jurists\' opinion often carried further than the court\'s. Part of the labour force were Persian captives seized and sold by Turkmen raiders, which in the 19th century became one of Russia\'s stated reasons for intervening.'],
      money:['灌溉农业(粮食、桑蚕、瓜果、棉花)是底盘。海路兴起后东西过境贸易的分量确实下降,但南北方向反而扩大:18至19世纪,俄国的布匹与金属南下,中亚的棉花与卡拉库尔羔皮北上,布哈拉商人一直做到下诺夫哥罗德的集市;浩罕则专营与新疆的贸易,1830年代还取得了在喀什噶尔向外来商人抽税的权利。','Irrigated agriculture, grain and silk and fruit and cotton, was the base. East-west transit trade did lose weight after the sea routes opened, but the north-south axis grew instead: through the 18th and 19th centuries Russian cloth and metal came south while Central Asian cotton and karakul lambskins went north, with Bukharan merchants trading as far as the fair at Nizhny Novgorod, while Kokand specialised in the Xinjiang trade and in the 1830s won the right to tax foreign merchants in Kashgar.'],
      power:['骑兵、城塞,以及彼此的均势。三家谁也压不倒谁,反过来说,也就谁都没有压力去改革军队——直到19世纪中叶遇上带线膛炮与操典化步兵的俄军,差距一次显形。','Cavalry, walled cities, and a balance among the three. None could overpower the others, which also meant none was ever under pressure to reform its army, until the mid-19th century brought Russian troops with rifled artillery and drilled infantry and the gap showed all at once.'],
      fall:['多因叠加:三家长年互攻(布哈拉与浩罕反复争夺乌拉提尤别一线)消耗国力;军事技术停滞;英俄“大博弈”与俄国纺织业对棉花的需求,把中亚推到了迟早被吞并的位置。1865年俄军取塔什干,1868年布哈拉战败成为保护国,1873年希瓦亦然,1876年浩罕被直接并入。布哈拉与希瓦以保护国形式一直存续到1920年才被红军终结。','Causes stacked: constant war among the three, with Bukhara and Kokand fighting repeatedly over the Ura-Tyube line, drained them; military technology stood still; and the Anglo-Russian Great Game together with the Russian textile industry\'s hunger for cotton put Central Asia in a position where annexation was only a matter of time. Russian troops took Tashkent in 1865, Bukhara was defeated and made a protectorate in 1868 and Khiva in 1873, and Kokand was annexed outright in 1876. Bukhara and Khiva survived as protectorates until the Red Army ended them in 1920.'],
      legacy:['今天乌兹别克斯坦、土库曼斯坦、塔吉克斯坦的人口与城市格局,基本是在这三百多年里定型的。布哈拉长期是伊斯兰世界经学院最密集的城市之一,在中亚享有圣城之名;希瓦与布哈拉的老城至今整体保存。19世纪末从这些城市里生出的扎吉德改革运动(主张办新式学校),是中亚近代知识分子的起点。','The population and urban map of today\'s Uzbekistan, Turkmenistan and Tajikistan largely took shape during these three centuries. Bukhara was long among the most madrasa-dense cities in the Islamic world and was known across Central Asia as a holy city, and the old towns of Khiva and Bukhara survive intact. The Jadid reform movement that grew out of these cities in the late 19th century, arguing for new-method schools, was the starting point of modern Central Asian intellectual life.'] },
  d:'昔班尼率乌兹别克人南下灭掉帖木儿王朝,此后中亚由乌兹别克诸汗国分治,布哈拉与希瓦立于16世纪初,浩罕晚到18世纪初。海路兴起后陆上丝路迅速萧条,三汗国日益封闭内向,布哈拉却仍是伊斯兰世界经学院最密集的城市之一。19世纪它们成了英俄"大博弈"的棋盘,最终一个接一个并入沙俄——中亚本土政权的最后一页。' },
{ l:'st', s:'steppe', v:1, n:'准噶尔', k:[[1634,0],[1690,.3],[1758,0]], b:'最后的草原帝国,与清三朝拉锯七十年。',
  e:{ n:'Dzungars', w:'Dzungar Khanate', b:'The last steppe empire, ground down by three Qing reigns.', d:'The last nomad empire fought Kangxi, Yongzheng and Qianlong for seventy years before annihilation. In the age of muskets and cannon the mounted archer\'s edge was gone — the two-thousand-year steppe-empire era ended here.', f:{ 'Peak':'Galdan (1670s–90s)', 'Center':'Ili valley', 'Figures':'Galdan' } },
  f:{ '鼎盛':'噶尔丹(17世纪末)', '中心':'伊犁河谷', '人物':'噶尔丹' },
  qh:{ born:['不能称汗,就当佛教的护法者','Barred from the title of khan, it became defender of the faith'],
       rule:['南疆的税,交给当地家族代收','Taxes in the south were collected by local families'],
       money:['在草原上,给自己建了一个粮食基地','It built itself a granary out on the steppe'],
       power:['同时握着牧场和绿洲,拉锯了七十年','Holding both pasture and oasis, it held out seventy years'],
       fall:['输在火炮和粮台,不在骑兵','It lost to cannon and supply trains, not to cavalry'],
       legacy:['最后一个能威胁定居帝国的草原政权','The last steppe power that could threaten a settled empire'] },
  q:{ born:['卫拉特(西蒙古)诸部不是成吉思汗后裔,按草原旧规不能称汗,于是走了另一条路:以藏传佛教格鲁派护法者的身份取得合法性。17世纪30年代绰罗斯部的巴图尔珲台吉在额敏河、塔尔巴哈台一带整合诸部,1640年各部会盟制定《蒙古—卫拉特法典》,给这个联盟立了共同规矩。噶尔丹本人早年在西藏受戒学经,是带着宗教身份回来夺权的。','The Oirats, the western Mongols, were not descended from Chinggis Khan and so by old steppe rule could not take the title khan; they took another road, deriving legitimacy from being protectors of the Gelug school of Tibetan Buddhism. In the 1630s Erdeni Batur of the Choros clan pulled the tribes together in the Ili valley, and in 1640 an assembly of Mongol and Oirat chiefs adopted a shared law code. Galdan himself had been ordained and educated in Tibet, and came home to seize power carrying that religious standing.'],
      rule:['珲台吉之下是卫拉特各部,靠1640年的法典与联姻维系;宗教上则通过干预西藏事务(1717至1720年一度占据拉萨)来加固地位。塔里木盆地的绿洲由和卓家族代为征收赋税,准噶尔从南疆抽取粮食与货币,自己不直接管理城市。','Below the khong tayiji sat the Oirat tribes, held together by the 1640 code and by marriage, while religious standing was reinforced by intervening in Tibet, including an occupation of Lhasa from 1717 to 1720. In the Tarim basin the Khoja families collected taxes on their behalf, so the Dzungars drew grain and silver from the southern oases without administering the cities themselves.'],
      money:['牧业、南疆绿洲的赋税、与俄国及清朝的边境与朝贡贸易,再加上一手前人没做过的:把回部农民迁到伊犁河谷屯田(称“塔兰奇”),在草原上自建粮食基地。他们还试图自造军械——据记载,一名被俘的瑞典人雷纳特在准噶尔待了十余年,协助铸炮与绘制地图。','Herding, taxes from the southern oasis towns, border and tribute trade with Russia and the Qing, and one thing no predecessor had done: they moved Muslim farmers from the Tarim to the Ili valley, the Taranchi, to grow grain, building an agricultural base on the steppe itself. They also tried to make their own weapons; a captured Swede, Renat, is recorded as spending more than a decade among them helping to cast cannon and draw maps.'],
      power:['骑兵仍强,但它认真尝试过补上火器这块短板,也是同时握有草原牧场与塔里木绿洲两套资源的少数政权之一。凭这两点,它与康熙、雍正、乾隆三朝拉锯了七十年。','The cavalry was still strong, but this was a steppe power that made a serious attempt at closing the firearms gap, and one of the few to hold both steppe pasture and the Tarim oases at once. On those two strengths it fought the Qing across the reigns of three emperors for seventy years.'],
      fall:['多因叠加:清朝在火炮尤其是后勤上占绝对优势,能沿戈壁设仓转运、维持长距离远征,而准噶尔始终造不出同等规模的火器;1727年中俄《恰克图条约》划定边界,断了它借俄自重的可能;1745年噶尔丹策零死后继承内讧,阿睦尔撒纳投清并为清军引路。1755至1758年清军两路进兵,战乱、屠戮与随之而来的天花使准噶尔部众几近消失。','Causes stacked: the Qing had a decisive advantage in artillery and above all in logistics, building supply depots across the Gobi to sustain long-range campaigns, while the Dzungars never produced firearms on a comparable scale; the Treaty of Kyakhta in 1727 fixed the Russian border and removed any chance of leaning on Russia; and after Galdan Tseren died in 1745 a succession war broke out and Amursana defected to the Qing and guided its armies in. Qing forces advanced in two columns between 1755 and 1758, and war, killing and the smallpox that followed left almost nothing of the Dzungar people.'],
      legacy:['它常被称作最后一个草原帝国:此后再没有哪个游牧政权能威胁定居帝国——不是因为草原上的人变了,而是因为火炮、粮台与条约边界让机动性不再是决定性优势。清朝由此控制天山南北,后设新疆行省;空出来的伊犁河谷陆续迁入察哈尔、锡伯、维吾尔等各族,1771年从伏尔加河畔东归的土尔扈特部也落脚于此,今天新疆北部的人口格局由此形成。','It is often called the last steppe empire: after it no nomadic power ever threatened a settled empire again, not because the people of the steppe had changed but because artillery, supply depots and treaty borders had ended mobility\'s decisive edge. The Qing thereby controlled both sides of the Tianshan and later made Xinjiang a province; the emptied Ili valley was resettled with Chahar Mongols, Xibe, Uyghurs and others, and the Torghuts who trekked back from the Volga in 1771 also ended up there, which is how northern Xinjiang\'s population map came to be.'] },
  d:'最后一个草原帝国,与康熙、雍正、乾隆三朝拉锯七十年,终为乾隆两路进兵所灭。在火器与火炮的时代,骑射优势不复存在——延续两千年的游牧帝国时代就此终结。' },
{ l:'st', s:'steppe', v:2, n:'蒙古国', k:[[1911,0],[1924,.2],[1960,.22],[1990,.25],[2025,.3]], b:'成吉思汗的故乡在 20 世纪重新成为一个国家:先做苏联的邻居,1990 年后一人一票选总统。',
  e:{ n:'Mongolia', w:'Mongolia', b:'The homeland of Genghis Khan became a state again in the twentieth century — first in the Soviet shadow, then, after 1990, a democracy of its own.', d:'When the Qing fell in 1911 the Mongol nobles of the north declared independence under the Bogd Khan, their Buddhist head; after a decade of turmoil the revolution of 1921 and the People\'s Republic of 1924 tied the country to the Soviet Union for seventy years — the second communist state in the world, its monasteries destroyed in the 1930s. In 1990 peaceful demonstrations in Ulaanbaatar brought free elections, and Mongolia has been a parliamentary democracy since. Some three million people live on land the size of Western Europe, a quarter or more of them still herding; copper and coal are the exports, and China and Russia the only neighbours. The traditional script, the horse-head fiddle and the naadam games of wrestling, racing and archery survived it all.', f:{ 'Peak':'1990s to today', 'Centre':'Ulaanbaatar', 'Figures':'Damdin Sükhbaatar', 'Legacy':'independence kept between two giants, the naadam, the traditional Mongolian script revived' } },
  f:{ '鼎盛':'1990年代至今', '中心':'乌兰巴托', '人物':'苏赫巴托尔', '成就':'夹在两个大国之间守住的独立、那达慕、重新使用的传统蒙古文' },
  qh:{ born:['清朝一倒,北边的蒙古王公就宣布独立','When the Qing fell, the northern Mongol nobles declared independence'],
       rule:['世界上第二个共产党国家,后来一人一票','The second communist state in the world, later one person one vote'],
       money:['三百万人,四个里有一个还在放牧','Three million people, one in four still herding'],
       power:['两个邻居都是巨人,一个也得罪不起','Two neighbours, both giants, neither to be crossed'],
       fall:['援助一断,先崩溃,再靠矿翻身','Aid stopped, collapse came, then the mines pulled it up'],
       legacy:['成吉思汗回来了:机场、大学都叫他','Genghis is back — the airport and the university carry his name'] },
  q:{ born:['1911 年辛亥革命一起,外蒙古的王公和喇嘛在库伦(今乌兰巴托)拥立八世哲布尊丹巴为「博克多汗」,宣布脱离清朝独立;北洋政府 1919 年一度收回,1921 年苏赫巴托尔领导的人民党在苏俄红军支持下掌权,1924 年博克多汗去世后成立蒙古人民共和国——通常被算作世界上第二个共产党执政的国家。此后七十年它是苏联最紧的盟友,1930 年代的清洗毁掉了几乎全部寺院,喇嘛被杀被还俗的以万计。','When the revolution of 1911 broke out, the nobles and lamas of Outer Mongolia in Urga (today\'s Ulaanbaatar) enthroned the eighth Jebtsundamba as Bogd Khan and declared independence from the Qing; the Beijing government took the country back briefly in 1919, but in 1921 the People\'s Party under Sükhbaatar, backed by the Soviet Red Army, took power, and after the Bogd Khan died in 1924 the Mongolian People\'s Republic was proclaimed — usually counted as the second communist state in the world. For seventy years it was the Soviet Union\'s closest ally; the purges of the 1930s destroyed almost every monastery and killed or defrocked lamas by the tens of thousands.'],
      rule:['1990 年初,乌兰巴托的年轻人在苏赫巴托尔广场绝食示威,要求多党制,执政党没有开枪,几个月后举行了第一次自由选举——转型没有流血。1992 年新宪法把国名改回「蒙古国」,此后总统、议会都是一人一票选出,政权在人民党和民主党之间轮换过多次;传统蒙古文从 1990 年代起重新进入学校,与西里尔字母并用。','Early in 1990 young people in Ulaanbaatar went on hunger strike in Sükhbaatar Square demanding a multi-party system; the ruling party did not shoot, and within months the first free elections were held — the transition cost no lives. A new constitution in 1992 renamed the country simply Mongolia, and presidents and parliaments have been chosen by one person one vote since, power passing several times between the People\'s Party and the Democrats; the traditional Mongolian script came back into schools in the 1990s alongside the Cyrillic alphabet.'],
      money:['国土有西欧那么大,人口只有三百多万,将近一半住在乌兰巴托,四分之一到三分之一的人还在草原上放牧——羊、山羊、牛、马、骆驼加起来五六千万头,是人的十几倍(2024 年前后的数,白灾一来就跌)。出口靠矿:铜、煤、黄金,买家几乎只有中国;冬天的极端严寒「白灾」一来,牲畜成群冻死,牧民就搬进首都边上的蒙古包区。羊绒是它最出名的商品。','The land is the size of Western Europe and holds only three million people, nearly half of them in Ulaanbaatar, while a quarter to a third still herd on the steppe — fifty or sixty million sheep, goats, cattle, horses and camels between them around 2024, more than fifteen animals to every person, the number falling whenever a hard winter strikes. Exports are mining: copper, coal, gold, sold almost entirely to China; when the killing winter cold called dzud comes, livestock die in their thousands and herders move into the ger districts on the edge of the capital. Cashmere is its best-known product.'],
      power:['蒙古国只有两个邻居——俄罗斯和中国,而且都是巨人,它的外交就是在两者之间保持平衡:冷战时靠苏联,1961 年在苏联支持下加入联合国;1990 年后提出「第三邻国」政策,与美国、日本、韩国、欧盟往来,但铁路轨距是俄式的、出口靠中国港口。1939 年的诺门罕之战,苏蒙联军在东部边境击败日军,是二战前夜的一场大仗。','Mongolia has only two neighbours, Russia and China, both giants, and its foreign policy is a balancing act between them: it leaned on the Soviet Union in the Cold War and joined the United Nations with Soviet backing in 1961; after 1990 it adopted a third-neighbour policy, courting the United States, Japan, Korea and the European Union, though its railway gauge is Russian and its exports go out through Chinese ports. At Khalkhin Gol in 1939 Soviet and Mongolian forces beat the Japanese army on the eastern border — a large battle on the eve of the Second World War.'],
      fall:['1990 年苏联的支援断了,蒙古经历了几年经济崩溃,配给、失业、通胀一起来;2000 年代靠矿业翻身,一度是世界增长最快的经济体之一,又随铜价起落。1911 年宣布独立时的那份想法——一个属于蒙古人自己的国家——在两个大国之间维持了一个多世纪,这是它最不容易的成就。','When Soviet aid stopped in 1990 Mongolia went through years of economic collapse — rationing, unemployment and inflation together; mining pulled it up in the 2000s, for a time one of the fastest-growing economies in the world, rising and falling with the copper price. The idea declared in 1911 — a state of the Mongols\' own — has been kept alive between two great powers for more than a century, its hardest achievement.'],
      legacy:['每年七月的那达慕是全国的节日,摔跤、赛马、射箭三项,赛马的骑手多是孩子;马头琴、长调和呼麦被列为人类非物质文化遗产。成吉思汗在 1990 年后重新被当作国父纪念,机场、大学都以他命名,乌兰巴托东边立起一座四十米高的成吉思汗骑马像。蒙古国是把 13 世纪的记忆和今天的国家连在一起最紧的地方。','The naadam every July is the national holiday — wrestling, horse racing and archery, the jockeys mostly children; the horse-head fiddle, long song and throat singing are listed as intangible heritage of humanity. After 1990 Genghis Khan was restored as father of the nation, with the airport and the university named for him and a forty-metre statue of him on horseback raised east of Ulaanbaatar. Nowhere else ties the memory of the thirteenth century so tightly to a state of today.'] },
  d:'1911 年清亡后外蒙古王公拥立博克多汗宣布独立;1921 年苏赫巴托尔的人民党在苏俄支持下掌权,1924 年成立蒙古人民共和国,苏联最紧的盟友,1930 年代寺院尽毁。1990 年和平转型,一人一票选总统与议会,1992 年改国名蒙古国。三百万人、西欧大小的国土、三分之一放牧,出口靠矿、买家靠中国,外交在中俄之间平衡。' },
{ l:'st', s:'west', v:0, n:'俄国治下中亚', k:[[1730,0],[1860,.4],[1900,.5],[1965,.5],[1991,0]], b:'沙俄与苏联渐次吞并草原与河中,游牧时代终结。',
  e:{ n:'Russian Central Asia', w:'Russian Turkestan', b:'Tsars and Soviets absorb the steppe; the Great Game.', d:'Russia swallowed the steppe and Transoxiana through the 19th century, playing the Great Game against British India across the Pamirs; Soviet rule forced settlement and cotton monoculture — the Aral Sea nearly died of it. In 1991 five republics emerged.', f:{ 'Peak':'c. 1900 (railways and cotton)', 'Center':'Tashkent', 'Figures':'Abai Qunanbaiuly', 'Keywords':'Great Game, cotton economy' } },
  f:{ '鼎盛':'1900年前后(铁路与棉花经济)', '中心':'塔什干', '人物':'阿拜', '关键词':'大博弈、棉花经济' },
  qh:{ born:['美国内战一断棉花,俄国就要自己的产棉区','The American civil war cut the cotton, and Russia wanted its own'],
       rule:['对伊斯兰,既不资助也不打击','Towards Islam: neither support nor suppression'],
       money:['水都去浇棉花了,咸海就干了','The water went to cotton, and the Aral Sea went dry'],
       power:['武器是代差,管人还是靠本地头人','A generation ahead in weapons, and ruling through local headmen'],
       fall:['它们是最后才宣布独立的那一批','They were among the last to declare independence'],
       legacy:['留下的是一份两面的账','What it left is a two-sided ledger'] },
  q:{ born:['推力来自北方而不是南方。俄国自18世纪起沿草原修筑要塞线(奥伦堡等),19世纪中叶沿锡尔河向南推进,原因有三:控制草原与商路、与英属印度争夺中亚影响力(即“大博弈”),以及美国内战切断棉花供应后,俄国纺织业急需一个自己的产棉区——最后这一条的分量,学界估计不一。1865至1885年间,征服基本完成。','The push came from the north, not the south. From the 18th century Russia built lines of forts along the steppe, at Orenburg and elsewhere, and from the mid-19th century advanced south along the Syr Darya, for three reasons: control of the steppe and its trade routes, rivalry with British India for influence in Central Asia, the Great Game, and, after the American Civil War cut off cotton supplies, the Russian textile industry\'s urgent need for a cotton source of its own, a factor whose weight historians assess differently. The conquest was essentially complete between 1865 and 1885.'],
      rule:['1867年设突厥斯坦总督区,以塔什干为中心,军政合一;布哈拉与希瓦保留为保护国。首任总督考夫曼对伊斯兰教采取既不资助也不打击的方针,清真寺与教法法庭大体照旧,但土地与水权逐步转入国家与移民手中。19世纪90年代起大批俄国农民移入哈萨克与吉尔吉斯草原,占去水草最好的地块。苏联时期改行民族划界,1924至1936年间划出中亚五个加盟共和国的边界,并在1929至1933年强制牧民定居与集体化。','A Turkestan Governor-Generalship was created in 1867 with Tashkent as its centre, under combined military and civil rule, while Bukhara and Khiva were left as protectorates. The first governor-general, Kaufman, adopted a policy of neither funding nor attacking Islam, so mosques and sharia courts largely carried on, while land and water rights passed gradually to the state and to settlers. From the 1890s large numbers of Russian peasants moved onto the Kazakh and Kyrgyz steppe and took the best watered land. Under Soviet rule the map was redrawn along national lines between 1924 and 1936, creating the five Central Asian republics, and herders were forcibly settled and collectivised between 1929 and 1933.'],
      money:['棉花。突厥斯坦的耕地大幅改种棉花供应俄国工厂,粮食转而靠铁路从俄国运入——外里海铁路(1888年通车)与奥伦堡至塔什干铁路(1906年通车)既是运棉的通道,也是控制的工具。苏联把这套结构推到极致:阿姆河与锡尔河的水被大规模引去灌溉棉田,卡拉库姆运河等工程使咸海入水锐减,到20世纪末咸海只剩原来的一小部分。','Cotton. Much of Turkestan\'s arable land was converted to cotton for Russian mills, and grain then had to come in by rail from Russia; the Trans-Caspian railway, opened in 1888, and the Orenburg to Tashkent line, opened in 1906, were both cotton conduits and instruments of control. The Soviet period took the structure to its limit: water from the Amu Darya and Syr Darya was diverted on a huge scale to cotton fields, and works such as the Karakum Canal cut the inflow to the Aral Sea so severely that by the end of the 20th century only a fraction of it was left.'],
      power:['线膛枪炮、操典化的步兵与铁路,对上以骑兵和城墙为主的本地军队,几乎是代差,几场关键战役都在很短时间内分出胜负。另一半力量在行政上:俄国大量任用本地头人管理基层,以很少的军政人员统治极广的地区。','Rifled guns, drilled infantry and railways against local armies built on cavalry and city walls amounted to a generational gap, and the decisive battles were settled quickly. The other half of their power was administrative: Russia governed through large numbers of local headmen, so that a very small staff could hold an enormous territory.'],
      fall:['这一时期的终结同样是多因的。1916年因征调本地人服后方劳役,中亚爆发大规模起义,遭到镇压,大批吉尔吉斯人逃往中国;强制定居与集体化在1930年代初造成严重饥荒,仅哈萨克一族的死亡人数,学界估计在一百多万到两百万之间,另有大量人口外逃。1991年苏联解体,中亚五国相继独立——值得注意的是,它们并非独立运动的推动者,反而是最后宣布独立的一批加盟共和国。','The end of this era had several causes as well. In 1916 the conscription of local men for rear-area labour set off a mass uprising that was put down with heavy loss, and large numbers of Kyrgyz fled to China; forced settlement and collectivisation produced a severe famine in the early 1930s, in which scholarly estimates of Kazakh deaths alone range from something over one million to about two million, with many more fleeing abroad. When the Soviet Union dissolved in 1991 the five republics became independent one after another, though notably they had not been drivers of the independence movement and were among the last union republics to declare it.'],
      legacy:['游牧生活方式在一两代人之内结束,哈萨克与吉尔吉斯从此以定居为主。留下的是一份两面的账:一面是接近普及的识字率、工业与医疗体系,以及五个有明确边界的现代国家;另一面是单一棉花经济、干涸的咸海,以及犬牙交错的边界所埋下的水资源与飞地纠纷。俄语至今仍是中亚的通用语,20世纪被强制迁来的朝鲜人、德意志人等群体也留在了当地。','The nomadic way of life ended within a generation or two, and Kazakhs and Kyrgyz have been settled peoples ever since. The ledger has two sides: on one, near-universal literacy, industrial and medical systems, and five modern states with defined borders; on the other, a cotton monoculture, a dried-out Aral Sea, and borders drawn so intricately that water disputes and enclaves were built in from the start. Russian is still the region\'s lingua franca, and the Koreans, Germans and other peoples deported there in the 20th century stayed on.'] },
  d:'沙俄19世纪蚕食鲸吞草原与河中地区,与英属印度隔着帕米尔展开"大博弈";苏联时期强推定居化与棉花单一种植,咸海因过度灌溉几近干涸。1991年,中亚五国随苏联解体而独立。' },
{ l:'st', s:'mideast', v:1, n:'阿富汗', k:[[1747,0],[1761,.35],[1772,.3],[1823,.12],[1880,.1],[1919,.16],[1979,.12],[2025,.08]], b:'兴都库什山两边的部落在 1747 年头一回建起自己的国家;从那以后,想在这里驻下来的大国没有一个留得住。',
  e:{ n:'Afghanistan', w:'Afghanistan', b:'The tribes on both sides of the Hindu Kush founded a state of their own in 1747; since then no great power that came through has managed to stay.', d:'When the Persian ruler Nader Shah was assassinated in 1747, one of his Pashtun commanders, Ahmad Khan, went home to Kandahar and was chosen king by an assembly of tribal elders, renaming his tribe Durrani. At its height his empire covered today\'s Afghanistan, most of Pakistan, eastern Iran and Kashmir, and in 1761 at Panipat it destroyed the Maratha armies in one of the largest battles of the eighteenth century. The empire broke up after his death, and through the nineteenth century the country became the ground on which Britain and Russia played the Great Game: Britain invaded twice, occupying Kabul in 1839 and losing almost an entire army in the retreat of 1842, and took control of Afghan foreign policy until full independence in 1919. The Soviet Union came in 1979 and left in 1989; civil war followed, then the Taliban in 1996, then the Americans from 2001 to 2021 — more than forty years of war with no year of peace in them. It is landlocked and mountainous, and the deep blue lapis lazuli from its Badakhshan mines was traded to Mesopotamia and Egypt four thousand years ago.', f:{ 'Peak':'1747–1772 (Ahmad Shah Durrani)', 'Centre':'Kandahar, Kabul', 'Figures':'Ahmad Shah Durrani', 'Legacy':'lapis lazuli, the Khyber Pass, the Bamiyan caves' } },
  f:{ '鼎盛':'1747—1772年(艾哈迈德·沙·杜兰尼)', '中心':'坎大哈、喀布尔', '人物':'艾哈迈德·沙·杜兰尼', '成就':'青金石、开伯尔山口、巴米扬石窟' },
  qh:{ born:['1747 年,这里头一回由自己人立国','In 1747 the people here founded a state of their own'],
       rule:['国王的权力,是从部落头人手里借来的','A king\'s power was borrowed from the tribal chiefs'],
       money:['深蓝的青金石,四千年前就卖到埃及','Deep blue lapis, sold as far as Egypt four thousand years ago'],
       power:['山口就那么几个,守的人躲进山谷','Only a few passes, and defenders melt into the valleys'],
       fall:['苏联待了十年,美国待了二十年,都走了','The Soviets stayed ten years, the Americans twenty; both left'],
       legacy:['法老面具的眉毛,镶的是这里的石头','The eyebrows on the pharaoh\'s mask are stone from here'] },
  q:{ born:['统治这一带的波斯君主纳迪尔沙 1747 年被刺,他手下一位普什图将领艾哈迈德·汗带兵回到坎大哈,由部落长老会议推举为王,把自己的部落名从阿卜达里改成「杜兰尼」。在这之前的两千多年里,这片山地一直是别人的边疆:波斯人、贵霜人、嚈哒人、阿拉伯人、萨曼人、帖木儿和莫卧儿轮流管过它,喀布尔多数时候是某个大帝国最东边或最西边的一个省。所以艾哈迈德·沙·杜兰尼常被称作现代阿富汗的奠基者。','Nader Shah, the Persian ruler of these lands, was assassinated in 1747, and one of his Pashtun commanders, Ahmad Khan, marched his men home to Kandahar, where an assembly of tribal elders chose him king; he renamed his tribe from Abdali to Durrani. For more than two thousand years before that, this mountain country had been somebody else\'s frontier: Persians, Kushans, Hephthalites, Arabs, Samanids, Timur and the Mughals each held it in turn, and Kabul was usually the easternmost or westernmost province of some larger empire. That is why Ahmad Shah Durrani is generally called the founder of modern Afghanistan.'],
      rule:['艾哈迈德·沙靠各普什图部落推举上位,此后两百多年,喀布尔的统治者要办大事都得先在「支尔格大会」(部落与长老的大会)上取得同意;想跳过这一步的人几乎都失败了——1920 年代的阿马努拉汗照着土耳其的样子推行改革,办女子学校、限制多妻、要官员穿西装,1929 年被部落起义赶下台。1964 年查希尔沙颁布宪法,有过一段有选举和自由报刊的日子,史称「宪政十年」。','Ahmad Shah was raised up by the Pashtun tribes, and for more than two centuries afterwards a ruler in Kabul had to win the consent of a loya jirga — a grand assembly of tribes and elders — before doing anything large. Those who tried to skip that step mostly failed: in the 1920s Amanullah Khan pushed through reforms modelled on Turkey\'s, opening schools for girls, limiting polygamy and requiring officials to wear Western dress, and a tribal revolt drove him out in 1929. Zahir Shah\'s constitution of 1964 brought a decade with elections and a free press, remembered as the constitutional decade.'],
      money:['内陆、多山、干旱,没有出海口,东西运出去要借别人的路。传统上靠农业和放牧:小麦、葡萄干、石榴、开心果、羊。最特别的是巴达赫尚山里的青金石——一种深蓝色的石头,四千多年前就沿商路卖到两河流域与埃及,图坦卡蒙金面具的眉毛和眼眶镶的就是它。今天它是世界上最穷的国家之一,靠外国援助和侨汇过日子;地下探明有大量铜和铁,也常有人说有做电池要用的锂,但一直没探清;打了四十多年仗,路和电都不够,矿基本还留在地下。过去二十多年它还是世界上最大的鸦片产地——那是战乱长出来的经济。','It is landlocked, mountainous and dry, with no coast, so anything leaving has to cross somebody else\'s country. Traditionally it lived on farming and herding: wheat, raisins, pomegranates, pistachios, sheep. The most distinctive thing it has is the lapis lazuli of the Badakhshan mountains — a deep blue stone traded along the caravan roads to Mesopotamia and Egypt more than four thousand years ago, and the eyebrows and eye surrounds of Tutankhamun\'s golden mask are set with it. Today it is among the poorest countries on earth, living on foreign aid and money sent home by relatives abroad; large deposits of copper and iron have been surveyed, and lithium for batteries is often talked about though never properly measured; after forty years of war there are not enough roads or power stations and the ore is mostly still in the ground. For the past twenty years it has also been the world\'s largest source of opium — an economy the war grew.'],
      power:['力量来自地形和位置。兴都库什山把国家劈成两半,能过的山口就那么几个;开伯尔山口是从中亚进入印度平原最好走的一条,几千年里亚历山大、贵霜人、突厥人、蒙古人、巴布尔都从这一带走过。守的人躲进山谷,来的人守不住漫长的补给线——19 世纪英国人来过两次,1839 年占了喀布尔,1842 年撤退时整支队伍在山谷里几乎全没了;1979 年苏联开进来,打了十年,1989 年撤走;2001 年美国和盟军进来,待了二十年,2021 年撤走。','Its strength is terrain and position. The Hindu Kush splits the country in two and there are only a handful of passes; the Khyber is the easiest way from Central Asia down into the plains of India, and Alexander, the Kushans, Turks, Mongols and Babur all came through this corridor. Defenders melt into the valleys while invaders cannot hold a long supply line — the British came twice in the nineteenth century, occupied Kabul in 1839 and lost almost an entire column in the valleys during the retreat of 1842; the Soviet Union came in 1979, fought for ten years and withdrew in 1989; the Americans and their allies came in 2001, stayed twenty years and left in 2021.'],
      fall:['1973 年国王被堂弟推翻,1978 年共产党军官政变,1979 年底苏联出兵,打死当时的领导人,换上自己支持的人,战争从此没有停过:苏军十年、军阀内战、1996 年塔利班拿下喀布尔、2001 年美国与盟军进来、2021 年美军撤离当月塔利班重新掌权。四十多年里死了上百万人(具体数字争议很大),还有几百万人逃到巴基斯坦和伊朗——有很多年,阿富汗人是世界上人数最多的难民群体。塔利班 2021 年重新掌权,2022 年起禁止女孩上中学和大学,截至 2026 年仍未解除,这是外界最关注的一件事。','The king was overthrown by his cousin in 1973 and communist officers seized power in 1978; at the end of 1979 the Soviet Union sent in troops, killed the sitting leader and installed a man of its own, and the fighting has never really stopped since: ten years of Soviet war, then warlord civil war, then the Taliban taking Kabul in 1996, then the Americans and their allies from 2001, and in the same month the last American troops left in 2021 the Taliban were back in power. Well over a million are estimated to have died in these forty years, though the figures are much disputed, and millions fled to Pakistan and Iran — for many years Afghans were the largest refugee population in the world. Having returned to power in 2021, the Taliban barred girls from secondary school from 2022 and from university at the end of that year, and the ban still stood in 2026; it is what the outside world watches most closely.'],
      legacy:['巴米扬山崖上的两尊大佛立了一千四百年上下,是佛教沿丝路东传时代留下的,2001 年被塔利班炸毁;今天那两个空下来的石窟连同山谷列入了世界遗产名录。青金石仍在开采,普什图语与达里语的诗歌传统很长,风筝、地毯和抓羊比赛是它最日常的样子。给孩子最容易记住的一件事:埃及法老金面具上的眉毛,用的是这片山里出的石头——一个内陆山国,四千年前就已经和尼罗河边连着。','The two great Buddhas cut into the cliffs at Bamiyan stood for some fourteen hundred years, left from the age when Buddhism travelled the Silk Road; the Taliban blew them up in 2001, and the empty niches and the valley around them are now on the World Heritage list. Lapis is still mined, the poetry of Pashto and Dari runs long, and kite-flying, carpets and the horseback game of buzkashi are its everyday face. The easiest thing for a child to remember: the eyebrows on that Egyptian pharaoh\'s golden mask are stone mined in these mountains — a landlocked country in the hills, already connected to the banks of the Nile four thousand years ago.'] },
  d:'1747 年纳迪尔沙遇刺后,普什图将领艾哈迈德·汗在坎大哈由部落会议推举为王,建杜兰尼帝国,1761 年第三次帕尼帕特之战大破马拉塔,鼎盛时含今阿富汗、巴基斯坦大部、伊朗东部,以及克什米尔与今印度西北一角。帝国在他身后分崩,19 世纪成为英俄「大博弈」的棋盘:英国两次打进来,1839 年占了喀布尔,1842 年撤退时整支队伍几乎折在山谷里,此后外交权自 1879 年条约起归英国管,到 1919 年第三次战争后才完全收回。1979 年底苏联出兵、打死当时的领导人扶自己的人上台,打了十年撤走;此后是军阀内战、1996 年塔利班拿下喀布尔、2001 至 2021 年的美军二十年,四十多年里死了上百万人(数字争议很大)。内陆山国,兴都库什的山口是它的命门,巴达赫尚的青金石四千年前就卖到埃及。' },
{ l:'st', s:'steppe', v:1, n:'现代中亚', k:[[1991,0],[2000,.25],[2025,.3]], b:'独立五国再度成为大国过道与能源要地。',
  e:{ n:'Modern Central Asia', w:'Central Asia', b:'Five states between the powers; the corridor is busy again.', d:'Independent since 1991 and wedged between Russia, China and the West, the region is again a strategic corridor — pipelines and Belt-and-Road freight have made the old passage busy again.', f:{ 'Peak':'after 2000 (oil and gas exports)', 'Center':'Astana, Tashkent', 'Figures':'Nursultan Nazarbayev' } },
  f:{ '鼎盛':'2000年后(油气出口)', '中心':'阿斯塔纳、塔什干', '人物':'纳扎尔巴耶夫' },
  qh:{ born:['独立不是争取来的,是突然到来的','Independence was not won; it simply arrived'],
       rule:['经济先转,政治转得慢得多','The economy turned first; politics much more slowly'],
       money:['咸海几乎干掉,是人为造成的','The Aral Sea almost vanished, and people did it'],
       power:['谁都来往,谁都不完全倒向','Deal with everyone, and lean fully on no one'],
       fall:['一夜之间,从加盟共和国变成主权国家','Overnight, from Soviet republics to sovereign states'],
       legacy:['「算法」这个词,来自这里一个人的名字','The word algorithm comes from a man born here'] },
  q:{ born:['1991年苏联解体,哈萨克斯坦、乌兹别克斯坦、土库曼斯坦、吉尔吉斯斯坦、塔吉克斯坦五国独立。它们的国界是1920至1930年代苏联按民族划定的加盟共和国边界,并非历史上形成的——费尔干纳盆地被三国切开,飞地插花的情况至今仍是纠纷来源。独立不是争取来的,而是随着苏联散架突然到来的。','The Soviet Union dissolved in 1991 and five states became independent: Kazakhstan, Uzbekistan, Turkmenistan, Kyrgyzstan and Tajikistan. Their borders are those the Soviet state drew along national lines in the 1920s and 1930s rather than boundaries formed by history — the Fergana valley is cut between three of them, and the resulting enclaves are still a source of dispute. Independence was not won; it arrived when the union came apart.'],
      rule:['五国走向不同:哈萨克斯坦与乌兹别克斯坦保持强总统制并逐步开放经济;土库曼斯坦长期高度封闭;吉尔吉斯斯坦经历过数次街头政治导致的政权更替;塔吉克斯坦在1992至1997年打了一场内战。共同点是独立初期多由苏联时期的干部继续执政,政治转型普遍慢于经济转型。','The five went different ways: Kazakhstan and Uzbekistan kept strong presidencies while gradually opening their economies; Turkmenistan stayed largely closed; Kyrgyzstan has changed governments several times through street politics; and Tajikistan fought a civil war from 1992 to 1997. What they shared was that officials from the Soviet era mostly stayed in charge at first, and political change generally ran behind economic change.'],
      money:['资源为主:哈萨克斯坦的石油与铀(铀产量居世界第一)、土库曼斯坦的天然气(储量居世界前列)、乌兹别克斯坦的棉花与黄金。苏联时期为种棉花大量引阿姆河与锡尔河的水,导致咸海在几十年内几乎干涸——这是20世纪最严重的人为环境灾难之一,至今仍在影响当地气候与健康。','Resources above all: Kazakh oil and uranium, of which it is the world\'s largest producer; Turkmen natural gas, among the largest reserves anywhere; Uzbek cotton and gold. To grow that cotton the Soviet state diverted the Amu Darya and Syr Darya on a huge scale, and the Aral Sea largely dried up within a few decades — one of the worst man-made environmental disasters of the twentieth century, still affecting the local climate and people\'s health.'],
      power:['位置。它是欧亚大陆的中间地带,历史上是丝路的必经段,今天是中国、俄罗斯、欧洲与南亚之间油气管道与铁路的交汇处。各国普遍采取「多方位外交」——同时与中俄美欧保持关系而不完全倒向任一方,这是体量不占优的国家夹在大国之间的常见策略,在这里做得比较系统。','Position. It is the middle of the Eurasian landmass, historically the unavoidable stretch of the Silk Road and today where pipelines and railways between China, Russia, Europe and South Asia cross. The states generally practise a multi-vector foreign policy — keeping relations with China, Russia, the United States and Europe at once without committing to any — a common strategy for small countries between large ones, pursued here fairly systematically.'],
      fall:['1991年的独立本身就是这一带最近一次大的转折:一夜之间从加盟共和国变成主权国家,原本一体的经济、交通与人员流动被国界切断,工业订单与财政转移同时消失,五国在1990年代普遍经历了产出大幅下滑。此后随着油气出口与对外开放,经济逐步恢复。','Independence in 1991 is itself the region\'s last great turning point: overnight, Soviet republics became sovereign states, an integrated economy and its transport and labour flows were cut by new borders, and industrial orders and budget transfers vanished together. All five went through a steep fall in output through the 1990s, recovering later as energy exports and openness increased.'],
      legacy:['撒马尔罕、布哈拉与希瓦的建筑群是世界文化遗产,今天仍是伊斯兰建筑最完整的实物集合之一。历史上这里是花剌子米(「算法」一词源自他名字的拉丁写法,「代数」源自他那本书名里的 al-jabr)、比鲁尼、伊本·西那的家乡——中世纪伊斯兰科学的核心地带之一。丝绸之路的中段在这里,而今天中欧班列走的仍是大体相同的路线。','The monuments of Samarkand, Bukhara and Khiva are World Heritage sites and remain among the most complete bodies of Islamic architecture standing. This was the homeland of al-Khwarizmi — whose name, in its Latin form, gave us the word algorithm, while algebra comes from the al-jabr in his book\'s title — of al-Biruni and of Ibn Sina, one of the heartlands of medieval Islamic science. The middle stretch of the Silk Road ran through here, and the freight trains between China and Europe today follow much the same line.'] },
  d:'独立后夹在俄、中、西方之间,再度成为地缘要冲;能源管道与"一带一路"的班列,让这条古老的过道重新繁忙起来。' },
/* 南亚 */
{ l:'sa', s:'indic', v:0, n:'印度河文明', k:[[-2600,0],[-2300,.55],[-1900,.25],[-1700,.15],[-1300,0]], b:'哈拉帕与摩亨佐-达罗:规划整齐的排水城市,文字至今未解读。',
  e:{ n:'Indus Valley', w:'Indus Valley Civilisation', b:'Gridded drainage cities; script still undeciphered.', d:'The third great river civilization planned its cities better than anyone: straight streets, household drains — yet almost no palaces, temples or signs of war. Its script remains unread and its decline unexplained.', f:{ 'Peak':'c. 2300 BCE', 'Center':'Harappa, Mohenjo-daro', 'Legacy':'Grid cities, standard weights, drainage' } },
  f:{ '鼎盛':'约前2300年', '中心':'哈拉帕、摩亨佐-达罗', '成就':'网格城市、统一度量衡、排水系统' },
  qh:{ born:['泛滥留下的沃土,加一条通两河的海路','Silt from the flood, and a sea road to Mesopotamia'],
       rule:['没有王陵,没有大神庙,也没有战场','No royal tombs, no great temple, no battlefield'],
       money:['两河的泥板上,提到过一个海外商国','Mesopotamian tablets mention a trading land overseas'],
       power:['统一的砖和砝码,让上百座城像一张网','One brick, one weight, and a hundred towns in one web'],
       fall:['更像慢慢散场,不像一夜崩塌','More a slow dispersal than a sudden collapse'],
       legacy:['不炫耀国王和战争,也繁荣了七百年','It boasted of no kings or wars, and prospered seven centuries'] },
  q:{ born:['印度河每年泛滥留下沃土,养活了南亚最早的城市;这里又坐在通往两河流域的海路上,农业盈余加远程贸易,催生出哈拉帕与摩亨佐-达罗这样规划整齐的大城。','The Indus River\'s yearly floods left rich soil that fed South Asia\'s first cities. Sitting on the sea routes to Mesopotamia, farm surplus plus long-distance trade grew into planned cities like Harappa and Mohenjo-daro.'],
      rule:['我们其实不知道它怎么统治——没有王陵,没有大神庙,几乎没有战争痕迹,这本身就是它最大的谜。可街道笔直,砖块尺寸与度量衡全域统一,说明背后应有某种强有力的协调;是祭司、议事会还是别的什么,要等文字破译那天才知道。','Honestly, we do not know how it was governed — no royal tombs, no grand temples, almost no signs of war, and that is its greatest mystery. Yet streets run straight and bricks and weights follow one standard across the whole region, so some strong coordination existed; whether by priests, councils, or something else, we may only learn when the script is finally read.'],
      money:['农业与手工业打底,远程贸易添彩:小麦大麦棉花养活城市,作坊烧陶器、磨玛瑙珠子;商人带着盖印章的货物远航,两河的泥板提到一个海外商国「麦鲁哈」,一般认为指的就是它。','Farming and craft at the base, long-distance trade on top: wheat, barley, and cotton fed the cities while workshops turned out pottery and carnelian beads. Merchants sailed with sealed goods so far that Mesopotamian tablets mention an overseas trading land called Meluhha — generally thought to be this civilization.'],
      power:['它的强大不靠军队——遗址里几乎找不到武器堆和战火毁灭层;靠的是标准化:统一的砖、统一的砝码、相似的城市模板,让上百座城镇像一张网一样协同运转。','Its strength was not armies — the sites show almost no weapon hoards or destruction layers. It ran on standardization: uniform bricks, uniform weights, and a shared city template that let over a hundred towns work as one network.'],
      fall:['衰落原因尚无定论,主要假说是气候变化与河流改道:季风减弱,支撑农业的河流(如加格尔-哈克拉河)逐渐干涸,大城被一座座放弃,人口散回乡村;没有大火与屠杀的痕迹,更像慢慢散场,而不是一夜崩塌。','No one knows for sure why it declined. The leading hypotheses are climate change and shifting rivers: weakening monsoons and drying rivers such as the Ghaggar-Hakra slowly starved the farms, and the great cities were abandoned one by one as people dispersed into villages — with no traces of fire or slaughter, less a sudden collapse than a slow fade.'],
      legacy:['留下至今无人能读的印章文字,和一套领先世界的城市理念——网格街道、家家接入的排水系统;也留下一个提醒:一个不炫耀国王与战争的文明,同样繁荣了七百年。','It left a script no one can yet read, and city ideas far ahead of their time — grid streets and household drains. It also left a reminder: a civilization that showed off no kings and no wars still thrived for seven hundred years.'] },
  d:'与埃及、两河并立的第三大古文明,城市规划之整齐远超同侪:笔直的街道、家家接入的排水系统;却几乎不见宫殿、神庙与战争的痕迹。其印章文字至今无人解读,衰亡原因(气候变迁?河流改道?)也仍是悬案。' },
{ l:'sa', s:'indic', v:1, n:'吠陀时代', k:[[-1500,0],[-1000,.35],[-600,.4],[-500,0]], b:'说印欧语的人群南下,吠陀经、种姓制度与早期印度教在此成形。',
  e:{ n:'Vedic Age', w:'Vedic period', b:'Indo-European speakers move south; the Vedas, caste and early Hinduism take shape.', d:'Indo-European speakers moved down from Central Asia; the orally transmitted Rigveda is India\'s oldest text. The four-varna hierarchy took shape, Brahmanism spread along the Ganges — and Buddhism and Jainism soon rebelled from this very soil.', f:{ 'Peak':'1000–600 BCE (later Vedic)', 'Center':'Indus–Ganges plains', 'Figures':'Panini', 'Legacy':'The Vedas, Sanskrit, varna system' } },
  f:{ '鼎盛':'前1000—前600年(后期吠陀)', '中心':'印度河—恒河平原', '人物':'波你尼', '成就':'《吠陀经》、梵语、瓦尔纳制度' },
  qh:{ born:['没留下城市,留下的是口传的颂诗','It left no cities, only hymns passed by mouth'],
       rule:['把社会分层,说成是神定的','The social order was declared to be divine'],
       money:['财富按牛算,抢牛就是打仗的理由','Wealth was counted in cattle, and cattle were worth a war'],
       power:['铁斧开林,铁犁翻土,人就聚起来了','Iron axe, iron plough, and the people gathered'],
       fall:['不是灭亡,是转型:部落让位给王国','Not an end but a shift: tribes gave way to kingdoms'],
       legacy:['种姓制度的源头,就在这几百年','The caste system starts in these centuries'] },
  q:{ born:['印度河城市衰落后,说印欧语的游牧人群自中亚分批迁入,与本地居民混居融合;他们没有留下城市,却留下口耳相传的颂诗——《梨俱吠陀》,一个时代因此得名。','As the Indus cities faded, Indo-European-speaking herders migrated in waves from Central Asia and mixed with local peoples. They left no cities, but they left hymns passed down by voice — the Rigveda, which gives the age its name.'],
      rule:['部落首领「罗阇」靠战功与献祭立威,婆罗门祭司垄断通神的仪式;祭司-武士-平民-仆役的四瓦尔纳分层,把社会秩序说成神定的安排——这套解释一旦被接受,统治就不再只靠武力。','Tribal chiefs called rajas won standing through war and sacrifice, while Brahmin priests monopolized the rituals that reached the gods. The four-varna ranking of priest, warrior, commoner, and servant cast the social order as divinely fixed — and once that explanation was accepted, rule no longer rested on force alone.'],
      money:['早期财富按牛计算,抢牛就是战争的常见理由;后期铁器普及,恒河流域的丛林被开成稻田,农业盈余养出集市、城镇与最早铸造的钱币。','Early wealth was counted in cattle — cattle raids were a standard cause of war. Later, iron tools opened the Ganges jungles into rice fields, and farm surplus fed markets, towns, and the first minted coins.'],
      power:['马拉战车是早期的军事王牌;真正改变格局的是铁:铁斧开林,铁犁翻土,人口沿恒河聚成一个个王国,为下一个时代的十六雄国搭好舞台。','The horse-drawn chariot was the early military trump card. What truly changed the game was iron: axes cleared forests, plows broke soil, and populations gathered into Ganges kingdoms — setting the stage for the sixteen great states of the next age.'],
      fall:['与其说灭亡,不如说转型:部落让位于王国,祭祀经济让位于城市与商业;公元前6世纪前后,佛教与耆那教起身挑战婆罗门对真理的垄断,吠陀时代在争鸣声中落幕。','It transformed rather than fell: tribes gave way to kingdoms, the sacrifice economy to cities and commerce. Around the 6th century BCE, Buddhism and Jainism rose to challenge the Brahmin monopoly on truth, and the Vedic age closed amid the debate.'],
      legacy:['梵语与《吠陀经》是印度文明的源代码;瓦尔纳分层演化成影响至今的种姓制度;印度教的神谱与仪轨,大都能追溯回这几百年的颂诗与祭火。','Sanskrit and the Vedas are the source code of Indian civilization. The varna ranks evolved into the caste system that shapes life to this day, and much of Hinduism\'s gods and rites trace back to these centuries of hymn and sacred fire.'] },
  d:'说印欧语的人群自中亚分批南下、与本地居民混居(他们在《梨俱吠陀》里自称 ārya),口耳相传的《梨俱吠陀》是印度最古老的文献;祭司-武士-平民-仆役的四瓦尔纳分层在此定型。婆罗门教沿恒河扩展,而佛教与耆那教,正是稍后从这片土壤中反叛而生。' },
{ l:'sa', s:'indic', v:2, n:'孔雀王朝', k:[[-543,0],[-321,.5],[-261,.9],[-232,.7],[-185,0]], b:'首次统一次大陆;阿育王皈依佛教并向亚洲传法。',
  e:{ n:'Maurya Empire', b:'First unification of the subcontinent; Ashoka sends Buddhism abroad.', d:'Chandragupta unified the north as Alexander withdrew; Ashoka, horrified by the carnage at Kalinga, converted to Buddhism, carved his dharma on pillars across the realm and sent missions as far as the Hellenistic courts and Sri Lanka — Buddhism\'s leap to world religion starts here.', f:{ 'Peak':'Ashoka (268–232 BCE)', 'Center':'Pataliputra', 'Figures':'Chandragupta, Ashoka, Kautilya (Chanakya), Sanghamitta, Mahinda', 'Legacy':'First unification, edict pillars' } },
  f:{ '鼎盛':'阿育王(前268—前232)', '中心':'华氏城', '人物':'旃陀罗笈多、阿育王、考底利耶、桑伽蜜多、摩哂陀', '成就':'首次统一次大陆、石柱敕令' },
  qh:{ born:['次大陆第一次被缝成一个帝国','The subcontinent was stitched into one empire for the first time'],
       rule:['皇帝把话刻在石头上,绕过官员','The emperor cut his words in stone, bypassing officials'],
       money:['一台把全国产出抽进都城的机器','A machine for drawing the whole land into one capital'],
       power:['杀得太狠之后,他改用「法」服人','After the slaughter, he ruled by dharma instead'],
       fall:['靠强人撑起来的帝国,散场也快','An empire held up by one strong man falls apart fast'],
       legacy:['他的狮子柱头,今天印在印度国徽上','His lion capital is on the Indian state emblem today'] },
  q:{ born:['恒河下游的摩揭陀国坐拥沃土、铁矿与水运,本就是列国中的强者;亚历山大退兵在西北留下权力真空,旃陀罗笈多趁势夺取王位、席卷北印,次大陆第一次被缝成一个帝国。','Magadha on the lower Ganges held rich soil, iron mines, and river transport — already the strongest of the warring states. When Alexander\'s withdrawal left a vacuum in the northwest, Chandragupta seized the throne and swept across north India, stitching the subcontinent into one empire for the first time.'],
      rule:['靠一套早熟的官僚机器:分省而治,税吏遍布,据《政事论》描绘还有庞大的密探网络;阿育王更进一步,把「正法」敕令刻上全国的石柱与岩壁——皇帝绕过官员,直接对百姓说话。','Through a precocious bureaucratic machine: provinces, tax officers everywhere, and — as the Arthashastra describes — a vast network of spies. Ashoka went further, carving edicts of dharma onto pillars and rocks across the land: an emperor speaking past his officials, directly to his people.'],
      money:['农业税是命脉:王室主导垦荒,收成抽成归国库;矿山与武器作坊由国家专营,商路税卡一路排到港口——一台把次大陆的产出抽进都城华氏城的财政机器。','The land tax was the lifeline: the crown organized land clearance and took its share of every harvest. Mines and arms workshops were state monopolies, and toll posts lined the trade roads down to the ports — a fiscal machine drawing the subcontinent\'s output into Pataliputra.'],
      power:['先靠武力:据希腊使节记载,孔雀军队有数十万步骑与成群战象;羯陵伽之战杀伤惨重,阿育王转而以「法」服人——修路、建医所、遣使远至希腊化诸国传法,把军事帝国改造成道德帝国的实验场。','First by force: Greek envoys recorded an army of hundreds of thousands with masses of war elephants. After the carnage of Kalinga, Ashoka turned to conquest by dharma — building roads and clinics, sending envoys as far as the Hellenistic courts — remaking a military empire into an experiment in moral empire.'],
      fall:['阿育王身后,帝国在约半个世纪内瓦解:继位者才具平平又屡陷争位,庞大版图仅靠驿道与官僚勉强维系,边省纷纷脱离;约前185年,末代君主死于自己将军之手——靠强人个人撑起的帝国,散场也快。','Within about half a century of Ashoka\'s death the empire unraveled: successors were weak and contested, the vast realm held together only by roads and officials, and border provinces broke away. Around 185 BCE the last king was killed by his own general — an empire carried by strongmen dispersed quickly without one.'],
      legacy:['它证明次大陆可以是一个国家,此后每个立志统一印度的政权都以它为模板;阿育王资助的传法把佛教送出印度,变成世界宗教;他的狮子柱头,今天就印在印度的国徽上。','It proved the subcontinent could be one state, and every later power that dreamed of uniting India worked from its template. Ashoka\'s missions carried Buddhism beyond India into a world religion, and his lion capital stands today on the emblem of the Republic of India.'] },
  d:'旃陀罗笈多趁亚历山大退兵之隙统一北印;阿育王在羯陵伽之战的尸山血海后幡然皈依佛教,把"正法"刻上全国的石柱,并遣使远至希腊化诸国与斯里兰卡传法。佛教从地方教派跃为世界宗教,自此而始。' },
{ l:'sa', s:'indic', v:0, n:'巽伽与恒河诸国', k:[[-185,0],[-150,.22],[-100,.18],[-28,.12],[100,.15],[250,.1],[320,0]], b:'孔雀之后印度五百年没有大帝国,而两大史诗定成文本、波你尼的语法被立为标准、桑奇大塔包上石头,都发生在这几百年里。',
  d:'前 185 年孔雀王朝的末代君主被自己的将领普沙密多罗所杀,巽伽王朝取而代之,但它只守得住恒河中游一带。此后五百年北印度再没有出现统一帝国:巽伽之后是甘婆,西北被印度-希腊人与塞人轮流占着,德干有百乘,恒河下游是一串各管各的小国,直到 320 年笈多兴起。有意思的是,这几百年恰恰是很多东西定型的时候——《摩诃婆罗多》与《罗摩衍那》从口传定成文本,帕坦伽利为波你尼的语法写下《大疏》,把这套规则立成标准,阿育王用砖建的桑奇大塔,在这一时期被包上石头、扩大了一倍,又加了一圈石栏楯;再往后一点,四座满刻本生故事的塔门立了起来——南门的题记留着出钱人的名字:一位娑多迦尼王的工匠首领,和毗底沙的象牙工匠行会。没有皇帝的年代,反而把话说定了。',
  e:{ n:'Shungas and the Ganges States', w:'Shunga Empire', b:'India had no empire for five centuries after the Mauryas — and it was in exactly those centuries that the two epics were fixed in text, Panini\'s grammar was established as the standard, and the great stupa at Sanchi was cased in stone.', d:'In 185 BC the last Mauryan king was killed by his own general Pushyamitra, who founded the Shunga dynasty — but it held little more than the middle Ganges. For five centuries afterwards no empire united north India: the Shungas gave way to the Kanvas, the northwest passed between Indo-Greeks and Sakas, the Deccan belonged to the Satavahanas, and the lower Ganges was a string of small states, until the Guptas rose in 320. What is striking is that these same centuries fixed a great deal in place: the Mahabharata and Ramayana settled from oral performance into text, Patanjali wrote his great commentary on Panini\'s grammar, establishing it as the standard, the brick stupa Ashoka had built at Sanchi was cased in stone, doubled in size and ringed with a carved stone railing, and a little later acquired the four gateways it is known for — whose inscriptions name the donors: a foreman of king Satakarni\'s craftsmen, and the ivory-workers\' guild of Vidisha. An age without an emperor was the age that settled what would be said.', f:{ 'Peak':'early Shunga (185—150 BC)', 'Center':'Pataliputra; Vidisha', 'Figures':'Pushyamitra Shunga; Patanjali', 'Legacy':'The stone railings of Sanchi; the epics fixed in text' } },
  f:{ '鼎盛':'巽伽前期(前185—前150)', '中心':'华氏城、毗底沙', '人物':'普沙密多罗·巽伽、帕坦伽利', '成就':'桑奇的石栏楯、两大史诗定型' },
  qh:{ born:['将军杀了自己的王,接手了剩下的地盘','A general killed his king and took what was left'],
       rule:['谁也统不了全印度,于是各管各的','No one could rule all India, so each ruled his own'],
       money:['商路还在走,只是过路要交好几道税','The trade roads still ran — through several tollgates now'],
       power:['没有大帝国,也就没有一场决定性的战争','No empire meant no decisive war either'],
       fall:['笈多从这一带起来,重新把北印缝上','The Guptas rose here and sewed the north back together'],
       legacy:['没有皇帝的年代,反而把话说定了','The age without an emperor is the age that fixed the words'] },
  q:{ born:['前 185 年,孔雀王朝的末代君主在阅兵时被自己的总司令普沙密多罗杀死,巽伽王朝由此开始。但新王朝远没有前朝的规模:它守着恒河中游与马尔瓦一带,再往西是印度-希腊人,再往南是百乘,再往东是一串小国。一个靠强人撑起来的帝国散场之后,填进来的是许多个中等大小的政权。','In 185 BC the last Mauryan king was killed at a military review by his own commander-in-chief, Pushyamitra, and the Shunga dynasty began. It was nothing like its predecessor in scale: it held the middle Ganges and Malwa, with Indo-Greeks to the west, Satavahanas to the south and a string of small states to the east. When an empire held together by strong men broke up, what filled the space was a set of middling powers.'],
      rule:['这五百年北印度的常态是并立而不是统一。巽伽之后是甘婆,西北在印度-希腊人与塞人之间反复易手,恒河下游各城各自为政。中央权力弱下去之后,真正维持秩序的是村社、行会与神庙——这套东西不随王朝更替而变,后来成了印度社会的底盘。','For these five centuries north India was normally divided rather than united. The Kanvas followed the Shungas, the northwest passed back and forth between Indo-Greeks and Sakas, and the cities of the lower Ganges went their own ways. With central power weak, order rested on villages, guilds and temples — an arrangement that outlasted every dynasty and became the underlying structure of Indian society.'],
      money:['恒河仍是印度最好的一条运输线,从华氏城到河口的商路没有断;变化是过路要交好几道税,因为沿途换了好几家。这一时期铸币的政权特别多,考古学家靠钱币把这几百年的小王朝一个个排出来。对外贸易也旺:罗马的金币经海路进入南印与德干,象牙、棉布、香料反向出去。','The Ganges was still the best transport line in India and the road from Pataliputra to the delta never closed; what changed is that it now ran through several tollgates, because several powers held stretches of it. An unusual number of these states struck coins, and archaeologists have reconstructed the small dynasties of these centuries largely from coinage. Foreign trade was brisk too: Roman gold came by sea into the south and the Deccan, with ivory, cotton and spices going the other way.'],
      power:['没有统一帝国,也就没有一场决定性的战争。巽伽与西北的印度-希腊人打过,与南边的百乘也有摩擦,但谁都没有能力吞掉对方。这几百年真正的变化不在战场上:佛教与耆那教得到商人阶层的大量捐助,石窟与佛塔沿着商路一座座建起来——出钱的往往不是国王,而是行会与商队。','With no empire there was no decisive war. The Shungas fought the Indo-Greeks in the northwest and rubbed against the Satavahanas in the south, but none could finish another. The real change of these centuries was not on the battlefield: Buddhism and Jainism drew heavy patronage from merchants, and rock-cut monasteries and stupas went up along the trade roads one after another — funded not usually by kings but by guilds and caravan owners.'],
      fall:['3 世纪末 4 世纪初,摩揭陀又一次成为起点:旃陀罗笈多一世在华氏城一带崛起,与离车族联姻取得势力,320 年建立笈多王朝,几十年间把北印度重新缝成一片。五百年的分立就此结束,而这次统一起来的国家,文化上继承的正是分立时代攒下的那些东西。','At the turn of the fourth century Magadha became the starting point once again: Chandragupta I rose around Pataliputra, gained strength through a marriage alliance with the Licchavis, founded the Gupta dynasty in 320 and within decades had sewn north India back together. Five centuries of division ended — and what the new empire inherited culturally was precisely what the divided centuries had accumulated.'],
      legacy:['这几百年攒下的东西比政治史多得多。《摩诃婆罗多》与《罗摩衍那》在此期间从口头表演定成文本,今天读到的规模大体是那时候的;帕坦伽利为波你尼那部语法写下《大疏》——波你尼用不到四千条规则写完了梵语的语法(站内他挂在吠陀时代那条带上),而帕坦伽利这部注疏把它立成了标准,此后两千年梵语的写法几乎没有再变。阿育王在桑奇建的是一座砖塔,巽伽时期给它包上石头、扩大一倍、加了一圈石栏楯;四座满刻本生故事的塔门立得更晚一些,南门的题记写着出钱的人——一位娑多迦尼王的工匠首领,和毗底沙的象牙工匠行会。今天去桑奇看的,主要就是这几座门与这圈栏楯。一个没有皇帝的时代,把这个文明后来要说的话，先定了下来。','These centuries left far more than political history. The Mahabharata and the Ramayana settled from oral performance into written text, at roughly the length read today; Patanjali wrote his great commentary on Panini — Panini had written the whole grammar of Sanskrit in fewer than four thousand rules (this site places him on the Vedic band) — and the commentary made that grammar the standard, after which the language barely changed in two thousand years. What Ashoka raised at Sanchi was a brick stupa; the Shunga period cased it in stone, doubled its size and ringed it with a carved railing. The four gateways, covered with birth-stories of the Buddha, went up somewhat later, and their inscriptions name who paid: a foreman of king Satakarni\'s craftsmen, and the ivory-workers\' guild of Vidisha. Those gateways and that railing are the main thing visitors come to see. An age without an emperor set down what this civilization would go on saying.'] } },
{ l:'sa', s:'indic', v:1, n:'百乘王朝', k:[[-230,0],[-100,.3],[100,.45],[220,0]], b:'德干高原的第一个大帝国,一手连北印、一手连罗马海商。',
  e:{ n:'Satavahana Empire', w:'Satavahana dynasty', b:'The Deccan\'s first great empire — north India in one hand, Roman shipping in the other.', d:'After the Mauryas collapsed, this Brahmin dynasty rose on the Deccan plateau and filled a four-century gap between north and south. It held one hand out to the Ganges kingdoms and the other to Rome\'s Indian Ocean trade — most of the Roman gold coins dug up in south India belong to this era. The court funded Brahmin sacrifice and endowed Buddhist monasteries at the same time; the reliefs of the Amaravati stupa, soft and flowing, are a strand of Buddhist art quite separate from Gandhara.', f:{ 'Peak':'early 2nd c.', 'Center':'Pratishthana, later Amaravati', 'Figures':'Gautamiputra Satakarni', 'Legacy':'The Amaravati stupa; India\'s earliest lead coinage' } },
  f:{ '鼎盛':'2世纪初', '中心':'普拉蒂什塔纳→阿马拉瓦蒂', '人物':'乔达米普特拉·娑多迦尼', '成就':'阿马拉瓦蒂大塔、大量铸行的铅币' },
  qh:{ born:['把一个过道位置,经营成四百年帝国','It made a corridor into a four-hundred-year empire'],
       rule:['祭婆罗门,也供佛教,两头下注','It backed the brahmins and the Buddhists both'],
       money:['南印出土的罗马金币,多半是这时候的','Most Roman coins found in the south date from here'],
       power:['一度大破塞人,把王朝推上顶峰','It broke the Saka once, and reached its height'],
       fall:['中央一弱,总督们就各自称王','The centre weakened, and the governors crowned themselves'],
       legacy:['阿马拉瓦蒂的浮雕,自成一个流派','The Amaravati reliefs became a school of their own'] },
  q:{ born:['孔雀王朝崩溃后,德干高原出现权力空档;本地的婆罗门家族乘势立国,卡在北印与南印之间的通道上,把「过道位置」经营成四百年的帝国。','When the Mauryan empire collapsed, a power gap opened on the Deccan plateau. A local Brahmin family built a kingdom astride the corridor between north and south India, turning a passageway position into an empire of four centuries.'],
      rule:['王室两头下注:以婆罗门祭祀确立正统,同时大笔布施佛教僧团,笼络商人信众;地方交给王族与总督分治——这套松散结构平时省力,末期却成了裂解的伏笔。','The court hedged both ways: Vedic sacrifices secured legitimacy while lavish gifts to Buddhist monasteries won over merchant communities. The provinces were left to princes and governors — a loose structure cheap to run in good times, and the seed of breakup at the end.'],
      money:['吃的是商路饭:西海岸港口对接罗马的印度洋航线,胡椒、棉布、宝石换回罗马金币——南印出土的罗马钱币多半属于这个时代;境内商路收税,还大量铸行铅币,是印度铅币最主要的发行者。','It lived off the trade roads: west-coast ports linked to Rome\'s Indian Ocean shipping, trading pepper, cotton, and gems for Roman gold — most Roman coins unearthed in south India date to this era. Internal routes paid tolls, and the dynasty struck India\'s earliest lead coins.'],
      power:['强在扼守山口与商道,商队绕不开它;军事上与西北的塞人政权(西萨特拉普)反复拉锯,乔达米普特拉·娑多迦尼一度大破对手,把王朝推上顶峰。','Its strength lay in holding the passes and roads no caravan could avoid. Militarily it wrestled for generations with the Saka rulers to the northwest, and Gautamiputra Satakarni\'s crushing victories pushed the dynasty to its peak.'],
      fall:['多因叠加:与塞人政权的长期拉锯消耗国力;辽阔版图靠总督分治,中央一弱,阿毗罗、伊克什瓦库等地方势力便相继自立;3世纪初,帝国裂成数个继承国,德干重回列国状态。','Causes stacked up: the long seesaw war with the Sakas drained the state, and the sprawling realm ran on delegated governors — so when the center weakened, regional houses like the Abhiras and Ikshvakus broke away one after another. By the early third century the empire had split into successor states and the Deccan returned to a patchwork of kingdoms.'],
      legacy:['它第一次把德干组织成政治整体,此后的南印大国都走在它踩出的路上;阿马拉瓦蒂大塔的浮雕自成一派,与犍陀罗、秣菟罗并列为印度佛教艺术的几大流派,影响随海路远及斯里兰卡与东南亚。','It organized the Deccan into a political whole for the first time, and later southern powers walked the roads it laid. The reliefs of the Amaravati stupa founded a school of Buddhist art to stand beside Gandhara, its influence sailing with the monks to Sri Lanka and Southeast Asia.'] },
  d:'孔雀王朝崩溃后,德干高原上崛起的婆罗门王朝,填住了北印与南印之间四百年的空档。它一手连着恒河流域诸国,一手连着罗马的印度洋航线——南印出土的罗马金币多半属于这个时代。王室供养婆罗门祭祀,同时大笔布施佛教僧团;阿马拉瓦蒂大塔的浮雕柔软流动,是犍陀罗之外另一支佛教艺术源流。' },
{ l:'sa', s:'west', v:0, n:'印度-希腊诸王', k:[[-250,0],[-190,.18],[-160,.28],[-140,.35],[-100,.22],[-50,.12],[10,0]], b:'亚历山大留下的希腊人在这里当了两百年国王;今天我们认识他们,几乎全靠他们留下的钱币。',
  d:'亚历山大在旁遮普的比阿斯河边被自己的军队逼得折返,他留在巴克特里亚的希腊移民却住了下来,前 3 世纪中叶脱离塞琉古自立。前 180 年前后这些人翻过兴都库什山南下,取下犍陀罗与旁遮普——这是希腊人在离家最远的地方建起的国家。他们的钱币一面刻希腊文、一面刻佉卢文,国王供养佛教僧团;《弥兰陀王问经》记下了米南德王与那先比丘的一场问答。三十多位国王里,大部分的名字只出现在钱币上,任何一部史书都没有写过他们。',
  e:{ n:'Indo-Greek Kingdoms', w:'Indo-Greek Kingdom', b:'Greeks left behind by Alexander ruled here for two centuries — and we know almost all of them only from their coins.', d:'Alexander turned back at the Hyphasis in the Punjab, but the Greek settlers he left in Bactria stayed and eventually broke away from the Seleucids. Around 180 BC their armies crossed the Hindu Kush and took Gandhara and the Punjab, founding the furthest-flung Greek states the ancient world produced. Their kings struck coins bearing Greek titles on one face and Kharoshthi on the other, endowed Buddhist monasteries, and left in the Milinda Panha a record of King Menander questioning the monk Nagasena. More than thirty of these kings are known from nothing whatever but their coinage.', f:{ 'Peak':'Menander I (c. 155—130 BC)', 'Center':'Taxila; Sagala', 'Figures':'Menander I (Milinda)', 'Legacy':'Bilingual coinage; the Milinda Panha' } },
  f:{ '鼎盛':'米南德一世(约前155—前130)', '中心':'塔克西拉、舍羯罗', '人物':'米南德一世(弥兰陀王)', '成就':'双语钱币、《弥兰陀王问经》' },
  qh:{ born:['亚历山大走了,他的兵留下来了','Alexander left; his soldiers stayed'],
       rule:['同一个名字,正面希腊文,背面印度文','The same name — Greek on one side, Indian on the other'],
       money:['钱铸得好,后来取代他们的人照着做','Their coin was good, and those who replaced them copied it'],
       power:['一度打到恒河边,又退了回来','They reached the Ganges once, then fell back'],
       fall:['没有输掉哪一场大战,是被慢慢挤没的','No great defeat — they were simply squeezed out'],
       legacy:['一位希腊国王问「到底是谁在轮回」,问出了一部经','A Greek king\'s question became a Buddhist scripture'] },
  q:{ born:['亚历山大一路打到旁遮普的比阿斯河边,军队不肯再往前,他只好折返;而他留在巴克特里亚(今阿富汗北部)的希腊移民住了下来。他在回程路上围攻过的桑加拉,后来正是米南德王的都城。前 3 世纪中叶他们脱离塞琉古自立;前 180 年前后,他们的军队翻过兴都库什山南下,取下犍陀罗与旁遮普——这是希腊人在离家最远的地方建起的国家。','Alexander pushed as far as the Hyphasis in the Punjab, where his army refused to go further and he turned back; the Greek settlers he had left in Bactria — today\'s northern Afghanistan — stayed on. In the mid-third century BC they broke away from the Seleucids, and around 180 BC their armies crossed the Hindu Kush and took Gandhara and the Punjab. These were the furthest-flung states the Greek world ever produced.'],
      rule:['他们是统治印度人的外来少数,做法是两边都认:钱币正面刻国王的希腊文名号与头像,背面刻同一个名号的印度文字(佉卢文);国王供养佛教僧团,也接受本地的神。不去强行改造别人,而是把自己翻译成当地读得懂的样子。','They were a foreign minority ruling Indians, and their answer was to be legible on both sides: a king\'s coin carried his portrait and Greek titles on one face, the same titles in Kharoshthi on the other. Kings endowed Buddhist monasteries and accepted local gods. Rather than remake their subjects, they translated themselves into something their subjects could read.'],
      money:['底牌是位置:北通中亚草原,西接波斯与地中海,南下印度河出海,三个方向的货都要从这里过。他们铸的钱成色稳、样式固定,在西北印度通行了几百年——连后来取代他们的贵霜人,也照着这套样式铸自己的钱。','Their asset was position: the steppe to the north, Persia and the Mediterranean to the west, the Indus running down to the sea in the south — goods from all three had to pass through. Their coinage held its weight and its design, circulated in the northwest for centuries, and was copied by the Kushans who eventually replaced them.'],
      power:['最强的是米南德一世,据记载他的军队一度东进到恒河流域。但这些王国从来没有真正合成一个:同一时期常有好几位国王各据一方、互相攻打——所以钱币上留下三十多个名字,而其中大部分在任何一部史书里都找不到。','Menander I was the strongest; his armies are said to have pushed east into the Ganges plain. But these kingdoms never became a single state — several kings often ruled at once and fought each other. That is why more than thirty names survive on coins while most of them appear in no written history at all.'],
      fall:['塞人(斯基泰的一支)先从北边南下,月氏人随后跟上,一块一块把他们挤掉。最后一位留下名字的国王在公元前 10 年前后消失。他们不是被哪一场大战打垮的,是被慢慢挤没的。','The Sakas, a branch of the Scythians, came down from the north first and the Yuezhi followed, taking their land piece by piece. The last king to leave a name disappears around 10 BC. No single battle finished them; they were squeezed out.'],
      legacy:['最大的遗产不在土地上,而在一场对话里。《弥兰陀王问经》记下米南德王与那先比丘的问答:国王一遍遍追问「既然没有一个不变的我,那到底是谁在轮回」,僧人指着国王自己的马车反问回去。这是希腊式的追问与印度佛法第一次正面碰上,而把它记下来的是佛教那一方。希腊的雕刻手法也留在了这一带,几百年后成为犍陀罗佛像的来源之一。','The largest legacy is not territorial but a conversation. The Milinda Panha records King Menander questioning the monk Nagasena: if there is no unchanging self, then who exactly is it that is reborn? The monk answers by pointing at the parts of the king\'s own chariot.'] } },
{ l:'sa', s:'steppe', v:0, n:'贵霜帝国', k:[[30,0],[100,.5],[200,.45],[375,0]], b:'大月氏人所建,丝路十字路口;犍陀罗艺术融希腊与佛教。',
  e:{ n:'Kushan Empire', b:'Steppe-born lords of the Silk Road crossroads; the earliest Buddha images.', d:'The Yuezhi, pushed out by the Xiongnu, built an empire at the Silk Road\'s crossroads and grew rich on it; under Kanishka\'s patronage the Buddha began to be shown in human form — at Gandhara and at Mathura almost at once, with no settled answer as to which came first, and both inside this Greco-Indo-steppe hybrid.', f:{ 'Peak':'Kanishka (2nd c.)', 'Center':'Peshawar', 'Figures':'Kanishka I', 'Legacy':'Gandhara art, Silk Road hub' } },
  f:{ '鼎盛':'迦腻色伽(2世纪初)', '中心':'白沙瓦', '人物':'迦腻色伽一世', '成就':'犍陀罗佛像艺术、丝路枢纽' },
  qh:{ born:['被挤出来的人,落在了十字路口上','Pushed out of their land, they landed on a crossroads'],
       rule:['钱币上,希腊神和佛陀轮番出现','Greek gods and the Buddha took turns on the coins'],
       money:['货币本身,就是一份招商广告','The coinage itself was an advertisement for trade'],
       power:['草原骑兵,加一个换不掉的位置','Steppe cavalry, plus a position no one could replace'],
       fall:['西边被萨珊夺城,东边属地渐次脱离','Persia took the west; the eastern lands slipped away'],
       legacy:['佛教北传中国,走的是它的驿站','Buddhism travelled to China along its relay stations'] },
  q:{ born:['一场草原上的连锁挤压:大月氏人被匈奴逐出河西走廊,西迁中亚;五部之中的贵霜部统一诸部,翻过兴都库什山南下,恰好落在丝绸之路与印度商路的十字路口上。','A chain reaction on the steppe: the Yuezhi, driven from the Gansu corridor by the Xiongnu, migrated into Central Asia. The Kushan clan united the five tribes and crossed the Hindu Kush — landing exactly on the crossroads of the Silk Road and the routes into India.'],
      rule:['统治的诀窍是「都认」:君主自称「万王之王」,钱币上希腊神、波斯神、印度神与佛陀轮番出现;不强迫改宗,不独尊一教,让希腊城民、印度信众与草原部众各拜各的神、共交一份税。','The trick of rule was to endorse everyone: the kings styled themselves King of Kings, and their coins carried Greek, Persian, and Indian gods and the Buddha in turn. No forced conversion, no single creed — Greek townsmen, Indian devotees, and steppe clansmen each kept their gods and all paid the same taxes.'],
      money:['赚的是过路钱:中国的丝绸、罗马的金币、印度的香料与宝石都要经它的地盘换手;它仿照罗马金币的成色铸金币,让商队在整个帝国用一种钱结账——货币本身就是招商广告。','It earned the toll of passage: Chinese silk, Roman gold, Indian spices and gems all changed hands on its ground. It struck gold coins matched to the Roman standard so caravans could settle accounts in one currency across the realm — the coinage itself was an advertisement for doing business there.'],
      power:['底子是草原骑兵,位置是无可替代的商路枢纽,两样加起来就是国力;迦腻色伽时代版图与声望俱达顶峰,他资助佛教结集与寺院,把宗教影响力也变成帝国资产。','The base was steppe cavalry; the position was an irreplaceable trade hub — together they made national power. Under Kanishka the empire peaked in reach and prestige, and his patronage of Buddhist councils and monasteries turned religious influence into an imperial asset as well.'],
      fall:['多因叠加:3世纪新兴的萨珊波斯自西面反复进攻,夺走中亚重镇;印度一侧的属地渐次脱离,后来又受笈多势力挤压;帝国裂成若干小邦,分头存续到4世纪后被逐一吞并。','Causes stacked: from the west the rising Sasanian Persia attacked repeatedly and seized the Central Asian strongholds, while the Indian territories slipped away and were later squeezed by the Guptas. The empire fractured into petty kingdoms that lingered into the fourth century before being swallowed one by one.'],
      legacy:['最大的遗产是佛像:最早的一批佛陀造像出自贵霜治下的犍陀罗与秣菟罗两地,前者带希腊雕塑的手法,后者是印度本土路数;它扼守的通道也是佛教北传之路——经中亚进入中国的佛法,走的正是贵霜的驿站。','Its greatest legacy is the Buddha image: the earliest of them came from Gandhara and Mathura, both under Kushan rule — the first in a Greek manner, the second in a wholly Indian one. Its corridors were also Buddhism\'s road north — the dharma that reached China through Central Asia traveled by Kushan way stations.'] },
  d:'被匈奴挤走的大月氏人辗转中亚建国,扼丝路十字路口而暴富;迦腻色伽护法,佛陀开始有了人的形象——犍陀罗与秣菟罗几乎同时,谁先谁后至今没有定论,而两地都在这个希腊、印度与草原的混血帝国之内。' },
{ l:'sa', s:'indic', v:2, n:'伐卡塔卡与德干诸国', k:[[220,0],[300,.2],[400,.26],[470,.3],[520,.2],[550,0]], b:'百乘之后的德干:一位笈多公主嫁过来,丈夫早死,她替儿子摄政二十年;阿旃陀最好的那批洞窟,就凿在这个王朝手里。',
  d:'220 年百乘王朝解体后,德干高原换成几家并立:中部是伐卡塔卡,西北沿海是塞人后裔的西萨特拉普,南边是卡丹巴与西恒伽。伐卡塔卡是其中分量最重的一支,它与北方的笈多王朝长期联姻——笈多王旃陀罗笈多二世把女儿普拉巴瓦蒂古普塔嫁了过来,丈夫早逝后她替年幼的儿子摄政约二十年,以笈多公主的身份实际治理德干。这几百年最看得见的产物是阿旃陀石窟:第一批洞窟早在公元前就开凿了,而壁画最精美的第二期,是 5 世纪后期在伐卡塔卡王哈里塞纳手里完成的。550 年前后遮娄其(巴达米)在这一带兴起,德干进入下一个时代。',
  e:{ n:'Vakatakas and the Deccan States', w:'Vakataka dynasty', b:'The Deccan after the Satavahanas — a Gupta princess ruled it for twenty years, and the finest caves at Ajanta were cut under this dynasty.', d:'When the Satavahana empire broke up around 220, the Deccan passed to several powers at once: the Vakatakas in the centre, the Western Kshatrapas — descendants of Saka rulers — along the northwest coast, and the Kadambas and Western Gangas to the south. The Vakatakas were the weightiest of them, and married repeatedly into the Gupta house to the north: Chandragupta II gave his daughter Prabhavatigupta in marriage here, and when her husband died young she governed as regent for her small sons for about twenty years — a Gupta princess effectively ruling the Deccan. The most visible product of these centuries is Ajanta: the earliest caves there were cut centuries BC, but the second phase, the one with the great paintings, was completed in the late fifth century under the Vakataka king Harishena. Around 550 the Chalukyas of Badami rose here and the Deccan entered its next age.', f:{ 'Peak':'Harishena (c. 460—480)', 'Center':'Nandivardhana; Vatsagulma', 'Figures':'Prabhavatigupta; Harishena', 'Legacy':'The second phase of Ajanta; the Gupta-Vakataka marriage tie' } },
  f:{ '鼎盛':'哈里塞纳(约460—480)', '中心':'那格尔达纳、瓦茨古尔马', '人物':'普拉巴瓦蒂古普塔、哈里塞纳', '成就':'阿旃陀第二期石窟、笈多与伐卡塔卡的联姻' },
  qh:{ born:['百乘散了,德干换成几家并立','The Satavahanas broke up; several powers shared the Deccan'],
       rule:['一位笈多公主替儿子管了德干二十年','A Gupta princess ran the Deccan for twenty years'],
       money:['棉花与铁,还有绕不开的两条山口','Cotton and iron — and two passes no one could avoid'],
       power:['靠联姻结盟,不靠一场决战','Held together by marriage, not by one decisive battle'],
       fall:['遮娄其从南边起来,接手了这片高原','The Chalukyas rose from the south and took the plateau'],
       legacy:['阿旃陀壁画上的脸,是这时候画的','The faces on the Ajanta walls were painted in these years'] },
  q:{ born:['220 年前后百乘王朝解体,德干没有再出现一个统一政权,而是几家并立:中部与东部是伐卡塔卡,西北沿海是塞人后裔的西萨特拉普,南边是卡丹巴与西恒伽。北印度这时正由笈多王朝统一,而德干走的是另一条路——这片高原此后一千年的常态,就是南北各有强邦、谁也压不倒谁。','Around 220 the Satavahana empire broke up, and no single power replaced it on the Deccan: the Vakatakas held the centre and east, the Western Kshatrapas — descended from Saka governors — the northwest coast, the Kadambas and Western Gangas the south. North India was being united by the Guptas at just this time, while the Deccan went the other way. That became the plateau\'s normal condition for the next thousand years: strong states north and south, neither able to hold the other down.'],
      rule:['伐卡塔卡的办法是联姻而不是征服。笈多王旃陀罗笈多二世把女儿普拉巴瓦蒂古普塔嫁到这里,她的丈夫早逝,她便以太后身份替年幼的儿子摄政约二十年——她发出的铜板敕令,开头列的是娘家笈多的祖宗谱,而不是夫家的。一位北方公主,实际统治了南方这片高原二十年,而两个王朝谁也没有吞掉谁。','The Vakataka method was marriage rather than conquest. Chandragupta II of the Guptas gave his daughter Prabhavatigupta in marriage here; her husband died young and she governed as regent for her small sons for about twenty years — issuing copper-plate grants in her own name, and opening them with her father\'s Gupta lineage rather than her husband\'s. A princess from the north effectively ruled this southern plateau for two decades, and neither dynasty swallowed the other.'],
      money:['德干高原的黑土适合种棉花,山里有铁矿,而真正值钱的是位置:从北印度下到南印度、从西海岸的港口进内陆,商队都要走西高止山的几条山口。伐卡塔卡与西萨特拉普各据一头,前者守内陆通道,后者握着阿拉伯海的港口——这也是笈多后来一定要南下打西萨特拉普的原因。','The black soil of the plateau suits cotton, the hills hold iron, and what really paid was position: caravans going from north India to the south, or inland from the west-coast ports, had to use a handful of passes through the Western Ghats. The Vakatakas held the inland routes and the Kshatrapas the Arabian Sea harbours — which is why the Guptas eventually came south to break the latter.'],
      power:['这几百年德干没有打出过一场决定性的大战。各家靠联姻、结盟与承认对方的地盘维持均势:伐卡塔卡与笈多是姻亲,与南边的卡丹巴、西恒伽多半相安。真正改变格局的不是战争,是 4 世纪末笈多灭掉西萨特拉普——西海岸的港口从此归了北方。','No decisive battle was fought on the Deccan in these centuries. The powers held their balance by marriage, alliance and mutual recognition of territory: the Vakatakas were in-laws to the Guptas and mostly at peace with the Kadambas and Western Gangas to the south. What changed the picture was not a war here but the Gupta destruction of the Western Kshatrapas at the end of the fourth century, which handed the west-coast ports to the north.'],
      fall:['6 世纪初伐卡塔卡的两支先后断绝,德干重新碎开;550 年前后遮娄其家族从南边的巴达米一带起来,逐步统一高原西部,并与南方的帕拉瓦长期争锋。这片高原的主角换了人,而分立的格局没有变。','The two Vakataka branches died out early in the sixth century and the Deccan fragmented again. Around 550 the Chalukya family rose from Badami in the south, gradually unified the western plateau and settled into a long rivalry with the Pallavas further south. The plateau changed protagonists; its habit of division did not.'],
      legacy:['阿旃陀石窟的第一批洞窟早在公元前就凿好了,而壁画最精美的第二期,是 5 世纪后期在伐卡塔卡王哈里塞纳手里完成的——今天挂在世界各地画册上的那些脸,大多来自这一批。这些洞窟在 6 世纪之后被森林盖住,直到 1819 年一队英国军官打猎时偶然发现。这一段德干的历史几乎没有留下史书,靠的是石头上刻的敕令、铜板上写的赠地文书,和洞窟墙上的画。','The first caves at Ajanta were cut centuries before Christ, but the second phase — the one with the great paintings — was completed in the late fifth century under the Vakataka king Harishena; most of the faces reproduced in art books around the world come from that campaign. The caves were swallowed by forest after the sixth century and were found again only in 1819, by British officers out hunting. Almost no chronicle survives from this Deccan age: what we know rests on edicts cut in stone, land grants written on copper plates, and the paintings on those cave walls.'] } },
{ l:'sa', s:'indic', v:0, n:'笈多王朝', k:[[320,0],[380,.7],[450,.75],[550,0]], b:'印度古典黄金时代:梵语文学、数字"零"与十进制。',
  e:{ n:'Gupta Empire', b:'India\'s classical golden age: Sanskrit letters, zero and decimals.', d:'Classical Hindu culture crystallized here: Kalidasa\'s drama, Aryabhata\'s astronomy and mathematics; zero and decimal notation traveled west via the Arabs to become humanity\'s arithmetic — perhaps India\'s greatest gift. The White Huns broke the empire and India returned to its many kingdoms.', f:{ 'Peak':'Chandragupta II (380–415)', 'Center':'Pataliputra', 'Figures':'Kalidasa, Aryabhata, Chandragupta II, Vasubandhu', 'Legacy':'Zero & decimals, classical Sanskrit literature' } },
  f:{ '鼎盛':'超日王(380—415)', '中心':'华氏城', '人物':'迦梨陀娑、阿耶波多、旃陀罗·笈多二世、世亲', '成就':'"零"与十进制、梵语古典文学' },
  qh:{ born:['起点和孔雀王朝,是同一片地方','It rose from the same ground as the Mauryas'],
       rule:['粘住各地贵族的不是税吏,是同一套经典','Not tax men but a shared canon held the nobles together'],
       money:['铸得极精的金币,就是国库的底气','Finely struck gold coins were the treasury speaking'],
       power:['不开战也能让人跟着学,这就是力量','Others copied it without a war, and that was the strength'],
       fall:['外敌来了几次,国库就打空了','A few invasions, and the treasury was empty'],
       legacy:['「零」和十进制,成了全人类的算术底座','Zero and decimal notation became the arithmetic of all'] },
  q:{ born:['贵霜衰落后北印重回碎片,笈多家族从摩揭陀老根据地起家——与孔雀王朝同一片起点;旃陀罗·笈多一世靠联姻立足,其子沙摩陀罗笈多南征北讨,把恒河流域重新缝成帝国。','After the Kushan decline, north India fell back into fragments. The Gupta family rose from Magadha — the same cradle that launched the Mauryas: Chandragupta I gained his footing through marriage alliance, and his son Samudragupta\'s campaigns stitched the Ganges basin back into an empire.'],
      rule:['比孔雀松得多:核心区直辖,外围让战败的王公继续在位、纳贡称臣;真正把精英粘在一起的是梵语宫廷文化——同一套经典、诗歌与礼仪,比税吏更能让各地贵族认同这个帝国。','Far looser than the Mauryas: the core was ruled directly, while defeated kings kept their thrones as tribute-paying vassals. What truly bonded the elite was Sanskrit court culture — a shared canon of classics, poetry, and ritual that won over regional nobles more surely than tax collectors could.'],
      money:['恒河农业的田赋打底,海陆贸易添彩:西港通波斯与地中海世界,东岸连东南亚;铸工精美的笈多金币,是国库底气的直接物证。','Land tax from Ganges agriculture formed the base, with trade as the bonus: western ports reached Persia and Rome, the east coast linked to Southeast Asia. The finely struck Gupta gold coinage stands as direct evidence of the treasury\'s strength.'],
      power:['军事上南征北讨,更靠文化辐射:天文、数学、医学、文学在此汇成古典范式,周边王国主动学它的文字、拜它的神、仿它的宫廷——不必开战就赢得认同的软实力。','Alongside campaigns in every direction, its real reach was cultural: astronomy, mathematics, medicine, and literature crystallized here into a classical paradigm, and neighboring kingdoms voluntarily adopted its script, its gods, and its court style — soft power that won allegiance without war.'],
      fall:['多因叠加:5世纪后期起,白匈奴(嚈哒)自西北反复入侵,战争开销掏空国库;外围附庸本就只是纳贡关系,见中央疲弱便相继自立;帝国收缩回摩揭陀一隅,约550年后名存实亡。','Causes stacked: from the late fifth century the Hephthalites (White Huns) invaded again and again from the northwest, and the cost of war drained the treasury. The outer vassals, bound only by tribute, broke away as the center weakened, and the empire shrank back to Magadha, effectively ending around 550.'],
      legacy:['「零」与十进制记数法在此成形,经阿拉伯学者西传,成为全人类的算术底座;加上迦梨陀娑的梵语文学与定型的印度教神庙范式,后世把这两个多世纪称作印度的古典黄金时代。','The zero and the decimal place-value system took shape here and traveled west through Arab scholars to become the arithmetic bedrock of all humanity. With Kalidasa\'s Sanskrit classics and the settled template of the Hindu temple, later ages named these three centuries India\'s classical golden age.'] },
  d:'印度教古典文化在此定型:迦梨陀娑的戏剧、阿耶波多的天文与数学;"零"与十进制记数法经阿拉伯人西传,成为全人类的算术底座——这可能是印度对世界最大的一笔馈赠。白匈奴入侵后帝国瓦解,印度重回列国时代。' },
{ l:'sa', s:'indic', v:1, n:'中世纪诸王朝', k:[[540,0],[600,.2],[700,.35],[1000,.33],[1206,0]], b:'戒日之后列国并立;印度教文化持续繁荣并输出海外。',
  e:{ n:'Medieval Kingdoms', w:'Medieval India', b:'Many kingdoms, exporting culture to Southeast Asia.', d:'After Harsha\'s brief reunification the subcontinent settled into centuries of Rajput and southern dynasties; political division didn\'t stop cultural export — these are the centuries when Hinduism and Buddhism deeply shaped Southeast Asia by sea.', f:{ 'Peak':'7th c. (Harsha)', 'Center':'Kannauj, the Deccan', 'Figures':'Harsha' } },
  f:{ '鼎盛':'7世纪(戒日王)', '中心':'卡瑙杰、德干诸都', '人物':'戒日王' },
  qh:{ born:['再没有人能把全印度重新拼起来','No one could put all India back together again'],
       rule:['换的是上层,底盘纹丝不动','The top changed; the base did not move'],
       money:['神庙同时是银行,也是市政厅','The temple was both the bank and the town hall'],
       power:['影响力出海了,一兵一卒都没派','The influence sailed out, without a single soldier'],
       fall:['互相耗了几百年,对外始终没合力','Centuries spent on each other, and never united outward'],
       legacy:['吴哥和爪哇的印度化,是它输出的','The Indianisation of Angkor and Java came from here'] },
  q:{ born:['笈多解体后,再没有力量能重造全印帝国:戒日王7世纪短暂重聚北印,身后即散;此后数百年,次大陆的常态是列国并立——北有拉杰普特诸王,南有德干与泰米尔强邦。','After the Guptas dissolved, no power could rebuild an all-India empire: Harsha briefly reunited the north in the seventh century, and it scattered at his death. For centuries afterward the subcontinent\'s normal state was a concert of kingdoms — Rajput princes in the north, Deccan and Tamil powers in the south.'],
      rule:['王朝走马灯,社会自运转:种姓网络、村社与神庙承担了基层的秩序、司法与救济,王只在上层收税与打仗;所以政权更替频繁,文明的底盘却纹丝不动。','Dynasties revolved like a lantern while society ran itself: caste networks, village assemblies, and temples handled local order, justice, and relief, while kings merely taxed and fought above them. Regimes changed constantly; the civilization\'s chassis never moved.'],
      money:['神庙是这个时代的经济枢纽:王与商人向神庙捐地捐金,神庙再放贷、雇工、办集市,兼任银行与市政厅;对外则靠印度洋贸易,香料与棉布源源出海。','The temple was the economic hub of the age: kings and merchants endowed it with land and gold, and it lent money, hired labor, and ran markets — bank and city hall in one. Overseas, Indian Ocean trade carried out spices and cotton without pause.'],
      power:['没有霸主,只有均势:几大强权为争夺卡瑙杰缠斗百年,谁也吃不下谁;力量于是转向海外——印度教与佛教沿商路深刻塑造东南亚,不靠一兵一卒。','No hegemon, only balance: the great powers wrestled for a century over Kannauj and none could swallow the others. Strength flowed outward instead — Hinduism and Buddhism shaped Southeast Asia along the trade routes without a single soldier.'],
      fall:['列国互耗数百年,始终没能对西北方向形成合力;12世纪末,古尔王朝的军队接连击破北印诸王,1206年德里苏丹国建立——分立的时代结束,北印进入新的政权格局。','Centuries of rivalry left the kingdoms unable to unite against the northwest. In the late twelfth century the armies of Ghor defeated the northern kings one after another, and the founding of the Delhi Sultanate in 1206 closed the age of the concert and opened a new order in the north.'],
      legacy:['印度教神庙建筑在此期达到艺术巅峰,从卡杰拉霍到坦贾武尔;东南亚从吴哥到爪哇的印度化,是它输出的文明;拉杰普特的尚武传统,则成为后世印度身份的一部分。','Hindu temple architecture reached its artistic summit in this era, from Khajuraho to Thanjavur. The Indianization of Southeast Asia, from Angkor to Java, was its export, and the Rajput martial tradition became a lasting strand of Indian identity.'] },
  d:'戒日王短暂重聚北印后,次大陆进入拉杰普特诸王与南方王朝并立的漫长中世纪;政治分裂无碍文化输出——印度教与佛教正是在这几百年间沿海路深刻塑造了东南亚。' },
{ l:'sa', s:'indic', v:0, n:'波罗王朝', k:[[750,0],[810,.4],[860,.42],[1000,.28],[1161,0]], b:'孟加拉的佛教王朝:供养那烂陀,又建了超戒寺,把佛法第二次送进西藏。',
  e:{ n:'the Pala dynasty', w:'Pala Empire', b:'A Buddhist dynasty in Bengal: it kept Nalanda going, built Vikramashila, and sent the dharma to Tibet a second time.', d:'After Harsha, northern India fell into disorder its own records call the law of the fishes. Around 750 the chiefs of Bengal elected Gopala king — a dynasty that began by being asked in rather than fighting its way in. Dharmapala and Devapala took it to its height, contesting Kannauj for a century with the Gurjara-Pratiharas and the Rashtrakutas. It endowed Nalanda and founded Vikramashila, making Bengal the densest concentration of Buddhist learning in the world; in 1042 the scholar Atisha left for Tibet and shaped Tibetan Buddhism deeply. The Senas replaced it around 1161, and within forty years Turkish cavalry destroyed the great monasteries — the end of the monastic system that had been Buddhism\'s home ground in India.', f:{ 'Peak':'late 8th to 9th c. (Dharmapala to Devapala)', 'Center':'Gauda', 'Figures':'Dharmapala, Atisha', 'Legacy':'Vikramashila and the endowment of Nalanda, Pala sculpture, Buddhism\'s road into Tibet' } },
  f:{ '鼎盛':'8世纪末—9世纪(达摩波罗至提婆波罗)', '中心':'高德', '人物':'达摩波罗、阿底峡', '成就':'超戒寺与那烂陀的供养、波罗风格造像、佛法二次入藏' },
  qh:{ born:['不是打出来的王,是被推出来收拾局面的','Not a conqueror, but a king chosen to fix the mess'],
       rule:['供佛,也给婆罗门赐地,不二选一','It endowed Buddhists and brahmins alike, choosing neither'],
       money:['一条山路通西藏,经卷就是这么过去的','A mountain road to Tibet, and the scriptures went that way'],
       power:['真正的护身符是水:骑兵在这儿不好用','The real protection was water: cavalry did not work here'],
       fall:['寺院被毁,佛教在印度本土就此结束','The monasteries fell, and Buddhism ended in its homeland'],
       legacy:['一位学者入藏,今天还接着那条线','One scholar went to Tibet, and the line still runs'] },
  q:{ born:['戒日王之后北印度陷入长期混战,孟加拉一带尤其无主。当地记载把那段日子叫作「马磋尼耶」——大鱼吃小鱼的意思。约750年,各方首领推举瞿波罗为王,这在印度王朝史上很少见:不是靠征服起家,而是被推出来收拾局面的。他的继承者达摩波罗与提婆波罗把王朝推向鼎盛,一度北上争夺曲女城,与西边的瞿折罗-普腊蒂哈腊、南边的罗湿陀罗拘陀三家反复拉锯——这段被称为「三方之争」。','After Harsha died northern India fell into long disorder, and Bengal in particular had no master; the local records call those years matsyanyaya, the law of the fishes, where the big eat the small. Around 750 the chiefs of the region elected Gopala king — an unusual beginning in Indian dynastic history, a ruler put up to end the chaos rather than one who conquered his way in. His successors Dharmapala and Devapala carried the dynasty to its height and pushed north to contest Kannauj, tugging back and forth for a century with the Gurjara-Pratiharas to the west and the Rashtrakutas to the south, in what is called the tripartite struggle.'],
      rule:['王权与僧团绑得很紧:国王供养寺院,寺院则是行政与教育的骨架。它没有把佛教定为唯一信仰——铜板文书里同样有给婆罗门的赐地,湿婆与毗湿奴的神庙照建。这在当时的印度是常态:统治者按需要资助不同教派,而不是二选一。','Kingship and the monastic order were tightly bound: the king endowed the monasteries and the monasteries supplied the framework of administration and schooling. It did not make Buddhism the sole faith — the copperplate grants record land given to Brahmins as well, and Shiva and Vishnu temples went on being built. That was normal in the India of the day: rulers funded whichever schools suited them rather than choosing one.'],
      money:['孟加拉三角洲的稻作是底盘,恒河与布拉马普特拉河的水系又让内河运输极便宜。对外一头连着东南亚的海上航线,一头连着经尼泊尔进入西藏的山路——僧人、经卷与铜像走的正是后一条。它铸币不多,大额交易常用贝币与实物,这一点与同期的朱罗很不一样。','Rice in the Bengal delta was the base, and the Ganges and Brahmaputra made river transport very cheap. Outward it faced the sea routes to Southeast Asia on one side and, on the other, the mountain roads through Nepal into Tibet — which is the road the monks, the manuscripts and the bronzes took. It struck little coin, and large transactions often ran on cowries and goods in kind, quite unlike the contemporary Cholas.'],
      power:['军力以象军著称,阿拉伯旅行者的记述里对波罗的战象数量印象很深(数字多半夸大,但象在这一带确实是主力)。它北上曲女城一度得手,随即又被逐回——三方之争谁也吃不掉谁,消耗了三家一百多年。真正的护身符其实是地理:孟加拉多水,骑兵不好用。','Its army was known for elephants, and Arab travellers wrote down large numbers of Pala war elephants — the figures are surely inflated, but elephants really were the mainstay here. It took Kannauj once and was driven back out; in the tripartite struggle none of the three could finish the others, and it drained all of them for over a century. Its real protection was the ground: Bengal is a country of water, and cavalry does not work well in it.'],
      fall:['10世纪起王朝反复衰而复振,11世纪初摩希波罗一世还中兴过一次。但地方豪族坐大,东边的迦摩缕波与南边的朱罗都来分过一杯羹——朱罗的罗贞陀罗一世曾北征到恒河边。1161年前后,原本臣属的犀那家族取而代之。此后不到四十年,突厥将领巴赫蒂亚尔·卡尔吉的骑兵进入比哈尔,超戒寺与欧丹多富梨被毁、那烂陀元气大伤,僧人四散——恒河流域的大型寺院体系就此崩解。零星的佛教社群在东印与南印又延续了几百年,但作为一套有寺院、有学统的建制,它在印度本土结束了。','From the tenth century the dynasty sagged and revived repeatedly, and Mahipala I managed one real restoration in the early eleventh. But local magnates grew strong, Kamarupa pressed from the east and the Cholas from the south — Rajendra I marched north as far as the Ganges. Around 1161 the Senas, once its vassals, took over. Less than forty years later Turkish cavalry under Bakhtiyar Khalji rode into Bihar, Vikramashila and Odantapuri were destroyed and Nalanda crippled, and the monks scattered — the great monastic system of the Ganges valley came apart. Scattered Buddhist communities went on for centuries yet in eastern and southern India, but as an institution with monasteries and a living scholarship it was finished in India itself.'],
      legacy:['它供养的那烂陀已经运转了三百多年,它又新建了超戒寺与欧丹多富梨寺,把孟加拉变成当时佛学最密集的地方。1042年,超戒寺的学者阿底峡应邀入藏,此后藏传佛教的教法体系与他这一支关系极深——今天西藏寺院里念的经、供的像,源头有一条就在这里。造像上的「波罗风格」经尼泊尔传入西藏,又随海路影响到东南亚。孟加拉国的索马普拉大寺遗址1985年列入世界遗产,是当时寺院规模的实物。','The Nalanda it endowed had already been running for three centuries, and it built Vikramashila and Odantapuri besides, making Bengal the densest concentration of Buddhist learning anywhere at the time. In 1042 the Vikramashila scholar Atisha was invited to Tibet, and the doctrinal framework of Tibetan Buddhism owes a great deal to his line — some of what is chanted and worshipped in Tibetan monasteries today runs back to here. The Pala style in sculpture reached Tibet through Nepal and Southeast Asia by sea. The ruins of Somapura Mahavihara in Bangladesh, a World Heritage site since 1985, show how large these monasteries were.'] },
  d:'戒日王之后北印大乱,孟加拉的首领们推举瞿波罗为王——不是打出来的,是被推出来收拾局面的。达摩波罗与提婆波罗时北上争夺曲女城,与瞿折罗-普腊蒂哈腊、罗湿陀罗拘陀三家拉锯百年。它供养那烂陀、新建超戒寺,把孟加拉变成佛学最密集的地方;1042年超戒寺的阿底峡入藏,深刻塑造了藏传佛教。1161年前后被犀那家族取代,不到四十年超戒寺被毁、那烂陀元气大伤,恒河流域的大型寺院体系就此崩解。' },
{ l:'sa', s:'indic', v:2, n:'朱罗王朝', k:[[850,0],[1010,.5],[1070,.45],[1250,0]], b:'南印海上强权,舰队远征三佛齐,印度文化圈随商船外扩。',
  e:{ n:'Chola Empire', w:'Chola dynasty', b:'Tamil sea power; fleets to Srivijaya.', d:'The Tamil maritime empire of south India sent fleets to the Malay peninsula and Srivijaya — rare naval power in Indian history; its bronze Dancing Shiva remains Indian art\'s calling card.', f:{ 'Peak':'Rajendra I (1014–1044)', 'Center':'Thanjavur', 'Figures':'Rajaraja I, Rajendra I', 'Legacy':'Ocean fleets, bronze Nataraja, stone temples' } },
  f:{ '鼎盛':'罗贞陀罗一世(1014—1044)', '中心':'坦贾武尔', '人物':'拉贾拉贾一世、罗贞陀罗一世', '成就':'远洋舰队、青铜舞王像、石构神庙' },
  qh:{ born:['拿下最肥的三角洲,就有了争霸的粮仓','Taking the richest delta gave it a granary to fight from'],
       rule:['石刻上写着,村委会怎么抽签选举','A stone inscription lays out how the village drew lots'],
       money:['商船走得越远,税源就越广','The further the ships went, the wider the tax base'],
       power:['舰队一路打到今天的印尼','Its fleet struck as far as present-day Indonesia'],
       fall:['海上霸权,比王朝本身散得更早','The sea power faded before the dynasty did'],
       legacy:['东南亚的神庙里,还认得出它的影子','Its shadow is still visible in Southeast Asian temples'] },
  q:{ born:['朱罗是泰米尔古诗里就传唱的古老王统,9 世纪趁旧霸主帕拉瓦衰落而复兴;夺下科弗里河三角洲这片南印最肥的稻田后,它有了争霸的粮仓。这个王统有多老,河上有实物:公元 100 到 150 年前后,早期朱罗的卡里卡兰王在科弗里河上用未经打磨的石头垒起一道拦河坝「卡拉奈」,长 329 米、宽 20 米、高 5.4 米,今天仍在用——是印度还在服役的最古老水利工程。要说清楚的是,这套灌区从约六万九千英亩扩到上百万英亩,主要是 19 世纪英国人改建的结果,不该算在朱罗头上。','The Cholas were an ancient Tamil royal line, sung of in early poetry, that revived in the ninth century as the old Pallava power faded. Seizing the Kaveri delta — the richest rice land in the south — gave them the granary of contenders. How old that line is has a physical answer in the river. Around AD 100 to 150 the early Chola king Karikalan threw a barrage of unhewn stone across the Kaveri — the Kallanai, 329 metres long, 20 wide and 5.4 high — and it is working still, the oldest water-regulating structure in India remaining in use. One qualification belongs with that: the growth of the irrigated area from some sixty-nine thousand acres to over a million was largely the work of nineteenth-century British rebuilding, and is not to the credit of the Cholas.'],
      rule:['神庙加村社的双层架构:王把征服所得砸进巨庙,把王权与湿婆信仰绑在一起;基层则有铭文记载的村社自治——乌塔拉梅鲁尔的石刻甚至详细规定了村委会如何抽签选举。','A two-layer frame of temple and village: kings poured conquest wealth into colossal temples, binding royal power to the worship of Shiva, while inscriptions record self-governing village assemblies — the stones of Uthiramerur even spell out how committee members were chosen by lot.'],
      money:['稻米打底,海贸生金:科弗里三角洲的收成养活王朝,商人行会把胡椒、棉布与宝石卖到东南亚和宋朝中国;王家舰队护航,商船走得越远,税源就越广。','Rice at the base, sea trade for gold: the Kaveri harvests fed the dynasty while merchant guilds sold pepper, cloth, and gems to Southeast Asia and Song China. The royal fleet convoyed them — the farther the ships sailed, the wider the tax net.'],
      power:['它是印度史上罕见的海上远征型政权:舰队征服斯里兰卡北部,1025年更跨洋突袭三佛齐诸港——一般认为是为了打通对宋贸易的航道;在陆权为常态的印度,几乎没有别家走过这条路线。','It was that rare thing in Indian history, a naval expedition power: its fleets conquered northern Sri Lanka, and in 1025 struck across the ocean at the ports of Srivijaya — generally thought to be about clearing the sea lanes to Song China. In a land of land powers, almost no one else took this route.'],
      fall:['多因叠加:与德干的遮娄其王朝百年拉锯耗尽扩张余力;附庸的潘地亚在南方复兴反噬;13世纪王统式微,故土被潘地亚吞并——远洋霸权先于王朝本身消散。','Causes stacked: a century of seesaw war with the Chalukyas of the Deccan spent its strength; the vassal Pandyas revived in the south and turned on their overlord; by the thirteenth century the line had withered and its homeland fell to the Pandyas — the overseas reach faded even before the dynasty did.'],
      legacy:['坦贾武尔大庙与青铜舞王湿婆像至今是印度艺术的名片;泰米尔文学与信仰在它治下定型;它的商船与僧侣把南印文化送进东南亚,那里的神庙里至今认得出朱罗的影子。','The great temple of Thanjavur and the bronze dancing Shiva remain calling cards of Indian art. Tamil letters and devotion took lasting shape under its rule, and its ships and monks carried south Indian culture into Southeast Asia, where temples still show a Chola profile.'] },
  d:'南印泰米尔人的海上强权,舰队远征马来半岛、突袭三佛齐,是印度史上罕见的海权帝国;其青铜"舞王湿婆"像至今是印度艺术的名片。' },
{ l:'sa', s:'indic', v:1, n:'斯里兰卡诸王国', k:[[-250,0],[-100,.25],[500,.3],[1150,.35],[1300,.2],[1600,.15],[1815,0]], b:'阿努拉德普勒、波隆纳鲁沃、康提:一座岛上接力两千年的僧伽罗王国,佛教在这里保存得几乎最久。',
  e:{ n:'The kingdoms of Sri Lanka', w:'History of Sri Lanka', b:'Anuradhapura, Polonnaruwa, Kandy — Sinhalese kingdoms handing the island on for two thousand years, and Buddhism kept longer here than almost anywhere.', d:'Sinhalese tradition dates the first kingdom on the island to the fifth century BC; Buddhism arrived around 250 BC, sent — the chronicles say — by the emperor Ashoka through his son Mahinda, and a cutting of the Bodhi tree planted at Anuradhapura then is still alive. Anuradhapura was the capital for over a thousand years, its kings raising brick stupas as large as the pyramids and a web of reservoirs and canals that made dry-zone rice farming possible; the Chola conquest of 993 ended it, and Vijayabahu I drove the Cholas out in 1070 and ruled from Polonnaruwa, where Parakramabahu I (1153-1186) built the great Sea of Parakrama tank. After the thirteenth century the centres moved south-west; the Portuguese arrived in 1505, the Dutch took the coasts in 1658, the British in 1796, and the last kingdom, Kandy in the hills, fell to Britain in 1815. The Pali chronicles kept here — the Mahavamsa above all — are among the longest continuous histories written anywhere in Asia.', f:{ 'Peak':'12th c. (Polonnaruwa)', 'Centre':'Anuradhapura, Polonnaruwa, Kandy', 'Figures':'Devanampiya Tissa, Parakramabahu I', 'Legacy':'the great stupas of Anuradhapura, Sigiriya, the tank-and-canal system, the Mahavamsa chronicle, the Temple of the Tooth' } },
  f:{ '鼎盛':'12世纪(波隆纳鲁沃)', '中心':'阿努拉德普勒、波隆纳鲁沃、康提', '人物':'天爱帝须、波罗迦罗摩巴忽一世', '成就':'阿努拉德普勒大塔、狮子岩、水库与水渠系统、《大史》、佛牙寺' },
  qh:{ born:['编年史说,阿育王的儿子把佛教带上岛','The chronicles say Ashoka\'s son brought Buddhism over'],
       rule:['一座都城用了一千多年','One capital served for over a thousand years'],
       money:['旱地上种稻,全靠人挖的湖','Rice on dry land, all thanks to man-made lakes'],
       power:['砖砌的塔,高得能和金字塔比','Brick stupas that stand up to the pyramids'],
       fall:['沿海归了葡萄牙、荷兰、英国,山里还是国王','Portuguese, Dutch, British held the coasts; the hills still had a king'],
       legacy:['几千个古老的水库,今天还在灌田','Thousands of ancient tanks still water the fields'] },
  q:{ born:['僧伽罗人的编年史把岛上第一个王国追到公元前 6—5 世纪,考古上阿努拉德普勒在前 4 世纪已是有城墙的城。约前 250 年,佛教传上岛——编年史说是阿育王派儿子摩哂陀来的,国王天爱帝须皈依,菩提伽耶那棵菩提树的一枝被带来种在阿努拉德普勒,至今活着,是有记录的最老的人工种植树木之一。此后佛教在别处几起几落,在这座岛上却一直没有断。','The Sinhalese chronicles trace the island\'s first kingdom to the sixth or fifth century BC, and archaeologically Anuradhapura was a walled city by the fourth. Around 250 BC Buddhism reached the island — the chronicles say the emperor Ashoka sent his son Mahinda, and King Devanampiya Tissa was converted; a cutting of the Bodhi tree of Bodh Gaya was planted at Anuradhapura and is still alive, one of the oldest planted trees on record anywhere. Buddhism rose and fell elsewhere; on this island it never broke off.'],
      rule:['阿努拉德普勒做了一千多年都城(约前 4 世纪—1017 年),这在世界上极少见。国王的合法性和僧团绑在一起:大寺与无畏山寺两派长期并立,王权更迭常牵动僧团。10 世纪末南印度的朱罗王朝渡海攻来,993 年占领阿努拉德普勒;1070 年维阇耶巴忽一世把朱罗人赶走,把都城迁到东南面的波隆纳鲁沃。13 世纪后国都一路南迁,最后落在中部山地的康提。','Anuradhapura was the capital for over a thousand years, from about the fourth century BC to 1017 — a rarity anywhere in the world. Kingship was bound up with the monastic community: the Mahavihara and Abhayagiri traditions stood side by side for centuries, and changes on the throne often reached into the monasteries. At the end of the tenth century the Chola kingdom of south India came over the sea and took Anuradhapura in 993; Vijayabahu I drove the Cholas out in 1070 and moved the capital south-east to Polonnaruwa. After the thirteenth century the seat of the kings kept moving south, ending at Kandy in the central hills.'],
      money:['岛的北半部是旱区,一年里大半时间不下雨,王国的根本是水:从前 4 世纪起国王们修水库(当地叫「湖」)和水渠,把雨季的水存起来灌溉稻田,波罗迦罗摩巴忽一世的「波罗迦罗摩海」堤坝长十多公里,他有句名言——「一滴雨水也不能不为人所用就流进海里」。这套系统养活了大人口,也让宝石、象牙、肉桂和珍珠出口成为可能;科伦坡一带的港口在中世纪已有阿拉伯商人常住。','The northern half of the island is a dry zone where it does not rain for much of the year, and the kingdoms rested on water: from the fourth century BC the kings built reservoirs — tanks — and canals to store the monsoon rain for the rice fields, and the Sea of Parakrama, dug by Parakramabahu I, has an embankment over ten kilometres long; his saying was that not a drop of rain should reach the sea without serving man. The system fed a large population and made exports of gems, ivory, cinnamon and pearls possible; Arab merchants were living at the ports around Colombo by the middle ages.'],
      power:['阿努拉德普勒的砖塔是古代世界最大的建筑之一:祇陀林塔约 4 世纪建成时高一百二十米上下,只比吉萨大金字塔矮一些;鲁梵伐利塔(大塔,前 2 世纪)至今仍是朝拜中心。5 世纪末的国王迦叶波把宫殿建在两百米高的狮子岩顶上,岩壁上留下的仕女壁画和「镜墙」上游客刻的诗至今还在,1982 年列入世界遗产。','The brick stupas of Anuradhapura are among the largest structures of the ancient world: the Jetavana stupa stood around a hundred and twenty metres high when finished in the fourth century, only a little short of the Great Pyramid, and the Ruwanwelisaya of the second century BC is still a centre of pilgrimage. At the end of the fifth century King Kashyapa built his palace on top of Sigiriya, the Lion Rock, two hundred metres up; the frescoes of women on its face and the verses visitors scratched on its mirror wall are still there, and it was listed as World Heritage in 1982.'],
      fall:['1505 年葡萄牙人到岸,一步步控制了沿海和肉桂贸易;1658 年荷兰东印度公司把葡萄牙人赶走,接管沿海;1796 年英国又从荷兰手里接过来。山里的康提王国靠地形撑到 1815 年,英国人扶持不满国王的贵族,签下《康提公约》,岛上最后一个王国结束——整座岛第一次归于一个外来政权。1948 年锡兰独立,1972 年改国名斯里兰卡。','The Portuguese landed in 1505 and step by step took the coasts and the cinnamon trade; the Dutch East India Company drove them out in 1658 and held the coasts; the British took over from the Dutch in 1796. The kingdom of Kandy in the hills held out on its terrain until 1815, when the British backed nobles who had turned against their king and the Kandyan Convention ended the last kingdom on the island — the first time the whole island belonged to one outside power. Ceylon became independent in 1948 and took the name Sri Lanka in 1972.'],
      legacy:['这座岛上写成的巴利文编年史——尤其是 5 世纪起写、后来一直续到 20 世纪的《大史》——是亚洲连续记录最长的史书之一,南传佛教的经典也是在这里的寺院里第一次被写在贝叶上(约前 1 世纪)。康提的佛牙寺供着佛牙,每年夏天的佛牙节游行有大象和鼓手,是全岛最大的节庆;阿努拉德普勒的菩提树、狮子岩、波隆纳鲁沃都是世界遗产,而旱区里几千个古老的水库,今天还在灌溉稻田。','The Pali chronicles written on this island — above all the Mahavamsa, begun in the fifth century and continued into the twentieth — are among the longest continuous histories in Asia, and the scriptures of Theravada Buddhism were first written down on palm leaves in its monasteries around the first century BC. The Temple of the Tooth at Kandy keeps the Buddha\'s tooth relic, and its summer procession of elephants and drummers is the island\'s greatest festival; the Bodhi tree of Anuradhapura, Sigiriya and Polonnaruwa are all World Heritage, and thousands of ancient tanks in the dry zone still water the rice fields.'] },
  d:'僧伽罗传统把岛上第一个王国定在公元前 5 世纪。约前 250 年佛教传上岛——编年史说是阿育王派儿子摩哂陀送来的,当时栽下的那株菩提树至今还活着。阿努拉德普勒做了一千多年都城,靠水库与水渠在旱区种稻,砖塔高可比金字塔;993 年朱罗攻占,1070 年毗阇耶巴忽一世把朱罗人赶出去、迁都波隆纳鲁沃,波罗迦罗摩巴忽一世(1153—1186 年在位)在那里筑起被称作「波罗迦罗摩海」的大水库;13 世纪之后政治中心一路南移。葡萄牙(1505)、荷兰(1658)、英国(1796)接连控制沿海,1815 年康提亡,全岛归英。留下《大史》、菩提树、狮子岩与佛牙寺——岛上用巴利文写下的这批编年史,是亚洲连续记载时间最长的史书之一。' },
{ l:'sa', s:'mideast', v:0, n:'德里苏丹国', k:[[1206,0],[1300,.55],[1398,.3],[1526,0]], b:'突厥-阿富汗军人建立的伊斯兰政权,统治北印三百年。',
  e:{ n:'Delhi Sultanate', b:'Turko-Afghan Islam rules the north for three centuries.', d:'Turko-Afghan soldiery built an Islamic state over north India, five dynasties in succession; it stopped the Mongols at the Indus but was wrecked by Timur\'s sack. Indo-Islamic architecture and Urdu trace here.', f:{ 'Peak':'early 14th c.', 'Center':'Delhi', 'Figures':'Razia Sultana, Alauddin Khalji', 'Legacy':'Indo-Islamic architecture, roots of Urdu' } },
  f:{ '鼎盛':'14世纪初', '中心':'德里', '人物':'拉齐娅女苏丹、阿拉乌丁·卡尔吉', '成就':'印度-伊斯兰建筑、乌尔都语源头' },
  qh:{ born:['一个奴隶出身的将军,自己当了王','A general born a slave made himself king'],
       rule:['五个王朝走马灯,平衡从没稳过','Five dynasties in turn: the balance never held'],
       money:['用物价管制来养兵,这是个实验','Feeding an army by price control was an experiment'],
       power:['它顶住了蒙古,北印才躲过一劫','It held off the Mongols, and the north was spared'],
       fall:['帖木儿洗劫德里之后,就散架了','After Timur sacked Delhi, it came apart'],
       legacy:['乌尔都语的源头,在军营和市井之间','Urdu began between the barracks and the bazaar'] },
  q:{ born:['12世纪末,古尔王朝的军队击破北印诸王;主帅死后,他的突厥奴隶出身的将军艾伊拜克在拉合尔自立,数年后德里成为都城。此后三百年,统治北印的是一个靠军功上位、以德里为都的伊斯兰军人集团。','In the late twelfth century the armies of Ghor broke the kings of north India, and when the sultan died, his general Aibak — a former Turkic slave — set up on his own in Delhi. For the next three centuries north India was ruled by an Islamic military elite that rose by the sword and ruled from Delhi.'],
      rule:['靠伊克塔制:苏丹把各地税权分包给军事贵族,换他们供养骑兵;对占多数的印度教徒征收人头税,同时又离不开本地文书与包税人的协作;五个王朝走马灯般更替,说明苏丹与军头之间的平衡始终没有稳过。','Through the iqta system: the sultan farmed out regional tax rights to military nobles in exchange for cavalry. Hindu subjects, the majority, paid a poll tax, yet the state could not run without local clerks and revenue men. Five dynasties revolving through the throne shows the balance between sultan and warlords never held for long.'],
      money:['北印的田赋与市税是根本,德里又居于中亚商路的南端口;阿拉乌丁·卡尔吉曾以严厉的市场限价供养大军——用物价管制养兵,是它财政上最出名的实验。','Land and market taxes of north India were the base, with Delhi as the southern gate of the Central Asian trade roads. Alauddin Khalji famously imposed strict price controls to feed a huge army — financing troops through fixed markets was its best-known fiscal experiment.'],
      power:['军力照搬中亚剧本:突厥骑兵加要塞;它最大的军事成绩是顶住了蒙古——13至14世纪蒙古大军多次南下,1303年一度围困德里两个多月,却始终没能在印度立足——北印因此躲过了席卷欧亚的浩劫。','Its arms followed the Central Asian script: Turkic cavalry plus fortresses. Its greatest military feat was holding off the Mongols — repeated invasions in the 13th and 14th centuries were kept out of the Indian heartland, sparing north India the storm that swept Eurasia.'],
      fall:['多因叠加:王朝频繁更替暴露继承机制的脆弱;1398年帖木儿洗劫德里,苏丹国元气大伤,各地苏丹与印度教政权纷纷自立;1526年,巴布尔的火炮在帕尼帕特终结了最后的洛迪王朝。','Causes stacked: the parade of dynasties exposed how fragile succession was; Timur\'s sack of Delhi in 1398 broke the sultanate\'s strength, and regional sultans and Hindu kingdoms declared independence. In 1526 Babur\'s cannon at Panipat finished the last Lodi dynasty.'],
      legacy:['印度-伊斯兰建筑(以顾特卜塔为代表)、波斯语的行政与文学传统,以及军营与市井交融出的乌尔都语源头,都出自这三百年;它也把北印重新连回中亚-波斯世界。','Indo-Islamic architecture (the Qutb Minar above all), the Persian language of administration and letters, and the camp-and-bazaar origins of Urdu all come from these three centuries — which also rejoined north India to the Central Asian and Persian world.'] },
  d:'中亚突厥-阿富汗军人在北印建立的伊斯兰政权,五个王朝走马灯般更替;挡住了蒙古南下,却毁于帖木儿的洗劫。印度-伊斯兰建筑与乌尔都语的源头都在这三百年里。' },
{ l:'sa', s:'indic', v:0, n:'维查耶纳伽尔', k:[[1336,0],[1400,.25],[1520,.45],[1565,.15],[1646,0]], b:'南印度三百年主角,挡住北方三百年。',
  e:{ n:'Vijayanagara', b:'The main power of southern India for three centuries, holding the north at bay.', d:'After armies from the north broke the old Deccan kingdoms, two brothers founded a city of victory on the Tungabhadra and held the south for three hundred years. Under Krishnadevaraya the state was at its height, its capital holding several hundred thousand people; Portuguese visitors, and a Persian envoy a generation earlier, both recorded its scale. Depending on imported warhorses was its structural weakness, and after the defeat at Talikota in 1565 the capital was sacked over months — the ruins are Hampi.', f:{ 'Peak':'Krishnadevaraya (1509-1529)', 'Center':'Vijayanagara (Hampi)', 'Figures':'Krishnadevaraya', 'Legacy':'The Hampi monuments, irrigation works, literature in the southern languages' } },
  f:{ '鼎盛':'克里希纳提婆罗耶(1509—1529)', '中心':'毗奢耶那伽罗(汉皮)', '人物':'克里希纳提婆罗耶', '成就':'汉皮建筑群、灌溉水利、南印度诸语文学' },
  qh:{ born:['北边压过来,南边的势力重新组了一次','Pressure from the north made the south regroup'],
       rule:['宗教对立,后来被写得比实际严重','The religious divide was written up harsher than it was'],
       money:['什么都有,就是不产马,只能买','It had everything but horses, and had to buy them'],
       power:['首都是当时世界上最大的城市之一','Its capital was among the largest cities alive then'],
       fall:['马要买,所以长期被人捏着','Buying its horses meant being held by the throat'],
       legacy:['有一座庙的石柱,敲上去能出乐音','One temple has stone pillars that ring like music'] },
  q:{ born:['14世纪初德里苏丹国的军队多次南下,德干与南印度的旧王朝相继瓦解。1336年,两兄弟哈里哈拉与布卡在通伽巴德拉河南岸建城立国,以"胜利之城"为名。关于他们的出身,史料记载不一——有说法称二人曾被俘北上、改宗后又返回复归印度教,但这一段真伪学界仍有争论。可以确定的是,这个政权是在北方压力下由南方地方势力重组而成的。','In the early fourteenth century armies from the Delhi Sultanate came south repeatedly and the older kingdoms of the Deccan and the far south collapsed one after another. In 1336 two brothers, Harihara and Bukka, founded a city and a state on the south bank of the Tungabhadra, naming it the city of victory. The sources disagree about their background — one account has them captured and taken north, converted, and then returning to Hinduism, but its truth is still debated. What is clear is that the state was assembled by southern regional powers under pressure from the north.'],
      rule:['中央之下设"纳耶卡"制:把土地连同税收权分给军事贵族,条件是按额供养骑兵与步兵、随时应征。这套安排让帝国能快速动员,也埋下了地方坐大的隐患。国王同时扮演印度教的护法者角色,大量捐赠寺庙、供养婆罗门与各教派,但对治下的穆斯林商人和雇佣兵并不排斥——军中就有成建制的穆斯林弓骑兵。宗教对立在后世的历史书写里被说得比实际更绝对。','Below the centre ran a system of military governors: land and its revenues were assigned to commanders on condition they maintained a set quota of horse and foot and answered any summons. It let the empire mobilise fast and also let the provinces grow strong. The king acted as protector of Hindu religion, endowing temples and supporting Brahmins and the various sects on a large scale, yet Muslim merchants and mercenaries were not excluded — the army included whole units of Muslim horse-archers. Later historical writing has made the religious opposition look far more absolute than it was in life.'],
      money:['南印度的水利是它的基础:修建水库与引水渠灌溉半干旱的德干高原,粮食与棉花产量因此提高。对外贸易极为兴盛——西海岸的港口输出棉布、香料与铁,进口最重要的商品是战马,由阿拉伯与波斯商人经海路运来(南印度不产良马,这一直是它的软肋)。葡萄牙人在克里希纳提婆罗耶治下、波斯使节在更早一代,都留下记载,对首都的规模与市场上的宝石交易印象深刻。','Water control was the base: reservoirs and channels irrigated the semi-arid Deccan and raised yields of grain and cotton. Overseas trade was very active — the west-coast ports shipped out cotton cloth, spices and iron, and the most important import was warhorses, brought by sea by Arab and Persian merchants, since southern India bred no good cavalry mounts and never solved that weakness. Portuguese visitors in his reign, and a Persian envoy a generation earlier, both left accounts struck by the scale of the capital and the gem trading in its markets.'],
      power:['靠三样东西:河流与花岗岩丘陵构成的天然要塞地形、进口战马组建的骑兵、以及首都巨大的防御工事。克里希纳提婆罗耶在位期间(1509—1529)国力最盛,向北压过德干各苏丹国,向东控制沿海。首都毗奢耶那伽罗当时人口可能达数十万,是同时代世界上最大的城市之一,城墙、水利与市场遗迹今天仍在汉皮。','Three things: a natural fortress of rivers and granite hills, cavalry mounted on imported horses, and enormous fortifications around the capital. Under Krishnadevaraya (1509–1529) the state was at its strongest, pressing north against the Deccan sultanates and controlling the eastern coast. The capital may have held several hundred thousand people, making it one of the largest cities in the world at the time; its walls, waterworks and market ruins still stand at Hampi.'],
      fall:['1565年塔利科塔之战是转折:德干几个苏丹国联合出兵,维查耶纳伽尔战败,首都被攻破并遭数月洗劫。此后王室退往南方,又存续了约八十年,但再未恢复。原因不止一战:纳耶卡贵族早已半独立,王位继承屡起争夺,而战马依赖进口这一点让它在与北方的长期对抗中始终受制于人。1646年最后的据点陷落。','The battle of Talikota in 1565 was the turning point: several Deccan sultanates combined against it, the army was beaten, and the capital was taken and sacked over some months. The royal house withdrew south and lasted about another eighty years without ever recovering. The causes were more than one battle: the military governors were already half independent, the succession was repeatedly disputed, and dependence on imported warhorses left it structurally at a disadvantage in a long contest with the north. The last stronghold fell in 1646.'],
      legacy:['汉皮遗址是世界文化遗产,数百座神庙、王宫与市场廊道保存至今,毗塔拉神庙的石柱能敲出乐音,是南印度石构技艺的代表。这一时期泰卢固语、卡纳达语与泰米尔语文学都获得王室赞助而繁荣,克里希纳提婆罗耶本人也是诗人。政治上,战败后各地纳耶卡演变为独立小邦,南印度进入新的分裂格局,直到英国人到来。','The ruins at Hampi are a World Heritage site, with hundreds of temples, palaces and market colonnades still standing; the stone pillars of the Vittala temple ring with musical notes, a showpiece of southern Indian stonework. Telugu, Kannada and Tamil literature all flourished under royal patronage in this period, and Krishnadevaraya was himself a poet. Politically, after the defeat the military governors became independent statelets and southern India entered a new age of fragmentation that lasted until the British arrived.'] },
  d:'德里苏丹国南下压垮德干旧王朝后,两兄弟在通伽巴德拉河南岸建"胜利之城",挡住北方三百年;克里希纳提婆罗耶时国力最盛,首都人口数十万,葡萄牙人与更早一代的波斯使节都记下了它的规模。战马全靠海路进口是结构软肋,1565年塔利科塔战败后首都被洗劫数月,今日的汉皮遗址即由此而来。' },
{ l:'sa', s:'indic', v:1, n:'马拉塔', k:[[1674,0],[1707,.3],[1758,.55],[1761,.35],[1800,.3],[1818,0]], b:'从山地游击到印度最大势力;莫卧儿垮下去之后,接手的是它。',
  e:{ n:'the Marathas', b:'From hill-country raiding to the largest power in India; when the Mughals gave way, it was they who took over.', d:'Shivaji began by taking hill forts and used light cavalry to wear down twenty years of Mughal campaigning in the Deccan. After the empire lost its grip in 1707 the Marathas pushed north, reaching Attock by 1758 — the last time an Indian power held that line. The disaster at Panipat in 1761 ended the northern expansion, and after three Anglo-Maratha wars the territories were annexed to British India in 1818.', f:{ 'Peak':'around 1758 (its reach as far north as Attock)', 'Center':'Raigad, later Pune', 'Figures':'Shivaji, Baji Rao I', 'Legacy':'The hill-fort system, light-cavalry raiding and revenue-sharing' } },
  f:{ '鼎盛':'1758年前后(兵锋最北抵阿托克)', '中心':'赖加德→浦那', '人物':'希瓦吉、巴吉·拉奥一世', '成就':'山地要塞体系、包税与轻骑袭扰战法' },
  qh:{ born:['不打正面,只袭扰补给线','Never a pitched battle: raid the supply line instead'],
       rule:['扩张时效率极高,要统一决策就露短','Superb at expanding, weak whenever one decision was needed'],
       money:['不用占领就能抽税,所以只抽不治','It could tax without occupying, so it never governed'],
       power:['马拉地语里有句话:旗子插到阿托克','A Marathi phrase still says: the flag reached Attock'],
       fall:['几大家族互不统属,被一家家吃掉','The great houses answered to no one, and fell one by one'],
       legacy:['英国人在印度真正的对手,是它','In India, the real British opponent was this'] },
  q:{ born:['17世纪的德干由比贾布尔等苏丹国统治,马拉塔人是当地的农耕与军事群体,长期在各方军中当兵。希瓦吉从夺取一座座山地要塞起家,靠轻骑兵袭扰补给线、避免正面决战,逐步在西高止山一带建立起自己的地盘,1674年正式加冕为王。莫卧儿皇帝奥朗则布为消灭他和他的后继者而南征,前后二十余年未能成功,自己也死在德干。','The seventeenth-century Deccan was ruled by sultanates such as Bijapur, and the Marathas were a local farming and soldiering people who had long served in everyone\'s armies. Shivaji began by taking hill forts one at a time, using light cavalry to cut supply lines and refusing pitched battle, and built up his own territory along the Western Ghats, crowning himself king in 1674. The Mughal emperor Aurangzeb campaigned south to destroy him and his successors for more than twenty years without succeeding, and died in the Deccan himself.'],
      rule:['希瓦吉建立的是有薪官僚与常备军的体制,八部大臣分掌政务。但1707年之后重心转移:实权落到世袭宰相佩什瓦手中,王室退居象征地位。18世纪中期,马拉塔实际上是一个由几大家族(辛迪亚、霍尔卡尔、盖克瓦德、蓬斯莱)组成的联盟,各自据有一方、各有军队,以浦那的佩什瓦为盟主。这套结构扩张时效率极高,一旦需要统一决策就暴露弱点。','Shivaji built a state with salaried officials and a standing army under eight ministers. After 1707 the centre of gravity moved: real power passed to the hereditary chief minister, the Peshwa, and the royal house became symbolic. By the mid-eighteenth century the Marathas were in practice a confederacy of a few great houses — Scindia, Holkar, Gaekwad, Bhonsle — each holding its own country and army, with the Peshwa at Pune as head. The arrangement was highly efficient while expanding and showed its weakness whenever a single decision was needed.'],
      money:['财政的核心是两项征收权:向未被直接统治的地区收取相当于四分之一税收的"乔特",以及另外十分之一的"萨尔德什穆基"。这套做法让它不必占领就能抽取资源,扩张成本极低,但也意味着它长期是抽税者而非治理者。本土的西海岸则有港口贸易与造船业,安格雷家族的舰队一度让英国与葡萄牙船只都得纳买路钱。','Its finances rested on two claims: a levy of about a quarter of the revenue from territories it did not directly rule, and a further tenth on top. That let it extract resources without occupying, making expansion very cheap, but it also meant it long remained a taxer rather than a governor. At home the west coast supplied port trade and shipbuilding, and for a time the Angre family\'s fleet made even English and Portuguese ships pay for passage.'],
      power:['战法是轻骑兵与山地要塞的组合:不带辎重、长途奔袭、抢掠敌方补给,逼对手在不利地形上作战;境内数百座山堡互为犄角,失一座不伤全局。1707年奥朗则布死后帝国失序,马拉塔北上扩张,巴吉·拉奥一世多次奔袭德里以北,1737年一度兵临德里城下;到1758年势力最北抵达阿托克(今巴基斯坦西北),马拉地语里至今有句话叫「旗过阿托克」,说的就是这一次。','The method was light cavalry plus hill forts: move without baggage, strike far, take the enemy\'s supplies and force him to fight on ground of your choosing; hundreds of forts supported one another so that losing one cost little. After Aurangzeb died in 1707 the empire lost its grip and the Marathas pushed north, with Baji Rao I raiding repeatedly beyond Delhi and reaching its outskirts in 1737. By 1758 they had pushed as far north as Attock in what is now northwestern Pakistan — a reach still remembered in a Marathi phrase, \'the banner beyond Attock\'.'],
      fall:['1761年第三次帕尼帕特之战对阿富汗的杜兰尼军队大败,损失惨重,北方扩张就此中止。此后各大家族之间互不统属的弱点持续放大,常常各自与英国东印度公司缔约或作战。三次英国—马拉塔战争跨越四十年:1775—1782年打成平手,1803—1805年主力被击败,1817—1818年最后一战后佩什瓦被废黜、领地并入英属印度。','At the third battle of Panipat in 1761 they were badly beaten by the Afghan Durrani army, with heavy losses, and the northern expansion stopped there. The confederacy\'s want of a single command grew worse afterwards, with the great houses treating or fighting with the English East India Company separately. Three Anglo-Maratha wars ran across forty years: a draw in 1775–1782, a defeat of the main armies in 1803–1805, and after the last in 1817–1818 the Peshwa was deposed and the territories annexed to British India.'],
      legacy:['莫卧儿帝国名义上存在到1857年,但1707年之后它对印度大部分地区已无实际统治力——把这块权力接过去的主要就是马拉塔。也正因如此,英国人在印度真正的对手是马拉塔而非莫卧儿。希瓦吉在今天的马哈拉施特拉邦是最重要的历史符号,山地要塞群已列入世界文化遗产。轻骑袭扰与要塞体系的战法,也常被后世军事史著作引用。','The Mughal empire existed in name until 1857, but after 1707 it had no real hold over most of India — and the power that took that up was chiefly the Marathas. For the same reason, Britain\'s real opponent in India was the Marathas rather than the Mughals. Shivaji is the central historical symbol in present-day Maharashtra, and the hill forts are inscribed as World Heritage. The combination of light-cavalry raiding and a fortress network is still cited in military history.'] },
  d:'希瓦吉从夺山地要塞起家,以轻骑袭扰拖垮奥朗则布二十余年的南征;1707年后莫卧儿失序,马拉塔北上,1758年疆域最北抵阿托克——印度本土政权最后一次到达那里。1761年帕尼帕特惨败终止北扩,三次英马战争后于1818年并入英属印度。' },
{ l:'sa', s:'mideast', v:2, n:'莫卧儿帝国', k:[[1526,0],[1600,.8],[1700,.9],[1757,.4],[1857,0]], b:'鼎盛期约占世界经济四分之一;泰姬陵是其美学注脚。',
  e:{ n:'Mughal Empire', b:'A quarter of the world economy at peak; the Taj is its footnote.', d:'Babur, Timur\'s heir, took Delhi with guns; Akbar abolished the poll tax and married Rajput allies, and the empire peaked — Shah Jahan built the Taj for his empress. Aurangzeb\'s wars and rigidity hollowed it; a British company found its opening.', f:{ 'Peak':'Akbar to Aurangzeb (16th–17th c.)', 'Center':'Agra, later Delhi', 'Figures':'Akbar, Shah Jahan, Aurangzeb, Nur Jahan, Dara Shukoh', 'Legacy':'Taj Mahal, tolerant statecraft (Akbar)' } },
  f:{ '鼎盛':'阿克巴至奥朗则布(16—17世纪)', '中心':'阿格拉→德里', '人物':'阿克巴、沙贾汗、奥朗则布、努尔·贾汗、达拉·舒科', '成就':'泰姬陵、宗教宽容政策(阿克巴)' },
  qh:{ born:['一个中亚的失意者,在印度开了新局','A failure in Central Asia opened a new empire in India'],
       rule:['统治的秘诀不是压服,是让人入股','The trick was not subjugation but shareholding'],
       money:['鼎盛时约占世界经济的四分之一','At its height, about a quarter of the world economy'],
       power:['真正的强大不在火炮,在整合','The real strength was not the guns but the integration'],
       fall:['税又收回来了,盟友也就走了','The tax came back, and the allies left'],
       legacy:['帝国换了主人,那台机器还在转','The empire changed hands; the machine kept running'] },
  q:{ born:['帖木儿后裔巴布尔在中亚争位失败,转而南望印度;1526年帕尼帕特之战,他以火炮与野战工事击破德里苏丹的大军与战象——一个中亚的失意者,在印度开出一个新帝国。','Babur, a descendant of Timur who had lost out in Central Asia, turned his ambitions south. At Panipat in 1526 his cannon and field works shattered the Delhi sultan\'s host and its elephants — a Central Asian loser opened a new empire in India.'],
      rule:['靠曼萨布达尔体系:贵族按官阶领薪养兵,位子由皇帝授予而非世袭领地;阿克巴更进一步,废除人头税、与拉杰普特王族联姻,把被征服者变成帝国的合伙人——统治的秘诀不是压服,而是入股。','Through the mansabdar system: nobles held ranked offices with pay and troop quotas granted by the emperor, not hereditary lands. Akbar went further — abolishing the poll tax and marrying into Rajput royal houses — turning the conquered into partners of the empire. The secret of rule was not subjugation but shareholding.'],
      money:['一套精细的田赋制度把丰饶农业变成稳定国库,棉纺织品行销全球;鼎盛时它约占世界经济的四分之一,欧洲商人排着队用白银换印度的布。','A finely tuned land-revenue system turned rich agriculture into a steady treasury, and Indian cottons sold across the world. At its height the empire held roughly a quarter of the world economy, with European merchants queuing to pay silver for Indian cloth.'],
      power:['火药帝国的标配:火炮、火枪加机动骑兵;但真正的强大在整合——拉杰普特骑士、波斯文官、印度商人都能在体制里找到位置,帝国的军力与财力因此远超单一族群所能提供。','The standard kit of a gunpowder empire: cannon, muskets, and mobile cavalry. But its real strength was integration — Rajput knights, Persian administrators, and Indian merchants all found places in the system, giving the empire armies and revenues far beyond what any single group could supply.'],
      fall:['多因叠加:奥朗则布在德干数十年征战掏空国库,恢复人头税又疏远了印度教盟友;他身后继承内战不断,总督与马拉塔势力各自坐大,皇帝渐成傀儡;空心化的帝国给了一家英国公司可乘之机,1857年大起义后,末代皇帝被英国人废黜流放。','Causes stacked: Aurangzeb\'s decades of war in the Deccan drained the treasury, and restoring the poll tax alienated Hindu allies. After him, succession wars raged while governors and the Marathas built their own power and emperors faded into figureheads. The hollowed empire left an opening for an English company, and after the 1857 uprising the last emperor was deposed and exiled by the British.'],
      legacy:['泰姬陵与莫卧儿细密画是它的美学遗产;波斯-印度交融的宫廷文化与乌尔都语的成熟都在其治下;它的田赋册籍与行政区划,后来被英国人整套接手——帝国换了主人,机器还在运转。','The Taj Mahal and Mughal miniatures are its aesthetic bequest; the blended Persian-Indian court culture and the maturing of Urdu belong to its reign. Its revenue rolls and administrative map were taken over wholesale by the British — the empire changed owners, but the machine kept running.'] },
  d:'帖木儿后裔巴布尔以火器破德里;阿克巴废除异教人头税、与拉杰普特联姻,帝国臻于极盛,沙贾汗为亡妻建起泰姬陵。奥朗则布穷兵黩武且宗教政策转严,身后帝国迅速空心化——给了一家英国公司可乘之机。' },
{ l:'sa', s:'west', v:2, n:'英属印度', k:[[1757,0],[1858,.7],[1900,.75],[1947,0]], b:'从东印度公司到直辖殖民地,"帝国王冠上的明珠"。',
  e:{ n:'British Raj', b:'From company to crown; the jewel and its cost.', d:'A trading company ate the subcontinent by mercenaries and treaties; after the 1857 revolt the Crown ruled directly. Railways and telegraphs stitched India together while wealth drained to London; Gandhi\'s nonviolence mobilized millions to independence — and Partition\'s dead, counted in the hundreds of thousands or more.', f:{ 'Peak':'c. 1900', 'Center':'Calcutta → New Delhi', 'Figures':'Clive; Gandhi (resistance), Rabindranath Tagore, Rani Lakshmibai', 'Legacy':'Railway & telegraph net (double-edged)' } },
  f:{ '鼎盛':'1900年前后', '中心':'加尔各答→新德里', '人物':'克莱武;甘地(反抗方)、泰戈尔、拉克什米·芭伊', '成就':'铁路电报网络(殖民遗产双面)' },
  qh:{ born:['一家公司变成了政权,拿印度的税养兵','A trading company became a government, funded by Indian taxes'],
       rule:['「分而治之」是写在纸上的策略','Divide and rule was written policy, not a slur'],
       money:['本来出口布,后来只出口原料','Once it exported cloth; then only raw material'],
       power:['同一条铁路运兵,也在饥荒里运粮出口','The same rails moved troops, and grain out during famine'],
       fall:['独立了,代价是分治与迁徙中的死亡','Independence came, at the price of partition'],
       legacy:['一条仓促划下的线,至今还在消化','A line drawn in haste, still being digested'] },
  q:{ born:['莫卧儿空心化后,次大陆碎成互斗的诸侯,一家做贸易的英国公司看到了机会:1757年普拉西之战,东印度公司靠收买叛将击败孟加拉行省长官,随后攫取孟加拉的征税权——公司从此变成政权,再用印度的税养印度的佣兵,像滚雪球一样吞并次大陆。','With the Mughal empire hollow, the subcontinent broke into rival princes, and an English trading company saw its chance. At Plassey in 1757 the East India Company defeated the Nawab of Bengal by buying off his general, then seized Bengal\'s right to tax — a company became a state, using Indian revenue to pay Indian sepoys and snowballing across the subcontinent.'],
      rule:['极少数英国官员,加本地佣兵、土邦王公与文书系统的协作;「分而治之」是明写的策略——利用族群与教派的分野,防止再出现联合反抗;1857年大起义后,英王取代公司直接统治。','A tiny number of British officials, working through Indian sepoys, princely states, and local clerks. Divide and rule was explicit policy — playing on lines of community and creed to forestall another united revolt. After the 1857 uprising the Crown replaced the Company.'],
      money:['殖民经济的逻辑是单向抽取:印度的田赋供养殖民政府与军队,棉花、鸦片、茶叶等原料输出,英国工业品返销;曾经的纺织出口大国沦为原料产地与市场,财富持续外流伦敦——印度学者称之为「财富流失」。','The colonial economy ran on one-way extraction: Indian land revenue funded the colonial state and army; cotton, opium, and tea flowed out as raw materials while British manufactures flowed back in. A great textile exporter was remade into a supplier of raw goods and a captive market, with wealth draining steadily to London — what Indian scholars named the drain of wealth.'],
      power:['靠军事技术与组织的代差,更靠印度诸侯彼此为敌——各个击破从来比正面征服省力;铁路与电报把控制力送到每个角落,这张网既运兵,也把粮食运往出口港,哪怕内地正在闹饥荒。','It rested on a gap in military technology and organization, and even more on Indian princes fighting each other — defeating them one by one always cost less than outright conquest. Railways and telegraphs carried control to every corner; the same network moved troops, and moved grain to export ports even while inland districts starved.'],
      fall:['殖民统治的根基被一点点掏空:反复的大饥荒(1943年孟加拉饥荒饿死数百万人)暴露出政权对属民生命的漠视;甘地把民族主义变成亿万普通人的非暴力不合作;二战耗尽英国国力,1947年印度独立——但独立以印巴分治为代价,迁徙与仇杀夺走数十万乃至上百万生命。','The ground was cut from under colonial rule piece by piece: recurring famines — the Bengal famine of 1943 killed millions — exposed a state indifferent to its subjects\' lives, while Gandhi turned nationalism into nonviolent noncooperation by hundreds of millions. World War II exhausted Britain, and in 1947 India became free — at the price of Partition, whose migrations and massacres took hundreds of thousands of lives, by some estimates well over a million.'],
      legacy:['遗产是双面的,两面都要如实说:铁路、英语、议会与普通法框架沿用至今;同样真实的是财富外流、去工业化与反复饥荒,以及一条仓促划下的分治线——它留下的裂痕,南亚至今仍在消化。','The legacy is double-sided, and both sides are real: railways, English, parliamentary government, and the common-law framework endure to this day. Equally real are the drain of wealth, deindustrialization, recurring famine, and a hastily drawn Partition line — fractures South Asia is still digesting.'] },
  d:'一家公司靠佣兵与条约蚕食次大陆百年,1857年大起义后英王直接接管;铁路与电报把印度织成一体,财富却源源流向伦敦。甘地以非暴力不合作动员亿万民众,1947年独立并印巴分治——自由伴随着百万人殒命的迁徙仇杀。' },
{ l:'sa', s:'indic', v:0, n:'印度·南亚诸国', k:[[1947,0],[1991,.4],[2025,.6]], b:'分治后的印巴孟等国;印度已是人口第一大国与新兴大国。',
  e:{ n:'India & South Asia', w:'India', b:'Partition, wars, then the world\'s most populous rising power.', d:'Three India-Pakistan wars and mutual nuclear tests followed Partition; liberalization in 1991 unleashed IT-led growth. In 2023 India passed China as the most populous nation — one of the century\'s most watched rising powers.', f:{ 'Peak':'after 2020 (most populous country)', 'Center':'New Delhi, Mumbai, Bangalore', 'Figures':'Nehru, Ambedkar, Jinnah', 'Legacy':'IT services, world\'s largest elections' } },
  f:{ '鼎盛':'2020年后(人口第一大国)', '中心':'新德里、孟买、班加罗尔', '人物':'尼赫鲁、安贝德卡尔、真纳', '成就':'IT服务业、全球最大民主选举' },
  qh:{ born:['按宗教划一条线,上千万人被迫搬家','A line drawn by religion moved over ten million people'],
       rule:['一次大选,九亿以上选民登记','One general election, over nine hundred million voters'],
       money:['没走东亚的制造业路,走了软件和药','Not the East Asian factory road: software and medicine instead'],
       power:['2023年起,它是世界第一人口大国','Since 2023 it has been the most populous country'],
       fall:['1991年外汇只够撑几周,只好全面开放','In 1991 the reserves lasted weeks, and the economy opened'],
       legacy:['「阿拉伯数字」其实是从这里出去的','The Arabic numerals actually came from here'] },
  q:{ born:['1947年英属印度独立并分治为印度与巴基斯坦,1971年东巴基斯坦独立为孟加拉国。分治按宗教划线,引发了人类历史上规模最大的一次迁徙之一,上千万人跨界移动,伴随严重的暴力,克什米尔的归属争端也由此开始,至今未解。斯里兰卡、尼泊尔等国的现代国家形态也在这一时期确立。','British India became independent in 1947 and was partitioned into India and Pakistan, with East Pakistan becoming Bangladesh in 1971. Partition was drawn along religious lines and set off one of the largest migrations in human history, with well over ten million people crossing the new borders amid severe violence; the dispute over Kashmir began then and is unresolved. Sri Lanka, Nepal and others took their modern form in the same period.'],
      rule:['印度是联邦制议会民主国家,宪法1950年生效,是世界上最长的成文宪法。它保障普选权,并为历史上受压迫的种姓与部族设立了保留名额——这是安贝德卡尔起草时的核心考虑之一。选举规模是世界之最:一次大选有九亿以上选民登记。区域内其他国家的政体各不相同,巴基斯坦长期在民选与军政之间反复。','India is a federal parliamentary democracy whose constitution, in force since 1950, is the longest written constitution in the world. It guarantees universal suffrage and reserves places for castes and tribes historically excluded — a central concern of Ambedkar, who chaired its drafting. Its elections are the largest anywhere, with more than nine hundred million registered voters. Other states in the region differ: Pakistan has swung repeatedly between elected and military rule.'],
      money:['独立后前四十年实行以国有企业与许可证为核心的计划色彩经济,增长缓慢。1991年外汇危机迫使全面开放:取消许可证制度、放宽外资、降低关税,此后增速显著提高。它的产业结构与东亚不同——制造业占比不高,却在软件外包、制药(全球最大的仿制药供应国之一)与影视产业上占据了世界位置。','For four decades after independence it ran a planned-leaning economy of state enterprises and licences, and grew slowly. A foreign-exchange crisis in 1991 forced a full opening: the licence system was scrapped, foreign investment eased and tariffs cut, and growth rose markedly afterwards. Its industrial profile differs from East Asia\'s — manufacturing is a modest share, yet it holds a world position in software services, in pharmaceuticals as one of the largest suppliers of generic drugs, and in film.'],
      power:['人口与语言。2023年印度成为世界第一人口大国,劳动年龄人口仍在增加;英语的普及让它在全球服务业分工中占据独特位置。此外是长期投入的高等教育与科研体系:低成本航天(2014年首次尝试即成功进入火星轨道)、核能与信息技术都由此而来。','Population and language. India became the world\'s most populous country in 2023 and its working-age population is still growing; the spread of English gives it a particular place in the global division of service work. To that add long investment in higher education and research: low-cost spaceflight — its first attempt reached Mars orbit in 2014 — along with nuclear power and information technology.'],
      fall:['1991年的外汇危机是最近一次大的转折:外汇储备只够支付几周进口,印度不得不空运黄金抵押并向国际货币基金组织求援。危机迫使经济全面开放,此后三十年增速与产业结构都明显改变。这也是南亚各国经济政策的共同分水岭——多国在同一时期先后放开市场。','The foreign-exchange crisis of 1991 was the last great turning point: reserves covered only a few weeks of imports, and the country had to fly gold abroad as collateral and go to the International Monetary Fund. The crisis forced the economy open, and both growth and industrial structure changed markedly over the thirty years since. It was a shared dividing line for the region, with several South Asian economies liberalising around the same time.'],
      legacy:['数学上的零与十进位记数法从这里经阿拉伯世界传向全世界,今天所有人用的「阿拉伯数字」其实源于印度。佛教诞生于此并传遍东亚与东南亚。当代的输出包括软件服务、仿制药、瑜伽与宝莱坞;而「世界上规模最大的一次民主选举」这件事本身,也常被视为一项政治实验的持续记录。','Zero and the decimal place-value system passed from here through the Arab world to everyone else — the numerals the whole world calls Arabic in fact came from India. Buddhism was born here and spread across East and Southeast Asia. Contemporary exports include software services, generic medicines, yoga and Hindi cinema; and the fact of running the largest democratic election on earth is itself often treated as an ongoing political experiment worth recording.'] },
  d:'分治后印巴三次战争、双双拥核;印度以IT服务与人口红利崛起,2023年超过中国成为人口第一大国,是本世纪最受瞩目的新兴力量之一。' },
/* 东南亚 */
{ l:'se', s:'indic', v:1, n:'扶南', k:[[68,0],[300,.35],[550,.25],[627,0]], b:'湄公河三角洲最早的印度化古国,南海-印度洋贸易中转站。',
  e:{ n:'Funan', b:'The Mekong delta\'s first Indianized state; early global entrepôt.', d:'Known from Chinese envoys\' accounts, Funan held the sea route\'s choke point; its port Óc Eo has yielded Roman coins and Han mirrors — globalization\'s first reach into the region. Its Sanskrit kingship set Southeast Asia\'s pattern.', f:{ 'Peak':'3rd c. (Fan Shiman)', 'Center':'Óc Eo (Mekong delta)', 'Figures':'Fan Shiman', 'Legacy':'First Indianized kingship in SE Asia' } },
  f:{ '鼎盛':'3世纪(范蔓)', '中心':'俄厄(湄公河三角洲)', '人物':'范蔓', '成就':'东南亚最早的印度化王权' },
  qh:{ born:['把一个歇脚点,做成了一个国家','It turned a stopping place into a state'],
       rule:['不是印度人来统治,是本地人去取经','Not Indians ruling: locals borrowing the script'],
       money:['罗马金币和汉朝铜镜,在同一处出土','Roman coins and Han mirrors came out of the same site'],
       power:['它的武力,是给商路服务的','Its force existed to serve the trade route'],
       fall:['船能直穿海峡了,就不必在这歇脚','Once ships could cross the strait, no one needed to stop'],
       legacy:['印度化王权加港口立国,成了通用模板','Indianised kingship plus a port became the standard template'] },
  q:{ born:['公元初年的航海要沿岸而行、等季风换船,湄公河三角洲正卡在中国与印度之间的必经一站;扶南在此立国,把「歇脚点」做成了国家。','Sailing in the early centuries CE hugged the coast and waited on the monsoon, and the Mekong delta sat squarely on the required stopover between China and India. Funan built a state there — turning a rest stop into a kingdom.'],
      rule:['靠一套进口的王权剧本:本地首领采用印度的梵文头衔、婆罗门仪式与神话谱系,给权力镀上神圣外衣——不是印度人来统治,而是本地人主动取经;它因此被称作东南亚最早的印度化政权。','Through an imported script of kingship: local chiefs adopted Sanskrit titles, Brahmin ritual, and Indian mythic genealogies to gild their power with sanctity. It was not Indians ruling — locals chose the playbook themselves — and Funan is thus called Southeast Asia\'s first Indianized state.'],
      money:['港口吃四方:俄厄遗址同时出土罗马金币、汉朝铜镜与印度饰物,证明公元初年的「全球化」已在此换手;腹地开凿运河,兼营三角洲稻作。','The port fed on all directions: the site of Oc Eo yields Roman coins, Han bronze mirrors, and Indian ornaments together — proof that the globalization of the early centuries already changed hands here. Inland, canals were dug and delta rice was farmed.'],
      power:['据康泰等中国使者的记载,国王范蔓造大船、征服邻邦,势力沿海岸延伸;控制的港口越多,商船越绕不开它——它的武力是为商路服务的。','According to Chinese envoys like Kang Tai, King Fan Man built great ships and subdued his neighbors, extending power along the coast. The more ports it held, the less ships could avoid it — its force existed to serve the trade route.'],
      fall:['主流看法是多因叠加:航海技术进步后,商船可以直穿马六甲海峡,不再需要沿岸中转,扶南的枢纽地位被苏门答腊一侧取代;内部则有属国真腊坐大,7世纪前后将其兼并。','The mainstream view is stacked causes: as seamanship improved, ships sailed straight through the Malacca Strait and no longer needed the coastal stopover, and the hub role shifted toward Sumatra. Meanwhile its vassal Chenla grew strong inland and absorbed it around the seventh century.'],
      legacy:['它开创的「印度化王权+港口立国」模式,成为此后千年东南亚政权的通用模板;高棉文明正是从扶南与真腊的土壤里长出来的。','Its model — Indianized kingship plus a state built on ports — became the standard template for Southeast Asian polities for the next thousand years, and Khmer civilization grew from the soil of Funan and Chenla.'] },
  d:'三国时吴使康泰笔下的"扶南"扼海上丝路要冲,俄厄遗址同时出土罗马金币与汉朝铜镜——公元初年的"全球化"已然抵达此地;其印度化的王权与梵文传统,开东南亚风气之先。' },
{ l:'se', s:'indic', v:0, n:'三佛齐', k:[[650,0],[900,.4],[1100,.3],[1288,0]], b:'苏门答腊海上帝国,凭马六甲海峡关税立国六百年。',
  e:{ n:'Srivijaya', b:'Six centuries taxing the Strait of Malacca.', d:'The Sumatran sea empire lived off the Malacca Strait for six centuries; the pilgrim Yijing studied Sanskrit here and ranked its Buddhist learning with India\'s. The Chola raid of 1025 broke its grip; Java and Malacca inherited the trade.', f:{ 'Peak':'9th–10th c.', 'Center':'Palembang', 'Figures':'Balaputradewa', 'Legacy':'Strait control, Mahayana scholarship' } },
  f:{ '鼎盛':'9—10世纪', '中心':'巨港', '人物':'巴拉普特拉', '成就':'控扼马六甲海峡、大乘佛教学术中心' },
  qh:{ born:['巨港正卡在咽喉上,这就是全部','Palembang sat on the throat, and that was everything'],
       rule:['不是一个疆域国家,是港口联盟的盟主','Not a territorial state, but the head of a league of ports'],
       money:['六百年,吃住了这条黄金水道','Six hundred years living off one golden waterway'],
       power:['佛学之盛,当时被拿来和印度比','Its Buddhist learning was compared with India itself'],
       fall:['先被跨海偷袭,再被爪哇一口口吃掉','Raided from across the sea, then eaten by Java'],
       legacy:['马六甲后来完整照抄了这套剧本','Malacca later copied the whole script'] },
  q:{ born:['商船改走直穿马六甲海峡的航线后,谁扼住海峡,谁就扼住东西方贸易;苏门答腊的巨港恰在咽喉上,7世纪的三佛齐把这个位置变成国家的全部——海峡过路费的接力,从它这第一棒传起。','Once ships took the route straight through the Strait of Malacca, whoever held the strait held East-West trade. Palembang on Sumatra sat right at the throat, and seventh-century Srivijaya made that position the whole basis of a state — the relay of strait tolls begins with this first runner.'],
      rule:['它不是疆域国家,而是港口联盟的盟主:靠舰队武力加利润分成让沿岸各港臣服,谁不合作就封锁谁;对中国按时朝贡,把天朝的册封变成盟主地位的背书。','It was not a territorial state but the chief of a league of ports: fleets plus profit-sharing kept the harbor towns loyal, and blockade awaited any that defected. Regular tribute to China converted the emperor\'s recognition into a warrant for its supremacy.'],
      money:['核心生意是海峡过路费:过往商船被引入——必要时强制——它的港口交易、补给并抽税;香料、香木、锡与中国瓷器在此转手,六百年吃住这条黄金水道。','The core business was the strait toll: passing ships were channeled — by force when needed — into its ports to trade, resupply, and pay duties. Spices, aromatic woods, tin, and Chinese ceramics changed hands here, and for six centuries it lived off the golden waterway.'],
      power:['舰队控制海峡两端,这是硬实力;软实力是佛教:义净称其佛学之盛可比印度,各国僧人往来停驻,声望本身就是招商与结盟的资本。','Fleets holding both ends of the strait were the hard power. The soft power was Buddhism: the pilgrim Yijing judged its scholarship a match for India\'s, monks from many lands stopped and studied there, and that prestige was itself capital for commerce and alliance.'],
      fall:['多因叠加:1025年朱罗舰队跨洋突袭诸港,霸权根基受创;此后爪哇势力在东侧步步进逼,各港见盟主疲弱纷纷自谋出路;13世纪末被爪哇政权吞并,商路霸权由爪哇与后起的马六甲接力继承。','Causes stacked: the Chola ocean raid of 1025 struck its ports and cracked the foundation of its supremacy; Javanese power then pressed from the east while member ports drifted away from a weakening chief. By the late thirteenth century it was absorbed by Javanese power, and its command of the trade route passed by relay to Java and then Malacca.'],
      legacy:['它示范了「不占土地,占航道」的立国方式,马六甲日后完整复刻了这套剧本;马来世界的海洋传统与巨港的传说记忆,都从它开始。','It demonstrated how to found a state on sea lanes rather than land — a script Malacca would later replay in full. The maritime tradition of the Malay world, and the legendary memory of Palembang, both begin with it.'] },
  d:'苏门答腊的海上帝国凭马六甲海峡的关税立国六百年,唐僧义净取经途中曾在此研习梵文数年,称其佛学之盛可比印度;1025年朱罗舰队跨洋突袭后元气大伤,商路霸权终被爪哇与马六甲继承。' },
{ l:'se', s:'indic', v:2, n:'高棉·吴哥', k:[[802,0],[1150,.6],[1218,.55],[1350,.3],[1431,0]], b:'以水利养起七八十万人的城市群;吴哥窟一般被认为是世界最大的宗教建筑群。',
  e:{ n:'Khmer / Angkor', w:'Khmer Empire', b:'A hydraulic landscape supporting several hundred thousand; Angkor Wat.', d:'Angkor\'s kings tamed the monsoon with vast reservoirs and canals, feeding possibly a million people; Angkor Wat shifted from Vishnu temple to Buddhist shrine — religious strata in stone. Siamese pressure and failing waterworks emptied the city and the jungle took most of the temples, though monks never left Angkor Wat itself; the nineteenth-century rediscovery is a European way of putting it.', f:{ 'Peak':'12th c.', 'Center':'Angkor', 'Figures':'Suryavarman II, Jayavarman VII', 'Legacy':'Angkor Wat, giant waterworks' } },
  f:{ '鼎盛':'12世纪(苏利耶跋摩二世)', '中心':'吴哥', '人物':'苏利耶跋摩二世、阇耶跋摩七世', '成就':'吴哥窟、巨型水利系统' },
  qh:{ born:['一片湖的鱼加一片稻田,养出了霸主','Fish from one lake and rice from one plain made a power'],
       rule:['为神修庙,和为国储水,常是同一件事','Building for the god and storing water were one job'],
       money:['一个内陆帝国,养活了七八十万人','An inland empire feeding some three quarters of a million'],
       power:['能挖水库的组织力,也能动员大军','The hands that dug reservoirs could also raise armies'],
       fall:['水利越修越难,最后转不动了','The waterworks grew harder to keep, and then failed'],
       legacy:['一座消失的都城,至今印在国旗上','A vanished capital is still on the national flag'] },
  q:{ born:['802年,阇耶跋摩二世自立为「转轮圣王」,统一高棉诸邦;洞里萨湖的鱼与洪泛平原的稻米提供了人口底盘,吴哥地区从此成为中南半岛的权力中心。','In 802 Jayavarman II proclaimed himself universal monarch and united the Khmer principalities. The fish of the Tonle Sap and the rice of its floodplain supplied the demographic base, and the Angkor region became the power center of mainland Southeast Asia.'],
      rule:['靠「神王」体制:王被奉为神在人间的化身,巨型神庙既是宗教中心,也是登记土地、储粮放贷的行政节点;为神修庙与为国储水,常常是同一项工程。','Through the god-king order: the ruler was honored as a deity\'s presence on earth, and the great temples served both as religious centers and as administrative nodes that registered land, stored grain, and lent seed. Building for the god and storing water for the state were often the same project.'],
      money:['财富长在水上:巨大的水库与运河网驯服季风,旱季有水,雨季不涝,稻作盈余养活了大吴哥地区七八十万人,在当时的世界屈指可数;它是内陆农业帝国,钱粮主要来自田亩而非海贸。','Wealth grew on water: vast reservoirs and canal networks tamed the monsoon — water in the dry season, drainage in the wet — and the rice surplus fed a capital region of some seven or eight hundred thousand. An inland agrarian empire, its revenue came from fields rather than sea trade.'],
      power:['能动员十几万人挖水库、建吴哥窟的组织力,同样能动员大军;鼎盛时高棉的势力覆盖今柬埔寨,并深入今泰国、老挝与越南南部,是中南半岛无可争议的霸主。','The organizing power that could set a hundred thousand people digging reservoirs and raising Angkor Wat could raise armies too. At its height Khmer power covered Cambodia and reached deep into today\'s Thailand, Laos, and southern Vietnam — the unquestioned hegemon of the mainland.'],
      fall:['主流看法是多因叠加:近年研究认为,庞大的水利系统年久淤塞,又赶上旱涝剧烈交替的气候波动,越修越难,终至失灵;同时西侧的暹罗(阿瑜陀耶)崛起并反复进攻,1431年吴哥城破;王室南迁湄公河一带,巨城逐渐还给了丛林。','The mainstream view is stacked causes: recent research holds that the huge water network silted up over the centuries and then met wild swings of drought and flood, becoming ever harder to repair until it failed. Meanwhile Ayutthaya rose to the west and attacked repeatedly, sacking Angkor in 1431; the court moved south toward the Mekong, and the great city was slowly returned to the forest.'],
      legacy:['吴哥窟一般被认为是世界最大的宗教建筑群,从毗湿奴神庙渐变为佛寺,一座建筑记录了信仰的更替;它至今印在柬埔寨国旗上——一个消失的都城,仍是一个民族的身份坐标。','Angkor Wat is generally reckoned the largest religious monument on earth, and its shift from Vishnu temple to Buddhist shrine records a change of faith within a single building. It appears on Cambodia\'s flag to this day — a vanished capital that still anchors a nation\'s identity.'] },
  d:'吴哥诸王以庞大的水库与运河驯服季风,养活了大吴哥地区七八十万人;吴哥窟从印度教毗湿奴神庙渐变为佛寺,是宗教叠层的活化石。暹罗兴起与水利失修后城市废弃,大部分神庙被丛林吞没,但吴哥窟一直有僧人守着;19世纪法国博物学家的「重新发现」是欧洲视角的说法。' },
{ l:'se', s:'sino', v:1, n:'大越', k:[[938,0],[1010,.25],[1428,.3],[1802,.3],[1884,0]], b:'脱离千年郡县自立,却承汉字科举儒制,中华圈最南端。',
  e:{ n:'Đại Việt', b:'Independent of China yet Confucian to the core; thrice repelled the Mongols.', d:'Independent in 939 after a millennium of Chinese rule, yet it kept Chinese script, examinations and Confucian governance — the sinosphere\'s southern edge. It repelled the Mongols three times and pushed steadily south over Champa before falling to France.', f:{ 'Peak':'15th c. (Le Thanh Tong)', 'Center':'Thăng Long (Hanoi)', 'Figures':'Ly Thai To, Tran Hung Dao', 'Legacy':'Thrice repelled Mongols, chữ Nôm' } },
  f:{ '鼎盛':'15世纪(黎圣宗)', '中心':'升龙(河内)', '人物':'李太祖、陈兴道', '成就':'三度击退蒙古、喃字' },
  qh:{ born:['北边一乱,南边的窗口就打开了','Chaos in the north opened a window in the south'],
       rule:['对外称藩,关起门来自称皇帝','A vassal abroad, an emperor at home'],
       money:['国境往南走,耕地也跟着往南走','The border moved south, and the fields moved with it'],
       power:['守北,攻南——几百年的基本盘','Hold the north, push the south: the pattern for centuries'],
       fall:['代差太大,对方还有现成的开战借口','The gap was too wide, and the pretext was ready'],
       legacy:['「以小抗大」的记忆,成了民族认同','The memory of the small resisting the large became identity'] },
  q:{ born:['唐末中原大乱,对最南端的控制随之失灵;938年白藤江之战,吴权以藏在江底的木桩阵大破南汉水军,千年郡县统治就此终结——中央帝国的衰弱窗口,给了边地自立的机会。','As Tang China fell into chaos, its grip on the far south failed. At the Bach Dang River in 938, Ngo Quyen impaled the Southern Han fleet on stakes hidden beneath the tide, ending a thousand years of Chinese county rule — a border land seized its chance in the empire\'s weak hour.'],
      rule:['剧本全盘取自中华:汉字、科举、儒家官僚体制一样不少;对外的姿态却是双面的——对中国称藩纳贡,关起门来自家称皇帝,史家称之为「外王内帝」。','The playbook was taken wholesale from China: Chinese characters, civil-service exams, a Confucian bureaucracy. Its posture, though, was two-faced by design — a tributary vassal toward China, an emperor at home — what historians call king abroad, emperor within.'],
      money:['红河三角洲的水稻是国本,堤坝与圩田一代代加密;对华贸易与陶瓷外销添利;后期数百年「南进」,把占婆与湄公河三角洲的土地渐次纳入,耕地随国境一起南移。','Red River delta rice was the foundation, its dikes and polders thickened generation by generation, with China trade and ceramic exports adding profit. Then came centuries of the southward march: Champa and the Mekong delta were absorbed step by step, farmland moving south with the border.'],
      power:['强在地利与韧性:热带丛林、水网与瘴气消磨北来的大军;13世纪三度击退蒙古入侵,1288年陈兴道在白藤江故技重施,以桩阵再歼敌舰;对南方则以人口与组织优势步步推进——守北攻南,是它数百年的基本盘。','Its strength was terrain and tenacity: jungle, waterways, and disease wore down invaders from the north, and Mongol invasions were repelled three times — in 1288 Tran Hung Dao reused the old stake trap at Bach Dang to destroy the enemy fleet. Southward, greater numbers and organization ground steadily forward: defend the north, advance the south was its centuries-long formula.'],
      fall:['多因叠加:16世纪起南北权臣长期分治(北郑南阮),内耗两百余年;19世纪初阮朝重新统一,却面对法国炮舰与巨大的技术代差,禁教政策又给了对方开战的借口;1884年沦为法国保护国,千年自立告一段落。','Causes stacked: from the sixteenth century rival lords — Trinh in the north, Nguyen in the south — split the realm in an internal standoff of two centuries. The Nguyen dynasty reunified the country in the early nineteenth century, but faced French gunboats across a vast technology gap, and its persecution of missionaries handed France a pretext for war. In 1884 it became a French protectorate, closing a millennium of independence.'],
      legacy:['它把中华制度移植到东南亚并活成自己的东西:喃字、越南儒学与科举传统;数百年南进划出的疆域,大体就是今日越南的版图;「以小抗大」的抵抗记忆,至今是越南认同的核心。','It transplanted the Chinese institutional package into Southeast Asia and made it its own: the Nom script, Vietnamese Confucianism, the exam tradition. The southward march drew, in outline, the map of today\'s Vietnam, and the memory of the small resisting the large remains the core of Vietnamese identity.'] },
  d:'939年脱离中国千年郡县统治自立,却全盘沿用汉字、科举与儒家官制,是中华文明圈的最南端;曾三度击退蒙古入侵,此后数百年不断南进吞并占婆,19世纪沦为法国殖民地。' },
{ l:'se', s:'indic', v:1, n:'蒲甘', k:[[1044,0],[1120,.4],[1200,.35],[1250,.25],[1297,0]], b:'伊洛瓦底江边的佛塔之城:两千多座砖塔至今还立在平原上。',
  e:{ n:'Pagan', w:'Pagan Kingdom', b:'A city of pagodas on the Irrawaddy: more than two thousand brick temples still stand on the plain.', d:'When the Pyu faded the Burmans came down the Irrawaddy, and in 1044 Anawrahta welded the small polities into one state and went south against the Mon, bringing back monks, scriptures and craftsmen. Theravada Buddhism became the religion of the state and has been Burma\'s ground colour ever since. Over two centuries something like ten thousand temples went up, of which about 2,200 survive; the four-language Myazedi inscription of 1113 later became the key to reading Pyu. Tax-free monastic land ate the revenue base, politics loosened, and Yuan armies pressed down from Yunnan — but the Mongols did not destroy the city, and most of the temples are still there.', f:{ 'Peak':'late 11th to 12th c.', 'Center':'Bagan', 'Figures':'Anawrahta', 'Legacy':'The temples of Bagan, a Theravada state, the Burmese script' } },
  f:{ '鼎盛':'11世纪末—12世纪', '中心':'蒲甘', '人物':'阿奴律陀', '成就':'蒲甘佛塔群、上座部佛教立国、缅文的形成' },
  qh:{ born:['他做的更像是把已有的信仰立为国教','What he did was make an existing faith the state one'],
       rule:['献给寺院的地不用交税,还收不回来','Land given to monasteries paid no tax and never came back'],
       money:['卖林产、宝石,还有王室专营的大象','Timber, gems, and elephants under royal monopoly'],
       power:['力气花在造塔,不在打仗','The effort went into pagodas, not campaigns'],
       fall:['真正拖垮它的是财政,蒙古只是最后一推','Finance broke it; the Mongols were only the last push'],
       legacy:['今天还在用的缅文,是那时候定型的','The Burmese script still in use took shape then'] },
  q:{ born:['伊洛瓦底江中游的干燥平原本是骠人诸城的地界,骠人衰落后缅人南下接手。1044年阿奴律陀即位,把周边小邦并成一个国家,并向南攻取孟人的直通——这一趟带回的不只是战利品,还有孟人的僧团、经卷与工匠。上座部佛教由此被立为国教,缅甸此后一千年的信仰格局在这几十年里定下来——不过「佛教是这一趟带回来的」出自18世纪以后的缅甸编年史,更早的碑铭显示上座部在此之前已有传播,他做的更像是把一种既有的信仰立为国教。','The dry middle plain of the Irrawaddy had belonged to the Pyu city-states; when the Pyu faded the Burmans came down and took it over. Anawrahta came to the throne in 1044, welded the small polities around him into one state, and went south against the Mon at Thaton — bringing back not only plunder but Mon monks, scriptures and craftsmen. Theravada Buddhism was made the religion of the state, and the religious shape of Burma for the next thousand years was settled in those few decades — though the story that Buddhism arrived on that campaign comes from Burmese chronicles of the eighteenth century and later, while earlier inscriptions show Theravada was already present; what he did looks more like making an existing faith official.'],
      rule:['王权靠功德合法化:国王建塔造寺,僧团回以承认。这套逻辑的副作用在两百年后显出来——献给寺院的土地免税、且不可回收,称为「僧地」,越积越多,王室能征税的地反而越来越少。这不是缅甸独有的问题,中古欧洲与日本的寺社领也走过同一条路。','Kingship was legitimised by merit: the king built pagodas and monasteries, and the order acknowledged him in return. The side effect showed up two centuries later — land given to monasteries was tax-free and could not be taken back, and as this glebe land piled up the crown had less and less it could tax. The problem was not peculiar to Burma; monastic estates in medieval Europe and Japan went the same way.'],
      money:['干旱区的灌溉稻作是底盘,王室维护堰渠、组织劳役。它同时卡在两条路上:伊洛瓦底江的水路直通印度洋,陆路则向北通往云南与四川。中国与印度的货物在这里过手,而它自己卖出去的是林产、宝石与大象(大象由王室专营)。','Irrigated rice in the dry zone was the base, with the crown keeping up the weirs and organising the labour. It also sat on two routes: the Irrawaddy running down to the Indian Ocean, and overland tracks north into Yunnan and Sichuan. Chinese and Indian goods changed hands here, while what it sold was forest products, gems and elephants, the last a royal monopoly.'],
      power:['它的力量更多花在营建而不是征战上:两百多年间在蒲甘平原上造了上万座塔寺,今天还立着约两千二百座。这个数量本身就是国力的证明——需要长期稳定的粮食盈余、组织化的工匠与持续的王室意志。1113年立的妙齐提碑用骠文、孟文、缅文、巴利文四种文字刻同一段话,后来成了释读骠文的钥匙,作用与罗塞塔石碑相同。','Its strength went into building rather than campaigning: over two centuries something like ten thousand temples and pagodas went up on the Bagan plain, of which about 2,200 still stand. The number is itself the proof of state capacity — it needs a long run of surplus grain, organised craftsmen and an unbroken royal will. The Myazedi inscription of 1113 carries the same passage in Pyu, Mon, Burmese and Pali, and later became the key to reading Pyu, doing the work the Rosetta Stone did.'],
      fall:['13世纪后期几件事叠在一起:僧地侵蚀税基、王室与地方的关系松动,而北面的蒙古人已经压到云南。1277至1287年间元军数次南下,1287年前后攻至蒲甘一带(是否进城学界有争议,近年研究倾向于没有);此后王国分裂为若干小邦,1297年一般被当作它作为统一政权的终点。要说清楚的是:蒙古人并没有摧毁这座城,塔寺大多留了下来——真正让它衰落的是财政与政治,蒙古只是最后一推。','Several things came together in the later thirteenth century: monastic land had eaten into the tax base, the crown\'s hold on the regions had loosened, and the Mongols were already pressing down through Yunnan. Yuan armies came south repeatedly between 1277 and 1287 and reached the country around Bagan; whether they entered the city is disputed and recent work suggests they did not. The kingdom then broke into smaller states, and 1297 is generally taken as the end of it as a single polity. One thing should be said plainly: the Mongols did not destroy the city, and most of the temples survived — what actually brought it down was fiscal and political, and the Mongols were only the last push.'],
      legacy:['上座部佛教在这里立国,此后成为缅甸的底色,也与泰国、老挝、柬埔寨连成同一个佛教世界。缅文在这一时期从孟文与骠文的书写传统中定型,今天仍在用。蒲甘平原上的塔寺经历过多次地震(2016年那次损毁不小),修复方式也长期有争议——早年用水泥补,被批评为破坏原貌;2019年终于列入世界遗产。','Theravada Buddhism was made the religion of a state here, became the ground colour of Burma, and joins it to Thailand, Laos and Cambodia in one Buddhist world. The Burmese script took its settled form in this period out of Mon and Pyu practice, and is still in use. The temples on the plain have been through repeated earthquakes — the one in 2016 did considerable damage — and how to repair them has long been argued over, with early cement patching criticised for spoiling the originals. It became a World Heritage site in 2019.'] },
  d:'骠人衰落后缅人南下,1044年阿奴律陀即位,并小邦为一国,南取孟人的直通,带回僧团经卷与工匠,上座部佛教由此立国。两百多年在平原上造了上万座塔寺,今存约两千二百座;1113年的妙齐提四语碑后来成了释读骠文的钥匙。僧地免税侵蚀税基、政治松动,加上1277—1287年元军数次南下压境,1297年作为统一政权终结——但城与塔大多留了下来。' },
{ l:'se', s:'sea', v:1, n:'阿瓦·勃固', k:[[1287,0],[1360,.2],[1430,.28],[1470,.33],[1520,.2],[1555,0]], b:'蒲甘倒下后,缅甸分成说两种话的上下两半,打了两百年;下半边出过一位女王,把与自己体重相等的黄金捐给了大金塔。',
  d:'1287 年蒙古军南下、蒲甘瓦解之后,缅甸分成说两种话的两半:上缅甸是说缅语的一串小朝廷,几十年里都城换了三次,1364 年才定在阿瓦(今因瓦);下缅甸的孟人 1287 年在马都八立国,1369 年迁到勃固。两边为争夺伊洛瓦底江下游打了四十年(1385—1424),谁也吞不掉谁。下缅甸靠海,和马六甲、斯里兰卡、印度往来密切,反而更富。1453 年信修浮成为勃固的女王——东南亚少有的女性君主;她把大金塔加到约四十米,并捐出与自己体重相等的黄金,第一次给整座塔贴上金箔,又亲自挑了一位僧侣出身的继承人达摩悉提。达摩悉提整顿僧团、与斯里兰卡重新接上戒法,还铸了一口巨大的铜钟。16 世纪初东吁王朝从内陆兴起,把上下缅甸重新合成一个国家,这两百多年的分立到此结束。',
  e:{ n:'Ava and Pegu', w:'Kingdom of Ava', b:'After Pagan fell Burma split into two halves speaking two languages — and the lower half had a queen who gave the Shwedagon her own weight in gold.', d:'After Mongol armies came south in 1287 and Pagan came apart, Burma divided into two halves speaking two languages: upper Burma was a succession of small Burmese-speaking courts that moved capital three times before settling at Ava — today\'s Inwa — in 1364; the Mon of the lower country founded their kingdom at Martaban in 1287 and moved to Pegu in 1369. They fought forty years over the lower Irrawaddy (1385—1424) without either swallowing the other. The lower kingdom, facing the sea and trading with Malacca, Sri Lanka and India, was the richer of the two. In 1453 Shin Sawbu became queen of Pegu — a rare female sovereign in Southeast Asia; she raised the Shwedagon to about forty metres and gave her own weight in gold to have the whole of it gilded for the first time, and chose as her successor a monk, Dhammazedi. He reformed the monastic order, re-established its ordination line with Sri Lanka, and cast an enormous bronze bell. In the early sixteenth century the Toungoo dynasty rose from the interior and put the two halves back together, ending this long division.', f:{ 'Peak':'Shin Sawbu and Dhammazedi (1453—1492)', 'Center':'Ava; Pegu', 'Figures':'Shin Sawbu; Dhammazedi', 'Legacy':'The first full gilding of the Shwedagon; a reformed monastic order' } },
  f:{ '鼎盛':'信修浮与达摩悉提(1453—1492)', '中心':'阿瓦、勃固', '人物':'信修浮、达摩悉提', '成就':'大金塔的第一次整体贴金、僧团戒法的重整' },
  qh:{ born:['蒲甘倒了,缅甸裂成说两种话的上下两半','Pagan fell and Burma split in two, by language'],
       rule:['上边靠田,下边靠海,谁也吞不掉谁','The upper half lived on fields, the lower on the sea'],
       money:['海边那一半更富,因为船都停在那里','The seaward half was richer — the ships stopped there'],
       power:['为一条江的下游,打了四十年','Forty years of war over the lower reaches of one river'],
       fall:['内陆冒出一股新势力,把两半重新缝上','A new power rose inland and stitched the halves together'],
       legacy:['一位女王捐出与自己体重相等的黄金','A queen gave her own weight in gold'] },
  q:{ born:['1287 年蒙古军南下,蒲甘王朝瓦解。缅甸此后分成说两种话的两半:上缅甸的缅语朝廷几十年里换了三处都城,1364 年才定在阿瓦(今因瓦);下缅甸的孟人 1287 年在海边的马都八立国,1369 年迁到勃固。这不是一次改朝换代,而是一个国家沿着语言和地理裂成了两个。','Mongol armies came south in 1287 and the kingdom of Pagan came apart. Burma then lay in two halves speaking two languages: the Burmese-speaking north moved capital three times before settling at Ava — today\'s Inwa — in 1364, while the Mon founded their kingdom on the coast at Martaban in 1287 and moved to Pegu in 1369. This was not one dynasty replacing another but a country splitting along language and geography.'],
      rule:['两边各按各的条件立国。上缅甸守着伊洛瓦底江中游的稻田与灌溉渠,王权靠土地与僧团;下缅甸面朝安达曼海,靠港口与关税,王室直接参与海上贸易。缅语文学在阿瓦成熟,而勃固的宫廷同时用孟语与巴利语——同一片土地上,两套文字各写各的。','Each half built on what it had. Upper Burma held the rice land and irrigation of the middle Irrawaddy, and its kings rested on land and the monastic order; lower Burma faced the Andaman Sea and lived on ports and customs, its royal house trading at sea directly. Burmese literature came of age at Ava, while the court at Pegu worked in Mon and Pali — two written traditions on one piece of ground.'],
      money:['勃固与马六甲、斯里兰卡、印度南部往来密切,出口大米、柚木与宝石,换回棉布与瓷器;上缅甸的财富主要是稻田和玉石,要往下走这条江才能出海——而江口在对方手里。这条差别是两边打了两百年的根本原因。','Pegu traded with Malacca, Sri Lanka and southern India, sending out rice, teak and gems for cotton and porcelain; upper Burma\'s wealth was paddy and jade, and to reach the sea it had to go down the river — whose mouth the other side held. That difference is why the two fought for two centuries.'],
      power:['1385 到 1424 年的四十年战争打的就是伊洛瓦底江下游。双方都用象兵与河上的战船,战线沿着江来回移动,谁也没能把对方吃掉。战争间隙两边照样通商、通婚、互派僧人——打仗和过日子是并行的。','The Forty Years\' War, from 1385 to 1424, was fought over the lower Irrawaddy. Both sides used war elephants and river fleets, the front moving up and down the river, neither able to finish the other. Between campaigns they went on trading, intermarrying and exchanging monks — the fighting ran alongside ordinary life rather than replacing it.'],
      fall:['16 世纪初,内陆的东吁先夺下沿海,由此拿到火器与葡萄牙雇佣兵,力量迅速滚大:1539 年攻下勃固、1555 年取阿瓦,把上下缅甸重新合成一个国家。分立了两百多年的两半,最后是被第三方缝起来的。','In the early sixteenth century Toungoo, an inland state, took the coast first and with it the firearms and Portuguese mercenaries that made it grow fast: Pegu fell in 1539 and Ava in 1555, and put the country back together. The two halves, apart for over two centuries, were finally joined by a third party.'],
      legacy:['最看得见的遗产在仰光。信修浮把大金塔加到约四十米,并且第一次给整座塔贴上金箔——她捐的是与自己体重相等的黄金;她的继承人达摩悉提又加了更多。此后五百年人人往上加金,而今天看到的九十九米,是 1768 年地震震塌塔顶之后、1775 年重修的结果。一座塔的高度,是一层层捐上去的。达摩悉提本人是僧侣出身,他整顿僧团、派人去斯里兰卡重新接上戒法,这套戒统缅甸沿用至今;他还铸过一口巨钟,1608 年被葡萄牙人抢走时沉进了河里,四百年来找了很多次,始终没有找到。','The most visible legacy stands in Yangon. Shin Sawbu raised the Shwedagon to about forty metres and had the whole of it gilded for the first time, giving her own weight in gold for the leaf; her successor Dhammazedi added more. People went on adding gold for five centuries after that, and the ninety-nine metres seen today date from the rebuilding of 1775, after an earthquake brought the crown down in 1768. The height of that stupa was donated onto it, layer by layer. Dhammazedi had been a monk; he reformed the order and sent men to Sri Lanka to re-establish its ordination line, which Burma follows to this day. He also cast a great bell, which sank in the river in 1608 as the Portuguese were carrying it off, and four centuries of searching have not found it.'] } },
{ l:'se', s:'indic', v:2, n:'满者伯夷', k:[[1293,0],[1350,.5],[1389,.45],[1478,.15],[1527,0]], b:'击退元军后立国,号令群岛,今日印尼版图的历史蓝本。',
  e:{ n:'Majapahit', b:'Java\'s island hegemon; blueprint of Indonesia\'s imagined map.', d:'Founded after repelling Kublai\'s fleet, at peak it claimed most of the archipelago — the historical blueprint of modern Indonesia\'s map. It fell as Islamic sultanates rose; its Hindu remnant still lives on Bali.', f:{ 'Peak':'mid-14th c. (Gajah Mada)', 'Center':'east Java', 'Figures':'Gajah Mada', 'Legacy':'Loose archipelago hegemony' } },
  f:{ '鼎盛':'14世纪中(加查·玛达)', '中心':'爪哇东部', '人物':'加查·马达', '成就':'马来群岛的松散霸权' },
  qh:{ born:['先借外国军队,再把这支军队赶走','It borrowed a foreign army, then drove that army out'],
       rule:['朝贡名单很长,真管住的只有核心区','The tribute list was long; the real control was small'],
       money:['用稻米,换香料群岛的丁香豆蔻','Rice traded for the cloves and nutmeg of the spice islands'],
       power:['不必占岛,也能让整片群岛按它的规矩转','It never occupied the islands, yet set the terms of their trade'],
       fall:['北岸的港口改了信仰,也就改了主人','The northern ports changed faith, and changed masters'],
       legacy:['王室东迁,巴厘成了最后的印度教之岛','The court moved east, and Bali stayed the last Hindu island'] },
  q:{ born:['1293年元军跨海讨伐爪哇,当地王子先借元军之力消灭政敌,随即反戈把元军逐回海上——借力打力立国;新王朝定都爪哇东部,接手爪哇的稻田与爪哇海的贸易。','In 1293 a Yuan armada crossed the sea to punish Java. A local prince first borrowed the Mongol force to destroy his rival, then turned and drove the Mongols back to their ships — a state founded on judo. The new dynasty, seated in east Java, took over the island\'s rice lands and the Java Sea trade.'],
      rule:['典型的「曼陀罗」式霸权:核心区直接治理,外岛与港口只需纳贡称臣、承认宗主;权相加查·马达立誓统合群岛;据宫廷长诗《爪哇史颂》所列,朝贡范围遍及群岛大部——史学界普遍认为这份名单夸大了实际控制,真正牢牢管住的是东爪哇核心区。','A classic mandala hegemony: the core was ruled directly, while outer islands and ports merely paid tribute and acknowledged the overlord. The great minister Gajah Mada vowed to unify the archipelago, and at its height Majapahit commanded most of it — through prestige and fleets, not garrisons.'],
      money:['底牌是稻米换香料:爪哇火山土的稻米盈余,正是缺粮的香料群岛最需要的东西;满者伯夷的商船以米易取丁香豆蔻,再经爪哇海转卖四方——靠掌握爪哇海航线分走香料财富,是海峡过路费故事的爪哇变奏。','The trump card was rice for spice: the surplus of Java\'s volcanic paddies was exactly what the food-short Spice Islands needed most. Majapahit\'s ships traded rice for cloves and nutmeg and resold them across the region — taking its cut by commanding the Java Sea lanes, a Javanese variation on the strait-toll story.'],
      power:['粮食就是权力:控制稻米,就扼住了香料群岛的命脉;再加上足以远航讨伐的舰队与爪哇的人口底盘,它不必占领各岛,就能让群岛的贸易按它的规矩转。','Food was power: control of rice held the lifeline of the Spice Islands. Add a fleet capable of punitive expeditions and Java\'s demographic weight, and it could make the archipelago\'s trade run by its rules without occupying the islands.'],
      fall:['多因叠加:加查·马达身后霸权已显疲态,15世纪初的王位内战(帕勒格雷格战争)重创国力;北岸港口纷纷改宗伊斯兰教,依托新兴的马六甲商网自立门户,淡目苏丹国在其中崛起;16世纪初残余王室败亡,印度教政权退出爪哇。','Causes stacked: the hegemony sagged after Gajah Mada, and the succession war of the early fifteenth century (the Paregreg war) gutted its strength. The north-coast ports converted to Islam and hitched themselves to the rising Malacca network, and the Sultanate of Demak rose among them. By the early sixteenth century the last of the royal house fell, and Hindu kingship left Java.'],
      legacy:['今日印度尼西亚把它当作版图想象的历史蓝本,国徽上的格言与统一叙事都追溯到它;王室与信众东迁巴厘岛,让巴厘成为群岛上最后的印度教之岛。','Today\'s Indonesia treats it as the historical blueprint of its territorial imagination — the national motto and the narrative of unity both trace back to it. Its court and faithful withdrew to Bali, leaving that island the last Hindu island of the archipelago.'] },
  d:'击退忽必烈的远征军后立国,鼎盛时号令马来群岛大部,是今日印尼版图想象的历史蓝本;随伊斯兰苏丹国兴起而衰亡,其印度教遗民至今仍聚居巴厘岛——印尼群岛上最后的印度教之岛。' },
{ l:'se', s:'mideast', v:0, n:'马六甲及诸苏丹国', k:[[1400,0],[1470,.35],[1511,.25],[1600,.2],[1700,0]], b:'香料贸易总汇与伊斯兰传播中心,奠定马来世界信仰版图。',
  e:{ n:'Malacca & Sultanates', w:'Malacca Sultanate', b:'Spice entrepôt and Islam\'s gateway to the archipelago.', d:'A small port backed by Zheng He\'s fleet became the spice trade\'s clearing-house and Islam\'s distribution point — Malay became the archipelago\'s lingua franca. Portugal took the city in 1511, but Islamization was already irreversible.', f:{ 'Peak':'late 15th c.', 'Center':'Malacca', 'Figures':'Parameswara', 'Legacy':'Malay as lingua franca' } },
  f:{ '鼎盛':'15世纪后期', '中心':'马六甲', '人物':'拜里米苏拉', '成就':'马来语成为群岛通用语' },
  qh:{ born:['明朝的背书,让别人不敢来吞它','Ming backing kept the neighbours from swallowing it'],
       rule:['统治的本事,就是让商人放心','The art of rule was making merchants feel safe'],
       money:['等风的船必须停下,停下就得交税','Ships waiting for wind had to stop, and pay'],
       power:['低税、公正、设施齐全,生意自己上门','Low tax, fair courts, good facilities, and the trade came'],
       fall:['城被攻下了,可网络杀不死','The city fell, but the network could not be killed'],
       legacy:['今天的马来语印尼语,同出这个集市','Malay and Indonesian both come out of this bazaar'] },
  q:{ born:['三佛齐王子拜里米苏拉流亡到马六甲河口建港,位置扼守海峡中段,又正卡在两季风的交汇点;郑和舰队的到来给了它决定性的靠山——明朝的背书让暹罗不敢吞并,小渔港数十年间跃为大商埠,接过海峡过路费的下一棒。','Parameswara, a fugitive prince of Srivijaya, founded a port at the Malacca river mouth — at the strait\'s middle of the strait, where the monsoons meet. Zheng He\'s fleets brought the decisive patron: Ming endorsement kept Siam at bay, and within decades a fishing village leapt into a great emporium, taking the next leg of the strait-toll relay.'],
      rule:['苏丹之下是一套为商人设计的制度:四位港务官(沙班达尔)各管一片商帮,商事纠纷有章可循;王室改宗伊斯兰教后,又接入了印度洋穆斯林商人的信任网络——统治的本事,就是让四方商人放心。','Beneath the sultan ran a system designed for merchants: four harbormasters (syahbandars) each looked after one trading community, and commercial disputes followed known rules. When the court embraced Islam it plugged into the trust network of Indian Ocean Muslim traders — the art of rule was making foreign merchants feel safe.'],
      money:['季风的时刻表就是它的收银机:乘东风与乘西风的商船都必须在此停泊换货、等风过季,马六甲坐地抽税,兼营仓储与中介;香料、丝绸、棉布与白银在此换手,一座城吃住了东西方贸易的中转生意。','The monsoon timetable was its cash register: ships riding either wind had to berth here to exchange cargoes and wait out the season, while Malacca levied duties and sold storage and brokerage. Spices, silk, cotton, and silver changed hands here — a single city living off the transshipment of East-West trade.'],
      power:['它几乎不养大军,靠的是制度与背书:低税、公正、设施齐全,商船自然把生意送上门——港口越旺,盟友与税源越多;明朝的册封与伊斯兰商网,是它的两重外部保险。','It kept no great army; its power was institutional: low duties, fair dealing, and full port services drew the ships of their own accord — and the busier the port, the more allies and revenue. Ming recognition and the Muslim trade network were its twin outside insurances.'],
      fall:['1511年葡萄牙舰队攻陷马六甲城,想就此垄断香料贸易;但网络杀不死——穆斯林商人绕开葡萄牙人,把生意分流到亚齐、柔佛、万丹等继承者,苏丹后裔也在柔佛延续王统;17世纪荷兰人再夺此城,海峡诸苏丹国在欧洲人的夹缝中渐失主导权。','In 1511 a Portuguese fleet stormed Malacca, hoping to monopolize the spice trade. But a network cannot be killed by taking one node — Muslim merchants rerouted around the Portuguese to successor ports like Aceh, Johor, and Banten, while the sultan\'s line carried on in Johor. The Dutch took the city in the seventeenth century, and the strait sultanates slowly lost the game to the Europeans.'],
      legacy:['马来语借它的集市成为群岛通用语,今日的印尼语与马来西亚语同出此源;它奠定的马来-伊斯兰信仰版图延续至今;马来西亚诸州苏丹的王统与宫廷礼仪,多可追溯到马六甲。','Through its bazaars Malay became the lingua franca of the archipelago — today\'s Indonesian and Malaysian both descend from it. The Malay-Islamic map of faith it set endures, and the royal lines and court ceremony of Malaysia\'s sultanates trace largely back to Malacca.'] },
  d:'郑和舰队扶持的小港迅速成为香料贸易总汇与伊斯兰传播中心,马来语借此成为群岛通用语;1511年葡萄牙人夺城,但伊斯兰化已不可逆——今日马来世界的信仰版图就此奠定。' },
{ l:'se', s:'indic', v:1, n:'暹罗', k:[[1351,0],[1600,.35],[1767,.2],[1800,.3],[1900,.25],[1945,0]], b:'继吴哥而起的中南半岛强国,东南亚唯一未被殖民的国家。',
  e:{ n:'Siam', w:'Thailand', b:'Heir of Angkor; the only uncolonized state in the region.', d:'Ayutthaya inherited the mainland after Angkor\'s fall, warring with Burma for centuries; alone in Southeast Asia it kept independence by playing Britain against France — trading edge territories for the core\'s sovereignty.', f:{ 'Peak':'17th c. (Ayutthaya) and the late 19th (Chulalongkorn)', 'Center':'Ayutthaya → Bangkok', 'Figures':'Naresuan, Chulalongkorn', 'Legacy':'Diplomacy played between empires, sovereignty kept' } },
  f:{ '鼎盛':'17世纪(阿瑜陀耶)与19世纪末(朱拉隆功)', '中心':'阿瑜陀耶→曼谷', '人物':'纳黎萱、朱拉隆功', '成就':'以外交周旋列强、独保主权' },
  qh:{ born:['接了吴哥的位置,也接了它的剧本','It took over the place of Angkor, and its script too'],
       rule:['一个礼仪王国,被改造成近代国家','A kingdom of ritual remade into a modern state'],
       money:['对外贸易由王室垄断,利最厚','Foreign trade was a royal monopoly, and the richest'],
       power:['割掉边缘,保住核心——唯一没被殖民','It gave up the edges to keep the core, and stayed free'],
       fall:['不是亡国,是改了名字和政体','Not an ending: a change of name and of regime'],
       legacy:['小国靠外交和改革,也能保住自己','A small country kept itself by diplomacy and reform'] },
  q:{ born:['吴哥衰落让中南半岛出现权力真空;1351年阿瑜陀耶在湄南河下游立国,河口通海,腹地产米,又从高棉学来整套王权制度——继承了吴哥的位置,也继承了它的剧本。','Angkor\'s decline opened a vacuum on the mainland. Ayutthaya, founded in 1351 on the lower Chao Phraya, had a seagoing river mouth and a rice-rich hinterland, and borrowed the full kit of royal institutions from the Khmer — inheriting Angkor\'s position and its script alike.'],
      rule:['王权沿用承自高棉的神圣礼仪,社会按「萨克迪纳」等级各安其位;19世纪末朱拉隆功自上而下改革——废奴、设省、办新式学校与铁路,把一个礼仪王国改造成中央集权的近代国家。','Kingship kept the sacred ceremony inherited from the Khmer, and society was ranked by the sakdina system, each person in an assigned place. In the late nineteenth century Chulalongkorn reformed from above — abolishing slavery, building provinces, schools, and railways — remaking a ceremonial kingdom into a centralized modern state.'],
      money:['湄南河平原的稻米是根本;阿瑜陀耶曾是国际大港,波斯、日本、中国与欧洲的商馆并立,王室垄断对外贸易抽取厚利;近代转为大米出口国,曼谷靠米、柚木与锡接入世界市场。','Rice from the Chao Phraya plain was the base. Ayutthaya was a cosmopolitan port — Persian, Japanese, Chinese, and European factories side by side — with the crown monopolizing foreign trade for fat margins. In modern times Siam became a rice exporter, plugging into world markets through Bangkok with rice, teak, and tin.'],
      power:['硬实力靠人口与稻米:与缅甸百年攻伐互有胜负,都城两度陷落:1569年后原地复国,1767年被焚后干脆在曼谷重起炉灶;真正的绝活是外交——在英属缅甸与法属印度支那之间把自己经营成缓冲国,以割让边缘领土换核心主权,成为东南亚唯一未被殖民的国家。','Hard power rested on population and rice: a century of wars with Burma saw the capital fall twice — restored on its old site after 1569, but rebuilt at Bangkok after 1767. The real specialty was diplomacy — positioning itself as the buffer between British Burma and French Indochina, trading edge territories for core sovereignty to become the only Southeast Asian country never colonized.'],
      fall:['与其说衰亡,不如说转型:1932年一场不流血政变终结了君主专制,改行君主立宪;二战中在日本压力下结盟,战后又全身而退;1939年改称泰国(战后一度改回暹罗,1949年才定下来)——王统延续至今,「暹罗」作为国名走进了历史。','It transformed rather than fell: a bloodless coup in 1932 ended absolute monarchy for a constitutional one. Pressured into alliance with Japan in World War II, it extricated itself after the war; from 1939 the country took the name Thailand — the royal line continues, and Siam passed into history as a name.'],
      legacy:['一条未曾断裂的国家线:今日泰国的君主制、佛教立国传统与版图直接承自暹罗;它证明小国靠外交与改革也能在帝国时代保住自己——这份经验至今仍被反复引用。','An unbroken national line: today\'s Thailand — its monarchy, its Buddhist state tradition, its territory — descends directly from Siam. It proved a small country could survive the age of empires through diplomacy and reform, a lesson still cited today.'] },
  d:'阿瑜陀耶继承吴哥衰落后的中南半岛霸权,与缅甸百年攻伐、都城两度被焚;却是东南亚唯一凭外交在英法之间周旋、始终未被殖民的国家——代价是割让边缘领土,换来核心的独立。' },
{ l:'se', s:'west', v:0, n:'欧洲殖民东南亚', k:[[1511,0],[1700,.3],[1870,.5],[1941,.6],[1945,.3],[1957,0]], b:'从香料群岛到全境瓜分;二战日军南下击碎殖民神话。',
  e:{ n:'Colonial SE Asia', b:'Iberian start, Dutch spice, British-French carve-up; broken by 1942.', d:'Portugal and Spain began it, the Dutch monopolized spice, Britain took Malaya and Burma, France Indochina, America the Philippines; Japan\'s months-long sweep in WWII shattered the myth of white invincibility — independence followed within a decade.', f:{ 'Peak':'c. 1900 (partition complete)', 'Center':'Batavia, Manila, Saigon', 'Figures':'Stamford Raffles', 'Keywords':'Spices, rubber, tin' } },
  f:{ '鼎盛':'1900年前后(全境瓜分完成)', '中心':'巴达维亚(雅加达)、马尼拉、西贡', '人物':'莱佛士', '关键词':'香料、橡胶、锡' },
  qh:{ born:['想绕开层层中间商,直接去拿货源','They wanted the source, without the chain of middlemen'],
       rule:['公司先行,一家公司有自己的军队','The company went first, with its own army'],
       money:['毁掉树来抬价,逼农民种指定作物','Trees destroyed to raise prices, and crops made compulsory'],
       power:['很少正面征服,多是介入内争','Rarely a head-on conquest, usually a hand in a quarrel'],
       fall:['「白人不可战胜」这句话,当众破了','The myth that white men could not lose broke in public'],
       legacy:['掠夺和铁路,一起写进了各国的起点','Plunder and railways both went into the founding'] },
  q:{ born:['驱动力是香料的暴利:丁香豆蔻在欧洲的售价数十倍于产地,欧洲人想绕过层层中间商直取货源;1511年葡萄牙攻占马六甲开局,此后四百年,荷、英、法、美相继而来,从据点蚕食到全境瓜分。','The driver was the spice markup: cloves and nutmeg sold in Europe for many times their island price, and Europeans wanted the source without the middlemen. Portugal\'s seizure of Malacca in 1511 opened four centuries in which the Dutch, British, French, and Americans followed — from footholds to full partition.'],
      rule:['以极少数官员统治千万级人口,靠本地王公与头人的间接治理、族群分工与「分而治之」;公司先行——荷兰东印度公司有自己的军队与缔约权,破产后才由政府接管殖民地。','A handful of officials ruled tens of millions through indirect rule by local princes and headmen, ethnic division of labor, and divide-and-rule. Companies led the way — the Dutch VOC kept its own army and treaty powers, and only after its bankruptcy did the government take over the colonies.'],
      money:['殖民经济靠垄断与强制:荷兰人在香料群岛毁树限产以抬价,在爪哇推行强迫种植制,农民必须以官定低价种指定作物;后期的橡胶园与锡矿,靠引入的华工与印度劳工支撑——利润流向宗主国,风险与劳苦留在殖民地。','The colonial economy ran on monopoly and coercion: the Dutch destroyed surplus spice trees to prop up prices and imposed the Cultivation System on Java, forcing peasants to grow set crops at set prices. Later, rubber estates and tin mines ran on imported Chinese and Indian labor — profits flowed to the metropole, while risk and toil stayed in the colony.'],
      power:['靠船炮与组织的代差,更靠本地政权的互斗——欧洲人极少正面征服一个团结的对手,多是介入内争、各个击破;瓜分的边界往往在欧洲的谈判桌上画定,与当地族群的分布无关。','It rested on gaps in ships, guns, and organization — and even more on local rivalries: Europeans rarely conquered a united foe head-on, but entered internal quarrels and won piecemeal. The borders of partition were often drawn at European negotiating tables, indifferent to who actually lived where.'],
      fall:['二战是转折:日军数月横扫全境,俘虏欧洲守军,「白人不可战胜」的神话当众破碎;战后民族主义者不再接受旧秩序,武装斗争与谈判并举,而元气大伤的宗主国已无力久撑——印尼、缅甸、越南、马来亚等在十余年间相继独立。','World War II was the break: Japanese forces overran the region in months and marched European garrisons into captivity, shattering the myth of white invincibility in public view. After the war, nationalists refused the old order, pressing with arms and at the table, while the exhausted metropoles could no longer hold on — Indonesia, Burma, Vietnam, Malaya and others won independence within some fifteen years.'],
      legacy:['遗产双面:今日东南亚各国的国界、官僚与法律框架大多由殖民时期划定;种植园经济、族群分层与移民社会的格局同样源于此;掠夺与强制是这段历史如实的一面,与铁路港口一样,都写进了各国的起点。','The legacy is double-sided: today\'s national borders, bureaucracies, and legal frameworks were largely drawn in the colonial era, as were the plantation economies, ethnic stratification, and migrant societies. Extraction and coercion are the factual side of this history — written into each nation\'s starting point as surely as the railways and ports.'] },
  d:'葡西开局,荷兰以香料群岛立本,英取马来缅甸,法据印度支那,美继菲律宾;二战中日军数月横扫全境,击碎"白人不可战胜"的神话——战后独立浪潮十余年内席卷东南亚。' },
{ l:'se', s:'sea', v:0, n:'现代东南亚', k:[[1945,0],[1967,.3],[1997,.45],[2025,.55]], b:'从战乱走向东盟抱团;近七亿人口的供应链新枢纽。',
  e:{ n:'Modern SE Asia', w:'ASEAN', b:'From war to ASEAN; the supply chain\'s new hub.', d:'Through the Vietnam War and Cold War turmoil, ASEAN (1967) chose collective pragmatism; Singapore leapt from entrepôt to global financial center. Nearly seven hundred million people are again where they were before the Age of Sail — at the crossroads of world trade.', f:{ 'Peak':'after 2010 (ASEAN integration)', 'Center':'Jakarta, Singapore, Bangkok, Hanoi', 'Figures':'Sukarno, Lee Kuan Yew', 'Legacy':'ASEAN, the Singapore miracle' } },
  f:{ '鼎盛':'2010年后(东盟一体化)', '中心':'雅加达、新加坡、曼谷、河内', '人物':'苏加诺、李光耀', '成就':'东盟、新加坡奇迹' },
  qh:{ born:['独立来得晚,冷战又把这里变成前线','Independence came late, and the cold war made it a front'],
       rule:['决策慢,但立场不同的人能坐一起','Slow to decide, but it keeps very different states talking'],
       money:['位置是最大的资产:海峡就在这儿','The position is the asset: the strait runs through it'],
       power:['不选边,和谁都保持关系','It picks no side, and keeps every relationship'],
       fall:['1997年泰铢一崩,连锁反应扫过全区','The baht broke in 1997, and the shock ran through the region'],
       legacy:['南岛、印度、伊斯兰、华人,一层层叠上来','Austronesian, Indian, Islamic and Chinese layers, one on another'] },
  q:{ born:['二战期间日本占领打破了欧洲殖民统治的表象,战后各国相继独立:印尼1945年宣布、荷兰1949年承认,菲律宾1946年,缅甸1948年,马来亚1957年,新加坡1965年从马来西亚分离。泰国是唯一未被正式殖民的国家——代价是签下不平等条约、割走大片边地。独立之后,冷战把这一带变成前线,越南战争持续了二十年。','Japanese occupation during the Second World War broke the appearance of European rule, and independence followed one country at a time: Indonesia declared in 1945 and was recognised in 1949, the Philippines in 1946, Burma in 1948, Malaya in 1957, and Singapore separated from Malaysia in 1965. Thailand alone was never colonised. After independence the Cold War made the region a front line, and the war in Vietnam ran for twenty years.'],
      rule:['政体差异极大:议会制、君主立宪、一党制、军人执政都有,而且同一国家内也常变动。1967年成立的东南亚国家联盟提供了一个共同框架,它的特点是「协商一致、不干涉内政」——决策慢,但让立场差别很大的国家能坐在一起,这套做法后来被称作「东盟方式」。','The forms of government vary as widely as anywhere: parliamentary, constitutional monarchy, one-party, military, and often changing within the same country. The Association of Southeast Asian Nations, founded in 1967, gives them a shared frame, working by consensus and non-interference — slow to decide, but able to keep states with very different positions at one table, an approach that came to be called the ASEAN way.'],
      money:['先是橡胶、锡、稻米与石油等初级产品,1970年代后转向出口加工:纺织、电子组装、汽车零件。它的位置是最大的资产——马六甲海峡是世界最繁忙的航道之一,新加坡因此成为全球最大的转口港与炼油中心之一。今天这一带是全球电子与半导体供应链的关键环节。','First primary goods — rubber, tin, rice, oil — and after the 1970s export processing: textiles, electronics assembly, car parts. Its position is the great asset: the Strait of Malacca is among the busiest shipping lanes on earth, and Singapore grew on it into one of the world\'s largest transshipment ports and refining centres. The region is now a critical link in the global electronics and semiconductor supply chain.'],
      power:['地理与人口:近七亿人、扼守东西方海运要道。新加坡在一代人时间里从转口港变成人均收入最高的国家之一,靠的是法治、教育与对外开放的组合,常被作为小国治理的样本。区域整体的策略是不选边、与各大国同时保持关系,并靠东盟维持集体分量。','Geography and people: 650 million of them, astride the sea route between east and west. Singapore went from entrepôt to one of the highest incomes per head in the world within a single generation, on a combination of rule of law, schooling and openness, and is studied as a model of small-state governance. The region\'s collective approach is to avoid choosing sides, keep relations with all the major powers, and use ASEAN to hold its combined weight.'],
      fall:['1997年亚洲金融危机是最近一次大的转折:泰铢崩盘引发连锁反应,印尼、泰国、马来西亚货币与股市暴跌,印尼陷入政治动荡、苏哈托三十二年的统治随之结束。危机之后各国普遍提高外汇储备、改革金融监管,区域内也建立了货币互换机制,以防同样的事再发生。此前更沉重的一段是柬埔寨:1975至1979年红色高棉执政期间,约一百七十万至两百万人死于处决、强制劳动与饥饿。','The Asian financial crisis of 1997 was the last great turning point: the collapse of the Thai baht set off a chain reaction, currencies and share markets fell sharply across Indonesia, Thailand and Malaysia, and political upheaval in Indonesia ended Suharto\'s thirty-two years in power. Afterwards countries built up reserves, overhauled financial regulation, and set up currency swap arrangements within the region to keep it from happening again. A heavier passage had come before it, in Cambodia: between 1975 and 1979, under the Khmer Rouge, somewhere between 1.7 and 2 million people died from execution, forced labour and starvation.'],
      legacy:['吴哥窟与婆罗浮屠是世界最大的宗教建筑群之列,它们本身就是印度与本地传统结合的产物。这一带长期是南岛语族扩散、印度化与伊斯兰化、华人移民多层叠加的地方,今天的语言、饮食与信仰格局都由此而来。稻作、香料与橡胶则从这里影响了全世界的餐桌与工业。','Angkor Wat and Borobudur are among the largest religious monuments in the world, and both are products of Indian forms meeting local ones. The region has layered Austronesian expansion, Indian and Islamic influence and Chinese migration on top of one another, and its languages, food and faiths all follow from that. Rice cultivation, spices and rubber went out from here to change kitchens and industries everywhere.'] },
  d:'独立后历经越战与冷战动荡,1967年东盟成立走向抱团;新加坡从转口小港跃为全球金融中心。如今近七亿人口的东南亚是全球供应链转移的最大受益者之一,重新回到大航海时代之前的位置——世界贸易的十字路口。' },
/* 东亚 */
{ l:'ea', s:'sino', v:0, n:'三星堆·古蜀', k:[[-1700,0],[-1300,.24],[-1200,.3],[-1100,.26],[-900,.12],[-600,.06],[-453,0]], b:'成都平原的青铜文明:青铜神树、纵目面具与黄金面具。',
  e:{ n:'Sanxingdui & Ancient Shu', w:'Sanxingdui', b:'A bronze civilization on the Chengdu plain: sacred trees, protruding-eye masks, gold masks.', d:'A bronze tradition that ran in parallel with the Central Plains and looked nothing like it. Its sacred trees, protruding-eye masks and gold masks have no counterpart in China; the pits found in 1986 are among the strongest evidence that Chinese civilization had more than one origin. It left no writing, and why it rose and fell is still unsolved.', f:{ 'Peak':'c. 1200 BCE (the sacrificial pits)', 'Center':'Sanxingdui (Guanghan), Jinsha (Chengdu)', 'Legacy':'Bronze sacred trees and masks; a bronze ritual system independent of the Central Plains' } },
  f:{ '鼎盛':'前1200年前后(祭祀坑年代)', '中心':'三星堆(今广汉)、金沙(今成都)', '成就':'青铜神树与纵目面具、独立于中原的青铜礼制' },
  qh:{ born:['和中原不通,却自己长出一套传统','Cut off from the Central Plain, it grew its own'],
       rule:['资源大把投进祭祀,而不是打仗','Resources went into ritual, not into war'],
       money:['铜、象牙、海贝都不是本地产的','Copper, ivory, cowries: none of it was local'],
       power:['中原铸鼎,这里铸人像和神树','The Central Plain cast cauldrons; here they cast figures'],
       fall:['中心搬去了四十公里外的金沙','The centre moved forty kilometres away, to Jinsha'],
       legacy:['原来同一时期还有另一套青铜传统','A second bronze tradition, at the very same time'] },
  q:{ born:['成都平原被高山围住,与中原往来不便,却土地肥沃、水源充足。从新石器时代的宝墩文化起这里就自己长出了一套城邑传统;到公元前二千纪后期,三星堆一带出现了城墙、大型建筑与专门的青铜作坊。','The Chengdu plain is ringed by mountains and hard to reach from the Central Plains, but its soil is rich and its water plentiful. A tradition of walled towns grew up here on its own from the neolithic Baodun culture onward, and by the late second millennium BCE there were walls, large buildings and dedicated bronze workshops around Sanxingdui.'],
      rule:['没有文字留下来,统治结构只能从器物推断。祭祀坑里成批的青铜人像、面具与神树,显示这是一个把资源大量投进宗教仪式的社会;器物按尺寸与形制分等,推测有一个以祭祀为中心的等级。','No writing survives, so the shape of authority can only be read from the objects. The sacrificial pits held bronze figures, masks and trees in quantity — a society pouring its resources into ritual — and the objects are graded by size and type, suggesting a hierarchy organised around the rites.'],
      money:['农业靠成都平原的水土,手工业的核心是青铜与玉。铜锡与象牙都不产自本地,说明它有稳定的远距离交换网络;坑里还出土了四千多枚海贝——这东西成都平原不产。','Farming rested on the plain\'s soil and water, and the crafts on bronze and jade. Copper, tin and ivory are not local, so long-distance exchange must have been steady; and the pits yielded over four thousand cowrie shells, which the Chengdu plain does not produce.'],
      power:['它的强项不是征伐而是技术与信仰:青铜铸造水平与中原不相上下,却走了完全不同的路——中原铸鼎彝,这里铸人像与神树。一棵铜神树高近四米,是目前所知最高的一件商代青铜器。','Its strength lay not in conquest but in craft and belief. Its bronze casting matched the Central Plains but went a wholly different way: where the Central Plains cast cauldrons, here they cast human figures and sacred trees. One bronze tree stands nearly four metres — the tallest single bronze object known from Shang-period China.'],
      fall:['前1100年前后,三星堆的祭祀坑被集中掩埋,城址随后衰落,中心转移到四十多公里外的金沙(今成都市区)。原因至今无定论,水患、战争、宗教变革几种假说并存。金沙延续到前600年前后;再往后蜀地进入文献可考的开明王朝,前316年被秦所灭。','Around 1100 BCE the Sanxingdui pits were filled in together and the site declined, the centre shifting some forty kilometres to Jinsha, inside today\'s Chengdu. Why is unsettled — flooding, war and religious upheaval have all been proposed. Jinsha ran on to about 600 BCE; later Shu enters the written record under the Kaiming kings, until Qin destroyed it in 316 BCE.'],
      legacy:['1986年两个祭祀坑被偶然发现时,为「中华文明多元起源」提供了最有冲击力的一个证据——同一时期的中国,原来还有另一套完全不同的青铜传统。2019年起又发现六个坑,发掘仍在进行,黄金面具与丝绸残迹是近年最受关注的出土物。','When two sacrificial pits were found by accident in 1986, they gave the case for multiple origins of Chinese civilization its most striking single piece of evidence: an entirely separate bronze tradition had been running at the same time. Six more pits have been found since 2019 and excavation continues, with a gold mask and traces of silk among the finds that drew most attention.'] },
  d:'成都平原上一支与中原并行的青铜文明。青铜神树、纵目面具与黄金面具的样式在中国独一无二,1986年祭祀坑的发现,是「中华文明多元起源」最有力的物证之一;它没有留下文字,兴衰原因至今是未解之谜。' },
{ l:'ea', s:'sino', v:1, n:'二里头·夏', k:[[-2070,0],[-1750,.3],[-1700,.35],[-1600,0]], b:'中原最早的广域王权与宫殿都邑,对应传说中的夏。',
  e:{ n:'Erlitou / Xia', w:'Erlitou culture', b:'Earliest broad kingship in the Central Plain — the proto-China.', d:'Palace precincts, bronze jue cups and a turquoise dragon: Erlitou in the Luoyang basin is the Central Plain\'s first kingship whose reach went beyond a single city. Whether it is the textual "Xia" is debated — but the prototype of "China" is already here.', f:{ 'Peak':'c. 1700 BCE (Erlitou phase III)', 'Center':'Erlitou (Luoyang basin)', 'Legacy':'Earliest palace city and bronze rites' } },
  f:{ '鼎盛':'前1700年前后(二里头三期,宫城建成)', '中心':'二里头(洛阳盆地)', '成就':'最早的宫城与青铜礼器群' },
  qh:{ born:['最早的宫城,但没挖出文字','The earliest palace city, but no writing found'],
       rule:['能用什么器物,就是什么身份','What vessels you could use was your rank'],
       money:['远方的原料变成礼器,礼器变成权威','Distant ores became ritual vessels, vessels became authority'],
       power:['影响力走得比疆界远','Its influence travelled further than its borders'],
       fall:['考古只看到权力中心转移','Archaeology sees only the centre of power move'],
       legacy:['后世王朝的许多基本语法,在这里初见雏形','Much of the later Chinese grammar of rule starts here'] },
  q:{ born:['农业在中原积累了上千年,到公元前二千纪前期,洛阳盆地出现了辐射广大区域的王权和最早的宫城。中国学界的主流看法是它对应文献中的夏;但二里头没有出土文字,海外学者多持保留态度,这个对应仍在争论中。','After centuries of farming built up wealth on the Central Plains, a royal power with the earliest known palace city emerged in the Luoyang basin in the early second millennium BCE. Chinese archaeologists generally identify it with the Xia, though most scholars outside China remain cautious of later texts, but no writing has been found at Erlitou, so the match remains debated.'],
      rule:['统治靠垄断「礼」:宫城里的宫殿用于仪式,青铜爵和绿松石礼器只能由王权作坊铸造、按身份分配。谁能主持祭祀、谁能用什么器物,就是权力的等级表。','Rule rested on a monopoly of ritual: palace ceremonies, and bronze and turquoise regalia that only royal workshops could make and only ranked elites could hold. Who presided over the rites, and who used which vessels, was the visible ladder of power.'],
      money:['经济的根基是粟和稻的农业;都邑同时控制着铜、锡、绿松石等远方原料的输入,把稀缺资源变成礼器,再把礼器变成权威。','The economy rested on millet and rice farming. The capital also controlled long-distance flows of copper, tin, and turquoise, turning scarce materials into ritual objects — and ritual objects into authority.'],
      power:['变强靠技术与礼制的辐射:二里头掌握了当时最复杂的青铜合金铸造,它的礼器样式和宫室布局被周边聚落模仿——影响力走得比疆界更远。','Its strength radiated through technology and ritual. Erlitou mastered the most complex bronze casting of its day, and neighboring communities copied its vessel styles and palace layouts — its influence traveled farther than any border.'],
      fall:['公元前1600年前后,二里头都邑衰落,郑州一带的二里岗文化(早商)兴起并取而代之。文献说商汤灭夏,考古只能看到权力中心的转移;两者如何对应,尚无定论。','Around 1600 BCE the Erlitou capital declined, and the Erligang culture (early Shang) around Zhengzhou rose in its place. Texts say Tang of Shang overthrew the Xia; archaeology shows only a shift of the power center, and how the two accounts fit together remains unsettled.'],
      legacy:['宫城居中、中轴对称的都城格局,和用青铜礼器标记等级的传统,被商周继承并放大——后世中国王朝的许多基本语法在这里初见雏形,所以考古学家称它为「最早的中国」。','Its centered, axial palace-city plan and its use of bronze ritual vessels to mark rank were inherited and amplified by the Shang and Zhou. Many basic grammars of later Chinese dynasties first appear here — which is why archaeologists call it \'the earliest China\'.'] },
  d:'宫城、青铜爵与绿松石龙——洛阳盆地的二里头,是中原第一个权力范围超出一城一地的王权;它是否就是文献中的"夏",学界仍在争论,但"最早的中国"的雏形已然在此。' },
{ l:'ea', s:'sino', v:0, n:'商', k:[[-1600,0],[-1300,.55],[-1046,0]], b:'甲骨文与青铜器:汉字与中华礼制文明的源头。',
  e:{ n:'Shang', w:'Shang dynasty', b:'Oracle bones and bronzes: the root of Chinese writing and rites.', d:'Oracle-bone script is the direct ancestor of Chinese characters, making Shang the start of China\'s recorded history; its bronze casting was superb — the Houmuwu ding, at over 800 kg, is still the largest ancient bronze ever unearthed. Fu Hao, queen and general, is the boneyard\'s most vivid figure.', f:{ 'Peak':'Wu Ding (13th c. BCE)', 'Center':'Yin (Anyang)', 'Figures':'Wu Ding, Fu Hao', 'Legacy':'Oracle-bone script, ritual bronzes' } },
  f:{ '鼎盛':'武丁(前13世纪)', '中心':'殷(安阳)', '人物':'武丁、妇好', '成就':'甲骨文、司母戊鼎' },
  qh:{ born:['神权和王权合成了一个','Priesthood and kingship became one thing'],
       rule:['刻在甲骨上的问答,就是国家档案','The questions cut into bone were the state archive'],
       money:['铸一件大鼎要几百个工匠','One great cauldron took hundreds of craftsmen'],
       power:['王后妇好也带兵打仗','Queen Fu Hao led armies too'],
       fall:['纣王的恶名,是周人写的','The last king was given his evil name by the Zhou'],
       legacy:['中国有文字可考的历史,从这里开始','Documented Chinese history begins here'] },
  q:{ born:['主流看法是商人取代了二里头代表的旧王权,文献称之为商汤灭夏。新王权把占卜和祭祀抓在自己手里,让神权与王权合为一体,统治从此有了宗教引擎。','The mainstream view is that the Shang displaced the older royal power represented by Erlitou — texts call it Tang\'s conquest of the Xia. The new kings took divination and sacrifice into their own hands, fusing religious and royal authority into a single engine of rule.'],
      rule:['商王既是君主也是最高祭司:大事必占卜,由王沟通祖先与至上神「帝」,刻在甲骨上的问答就是国家档案。王直接控制王畿,外围方国靠联盟、联姻与征伐维系,服从并不稳固。','The Shang king was both monarch and chief priest: major decisions went through divination, with the king mediating between the ancestors and the high god, and the questions carved on oracle bones became state archives. He ruled the royal domain directly, while outer polities were held by alliance, marriage, and war — and their obedience was never secure.'],
      money:['经济以农业为本,青铜铸造是王室垄断的顶级产业;海贝作为珍贵财物流通,常被王赏赐给臣下。铸一件大鼎要动员数百工匠,本身就是国力的展示。','Farming was the economic base, and bronze casting was the top industry, monopolized by the court. Cowrie shells circulated as precious wealth, often granted by the king as rewards. Casting a great cauldron took hundreds of craftsmen — itself a display of state power.'],
      power:['变强靠青铜兵器和马拉战车组成的军队,商王频繁亲征周边方国;武丁时代最盛,王后妇好也统兵出征,甲骨文里记着她的战功。','Strength came from armies with bronze weapons and horse-drawn chariots, and Shang kings campaigned constantly against neighboring polities. The peak came under Wu Ding, whose consort Fu Hao herself led troops — her victories are recorded on the oracle bones.'],
      fall:['主流看法是多因叠加:晚期王室连年对东夷用兵消耗国力,内部也有紧张;周人在西方坐大,牧野一战商军崩溃。纣王荒暴的形象主要出自周人的记载,当有夸张成分。','The mainstream view points to converging causes: late Shang kings drained the state in long wars against the eastern peoples while tensions grew at court, and the Zhou rose in the west until the Shang army collapsed at Muye. The image of the last king as a monster comes mainly from Zhou records, and is likely exaggerated.'],
      legacy:['甲骨文是汉字的直系祖先,三千多年前的问卜今天仍能被读出;青铜礼器与祖先崇拜奠定了中华礼制的底色。中国有文字可考的历史,从商开始。','Oracle-bone script is the direct ancestor of Chinese characters — questions asked three thousand years ago can still be read today. Bronze ritual vessels and ancestor worship set the tone of Chinese ritual culture, and China\'s documented history begins with the Shang.'] },
  d:'占卜刻辞的甲骨文是汉字的直系祖先,让商成为中国第一个有当时文字可证的王朝;青铜铸造极精,八百余公斤的后母戊鼎(又称司母戊鼎)至今仍是世界上出土的最大古代青铜器。妇好既是王后又统兵征伐,是甲骨文里最鲜活的人物。' },
{ l:'ea', s:'sino', v:1, n:'西周', k:[[-1046,0],[-1000,.6],[-880,.5],[-771,0]], b:'封建与礼乐:周公制礼,"天命"观念为中国政治哲学定调。',
  e:{ n:'Western Zhou', b:'Feudal enfeoffment and the Mandate of Heaven.', d:'After defeating the Shang, the Zhou kings settled kinsmen and allies across the land as a shield of vassal states around the royal house; the Duke of Zhou then set out a full order of rites and music; the creed that "Heaven favours no one — it helps only the virtuous" took root in this age, and stayed the baseline of Chinese political thought for three millennia. After the uprising of 841 BCE, the "Gonghe regency" begins China\'s unbroken chronology; in 771 BCE the Quanrong sacked the capital, ending the Western Zhou.', f:{ 'Peak':'Cheng-Kang era', 'Center':'Haojing, Luoyi', 'Figures':'King Wu, Duke of Zhou', 'Legacy':'Lineage feudalism, rites and music, the Mandate of Heaven' } },
  f:{ '鼎盛':'成康之治', '中心':'镐京、洛邑', '人物':'周武王、周公', '成就':'宗法封建、礼乐制度、天命观' },
  qh:{ born:['人少地大,就把亲戚封出去占地方','Few people, vast land, so kinsmen were sent to hold it'],
       rule:['用礼仪和音乐,把等级刻进日常','Ritual and music cut rank into daily life'],
       money:['王的赏赐,就是当时的政治货币','Royal gifts were the political currency'],
       power:['每个封国都是一座前哨','Every fief was an outpost'],
       fall:['几代之后血缘变远,诸侯就不听了','Kinship thinned over generations, and the lords stopped listening'],
       legacy:['「中国」二字最早的实物,在这里','The earliest object bearing the words Middle Kingdom'] },
  q:{ born:['牧野之战后,人口不多的周人面对辽阔的商朝故地,发明了一套治理方案:大封宗亲功臣到各地建国,像撒网一样铺开据点。又提出「天命」——上天把统治权交给有德者,商失德所以周代之,征服由此获得道义解释。','After Muye, the small Zhou people faced the vast former Shang lands and invented a solution: granting kinsmen and allies fiefs across the realm, spreading strongholds like a net. They also proclaimed the Mandate of Heaven — rule belongs to the virtuous, and the Shang had forfeited it — giving conquest a moral explanation.'],
      rule:['统治靠宗法加封建:天子、诸侯、卿大夫按血缘层层分封,嫡长子继承定下名分;周公制礼作乐,用礼仪和音乐把等级刻进日常生活——据后世记载,天子用九鼎八簋、诸侯七鼎六簋、大夫五鼎四簋,墓里的鼎数一数就知道墓主是什么身份。整套秩序靠亲情与仪式维系,而不靠常备官僚。','Rule combined kinship law with enfeoffment: king, lords, and ministers were ranked by blood, with succession fixed on the eldest son of the principal wife. The Duke of Zhou codified rites and music that carved hierarchy into daily life — later texts say a king used nine tripods and eight tureens, a lord seven and six, a minister five and four, so that counting the tripods in a tomb tells you the rank of whoever lay in it. The whole order ran on kinship and ceremony, not on a standing bureaucracy.'],
      money:['经济以农业为本,据后世记载,土地按「井田」划分,由庶民耕种、贵族收取劳役地租——井田的实际形态学界仍有争论。青铜器既是礼器也是财富,王的赏赐就是政治货币:铭文里常记「王赐贝十朋」「赐金」,贝壳串成朋、铜叫作金,受赐的人就铸一件铜器把这事刻下来。1975 年岐山出土的卫盉记着一桩交易:贵族矩伯用十三块田换裘卫的一件玉璋、两件玉琥和几件皮货——土地在西周中期已经能拿来交换了。','The economy rested on farming. Later texts describe land divided into \'well-field\' grids worked by commoners for aristocratic lords, though how literally this operated is still debated. Bronzes were both ritual objects and wealth — royal gifts were political currency: inscriptions often record "the king gave ten strings of cowries" or "gave metal" (bronze), and the recipient cast a vessel to record it. A bronze found at Qishan in 1975, the Wei he, records a deal in which the noble Ju Bo traded thirteen fields for a jade sceptre, two jade tigers and some leather goods from Qiu Wei — by mid-Western Zhou, land could change hands.'],
      power:['变强靠封建网络的扩张:把周人的语言、礼制和农业带到边地;成康之治时鼎盛,后世追述称那时刑罚长期搁置不用——「刑措四十余年不用」这句出自后人追记,当不得实录看,但它反映了后世对那几十年的印象。这套扩张有个不常被提起的代价:封出去的诸侯每一代都比上一代与王室远一层。血缘是会稀释的:第一代是王的兄弟儿子,到第五代第六代就只剩同姓而已,而这套秩序恰恰靠亲情维系、不靠常备官僚。','Strength grew through the expanding web of fiefs, carrying Zhou language, ritual, and agriculture to the frontiers. The peak came under kings Cheng and Kang, when — later chroniclers claimed — punishments went unused for decades. That they lay unused for forty years is a line from later chroniclers rather than a record made at the time, but it preserves how those decades were remembered. The expansion carried a cost that is less often named: each generation of an enfeoffed lord stood one degree further from the royal house than the last. Blood thins. The first holder was a brother or a son of the king; by the fifth or sixth he shared only a surname — and this was an order held together by kinship rather than by any standing bureaucracy.'],
      fall:['主流看法是多因叠加:王室直辖的土地与军队不断缩水;厉王与民争利引发国人暴动,幽王废嫡引来申侯联合犬戎攻破镐京(前771年)。平王东迁洛邑,王权从此名存实亡。','The mainstream view sees converging causes: the royal domain and army kept shrinking. King Li\'s grab at profits sparked a popular uprising; King You\'s tampering with the succession provoked an attack that sacked the capital in 771 BCE. The court fled east to Luoyi, and real royal power was gone.'],
      legacy:['「皇天无亲,惟德是辅」把政权合法性和统治者的德行绑在一起,成为此后三千年中国政治哲学的底层逻辑;宗法观念渗入中国的家庭伦理;青铜器何尊铭文「宅兹中国」,是「中国」一词最早的实物见证。','The idea that Heaven\'s mandate follows virtue tied legitimacy to a ruler\'s conduct — the base code of Chinese political philosophy for three millennia. Zhou kinship norms seeped into Chinese family ethics, and the He zun bronze\'s inscription \'dwelling in Zhongguo\' is the earliest physical witness of the term \'Middle Kingdom\'.'] },
  d:'武王灭商之后,周人把亲族与功臣分封到各地建国,像屏障一样拱卫王室;周公又制定了一整套礼乐制度;"上天不偏爱谁,只辅助有德的人"的天命观也在这个时代定下——它是此后三千年中国政治哲学的基调。前841年国人暴动,随后的"共和行政"是中国有确切纪年的开始;前771年犬戎攻破都城镐京,西周终结。' },
{ l:'ea', s:'sino', v:0, n:'春秋', k:[[-770,0],[-700,.4],[-600,.42],[-500,.45],[-454,0]], b:'王室东迁只剩名分,霸主轮流坐庄——孔子和老子就活在这三百年里。',
  e:{ n:'Spring & Autumn', w:'Spring and Autumn period', b:'The court kept the title; the strongest kept the power — and Confucius lived here.', d:'King Ping moved the capital east to Luoyi, and the Zhou house was left with a name and nothing else. Duke Huan of Qi and Duke Wen of Jin took turns as hegemon under the slogan "revere the king, expel the barbarians," while over a hundred small states were swallowed down to a dozen. Precisely because the old order had loosened, Confucius opened a school that took students regardless of birth, and Laozi left behind five thousand characters — the headwaters of Chinese thought.', f:{ 'Peak':'the age of hegemons (7th-5th c. BCE)', 'Center':'Luoyi and the states\' capitals', 'Figures':'Confucius, Laozi', 'Legacy':'Hegemon assemblies, private schools, first iron' } },
  f:{ '鼎盛':'霸主迭起(前7—前5世纪)', '中心':'洛邑与列国都城', '人物':'孔子、老子', '成就':'会盟称霸、私学兴起、铁器初现' },
  co:[ { n:['齐','Qi'], c:['临淄','Linzi'] },
       { n:['晋','Jin'], c:['绛→新田','Jiang, later Xintian'] },
       { n:['楚','Chu'], c:['郢','Ying'] },
       { n:['秦','Qin'], c:['雍','Yong'] },
       { n:['吴','Wu'], y:[null,-473], c:['梅里→姑苏','Meili, later Gusu'] },
       { n:['越','Yue'], c:['会稽','Kuaiji'], x:['等一百余国,春秋末并到十几家','among a hundred-odd states, down to a dozen by the end'] } ],
  qh:{ born:['天子只剩名分,秩序靠最强的诸侯','The king kept the title; the strongest lord kept order'],
       rule:['尊天子是外衣,当盟主才是实质','Honouring the king was the coat; leadership was the point'],
       money:['铁器和牛耕来了,荒地变成私田','Iron and oxen arrived, and waste land became private fields'],
       power:['小国靠会盟活命,大国靠灭国长大','Small states lived by alliance, big ones grew by swallowing'],
       fall:['卿大夫反过来把国君架空了','The ministers hollowed out their own rulers'],
       legacy:['中国人讲政治与道德的词,多半铸于此','Most words Chinese use for politics and morals were cast here'] },
  q:{ born:['周平王东迁后,王室失去了关中的土地和军队,只剩天下共主的名分;权力出现真空,秩序只能由最强的诸侯来维持——霸主时代由此开场。','After the Zhou court fled east it lost its lands and armies in the Wei valley, keeping only the title of overlord. Into the power vacuum stepped the strongest lords, who alone could keep order — the age of hegemons had begun.'],
      rule:['这个时代没有统一政权:周天子是名义共主,实际秩序靠霸主召集会盟来维持,齐桓公、晋文公都打「尊王攘夷」的旗号——尊天子是外衣,当盟主是实质。列国内部,权力又渐渐从国君滑向卿大夫家族。','No single power ruled this era. The Zhou king was overlord in name only; real order came from hegemons summoning the lords to sworn covenants under the banner of \'honor the king, repel the tribes\' — reverence was the costume, leadership the substance. Within each state, power meanwhile slid from rulers to ministerial clans.'],
      money:['经济在战争间隙里升级:铁器开始出现,牛耕初步推广,荒地被开垦成私田;各国自铸铜币,商人往来列国之间,郑国等地的市场已相当活跃。','The economy upgraded between wars: iron tools appeared, ox-drawn plowing began to spread, and wasteland became private fields. States minted their own bronze coins, and merchants moved across borders — markets in states like Zheng were already lively.'],
      power:['变强的逻辑是兼并:一百多个诸侯国互相吞并到只剩十几个,小国靠会盟求生,大国靠灭国扩张;军队规模随之膨胀,战争从贵族车战滑向全民动员的前夜。','The logic of strength was annexation: over a hundred states devoured one another down to a dozen or so, small ones surviving by covenant, great ones growing by conquest. Armies swelled accordingly, and war drifted from aristocratic chariot duels toward the eve of mass mobilization.'],
      fall:['这个格局的终结来自内部:各国的卿大夫家族坐大,反过来架空国君;前453年晋国的赵、魏、韩三家瓜分了晋国实权,前403年周天子索性把三家册封为诸侯——连「君臣名分」这层遮布也撕了——历史进入更赤裸的战国。','The order ended from within: ministerial clans grew strong enough to hollow out their own rulers. In 453 BCE three such clans carved up the great state of Jin, breaking even the last pretense of lord-and-vassal order — history entered the more naked age of the Warring States.'],
      legacy:['旧秩序松动的缝隙里长出了中国思想的源头:孔子办不问出身的私学,相传老子留下《道德经》,《诗经》在此定型。此后中国人讨论政治与道德的基本词汇,大半在这三百年里铸成。','In the cracks of the loosening old order grew the wellspring of Chinese thought: Confucius opened schools that ignored birth, Laozi left the Daodejing, and classics like the Book of Songs took shape. Much of the basic vocabulary Chinese still use to discuss politics and morality was forged in these three centuries.'] },
  d:'周平王把都城迁到洛邑,王室从此只剩一个名分,谁强谁说了算。齐桓公、晋文公先后打着"尊王攘夷"的旗号当上霸主,一百多个诸侯国互相吞并到只剩十几个。恰恰在这个旧秩序松掉的年代,孔子办起了不问出身的私学,老子留下五千字的《道德经》——中国思想的源头从这里开始流。',
  gl:[ { a:-550, b:-454, k:'thought', t:['私学与诸子先声','Private schools, first masters'], d:['孔子"有教无类",学问第一次走出贵族。','Confucius taught "regardless of class" — learning left the aristocracy.'] } ] },
{ l:'ea', s:'sino', v:1, n:'战国', k:[[-453,0],[-400,.42],[-350,.48],[-300,.5],[-250,.5],[-221,0]], b:'七个大国打了两百年,也吵了两百年——变法、铁犁与百家争鸣。',
  e:{ n:'Warring States', w:'Warring States period', b:'Seven kingdoms fought for two centuries — and argued for just as long.', d:'After Jin was carved into three, even the pretense of revering the king was dropped, and seven kingdoms each reformed to survive: Li Kui in Wei, Wu Qi in Chu, Shang Yang in Qin. Iron plows and ox-drawn ploughing turned wasteland into fields, and the Dujiangyan works that Li Bing built still water Sichuan today. At the Jixia Academy in Qi, Confucians, Daoists, Legalists, Mohists and logicians all talked at once — the loudest two centuries in Chinese thought. Qin won it with merit ranks and commanderies.', f:{ 'Peak':'Hundred Schools (4th–3rd c. BCE)', 'Center':'Xianyang, Linzi, Handan', 'Figures':'Shang Yang, Qu Yuan', 'Legacy':'Reform movements, iron farming, the Hundred Schools' } },
  f:{ '鼎盛':'百家争鸣(前4—前3世纪)', '中心':'咸阳、临淄、邯郸', '人物':'商鞅、屈原', '成就':'变法运动、铁器牛耕、诸子百家' },
  co:[ { n:['秦','Qin'], y:[null,-221], c:['雍→栎阳→咸阳','Yong, Yueyang, then Xianyang'], m:1 },
       { n:['楚','Chu'], y:[null,-223], c:['郢→寿春','Ying, later Shouchun'] },
       { n:['齐','Qi'], y:[null,-221], c:['临淄','Linzi'] },
       { n:['赵','Zhao'], y:[-453,-228], c:['晋阳→邯郸','Jinyang, later Handan'] },
       { n:['魏','Wei'], y:[-453,-225], c:['安邑→大梁','Anyi, later Daliang'] },
       { n:['韩','Hann'], y:[-453,-230], c:['阳翟→新郑','Yangdi, later Xinzheng'] },
       { n:['燕','Yan'], y:[null,-222], c:['蓟','Ji'] } ],
  qh:{ born:['谁不改革,谁就出局','Reform, or be eliminated'],
       rule:['绕开世袭贵族,改用拿薪水的官','Around the hereditary nobles, salaried officials instead'],
       money:['都江堰到今天还在浇地','Dujiangyan still waters the plain today'],
       power:['平民靠战功,也能换来爵位和田宅','Commoners could trade battle merit for rank and land'],
       fall:['秦手里有两个粮仓,十年灭掉六国','Qin held two granaries, and took all six in ten years'],
       legacy:['治国的工具箱,大半是这时候打出来的','Most of the toolkit for ruling was forged here'] },
  q:{ born:['三家分晋撕掉了旧秩序的最后遮羞布,七个大国进入你死我活的淘汰赛;生存压力逼着各国变法——谁不改革,谁就出局。','The partition of Jin tore away the old order\'s last fig leaf, and seven great powers entered a life-or-death elimination round. Survival pressure forced reform on everyone — change, or be knocked out.'],
      rule:['这个时代没有统一政权,统治的新形态却在竞争中诞生:各国君主绕开世袭贵族,把农民直接编入国家户籍,派拿薪水的官僚去管理郡县。变法最彻底的秦,把这台机器造得最完整。','No unified power existed, but a new form of rule was born in the contest: rulers bypassed hereditary nobles, registered peasants directly with the state, and sent salaried officials to run counties. Qin, the most thorough reformer, built this machine most completely.'],
      money:['铁犁与牛耕让荒地变良田,李冰修的都江堰至今仍在灌溉成都平原;各国铸造形状各异的货币,临淄这样的都会人口数十万。各国的财政,已能支撑数十万人规模的大军。','Iron plows and ox power turned wasteland into farmland, and Li Bing\'s Dujiangyan waterworks still irrigate the Chengdu plain today. States minted coins of wildly different shapes, and cities like Linzi held hundreds of thousands of people. State finances could now sustain armies numbering in the hundreds of thousands.'],
      power:['变强靠制度:魏国李悝、楚国吴起、秦国商鞅先后变法,军功爵让平民靠战功换地位,郡县制让君主的命令直达基层。战争随之升级为倾国动员的总体战,长平之战赵国损失的军队,据《史记》记载达四十余万——数字或有夸大。','Strength came from institutions: reformers like Li Kui, Wu Qi, and Shang Yang rebuilt their states, merit ranks let commoners rise through battlefield service, and county administration carried the ruler\'s orders down to the village. War escalated into total mobilization — at Changping, Zhao\'s losses were recorded (perhaps with exaggeration) at over four hundred thousand.'],
      fall:['格局的终结者是秦:据有关中和巴蜀两大粮仓,变法最彻底、动员最高效,再配上远交近攻的外交;从前230年起十年之内,六国次第而亡,前221年天下归一。','Qin ended the era: holding the twin granaries of the Wei valley and Sichuan, running the most thorough reforms and the most efficient mobilization, and pairing them with divide-and-conquer diplomacy. From 230 BCE it destroyed the six rival states within a decade, uniting the realm in 221 BCE.'],
      legacy:['以齐国稷下学宫为代表的百家争鸣,是中国思想史最富创造力的时期;官僚制、郡县制、户籍制这些国家机器零件的原型也在此锻成。此后两千年,中国人治国的工具箱大半来自战国。','The Hundred Schools debating at the Jixia academy made this the most creative period in Chinese intellectual history. The prototypes of bureaucracy, county administration, and household registration — core parts of the state machine — were also forged here. For the next two millennia, much of China\'s governing toolkit came from the Warring States.'] },
  d:'三家分晋之后,连"尊王"这块遮羞布也不要了,七个大国各自变法图强——魏国李悝、楚国吴起、秦国商鞅。铁犁和牛耕让荒地变成良田,李冰修的都江堰灌溉四川到今天;齐国的稷下学宫里儒道法墨名农各说各话,吵出了中国思想最热闹的两百年。最后靠军功爵和郡县制,秦赢了。',
  gl:[ { a:-453, b:-280, k:'thought', t:['百家争鸣','Hundred Schools'], d:['各国互相争斗、都急着找能富国强兵的办法,于是养士成风:儒家讲礼与仁、道家讲顺其自然、法家讲严刑峻法、墨家讲兼爱与守城。此后两千多年中国人争论的题目,大半是这几百年里提出来的。','The states were at each other\'s throats and all wanted a doctrine that would make them strong, so they kept scholars: the Confucians argued for ritual and humaneness, the Daoists for going with nature, the Legalists for strict law and punishment, the Mohists for universal love and the defence of cities. Most of what Chinese thinkers argued about for the next two thousand years was raised in these few centuries.'] } ] },
{ l:'ea', s:'sino', v:2, n:'秦', k:[[-221,0],[-219,.85],[-210,.9],[-207,0]], b:'十五年而亡的统一者:书同文、车同轨、郡县制。',
  e:{ n:'Qin', w:'Qin dynasty', b:'Fifteen years that installed China\'s operating system.', d:'King Zheng of Qin conquered the six rival states in ten years, then bound the realm into one system: one script, one axle width, commanderies in place of fiefs — the basic frame of Chinese government for two thousand years, built in fifteen. Yet its punishments were harsh and its labour levies endless; the First Emperor died and the realm rose in revolt. Qin lasted two reigns — and Han inherited its system whole.', f:{ 'Peak':'221–210 BCE', 'Center':'Xianyang', 'Figures':'Qin Shi Huang, Li Si, Meng Tian, Chen Sheng, Xu Fu', 'Legacy':'Unified script and measures, commanderies, the highways and the Wall' } },
  f:{ '鼎盛':'前221—前210', '中心':'咸阳', '人物':'秦始皇、李斯、蒙恬、陈胜、徐福', '成就':'统一文字度量衡、郡县制、驰道长城' },
  qh:{ born:['种地和打仗,被绑进同一套奖惩','Farming and fighting tied into one system of reward'],
       rule:['官由皇帝任免,不许世袭','Officials appointed by the emperor, never inherited'],
       money:['收的不是钱,是粮食和人力','What it collected was grain and labour, not coin'],
       power:['打仗是平民翻身最快的路','War was the fastest way up for a commoner'],
       fall:['统一之后,动员强度不降反升','After unification the demands went up, not down'],
       legacy:['制度被汉整个接手,速亡成了教训','Han kept the whole system; the swift fall became the lesson'] },
  q:{ born:['秦据关中,东有函谷之险可守,西北可开边扩土。商鞅变法把种地和打仗绑进同一套奖惩里,国家能直接支配到每一户的人力与田亩;再配上远交近攻的外交,秦用十年扫平六国,前221年建立起第一个中央集权的统一王朝。','Qin sat in the Wei River basin, shielded to the east by mountain passes and free to expand along its northwestern frontier. Shang Yang\'s reforms tied farming and fighting into a single system of rewards and punishments, letting the state reach down to every household for land and manpower. With that mobilisation machine and a diplomacy of befriending the far and attacking the near, Qin conquered the six rival states in ten years and founded China\'s first centralised unified dynasty in 221 BCE.'],
      rule:['郡县制取代分封:全国划为郡、县,长官由皇帝任免、不得世袭,命令从咸阳直达地方。配套的是统一文字、度量衡与车轨,让同一套政令在方言不同的地区都能执行;户籍、连坐与细密的律令,则保证人力随时可以征调。','Commanderies and counties replaced hereditary fiefs: officials were appointed and dismissed by the emperor and could not pass their posts to their sons, so orders ran from the capital straight to the ground. Standardised script, weights, measures and cart axles let one set of rules work across regions that spoke differently. Household registers, collective liability and a dense legal code kept manpower permanently available to the state.'],
      money:['财政直接建在土地和人身上:授田之后按亩收田租,按成年人收口赋,再用徭役和兵役直接征走劳动力,中间不太需要货币周转。半两钱统一了流通,但秦更依赖实物与人力的征发——这也是它一旦大工程齐上就绷不住的原因。','Revenue rested directly on land and people: a tax on cultivated acreage, a head tax on adults, and corvee and military service that took labour outright, with little need for money in between. The banliang coin standardised the currency, but the state leaned mainly on levies of grain and manpower — which is why its finances strained the moment several huge projects ran at once.'],
      power:['军功爵制让平民凭战场斩获升爵、换田宅,打仗成了改变身份最快的通道,举国的动员意愿因此被拉满。铁器、弩机与统一规格的后勤放大了这种力量;驰道、直道让军队与粮草能快速调往边境,北方旧长城则被连缀成一条防线。','Ranks earned on the battlefield let commoners win titles, land and houses, so war became the quickest route to a better life and the whole country had a reason to mobilise. Iron tools, the crossbow and standardised supplies multiplied that effect. Imperial highways moved troops and grain quickly to the frontiers, and the older northern walls were linked into one defensive line.'],
      fall:['主流看法是多因叠加,而不是暴政一条。统一之后动员强度不降反升,长城、驰道、宫室、戍边同时开工,民力被拉到极限;六国旧贵族与地方势力刚被打服、并未消化;始皇死后皇位交接混乱,中枢迅速失去权威。陈胜吴广一起事,各地旧势力随即响应。','Historians generally see several causes stacking up rather than tyranny alone. After unification the pace of mobilisation rose instead of falling — walls, highways, palaces and frontier garrisons all at once — stretching the population to its limit. The aristocracies of the conquered states had been beaten but not absorbed, and when the succession arrangement was overturned after the First Emperor\'s death the centre quickly lost authority. The Chen Sheng and Wu Guang revolt was followed almost immediately by risings across the old six states.'],
      legacy:['秦制被汉几乎整体接手:郡县、官僚、律令、户籍,构成此后两千年中国政治的默认框架。统一的文字让方言不同的地区共享同一套书面语,这是文化能长期延续的技术基础;而它十五年而亡的速度,也成了历代反复援引的教训。','Han took over the Qin system almost whole — commanderies, a salaried bureaucracy, codified law, household registers — and that became the default framework of Chinese politics for the next two thousand years. A single script let regions with different spoken languages share one written language, the technical basis of long cultural continuity. Its collapse after only fifteen years, meanwhile, became a cautionary tale later dynasties cited again and again.'] },
  d:'秦王嬴政用十年灭掉六国,又把全国拧成一套制度:文字统一、车轨统一、废除封国改设郡县——此后两千年中国政治的基本框架,十五年内一次成型。但它的刑罚同样严酷,劳役几乎不停;始皇一死各地就反了,秦朝只传了两代。而它创下的这套制度,被汉朝整体继承。' },
{ l:'ea', s:'sino', v:0, n:'西汉', k:[[-206,0],[-200,.5],[-141,.7],[-110,1],[-49,.85],[8,.4],[9,0]], b:'文景休养、武帝开边:凿空西域,与罗马各据欧亚一端。',
  e:{ n:'Western Han', w:'Han dynasty', b:'Rest, then expansion: the Silk Road opens; Rome\'s counterpart.', d:'The Western Han kept Qin\'s system but relaxed its harshest rules; after decades of recovery the treasury filled. Emperor Wu spent it all: driving back the Xiongnu in the north, opening the road west later called the Silk Road, and making Confucianism the state orthodoxy — the basic frame of Chinese governance for two thousand years was set here. In the dynasty\'s last years power slid to the empresses\' families, and Wang Mang finally took the throne through a staged "abdication."', f:{ 'Peak':'Emperor Wu (141–87 BCE)', 'Center':'Chang\'an', 'Figures':'Liu Bang, Emperor Wu, Zhang Qian, Sima Qian, Luoxia Hong, Consort Ban', 'Legacy':'Silk Road, Confucian state, the Records' } },
  f:{ '鼎盛':'汉武帝(前141—前87)', '中心':'长安', '人物':'刘邦、汉武帝、张骞、司马迁、落下闳、班婕妤', '成就':'丝绸之路、独尊儒术、《史记》' },
  qh:{ born:['制度照抄秦,但把征发的劲松开','Kept the Qin system, but eased the demands'],
       rule:['推恩令把大封国拆成小块','A decree cut the great fiefs into small ones'],
       money:['盐和铁收归官营,钱就回到国家手里','Salt and iron taken by the state, and wealth followed'],
       power:['先攒马和粮,再打到漠北去','Horses and grain first, then strikes deep into the north'],
       fall:['能收税的人越来越少','Fewer and fewer people the state could tax'],
       legacy:['郡县、察举、儒学,后世照着用了两千年','Commanderies, recommendation, Confucian learning — copied for two thousand years'] },
  q:{ born:['秦亡后是四年楚汉相争,刘邦在垓下胜出,前202年称帝。汉初吸取秦的教训,制度照搬秦制,但把征发强度降下来:轻徭薄赋、无为而治,让人口和粮食先长回来。文景两代攒下的家底,后来全被汉武帝投进了对外战争。','Qin\'s fall was followed by four years of civil war, and Liu Bang emerged the winner, taking the throne in 202 BCE. The early Han kept Qin\'s institutions but dialled down the demands: light taxes, light corvee, and a deliberately hands-off government that let population and grain stocks recover. The reserves built up under emperors Wen and Jing were later poured almost entirely into Emperor Wu\'s foreign wars.'],
      rule:['开国时是郡国并行——一半郡县、一半封国,结果封国坐大,七国之乱后靠推恩令把大国拆成小块,中央才真正压住地方。选官走察举,由地方长官举荐孝廉;汉武帝独尊儒术后,儒家经典成了官僚阶层共同的语言与考核标准。','The dynasty began as a hybrid: half directly ruled commanderies, half hereditary kingdoms. After the kingdoms grew strong enough to rebel, a law forcing each prince to divide his land among all his sons broke them into harmless fragments and the centre finally held. Officials were recommended by local governors rather than examined, and once Emperor Wu made Confucian learning the state doctrine, the classics became the shared language and yardstick of the bureaucracy.'],
      money:['底子是田赋与人头税,加上盐铁这类大宗物资。武帝打匈奴打空了国库,于是把盐、铁、酒收归官营,又用均输平准调运物资、平抑物价,并向商人征财产税,把民间财富转到国家手里。五铢钱由中央统一铸造,币权从此不再下放。','The base was a land tax and a head tax, plus bulk commodities. Emperor Wu\'s campaigns against the Xiongnu emptied the treasury, so the state took salt, iron and liquor into government monopoly, used a network of transport and price-levelling offices to move goods and steady prices, and taxed merchants\' property — shifting private wealth into public hands. The wuzhu coin was minted centrally, and the right to strike money was never devolved again.'],
      power:['文景积攒的马匹与粮仓,让汉军从守势转成骑兵集团的远程突击,卫青、霍去病数次深入漠北。张骞出使打开了通往西域的通道,前60年设西域都护府,汉的影响延伸到中亚绿洲城邦;这条路后来被称作丝绸之路。','The horses and granaries accumulated under Wen and Jing let Han armies switch from defence to long-range cavalry strikes deep into the steppe. Zhang Qian\'s missions opened the corridor to the Western Regions, and in 60 BCE a protector-general\'s office extended Han influence to the oasis city-states of Central Asia. That corridor later became known as the Silk Road.'],
      fall:['机制上是税基被慢慢掏空:豪族兼并土地,自耕农破产成为佃户或流民,国家能收税、能征兵的登记人口越来越少。政治上则是外戚长期把持中枢,成帝哀帝之后皇统屡屡断绝,王氏一门权势独大;公元9年王莽以禅让形式代汉建新。这条路径与后来东汉的崩溃并不相同。','The underlying mechanism was an eroding tax base: powerful families bought up land, smallholders sank into tenancy or vagrancy, and the number of registered households the state could tax and conscript kept shrinking. Politically, the families of empresses held the central government for decades, and after a run of emperors died without heirs the Wang clan stood alone at the top. In 9 CE Wang Mang took the throne through a staged abdication and founded a new dynasty. This path was quite different from the way the Eastern Han later came apart.'],
      legacy:['汉字、汉族、汉语这些名字都来自这个王朝,它是中国人自我认同的起点之一。制度上,郡县加察举加儒家意识形态的组合成为后世标准配置;丝绸之路把中原和中亚、地中海世界连了起来;司马迁的《史记》确立了纪传体,此后两千年的正史都照它的体例写。','The words for Chinese characters, the Han ethnic name and the Chinese language all come from this dynasty, which is one of the starting points of Chinese self-identity. Institutionally, the package of commandery administration, recommendation-based recruitment and Confucian ideology became the standard template for later dynasties. The Silk Road linked the Chinese heartland to Central Asia and the Mediterranean world, and Sima Qian\'s Records of the Grand Historian set the biographical format that every official history followed for the next two thousand years.'] },
  d:'西汉继承了秦朝的制度,却放宽了其中最严苛的部分;经过几十年休养生息,国力渐渐充实。汉武帝将这份积蓄尽数投入:北面击退匈奴,向西打通了后来被称为丝绸之路的商路,又确立"独尊儒术"——此后两千年中国治国的基本框架,就在这时定型。王朝晚期,大权落入皇后家族(外戚)手中,王莽最终借一场"禅让"取代了汉朝。',
  gl:[ { a:-179, b:-141, k:'econ', t:['文景之治','Wen-Jing prosperity'], d:['轻徭薄赋不是一句空话:文帝前 178 年与前 168 年两次「除田租税之半」,田租税率最后定在三十税一,文帝十三年(前 167)六月干脆把全国田租免了——而且不是免一年:这一免持续了约十三年,直到景帝时才恢复征收、定在三十税一。几十年攒下来的样子,《汉书·食货志》有一段很具体的描写——京城库里的钱堆到「贯朽而不可校」,串钱的绳子烂了、数都数不清;太仓的粟一层压一层堆到仓外露天放着,放到坏掉不能吃。这笔家底后来被武帝一次性花在了打匈奴和通西域上。','Light taxes were not a slogan. In 178 and again in 168 BC Emperor Wen cut the land tax by half, the rate settled at one part in thirty, and in his thirteenth year, 167 BC, he remitted it altogether — not for one year but for some thirteen, until the reign of his son restored it at one part in thirty. The Book of Han describes what decades of that looked like: in the capital treasury the strings holding the coin had rotted through and the money could no longer be counted, while grain piled up in the granaries year on year, spilled out into the open air and rotted where it lay. Emperor Wu spent the whole of that inheritance on the Xiongnu wars and the road west.'] },
       { a:-186, b:-168, k:'thought', t:['一座墓里挖出来的两千年前的书','Books two thousand years old, out of a grave'], d:['1971 年底到 1974 年初,长沙马王堆挖开三座西汉墓。一号墓的女主人下葬两千一百年,遗体竟然保存了下来;她的名字刻在印章上,末一个字起初认不出,后来读作「辛追」,也有学者认为该读「避」——连墓主叫什么都还在争。三号墓里出土简牍六百一十支——遣策四百一十支、医书两百支;另有一批帛书,《老子》《周易》与《战国纵横家书》都写在上面(它与传世的《战国策》不是同一部书);还有帛画四幅,最大的一幅呈 T 形,通长 2.33 米。这些书两千年没人读过,一出土就把好几部古籍的版本往前推了一大截。','Between late 1971 and early 1974 three Han graves were opened at Mawangdui outside Changsha. The woman in tomb one had lain there twenty-one centuries and her body had survived; her name is cut on a seal whose last character could not be read at first — it is now usually given as Xin Zhui, though some scholars read it as Bi, so even what she was called is still argued over. Tomb three gave up six hundred and ten bamboo and wooden slips — four hundred and ten of grave inventory, two hundred of medicine — and, separately, a body of manuscripts written on silk, among them the Laozi, the Book of Changes and a text on the Warring States that is not the transmitted Stratagems but a different compilation; and four silk paintings, the largest T-shaped and 2.33 metres long. Nobody had read these books for two thousand years, and the moment they came out they pushed the earliest text of several classics a long way back.'] },
       { a:-134, b:-50, k:'thought', t:['经学时代','Classicist scholarship'], d:['独尊儒术,五经博士,儒学成为帝国官学。','Confucianism becomes imperial orthodoxy.'] } ] },
{ l:'ea', s:'sino', v:1, n:'东汉', k:[[23,0],[25,.5],[57,.7],[105,.75],[150,.6],[184,.4],[208,.3],[220,0]], b:'光武中兴、蔡伦造纸;豪族与宦官外戚之争终致黄巾。',
  e:{ n:'Eastern Han', w:'Han dynasty', b:'Restoration, paper, Buddhism — then eunuchs, warlords, Yellow Turbans.', d:'After Wang Mang\'s regime collapsed in chaos, Emperor Guangwu rebuilt the Han with its capital at Luoyang. Ban Chao reopened the Western Regions with a party of thirty-six; Cai Lun improved papermaking; Buddhism arrived along the Silk Road. In later reigns the empresses\' families and the palace eunuchs took turns running the court, and critics were twice banned from office en masse — trust drained away. When the Yellow Turbans rose, regional strongmen raised their own armies: the prologue to the Three Kingdoms.', f:{ 'Peak':'Ming-Zhang era (57–88)', 'Center':'Luoyang', 'Figures':'Guangwu, Ban Chao, Cai Lun, Zhang Heng', 'Legacy':'Paper, Buddhism\'s arrival, an imperial academy of thirty thousand' } },
  f:{ '鼎盛':'明章之治(57—88)', '中心':'洛阳', '人物':'光武帝、班超、蔡伦、张衡', '成就':'造纸术、佛教传入、太学三万人' },
  qh:{ born:['靠豪族起家,就得和豪族共处','Raised up by the great clans, it had to live with them'],
       rule:['皇帝年长就管用,皇帝年幼就失灵','It worked with a grown emperor, and failed with a child'],
       money:['税更轻了,国家却没多收到钱','The tax was lighter, and the state got no more'],
       power:['班超在西域,靠的是结盟不是大军','Ban Chao held the west by alliance, not by armies'],
       fall:['外戚和宦官轮流坐庄,兵权掉到地方','Consort clans and eunuchs took turns; the armies went local'],
       legacy:['造纸变便宜,书写的门槛塌了一截','Paper got cheap, and the cost of writing fell away'] },
  q:{ born:['王莽的托古改制在土地、奴婢、货币上连番变动,又遇上黄河改道与连年灾荒,绿林、赤眉相继起事。刘秀出身南阳,靠河北与南阳的豪族支持胜出,25年重建汉室、定都洛阳。这层豪族出身,决定了东汉从一开始就要和地方大族共处。','Wang Mang\'s attempts to remake landholding, slavery and the currency in the name of antiquity collided with a shift in the Yellow River\'s course and years of famine, and mass revolts followed. Liu Xiu, from a landed Nanyang family, won with the backing of the great clans of Hebei and Nanyang, restored the Han in 25 CE and moved the capital to Luoyang. That base among the gentry meant the Eastern Han had to live with powerful local families from the very start.'],
      rule:['皇帝把决策权收进身边的尚书台,三公变成荣衔,中枢反而更依赖亲信。地方上,朝廷承认豪族的势力,靠他们征税、维持秩序;察举与征辟造出层层门生故吏的人情网,官位与家族逐渐挂钩。这套安排在皇帝年长时有效,皇帝年幼时就会失灵。','The emperor pulled decision-making into a secretariat of close attendants while the three senior ministries became honorific, so the centre came to depend on personal favourites. In the provinces the court accepted the power of the great clans and used them to collect taxes and keep order. Recruitment by recommendation and personal appointment built dense webs of patrons and proteges, and offices drifted towards particular families. The arrangement worked when the emperor was an adult, and broke down when he was a child.'],
      money:['田租定在三十税一,比西汉还轻,可国家实际收到的钱并没有变多。原因在结构:豪强的大庄园兼并土地、荫庇依附人口,这些人不上国家户籍,也就不纳税不服役。庄园自己冶铁、纺织、酿酒,几乎自给自足,商品和赋税都少经过朝廷的手。','The land tax was set at one part in thirty, lighter than under the Western Han, yet the state did not end up with more. The reason was structural: great estates absorbed both fields and the people who worked them, and those dependants never appeared on government registers, so they paid no tax and served no corvee. The estates smelted their own iron, wove their own cloth and brewed their own liquor, so goods and revenue alike largely bypassed the court.'],
      power:['军事上不再走西汉那种举国远征的路子,而是依靠边郡驻军、招募内附族群充当骑兵,再配合外交分化。班超以极少人手在西域纵横数十年,靠的是结盟与威望而非大军。这套办法省钱,但也让朝廷对边地军事集团的依赖越来越深。','Rather than the Western Han\'s nationwide expeditions, the Eastern Han relied on frontier garrisons, cavalry recruited from allied steppe and northwestern peoples, and diplomacy that split its enemies. Ban Chao operated in the Western Regions for decades with a tiny staff, working through alliances and prestige rather than armies. It was cheap, but it deepened the court\'s dependence on frontier military groups.'],
      fall:['路径和西汉不同:这里的循环是幼帝即位、母族外戚辅政、皇帝长大后借宦官夺权,如此反复,朝廷高层始终在内斗。士人反对宦官,遭到党锢之祸,读书人对朝廷离心。与此同时豪强已有坞堡与私人部曲。184年黄巾起事后朝廷放开地方募兵,188年又改刺史为州牧、军政合一,兵权就此下移到地方,董卓之乱后各军事集团割据成形。','The path differed from the Western Han\'s. Here the cycle was a child emperor, regency by the empress\'s family, then the grown emperor using palace eunuchs to seize power back — repeated until the top of government was in permanent conflict. Scholar-officials who opposed the eunuchs were purged and banned from office, alienating the educated class, while the great clans already had walled compounds and private troops of their own. After the Yellow Turban risings of 184, the court let provincial governors raise their own armies to suppress them, military power passed to the regions, and after Dong Zhuo\'s coup the warlord era took shape.'],
      legacy:['蔡伦改良的造纸法让书写材料变便宜,长期看这是中国知识传播成本的一次断崖式下降。佛教在这一时期沿丝路传入并开始译经;太学一度有三万余名太学生,经学与士人群体成为独立的政治力量。张衡的浑天仪与候风地动仪,是当时官方天文机构的产物。','Cai Lun\'s improved papermaking made writing material cheap, which over the long run cut the cost of spreading knowledge in China dramatically. Buddhism entered along the Silk Road in this period and the first sutra translations began. The imperial academy at one point held over thirty thousand students, and classical scholarship gave the educated class an independent political weight. Zhang Heng\'s armillary sphere and seismoscope came out of the official astronomical bureau of the time.'] },
  d:'王莽的政权在大乱中垮台后,光武帝重建汉室,定都洛阳。班超只带三十六人出使,就重新打通了西域;蔡伦改良造纸,佛教也沿丝路传入中国。王朝中后期,皇后家族(外戚)与宦官轮流把持朝政,批评时政的士人两次被成批禁锢(党锢之祸),人心渐渐散了;黄巾起义一起,各地豪强拥兵自立——三国的序幕就此拉开。' },
{ l:'ea', s:'sino', v:2, n:'三国', k:[[220,0],[229,.45],[263,.4],[280,0]], b:'魏蜀吴鼎立六十年;一段被演义放大千年的历史。',
  e:{ n:'Three Kingdoms', b:'Wei, Shu and Wu — sixty years magnified a thousandfold by legend.', d:'Red Cliffs fixed the tripod: Wei on the plain, Shu in Sichuan, Wu on the Yangtze. Zhuge Liang died on his fifth northern campaign; Wei took Shu, Jin took Wei and then Wu. Sixty years of history — and China\'s most beloved epic ever since.', f:{ 'Peak':'229–263', 'Center':'Luoyang, Chengdu, Jianye', 'Figures':'Cao Cao, Liu Bei, Sun Quan, Zhuge Liang', 'Legacy':'Military-agricultural colonies, the south and south-west opened' } },
  f:{ '鼎盛':'三足鼎立(229—263)', '中心':'洛阳、成都、建业', '人物':'曹操、刘备、孙权、诸葛亮', '成就':'屯田制、江南与西南的深度开发' },
  co:[ { n:['魏','Wei'], y:[220,265], c:['洛阳','Luoyang'], m:1 },
       { n:['蜀汉','Shu Han'], y:[221,263], c:['成都','Chengdu'] },
       { n:['东吴','Eastern Wu'], y:[229,280], c:['建业','Jianye'] } ],
  qh:{ born:['山和江把天下切成了三块','Mountains and the great river cut the land in three'],
       rule:['三家各走一条路,后来都留下影响','Three states, three answers, all three left a mark'],
       money:['先把粮食问题稳住,才谈别的','Steady the grain first, everything else after'],
       power:['三家的长处不一样,谁也吃不掉谁','Each was strong in a different way, so none could swallow another'],
       fall:['北方的人和地就是多,耗下去必赢','The north simply had more people and land, and time favoured it'],
       legacy:['六十年的历史,中国人却最熟','Sixty years, and the best-known stretch of Chinese history'] },
  q:{ born:['汉末州牧握兵、豪强自守,中央权威消失后,群雄兼并了二十年。官渡之战让北方归于一家,赤壁之战则挡住了它南下的势头,长江与秦岭巴山把版图切成三块。220年汉献帝禅位,三个政权先后称帝,分裂由事实变成名分。','Once provincial governors held armies and great families fortified themselves, central authority vanished and rival warlords fought for twenty years. The battle of Guandu left the north under one house; the battle of Red Cliffs stopped that house from taking the south. The Yangtze and the mountain barriers of the west then cut the map into three. In 220 the last Han emperor abdicated, and within a decade three courts had each claimed the imperial title, turning division from a fact into a formal arrangement.'],
      rule:['这个时代没有统一政权,三方各自摸索,竞争本身就是答案。北方与士族妥协,建立按门第与品评定官阶的选官办法;西南由丞相集权,以严明的法令弥补地盘小、人口少;东南则和江东大族分权,将领世袭领兵、自带部曲。三条路后来都留下了长影响。','There was no single government in this age; each of the three courts tried its own answer, and the competition itself is the answer to the question. The northern state compromised with the aristocratic clans and graded official rank by family standing; the southwestern state concentrated power in its chancellor and used strict, transparent law to make up for a small territory and population; the southeastern state shared power with the great families of the lower Yangtze, letting commanders inherit their units and bring their own retainers. All three approaches cast long shadows.'],
      money:['战乱使人口流散、田地抛荒,恢复生产成了第一要务。北方推行屯田,把流民和士兵编组起来官给牛种、分成交租,粮食问题因此先稳住。西南以蜀锦作为对外换取物资的硬通货;东南则靠江南水田的开垦、山地族群的编户,以及沿海与海外的往来。','War scattered the population and left fields idle, so restoring production came first. The north organised refugees and soldiers into state farms, supplying oxen and seed in return for a share of the harvest, which stabilised the grain supply. The southwest used its famous brocade as hard currency for goods it could not make. The southeast opened wet-rice land in the lower Yangtze, brought upland peoples onto the tax registers, and traded along the coast and overseas.'],
      power:['三方的强项正好是三种不同的资源:中原有最多的耕地与人口,还能从北方边地取得战马;西南有秦岭与三峡的天险,易守难攻;东南有长江和成建制的水军,北方骑兵到了江边就失去优势。谁也吃不掉谁,僵局才持续了几十年。','Each side\'s strength was a different kind of resource. The central plain had the most farmland and people and could get warhorses from the northern frontier; the southwest was ringed by mountains and gorges that were hard to attack and easy to hold; the southeast had the Yangtze and a real navy, so northern cavalry lost its advantage at the water\'s edge. Because none could swallow another, the deadlock lasted for decades.'],
      fall:['根本原因是国力不对等:户籍所载的人口与耕地,北方远多于另外两方,长期消耗战对它有利。西南多次北伐都受限于粮道翻山,263年被灭;北方内部则由掌兵的家族取代了皇室;280年晋军顺流东下,东南政权投降,分裂结束。','The basic reason was unequal weight: on the registers the north had far more people and farmland than the other two combined, so a long war of attrition favoured it. The southwest\'s repeated northern campaigns were limited by supply lines that had to cross mountains, and it fell in 263. In the north itself, the family that controlled the army replaced the ruling house. In 280 its fleet came down the Yangtze, the southeastern state surrendered, and the division ended.'],
      legacy:['按门第定品级的选官办法本是权宜,后来固化成门阀政治,影响此后三百多年。屯田制成为历代战后恢复生产的常用手段。长江以南和西南的开发在这几十年里明显提速,为后来的经济重心南移打了底。而《三国演义》让这段六十年的历史,成为中国人最熟悉的一段。','Grading officials by family standing began as a stopgap and hardened into aristocratic politics that shaped the next three centuries. State farming became a standard tool for restarting agriculture after any war. Development of the lands south of the Yangtze and in the southwest sped up noticeably in these decades, laying groundwork for the later shift of China\'s economic centre southward. And the novel Romance of the Three Kingdoms made these sixty years the stretch of history Chinese readers know best.'] },
  d:'赤壁之战定下三分格局:曹魏据中原、蜀汉守巴蜀、孙吴开江东。诸葛亮五次北伐,最终病逝军中;魏将邓艾抄小路奇袭灭蜀,取代魏的西晋又顺江而下灭吴。正史六十年,却因《三国演义》成为中国人最熟的一段历史——江南与西南的开发也自此提速。' },
{ l:'ea', s:'sino', v:1, n:'西晋', k:[[266,0],[280,.5],[300,.4],[311,.15],[316,0]], b:'短暂统一即陷八王之乱;永嘉之祸,衣冠南渡。',
  e:{ n:'Western Jin', w:'Jin dynasty (266–420)', b:'Brief reunification, then princes\' wars and the fall of Luoyang.', d:'The Sima clan reunified the realm, then armed its princes: sixteen years of internecine war invited the Xiongnu in. Luoyang fell in 311 — the "Yongjia catastrophe" — and the northern gentry fled south en masse.', f:{ 'Peak':'Taikang era (280–289)', 'Center':'Luoyang', 'Figures':'Sima Yan', 'Legacy':'A reunification that failed' } },
  f:{ '鼎盛':'太康之治(280—289)', '中心':'洛阳', '人物':'司马炎', '成就':'再统一(旋即失序)' },
  qh:{ born:['靠士族抬上台,就得一直给他们好处','Put in power by the great clans, and paying them ever after'],
       rule:['和士族共治,又给亲王兵权','Shared rule with the clans, and armies to the princes'],
       money:['统一那天起,财政就是单薄的','The treasury was thin from the day of unification'],
       power:['兵不在朝廷手上,在亲王手上','The armies belonged to the princes, not to the court'],
       fall:['自家亲王互相攻杀了十几年','The princes spent a decade killing each other'],
       legacy:['人口、技术和典籍,一起搬去了江南','People, skills and books all moved south together'] },
  q:{ born:['曹魏后期兵权与朝政落入司马氏手中,三代经营之后以禅让形式改朝换代。266年建晋,280年灭东南政权,分裂近百年的中国重归一统。开国靠的是士族的支持而非征服的余威,这决定了它必须持续让渡利益给这些家族。','In the late years of the northern state the army and the court both fell into the hands of the Sima family, and after three generations of consolidation they took the throne through a staged abdication. The Jin dynasty was founded in 266 and conquered the southeastern state in 280, reuniting a China that had been split for nearly a century. It came to power through aristocratic backing rather than conquest, which meant it had to keep paying those families in privileges.'],
      rule:['两条主线都是为了避免重蹈前朝覆辙,结果都出了问题。一是与士族共治,用占田荫客制正式承认他们可以按品级占地、庇护佃客;二是吸取前朝宗室无权、孤立而亡的教训,大封同姓诸王并给他们封地和军队。中央因此既缺钱,又缺对军权的独占。','Both of its main policies were meant to avoid the previous dynasty\'s fate, and both backfired. The first was co-rule with the aristocracy: a land statute formally allowed noble families to hold estates and shelter tenants according to rank. The second was a reaction to the previous dynasty\'s isolation, in which imperial kinsmen had held no power: Jin gave its princes territories and armies of their own. The result was a centre short of both money and a monopoly on force.'],
      money:['推行占田课田与户调:名义上规定每户可占多少地、须按亩纳粮,并按户征收绢绵。问题在于士族依品占田且能荫庇大量佃客,这些人不入国家户籍;真正承担赋役的自耕农数量有限,财政从统一之初就单薄。','The state set quotas for how much land a household could hold and how much it owed per acre, and collected silk and floss by household. The trouble was that noble families could claim land by rank and shelter large numbers of tenants who never entered the government registers. The pool of smallholders actually carrying the burden stayed small, so the treasury was thin from the moment of unification.'],
      power:['军力承自曹魏,统一后又吸收了南方的资源,论总量并不弱。但兵不在中央而在宗王手上,几个亲王各据要地、各掌一军;同时大量内迁的匈奴、羯、鲜卑、氐、羌人口早已编入军队与户籍,是现成的战斗力,也是随时可能自立的力量。','Its forces were inherited from the previous northern state and topped up with southern resources, so on paper they were not weak. But the troops sat with the princes rather than the capital, several of whom held key regions with their own armies. At the same time large numbers of Xiongnu, Jie, Xianbei, Di and Qiang people who had migrated inland were already enrolled in the armies and registers — ready fighting strength, and also a force that could break away at any moment.'],
      fall:['统一才十年就开始崩解。惠帝无力主政,后族与诸王争夺辅政之权,酿成八王之乱,宗王们互相攻杀十余年,把中央的军队与粮储打光了。内迁族群在混战中被各方拉拢参战,随后自立建国;311年洛阳陷落、316年长安陷落,西晋亡。多因叠加,而不是某一族入侵。','It began to come apart barely ten years after unification. An emperor unable to govern left the empress\'s family and the imperial princes fighting over the regency, touching off more than a decade of civil war among the princes that consumed the central army and its grain reserves. The inland-settled peoples were recruited by one side or another during the fighting and then set up states of their own. Luoyang fell in 311 and Chang\'an in 316 — a stack of causes, not a single invasion.'],
      legacy:['永嘉之后中原士族大批南迁,把人口、技术、典籍和家学带到江南,南方的深度开发从此起步。门阀政治在这一时期定型,并在东晋达到顶点。而一个刚统一就迅速瓦解的王朝,后来被历代反复引用:分封与共治的边界该划在哪里,是它留下的问题。','After 311 the northern aristocracy moved south in large numbers, carrying people, techniques, books and family scholarship with them, and the serious development of the south began there. Aristocratic politics took its mature form in this period and peaked under the following dynasty. And an empire that fell apart almost as soon as it had united became a case study later rulers cited again and again: where exactly to draw the line on enfeoffment and power-sharing is the question it left behind.'] },
  d:'司马氏代魏灭吴,天下重归一统,却大封宗室埋下祸根:八王之乱自相残杀十六年,匈奴刘渊趁虚而入,311年洛阳陷落——"永嘉之乱"后中原士族举族南渡,北方进入五胡十六国时代。' },
{ l:'ea', s:'sino', v:0, n:'东晋·十六国', k:[[317,0],[350,.35],[383,.4],[420,0]], b:'北方五胡迭起,南方偏安江左;淝水一战保住半壁。',
  e:{ n:'E. Jin & 16 Kingdoms', w:'Sixteen Kingdoms', b:'The north churns; the south holds at the Fei River.', d:'Sixteen short-lived northern regimes churned while the émigré court held the south; at the Fei River in 383, eighty thousand beat a claimed million and preserved the southern line. Wang Xizhi\'s Orchid Pavilion and Faxian\'s pilgrimage both belong to this turbulent age.', f:{ 'Peak':'383 (after the Fei River)', 'Center':'Jiankang; northern capitals', 'Figures':'Wang Dao, Xie An, Wang Xizhi, Fu Jian', 'Legacy':'The Yangtze south developed, calligraphy\'s peak, Faxian\'s journey west' } },
  f:{ '鼎盛':'383年(淝水之战,南方转危为安)', '中心':'建康;北方诸都', '人物':'王导、谢安、王羲之、苻坚', '成就':'江南开发、书法巅峰、法显西行' },
  co:[ { n:['东晋','Eastern Jin'], y:[317,420], c:['建康','Jiankang'], m:1, g:['南方','South'], x:['士族拥晋室偏安','the gentry held the south'] },
       { n:['成汉','Cheng-Han'], y:[304,347], c:['成都','Chengdu'], g:['北方','North'], x:['等十六国,走马灯','among sixteen states, in quick succession'] },
       { n:['前赵','Former Zhao'], y:[304,329], c:['平阳→长安','Pingyang, later Chang\'an'], g:['北方','North'] },
       { n:['后赵','Later Zhao'], y:[319,351], c:['襄国→邺','Xiangguo, later Ye'], g:['北方','North'] },
       { n:['前燕','Former Yan'], y:[337,370], c:['龙城→邺','Longcheng, later Ye'], g:['北方','North'] },
       { n:['前秦','Former Qin'], y:[351,394], c:['长安','Chang\'an'], m:1, g:['北方','North'] },
       { n:['后秦','Later Qin'], y:[384,417], c:['长安','Chang\'an'], g:['北方','North'] } ],
  qh:{ born:['南北同时开场,起因是同一场崩溃','North and south began at once, from the same collapse'],
       rule:['南边王与马共天下,北边胡汉分治','In the south, clans shared the throne; in the north, two systems'],
       money:['南方在开荒,北方退回以物易物','The south broke new fields; the north fell back to barter'],
       power:['北府兵是防线,后来也成了改朝的手','The northern garrison was the shield, and then the sword'],
       fall:['握兵的人最后取代了朝廷','The man who held the army replaced the court'],
       legacy:['经济重心从这里开始往南挪','This is where the economic centre started moving south'] },
  q:{ born:['洛阳、长安相继陷落后,琅琊王司马睿在建康被南渡士族与江东大族共同推上帝位,晋室得以延续,史称东晋。北方则由内迁各族与地方势力反复建国、灭国,史书笼统称作十六国。南北同时开始,起因是同一场崩溃。','After Luoyang and then Chang\'an fell, a Jin prince at Jiankang was raised to the throne jointly by the emigre northern aristocracy and the established families of the lower Yangtze, and the dynasty continued in the south. In the north, the inland-settled peoples and regional strongmen founded and destroyed states in quick succession, a period historians group under a conventional count of sixteen. South and north both begin here, out of the same collapse.'],
      rule:['南北各转各的:南方是门阀政治,几大家族轮流执政,皇帝的权力受制于他们,时人有王与马共天下之说;北方多数政权采取胡汉分治,本族保持部落军事组织,汉人按郡县编户耕作、并任用汉人文官处理行政。','There was no unified government in this age; south and north ran different systems, and the competition itself is the answer. The south was aristocratic politics: a handful of great families took turns running the government and the emperor\'s authority was bounded by them, summed up in the saying that the Wang clan shared the realm with the imperial Sima house. Most northern states ran a dual system, keeping their own people in tribal military organisation while the Chinese population farmed under ordinary county administration, with Chinese scholars staffing the civil offices.'],
      money:['南方设侨州郡县安置南下流民,同时开垦江南的圩田、山泽与丘陵,农业产能在这一百年里明显提升,商业与航运也随建康的繁荣起来。北方战乱频繁,货币经济退化,交易多用实物与绢帛,政权财政主要靠军屯、征发与战争所得。','The south set up shadow prefectures to settle refugees from the north while opening polder fields, hills and marshland in the Yangtze valley, and agricultural output rose noticeably over this century, with trade and river shipping growing alongside the capital. In the north, constant war rolled the money economy back: transactions were largely in grain and silk, and states funded themselves through military colonies, requisition and the spoils of war.'],
      power:['南方的凭借是长江天险,加上用南渡流民组建的北府兵——这支军队既是防线,也是后来改朝换代的力量。北方各政权靠的是本族骑兵与部落兵制,动员快、战力强,但政权与君主个人绑得太紧。383年淝水之战,南方守住了长江以南。','The south relied on the Yangtze as a barrier plus an army raised from northern refugees, a force that served both as its shield and, later, as the instrument that changed the dynasty. Northern states relied on their own cavalry and tribal levies, which mobilised fast and fought hard but were bound too tightly to the person of each ruler. At the battle of the Fei River in 383 the south held the line.'],
      fall:['南方的终结来自内部:门阀之间倾轧不断,孙恩卢循的民变消耗了东南财赋之地,桓玄一度篡位,最后握有北府兵的刘裕以军功取代晋室,420年建宋。北方各政权则普遍缺乏稳定的继承制度与官僚体系,常常君主一死就分裂,直到北魏才把北方重新整合起来。','In the south the end came from inside: the great families fought one another constantly, the Sun En and Lu Xun rebellions drained the wealthy southeast, a general briefly usurped the throne, and finally Liu Yu, who commanded the refugee army, replaced the Jin house on the strength of his victories and founded the Song in 420. Northern states generally lacked stable succession rules or a durable bureaucracy and tended to split apart the moment a ruler died, until the Northern Wei finally reassembled the north.'],
      legacy:['江南从此不再是边缘,人口、水利与文化都上了一个台阶,经济重心南移由此启动。书法与玄学在这一百年达到高峰,兰亭雅集是它的代表场景。佛教在南北同时扎根:法显走陆路去印度、经海路回国,带回并翻译了大量戒律典籍;北方则有大规模的译场。族群之间的通婚、共居与制度互鉴,也在这个乱世里开始。','The lower Yangtze stopped being a periphery: population, water control and culture all rose a level, and the long shift of China\'s economic centre southward began here. Calligraphy and metaphysical philosophy peaked in this century, epitomised by the gathering at the Orchid Pavilion. Buddhism took root in both halves: the monk Faxian travelled overland to India and returned by sea, bringing back and translating a large body of monastic texts, while the north ran large translation workshops. Intermarriage, shared settlement and the borrowing of institutions between peoples also began in this age of division.'] },
  d:'北方在五胡十六国的走马灯中反复破碎,南方士族拥立晋室,在建康(今南京)守住半壁江山;383年淝水之战,谢安以八万胜苻坚号称百万,保住江南文脉。王羲之写下《兰亭序》的那场雅集,与法显徒步万里去印度求经,都发生在这个乱世。',
  gl:[ { a:340, b:420, k:'art', t:['书法与玄学','Calligraphy & Neo-Daoism'], d:['王羲之的行书至今是中文书写的美学标尺。','Wang Xizhi sets the aesthetic standard of the script.'] } ] },
{ l:'ea', s:'sino', v:1, n:'南北朝', k:[[420,0],[450,.4],[494,.45],[550,.4],[589,0]], b:'南朝四代与北朝汉化并行;佛教石窟时代。',
  e:{ n:'N. & S. Dynasties', w:'Northern and Southern dynasties', b:'Southern letters, northern reforms; the grotto-Buddha age.', d:'Four southern courts cultivated letters while the Xianbei north moved to Luoyang and sinicized wholesale; the equal-field and garrison-militia systems — two pillars of Sui-Tang — were cast in the north. The Yungang and Longmen Buddhas rose above the wars.', f:{ 'Peak':'early 6th c. (after the Xiaowen reforms)', 'Center':'Jiankang; Pingcheng → Luoyang', 'Figures':'Emperor Xiaowen, Emperor Wu of Liang', 'Legacy':'Grotto Buddhas, the equal-field system, the militia system' } },
  f:{ '鼎盛':'6世纪初(北魏孝文帝改革后)', '中心':'建康、平城→洛阳', '人物':'北魏孝文帝、萧衍(梁武帝)', '成就':'云冈龙门石窟、均田制、府兵制' },
  co:[ { n:['刘宋','Liu Song'], y:[420,479], c:['建康','Jiankang'], m:1, g:['南朝','Southern'] },
       { n:['南齐','Southern Qi'], y:[479,502], c:['建康','Jiankang'], g:['南朝','Southern'] },
       { n:['梁','Liang'], y:[502,557], c:['建康','Jiankang'], g:['南朝','Southern'] },
       { n:['陈','Chen'], y:[557,589], c:['建康','Jiankang'], g:['南朝','Southern'] },
       { n:['北魏','Northern Wei'], y:[386,534], c:['平城→洛阳','Pingcheng, later Luoyang'], m:1, g:['北朝','Northern'] },
       { n:['东魏','Eastern Wei'], y:[534,550], c:['邺','Ye'], g:['北朝','Northern'] },
       { n:['西魏','Western Wei'], y:[535,556], c:['长安','Chang\'an'], g:['北朝','Northern'] },
       { n:['北齐','Northern Qi'], y:[550,577], c:['邺','Ye'], g:['北朝','Northern'] },
       { n:['北周','Northern Zhou'], y:[557,581], c:['长安','Chang\'an'], g:['北朝','Northern'] } ],
  qh:{ born:['都说自己是正统,谁也吞不下谁','Each called itself legitimate, and neither could swallow the other'],
       rule:['同一个问题,南北给了两种解法','One problem, and two different answers'],
       money:['无主的荒地,按人头分给农民','Ownerless land handed out by the head'],
       power:['当兵的单独立籍,战时自带装备','Soldiers on a separate roll, bringing their own gear'],
       fall:['南边被一场乱打断,北边分家后西边赢了','One revolt broke the south; the north split and the west won'],
       legacy:['均田、府兵、三省,都是这时候的产物','Land allotment, militia, three departments: all born here'] },
  q:{ born:['南方由掌兵的将领取代晋室,开启宋齐梁陈四代相继的南朝;北方则由鲜卑拓跋部建立的北魏在439年统一。此后一百多年,南北各有正统主张、互称对方为伪,却谁也吞不下谁,长期对峙成为常态。','In the south a victorious general replaced the Jin house, beginning a run of four short-lived southern dynasties. In the north, a state founded by the Xianbei Tuoba people unified the region in 439. For the next century and a half each side claimed to be the legitimate China and called the other an impostor, but neither could swallow the other, and long confrontation became the norm.'],
      rule:['南边在换皇帝,北边在挖户口——同一个问题的两种解法。南朝皇帝多出身军人,靠提拔寒门武将来制衡门阀,代价是政权更替频繁;北朝的孝文帝改革则更彻底:推行均田制与三长制,把户口从豪强手里挖回国家,又迁都洛阳、改汉姓、用汉语,把部族军事贵族改造成王朝官僚。','There was no single government in this age, and south and north gave two different answers; the competition itself is the answer. Southern emperors mostly came from the army and balanced the old aristocracy by promoting officers of humble birth, at the cost of frequent changes of dynasty. The northern reforms went further: an equal-field land system and a village registration system pulled households back from the great clans to the state, while moving the capital to Luoyang, adopting Chinese surnames and using Chinese turned a tribal military nobility into a dynastic bureaucracy.'],
      money:['北方的关键制度是均田:战乱留下大量无主荒地,国家把它按人口授给农民,再配租调制按户征粮征绢,税基因此重建。南方则靠江南的水田、庄园经济与商业,建康与荆州一带的手工业和长江航运都很兴盛,寺院经济在南北也都成了规模。','The north\'s key institution was the equal-field system: war had left large tracts of ownerless land, so the state granted it to farmers by head and collected grain and cloth from each household in return, rebuilding the tax base. The south lived off wet-rice farming, estate agriculture and trade, with flourishing crafts and Yangtze shipping around the capital and the middle river. Monastic economies grew large on both sides of the divide.'],
      power:['北朝后期的西魏北周创立府兵制:士兵单独立籍、由军府统领而脱离州县,战时自备装具出征,兵源与财政的矛盾因此缓解,战斗力也保持得住。这套制度与关中的军事贵族集团结合,成为北方最终胜出的基础。南朝主要依赖水军与长江防线,野战力量长期弱于北方。','In the later north, one of the successor states created a militia system: soldiers were registered separately under military headquarters rather than the civil districts, and campaigned with their own equipment, which eased the conflict between manpower and money while keeping quality up. Combined with the military aristocracy of the Guanzhong region, this became the foundation of the north\'s eventual victory. The south leaned on its navy and the Yangtze line, and its field armies stayed weaker than the north\'s.'],
      fall:['南朝在侯景之乱中受创极重,建康残破、江南经济与人口大伤,此后再未恢复。北朝则先因六镇边防军团的不满爆发起义而分裂为东西两半,西边凭府兵制与关陇集团逐步压倒东边。581年杨坚代周建隋,589年渡江灭陈,一百七十年的南北对峙结束。','The south was crippled by the Hou Jing rebellion, which wrecked the capital and badly damaged the population and economy of the lower Yangtze; it never fully recovered. The north first split in two after the frontier garrisons of its northern border revolted, and the western half gradually overpowered the eastern half through its militia system and its Guanzhong aristocracy. In 581 Yang Jian took the throne and founded the Sui, and in 589 his armies crossed the Yangtze and ended a hundred and seventy years of division.'],
      legacy:['隋唐的制度骨架有相当一部分铸于北朝:均田制、府兵制、以及三省制的雏形,都是这一时期的产物。云冈与龙门的石窟造像开凿于此时,佛教在南北都成为跨越战乱的精神依托,也带来了雕塑、建筑与音乐的新样式。南北人口、语言与习俗的长期交融,则为后来的重新统一准备了社会基础。','A substantial part of the institutional skeleton of the Sui and Tang was cast here: the equal-field land system, the militia system and the early form of the three-department central government all came out of this period. The cave temples of Yungang and Longmen were carved now, and Buddhism became a spiritual refuge on both sides of the divide while bringing new styles of sculpture, architecture and music. The long mixing of peoples, languages and customs across the divide prepared the social ground for reunification.'] },
  d:'南朝宋齐梁陈文风鼎盛,北朝鲜卑从平城迁洛、全面汉化,均田制与府兵制在北方成型——隋唐制度的三大支柱有两根铸于北朝。云冈龙门的大佛凿于此时,佛教在战乱中成为南北共同的精神庇护。' },
{ l:'ea', s:'sino', v:2, n:'隋', k:[[581,0],[589,.7],[605,.75],[615,.4],[618,0]], b:'再造统一、开凿运河、创立科举;隋亡而制度长存。',
  e:{ n:'Sui', w:'Sui dynasty', b:'Reunification, the Grand Canal, the examination system.', d:'Wendi ended three centuries of division and created the ministries and examinations; Yangdi cut the Grand Canal, welding China\'s south to its north. Three failed Korean wars bled the people; like Qin, Sui died in two reigns — and like Qin, its systems lived on.', f:{ 'Peak':'Kaihuang era', 'Center':'Daxing (Chang\'an)', 'Figures':'Emperor Wen, Emperor Yang, Yuwen Kai, Liu Zhuo', 'Legacy':'Grand Canal, examinations, three departments and six ministries' } },
  f:{ '鼎盛':'开皇之治', '中心':'大兴(长安)', '人物':'隋文帝、隋炀帝、宇文恺、刘焯', '成就':'大运河、科举制、三省六部' },
  qh:{ born:['统一的本钱,是北朝攒了一百多年的','The means to unify had been saved up for a century'],
       rule:['宰相之权被拆成几份,选官改考试','The chancellor split in three, and office by examination'],
       money:['把藏起来的人口查出来,税基就暴涨','Hidden households counted, and the tax base leapt'],
       power:['一条运河,把南北焊在一起','One canal welded north and south together'],
       fall:['不是暴虐一条,是动员过度加内部失和','Not cruelty alone: overreach, and a ruling class divided'],
       legacy:['用极短的时间,为后世铺好了轨道','A very short reign that laid the tracks for what followed'] },
  q:{ born:['北周凭府兵制与关陇军事贵族集团胜出后,外戚杨坚在581年代周称帝。此时南方的陈已经衰弱,北方的均田、府兵、户籍都已成型,统一所需的制度和军力其实是北朝百余年积累的结果。589年灭陈,近三百年的分裂结束。','After the northwestern state won out through its militia system and its Guanzhong military aristocracy, Yang Jian, a relative of the imperial house by marriage, took the throne in 581. The southern dynasty was by then weak, while the north already had a working land system, militia armies and household registers. The institutions and force needed for unification were the accumulated product of more than a century of northern development. The south fell in 589, ending nearly three hundred years of division.'],
      rule:['中央设三省六部,决策、审核、执行分开,宰相之权被拆成几份,这套架构被唐及以后长期沿用。地方废郡、只留州县两级,官员一律由中央任免、异地为官,地方大族因此难再世袭权位。选官上废除按门第定品级的旧法,改由考试取士,这是科举制度的起点。','At the centre, three departments split policy-making, review and execution, dividing what had been a single chancellor\'s power, and the design was used by the Tang and long afterwards. Locally the middle tier was abolished, leaving only prefectures and counties, with all officials appointed by the capital and posted away from their home regions, so local clans could no longer inherit authority. For recruitment, grading by family standing was scrapped in favour of selection by examination — the starting point of the civil service examination system.'],
      money:['继承均田制与租庸调:授田后按丁纳粟、纳绢,并可以绢代役。真正的关键动作是清查户口——用大索貌阅核对年龄相貌、用输籍法重定纳税等级,把大量被豪强荫庇的人口挖回国家户籍,税基因此暴涨,含嘉仓、回洛仓一类的大型官仓也在这时修起来。','Sui kept the equal-field system and its matching tax: grain and cloth owed per adult male, with cloth accepted in place of labour service. The decisive move was a census drive — checking ages against appearance and re-setting tax grades household by household — which pulled large numbers of people out from under the protection of great families and back onto the state registers. The tax base jumped, and the huge state granaries of this era were built with the proceeds.'],
      power:['府兵制让兵农合一,军队规模大而养兵成本低。大运河把江南的粮食直接送到黄河流域与北方前线,南北的经济轴线被焊在一起,这条水道同时也是运兵调粮的战略通道。统一之后的人口与仓储,让隋在短期内具备了极强的动员能力。','The militia system merged soldier and farmer, giving Sui a large army at low cost. The Grand Canal carried grain from the lower Yangtze straight to the Yellow River valley and the northern front, welding the country\'s economic axis together while doubling as a strategic route for moving troops and supplies. With a unified population and full granaries, Sui could mobilise on a very large scale in a very short time.'],
      fall:['主流看法是过度动员加统治集团失和,而非炀帝个人残暴一条。营建东都、开凿运河、修筑长城、三次征高丽在十来年里叠加,征发的人力远超民力所能承受;关陇贵族与山东士族对炀帝的做法多有不满,民变自大业七年起在各地零星燃起,613年杨玄感又在贵族中起兵,响应者众。炀帝滞留江都,最终被部下所弑,李渊入长安建唐。','The mainstream reading is over-mobilisation plus a fractured ruling elite, not simply a cruel emperor. Building a second capital, cutting the Grand Canal, rebuilding the northern walls and three campaigns against Goguryeo all fell within little more than a decade, demanding far more labour than the population could bear. The Guanzhong aristocracy and the eastern gentry were both unhappy with the emperor\'s course, and after the Korean campaigns failed one nobleman\'s revolt was quickly echoed across the country. The emperor stayed in the south, was killed by his own guards, and Li Yuan entered Chang\'an to found the Tang.'],
      legacy:['隋亡而制度长存:科举、三省六部、州县两级都被唐全盘继承并发展,其中科举此后影响中国选官一千三百年。大运河成为此后各代漕运的干线,把政治中心与产粮区长期连在一起。和秦一样,它是一个用极短的时间为后世铺好轨道的王朝。','The dynasty died but its institutions lived on: the examination system, the three-department government and the two-tier local administration were all taken over and developed by the Tang, and the examinations went on shaping how China chose officials for some thirteen hundred years. The Grand Canal became the trunk line of grain transport for every later dynasty, permanently linking the political centre to the rice-growing south. Like Qin, Sui laid the tracks for its successors in a very short time.'] },
  d:'文帝结束近三百年分裂,创三省六部与科举取士;炀帝凿通大运河,把中国的经济南北轴线焊在一起。但三征高丽耗尽民力,隋如秦一样二世而亡——也如秦一样,它的制度被继任者全盘继承并发扬。' },
{ l:'ea', s:'sino', v:0, n:'唐', k:[[618,0],[627,.8],[713,1],[755,.9],[770,.55],[820,.5],[875,.35],[907,0]], b:'开放帝国的顶峰,长安是世界最大都会;安史之乱由盛转衰。',
  e:{ n:'Tang', w:'Tang dynasty', b:'The open empire at its height; Chang\'an, capital of the world.', d:'Taizong was hailed "Heavenly Khagan" by the steppe peoples; a million people lived in Chang\'an, where Sogdian merchants, Japanese envoys and pilgrim monks converged — a true world empire. The An Lushan rebellion broke the golden age in half; afterwards regional garrisons ruled themselves and eunuchs could make and unmake emperors, and after Huang Chao\'s revolt the dynasty reigned in name only. But the examinations, the law codes and Tang poetry had already spread across East Asia — and shape it still.', f:{ 'Peak':'Kaiyuan era (713–741)', 'Center':'Chang\'an, Luoyang', 'Figures':'Taizong, Wu Zetian, Li Bai, Du Fu, Xuanzang, Shangguan Wan\'er', 'Legacy':'Heavenly Khagan order, Tang poetry, codes exported across East Asia' } },
  f:{ '鼎盛':'开元盛世(713—741)', '中心':'长安、洛阳', '人物':'唐太宗、武则天、李白、杜甫、玄奘、上官婉儿', '成就':'天可汗体系、唐诗、律令制输出东亚' },
  q:{ born:['隋统一了天下却透支了民力:开运河、三征高句丽,把百姓逼反。李唐接住这份家业,而且几乎是原样接过隋朝的架子——三省六部、科举、均田制、大运河,全是隋朝留下的东西;唐改的是怎么用,不是重新搭一套。所以它一开国就能运转,不必从头摸索。','The Sui reunified China but spent its people too hard: the canal works and three invasions of Goguryeo drove them to revolt. The Tang caught the falling estate — and kept the frame almost unaltered. The Three Departments, the examinations, the land allotment and the Grand Canal were all Sui inventions; what the Tang changed was how they were used, not the structure. That is why it could run from the first day instead of feeling its way.'],
      rule:['三省六部把一道命令拆给三个衙门:中书省起草、门下省审核、尚书省执行。门下省手里有「封驳」之权——诏敕它认为不妥,可以直接退回去,皇帝下的也一样;三省长官另在政事堂碰头议事。法典是 652 年编定、次年颁行的《唐律疏议》,12 篇 502 条,长孙无忌等 19 人写成,每条律文后面还附着逐条的解释。','One order passed through three offices: the Secretariat drafted it, the Chancellery reviewed it, the Department of State Affairs carried it out. The Chancellery held the power of fengbo — anything it judged improper it could send straight back, including edicts from the emperor himself — while the heads of the three met separately in the Hall of Government Affairs. The code was the Tang Code, compiled in 652 and promulgated the next year: twelve books, five hundred and two articles, written by Zhangsun Wuji and eighteen others, every article carrying its own commentary.'],
      money:['前期是均田配租庸调。624 年定下来:一个成年男子授田 100 亩,其中 80 亩叫口分田,人死了要交还国家;20 亩叫永业田,可以传给儿子。他每年交粟 2 石,另服 20 天劳役,不去服役就按每天 3 尺绢折算。人口涨上来之后地不够分,这套就散了;780 年换成两税法,不再数人头,改按你有多少田产来定,财政此后靠江南的漕船撑着。','Early on it was allotted land with dues in grain and labour. The rule set in 624 gave an adult man a hundred mu: eighty of them went back to the state when he died, twenty stayed with his sons. He owed two piculs of grain a year and twenty days of labour, commutable at three feet of silk a day. As the population grew there was no longer enough land to hand out and the system came apart; in 780 the Two-Tax reform stopped counting heads and assessed property instead, and the treasury leaned thereafter on the grain fleets of the Yangtze.'],
      /* v134:钩子句取的就是这段原本的第一句,正文里随之删掉——不删就是同一句连写两遍(截图里一眼看得出)。 */
      power:['这份开放有一个很硬的筛子:科举。《通典》说进士科「大抵千人,得第者百一二」——一千个人去考,中的十来个;考中了还不算完,得再过吏部的关试才有官做。当时的说法是「三十老明经,五十少进士」:五十岁中进士,算年轻的。这条窄得出奇的路,把门阀之外的人放了进来。与此同时归降的突厥将领带着唐朝的兵,丝路商人在城里做买卖——外面的能量不断被吸进来。','That openness came with one very hard filter: the examinations. Of the presented-scholar degree the Tongdian says that of roughly a thousand candidates one or two in a hundred passed — a dozen or so out of a thousand — and passing was not the end of it: a further test at the Board of Personnel stood between a graduate and an actual post. The saying went that a man of thirty was old for the classics degree and a man of fifty young for this one. That improbably narrow road let in men from outside the great clans, while surrendered Turkic generals led Tang armies and Silk Road merchants traded in the city — outside energy drawn steadily in.'],
      fall:['均田制在人口增长与土地兼并下失灵,府兵随之枯竭;改募兵又让边镇节度使拥兵自重,安史之乱砍断王朝脊梁;此后中央与藩镇共治一百五十年,黄巢起义烧完了财政根基。','Land allotment failed as population grew and estates swallowed farms, and the militia dried up; the paid frontier armies then belonged to their governors, and the An Lushan rebellion broke the spine of the dynasty. For a century and a half the court shared power with the warlord provinces, until the Huang Chao rising burned out the fiscal base.'],
      legacy:['科举在这里定型,此后历代照着修,成了中国选官的常态;唐诗是中文的高峰;长安的棋盘格规划影响了日本京都;海外华人至今自称「唐人」,唐人街的名字就是这么来的。','The examinations took their settled shape here and every later dynasty worked from it, until choosing officials by examination was simply what China did; Tang poetry remains the summit of Chinese verse; the grid plan of the capital shaped Kyoto; and overseas Chinese still call themselves the people of Tang — which is where Chinatown gets its Chinese name.'] },
  /* qh = 六问的钩子句(v134 样板)。纪律:**从 q 正文里提取,不新增事实**——新事实要走核查流程。
     ≤20 字,直接回答那一问;读不下去的人至少带走这一行。唐的六条全部有正文原句可对。 */
  qh:{ born:['接住隋朝的家业,避开隋朝的死法','Took over the Sui inheritance, avoided the Sui fate'],
       rule:['权力拆成三块,当官不只看出身','Power split three ways; birth no longer the only road to office'],
       money:['先分地收粮,后按家产收税','Land for grain first, a property tax later'],
       power:['开放本身就是国力','Openness was itself the engine'],
       fall:['兵制先垮,边将才变成藩镇','The militia failed first; then the generals owned the armies'],
       legacy:['科举管了一千三百年;华人至今自称唐人','Exams for 1,300 years; overseas Chinese still call themselves Tang'] },
  d:'唐太宗被草原各部尊为"天可汗";长安住着上百万人,西域商人、日本的遣唐使与求法的僧人都汇聚于此——一个真正的世界帝国。安史之乱把盛世拦腰打断,此后地方军镇各自为政,宦官甚至能废立皇帝;黄巢起义后,王朝名义尚存、实际已经管不动天下。但科举、律令与唐诗早已传遍东亚,影响延续至今。',
  gl:[ { a:700, b:770, k:'art', t:['盛唐气象','High Tang poetry'], d:['李白杜甫王维同时在世——中文诗歌的最高峰。','Li Bai, Du Fu and Wang Wei alive at once.'] },
       { a:780, b:880, k:'econ', t:['中晚唐商业化','Late-Tang commerce'], d:['两税法后市坊松动,扬州益州繁华胜昔。','After the tax reform, Yangzhou and Chengdu boom.'] },
       { a:653, b:750, k:'thought', t:['律令与佛学','Law codes and Buddhist learning'], d:['《唐律疏议》定下东亚法制底本,玄奘译经、禅宗成形。','The Tang Code becomes East Asia\'s legal template; Xuanzang translates, Chan takes shape.'] } ] },
{ l:'ea', s:'sino', v:2, n:'南诏·大理', k:[[738,0],[830,.3],[902,.12],[937,.14],[1100,.2],[1253,0]], b:'云南高原的五百年:两败唐军,后来向宋称臣、被蒙古所灭。',
  e:{ n:'Nanzhao and Dali', b:'Five centuries on the Yunnan plateau: it beat two Tang armies, later paid homage to Song, and fell to the Mongols.', d:'Backed by the Tang as a counterweight to Tibet, Nanzhao then destroyed two great Tang punitive armies outright in 751 and 754 and swung to the Tibetan side for a time. It fell to a usurper in 902; Duan Siping founded the Dali kingdom in 937, which then went more than two centuries without a war against Song China, living on horse trading and transit commerce — and nine or ten of its twenty-two rulers ended their reigns as monks. In 1253 Kublai took the city on a march to outflank the Southern Song.', f:{ 'Peak':'9th c. (Nanzhao) and 11th-12th c. (Dali)', 'Center':'Yangjumie (Dali)', 'Figures':'Piluoge, Yimouxun, Duan Siping', 'Legacy':'The Dehua stele, Dali Buddhist paintings, the tea-horse road' } },
  ct:['先后的两个王朝','The two successive kingdoms'],
  co:[ { n:['南诏','Nanzhao'], y:[738,902], c:['太和城→羊苴咩城(大理)','Taihe, later Yangjumie (Dali)'], x:['两朝之间有三个短命政权,合计不过三十余年','three short-lived regimes came between them, lasting some thirty years in all'] },
       { n:['大理','the Dali kingdom'], y:[937,1253], c:['羊苴咩城(大理)','Yangjumie (Dali)'] } ],
  f:{ '鼎盛':'9世纪(南诏)与11—12世纪(大理)', '中心':'羊苴咩城(大理)', '人物':'皮逻阁、异牟寻、段思平', '成就':'南诏德化碑、大理写本佛画、茶马古道' },
  qh:{ born:['被两个大国夹着,反而有了议价空间','Caught between two great powers, and able to bargain'],
       rule:['二十二个皇帝,九到十个当了和尚','Of twenty-two rulers, nine or ten ended as monks'],
       money:['宋朝没了牧场,战马只能向它买','Song had lost its pastures, and had to buy horses here'],
       power:['唐朝两次来打,两次全军覆没','Tang came twice, and lost both armies'],
       fall:['它是被另一场战争顺手灭掉的','It was destroyed on the way to another war'],
       legacy:['三座塔,正好是两个王朝的接力棒','Three pagodas, two dynasties handing over'] },
  q:{ born:['洱海周边原有六个部落("六诏"),其中蒙舍诏在最南,故称南诏。唐朝为牵制吐蕃而扶植它,738年册封皮逻阁为云南王,他借势兼并其余五诏,统一了洱海地区。这个政权是被两个大国夹在中间催生出来的:唐要它挡吐蕃,吐蕃要它抄唐的后路,两边都给好处,它因此有了议价空间。','Six tribal domains lay around Lake Erhai, and the southernmost gave the state its name. The Tang court backed it as a counterweight to Tibet, investing its ruler as King of Yunnan in 738, and he used that backing to absorb the other five and unify the Erhai region. The state was created by being caught between two great powers: Tang wanted it to block Tibet, Tibet wanted it to strike at Tang\'s flank, and both offered inducements — which gave it room to bargain.'],
      rule:['南诏的官制大体仿唐,设清平官(相当于宰相)与六曹,同时保留部落首领的世袭地位;文书用汉字,王室子弟被送到成都读书。937年段思平灭大义宁建大理国后,格局变了:高氏等大贵族长期把持相权,皇帝多次被迫退位出家为僧——大理国二十二位皇帝里有九到十位以出家收场(各家计法不一),这在中国历史上是独一份。佛教既是信仰,也是这套权力安排的一部分。','Nanzhao\'s offices were largely modelled on the Tang, with a chief councillor and six boards, while tribal chiefs kept their hereditary standing; documents were in Chinese and royal sons were sent to Chengdu to study. After Duan Siping founded the Dali kingdom in 937 the pattern changed: a few great houses, the Gao above all, held the chancellorship for generations, and emperors were repeatedly pushed into abdication and monastic life — nine or ten of Dali\'s twenty-two rulers ended up as monks (counts differ), which has no parallel elsewhere in Chinese history. Buddhism was both a faith and a part of that arrangement.'],
      money:['坝子(山间平地)里的稻作农业是底盘,洱海与滇池周围可以精耕。此外它握着三条路:向北经蜀身毒道通往成都,向西经缅甸通往印度,向南通往中南半岛,是西南方向的贸易枢纽。大理国时期与宋朝的马匹贸易规模很大——宋失去了北方牧场,战马严重不足,只能向大理买,横山寨等地设有专门的马市。茶马古道的雏形就在这条线上。','Wet-rice farming in the mountain basins was the base, with intensive cultivation around Lakes Erhai and Dian. Beyond that it held three roads: north to Chengdu, west through Burma to India, and south into mainland Southeast Asia, making it the trading hub of the southwest. Under Dali the horse trade with Song China was large — having lost the northern pastures, the Song was badly short of warhorses and had to buy from Dali, with dedicated markets set up on the frontier. The tea-horse road grew out of this traffic.'],
      power:['南诏的战力被两次战争证明:751年与754年唐朝两次大举征讨都以惨败告终,史称天宝战争:751年鲜于仲通所部大败,754年李宓一军全军覆没,唐军前后损失以十万计——这直接削弱了唐朝的西南边防,也是安史之乱前夕国力的一次消耗。此后它一度与吐蕃结盟,又在794年转回唐方;9世纪更曾攻入成都、远袭安南。大理国则相反,基本不对外用兵,靠地形与外交维持,与宋朝二百余年无战事。','Nanzhao\'s fighting power was proved twice: the Tang launched two great punitive campaigns in 751 and 754 and lost both, the second army destroyed to a man, with casualties running into the hundreds of thousands over the war — which weakened Tang defences in the southwest and drained strength on the eve of the An Lushan rebellion. It then allied with Tibet for a time before turning back to Tang in 794, and in the ninth century it raided as far as Chengdu and into what is now northern Vietnam. Dali was the opposite: it barely campaigned abroad, relying on terrain and diplomacy, and had no war with Song China in more than two centuries.'],
      fall:['南诏的结局是内耗:长年对外用兵耗尽国力,902年权臣郑买嗣灭蒙氏王室,此后三十余年三易其主,直到937年段思平建大理才重新稳定。大理的结局则来自外部:1253年忽必烈率军经甘肃、四川绕道南下,渡金沙江攻破大理城;末代皇帝段兴智出逃,次年在善阐(今昆明)被擒。蒙古这次远征的战略目的是从西南方向包抄南宋,大理是被卷进了另一场战争。','Nanzhao was undone from inside: decades of campaigning exhausted it, a powerful minister destroyed the royal house in 902, and three regimes changed hands over the next thirty years until Duan Siping founded Dali in 937 and stability returned. Dali\'s end came from outside: in 1253 Kublai led an army south through Gansu and Sichuan, crossed the Jinsha River and stormed the city of Dali; the last king fled and was taken the following year at Shanchan, now Kunming. The strategic point of that expedition was to outflank the Southern Song from the southwest; Dali was drawn into someone else\'s war.'],
      legacy:['大理城至今仍在原址,崇圣寺的主塔千寻塔建于南诏,两侧的小塔则是大理国所建——三座塔恰好是两个王朝接力的实物。《南诏德化碑》立于766年,碑文详述南诏与唐决裂的经过,是研究这段关系最重要的实物史料。佛教艺术方面,《张胜温画卷》与大理国写本佛画是宋代西南佛教美术的代表。蒙古灭大理后设云南行省,段氏被留用为世袭总管,云南自此长期纳入中原王朝的行政体系。','The city of Dali still stands on its old site, and the main pagoda at Chongsheng temple was built under Nanzhao and the two smaller ones under Dali, so the three of them are the two kingdoms in stone. The Dehua stele of 766 sets out in detail how Nanzhao broke with the Tang, and is the most important physical source for that relationship. In Buddhist art, the Zhang Shengwen scroll and the Dali manuscript paintings are the outstanding southwestern Buddhist works of the Song era. After the Mongol conquest a Yunnan province was created and the Duan family kept on as hereditary governors, and Yunnan has been part of the central administrative system ever since.'] },
  d:'唐朝为牵制吐蕃扶植南诏,它却在751与754年两次全歼唐朝征讨大军(天宝战争),又一度倒向吐蕃;902年亡于权臣,937年段思平建大理国,此后与宋朝二百余年无战事、专做马匹与转口贸易,二十二位皇帝有九到十位出家为僧。1253年忽必烈为包抄南宋绕道攻破大理。' },
{ l:'ea', s:'steppe', v:0, n:'吐蕃', k:[[618,0],[670,.3],[763,.5],[790,.55],[821,.5],[842,0]], b:'高原上的帝国,与唐争西域两百年,一度攻入长安。',
  e:{ n:'the Tibetan Empire', b:'A plateau empire that contested the Western Regions with Tang for two centuries.', d:'Songtsen Gampo united the plateau and had a script devised for Tibetan; from the heights his successors fought Tang for the Western Regions for two hundred years, crushing a Tang army at Dafeichuan in 670 and briefly taking Chang\'an in 763 while the Tang was busy with rebellion. A treaty pillar of 821 still stands before the Jokhang. The state broke apart after the ruler was assassinated in 842, but its translation tradition and its Buddhism outlasted it, reaching the Mongol court centuries later through the monk Phagpa.', f:{ 'Peak':'late 8th c. (around Trisong Detsen)', 'Center':'Lhasa', 'Figures':'Songtsen Gampo, Trisong Detsen', 'Legacy':'Tibetan script, sutra translation, the treaty pillar' } },
  f:{ '鼎盛':'8世纪末(赤松德赞前后)', '中心':'逻些(拉萨)', '人物':'松赞干布、赤松德赞', '成就':'藏文、佛经译场、唐蕃会盟碑' },
  qh:{ born:['高原第一次有了文字,也第一次统一','The plateau got its first script, and its first unity'],
       rule:['君臣歃血会盟,把义务刻在石头上','Lord and vassal swore in blood, and cut it into stone'],
       money:['唐朝要马,它要绢和茶','Tang wanted horses; it wanted silk and tea'],
       power:['从高原往下打,曾一度攻进唐都','Striking down from the plateau, it once took the Tang capital'],
       fall:['赞普被刺,没人接得住,王室就散了','The king was killed, no heir agreed, and the house split'],
       legacy:['有些梵文原本失传了,只能靠藏译找回','Some Sanskrit originals survive only through the Tibetan'] },
  q:{ born:['青藏高原不是一片荒原:雅鲁藏布江及其支流的河谷有可耕的土地,能种青稞,高处的草场则养得起牛羊与马。7世纪前期,雅隆河谷的首领松赞干布陆续兼并高原上的各部,把都城迁到逻些,又向邻邦求婚——尼泊尔的尺尊公主与641年入藏的唐朝文成公主,都是这一轮外交的结果。他在位期间参照印度字母创制了藏文,高原第一次有了自己的文字与统一政权。','The Tibetan plateau is not a wasteland: the valleys of the Yarlung Tsangpo and its tributaries hold farmland that grows barley, and the higher pastures support yaks, sheep and horses. In the early seventh century Songtsen Gampo, a chief from the Yarlung valley, absorbed the other plateau clans one by one, moved his capital to Lhasa, and sought marriages abroad — a Nepali princess, and in 641 a Tang princess. During his reign a script for Tibetan was devised on an Indic model, and for the first time the plateau had both its own writing and a single state.'],
      rule:['统治的核心是赞普与几大家族的结盟,靠盟誓维系:君臣定期歃血会盟,把义务刻在石碑上。噶尔家族曾长期把持朝政,几乎架空赞普,直到8世纪初才被清除。8世纪后期赤松德赞大力扶植佛教,建成桑耶寺、请印度与汉地僧人译经,佛教由此成为王权的第二根支柱——但这也与信奉本土苯教的旧贵族形成长期张力,王朝后期的政争多与此有关。','Power rested on an alliance between the btsanpo and a few great clans, held together by oaths: ruler and nobles swore blood covenants at intervals and had the obligations carved on stone pillars. One clan, the Gar, ran the government for decades and nearly hollowed out the throne before being purged in the early eighth century. In the later eighth century Trisong Detsen backed Buddhism heavily, founding the Samye monastery and inviting Indian and Chinese monks to translate scripture, making Buddhism a second pillar of kingship — and setting up a long tension with the old nobility, who held to the indigenous Bon tradition, which runs through the dynasty\'s later political struggles.'],
      money:['底盘是河谷的青稞农业加高原的畜牧,牦牛与马是最重要的牲畜。扩张之后,收入结构变了:控制河西走廊与西域诸城意味着过境商路的税与贡赋归它所有;与唐的边境上还有绢马互市——唐要马,吐蕃要绢与茶,这条交易一直延续到吐蕃解体之后。','The base was barley farming in the valleys plus herding on the plateau, with yaks and horses the key animals. Expansion changed the mix: holding the Hexi Corridor and the oasis cities of the Tarim meant the taxes and tribute of the transit trade came its way. Along the Tang frontier there was also a silk-for-horses exchange — Tang wanted horses, Tibet wanted silk and tea — a trade that outlasted the empire itself.'],
      power:['军队以骑兵为主,着重甲,兵源按部落征发。真正的优势是地形与高度:从高原向下用兵进退自如,而唐军仰攻则要承受高原反应与补给线过长。670年大非川一战唐军大败,安西四镇易手;755年安史之乱爆发后唐朝抽调西北边军平叛,吐蕃趁虚东进,763年一度攻入长安,停留约半个月。821年与822年双方在长安、逻些两地会盟,823年刻石立碑,碑至今仍立在拉萨大昭寺前。','The army was built on armoured cavalry levied from the tribes. The real advantage was terrain and altitude: campaigning downhill from the plateau allowed easy advance and retreat, while Tang armies attacking upward faced altitude sickness and overlong supply lines. At Dafeichuan in 670 a Tang army was badly beaten and the Four Garrisons of Anxi changed hands. After the An Lushan rebellion broke out in 755 the Tang pulled its northwestern frontier troops back to fight it, and Tibet pushed east into the gap, briefly taking Chang\'an in 763 and holding it about a fortnight. In 821 and 822 the two sides swore a treaty at Chang\'an and at Lhasa, and in 823 it was cut in stone; that pillar still stands before the Jokhang temple in Lhasa.'],
      fall:['842年赞普朗达玛遇刺身亡,没有公认的继承人,王室分裂成几支互相攻伐,统一政权就此瓦解——传统叙事把这归因于他毁佛招祸,但现代研究认为宗教冲突只是其中一条线索。多因并存:长期对外用兵消耗了人力与财力;高原的农业底盘本就养不起持续扩张;赞普与贵族、佛教与苯教两组矛盾同时激化。崩解之后局面继续恶化:869年前后爆发大规模平民起义,高原就此进入数百年的分裂期,河西与西域的驻军也各自失去了后方。','In 842 the btsanpo Langdarma was assassinated, no successor was generally accepted, and the royal house split into branches that fought one another; the unified state came apart. The traditional account blames his persecution of Buddhism, but modern scholarship treats religious conflict as only one thread. Several causes ran together: decades of campaigning drained manpower and money; the plateau\'s farming base could not fund endless expansion; the frictions between ruler and nobility, and between Buddhism and Bon, sharpened at the same time. Things kept unravelling afterwards: a large commoner uprising broke out around 869, and the plateau entered centuries of fragmentation, and the garrisons left in the Hexi Corridor and the Tarim lost their home base.'],
      legacy:['最持久的产物是文字与译经:吐蕃时期定下的翻译规范,使大量梵文佛典以极高的对应精度译成藏文,其中一些梵文原本后来失传,只能靠藏译本回溯。藏传佛教在王朝解体后继续发展,并向北传入蒙古——元代八思巴受封帝师、为忽必烈创制八思巴字,源头就在这里。823年立的唐蕃会盟碑用汉藏两种文字刻成,是这段关系留在地面上的实物。','The most lasting products were the script and the translation project: the standards fixed in this period rendered a large body of Sanskrit Buddhist texts into Tibetan with unusual precision, and for some of them the Sanskrit originals were later lost, so the Tibetan is the way back to them. Tibetan Buddhism kept developing after the state collapsed and spread north into Mongolia — the Tibetan monk Phagpa, made imperial preceptor under Kublai Khan and author of a script for the Mongol court, comes from this lineage. The treaty pillar of 823, cut in both Chinese and Tibetan, is the physical remainder of the relationship.'] },
  d:'松赞干布统一高原、创制藏文,吐蕃靠高原地利与唐争夺西域两百年;670年大非川大败唐军,763年趁安史之乱一度攻入长安,821年双方会盟立碑于大昭寺前。842年朗达玛遇刺后分裂,但译经传统与藏传佛教留了下来,后来经八思巴一路传到元朝宫廷。' },
{ l:'ea', s:'sino', v:1, n:'五代十国', k:[[907,0],[930,.35],[955,.4],[979,0]], b:'北方五代走马灯,南方十国割据;燕云十六州埋下两宋边患。',
  e:{ n:'Five Dynasties', w:'Five Dynasties and Ten Kingdoms period', b:'Five northern regimes, ten southern states, one fatal land cession.', d:'Five dynasties cycled through the north in seventy years while ten states split the south; in 936 Shi Jingtang ceded the Sixteen Prefectures to the Khitan, leaving the plain defenseless for four hundred years. The south, meanwhile, quietly prospered.', f:{ 'Peak':'954–959 (Chai Rong of Later Zhou)', 'Center':'Kaifeng; southern capitals', 'Figures':'Chai Rong (Zhou Shizong)', 'Legacy':'The southern economy matures' } },
  f:{ '鼎盛':'954—959年(后周世宗柴荣)', '中心':'开封;南方诸都', '人物':'柴荣(周世宗)', '成就':'南方经济持续开发' },
  co:[ { n:['后梁','Later Liang'], y:[907,923], c:['开封→洛阳→开封','Kaifeng, Luoyang, then Kaifeng'], g:['五代','Five Dynasties'], x:['北方,十四年换一朝','the north, a new dynasty every fourteen years'] },
       { n:['后唐','Later Tang'], y:[923,936], c:['洛阳','Luoyang'], g:['五代','Five Dynasties'] },
       { n:['后晋','Later Jin'], y:[936,947], c:['洛阳→开封','Luoyang, later Kaifeng'], g:['五代','Five Dynasties'] },
       { n:['后汉','Later Han'], y:[947,951], c:['开封','Kaifeng'], g:['五代','Five Dynasties'] },
       { n:['后周','Later Zhou'], y:[951,960], c:['开封','Kaifeng'], m:1, g:['五代','Five Dynasties'] },
       { n:['南唐','Southern Tang'], y:[937,975], c:['金陵','Jinling'], m:1, g:['十国','Ten Kingdoms'], x:['等十国,除北汉外都在南方,反而安定','among ten kingdoms; all but Northern Han lay south, and fared better'] },
       { n:['吴越','Wuyue'], y:[907,978], c:['杭州','Hangzhou'], g:['十国','Ten Kingdoms'] },
       { n:['后蜀','Later Shu'], y:[934,965], c:['成都','Chengdu'], g:['十国','Ten Kingdoms'] },
       { n:['北汉','Northern Han'], y:[951,979], c:['太原','Taiyuan'], g:['十国','Ten Kingdoms'] } ],
  qh:{ born:['不是突然塌的,是攒了一百多年','Not a sudden collapse: a century of drift'],
       rule:['皇帝由禁军拥立,也被禁军推翻','The guards raised the emperor, and the guards pulled him down'],
       money:['乱世里,经济重心还在继续南移','Even in the chaos, the economy kept moving south'],
       power:['割掉燕云十六州,屏障和马场一起没了','Sixteen prefectures given away: the shield and the horses both'],
       fall:['有人把家底攒好了,别人接手用上了','One ruler saved up the strength; another spent it'],
       legacy:['制度往往是上一段历史的答案','Institutions are usually the answer to the last chapter'] },
  q:{ born:['唐后期藩镇握兵自立、朝廷失去财权与军权,黄巢起义又把关中与中原打烂。907年朱温废唐称帝,原本的藩镇纷纷各自称王称帝。这不是一次突然的崩塌,而是唐代中后期地方军事化累积了一百多年的结果。','In the late Tang, regional military governors held their own armies while the court lost control of both revenue and force, and the Huang Chao rebellion then wrecked the capital region and the central plain. In 907 one governor deposed the Tang emperor and took the throne himself, and other governors promptly declared themselves kings or emperors. This was not a sudden collapse but the accumulated result of more than a century of regional militarisation.'],
      rule:['北方的通行规则是兵强马壮者为天子:皇帝多由禁军将领拥立,也常被禁军推翻,王朝平均只维持十来年。南方相对安定,不少君主重农桑、通商贸、招纳北方逃来的士人,政权寿命普遍比北方长。','There was no unified government in this age; two different situations coexisted, and the competition itself is the answer. In the north the operating rule was that whoever had the strongest army became emperor: rulers were usually raised up by the palace guard and often removed by it too, and dynasties lasted little more than a decade on average. The south was calmer, with many rulers encouraging farming and sericulture, opening trade and taking in scholars fleeing the north, and its states generally lasted longer.'],
      money:['北方连年征战,赋税重、货币混乱,常靠临时加征与劣质钱应付军费。南方则各有财源:江浙的丝绸与稻米、福建广东的海上贸易、四川的茶与盐、江西的瓷器,几个政权都主动招徕外商。中国的经济重心在这段割据里继续向南移动。','The north fought constantly, so taxes were heavy, the currency was chaotic, and armies were often paid through emergency levies and debased coin. The southern states each had their own revenue: silk and rice in the lower Yangtze, maritime trade in Fujian and Guangdong, tea and salt in Sichuan, porcelain in Jiangxi, and several courts actively courted foreign merchants. China\'s economic centre of gravity kept moving south through this period of division.'],
      power:['北方各朝的核心武力是牙兵与禁军,由将领亲自豢养、赏赐维系,忠于主帅甚于忠于王朝,战力强而政治上极不稳定。936年石敬瑭为换取契丹出兵,把燕云十六州割让出去,中原北面的山地屏障与养马地一并失去,这个后果一直延伸到两宋。','The core of northern military power was the personal guard units that commanders raised and paid themselves; they were loyal to their general rather than the dynasty, which made them effective in battle and deeply destabilising in politics. In 936 one ruler ceded the sixteen prefectures along the northern frontier in exchange for Khitan military help, and the central plain lost both its mountain barrier and its main horse-breeding country at once — a consequence that reached all the way into the Song.'],
      fall:['后周世宗整顿禁军、抑制佛寺以增加税户与铜料、清丈田亩,把北方的财政与军力重新拢起来,并已开始向南向北用兵。他早逝后,殿前都点检赵匡胤在陈桥被拥立,建立北宋。宋以先易后难、先南后北的次序逐个收取南方诸国,979年灭北汉,分裂结束。','The last northern dynasty\'s most capable ruler reorganised the palace armies, curbed the monasteries to recover taxpayers and bronze, resurveyed farmland, and had begun campaigning both south and north. When he died young, the commander of the palace guard was raised to the throne by his troops and founded the Song. The Song took the southern states one by one, easiest first, and in 979 absorbed the last northern holdout, ending the division.'],
      legacy:['燕云的丢失让此后的中原政权在北面长期无险可守、缺乏战马,两宋的战略被动在这里埋下。南方经济与人口在割据中持续增长,为北宋的商业繁荣打好了底子。北宋重文抑武、以文官统兵的国策,直接是对这七十年武人政治的反应——制度往往是上一段历史的答案。','The loss of the northern prefectures left later dynasties without a defensible frontier or a horse supply in the north, which is where the Song\'s strategic difficulties begin. The southern economy and population kept growing through the division, laying the base for the Song commercial boom. And the Song policy of elevating civil officials over soldiers and putting armies under civilian command was a direct response to these seventy years of rule by generals — institutions are often an answer to the previous chapter.'] },
  d:'七十年间北方五个王朝更替、南方十国并立;936年石敬瑭把燕云十六州割给契丹,使中原此后四百年无险可守——两宋的战略困境在此注定。周世宗的改革为赵宋统一铺路,南方在割据中反而持续繁荣。' },
{ l:'ea', s:'sino', v:0, n:'北宋', k:[[960,0],[980,.65],[1050,.75],[1100,.65],[1127,0]], b:'商业革命与文治巅峰:纸币、活字、《清明上河图》。',
  e:{ n:'Northern Song', w:'Song dynasty', b:'The commercial revolution: paper money, movable type, the Qingming scroll.', d:'A cup of wine dissolved the generals\' commands and civil officials ruled; peace was bought from Liao and Xia while the economy hit a premodern world peak — the first paper money, night markets without curfew, Shen Kuo\'s science. Jingkang ended it overnight.', f:{ 'Peak':'Renzong era (mid-11th c.)', 'Center':'Kaifeng', 'Figures':'Zhao Kuangyin, Wang Anshi, Su Shi, Shen Kuo', 'Legacy':'Paper money, movable type, firearms' } },
  f:{ '鼎盛':'仁宗朝(11世纪中)', '中心':'开封', '人物':'赵匡胤、王安石、苏轼、沈括', '成就':'交子(纸币)、活字印刷、火药武器' },
  qh:{ born:['所有设计只为一件事:军队别再决定皇帝','Every design aimed at one thing: armies must not pick emperors'],
       rule:['皇帝亲自主考,考中的算天子门生','The emperor examined them himself, and they became his men'],
       money:['世界上最早的纸币,出在四川','The world had its first paper money here'],
       power:['灾年把流民招进军队,军队就成了包袱','Famine refugees enlisted, and the army became the burden'],
       fall:['联金灭辽,既拆了缓冲,又露了底','Allying to destroy Liao removed the buffer and showed the weakness'],
       legacy:['一幅画记下城市,一部书记下技术','One scroll recorded the city; one book recorded the science'] },
  q:{ born:['赵匡胤本是后周禁军统帅,960年在陈桥被部下拥立称帝。他上台后要解决的正是让他上台的那个问题:武将拥兵可以随时改朝换代。杯酒释兵权、把兵权拆分给不同机构、用文官统军,一整套设计都指向同一个目标——让军队不再能决定谁当皇帝。','Zhao Kuangyin commanded the palace armies of the previous dynasty and was raised to the throne by his own troops in 960. The problem he then had to solve was precisely the one that had put him there: a general with an army could change the dynasty at any moment. Persuading his commanders to retire, splitting military authority among separate agencies and putting civil officials over the armies were all aimed at the same target — making sure the army could no longer decide who was emperor.'],
      rule:['文官政治是核心:科举大幅扩招,加设由皇帝亲自主持的殿试,考中的人从此算天子门生,官僚与皇权直接绑定,门第的作用大幅下降。兵权被拆成三块——枢密院有调兵权、三衙有统兵权、出征另派将领,互相牵制。地方设通判监督知州,财赋由转运使直送中央。代价是机构叠床架屋、官员冗滥。','Civil government was the core. The examinations were greatly expanded and topped with a palace round presided over by the emperor himself, so successful candidates counted as the emperor\'s own students; bureaucrats were now tied directly to the throne and birth mattered far less. Military authority was split three ways — one body could order troops to move, another commanded them in peacetime, and field commanders were appointed separately — so that no one held all of it. Prefects were shadowed by a supervising official and revenue went straight to the capital through transport commissioners, at the price of overlapping agencies and a swollen payroll.'],
      money:['这是中国前近代经济最出色的一段。农业剩余增加,城市里坊市的墙被拆掉、夜市开放,开封成为百万人口级的消费市场;商税与盐、茶、酒的专卖收入大幅上升,财政不再只靠田赋。四川商人为解决铁钱笨重而发行的交子,后由官府接办成为官方纸币——一般认为这是世界上最早的纸币。对辽、西夏还设榷场互市,岁币的一部分又通过贸易流回来。','This is one of the strongest stretches of pre-modern Chinese economic history. Farm surpluses grew, the walls separating markets from residential wards came down, night markets opened, and the capital became a consumer city of around a million people. Commercial taxes and the salt, tea and liquor monopolies rose sharply, so the treasury no longer depended on the land tax alone. Merchants in Sichuan issued paper receipts to avoid hauling heavy iron coin and the government took the system over as official paper money — generally regarded as the world\'s earliest banknotes — while licensed border markets with the Khitan and Tangut states meant part of the annual tribute payments flowed back through trade.'],
      power:['宋走的是募兵制:招募职业兵、终身在营,连灾年流民也大量招进军队以防其为乱。这让政权稳定,却把军队变成巨大的财政包袱,禁军规模长期居高不下。技术上宋军已大量使用火药武器和床子弩,又设专门机构管理军器。对辽、西夏则以岁币换和平——澶渊之盟起初每年绢二十万匹、银十万两,1042年后又有增加,比长期战争便宜,但和冗官冗兵一起把财政拖紧,这正是王安石变法要处理的问题。','The Song used paid professional soldiers who served for life, and in famine years enlisted large numbers of refugees to keep them from turning to revolt. That bought stability but turned the army into an enormous fiscal burden, and its size stayed high for a century and a half. Song forces already used gunpowder weapons and heavy mounted crossbows in quantity, managed by a dedicated arms bureau, while peace with the Khitan and the Tangut was bought with annual payments — the 1005 treaty set two hundred thousand bolts of silk and a hundred thousand taels of silver a year, raised again after 1042 — which was cheaper than permanent war but, together with the swollen payroll, squeezed the budget hard — the squeeze Wang Anshi\'s reforms set out to fix.'],
      fall:['财政上是冗官、冗兵、冗费长期并存,收入虽高却始终紧张;政治上,变法派与反变法派反复推翻对方的政策,决策力被党争消耗掉。军事上则是长期用钱买和平,野战能力没有跟上。宣和年间联金灭辽,结果既除掉了北面的缓冲,又向对方暴露了自身的虚实;1127年金军攻破开封,徽钦二帝被掳,北宋亡。','Fiscally, a bloated officialdom, a bloated army and bloated spending coexisted for generations, so even high revenues felt tight. Politically, reformers and their opponents repeatedly reversed each other\'s policies and factional struggle ate up the government\'s capacity to decide. Militarily, decades of buying peace meant field capability never caught up. When the Song allied with the Jurchen to destroy the Khitan state it removed its own buffer and revealed its weakness to its new neighbour, and in 1127 Jurchen armies took the capital, carried off two emperors and ended the Northern Song.'],
      legacy:['纸币、活字印刷、火药武器与指南针的航海应用,都在这个时期成熟或普及。科举扩招造就了一个以考试而非门第为入口的士大夫阶层,政治文化从此不同。学术上有理学的兴起与《资治通鉴》的编成,艺术上有山水画与瓷器的高峰。《清明上河图》与《梦溪笔谈》,一幅记下了城市的样子,一部记下了当时最前沿的技术与观察。','Paper money, movable type, gunpowder weapons and the use of the compass at sea all matured or spread in this period. The expanded examinations produced a scholar-official class entered through tests rather than birth, and political culture was never the same. In learning, Neo-Confucianism took shape and the great chronicle Zizhi Tongjian was compiled; in art, landscape painting and ceramics reached a peak. The scroll Along the River During the Qingming Festival recorded what the city looked like, and the Dream Pool Essays recorded the most advanced technology and observation of the day.'] },
  d:'宋太祖在一场酒宴上劝将领们交出兵权("杯酒释兵权"),从此文官治国,军事对辽夏一再花钱买和平,经济文化却登上前近代的世界之巅:开封百万人口夜市不禁,交子是世界上最早由官府发行的纸币,《梦溪笔谈》记录着当时最前沿的科学。靖康之变,盛世戛然而止。',
  gl:[ { a:980, b:1120, k:'econ', t:['商业革命','Commercial revolution'], d:['纸币、海贸、市坊制瓦解——有史家称之为最接近近代的前近代社会。','Paper money, sea trade, urban markets unbound.'] },
       { a:1040, b:1120, k:'art', t:['文人艺术','Literati arts'], d:['苏黄米蔡、宋徽宗院画,书画审美定型千年。','Su Shi\'s circle and the imperial academy set the canon.'] },
       { a:1040, b:1100, k:'tech', t:['科技高峰','Peak of invention'], d:['活字、火药武器、水运仪象台皆在此数十年内成熟。','Movable type, firearms and the astronomical clock mature.'] },
       { a:1040, b:1120, k:'thought', t:['理学开端','Neo-Confucianism begins'], d:['周敦颐、张载、二程,为一百年后的朱熹备好全部材料。','Zhou, Zhang and the Cheng brothers lay everything Zhu Xi would build on.'] } ] },
{ l:'ea', s:'sino', v:1, n:'南宋', k:[[1127,0],[1150,.55],[1250,.5],[1279,0]], b:'半壁江山的经济奇迹:海上贸易与理学定型。',
  e:{ n:'Southern Song', w:'Song dynasty', b:'Half the land, twice the trade; Neo-Confucianism codified.', d:'Half the realm was lost, yet the south grew richer: maritime trade offices at Quanzhou and Guangzhou funded the state, and compass-guided ships sailed as far as Persia and Africa. Zhu Xi organised Confucianism into a complete system (Neo-Confucianism); for six centuries the examinations were graded by his commentaries. In its later decades the court allied with the Mongols to destroy Jin — repeating its old mistake with Liao. In 1279, after defeat at Yashan, the minister Lu Xiufu carried the boy emperor into the sea, and the Southern Song ended.', f:{ 'Peak':'late 12th c.', 'Center':'Lin\'an (Hangzhou)', 'Figures':'Yue Fei, Zhu Xi, Xin Qiji', 'Legacy':'Maritime trade, Neo-Confucian canon' } },
  f:{ '鼎盛':'12世纪后期', '中心':'临安(杭州)', '人物':'岳飞、朱熹、辛弃疾', '成就':'市舶司海贸、理学集大成' },
  qh:{ born:['都城只肯叫「行在」,意思是早晚要回去','The capital was only ever called a temporary residence'],
       rule:['宰相兼管军政,权相成了常态','One chancellor over both army and state became normal'],
       money:['海上贸易的税,成了财政的一大块','Sea trade tax became a major part of the treasury'],
       power:['四川的山城,能拖住优势兵力很久','The Sichuan hill forts held off far larger armies'],
       fall:['联蒙灭金,重蹈了当年的覆辙','It repeated the very mistake that had killed the north'],
       legacy:['经济重心南移,在这一百五十年里做完','The move of wealth to the south was completed here'] },
  q:{ born:['开封失守后,康王赵构在应天府即位、一路南迁,最终以临安为行在。1141年绍兴和议划定东以淮河、西以大散关为界,南宋在长江以南站稳。名义上仍是行在而非首都,但一个重心完全在南方的政权就此定型。','After the capital fell, a surviving prince took the throne and moved steadily south, finally settling his court at Lin\'an, today\'s Hangzhou. The treaty of 1141 fixed the border at the Huai River in the east and a mountain pass in the west, and the Southern Song was secure below the Yangtze. Officially the city remained a temporary residence rather than a capital, but a state whose centre of gravity lay entirely in the south had taken shape.'],
      rule:['官制沿袭北宋,但战时色彩浓得多:宰相长期兼任军政要职,权相秉政成为常态,决策集中于少数人手中。地方上,朝廷与士人家族、书院网络的关系更紧密。理学最初在书院与地方讲学中发展,一度被斥为伪学,后期才被立为官学并进入科举。','The bureaucracy was inherited from the Northern Song but had a much stronger wartime cast: chief councillors also held the top military posts for long stretches, government by a single dominant minister became routine, and decisions rested with a very few people. In the provinces the court worked more closely with gentry families and the network of private academies. Neo-Confucianism grew first in those academies and local lecture halls, was for a time condemned as heterodox, and only later became state orthodoxy and part of the examinations.'],
      money:['南宋不是偏安等死,它的经济体量与外向程度都是中国前近代的高点。沿用北宋以来的泉州、广州、明州市舶司,对进口货抽解、部分官买,海外贸易的税收成为财政的重要一块;瓷器、丝绸、铜钱大量输出,商船借指南针远达东南亚、印度洋沿岸。国内则有江南稻作两熟、太湖圩田、纸币会子的大规模流通,以及盐茶专卖。一般认为其人均物质水平在12世纪的世界上位居前列。','The Southern Song was not a rump state waiting to die: its economy and its openness to the outside world were both high points of pre-modern China. Maritime trade offices at Quanzhou, Guangzhou and Ningbo taxed imports and bought part of each cargo for the state, and overseas trade revenue became an important part of the budget. Porcelain, silk and copper coin flowed out in bulk, and merchant ships used the compass to reach Southeast Asia and the shores of the Indian Ocean. At home there was double-cropped rice in the Yangtze delta, reclaimed polder fields around Lake Tai, large-scale circulation of paper money and the salt and tea monopolies, and by the standards of the time its urbanisation and material living standards were among the world\'s highest.'],
      power:['防御建立在两条水线上:淮河一线的据点与长江的水军。宋军的战船与火器在当时相当先进,已使用突火枪、火箭一类的火药兵器,水战多次挡住北方骑兵。四川的山城体系依托地形节节抵抗,能拖住优势兵力很长时间——钓鱼城之战是这套办法的代表。','Defence rested on two lines of water: fortified positions along the Huai and a navy on the Yangtze. Song warships and firearms were advanced for their day, including fire-lances and rocket-type gunpowder weapons, and river battles repeatedly stopped northern cavalry. In Sichuan a system of mountain fortresses used the terrain to resist in depth and could tie down a much larger army for years, of which the siege of Diaoyucheng is the best-known example.'],
      fall:['财政高度依赖海贸、专卖与纸币,后期会子发行过量、贬值严重,军费越打越贵;权相长期专断使决策僵化,主战主和之间反复摇摆。战略上,联蒙灭金重蹈了当年联金灭辽的覆辙,金一亡即与蒙古直接接壤。襄阳被围数年后失守,长江防线被打开,1276年临安出降,1279年崖山之后残余势力覆灭。','Public finance depended heavily on maritime trade, monopolies and paper money; late in the dynasty the notes were over-issued and lost much of their value while war costs kept climbing. Rule by a single dominant minister made decisions rigid, and policy swung back and forth between fighting and negotiating. Strategically, allying with the Mongols to destroy the Jurchen repeated the earlier mistake of allying with the Jurchen against the Khitan, and left the Song facing the Mongols directly. After a siege lasting years the fortress city of Xiangyang fell, opening the Yangtze line; Lin\'an surrendered in 1276 and the last resistance ended at sea in 1279.'],
      legacy:['朱熹把四书重新编次作注,理学由此集成;元代起他的注本被定为科举标准,此后数百年间读书人共用同一套解释框架,影响远及朝鲜半岛与日本。海上贸易网络与中国的瓷器、丝绸、造船与指南针技术沿这条路外传。经济重心南移在这一百五十年里彻底完成,江南从此长期是中国最富庶的地区。','Zhu Xi re-edited and annotated the Four Books, bringing Neo-Confucianism together into a system; from the Yuan dynasty onward his commentaries were made the examination standard, so for centuries educated people across the region shared one interpretive framework, and its influence reached Korea and Japan. The maritime trade network carried Chinese porcelain, silk, shipbuilding and compass navigation outward along the same routes. The southward shift of China\'s economic centre was completed in these hundred and fifty years, and the lower Yangtze has been the country\'s wealthiest region ever since.'] },
  d:'丢了半壁江山,反而更富:泉州、广州管理海外贸易的市舶司收入撑起财政,商船靠指南针远航到波斯与非洲;朱熹把儒学整理成一套完整体系(理学),此后六百年科举都以他的注本为标准。后期联合蒙古灭金,重演了当年联金灭辽的错误;1279年崖山海战战败,大臣陆秀夫背着小皇帝跳海,南宋灭亡。',
  gl:[ { a:1150, b:1270, k:'econ', t:['海上贸易','Maritime trade'], d:['泉州成为世界级大港,海路取代陆路丝绸之路。','Quanzhou becomes a world port; the sea road replaces the land road.'] },
       { a:1170, b:1250, k:'thought', t:['理学定型','Neo-Confucian synthesis'], d:['朱熹的体系成为此后东亚的官方哲学。','Zhu Xi\'s synthesis becomes East Asia\'s orthodoxy.'] },
       { a:1130, b:1279, k:'tech', t:['火器与航海','Firearms and navigation'], d:['管形火器、指南针导航、水密隔舱的远洋海船。','Fire-lances, the navigational compass, bulkheaded ocean ships.'] } ] },
{ l:'ea', s:'steppe', v:2, n:'渤海国', k:[[698,0],[750,.15],[830,.3],[900,.2],[926,0]], b:'靺鞨与高句丽遗民所建,唐人称"海东盛国"。',
  e:{ n:'Balhae', b:'Founded by Mohe and Goguryeo survivors; the Tang called it the flourishing land east of the sea.', d:'Thirty years after Goguryeo fell, Dae Joyeong led its survivors and Mohe tribespeople back east and founded a state, copying Tang institutions while using its own reign titles at home. It grew rich as the transfer point between Tang, Silla and Japan, sending more than thirty embassies across the sea to Japan in two centuries. It reached its greatest extent in the early ninth century; the Khitan destroyed it in 926 and moved much of its population west, and those who stayed lived on among the Jurchen.', f:{ 'Peak':'early 9th c. (around King Seon)', 'Center':'Sanggyeong', 'Figures':'Dae Joyeong, King Seon', 'Legacy':'Five-capital system, Balhae tiles and stone lanterns' } },
  f:{ '鼎盛':'9世纪初(宣王前后)', '中心':'上京龙泉府', '人物':'大祚荣、大仁秀', '成就':'五京制、渤海琉璃瓦与石灯' },
  qh:{ born:['出身是一场迁徙,加一次趁乱东归','Born of a migration, and a dash home in the chaos'],
       rule:['对唐称藩,对日本自称国王','A vassal to Tang, a king in letters to Japan'],
       money:['卡在唐、新罗、日本中间做中转','Wedged between Tang, Silla and Japan, and trading with all'],
       power:['谁都不彻底得罪,被唐人叫作海东盛国','It offended no one outright, and Tang called it flourishing'],
       fall:['契丹打了十几天,二百二十八年就没了','The Khitan needed ten days to end two centuries'],
       legacy:['东北亚最有争议的一段历史','The most contested history in northeast Asia'] },
  q:{ born:['668年唐与新罗灭高句丽后,大批高句丽遗民与粟末靺鞨部众被迁往辽西。696年营州的契丹人起兵反唐,局面大乱,大祚荣趁机率部东走,渡辽水回到故地,698年在今吉林敦化一带建国,初称震国。713年唐朝册封其为渤海郡王,国号自此定为渤海。它的出身是一场迁徙与一次趁乱东归。','After Tang and Silla destroyed Goguryeo in 668, large numbers of Goguryeo survivors and Mohe tribespeople were resettled westward into Liaoxi. In 696 a Khitan revolt threw the region into chaos, and Dae Joyeong led his people east through the disorder, back across the Liao River to their homeland, founding a state around present-day Dunhua in 698. In 713 the Tang court invested him as Prince of Bohai, and that became the state\'s name. Its origin was a forced migration, and then a march home through someone else\'s rebellion.'],
      rule:['制度几乎照搬唐朝:中央设三省六部,只是名称改用忠、仁、义等儒家德目;地方设五京十五府六十二州,五京制则参考了高句丽与唐的双重经验。官方文书用汉文,同时向唐派遣留学生入国子监。但王室并不掩饰自主性——对内使用自己的年号,对日本的国书中曾自称"高丽国王",唐朝则始终以册封的藩属看待它,两边的表述并不一致。','Its institutions were largely copied from the Tang: three departments and six ministries at the centre, though renamed after Confucian virtues, and five capitals, fifteen prefectures and sixty-two districts below. Official documents were in Chinese, and students were sent to the Tang imperial academy. Yet the royal house did not hide its autonomy: it used its own reign titles at home, and in letters to Japan its ruler once styled himself king of Goguryeo, while the Tang court consistently treated it as an invested vassal. The two sides never described the relationship the same way.'],
      money:['农业在松嫩与牡丹江流域的平原上展开,同时保留渔猎与畜牧。真正让它富起来的是位置:它卡在唐、新罗、日本与北方各部之间,是东北亚贸易的中转站。向唐输出貂皮、人参、海东青(一种猎鹰)与马匹,换回丝绸与铜钱;又开辟经日本海直航日本的航路,两百年间使团往返三十余次,输出毛皮与药材。','Farming spread over the plains of the Songhua and Mudan river valleys alongside fishing, hunting and herding. What made it rich was position: it sat between the Tang, Silla, Japan and the northern tribes, and served as the transfer point of northeast Asian trade. Sable, ginseng, gyrfalcons and horses went to the Tang in exchange for silk and copper coin; a sea route was opened straight across to Japan, and over two centuries more than thirty embassies made the crossing, carrying furs and medicines.'],
      power:['立国之初就打了硬仗:732年渤海水军渡海袭击唐朝登州,唐与新罗联手反击未果,双方此后转向和解。此后它长期不以扩张见长,而是靠三件事立足——地形上有长白山与松花江为屏障;外交上在唐、新罗、日本之间保持平衡,谁也不彻底得罪;9世纪初宣王在位时向北收服诸部,疆域达到最大;到9世纪后期,唐人已称它"海东盛国"。','It fought hard early: in 732 a Bohai fleet crossed the sea and raided the Tang port of Dengzhou, a joint Tang-Silla counterstrike failed, and both sides then moved toward accommodation. Afterwards it was not an expansionist power but held its place through three things — mountains and rivers that shielded it, a diplomatic balance among Tang, Silla and Japan in which it never fully alienated anyone, and the northern campaigns of King Seon in the early ninth century, which brought it to its greatest extent. By the later ninth century Tang writers were calling it the flourishing land east of the sea.'],
      fall:['926年契丹阿保机亲征,契丹自出兵到渤海投降前后不过十余日,上京被围三日国王大諲譔即出降,立国二百二十八年而亡。契丹随即把这块地改称东丹国交给太子统治,并大规模迁徙渤海人口到辽西,原有的城市与制度被打散。为什么败得这么快,史料太薄以致难有定论:契丹方面的记载称其"上下离心",后世曾推测长白山火山喷发影响了生产,但那次大喷发后来被测定在946年、比亡国晚了二十年,时间线已把这个猜想排除;可以确定的是它长期缺乏强大的野战力量,而北方新崛起的契丹恰恰以骑兵见长。','In 926 the Khitan ruler Abaoji led a campaign in person, took the upper capital after a siege of just three days, and the king surrendered; the state had lasted 228 years. The Khitan renamed the territory and handed it to the heir apparent to govern, then moved much of the Bohai population west into Liaoxi, breaking up its cities and institutions. Why it fell so fast is hard to settle, the sources being thin: Khitan accounts speak of a state divided against itself, and later writers speculated that a volcanic eruption had wrecked its farming, but that eruption has since been dated to 946, twenty years after the state fell, which rules it out on timing. What is clear is that it had long lacked a strong field army, just as the rising Khitan power to its north excelled at cavalry.'],
      legacy:['渤海人此后分散:一部分被辽迁走并逐渐融入契丹与汉人,一部分南投高丽被接纳,还有留在故地的与女真诸部混居——两百年后建立金朝的完颜部,正出自同一片土地上的女真人。遗址留下的是实物证据:上京龙泉府的城址规模宏大、布局仿长安,出土的琉璃瓦、石灯幢与佛像至今可见。由于中、朝、韩、俄、日各国学界对其族属与归属的解释不一,渤海史是东北亚最有争议的题目之一。','The Bohai people scattered afterwards: some were moved west by the Khitan and merged into Khitan and Chinese society, some went south and were taken in by Goryeo, and others stayed and lived among the Jurchen tribes — the Wanyan clan that founded the Jin dynasty two centuries later came from the same ground. The ruins are the hard evidence: the upper capital was laid out on a grand plan modelled on Chang\'an, and its glazed tiles, stone lantern and Buddhist statuary survive. Because scholars in China, the Koreas, Russia and Japan read its ethnic makeup and its place in their national histories differently, Bohai is among the most contested subjects in northeast Asian history.'] },
  d:'高句丽亡国三十年后,大祚荣率遗民与靺鞨部众东归建国,制度仿唐而对内自建年号;卡在唐、新罗与日本之间做转口贸易,两百年间三十余次遣使渡海至日本。9世纪初疆域最大,唐人称"海东盛国";926年为契丹所灭,人口被大批西迁,遗民后与女真杂处。' },
{ l:'ea', s:'steppe', v:1, n:'辽', k:[[916,0],[1005,.4],[1080,.35],[1125,0]], b:'契丹人的双轨帝国:以国制治契丹,以汉制待汉人。',
  e:{ n:'Liao', w:'Liao dynasty', b:'The Khitan dual empire; a century of bought peace with Song.', d:'Abaoji founded his state half a century before the Song; after the Chanyuan treaty the two powers traded for a hundred peaceful years. Dual administration — steppe law for the steppe, Chinese law for the sown — became the template for Jin, Yuan and Qing; "Khitan" became Russia\'s very word for China.', f:{ 'Peak':'post-Chanyuan', 'Center':'Shangjing; Nanjing (Beijing)', 'Figures':'Abaoji, Empress Xiao', 'Legacy':'Dual administration, Khitan script' } },
  f:{ '鼎盛':'澶渊之盟后', '中心':'上京、南京(北京)', '人物':'耶律阿保机、萧太后', '成就':'南北面官双轨制、契丹文字' },
  qh:{ born:['同时拿着牧场和农田,制度只能分两套','Holding both pasture and farmland, it needed two systems'],
       rule:['皇帝不住都城,跟着季节走','The emperor kept no capital; he moved with the seasons'],
       money:['宋给的岁币,大半又买东西流回去了','Most of the Song tribute flowed back as purchases'],
       power:['骑兵能跑,燕云能供粮,攻守都有底','Cavalry to move, and the sixteen prefectures to feed them'],
       fall:['向女真索要猎鹰,索出了一场亡国','Demanding falcons from the Jurchen cost it everything'],
       legacy:['俄语里「中国」这个词,就是契丹','The Russian word for China is still Khitan'] },
  q:{ born:['契丹原是活动在西拉木伦河一带的游牧部落联盟,唐末中原动乱,北方的压力消失,耶律阿保机把八部整合起来,916年称帝建国。936年通过支持石敬瑭取得燕云十六州,从此同时拥有草原牧场和成熟的农耕区,这个双重身份决定了它此后的一切制度选择。','The Khitan were a confederation of nomadic tribes on the grasslands of what is now eastern Inner Mongolia. As Tang China collapsed and pressure from the south disappeared, Yelu Abaoji welded the eight tribes together and declared himself emperor in 916. In 936, by backing a Chinese claimant, the Liao obtained the sixteen frontier prefectures and so held pasture and mature farmland at the same time. That double identity determined every institutional choice it made afterwards.'],
      rule:['南北面官双轨制是它最有名的设计:北面官沿用契丹本族的部落制度管游牧人口与军事,南面官仿唐制设州县、用汉人官僚管汉人与渤海人的农耕区,两套系统各按各的习惯法运行。皇帝并不长住某座都城,而是随四季在捺钵——移动的行营——处理政务,行营才是真正的决策中心。','Its best-known design was a dual administration: a northern establishment that governed the nomadic population and the army through Khitan tribal institutions, and a southern establishment modelled on Tang China that ran prefectures and counties with Chinese officials for the farming population. Each side operated under its own customary law. The emperor did not live permanently in any capital but moved with the seasons between hunting camps where government business was done — the travelling camp, not the city, was the real seat of decision.'],
      money:['收入有三块:本族的畜牧,燕云与渤海故地的农业赋税,以及贸易。1005年澶渊之盟后,北宋每年输绢二十万匹、银十万两,1042年后有所增加;辽又在边境设榷场,把这些绢银换成茶、瓷器、药材等商品,岁币实际上大部分又流回南方。同时它也在东西向的草原商路上收取往来之利。','Revenue came from three sources: its own herds, the land taxes of the farming regions it had absorbed, and trade. After the treaty of 1005 the Song sent two hundred thousand bolts of silk and a hundred thousand taels of silver a year, raised somewhat after 1042. The Liao then ran licensed border markets where it exchanged that silk and silver for tea, porcelain and medicines, so most of the tribute in effect flowed back south. It also profited from the east-west caravan routes across the steppe.'],
      power:['军事主力是部族骑兵,平时游牧、战时集结,机动性远胜农耕政权的步兵,再加上燕云的人口、粮食与工匠提供攻城器械与后勤补给,攻守都有依托。与北宋议和后百余年少有大战,军力更多用于压制东北的属部与西北的边疆。','The core of its army was tribal cavalry that herded in peacetime and assembled for campaigns, far more mobile than the infantry of a settled state. The population, grain and craftsmen of the farming prefectures supplied siege equipment and logistics, so it could both attack and defend. After peace with the Song there were few major wars for over a century, and its forces were used mainly to hold down subject peoples in the northeast and the northwestern frontier.'],
      fall:['后期皇位继承与后族干政反复引发内斗,统治集团分裂。对东北属部的索求——史书常举索取海东青为例——加重了女真各部的不满。完颜阿骨打1114年起兵,辽军接连败绩,内部又有降附与叛离,1125年天祚帝被俘,立国二百余年的辽结束。宗室耶律大石率余部西迁中亚,另建西辽。','In its later decades disputed successions and interference by the empress\'s clan produced repeated internal fighting and split the ruling group. Demands on its subject peoples in the northeast — the histories often cite the levy of hunting falcons — deepened Jurchen resentment. Aguda rose in revolt in 1114, Liao armies lost battle after battle, and defections spread from within; the last emperor was captured in 1125, ending a state of more than two centuries. A member of the imperial clan led survivors west into Central Asia and founded a successor state there.'],
      legacy:['二元治理的思路——对不同生活方式的人群用不同制度——被金、元、清不同程度地借鉴,成为草原出身的政权统治农耕社会的一种范本。契丹人创制了大字与小字两套文字,至今仍未完全释读。而契丹这个名字经中亚传到西方,成为俄语等语言里中国的称呼。','Its dual approach — different institutions for peoples with different ways of life — was borrowed to varying degrees by the Jurchen, Mongol and Manchu states, and became one model for how a steppe-born dynasty could govern a farming society. The Khitan created two scripts, a larger and a smaller, which are still not fully deciphered. And the name Khitan travelled west through Central Asia to become the word for China in Russian and several other languages.'] },
  d:'阿保机建国早于赵宋近半个世纪;澶渊之盟后与北宋维持百年和平,岁币贸易两利。双轨官制是草原政权治理农耕社会的成功范本,深刻影响金元清;1125年亡于金,余部西迁建西辽,"契丹"一名经此成为俄语中"中国"的称呼。' },
{ l:'ea', s:'steppe', v:0, n:'西夏', k:[[1038,0],[1100,.25],[1200,.2],[1227,0]], b:'党项人的河西之国,扼丝路咽喉近两百年。',
  e:{ n:'Western Xia', b:'The Tangut state astride the Silk Road corridor.', d:'Li Yuanhao proclaimed empire and an intricate script of his own, playing Song, Liao and Jin off one another for nearly two centuries while taxing the Silk Road. Genghis Khan died on the final campaign against it; the Mongol destruction was so thorough that Tangut civilization was only rediscovered in the 20th century.', f:{ 'Peak':'12th c.', 'Center':'Xingqing (Yinchuan)', 'Figures':'Li Yuanhao', 'Legacy':'Tangut script, corridor trade' } },
  f:{ '鼎盛':'12世纪', '中心':'兴庆(银川)', '人物':'李元昊', '成就':'西夏文、河西走廊贸易' },
  qh:{ born:['一个节度使辖区,变成了独立王朝','A frontier command turned itself into a dynasty'],
       rule:['专门造了一套字,来证明自己是自己','It invented a script to prove it was its own'],
       money:['商路必经此地,过路就得交钱','The trade road had to pass through, and pay'],
       power:['永远当第三方,靠均势活了两百年','Always the third party, living two centuries off the balance'],
       fall:['均势一没,它就活不下去了','Once the balance was gone, so was it'],
       legacy:['一批出土文献,让消失的文字重新能读','Buried documents made a lost script readable again'] },
  q:{ born:['党项是原居青藏高原东缘的羌系族群,唐代内迁到今陕北一带,唐末因平乱有功受封定难军节度使,世代据有夏、银等州。宋初它在宋与辽之间反复,1038年李元昊正式称帝、建国号大夏,把一个割据的节度使辖区变成了独立王朝。','The Tangut were a Qiang-related people from the eastern edge of the Tibetan plateau who moved inland during the Tang and were granted a hereditary military governorship in the northern Shaanxi region for helping suppress a rebellion. In the early Song they manoeuvred between the Song and the Khitan, and in 1038 Li Yuanhao formally declared himself emperor, turning a semi-independent governorship into a separate dynasty.'],
      rule:['采取蕃汉分治:蕃官系统管党项部落的军事与本族事务,汉官系统按州县管农耕区的行政与赋税,两套官职并行。官方文书与佛经并用西夏文、汉文与藏文。李元昊为立国族之别,专门命人创制笔画繁复的西夏文,并推行本族服饰与礼俗,制度上则大量借鉴宋制。','The Tangut state ran parallel administrations: one staffed by Tangut officials handling tribal and military affairs, another staffed by Chinese-style officials running prefectures, taxes and civil business in the farming areas. Official documents and Buddhist texts appeared in Tangut, Chinese and Tibetan. To mark the new state apart, Li Yuanhao had a deliberately intricate Tangut script created and enforced native dress and ritual, while borrowing heavily from Song institutions in practice.'],
      money:['地利是它的立国之本:河西走廊是东西商路的必经段,过境的商队要向它纳税,西域的马匹玉石与中原的丝绸茶叶都从这里过。农业靠贺兰山东麓与河套的引黄灌溉,青白盐则是重要的出口物。此外它也从宋、辽、金那里得到岁赐或岁币,并在边境榷场换取粮食布匹。','Geography was the foundation of the state: the Hexi Corridor was the unavoidable segment of the east-west trade route, so caravans paid it to pass, and horses and jade from the west met silk and tea from the east on its territory. Agriculture depended on irrigation drawn from the Yellow River along the Helan mountains and the Ordos loop, and its salt was an important export. It also received annual payments from its larger neighbours at various times and bought grain and cloth at licensed border markets.'],
      power:['军事上以骑兵为主,重装骑兵与山地步兵配合,再借助沙漠、山地的地形打防御反击,宋军数次大举进攻都在这上面吃亏。更关键的是外交:它始终在宋、辽,后来是宋、金之间保持第三方位置,名义上向强者称臣,实际视形势倒向另一边,靠均势维持了近两百年。','Its army was built around cavalry, with heavy horse supported by infantry trained for mountain country, and it used desert and highland terrain for defensive counterattacks — several large Song offensives came to grief that way. More important was diplomacy: it kept a third-party position between the Song and the Khitan, and later between the Song and the Jurchen, paying nominal allegiance to whichever side was stronger while tilting the other way as circumstances shifted, and survived on that balance for nearly two centuries.'],
      fall:['结构性弱点是国小人少,经不起长期消耗,而它的生存又依赖周边的均势。蒙古崛起后这个均势消失了,而后期皇室内乱、与金关系破裂,又让它失去了最可能的外部依靠。蒙古先后多次征伐,1227年都城被攻破,西夏灭亡。破城后的杀戮与破坏极为严重,大量典籍文物散失,这个文明因此长期几乎被遗忘。','Its structural weakness was a small territory and population that could not absorb a long war, and its survival depended on a balance of power among its neighbours. The rise of the Mongols removed that balance, while in its final decades the ruling house was torn by internal conflict and broke with the Jurchen state, losing the ally it most needed. After repeated Mongol campaigns the capital fell in 1227. The killing and destruction that followed were severe and a great deal of its written record was lost, which is why the civilisation was so nearly forgotten.'],
      legacy:['20世纪初黑水城遗址出土大批西夏文文献,这个消失的文字与它的佛经、字典、法典才被重新解读,今天已有专门的西夏学。河西走廊留下的佛教石窟与壁画是它宗教艺术的实物。党项人在其后数百年间逐渐融入周边各族群,不再作为独立民族存在。','In the early twentieth century a large cache of Tangut documents was excavated at the ruined city of Khara-Khoto, and only then were the lost script and its sutras, dictionaries and law codes read again; there is now a whole scholarly field devoted to it. The Buddhist caves and murals of the Hexi Corridor are the surviving evidence of its religious art. Over the following centuries the Tangut people merged into the surrounding populations and ceased to exist as a distinct group.'] },
  d:'李元昊称帝建国,创制笔画繁复的西夏文,以骑兵与地利周旋于宋辽金之间近两百年,掐住丝绸之路的要道,靠过路贸易获利;1227年成吉思汗死于征夏军中,蒙古破国后屠戮极烈,西夏文明湮没到20世纪才被重新发现。' },
{ l:'ea', s:'steppe', v:2, n:'金', k:[[1115,0],[1150,.5],[1200,.45],[1234,0]], b:'女真人灭辽克宋,定都燕京——北京建都之始。',
  e:{ n:'Jin (Jurchen)', w:'Jin dynasty (1115–1234)', b:'From 2,500 riders to master of north China; Beijing\'s first capital era.', d:'Aguda rose with 2,500 men, destroyed Liao in a decade and carried off two Song emperors the next year; the move to Yanjing began Beijing\'s history as a capital. Shizong ruled so mildly he was likened to the sage-kings of legend — a "little Yao and Shun" — but the dilemma of sinicization was never solved — Mongols and Song ended it at Caizhou.', f:{ 'Peak':'Shizong\'s Dading era', 'Center':'Zhongdu (Beijing)', 'Figures':'Aguda, Emperor Shizong', 'Legacy':'Beijing made a capital, the meng\'an-mouke system' } },
  f:{ '鼎盛':'世宗大定之治', '中心':'中都(北京)', '人物':'完颜阿骨打、金世宗', '成就':'北京建都之始、猛安谋克制' },
  qh:{ born:['以少胜多,十年就灭了辽','Outnumbered, and it destroyed Liao in ten years'],
       rule:['汉化和守住本族,一直在互相拉扯','Sinicisation and keeping its own pulled against each other'],
       money:['纸币越印越多,最后没人肯用','The more notes it printed, the less anyone would take them'],
       power:['战士分了田,几代之后就不能打了','Given farms, the warriors stopped being warriors'],
       fall:['北边丢了就去南边抢,结果两面树敌','Losing the north, it attacked the south, and faced both'],
       legacy:['北京第一次当上正式国都','Beijing became a dynastic capital for the first time'] },
  q:{ born:['女真是生活在松花江、黑龙江流域的渔猎农耕族群,长期受辽压迫并被索取贡物。完颜部首领阿骨打1114年起兵,次年称帝建国号金。此时辽的统治集团已经内耗多年,金以少胜多,十年灭辽;1127年南下攻破开封,把北宋也一并终结。','The Jurchen were a fishing, hunting and farming people of the Songhua and Amur river basins, long dominated by the Liao and pressed for tribute. Aguda of the Wanyan clan revolted in 1114 and declared himself emperor the following year. The Liao ruling group had been consuming itself for years, so the Jurchen won against much larger forces and destroyed the Liao within a decade. In 1127 they came south, took the Song capital and ended the Northern Song as well.'],
      rule:['本族的组织基础是猛安谋克:三百户为一谋克、十谋克为一猛安,既是户籍单位也是军事编制,平时耕牧、战时按编制出兵。入主中原后逐步采用辽宋的官制:熙宗废除旧的贵族议事制度、改行三省制,海陵王迁都燕京、进一步加强皇权;世宗、章宗两朝汉化更深,扩充科举、增设女真进士科、编修法典,同时又反复下令保护女真语言与习俗,汉化与守本之间始终紧张。','Jurchen society was organised in units of three hundred households, grouped in tens, which served at once as household registers and as military formations: they farmed and herded in peacetime and mustered by unit in war. After taking north China the state gradually adopted Liao and Song administrative forms — one emperor moved the capital to today\'s Beijing and strengthened the throne — the old council of nobles had already been abolished by his predecessor, who adopted Tang-style departments — while later reigns went further, widening the examinations with a Jurchen-language track and compiling law codes. At the same time repeated edicts tried to protect the Jurchen language and customs, and the tension between assimilation and preservation was never resolved.'],
      money:['主体是华北的农业赋税与盐、酒、茶的专卖,再加上与南宋的岁币和边境榷场贸易。金也发行纸币交钞,起初有准备、流通正常,后期为应付蒙古战争的军费而大量增发,交钞迅速贬值,朝廷屡次改换名目重新发行,信用越换越低,民间转而使用实物与白银。','The main sources were land taxes across north China and monopolies on salt, liquor and tea, supplemented by annual payments from the Southern Song and trade at licensed border markets. The Jin also issued paper money, which circulated normally at first when it was backed by reserves. Later, to pay for the war against the Mongols, it was printed in bulk and lost value fast; the court repeatedly relaunched it under new names, each time with less credibility, and people turned back to goods and silver.'],
      power:['早期战力来自猛安谋克骑兵:兵农合一、自备马匹装具,组织与作战单位一致,动员极快。灭辽克宋之后,大批猛安谋克户被迁到华北屯田,分给土地、脱离原本的生产与训练环境,几代之后战斗力明显下降,朝廷只好越来越依赖招募的汉军与契丹军。','Its early striking power came from the cavalry of those household units: soldier and farmer were the same person, men supplied their own horses and gear, and the unit of production was the unit of battle, so mobilisation was extremely fast. After the conquests, large numbers of these households were resettled on farmland in north China, given land and cut off from their original way of life and training. Within a few generations their fighting quality had visibly declined, and the court leaned more and more on recruited Chinese and Khitan troops.'],
      fall:['多因叠加:军户制度腐化使核心战力流失;黄河在12世纪多次改道决口,河北、山东残破,税源与人口大减;财政靠滥发纸币支撑,通胀削弱了国家动员能力。蒙古1211年南下,1214年金廷被迫迁都汴京,北方大部丢失;南下攻宋以求补偿又两面树敌,1234年在蒙宋夹击下亡于蔡州。','Several causes stacked up. The decay of the military household system drained its core fighting strength. The Yellow River changed course and burst its banks repeatedly during the twelfth century, wrecking Hebei and Shandong and cutting both revenue and population, while public finance ran on over-issued paper money whose inflation weakened the state\'s capacity to mobilise. The Mongols came south in 1211, the court was forced to move its capital to Kaifeng in 1214 and lost most of the north, and an attempt to compensate by attacking the Southern Song only created enemies on two fronts; caught between them, the dynasty fell at Caizhou in 1234.'],
      legacy:['把都城定在燕京,这是北京第一次成为一个王朝的正式国都(此前辽以它为陪都);此后元明清相继在此建都,今天北京城的选址源头在这里。女真人创制了女真大字与小字。金代的官修法典与文学(元好问等)在北方文化史上有分量。后来满洲的八旗制度常被拿来与猛安谋克对比,两者是否有直接承袭尚有争论。','Making today\'s Beijing its capital was the first time Beijing served as a dynasty\'s formal capital — the Liao had used it only as a secondary capital — and the Yuan, Ming and Qing all followed, and the site of the modern city traces back to this choice. The Jurchen created a larger and a smaller script of their own. The dynasty\'s official law codes and its northern literary tradition carry real weight in cultural history. The later Manchu banner system shares clear features with the Jurchen household-unit system, and whether one descends directly from the other is still debated.'] },
  d:'阿骨打以两千五百人起兵,十年灭辽,再一年掳走徽钦二帝;迁都燕京,北京作为都城的历史由此开篇。金世宗治国宽和,被比作上古贤君,称"小尧舜",但汉化与守成的两难始终未解,1234年在蒙宋夹击下亡于蔡州。' },
{ l:'ea', s:'steppe', v:2, n:'元', k:[[1271,0],[1290,.8],[1368,0]], b:'草原帝国首次统一全中国;行省制沿用至今。',
  e:{ n:'Yuan', w:'Yuan dynasty', b:'The steppe rules all China; the province system endures.', d:'The first whole-China rule from the steppe; its province system is still in use. Persian cobalt colored the blue-white porcelain and Marco Polo\'s Khanbaliq gave Europe its first systematic image of China. Ninety-seven years — among the shortest of the unified dynasties.', f:{ 'Peak':'Kublai (1271–1294)', 'Center':'Dadu (Beijing)', 'Figures':'Kublai, Guo Shoujing, Drogön Chögyal Phagpa, Huang Daopo', 'Legacy':'Province system, blue-white porcelain, zaju drama' } },
  f:{ '鼎盛':'忽必烈(1271—1294)', '中心':'大都(北京)', '人物':'忽必烈、郭守敬、八思巴、黄道婆', '成就':'行中书省、青花瓷、元曲' },
  qh:{ born:['草原政权第一次统治了整个中国','The first time a steppe power ruled all of China'],
       rule:['「省」这个词,是从这时候留下来的','The word province has been in use ever since'],
       money:['纸币第一次成了全国的主要钱','Paper money became the main currency nationwide'],
       power:['一张驿站网,把欧亚连成了一片','A relay network stitched Eurasia into one space'],
       fall:['纸币先崩,朝廷就再也调不动资源','The paper money went first, and the state lost its grip'],
       legacy:['人、技术、宗教和疾病,一起流动起来','People, skills, faiths and diseases all began to move'] },
  q:{ born:['蒙古在13世纪初统一草原后向四方扩张,先后灭西夏、灭金,并向中亚西亚推进。忽必烈在与兄弟争位中胜出,把统治重心从草原移到华北,1271年取《易经》大哉乾元之义定国号为大元,1279年灭南宋。这是草原政权第一次完整统治整个中国。','After unifying the steppe in the early thirteenth century the Mongols expanded in every direction, destroying the Tangut and Jurchen states and pushing into Central and Western Asia. Kublai won a contested succession, shifted the centre of rule from the grasslands to north China, adopted the dynastic name Yuan in 1271 from a phrase in the Book of Changes, and completed the conquest of the Southern Song in 1279. It was the first time a steppe power governed the whole of China as a single realm.'],
      rule:['行省制是它最持久的制度遗产:中书省在地方设派出机构,权限大、辖区大,行省作为一级行政区一直沿用到今天。社会管理上按族群来源分层任官与量刑,通常概括为蒙古、色目、汉人、南人四等——这个名称是后人的归纳,元代并无同名法令,但任官与法律上的差别待遇确有记载。科举时废时行,官员多由吏员出职或世袭承袭,宗教上则相当宽容。','Its most durable legacy was the provincial system: the central secretariat set up branch offices in the regions with wide powers over large territories, and the province has remained a top-level administrative unit ever since. Socially, appointments and legal penalties were graded by a person\'s origin, usually summarised as four ranks — Mongols, Central and Western Asians, northern Chinese and southern Chinese. That label is a later scholarly shorthand rather than a Yuan statute of that name, but the differential treatment in office-holding and law is well documented. The examinations were suspended and revived by turns, most officials rose through clerical service or inherited their posts, and religious policy was notably tolerant.'],
      money:['元把纸币推到了前所未有的规模:交钞以白银为本位、全国通行,金属货币在很长时间里退居次要位置,一般认为这是纸币第一次在全中国范围内成为主要通货。盐引专卖是财政支柱,大宗收入来自盐、酒、茶的官榷。此外朝廷把征税与官本借贷承包给色目商人组成的商团,他们同时经营欧亚长途贸易;粮食则通过海运与改道后的大运河北上供应大都。','The Yuan took paper money to an unprecedented scale: notes were denominated against silver, valid across the whole country, and for long stretches metal coin was pushed into a secondary role — generally reckoned the first time paper served as the main currency throughout China. Salt certificates were the backbone of the budget, with further bulk revenue from liquor and tea monopolies. The court also farmed out tax collection and state-funded lending to merchant associations of Central and Western Asian traders, who simultaneously ran long-distance Eurasian commerce. Grain reached the capital by sea and along a re-routed Grand Canal.'],
      power:['军事上是草原骑兵加上吸收来的攻城与水战技术:围襄阳时使用了来自西亚工匠的配重投石机,灭宋则动用了大规模水军。真正把帝国连起来的是站赤,即遍布欧亚的驿站网络,情报、使节、货物沿着它高速流动,元代中国与波斯、欧洲的往来因此比以往密切得多。','Militarily it combined steppe cavalry with siege and naval techniques absorbed from elsewhere: counterweight trebuchets built by engineers from western Asia were used at the siege of Xiangyang, and a large navy was needed to finish off the Song. What really held the empire together was the post-relay network spanning Eurasia, along which intelligence, envoys and goods moved fast, and contact between China, Persia and Europe grew far closer than before.'],
      fall:['核心机制之一是纸币体系的崩溃:准备金被挪用后交钞持续增发,恶性通胀摧毁了财政信用,朝廷再想征调资源已难以做到。政治上,中期皇位继承屡起争斗、皇帝更替频繁,中枢政令难以持续。加上黄河改道后大规模征发民夫治河、江淮水旱不断,红巾军自1351年起遍地而生。1368年明军北伐,元廷退回草原,史称北元。','One core mechanism was the collapse of the paper currency: once the silver reserves were spent, notes kept being printed, hyperinflation destroyed the state\'s financial credit, and the court could no longer command resources when it needed them. Politically, disputed successions in the middle decades produced a rapid turnover of emperors and little policy continuity. Add a mass conscription of labour to reroute the Yellow River after it shifted course, plus repeated floods and droughts in the Huai valley, and the Red Turban risings spread from 1351. In 1368 Ming armies took the north and the Yuan court withdrew to the steppe.'],
      legacy:['行省制成为中国地方行政的基本框架,沿用至今。大都的城市规划与改道后的大运河,奠定了此后北京的格局与南粮北运的路线。景德镇用波斯进口的钴料烧出青花瓷,元曲则把戏剧推到新高度。更大的影响在欧亚层面:人员、技术、宗教与疾病沿着这个连通的空间大规模流动,欧洲对中国的系统想象也从这一时期的旅行记述开始。','The provincial system became the basic framework of Chinese local administration and is still in use. The layout of the capital and the re-routed Grand Canal set the shape of later Beijing and the route by which southern grain fed the north. Jingdezhen used cobalt imported from Persia to fire blue-and-white porcelain, and Yuan drama raised Chinese theatre to a new level. The larger effect was Eurasian: people, techniques, religions and diseases moved across a connected space on a new scale, and Europe\'s systematic picture of China began with the travel accounts of this period.'] },
  d:'草原帝国首次整体统治中国,行省制沿用至今;色目商人往来欧亚,青花瓷的钴料来自波斯,马可·波罗笔下的"汗八里"让欧洲第一次系统地想象中国。九十七年而亡,是大一统王朝中最短的之一。' },
{ l:'ea', s:'sino', v:2, n:'明', k:[[1368,0],[1405,.85],[1550,.7],[1644,0]], b:'郑和七下西洋早于哥伦布近一个世纪;后期转向内敛。',
  e:{ n:'Ming', w:'Ming dynasty', b:'Zheng He sailed a century before Columbus — then the court turned inward.', d:'Zheng He\'s treasure fleets sailed nearly a century before Columbus at many times the scale, then stopped dead when the court turned inward — the dividend of the sea passed to Europe. Late-Ming Jiangnan boomed on silver and market towns before fiscal collapse met the Little Ice Age.', f:{ 'Peak':'Yongle (1403–1424)', 'Center':'Nanjing → Beijing', 'Figures':'Zhu Yuanzhang, Yongle, Zheng He, Wang Yangming, Li Shizhen', 'Legacy':'Treasure fleets, Forbidden City, Yangming philosophy' } },
  f:{ '鼎盛':'永乐(1403—1424)', '中心':'南京→北京', '人物':'朱元璋、永乐帝、郑和、王阳明、李时珍', '成就':'郑和宝船、紫禁城、阳明心学' },
  qh:{ born:['开国皇帝是从最底层打上来的','Its founder came up from the very bottom'],
       rule:['每家每户登记在册,锁在土地上','Every household on the register, and tied to the land'],
       money:['税额定死了,简单,但一点都不灵活','A fixed tax quota: simple, and utterly rigid'],
       power:['郑和的舰队,七次开到西洋去','Zheng He took his fleet to the western ocean seven times'],
       fall:['加税就反,不加税就没钱','Raise taxes and they revolt; do not, and there is no money'],
       legacy:['今天看到的长城,主体是明朝修的','The Great Wall you see today is mostly Ming'] },
  q:{ born:['元末天灾连年、纸币崩溃、治理失灵,红巾军四起;朱元璋从最底层打出来,重建了一个以农为本的王朝。起事有个很具体的引子:至正十一年(1351)朝廷派贾鲁治黄河,从汴梁、大名等十三路征了十五万人上工地,官吏又克扣河工的口粮钱。工地上挖出一个独眼石人——传统的说法是韩山童、刘福通事先埋下去的,配着一句早已传开的话「石人一只眼,挑动黄河天下反」。人就这么反了,起事者头缠红巾,故称红巾军。','Late-Yuan floods and famines, a collapsed paper currency and failing rule bred the Red Turban risings; Zhu Yuanzhang fought up from the very bottom and rebuilt a dynasty rooted in the land. The rising had a very concrete trigger. In 1351 the court sent Jia Lu to repair the Yellow River and conscripted a hundred and fifty thousand men from thirteen circuits, whose food money the officials then skimmed. A one-eyed stone man was dug up on the works — by the traditional account planted there beforehand by Han Shantong and Liu Futong — matching a rhyme already going about: the stone man with one eye will stir the Yellow River and set the realm in revolt. It did. Those who rose bound red cloth about their heads, and were called the Red Turbans.'],
      rule:['废丞相,皇帝直管六部,权力集中到极点;科举官僚治民,里甲户籍把每家每户登记在册、锁在土地上。这套登记做得极认真:洪武十四年起编造「黄册」,把全国每一户的丁口、事产一一登记,每十年重造一次,明朝前后造了二十七回;每次一式四份,户部、布政司、府、县各存一份。另有一套「鱼鳞图册」专记田亩——一块块田画出来挨着排,远看像鱼鳞。连「黄册」这名字的来历都还在争:一说户部那份用黄纸做封面,也有学者认为跟颜色无关。','The chancellorship was abolished and the emperor ran the ministries himself; examination officials governed, while household registers fixed every family to its land. The registering was done in earnest: from 1381 the Yellow Registers recorded every household in the realm, its people and its property, and were remade every ten years — twenty-seven times over the dynasty — in four copies each, one for the Board of Revenue and one each for province, prefecture and county. A second set, the Fish-Scale Maps, recorded the fields: plot drawn beside plot until the page looked like scales. Even the name of the Yellow Registers is still argued over — that the Board of Revenue copy was bound in yellow paper, or that the colour has nothing to do with it.'],
      money:['财政以定额农业税为主,简单但僵硬;晚明美洲白银经海贸大量流入,一条鞭法把赋役折成银两征收。改按田亩起税之后,原本按人头编的黄册就越编越不准,朝廷转而以记田的鱼鳞册为依据——税从「按人」变成「按地」,登记的重心也跟着搬了家。','Revenue rested on fixed farm quotas — simple but rigid; in the late Ming, American silver poured in through the sea trade, and the Single Whip reform converted taxes into silver. Once the levy was assessed on land, the Yellow Registers of people grew steadily less accurate and the state fell back on the Fish-Scale Maps of fields instead: as the tax moved from persons to acres, so did the register that mattered.'],
      power:['开国的动员力惊人:郑和舰队七下西洋、重修长城、营建北京;战乱后人口与耕地快速恢复。养这支军队的办法叫卫所:一卫约 5600 人,下面千户所 1120 人、百户所 112 人;军户是世袭的,一旦入了军籍极难除去,平时一部分守城、一部分屯田,自己种粮养自己。朱元璋因此说过一句「吾养兵百万,不费百姓一粒米」(《续文献通考》)。这句话后来被现实驳倒:据记载,正统三年在册的逃兵已达一百六十三万余人,屯田被层层侵占,到嘉靖年间只好改用募兵,卫所形同废止。','The founding state could mobilise on a huge scale: the Zheng He fleets, the rebuilt Great Wall, the new capital at Beijing; people and farmland recovered fast after the wars. The army was kept by the guard system: a guard of about 5,600 men, a battalion of 1,120 under it, a company of 112 under that. Military households were hereditary and almost impossible to leave; part of each garrison stood watch while the rest farmed military land and fed the whole. Hence the boast attributed to the founder — I keep an army of a million and it costs the people not one grain of rice. Reality answered it: the registers for 1438 are recorded as showing more than 1.63 million deserters, the military land had been eaten away by officials, and in the Jiajing years the state had to hire soldiers instead; the guard system was dead in all but name.'],
      fall:['定额财政收不抵支,加税就激民变;不少学者认为,对海外白银的依赖也加剧了动荡;小冰期天灾加辽东战费压顶——李自成进京,清军坐收渔利。','The rigid quotas could not meet rising costs, and new levies bred revolt; many scholars add that dependence on overseas silver deepened the turmoil. Little Ice Age disasters and the Manchurian war bills crushed the budget — Li Zicheng took Beijing, and the Qing collected the prize.'],
      legacy:['紫禁城与今日北京的城市格局;现存长城主体是明长城;《本草纲目》与《天工开物》记下了那个时代的科学与工艺。','The Forbidden City and the layout of Beijing; the Great Wall as it stands today is mostly Ming work; and the great compendia of medicine and technology recorded the science of the age.'] },
  d:'郑和宝船七下西洋,比哥伦布早近一个世纪、船队规模大数十倍,却在朝廷转向后戛然而止——此消彼长间,大航海的红利归了欧洲。晚明江南市镇与白银经济一度繁荣,终亡于财政崩溃与小冰期灾荒的交迫。',
  gl:[ { a:1550, b:1630, k:'econ', t:['白银经济','The silver economy'], d:['美洲白银经马尼拉涌入,江南市镇与手工业空前繁荣。','American silver pours in via Manila; Jiangnan booms.'] },
       { a:1508, b:1590, k:'thought', t:['阳明心学','Yangming philosophy'], d:['知行合一,冲击程朱正统,影响远及日本。当时科举考的是程朱一路的注解,读书人从小背的就是那套「道理在圣贤书里」;心学反过来说道理在人自己心里,人人都能凭良知判断——这话在一个靠背书选官的体制里,几乎是拆台。','Knowledge and action are one, said Wang Yangming, and the orthodoxy of Zhu Xi was shaken; the school reached Japan. The examinations at the time tested the Cheng-Zhu commentaries, and every candidate had grown up on the premise that the truth lives in the books of the sages. Wang put it the other way round — the truth is in your own mind, and anyone can judge by the conscience he was born with. In a state that chose its officials by memorisation, that was close to pulling the floor out.'] },
       { a:1580, b:1640, k:'art', t:['小说时代','The age of the novel'], d:['《西游记》《金瓶梅》与晚明出版业互相成就。','Journey to the West and a thriving print market.'] },
       { a:1570, b:1640, k:'tech', t:['晚明技术总结','The late-Ming compendia'], d:['《本草纲目》《天工开物》《农政全书》三部大书同代问世。','Three great technical compendia in a single generation.'] } ] },
{ l:'ea', s:'sino', v:0, n:'清', k:[[1636,0],[1700,.8],[1790,.9],[1840,.6],[1895,.35],[1912,0]], b:'康乾盛世奠定现代中国版图;鸦片战争后陷入百年危机。',
  e:{ n:'Qing', w:'Qing dynasty', b:'The High Qing set China\'s modern map; then a century of crisis.', d:'The Kangxi-Qianlong age passed 300 million people and fixed the modern territorial base including Xinjiang and Tibet; but closure and technical stagnation opened an invisible gap. After 1840 the gunboats came — treaties, cessions, indemnities — "a change unseen in three thousand years."', f:{ 'Peak':'18th century', 'Center':'Beijing', 'Figures':'Kangxi, Qianlong, Cao Xueqin, Wang Zhenyi, Wei Yuan', 'Legacy':'Modern territory & multiethnic state, Dream of the Red Chamber' } },
  f:{ '鼎盛':'乾隆前中期(18世纪)', '中心':'北京', '人物':'康熙、乾隆、曹雪芹、王贞仪、魏源', '成就':'奠定现代版图与多民族格局、《红楼梦》' },
  qh:{ born:['八旗把部落,变成了一台战争机器','The banners turned tribes into a war machine'],
       rule:['同一个皇帝,对不同族群换不同身份','One emperor, appearing differently to each people'],
       money:['茶、丝、瓷换回来的,是白银','Tea, silk and porcelain came back as silver'],
       power:['玉米红薯一来,人口涨到三亿','Maize and sweet potato arrived, and the people reached three hundred million'],
       fall:['改革总比危机慢一步','Reform was always one step behind the crisis'],
       legacy:['人口大国的底盘,也是那时候打下的','The base of a billion-strong country was laid then'] },
  q:{ born:['满洲各部原在明朝的辽东边墙之外、名义上受明朝羁縻,努尔哈赤用三十年把它们并成一体,1615 年定八旗——每个人既是兵又是民,部落从此成了一台战争机器;1636 年皇太极改国号为清。明亡于李自成,1644 年吴三桂开山海关,清军入关接管天下。','The Manchu clans lived beyond the Ming border wall in Liaodong, nominally under Ming suzerainty; Nurhaci spent thirty years welding them together and in 1615 fixed the Eight Banners — every man both soldier and subject, so the tribes became a war machine — and in 1636 Hong Taiji renamed the state Qing. When the Ming fell to Li Zicheng, Wu Sangui opened the Shanhai Pass in 1644 and the Qing marched in to take over the realm.'],
      rule:['一国多制:汉地沿用明制科举官僚,蒙古用盟旗,西藏派驻藏大臣,回疆用伯克——皇帝对不同族群以不同身份出现,八旗驻防各省监视。而真正拍板的地方越来越小:1729 年雍正在隆宗门内侧设了一处值房,后来叫军机处。它没有定员,最多时六七个人;没有专职官员,进去的都是拿着原职来兼差;屋里只有桌、椅、炕、砚。就是这么一间小屋取代了议政王大臣会议与内阁,成了帝国的决策中枢——离皇帝几步路,比任何品级都管用。(它的设立常与当年西北用兵连在一起说,也有研究认为两者并无直接关系、只是借了那个名目。)。','One empire, several systems: Ming-style examinations for China proper, banner leagues for Mongolia, imperial residents for Tibet, local begs in the Muslim west — the emperor wore a different face for each people, with banner garrisons watching all. Meanwhile the room where things were actually decided kept shrinking. In 1729 the Yongzheng emperor set up a duty office just inside the Longzong gate, later called the Grand Council. It had no fixed establishment, six or seven men at its largest; no posts of its own, everyone serving there while holding another office; and nothing in the room but a table, chairs, a heated platform and an inkstone. That small room displaced both the council of princes and the grand secretariat and became the centre of the empire — a few paces from the emperor, which counted for more than any rank. (Its founding is usually told alongside the western campaigns of that year, though some scholars hold the connection was in name only.)'],
      money:['1723 年起摊丁入亩,人头税并进田赋,田赋从此稳定;盐税是第二大进项。1757 年起对欧贸易只留广州一口,由十三行经手,茶叶、生丝、瓷器换回源源白银——十八世纪世界上流通的白银,有很大一部分最后沉淀在中国。','From 1723 the poll tax was folded into the land tax, which ran stable ever after; salt revenue came second. From 1757 trade with Europe was confined to the single port of Canton and handled by the Thirteen Hongs: tea, raw silk and porcelain went out and silver came in — a large share of the silver circulating in the eighteenth-century world ended up in China.'],
      power:['康雍乾三代持续经营内亚,版图达到一千三百万平方公里以上(英文材料按 1790 年的口径记到一千四百七十万);美洲作物玉米、红薯上山下地,人口涨到三亿,并在此后半个世纪突破四亿。','Three long reigns worked Inner Asia until the realm passed thirteen million square kilometres — Western scholarship, drawing the boundary differently, puts it at 14.7 million for 1790 — while maize and sweet potato climbed the hillsides and the population reached three hundred million, passing four hundred million within the next half century.'],
      fall:['人口爆炸而技术停滞,人均资源越摊越薄;小政府财政养不起近代军队;鸦片逆转白银流向,太平天国打烂腹地,列强环伺——改革总比危机慢一步,最终革命出局。','Population exploded while technique stood still, spreading resources ever thinner; a minimal treasury could not fund a modern army. Opium reversed the silver flow, the Taiping war wrecked the heartland, the powers pressed in — and reform ran one step behind crisis until revolution ended it.'],
      legacy:['今日中国版图的基本盘继承自清,人口大国的底盘亦然——这个「底盘」有很具体的形状:1741 年在册一亿四千三百万,1775 年两亿六千五百万,1833 年三亿九千九百万,1851 年四亿三千二百万。一百一十年翻了三倍,而摊丁入亩取消了人头税、生孩子不再多交税,是这条曲线转折的原因之一。故宫、避暑山庄与《四库全书》留存至今。','The territorial outline of modern China descends from the Qing, and so does its demographic base — and that base has a very definite shape: 143 million on the registers in 1741, 265 million in 1775, 399 million in 1833, 432 million in 1851. Threefold in a hundred and ten years, and one reason the curve turned upward is that the head tax had been folded into the land tax, so that another child no longer meant another levy. The Forbidden City, the Chengde resort and the great imperial library survive.'] },
  d:'康乾盛世人口破三亿,版图囊括新疆西藏,奠定现代中国的疆域底盘;但闭关与技术停滞使差距在不知不觉中拉开。1840年英国炮舰打上门之后,条约、割地、赔款接踵而至——"三千年未有之大变局"贯穿其后七十年。',
  gl:[ { a:1680, b:1790, k:'econ', t:['康乾盛世经济','High-Qing economy'], d:['在册人口 1741 年首次过一亿四千万,1790 年过三亿;玉米、红薯、土豆能种在稻麦种不了的山坡上,养活了新添的人口。1712 年康熙宣布「滋生人丁永不加赋」,人头税不再随人口涨,十一年后干脆并进田赋。','The registered population first passed 140 million in 1741 and 300 million in 1790; maize, sweet potato and potato grew on hillsides where rice and wheat could not, and fed the newcomers. In 1712 Kangxi froze the poll tax for ever, so it no longer rose with the population, and eleven years later it was folded into the land tax altogether.'] },
       { a:1720, b:1800, k:'thought', t:['《四库全书》与考据','The Four Treasuries and evidential scholarship'], d:['1773 年乾隆开四库馆,收书三千四百六十余种、七万九千多卷,十年抄成第一部,前后十几年抄齐七部分藏七阁,三千八百名抄手一字一字誊写;同时也借机销毁了不少「违碍」的书。学者转向考据:戴震、段玉裁一个字一个字地校勘古书,不空谈义理。','In 1773 Qianlong opened the Four Treasuries office; it gathered some 3,460 titles in more than 79,000 chapters, the first set finished in ten years and all seven sets — for seven pavilions — over about fifteen, copied by hand by 3,800 scribes — and used the occasion to destroy many books judged offensive. Scholars turned to evidence: Dai Zhen and Duan Yucai collated the classics character by character instead of arguing about their meaning.'] },
       { a:1750, b:1795, k:'art', t:['《红楼梦》时代','Dream of the Red Chamber'], d:['曹雪芹在北京西郊写《红楼梦》,前八十回以抄本流传,1791 年程伟元、高鹗排印一百二十回本。同一个时代,郎世宁在宫里用西洋画法给乾隆画像、参与设计圆明园的西洋楼;1790 年徽班三庆班进京为乾隆祝寿,其后四大徽班陆续会齐,京剧从此起步。','Cao Xueqin wrote Dream of the Red Chamber in the western suburbs of Beijing; the first eighty chapters circulated in manuscript, and in 1791 Cheng Weiyuan and Gao E printed a 120-chapter edition. In the same age the Jesuit Castiglione painted Qianlong in Western style and helped design the European palaces of the Yuanmingyuan, and in 1790 the Sanqing troupe from Anhui came to Beijing for Qianlong\'s birthday, the other great Anhui troupes following over the next years — the beginning of Peking opera.'] } ] },
{ l:'ea', s:'sino', v:2, n:'朝鲜半岛诸王朝', k:[[313,0],[676,.2],[1200,.18],[1392,.22],[1800,.18],[1910,0]], b:'新罗、高丽、朝鲜一脉千年;金属活字早于古腾堡两百年。',
  e:{ n:'the Korean dynasties', w:'History of Korea', b:'A thousand-year thread: Silla, Goryeo, Joseon.', d:'After Silla\'s unification, Goryeo and Joseon each ran five centuries — Confucian and examination-based like China yet distinct: Goryeo cast movable metal type two centuries before Gutenberg, and Sejong\'s hangul is among the most scientific scripts. Annexed by Japan in 1910; divided since the war.', f:{ 'Peak':'15th c. (Sejong of Joseon)', 'Center':'Gyeongju, then Kaesong, then Hanyang', 'Figures':'Sejong the Great, Yi Sun-sin', 'Legacy':'Goryeo celadon, metal type, hangul' } },
  f:{ '鼎盛':'15世纪(朝鲜世宗)', '中心':'庆州→开京→汉阳', '人物':'世宗大王、李舜臣', '成就':'高丽青瓷、金属活字、训民正音' },
  ct:['先后的王朝','The kingdoms in succession'],
  co:[ { n:['高句丽','Goguryeo'], y:[-37,668], c:['国内城→平壤','Gungnae, later Pyongyang'], g:['三国时代(至668)','The Three Kingdoms (to 668)'], x:['三国里高句丽疆域最大,占有半岛北部与今中国东北南部;隋唐两朝四代人打了七十年才灭掉它,最后统一半岛的却是三国里最弱的新罗','Goguryeo held the most ground, covering the north of the peninsula and part of what is now northeastern China; it took the Sui and Tang four generations and seventy years to bring it down — and the one that ended up unifying the peninsula was Silla, the weakest of the three'] },
       { n:['百济','Baekje'], y:[-18,660], c:['汉城→泗沘','Hanseong, later Sabi'], g:['三国时代(至668)','The Three Kingdoms (to 668)'] },
       { n:['新罗','Silla'], y:[-57,935], c:['金城(今庆州)','Gyeongju'], m:1, g:['三国时代(至668)','The Three Kingdoms (to 668)'] },
       { n:['统一新罗','Unified Silla'], y:[668,935], c:['金城(今庆州)','Gyeongju'], g:['统一之后','After unification'], x:['同时期北方另有渤海国,本图上另有一条色带','to the north stood Balhae, which has a band of its own on this chart'] },
       { n:['高丽','Goryeo'], y:[918,1392], c:['开京(今开城)','Kaesong'], g:['统一之后','After unification'] },
       { n:['朝鲜王朝','Joseon'], y:[1392,1910], c:['汉阳(今首尔)','Seoul'], m:1, g:['统一之后','After unification'] } ],
  qh:{ born:['王朝换了三次,人和文化一直没断','Three dynasties changed; the people and culture did not'],
       rule:['新罗时代,出身就是你的天花板','Under Silla, your birth was your ceiling'],
       money:['杂乱的贡物,后来折成米和布来收','The tangle of tribute goods was folded into rice and cloth'],
       power:['军事传统长于守,不长于打出去','A military tradition built to hold, not to expand'],
       fall:['在锁国与开化之间反复,最后被吞并','Wavering between closure and opening, and then annexed'],
       legacy:['专门为不识字的百姓造的一套文字','A script made on purpose for people who could not read'] },
  q:{ born:['半岛先有高句丽、百济、新罗三国并立,新罗在7世纪后期联唐灭百济、高句丽,统一了大同江以南。918年王建建高丽,936年灭后百济、重新统一半岛;1392年李成桂废高丽自立,建朝鲜王朝。三次改朝换代都以内部势力重组为主,王朝更替而族群与文化延续,这条千年一脉是它最突出的特点。','The peninsula first held three rival kingdoms — Goguryeo, Baekje and Silla. In the late seventh century Silla, allied with Tang China, destroyed the other two and unified the land south of the Taedong River. In 918 Wang Geon founded Goryeo, and by 936 he had destroyed Later Baekje and reunified the peninsula, and in 1392 Yi Seong-gye replaced Goryeo with the Joseon dynasty. All three transitions were mainly internal rearrangements of power: dynasties changed while the people and their culture continued, and that thousand-year continuity is the peninsula\'s most striking feature.'],
      rule:['三段三套办法。新罗行骨品制,按血统等级决定一个人能做到多大的官,出身即上限。高丽引入中国式科举,建立文武两班官僚体系,但门阀势力仍强,1170年后更出现近百年的武臣政权。朝鲜王朝以性理学立国,议政府与六曹分掌政务,《经国大典》把法制固定下来,两班士大夫通过科举与言官制度长期主导朝政。','Three eras, three answers. Silla used a bone-rank system in which a person\'s birth fixed the highest office they could ever hold. Goryeo introduced Chinese-style examinations and a bureaucracy of civil and military branches, though aristocratic clans remained powerful and a military junta ran the state for roughly a century after 1170. Joseon was founded on Neo-Confucian doctrine, dividing business between a state council and six ministries and fixing the legal order in a comprehensive code, while the scholar-official class dominated politics through the examinations and a system of remonstrance officials.'],
      money:['始终以农业为基础,关键在于收租权怎么分配:高丽的田柴科按官阶授予官员收租的土地,朝鲜初年的科田法沿着同一思路重新分配。高丽的对外贸易相当活跃,与宋、辽、日本往来,青瓷是它的名产。朝鲜前期以实物贡纳征收各地土产,弊病很多,17世纪起推行大同法,把杂乱的贡物折成米、布统一征收,是它财政史上的大改革。','The economy rested on agriculture throughout, and the key question was how the right to collect rent was distributed: Goryeo granted officials land-and-woodland rights by rank, and early Joseon redistributed along the same lines. Goryeo traded actively with Song China, the Khitan and Japan, and its celadon ware was famous abroad. Early Joseon collected local products as tribute in kind, a system full of abuses; from the seventeenth century a reform converted the tangle of tribute goods into a uniform levy of rice and cloth, the great fiscal change of the dynasty.'],
      power:['防御主要依托山城与地形:高丽面对蒙古入侵时迁都江华岛坚持了近三十年,最终以称臣通婚的方式保住了王朝存续。1592年起的壬辰战争中,朝鲜依靠李舜臣指挥的水军切断日军海上补给、各地义兵袭扰,加上明朝出兵,把战线顶了回去。半岛的军事传统长于守而非扩张。','Defence rested on mountain fortresses and terrain. Facing the Mongol invasions, the Goryeo court moved to Ganghwa Island and held out for nearly thirty years, finally preserving the dynasty by submitting and marrying into the Mongol imperial house. In the Japanese invasions from 1592, Korea cut the enemy\'s sea supply lines with a navy under Admiral Yi Sun-sin, harassed them with locally raised militia, and with Ming Chinese intervention pushed the front back. The peninsula\'s military tradition was one of defence rather than expansion.'],
      fall:['朝鲜后期两班内部党争长期化,土地兼并加剧,田政、军政与还谷这三项税制积弊严重,民乱频发。19世纪面对列强叩关,朝廷在锁国与开化之间反复,1876年被日本以武力胁迫开港。甲午战争后清朝退出半岛,1905年朝鲜被迫成为日本保护国,1910年被日本正式吞并,王朝终结。','In the later Joseon period factional struggle among the scholar-official class became chronic, land concentration worsened, and the three main tax systems — land, military service and the grain loan scheme — were riddled with abuses, producing frequent unrest. In the nineteenth century, facing pressure from foreign powers, the court swung between closing the country and opening it, and in 1876 Japan forced open its ports. After the Sino-Japanese War of 1894 to 1895 China withdrew from the peninsula; in 1905 Korea was made a Japanese protectorate, and in 1910 Japan formally annexed it, ending the dynasty.'],
      legacy:['高丽的金属活字印刷开始得很早,1377年印成的《直指》是现存最早的金属活字印本,已列入联合国教科文组织世界记忆名录。世宗组织创制的训民正音,为不识汉字的百姓提供了一套依发音原理设计的文字,即今天的谚文。《朝鲜王朝实录》与《承政院日记》记录之详密,是东亚史料的重要一环。高丽青瓷与朝鲜白瓷、儒教社会结构与书院传统,也都延续至今。','Metal movable type began early in Goryeo, and the Jikji, printed in 1377, is the oldest surviving book printed with metal type; it is listed in UNESCO\'s Memory of the World register. The script commissioned by King Sejong gave ordinary people who could not read Chinese characters a writing system designed from the sounds of speech — today\'s Hangul. The Annals of the Joseon Dynasty and the Diaries of the Royal Secretariat are among the most detailed records anywhere in East Asia. Goryeo celadon and Joseon white porcelain, along with the Confucian social order and the academy tradition, remain part of Korean life.'] },
  d:'新罗联唐统一半岛后,高丽与朝鲜两朝各延五百年,科举儒教承自中国又自成体统:高丽的金属活字印刷早于古腾堡两百年,世宗创制的谚文是最科学的表音文字之一。1910年被日本吞并,战后南北分治至今。' },
{ l:'ea', s:'sino', v:1, n:'日本', k:[[600,0],[800,.2],[1200,.25],[1600,.3],[1853,.25],[1905,.5],[1942,.7],[1945,.15],[1980,.6],[2025,.45]], b:'遣唐取经又自成一格;明治骤起,战败后以经济重兴。',
  e:{ n:'Japan', b:'Learned from Tang, closed under the shoguns, leapt with Meiji.', d:'Embassies to Tang brought wholesale learning, digested into mono no aware and bushidō; two closed Tokugawa centuries ended with the Black Ships, and the Meiji generation westernized in one lifetime — defeating Qing and Russia to join the powers, then burning down in militarism and two atomic bombs. Postwar Japan chose economics and nearly caught America.', f:{ 'Peak':'1980s (economy)', 'Center':'Kyoto, later Edo/Tokyo', 'Figures':'Prince Shōtoku, Tokugawa Ieyasu, Emperor Meiji, Murasaki Shikibu', 'Legacy':'Meiji Restoration, postwar miracle' } },
  f:{ '鼎盛':'1980年代(经济)', '中心':'京都→江户/东京', '人物':'圣德太子、德川家康、明治天皇、紫式部', '成就':'明治维新、战后经济奇迹' },
  qh:{ born:['近到能一直学,远到可以不学','Close enough to keep learning, far enough to stop'],
       rule:['天皇一直在,实权在别人手里','The emperor never left; the power was elsewhere'],
       money:['买原料,卖成品,一直是这条路','Buy the raw material, sell the finished thing'],
       power:['战后把资源全投进产业和技术','After the war, resources went into industry and technology'],
       fall:['泡沫破了,人口也开始减少','The bubble burst, and the population began to shrink'],
       legacy:['第一个完成工业化的非西方国家','The first non-Western country to industrialise'] },
  q:{ born:['列岛与大陆隔着一道海:近到能不断学,远到学不来的可以不学。7世纪起派遣唐使十余次,照唐朝的样子立律令、建都城、用汉字;但派不派、学什么,始终由自己决定——894年菅原道真以唐朝衰乱、海路凶险为由建言停派,遣唐使就此中止。','The islands sit at a distance from the mainland that is near enough to keep learning from it and far enough to decline what does not suit. From the seventh century more than ten embassies went to Tang China, and law codes, capital plans and the writing system were taken from it — but what to adopt, and whether to go at all, stayed a local decision: in 894 Sugawara no Michizane advised suspending them, citing the disorder in Tang China and the dangers of the crossing, and they were never resumed.'],
      rule:['一条贯穿千年的双轨:天皇一直在,但从1185年起实权归幕府将军,直到1868年明治维新才收回。这套「有天皇、有将军」的安排让改朝换代很少表现为王朝更替——天皇一系从未被推翻,换的是掌权的武家。战后宪法把天皇定为象征,内阁对国会负责。','One arrangement ran for most of a thousand years: the emperor remained, but from 1185 real power lay with the shogun, and it was only taken back at the Meiji Restoration in 1868. Because of that, changes of regime rarely looked like changes of dynasty — the imperial line was never overthrown; what changed was which warrior house held power. The postwar constitution made the emperor a symbol and put the cabinet answerable to the Diet.'],
      money:['耕地少、资源更少,所以路径一直是「买原料、卖成品」。江户时代靠国内的米与手工业,明治后靠生丝与纺织换外汇、买机器,战后靠钢铁、造船、汽车与电子。1980年代制造业达到顶点,丰田的生产方式被全世界工厂抄了一遍。','Little farmland and less in the way of raw materials, so the route has always been to buy inputs and sell finished goods. The Edo economy ran on rice and crafts at home; after Meiji, raw silk and textiles earned the foreign currency that bought machinery; after the war it was steel, shipbuilding, cars and electronics. Manufacturing peaked in the 1980s, and Toyota\'s way of running a factory was copied worldwide.'],
      power:['明治维新是一次自上而下的整体改造:废藩置县、征兵、办学校、建铁路与工厂,半个世纪内从被迫开国到打赢日俄战争。此后走向对外扩张:1910年吞并朝鲜,1931年起发动侵华战争,1941年与美英开战,1945年战败投降。战后力量的形式变了——放弃战争的宪法第九条加上美日同盟,把资源集中投进了产业与技术。','The Meiji Restoration was a wholesale reconstruction from the top: domains abolished, conscription introduced, schools, railways and factories built — and in half a century the country went from being forced open to defeating Russia. Expansion abroad followed: Korea was annexed in 1910, war against China began in 1931, war with the United States and Britain in 1941, and it surrendered in defeat in 1945. After 1945 the form of its strength changed: a constitution renouncing war, plus the alliance with the United States, concentrated its resources on industry and technology instead.'],
      fall:['1990年前后资产泡沫破裂,股市与地价长期下跌,银行背上巨额坏账,增长从此换挡——通常被称作「失去的十年」,实际影响延续得更久。同时人口结构转向:出生数自1970年代中期见顶后长期下行,2010年前后总人口开始减少,这是此后所有政策的底层约束。','The asset bubble burst around 1990: share and land prices fell for years, banks were left with enormous bad loans, and growth shifted down a gear in what is usually called the lost decade, though its effects ran longer. The population turned at the same time — births have fallen since the 1990s and the total began to shrink around 2010, and that is the constraint underneath every policy since.'],
      legacy:['汉字与佛教从大陆传入后被改造成自己的形态:假名、和歌、能与歌舞伎、浮世绘。近代它是第一个完成工业化的非西方国家,这条路径被后来的东亚各国反复参照。战后的制造业标准、动画与游戏,则是另一种形式的输出。','Writing and Buddhism came from the mainland and were reworked into local forms — the kana syllabaries, court poetry, noh and kabuki, the woodblock print. In the modern era it was the first non-Western country to industrialise, a path East Asian countries have referred back to ever since. Postwar manufacturing standards, animation and video games are an export of another kind.'] },
  ct:['先后的时代','The eras in succession'],
  co:[ { n:['飞鸟·奈良','Asuka-Nara'], y:[592,794], c:['飞鸟→平城京(奈良)','Asuka, later Nara'], g:['学中国的时代','Learning from China'], x:['派遣唐使十余次,照唐制立律令、建都城;文字、佛教与官制都从这条线进来','More than ten embassies went to Tang China; law codes and capital plans were copied from it, and writing, Buddhism and the shape of government all came in along this line'] },
       { n:['平安','Heian'], y:[794,1185], c:['平安京(今京都)','Kyoto'], g:['学中国的时代','Learning from China'] },
       { n:['镰仓幕府','Kamakura'], y:[1185,1333], c:['镰仓','Kamakura'], g:['武士当权的时代','The age of the warrior'], x:['天皇仍在,但实权归幕府;这套「有天皇、有将军」的双轨一直延续到1868年','The emperor remained, but power lay with the shogunate; that double arrangement — an emperor and a shogun — lasted until 1868'] },
       { n:['室町幕府','Muromachi'], y:[1336,1573], c:['京都','Kyoto'], g:['武士当权的时代','The age of the warrior'] },
       { n:['战国','Sengoku'], y:[1467,1600], c:['群雄割据','no single centre'], g:['武士当权的时代','The age of the warrior'] },
       { n:['江户幕府','Edo'], y:[1603,1868], c:['江户(今东京)','Edo, now Tokyo'], m:1, g:['武士当权的时代','The age of the warrior'] },
       { n:['近代日本','Modern Japan'], y:[1868,1945], c:['东京','Tokyo'], g:['近代以来','The modern era'], x:['明治维新后急速工业化与对外扩张,1945年战败;此后以经济重兴','Rapid industrialisation and expansion abroad followed the Meiji Restoration, ending in defeat in 1945; the country then rebuilt through its economy'] },
       { n:['战后日本','Postwar Japan'], y:[1945,2025], c:['东京','Tokyo'], g:['近代以来','The modern era'] } ],
  d:'遣唐使全盘取经,又消化出"物哀"的审美(对易逝之美的敏感)与武士道;德川锁国两百年后被黑船敲开,明治维新一代人完成西化,接连击败清俄跻身列强,终在军国扩张中毁于两颗原子弹。战后专注经济,一度逼近美国;动漫与精益制造至今是其文化与产业名片。' },
{ l:'ea', s:'sino', v:2, n:'朝鲜', k:[[1945,0],[1948,.2],[1970,.28],[1995,.15],[2025,.18]], b:'半岛北半边:1948 年建国,同一个家族掌权三代,今天世界上最封闭的国家之一。',
  e:{ n:'North Korea', w:'North Korea', b:'The northern half of the peninsula: founded in 1948, ruled by one family for three generations, today among the most closed countries in the world.', d:'Japan\'s rule over Korea ended in 1945 and the peninsula was split at the 38th parallel between Soviet and American occupation; in 1948 two states were proclaimed, and in the north Kim Il Sung, a former guerrilla, headed the Democratic People\'s Republic. The northern army\'s crossing of the parallel in June 1950 began the Korean War, which ended in 1953 with an armistice — never a peace treaty — and a border almost where it started. The north rebuilt with Soviet and Chinese help and for a time out-produced the south, then fell behind from the 1970s; the loss of Soviet aid after 1991 and floods brought a famine in the mid-1990s that killed hundreds of thousands. Power passed from Kim Il Sung to his son Kim Jong Il in 1994 and to his grandson Kim Jong Un in 2011; the state tested its first nuclear weapon in 2006 and remains under heavy international sanctions.', f:{ 'Peak':'1960s', 'Centre':'Pyongyang', 'Figures':'Kim Il Sung', 'Legacy':'the demilitarised zone, one of the world\'s longest-running armistices, mass games' } },
  f:{ '鼎盛':'1960年代', '中心':'平壤', '人物':'金日成', '成就':'三八线非军事区、持续最久的停战之一、大型团体操' },
  qh:{ born:['一条纬线,把一个民族分成两个国家','One line of latitude split one people into two states'],
       rule:['爷爷、爸爸、儿子,三代人一个位子','Grandfather, father, son — one seat for three generations'],
       money:['先是比南边富,后来饿死了几十万人','Richer than the south at first; later famine killed hundreds of thousands'],
       power:['那场仗打了三年,至今没有签和平条约','A war of three years, and still no peace treaty'],
       fall:['几次南北会面,一份和平条约也没换来','Several summits, and still no peace treaty'],
       legacy:['说一样的话,吃一样的泡菜,七十多年不能往来','Same language, same kimchi, seventy years apart'] },
  q:{ born:['1945 年 8 月日本投降,统治了朝鲜三十五年的殖民时期结束;苏联和美国以北纬三十八度线为界分区受降,原本说是暂时的。1948 年南北各自建国,北边由抗日游击队出身的金日成领导,叫朝鲜民主主义人民共和国,首都平壤——那座城在朝鲜战争中被炸平,战后按苏联式的宽马路和大广场重建。','Japan surrendered in August 1945 and thirty-five years of colonial rule over Korea ended; the Soviet Union and the United States divided the peninsula at the 38th parallel to take the surrender, supposedly for the time being. In 1948 two states were founded, the north under Kim Il Sung, a former anti-Japanese guerrilla, as the Democratic People\'s Republic of Korea with its capital at Pyongyang — a city flattened in the Korean War and rebuilt afterwards on Soviet lines with wide avenues and great squares.'],
      rule:['金日成掌权四十六年,把国家建成围绕他一个人的体制:「主体思想」写进宪法,他的像章人人佩戴;1994 年他去世后儿子金正日接班,2011 年金正日去世后孙子金正恩接班——这是社会主义国家里唯一的三代世袭。国家控制几乎全部信息,普通人不能自由上网、出国,离开的人被称为「脱北者」,多数经中国转道去了韩国。','Kim Il Sung held power for forty-six years and built the state around himself: the Juche idea was written into the constitution and everyone wore his badge; when he died in 1994 his son Kim Jong Il took over, and when Kim Jong Il died in 2011 his son Kim Jong Un followed — the only three-generation succession among socialist states. The state controls almost all information, ordinary people cannot use the open internet or travel abroad, and those who leave are called defectors, most of them reaching South Korea by way of China.'],
      money:['1950 年代到 60 年代,北方靠苏联和中国的援助和自己的煤铁重工业恢复得很快,一度比南方富;1970 年代起南方起飞,北方停滞。1991 年苏联解体、援助断绝,加上 1995 年前后的大水,粮食体系崩溃,「苦难的行军」年间饿死的人估计有几十万(具体数字争议大)。此后靠中国的粮食和石油,还有市场上悄悄长出来的小买卖过日子;核试验带来的国际制裁至今没有解除。','In the 1950s and 60s the north recovered fast on Soviet and Chinese aid and its own coal and heavy industry, and for a time was richer than the south; from the 1970s the south took off and the north stood still. The Soviet collapse in 1991 cut off aid, floods around 1995 broke the food system, and the famine of the Arduous March years killed an estimated hundreds of thousands (the figure is much argued). Since then the country has lived on Chinese grain and oil and on small markets that quietly grew up on their own; the international sanctions brought on by its nuclear tests remain in place.'],
      power:['1950 年 6 月北方军队越过三八线南下,几乎打到釜山;联合国军在仁川登陆后越过三八线北上,10 月中国出兵参战,少数部队一度打到鸭绿江边,战线最后又推回三八线附近。1953 年签的是停战协定,不是和平条约,所以从法律上说这场仗到今天没有结束——板门店的谈判桌就摆在分界线上,两边士兵面对面站着。北方 2006 年第一次核试验,此后又试了五次,拥有核武器成了它最主要的筹码。','In June 1950 the northern army crossed the 38th parallel and drove almost to Busan; United Nations forces landed at Incheon and pushed north across the parallel, China entered the war in October, a few units reached the Yalu, and the front settled again near the 38th parallel. What was signed in 1953 was an armistice, not a peace treaty, so in law the war has never ended — the negotiating table at Panmunjom sits on the line itself, with soldiers from both sides standing face to face. The north tested a nuclear weapon for the first time in 2006 and five times since; possessing the bomb has become its main bargaining chip.'],
      fall:['冷战结束时很多人以为它会像东德一样很快消失,三十多年过去它还在;2000 年、2007 年、2018 年南北领导人几度会面(2018 年一年就见了三次),2018—2019 年金正恩与美国总统开了两次峰会、又在板门店见过一次,都没有换来和平条约。今天南北的差距是世界上最悬殊的邻国之一:同一个民族,一边是发达国家,一边夜里从卫星上看几乎没有灯光。','When the Cold War ended many expected it to vanish quickly like East Germany, and more than thirty years later it is still there; the leaders of north and south met in 2000, in 2007 and three times in 2018, and Kim Jong Un held two summits with the American president in 2018-2019 and met him once more at Panmunjom, without a peace treaty coming of it. The gap between north and south is now among the widest between any two neighbours on earth: one people, one half a developed country, the other almost dark at night when seen from a satellite.'],
      legacy:['三八线两侧四公里宽的非军事区七十年几乎没有人住,反倒成了东北亚保存最好的野生动物走廊之一,丹顶鹤和白枕鹤在里面过冬。朝鲜的大型团体操「阿里郎」(2002—2013 年演出)曾让几万人同时翻动彩色卡片拼图,是世界上规模最大的团体表演之一;平壤地铁挖在一百多米深处,兼作防空洞。对孩子最容易记的一件事:半岛两边的人说同一种话、吃同样的泡菜,却已经七十多年不能自由往来。','The demilitarised zone, four kilometres wide along the line, has had almost no residents for seventy years and has become one of the best-preserved wildlife corridors in north-east Asia, where red-crowned and white-naped cranes winter. The Arirang mass games in Pyongyang (staged 2002-2013), tens of thousands of people flipping coloured cards in unison, were among the largest group performances in the world; the Pyongyang metro runs more than a hundred metres underground and doubles as a shelter. The easiest thing for a child to remember: people on both sides of the line speak the same language and eat the same kimchi, and have not been free to visit each other for more than seventy years.'] },
  d:'1945 年日本对朝鲜三十五年的统治结束,半岛以三八线为界由苏美分区受降;1948 年南北各自建国,北边由抗日游击队出身的金日成领导;1950—1953 年朝鲜战争以停战协定收场,至今无和平条约,分界线几乎回到开战时的位置。北方 1960 年代一度比南方富,1970 年代后停滞,1991 年后苏联援助断绝、再加上大水,1990 年代中期的饥荒死了估计几十万人。政权 1994、2011 年两次父传子,2006 年起六次核试验,受国际制裁;南北差距为世界之最之一。' },
{ l:'ea', s:'sino', v:0, n:'韩国', k:[[1948,0],[1990,.25],[2025,.35]], b:'战后废墟上的"汉江奇迹",制造业与流行文化双输出。',
  e:{ n:'South Korea', b:'The Miracle on the Han; chips and K-culture.', d:'From postwar ruins poorer than Ghana, one generation industrialized — the Miracle on the Han; today it leads in semiconductors and shipbuilding and exports its pop culture worldwide, the most successful late-development case of the century.', f:{ 'Peak':'after 1988 (democratisation, industrial upgrading)', 'Center':'Seoul', 'Figures':'Park Chung-hee, Kim Dae-jung', 'Legacy':'Semiconductors, shipbuilding, K-pop' } },
  f:{ '鼎盛':'1988年后(民主化与产业升级)', '中心':'首尔', '人物':'朴正熙、金大中', '成就':'半导体、造船、K-pop' },
  qh:{ born:['起点是世界上最穷的国家之一','It started as one of the poorest countries on earth'],
       rule:['先是威权办发展,1987年才有直选','Authoritarian development first, direct elections from 1987'],
       money:['从假发做到半导体,一级一级往上爬','From wigs to semiconductors, one rung at a time'],
       power:['国内市场太小,只能去外面卖','The home market was too small, so it had to sell abroad'],
       fall:['1997年外汇枯竭,百姓交出私藏黄金','In 1997 the reserves ran dry, and people gave up their gold'],
       legacy:['两代人,从废墟走到高收入','Two generations, from rubble to a high-income country'] },
  q:{ born:['1945年从日本殖民统治下解放——日本投降时,美苏以北纬三十八度线为界分区受降,这条临时的军事分界线后来固定下来,1948年南北各自建国,1950至1953年的战争把半岛打成废墟。战后的韩国是世界上最穷的国家之一,没有资源、没有资本、没有市场——后来的一切都要从这个起点看才有分量。','Liberated from Japanese colonial rule in 1945 — at the surrender the United States and the Soviet Union took the Japanese capitulation on either side of the 38th parallel, and that temporary military line hardened into a border, with separate states north and south from 1948, the peninsula was then wrecked by the war of 1950-53. The South that emerged was among the poorest countries on earth, with no resources, no capital and no market — everything that followed only carries its weight measured from there.'],
      rule:['前三十年是威权发展体制:政府定产业方向,把资金与出口配额投向少数几家企业集团,同时压制工会与反对派。1980年光州事件后民主运动持续扩大,1987年通过总统直选的修宪,此后政权在选举中和平轮替。','For three decades it ran an authoritarian development model: the state picked the industries and steered capital and export quotas to a handful of conglomerates, while suppressing unions and opposition. After the Gwangju uprising of 1980 the democracy movement widened, a constitutional amendment in 1987 brought direct presidential elections, and power has changed hands at the ballot box since.'],
      money:['一条清晰的产业阶梯:1960年代做假发、纺织与胶合板,70年代转向钢铁、造船与化工,80年代进汽车与家电,90年代之后是半导体、显示面板与手机。策略始终是出口导向——国内市场太小,必须去外面卖。','A clear industrial ladder: wigs, textiles and plywood in the 1960s; steel, shipbuilding and chemicals in the 1970s; cars and appliances in the 1980s; semiconductors, displays and phones from the 1990s. The strategy was always export-led, because the home market was too small to sell into.'],
      power:['把教育、储蓄与外部资金集中投进制造业,再用出口逼企业跟世界一流对标。政府主导提高了速度,也留下财阀集中与债务过高的隐患。半导体与造船长期居世界前列;2000年代之后,影视与流行音乐成为另一条影响力路径。','It concentrated education, savings and borrowed capital into manufacturing, then used exports to force its firms to measure themselves against the world\'s best. State direction added speed and also left concentration and heavy debt behind. Semiconductors and shipbuilding rank among the world\'s leaders, and since the 2000s film, television and music have become a second channel of influence.'],
      fall:['1997年亚洲金融危机:外债到期、外汇枯竭,韩国向国际货币基金组织求援,数家财阀破产重组,失业率骤升,民间发起献金运动交出私藏黄金。此后企业治理与金融监管被大幅改造,增长模式从规模优先转向效率与技术优先。','The Asian financial crisis of 1997: foreign debts came due, reserves ran out, the country went to the International Monetary Fund, several conglomerates were broken up or went under, unemployment jumped, and citizens queued to hand in gold from their own homes. Corporate governance and financial regulation were overhauled, and growth shifted from a priority on scale to one on efficiency and technology.'],
      legacy:['从战后废墟到高收入经济体只用了两代人,是二战后最完整的一条发展路径样本。谚文是少见的由君主主持、专为普通人识字而创制的文字,今天仍在用。半导体与显示面板支撑着全球电子产业;影视与流行音乐让一个五千万人口的国家在文化上远超其体量。','Two generations took it from ruins to a high-income economy, the most complete development path of the postwar era. Hangul is a rare case of a script commissioned by a ruler expressly so ordinary people could read, and it is still in use. Its semiconductors and displays underpin the world\'s electronics, while its screen and music industries give a country of fifty million a cultural weight far beyond its size.'] },
  d:'战后从人均不及加纳的废墟起步,一代人完成工业化,史称"汉江奇迹";如今半导体与造船居世界前列,流行文化输出全球——是二十世纪后发追赶最成功的样本之一。' },
{ l:'ea', s:'sino', v:1, n:'民国', k:[[1912,0],[1928,.3],[1937,.25],[1945,.3],[1949,0]], b:'帝制终结后的三十七年:军阀、启蒙、抗战与内战。',
  e:{ n:'Republic of China', w:'Republic of China (1912–1949)', b:'Thirty-seven years of warlords, enlightenment, war and civil war.', d:'The 1911 revolution ended two millennia of empire, but the republic staggered: amid warlord wars the New Culture and May Fourth movements lit an intellectual awakening; nominal unification in 1928 was followed by Japan\'s advance. Fourteen years of resistance ended in victory and a UN founding seat — then four years of civil war.', f:{ 'Peak':'1928–1937 (the Nanjing decade)', 'Center':'Nanjing; Chongqing (wartime)', 'Figures':'Sun Yat-sen, Chiang Kai-shek, Lu Xun', 'Legacy':'New Culture movement, the war of resistance won, a modern university system' } },
  f:{ '鼎盛':'1928—1937年(南京十年)', '中心':'南京、重庆(战时)', '人物':'孙中山、蒋介石、鲁迅', '成就':'新文化运动、抗战胜利、现代大学体系' },
  qh:{ born:['两千多年的帝制,在这里终结','Two thousand years of empire ended here'],
       rule:['宪法一再中断,各地各有各的军队','The constitution kept breaking off, and each region had its own army'],
       money:['关税自主权,是后来才一点点收回的','Even control of its own tariffs had to be won back'],
       power:['中央军和地方军长期并存,指挥不齐','Central and regional armies coexisted, and never fought as one'],
       fall:['打完十四年抗战,又打了内战','Fourteen years of war with Japan, then a civil war'],
       legacy:['现代大学和研究机构,是这时候建起来的','Modern universities and research institutes were built then'] },
  q:{ born:['清末推行新政与预备立宪,但地方咨议局、新军与留学知识群体反而成为体制外的力量。1911年10月武昌新军起义后,多省相继宣布独立。1912年1月1日中华民国临时政府在南京成立,2月清帝退位,随后袁世凯就任临时大总统,两千余年的帝制终结。','The late Qing reform programme and its move towards a constitution produced provincial assemblies, a new-style army and a body of students returned from abroad — all of which became forces outside the system it was meant to strengthen. After a mutiny by new-army units at Wuchang in October 1911, province after province declared independence. A provisional republican government was established at Nanjing on 1 January 1912; the last Qing emperor abdicated in February, and Yuan Shikai then took office as provisional president, ending more than two thousand years of imperial rule.'],
      rule:['宪政安排几经中断:临时约法与国会先后被停、被恢复,总统制与内阁制反复更改。1916年袁世凯去世后,中央政府的实际控制范围缩小,各地由不同军事集团掌握。1928年国民政府在形式上完成统一,实行训政,中央设行政、立法、司法、考试、监察五院,但各省实际受中央节制的程度差别很大。','Constitutional arrangements were repeatedly interrupted: the provisional constitution and the parliament were suspended and restored more than once, and the country switched between presidential and cabinet systems. After Yuan Shikai died in 1916 the central government\'s effective reach shrank and various regions came under the control of different military groups. In 1928 the Nationalist government completed a nominal reunification and instituted a five-branch central structure covering executive, legislative, judicial, examination and control functions, though how far individual provinces actually answered to the centre varied widely.'],
      money:['财政收入主要来自关税、盐税与统税,以及内债和外债;关税自主权到1928年后才逐步收回。1935年实行法币改革,禁止白银流通、由指定银行发行统一纸币,币制得到一次整合。抗战期间沿海关税与工商税源大量丧失,财政转向发行货币,战后货币发行量继续大幅增加,物价随之大幅上涨。','Revenue came mainly from customs duties, the salt tax and consolidated commodity taxes, plus domestic and foreign borrowing; tariff autonomy was only recovered step by step after 1928. A 1935 currency reform banned the circulation of silver and put note issue in the hands of designated banks, consolidating the monetary system. During the war with Japan the loss of coastal customs and industrial tax bases pushed the government towards financing itself by printing money, and note issue rose sharply again after the war, with prices rising accordingly.'],
      power:['1924年设立黄埔军校,建立国民革命军,1926年起北伐。此后中央军与各地方军事集团的部队长期并存,统一指挥程度有限。抗战期间获得苏联与美国的军事援助,并有美军顾问与援华航空队参与作战。战时兵员主要通过征兵补充,军队规模庞大而装备与训练差异很大。','A military academy founded at Whampoa in 1924 produced the National Revolutionary Army, which launched a northern campaign from 1926. Thereafter central forces and various regional armies coexisted for decades with limited unified command. During the war with Japan the government received military aid from the Soviet Union and then the United States, along with American advisers and air units. Troops were raised largely by conscription, and the armies were very large but uneven in equipment and training.'],
      fall:['1931年九一八事变起,中日冲突逐步扩大,通称十四年抗战;1937年起进入全面战争。战争造成大量人员伤亡与经济损失,沿海工业区与主要城市多被占领,政府迁往重庆。1945年日本投降,中华民国成为联合国创始会员国之一。战后接收过程中出现管理与通货膨胀问题,1946年起国共内战全面展开;1949年10月中华人民共和国在北京成立,12月国民政府迁往台北。','Conflict with Japan widened from the Mukden Incident of 1931 — the fourteen years of resistance are counted from that date — and became full-scale war in 1937. The war caused very large casualties and economic losses, most coastal industrial areas and major cities were occupied and the government moved to Chongqing; Japan surrendered in 1945 and the Republic of China became a founding member of the United Nations. The postwar takeover of occupied areas ran into administrative problems and severe inflation, and full-scale civil war between the Nationalists and the Communists resumed in 1946. In October 1949 the People\'s Republic of China was established in Beijing, and in December the Nationalist government moved to Taipei.'],
      legacy:['新文化运动推动白话文取代文言成为书面语的主流,现代文学、报刊与出版业在这一时期成形。现代大学与研究机构体系建立起来,中央研究院、协和、清华、北大等在此期间发展,一批学科的中国研究传统由此起步。法律上编成民法、刑法等六法体系。抗战胜利与联合国创始会员国身份,是这一时期在国际上的主要结果;1949年后形成的两岸格局也自此开始。','The New Culture Movement made vernacular Chinese rather than classical Chinese the mainstream written language, and modern literature, journalism and publishing took shape in this period. A system of modern universities and research institutes was built, and several academic disciplines began their Chinese research traditions here. A codified body of civil, criminal and procedural law was compiled. Victory in the war with Japan and founding membership of the United Nations were the period\'s main international outcomes, and the cross-strait situation that has existed since 1949 also begins here.'] },
  d:'辛亥终结两千年帝制,共和却步履维艰:军阀混战中,新文化运动与五四点燃思想启蒙;1928年名义统一,旋即面对日本步步进逼。十四年抗战以巨大牺牲换来胜利与联合国创始国席位,又在四年内战后退守台湾。' },
{ l:'ea', s:'sino', v:2, n:'共和国', k:[[1949,0],[1956,.35],[1978,.4],[2000,.65],[2025,.9]], b:'改革开放引爆史上最大规模工业化,重回世界舞台中心。',
  e:{ n:'People\'s Republic', w:'China', b:'Reform ignites history\'s largest industrialization; center stage again.', d:'The first three decades built the industrial base and the bomb through great turbulence; the 1978 reforms then ignited history\'s largest industrialization and urbanization — hundreds of millions out of poverty in forty years. China is back at center stage, in a new two-power tension with America.', f:{ 'Reform begins':'Reform & Opening 1978', 'Peak':'after 2010 (second-largest economy)', 'Center':'Beijing, Shanghai, Shenzhen', 'Figures':'Mao Zedong, Deng Xiaoping, Tu Youyou, Yuan Longping, Wang Xuan', 'Legacy':'Forty years of growth, mass poverty exit' } },
  f:{ '改革起点':'1978年改革开放', '鼎盛':'2010年后(世界第二大经济体)', '中心':'北京、上海、深圳', '人物':'毛泽东、邓小平、屠呦呦、袁隆平、王选', '成就':'四十年高速增长、数亿人脱贫' },
  qh:{ born:['人均寿命从三十五岁,涨到六十七岁','Life expectancy went from about 35 to about 67'],
       rule:['先在一个地方试,行得通再铺开','Try it in one place first, then spread what works'],
       money:['先在农村放开,再把工厂开给世界','Freed the countryside first, then opened the factories'],
       power:['高铁里程世界第一,工程师成批地出','The largest high-speed rail network, and engineers by the batch'],
       fall:['重心从阶级斗争转到经济建设','The central task shifted to building the economy'],
       legacy:['青蒿素、杂交水稻、汉字激光照排','Artemisinin, hybrid rice, and Chinese type for modern printing'] },
  q:{ born:['1949年建国时面对的是一个连年战乱、工业基础薄弱、文盲率极高的国家。前三十年确立了统一的国家机器、完成了土地改革与基础工业布局,同时经历了大跃进与文革。中共1981年的《历史决议》对这两段有正式结论:大跃进是「忽视了客观的经济规律」,文革则「使党、国家和人民遭到建国以来最严重的挫折和损失」。人均寿命从建国初的约35岁提高到1980年的约67岁,是这一时期最确定的一项变化。','In 1949 the new state inherited a country worn down by decades of war, with a thin industrial base and very high illiteracy. The first three decades established a unified state apparatus, carried out land reform and laid down basic industry, and also passed through the Great Leap Forward and the Cultural Revolution, The Party\'s own 1981 resolution on history reached formal conclusions on both: the Great Leap had \'ignored objective economic laws\', and the Cultural Revolution had \'brought the Party, the state and the people the most severe setback and losses since the founding of the People\'s Republic\'. Life expectancy rose from about 35 at the founding to about 67 by 1980, the most clearly measurable change of the period.'],
      rule:['中国共产党领导的单一制国家,中央与地方分级管理,五年规划是资源配置的主要工具。改革之后的一个显著做法是「先试点再推广」:深圳等经济特区、家庭联产承包责任制都是先在局部试,行得通再铺开——这套渐进方式与同期苏东的一次性转轨形成对照,也是许多研究者关注的重点。','A unitary state led by the Communist Party, administered through tiers from centre to locality, with five-year plans as the main tool for allocating resources. One notable practice since the reforms is to pilot first and extend later: the special economic zones and the household responsibility system in farming were both tried in one place and rolled out once they worked — a gradual approach often contrasted with the single-step transitions in the Soviet bloc, and much studied for that reason.'],
      money:['1978年前是计划经济。改革后先在农村放开生产,再引入外资与出口加工,凭借规模庞大且受过基础教育的劳动力成为世界制造中心;2001年加入世贸组织后出口迅速扩大。此后逐步转向基建、内需与产业升级,今天在电子、机械、新能源与电动车等领域产量居世界前列。','Before 1978 it ran a planned economy. The reforms first freed up production in the countryside, then brought in foreign investment and export processing, and a very large workforce with basic schooling made the country the world\'s manufacturing centre; exports expanded quickly after it joined the World Trade Organization in 2001. The emphasis has since shifted toward infrastructure, domestic demand and moving up the industrial ladder, and it now leads world output in electronics, machinery, renewables and electric vehicles.'],
      power:['规模本身就是一种力量:十四亿人口既是劳动力也是市场。此外是持续多年的高储蓄与高投资、覆盖全国的基础设施(高铁网络里程居世界第一),以及从基础教育到工程师培养的完整体系。航天、高铁、通信设备等领域的进展,多是长期国家投入与市场规模共同作用的结果。','Scale is itself a kind of strength: 1.4 billion people are both a workforce and a market. To that add many years of high saving and high investment, infrastructure reaching across the country — the largest high-speed rail network in the world — and a full pipeline from basic schooling to engineering training. Progress in spaceflight, high-speed rail and telecommunications equipment has generally come from sustained state investment meeting that scale of market.'],
      fall:['1978年底的十一届三中全会决定把工作重心转向经济建设,通常被视为当代中国的分水岭。此后四十余年,国内生产总值增长约数十倍,按世界银行的国际贫困线标准有数亿人脱贫,城镇化率从不足两成升至六成以上。这一进程也带来了区域差距、环境代价与人口结构变化等长期课题——1980年起实行的独生子女政策于2015年放开二孩、2021年放开三孩,是后一项的直接背景。','The Third Plenum at the end of 1978 shifted the state\'s central task to economic construction, and is generally taken as the dividing line of the contemporary era. Over the four decades since, output grew many times over, several hundred million people rose above the World Bank\'s international poverty line, and the share of people living in cities went from under a fifth to over three fifths. The same process brought regional disparities, environmental costs and a changing population structure as long-term questions — the one-child policy in force from 1980 was relaxed to two children in 2015 and three in 2021, and is the immediate background to the last of these.'],
      legacy:['汉字是唯一独立起源、又一直沿用到今天的古典文字体系。当代的具体贡献里,屠呦呦从青蒿中提取的青蒿素是全球抗疟疾治疗的基础药物,袁隆平主持的杂交水稻在多国推广,王选的激光照排让汉字进入了现代印刷。基础设施、移动支付与制造业规模,则是被其他发展中国家反复参照的经验。','Chinese characters are the only independently invented script of the ancient world still in everyday use. Among contemporary contributions, the artemisinin that Tu Youyou extracted from sweet wormwood is the basis of malaria treatment worldwide, the hybrid rice developed under Yuan Longping has been taken up in many countries, and Wang Xuan\'s laser typesetting brought Chinese characters into modern printing. Its infrastructure, mobile payments and manufacturing scale are studied repeatedly by other developing countries.'] },
  d:'前三十年在曲折中完成工业底盘与两弹一星;1978年改革开放引爆人类史上最大规模的工业化与城市化,四十年间数亿人脱贫、重回世界舞台中心,与美国构成新的两强张力——这条橙色曲线的下一段,正在书写。',
  gl:[ { a:1955, b:1993, k:'econ', t:['粮票的三十八年','Thirty-eight years of ration coupons'], d:['1955 年 11 月起全国发行粮票。那以后的三十多年里,买米不是有钱就行——得同时交钱和票;买布要布票,买油要油票,肉、糖、鸡蛋各有各的票,买自行车缝纫机还要工业券。票是按人头定量发的,1969 年规定人均一年的棉布定量是十六尺一寸。1983 年 12 月 1 日布票先停,1992 年 11 月粮票废除,1993 年 2 月起全国取消粮票油票。从「有钱也买不到」到「有钱就能买到」,这条线比任何数字都好认。','From November 1955 grain coupons were issued nationwide. For the next three decades buying rice took more than money — you handed over coupons as well; cloth needed cloth coupons, oil needed oil coupons, and meat, sugar and eggs each had their own, while a bicycle or a sewing machine took industrial vouchers on top. Coupons were rationed by head: the 1969 allowance was sixteen chi one cun of cotton cloth per person per year. Cloth coupons went first, on 1 December 1983; grain coupons were abolished in November 1992, and from February 1993 grain and oil coupons ended across the country. The line from cannot buy it even with money to can buy it with money is easier to see than any statistic.'] },
     { a:1970, b:2025, k:'tech', t:['一株野生稻','One wild rice plant'], d:['1970 年 11 月 23 日,在海南南红农场附近一片约三分地的野生稻里,李必湖与冯克珊找到一株雄性不育的野生稻——后来叫「野败」。要说清楚:找到它的是袁隆平的助手,不是袁隆平本人。1973 年籼型杂交水稻三系配套成功,1976 年「南优 2 号」在洞庭湖区第一次大面积推广。杂交稻的单产一般比普通稻高两成;到 2014 年种了约 1550 万公顷,占中国稻谷面积的 52%,2019 年这个比例回落到 45%。','On 23 November 1970, in about a fifth of a hectare of wild rice near the Nanhong farm on Hainan, Li Bihu and Feng Keshan found a male-sterile wild plant — later called yebai. It is worth being exact: the men who found it were Yuan Longping\'s assistants, not Yuan himself. The three-line hybrid system was completed in 1973 and the first variety to go out at scale, Nanyou 2, was planted around Dongting Lake in 1976. Hybrid rice yields about a fifth more than ordinary rice per unit of land; by 2014 some 15.5 million hectares were under it, 52 per cent of China\'s rice land, a share that fell back to 45 per cent by 2019.'] },
     { a:2001, b:2025, k:'econ', t:['世界工厂','Workshop of the world'], d:['入世后制造业规模跃居世界第一,2010年代后期产值超过美日总和。','After WTO entry it became the world\'s largest manufacturer; by the late 2010s its output topped the US and Japan combined.'] },
       { a:2003, b:2025, k:'tech', t:['航天与高铁','Space & high-speed rail'], d:['载人航天、北斗、四万八千公里高铁网(2024)。','Crewed spaceflight, BeiDou, a 48,000-km high-speed rail net (2024).'] } ] },
/* 撒南非洲 */
{ l:'af', s:'africa', v:0, n:'库施·努比亚', k:[[-1070,0],[-750,.4],[-300,.3],[350,0]], b:'尼罗河上游古国,曾北上统治全埃及(第25王朝)。',
  e:{ n:'Kush / Nubia', w:'Kingdom of Kush', b:'The Black Pharaohs; a thousand years on the upper Nile.', d:'The upper-Nile kingdom once ruled all Egypt as the 25th "Black Pharaoh" dynasty; from Meroë it ran its own script and ironworks, trading with Rome and Aksum for over a thousand years.', f:{ 'Peak':'8th c. BCE', 'Center':'Napata, later Meroë', 'Figures':'Taharqa', 'Legacy':'Meroitic script, early iron center' } },
  f:{ '鼎盛':'前8世纪(黑法老)', '中心':'纳帕塔→麦罗埃', '人物':'塔哈尔卡', '成就':'麦罗埃文字、非洲早期冶铁中心' },
  qh:{ born:['他们是带着埃及的宗教语言北上的','They came north carrying Egyptian religious language'],
       rule:['苏丹的金字塔,比埃及还多','Sudan has more pyramids than Egypt does'],
       money:['南北货物在这里转手,还自己炼铁','Goods changed hands here, and it smelted its own iron'],
       power:['非洲内陆的王,反过来统治了埃及','Kings from inland Africa ruled Egypt in their turn'],
       fall:['怎么结束的,到今天还说不清','How it ended is still not clear'],
       legacy:['字母能念出来,意思却读不懂','The letters can be sounded out; the meaning cannot'] },
  q:{ born:['尼罗河第一至第六瀑布之间是努比亚,长期在埃及的军事与文化影响之下,库施王权的核心在第四瀑布附近的纳帕塔一带。埃及新王国崩溃、势力北撤后,当地在纳帕塔一带兴起自己的王权;有意思的是,这些国王并不否定埃及文化,反而自认是阿蒙神信仰更纯正的守护者——他们是带着埃及的宗教语言北上的。','Nubia stretched from the first to the sixth cataract of the Nile, with Kushite kingship centred near the fourth at Napata; it, lay long under Egyptian military and cultural influence. When the Egyptian New Kingdom collapsed and its power withdrew north, a local kingship rose around Napata. What is striking is that these kings did not reject Egyptian culture; they claimed to be the purer guardians of the cult of Amun — they marched north speaking Egypt\'s own religious language.'],
      rule:['王权与阿蒙神庙紧密捆绑,据记载纳帕塔的祭司在选立新王时有发言权。王位继承不完全按父子相传,兄弟与母系亲属都在候选之列;麦罗埃时期还出现多位掌握实权的女性统治者,希腊罗马作者把她们的称号记作「坎达克」。王陵采用陡峭的小型金字塔形制,苏丹境内留下的金字塔数量比埃及还多。','Kingship was tightly bound to the temple of Amun, and the priests at Napata are recorded as having a voice in choosing a new king. Succession did not pass strictly from father to son; brothers and maternal kin were candidates too, and in the Meroitic period several women ruled in their own right, their title recorded by Greek and Roman writers as Kandake. Royal tombs took the form of small steep-sided pyramids, and more pyramids survive in Sudan than in Egypt.'],
      money:['财富来自两头:尼罗河谷的农业与畜牧养活人口,南北转运贸易带来利润——黄金、象牙、乌木、香料、豹皮、活兽从南方汇集,经努比亚运往埃及与地中海。迁都麦罗埃之后,当地丰富的铁矿与木材支撑起冶铁业,麦罗埃因此成为非洲东北部重要的冶铁中心之一。','Wealth came from two directions: farming and herding in the Nile valley fed the population, while the north-south carrying trade brought profit — gold, ivory, ebony, incense, leopard skins and live animals gathered from the south and moved through Nubia to Egypt and the Mediterranean. After the capital moved to Meroe, local iron ore and timber supported a smelting industry that made the city one of the important ironworking centres of northeastern Africa.'],
      power:['努比亚弓箭手历来有名,埃及人干脆把这片地方叫作「弓之地」。公元前8世纪库施王皮耶北上,塔哈尔卡时代统治了从苏丹到地中海的整条尼罗河,即埃及史上的第25王朝,史称「黑法老」——这是非洲内陆政权反向统治埃及的时刻。','Nubian archers were famous, and the Egyptians simply called the region the Land of the Bow. In the eighth century BCE the Kushite king Piye pushed north, and by the time of Taharqa the whole Nile from Sudan to the Mediterranean was under Kushite rule — Egypt\'s Twenty-fifth Dynasty, the so-called Black Pharaohs. It was the moment an inland African power ruled Egypt in reverse.'],
      fall:['先是被亚述赶出埃及(公元前7世纪中叶亚述军队攻入并焚掠底比斯),库施退回本土。此后衰落是缓慢的多因过程,而且史料很薄:与罗马交战后于公元前1世纪末议和,失去了对北方的影响;红海航路兴起,原本走尼罗河陆路的商品改由船运,努比亚的中转地位被削弱;过度放牧与冶铁耗用木材可能损伤了当地环境(这属于常见假说)。阿克苏姆的埃扎纳王碑文记载了对这一带的征讨,但麦罗埃王朝具体如何终结,尚无定论。','First Assyria drove Kush out of Egypt, storming and sacking Thebes in the mid-seventh century BCE, and Kush fell back to its homeland. What followed was a slow, multi-causal decline on thin evidence: after fighting Rome it made peace in the late first century BCE and lost influence to the north; the rise of Red Sea shipping moved cargo that had gone overland along the Nile onto boats, eroding Nubia\'s role as middleman; and overgrazing together with the timber consumed by ironworking may have damaged the local environment — a common hypothesis. An inscription of King Ezana of Aksum records a campaign in the region, but exactly how the Meroitic kingdom ended remains unsettled.'],
      legacy:['麦罗埃人用埃及文字的元素造出了自己的字母,字母的音值已被读出,语言却至今无法充分理解——这是非洲古代史上最著名的未解之谜之一,老实说我们还读不懂它。麦罗埃与纳帕塔的金字塔群是世界文化遗产;6世纪后努比亚皈依基督教,形成的几个王国延续了近千年,直到伊斯兰化才结束。','The Meroites built their own alphabet from Egyptian elements; its sound values have been recovered, but the language behind it still cannot be properly understood — one of the most famous unsolved problems in African antiquity, and honestly we still cannot read it. The pyramid fields of Meroe and Napata are World Heritage sites. From the sixth century Nubia turned Christian, and the kingdoms that formed lasted nearly a thousand years before Islamization ended them.'] },
  d:'尼罗河上游的库施王朝一度北上统治全埃及,史称"黑法老"的第25王朝;迁都麦罗埃后发展出自己的文字与冶铁业,与罗马、阿克苏姆贸易往来,前后存续超过一千年。' },
{ l:'af', s:'africa', v:2, n:'扎格维王朝', k:[[900,0],[1050,.18],[1150,.24],[1200,.3],[1250,.2],[1270,0]], b:'耶路撒冷去不了了,这位国王就在自己家里凿了一座:约旦河、各各他、圣墓,一样不缺。',
  d:'阿克苏姆衰落之后,埃塞俄比亚高原的中心南移,扎格维家族在罗哈一带立国。它最有名的国王叫拉利贝拉,在位大约 1181 到 1221 年——那正是萨拉丁 1187 年夺回耶路撒冷、基督徒朝圣之路被切断的年头。他的办法是把圣地搬回家:在自己的都城,从整块红色火山岩里向下凿出十一座教堂,又给旁边一条小河起名「约旦」,山丘叫「各各他」,还有一座「圣墓」。这些教堂不是遗址,今天仍在做礼拜,门口排着朝圣的人。1270 年耶库诺·阿姆拉克推翻扎格维,自称所罗门王与示巴女王的后裔;此后的王朝史料把扎格维写成篡位者——而拉利贝拉本人却被教会封为圣人,城也改叫了他的名字。',
  e:{ n:'Zagwe Dynasty', w:'Zagwe dynasty', b:'When Jerusalem became unreachable, this king cut one at home — a river Jordan, a Golgotha, a Holy Sepulchre, all of it.', d:'After Aksum declined the centre of the Ethiopian highlands moved south, and the Zagwe family established itself around Roha. Its best-known king was Lalibela, who reigned about 1181—1221 — the years in which Saladin retook Jerusalem, in 1187, and pilgrimage from Christian Ethiopia was cut off. His answer was to bring the holy city home: at his capital, eleven churches were cut downward out of solid red volcanic rock, a nearby stream was named the Jordan, a hill became Golgotha, and there was a Holy Sepulchre. These are not ruins — services are still held in them and pilgrims still queue at the doors. In 1270 Yekuno Amlak overthrew the Zagwe and claimed descent from Solomon and the Queen of Sheba; the chronicles written afterwards cast the Zagwe as usurpers — while Lalibela himself was canonised by the church, and the city took his name.', f:{ 'Peak':'Lalibela (c. 1181—1221)', 'Center':'Roha (today Lalibela)', 'Figures':'Lalibela', 'Legacy':'Eleven rock-hewn churches; a Jerusalem built at home' } },
  f:{ '鼎盛':'拉利贝拉王(约1181—1221)', '中心':'罗哈(今拉利贝拉)', '人物':'拉利贝拉', '成就':'十一座岩凿教堂、一座自己造的耶路撒冷' },
  qh:{ born:['阿克苏姆之后,高原的中心往南挪了','After Aksum the highland centre moved south'],
       rule:['国王同时是教会最大的施主','The king was also the church\'s largest patron'],
       money:['商路改走内陆,盐和黄金从南边来','Trade moved inland; salt and gold came from the south'],
       power:['守着高原,外面的军队上不来','It held the highlands, where armies could not follow'],
       fall:['被一个说自己是所罗门后裔的人推翻','Overthrown by a man claiming descent from Solomon'],
       legacy:['去不了圣城,就把圣城凿在家里','Unable to reach the holy city, they carved one at home'] },
  q:{ born:['阿克苏姆在 10 世纪前后衰落,红海的商路被阿拉伯人接手,这个王国失去了出海口。埃塞俄比亚的中心因此南移到内陆高原,扎格维家族在罗哈一带立国,时间大约从 10 世纪末到 1270 年。它不是阿克苏姆的直系延续,而是高原上另一支人接手了同一套东西:同一个教会、同一种文字、同一部经书。','Aksum declined around the tenth century, Arab powers took over the Red Sea trade, and the kingdom lost its outlet to the sea. The centre of Ethiopia therefore shifted south into the interior highlands, where the Zagwe family established itself around Roha, ruling from roughly the end of the tenth century to 1270. It was not a direct continuation of Aksum but another people of the highlands taking over the same inheritance: the same church, the same script, the same scriptures.'],
      rule:['王权与教会绑在一起:国王是教会最大的施主,教会则为王权背书。这套关系在拉利贝拉身上做到极致——他把国库大量投进凿教堂,而教会后来把他封为圣人。埃塞俄比亚正教会自 4 世纪起由埃及的科普特教会任命大主教,这条线一直延续到 20 世纪,所以这个高原上的基督教既古老又自成一格:守安息日、行割礼、用格厄兹语做礼拜。','Kingship and church were bound together: the king was the church\'s chief patron and the church underwrote the kingship. The arrangement reached its extreme in Lalibela, who poured the treasury into cutting churches and was afterwards made a saint by that church. From the fourth century the Ethiopian church had its metropolitan appointed by the Coptic church in Egypt, a link that lasted into the twentieth century — so Christianity on this plateau is at once very old and quite its own: keeping the Sabbath, practising circumcision, worshipping in Geez.'],
      money:['失去红海出海口之后,财源从转口贸易改成内陆:南边来的黄金、象牙与麝香,高原自产的盐块(阿法尔洼地的盐板一度直接当钱用),再经陆路运往红海沿岸的港口。高原本身宜农,一年两熟,养得起相当的人口——这也是它能长期自守的底子。','After losing the Red Sea outlet, income shifted from transit trade to the interior: gold, ivory and musk from the south, and salt from the highlands themselves — the salt bars of the Afar depression served for a time as currency — carried overland to the Red Sea ports. The plateau is good farmland with two harvests a year and could support a substantial population, which is also why it could hold itself apart for so long.'],
      power:['真正的防线是地形。埃塞俄比亚高原四面是断崖与深谷,外来的军队上得来也待不住,这让它在周围普遍伊斯兰化之后仍然保持基督教,成了「被伊斯兰世界包围的基督教孤岛」。欧洲中世纪流传的「祭司王约翰」传说,后来就被安到了这个国家头上——他们相信东方某处有一位基督教君主,可以从背后夹击。','The real defence was terrain. The Ethiopian plateau is ringed by escarpments and deep gorges; foreign armies could climb up but not stay, and that is why it remained Christian while the countries around it became Muslim — an island of Christianity inside the Islamic world. The medieval European legend of Prester John, a Christian king somewhere in the east who might take the Muslim powers from behind, was eventually attached to this country.'],
      fall:['1270 年一位名叫耶库诺·阿姆拉克的贵族推翻扎格维,自称是所罗门王与示巴女王之子的后裔,史称「所罗门王朝复辟」。此后的官方史料把扎格维写成没有正当血统的篡位者——而同一套史料无法处理的是,扎格维那位国王被教会封成了圣人,城也改叫他的名字。','In 1270 a nobleman named Yekuno Amlak overthrew the Zagwe and claimed descent from Solomon and the Queen of Sheba — the so-called Solomonic restoration. The chronicles written afterwards present the Zagwe as usurpers without legitimate blood. What those chronicles could not accommodate is that the church made the Zagwe king a saint, and the city was renamed after him.'],
      legacy:['拉利贝拉的十一座教堂是从整块红色火山岩里挖出来的:先在岩床上凿出深沟围出一个方块,再从上往下把里面掏空,门窗、柱子、屋顶全是原岩,没有一块是搬来的砖石。它们之间有隧道和排水沟连通,旁边一条小河被命名为「约旦」,一座山丘叫「各各他」,还有一座「圣墓」——1187 年萨拉丁夺回耶路撒冷之后,朝圣的路断了,于是这位国王在自己的国土上造了一座耶路撒冷。八百年后这些教堂仍在做礼拜,不是遗址,是还在用的房子。','The eleven churches at Lalibela were quarried out of solid red volcanic rock: trenches were cut into the bedrock to isolate a block, and the block was then hollowed downward from above, so that doors, columns and roof are all living rock and not one stone was carried in. Tunnels and drainage channels link them, a stream beside them is named the Jordan, a hill is Golgotha, and there is a Holy Sepulchre. After Saladin retook Jerusalem in 1187 the pilgrimage road closed, and this king built a Jerusalem inside his own country instead. Eight hundred years later services are still held in them: not ruins, but buildings still in use.'] } },
{ l:'af', s:'africa', v:2, n:'埃塞俄比亚帝国', k:[[1270,0],[1450,.35],[1543,.15],[1636,.25],[1800,.12],[1896,.4],[1974,0]], b:'高原上的基督教王国,1896年在阿杜瓦击败意大利。',
  e:{ n:'the Ethiopian Empire', b:'A Christian kingdom on the highlands; at Adwa in 1896 it defeated Italy.', d:'Yekuno Amlak restored the line by claiming descent from Solomon and the Queen of Sheba, and for three centuries the court moved across the highlands with a travelling camp before settling at Gondar. The Adal invasion of 1529-43 nearly ended it, and the tide turned only when Portuguese musketeers arrived; in 1896 Menelik II beat an Italian expeditionary force at Adwa. Italy still occupied the country from 1936 to 1941, and in 1974 a committee of officers deposed Haile Selassie, ending six centuries of the dynasty.', f:{ 'Peak':'15th c. and the late 19th c.', 'Center':'a travelling camp, then Gondar, then Addis Ababa', 'Figures':'Zara Yaqob, Tewodros II, Menelik II', 'Legacy':'Ge\'ez script and the Orthodox church, Adwa, its own calendar' } },
  f:{ '鼎盛':'15世纪与19世纪末', '中心':'游动王营→贡德尔→亚的斯亚贝巴', '人物':'扎拉·雅各布、特沃德罗斯二世、孟尼利克二世', '成就':'吉兹文与埃塞正教、阿杜瓦战役、自有历法' },
  qh:{ born:['一份血统主张,撑了六百多年王权','One claim of descent held up six centuries of rule'],
       rule:['长期没有都城,营地走到哪就是哪','For centuries there was no capital: the camp was it'],
       money:['咖啡的老家,就在这里的森林里','Coffee comes from the forests here'],
       power:['1896年在阿杜瓦,把意大利打了回去','At Adwa in 1896 it threw the Italians back'],
       fall:['打赢了外敌,最后是被内部终结的','It beat the invader, and was ended from inside'],
       legacy:['它用自己的历法,一年有十三个月','It keeps its own calendar, of thirteen months'] },
  q:{ born:['阿克苏姆衰落后,高原上先后由几个王朝接手,其中扎格维王朝留下了拉利贝拉的岩凿教堂。1270年耶库诺·阿姆拉克推翻扎格维,自称是所罗门王与示巴女王之子的后裔,史称所罗门王朝复辟。这套血统主张在14世纪被写成《君王的荣耀》,成为此后六百多年王权合法性的根据——它是一份政治文献,不是史料。','After Aksum declined the highlands passed through several dynasties, one of which, the Zagwe, left the rock-hewn churches of Lalibela. In 1270 Yekuno Amlak overthrew the Zagwe and claimed descent from the son of Solomon and the Queen of Sheba, a restoration of what is called the Solomonic line. In the fourteenth century that claim was written down as the Kebra Nagast and became the basis of royal legitimacy for the next six centuries — a political document rather than a historical source.'],
      rule:['长期没有固定都城:王室带着庞大的移动营地在高原上巡行,营地本身就是首都,一处的粮草吃完就换一处——直到1636年才在贡德尔定都。教会是另一根支柱,埃塞正教会的主教长期由埃及科普特教会指派,直到1950年才首次由埃塞俄比亚人出任,1959年教会获得完全自主。地方由世袭的「拉斯」(公侯)统治,中央与地方的强弱在六百年里反复摆动:1769至1855年皇帝几乎完全失权,史称「诸侯时代」,直到特沃德罗斯二世以武力重新统一。','For a long time there was no fixed capital: the court moved across the highlands with a huge travelling camp that was itself the capital, shifting once the local grain was eaten — until Gondar was settled on in 1636. The church was the other pillar, and the head of the Ethiopian Orthodox Church was appointed from the Coptic church in Egypt until 1950, when an Ethiopian first held the office; the church became fully autocephalous in 1959. The provinces were held by hereditary lords, and the balance between centre and provinces swung back and forth for six centuries: from 1769 to 1855 the emperor had almost no power at all, an age known as that of the princes, until Tewodros II reunited the country by force.'],
      money:['高原农业是底盘:海拔两千米以上雨水充足,种画眉草(苔麸)、大麦与小麦,再加畜牧;这里也是咖啡的原产地,野生咖啡就长在西南部的森林里。对外贸易走红海与内陆两条线,输出黄金、麝香、象牙与奴隶,换进布匹、金属与火器。高原本身是一道天然屏障——四周被峭壁与低地包围,进出都难,这既保住了它的独立,也让它长期与外部世界隔着一层。','Highland farming was the base: above two thousand metres the rains are reliable, and teff, barley and wheat were grown alongside herding. This is also the homeland of coffee, which grows wild in the southwestern forests. Trade ran to the Red Sea and inland, sending out gold, musk, ivory and slaves in exchange for cloth, metal and firearms. The highland is itself a rampart — ringed by escarpments and lowlands, hard to enter and hard to leave — which preserved its independence and also kept it at one remove from the outside world.'],
      power:['靠地形与骑步兵。1529至1543年阿达尔苏丹国的艾哈迈德·格朗率军攻入高原,一度几乎灭国,葡萄牙派出的火枪队于1541年赶到助战,1543年格朗阵亡,战局才逆转——这场战争让双方都元气大伤,随后奥罗莫人大规模北迁,高原的人口格局就此改变。19世纪末孟尼利克二世用出口所得大量购入欧洲步枪与火炮,1896年3月1日在阿杜瓦以数倍兵力击败意大利远征军,是近代非洲抵抗欧洲扩张最著名的一次胜利。','Terrain, plus horse and foot. Between 1529 and 1543 the armies of the Adal sultanate under Ahmad ibn Ibrahim broke into the highlands and came close to destroying the kingdom; a Portuguese musket force arrived in 1541 and the tide turned when he was killed in 1543 — a war that exhausted both sides, after which large Oromo migrations northward reshaped the population of the highlands. At the end of the nineteenth century Menelik II used export earnings to buy European rifles and artillery in quantity, and on 1 March 1896 at Adwa he defeated an Italian expeditionary force with a far larger army — the best-known victory of African resistance to European expansion in the modern era.'],
      fall:['阿杜瓦之后它仍然独立,但并非从未被占领:1935年意大利再度入侵,1936至1941年占领了这个国家,海尔·塞拉西流亡英国,直到二战中英军与埃塞游击队联手将其逐出。真正的终结来自内部:1973至1974年北部大饥荒被隐瞒,加上土地制度积弊与军队不满,1974年军官团(德尔格)废黜海尔·塞拉西,所罗门王朝结束,埃塞俄比亚进入军政府时期。','It remained independent after Adwa, though not unoccupied: Italy invaded again in 1935 and held the country from 1936 to 1941 while Haile Selassie lived in exile in Britain, until British forces and Ethiopian partisans drove the Italians out during the Second World War. The end came from inside: a great famine in the north in 1973–74 was concealed, and together with an unreformed land system and discontent in the army it brought down the throne — in 1974 a committee of officers deposed Haile Selassie, ending the Solomonic line and beginning military rule.'],
      legacy:['吉兹字母与埃塞正教会延续至今,埃塞俄比亚使用自己的历法(比公历晚七到八年,一年十三个月)与时刻制。因为长期未被殖民,它保留了独立的文字、宗教与国家传统,泛非主义与非洲统一组织把总部设在亚的斯亚贝巴,与这段历史直接相关;阿杜瓦战役至今是非洲各地反殖民叙事的共同符号。拉利贝拉岩凿教堂、贡德尔城堡群与阿克苏姆遗址都是世界文化遗产。','The Ge\'ez script and the Ethiopian Orthodox Church continue to this day, and Ethiopia keeps its own calendar — seven to eight years behind the Gregorian, with thirteen months — and its own clock. Having escaped lasting colonisation it kept an independent script, religion and statehood, which is directly why pan-Africanism and the Organisation of African Unity made Addis Ababa their seat; Adwa remains a shared symbol in anti-colonial narratives across the continent. The rock churches of Lalibela, the castles of Gondar and the ruins of Aksum are all World Heritage sites.'] },
  d:'耶库诺·阿姆拉克自称所罗门与示巴女王后裔而复辟,王室带着移动营地在高原上巡行了三百多年才定都贡德尔。1529—1543年几乎亡于阿达尔的入侵,葡萄牙火枪队赶到才逆转;1896年孟尼利克二世在阿杜瓦击败意大利远征军。1936—1941年仍被意大利占领过五年,1974年军官团废黜海尔·塞拉西,六百年王朝告终。' },
{ l:'af', s:'africa', v:1, n:'努比亚诸王国', k:[[350,0],[600,.22],[900,.28],[1200,.2],[1350,.08],[1504,.18],[1700,.15],[1821,0]], b:'阿拉伯军队打不下努比亚,于是签了一份约——那份约维持了六百年。',
  d:'库施衰亡之后,尼罗河上游先后出现几个王国,6 世纪时接受了基督教,以栋古拉为中心的马库里亚最强。641 年与 652 年阿拉伯军队两次南下都被挡回去:努比亚弓箭手准得出名,阿拉伯史料把他们叫作「瞳孔射手」。打不下来,双方改签条约,史称 baqt——努比亚每年送去一批奴隶,埃及回赠粮食、布匹与酒。这份约断断续续维持了六百年,在伊斯兰向外扩张的历史上是个罕见的例外。1312 年前后马库里亚衰亡,努比亚逐渐伊斯兰化;1504 年丰吉苏丹国在森纳尔立国,直到 1821 年被埃及的穆罕默德·阿里征服。',
  e:{ n:'Nubian Kingdoms', w:'Makuria', b:'Arab armies could not take Nubia, so they signed a treaty instead — and it held for six centuries.', d:'After Kush declined, several kingdoms rose along the upper Nile and adopted Christianity in the sixth century, the strongest being Makuria with its capital at Dongola. Arab armies came south twice, in 641 and 652, and were turned back both times: Nubian archers were famously accurate, and Arab sources called them the pupil-smiters. Unable to conquer, the two sides signed a treaty instead — the baqt, under which Nubia sent a quota of slaves each year and Egypt returned grain, cloth and wine. It held, on and off, for six centuries, a rare exception in the history of Islamic expansion. Makuria fell apart around 1312 and Nubia became gradually Muslim; in 1504 the Funj sultanate was founded at Sennar, and lasted until Muhammad Ali of Egypt conquered it in 1821.', f:{ 'Peak':'Makuria, 600—1200', 'Center':'Dongola; Sennar', 'Figures':'Kyriakos; Amara Dunqas', 'Legacy':'The baqt treaty; the wall paintings of Faras' } },
  f:{ '鼎盛':'马库里亚(600—1200)', '中心':'栋古拉、森纳尔', '人物':'基里亚科斯、阿马拉·敦卡斯', '成就':'baqt 条约、法拉斯的壁画' },
  qh:{ born:['库施之后,尼罗河上游改信了基督教','After Kush, the upper Nile turned Christian'],
       rule:['打不下来,就签一份约','What could not be conquered was contracted instead'],
       money:['南边的象牙与黄金,要从这里过','Ivory and gold from the south came through here'],
       power:['弓箭手准到被叫作「瞳孔射手」','Archers so accurate they were called pupil-smiters'],
       fall:['约到期了,人也慢慢改了信仰','The treaty lapsed and the faith slowly changed'],
       legacy:['壁画在大坝蓄水之前被切下来运走','The paintings were cut off the walls before the dam filled'] },
  q:{ born:['麦罗埃的库施王国 4 世纪衰亡之后,尼罗河上游出现了几个新王国:诺巴提亚、马库里亚、阿洛迪亚。6 世纪拜占庭派来的传教士使它们先后接受基督教,教堂沿着河建起来,用的是希腊文与当地的努比亚文。其中以栋古拉为都的马库里亚最强,后来把北边的诺巴提亚也并了进去。','After the Kushite kingdom at Meroe declined in the fourth century, new kingdoms appeared along the upper Nile: Nobatia, Makuria and Alodia. Missionaries sent from Byzantium in the sixth century brought them in turn to Christianity, and churches went up along the river, using Greek and the local Nubian script. Makuria, with its capital at Dongola, was the strongest, and later absorbed Nobatia to the north.'],
      rule:['641 与 652 年阿拉伯军队两次南下,都被挡了回去。约 748 年马库里亚国王基里亚科斯反过来带兵北上,一直打到埃及的福斯塔特城下,逼对方释放了被关押的亚历山大牧首——这条边界不是单向的。打不下来,双方改用条约:努比亚每年送去一批奴隶,埃及回赠粮食、布匹与酒——这份约叫 baqt,断断续续维持了约六百年。在伊斯兰向外扩张的那两百年里,能靠一纸约把边界稳住这么久的地方极少;努比亚因此比周边晚了六百年才改信伊斯兰教。','Arab armies came south in 641 and again in 652 and were turned back both times. Around 748 the Makurian king Kyriakos marched north in his turn, as far as Fustat in Egypt, and forced the release of the imprisoned patriarch of Alexandria — the frontier did not run one way only. Unable to conquer, the two sides settled on a treaty instead: Nubia would send a quota of slaves each year and Egypt would return grain, cloth and wine. This was the baqt, and it held on and off for some six centuries. Very few places anywhere held a frontier that long on paper during the two centuries of Islamic expansion — and Nubia stayed Christian six hundred years longer than its neighbours.'],
      money:['尼罗河是唯一的路。来自南边的象牙、黄金、乌木与奴隶都要顺河北上,努比亚各国卡在这条通道上收税、转运;条约里的岁贡与回赠,本身就是一条稳定的贸易线。栋古拉与后来的森纳尔都建在渡口附近,城里有教堂、集市与商队客栈。','The Nile was the only road. Ivory, gold, ebony and slaves from the south all had to go north along it, and the Nubian kingdoms sat astride that route, taxing and transhipping. The tribute and counter-gifts written into the treaty were themselves a steady trade line. Dongola, and later Sennar, were both built near crossings, with churches, markets and caravanserais inside.'],
      power:['努比亚弓箭手是这一带最出名的兵种,阿拉伯史料称他们为「瞳孔射手」,说他们能射中人的眼睛。加上尼罗河谷狭长、补给困难,外来军队很难在这里维持大规模作战——这是 baqt 之所以成立的现实基础:不是谁大度,是谁也吃不下谁。','Nubian archers were the famous arm here; Arab sources call them the pupil-smiters and say they could hit a man in the eye. Add a long narrow valley that made supply difficult, and a foreign army could not easily sustain a large campaign. That is the practical basis of the baqt: not anyone\'s generosity, but the fact that neither side could finish the other.'],
      fall:['13 世纪起马穆鲁克频繁干预,条约名存实亡;阿拉伯部落沿河迁入并通婚,基督教社群逐渐缩小。1312 年前后马库里亚的王位落到一位穆斯林手里,南边的阿洛迪亚也在 16 世纪初瓦解。1504 年丰吉人在森纳尔建立苏丹国,统治了三百年,1821 年被埃及的穆罕默德·阿里派兵征服。','From the thirteenth century the Mamluks intervened repeatedly and the treaty became a dead letter; Arab tribes moved in along the river and intermarried, and the Christian communities shrank. Around 1312 the throne of Makuria passed to a Muslim, and Alodia to the south broke up early in the sixteenth century. In 1504 the Funj founded a sultanate at Sennar which lasted three hundred years, until Muhammad Ali of Egypt sent an army to take it in 1821.'],
      legacy:['这一千多年留下的东西差点全没了。1960 年代埃及修阿斯旺高坝,努比亚北部将被水淹,考古队赶在蓄水前抢救发掘;法拉斯大教堂的壁画被整片切下来运走,今天分藏在华沙与喀土穆的博物馆里——那是非洲留存最完整的一批中世纪基督教壁画,画上的努比亚主教与圣徒都是深色皮肤。教堂本身留在了水下。','Most of what these thousand years left almost disappeared. When Egypt built the Aswan High Dam in the 1960s, northern Nubia was to go under water, and archaeologists dug ahead of the rising lake; the wall paintings of Faras cathedral were cut away whole and carried off, and now hang in museums in Warsaw and Khartoum. They are the most complete body of medieval Christian painting surviving in Africa, and the Nubian bishops and saints on them are dark-skinned. The cathedral itself stayed where it was, under the water.'] } },
{ l:'af', s:'africa', v:2, n:'阿克苏姆', k:[[100,0],[300,.45],[600,.3],[940,0]], b:'红海贸易强国,世界最早皈依基督教的国家之一。',
  e:{ n:'Aksum', w:'Kingdom of Aksum', b:'Red Sea trade power; among the first Christian states.', d:'Astride the Red Sea trade, Aksum minted its own gold across the Indian Ocean; King Ezana adopted Christianity before Rome made it official — the root of the Ethiopian church. It faded when Arabs took the Red Sea, but its royal line was claimed down to the last emperor in 1974.', f:{ 'Peak':'Ezana (4th c.)', 'Center':'Aksum', 'Figures':'Ezana', 'Legacy':'Giant stelae, own gold coinage' } },
  f:{ '鼎盛':'埃扎纳王(4世纪)', '中心':'阿克苏姆', '人物':'埃扎纳', '成就':'巨型方尖碑、自铸金币' },
  qh:{ born:['进出印度洋的货,都得过这道门','Goods in and out of the Indian Ocean passed this door'],
       rule:['最大的一根方尖碑,立起来时就倒了','The tallest obelisk fell as it was being raised'],
       money:['自己铸金币,还刻意对齐罗马的重量','It struck gold coins, weighed to match the Roman ones'],
       power:['一个非洲王国,曾跨海统治阿拉伯半岛','An African kingdom once ruled across the Red Sea'],
       fall:['港口被绕开了,现金来源就断了','The port was bypassed, and the cash dried up'],
       legacy:['方尖碑被墨索里尼运走,2005年才还','Mussolini took an obelisk; it came back in 2005'] },
  q:{ born:['埃塞俄比亚北部高原雨水充足、适合农耕,又居高临下俯视红海南端——从印度洋进入地中海世界的货物必须经过这道门。罗马时代印度洋季风贸易大盛,阿克苏姆凭着阿杜利斯港成为象牙与香料的出海口;1世纪的希腊文商旅手册《厄立特里亚海航行记》里已经记下了这个港口和它的国王。','The northern Ethiopian highlands get good rain and suit farming, and they look down on the southern end of the Red Sea — goods moving from the Indian Ocean into the Mediterranean world had to pass that gate. As monsoon trade across the Indian Ocean boomed in Roman times, Aksum\'s port of Adulis became the outlet for ivory and incense; the first-century Greek merchants\' handbook, the Periplus of the Erythraean Sea, already records the port and its king.'],
      rule:['国王自称「万王之王」,下面统辖一批附庸小王,巨型独石方尖碑立在王陵之上,越高代表越尊贵——最大的一根长约三十三米,一般认为在竖立时就已倒塌,真正立起来的最高一根约二十四米。4世纪埃扎纳王皈依基督教后,教会成了王权的第二根支柱;此后千余年间,埃塞俄比亚教会的主教一直由埃及的科普特教会指派,直到1950年才首次由埃塞俄比亚人出任,1959年教会获得完全自主。','The king styled himself King of Kings over a set of subordinate rulers, and towering monolithic stelae stood over the royal tombs — the taller the grander, the largest some thirty-three metres, though it is thought to have broken as it was raised; the tallest still standing is about twenty-four. After King Ezana converted in the fourth century, the church became the second pillar of the throne; for more than a thousand years afterwards the Ethiopian church\'s bishop was appointed by the Coptic church in Egypt until 1950, when an Ethiopian first held the office.'],
      money:['赚钱靠内陆物产与海外市场的差价:象牙、犀角、龟甲、乳香、黄金输出,换回罗马的金属器、玻璃与织物。最能说明它分量的一点是,阿克苏姆自铸金、银、铜三种货币,金币的重量刻意对齐罗马金币(约合当时奥里乌斯的一半)以便国际结算——在撒哈拉以南非洲,自铸货币的古代政权极为少见。','Money came from the gap between inland produce and overseas markets: ivory, rhino horn, tortoiseshell, frankincense and gold went out, and Roman metalware, glass and cloth came back. The clearest measure of its standing is that Aksum struck its own gold, silver and bronze coinage, with the gold struck at about half the weight of the contemporary Roman aureus for international settlement — an ancient state minting its own money was extremely rare in sub-Saharan Africa.'],
      power:['力量来自对港口与内陆商道的双重控制,而不是大规模常备军。6世纪卡列布王应拜占庭之请渡红海远征也门,一度统治南阿拉伯——一个非洲王国跨海统治阿拉伯半岛的时刻。3世纪的摩尼教文献据记载把阿克苏姆与罗马、波斯、中国并列为当时的四大强国,这是外人给它的位置。','Its strength came from controlling both the port and the inland trade roads rather than from a large standing army. In the sixth century King Kaleb crossed the Red Sea at Byzantium\'s request and campaigned in Yemen, ruling southern Arabia for a time — an African kingdom governing part of the Arabian peninsula. A third-century Manichaean text is recorded as listing Aksum alongside Rome, Persia and China as one of the four great powers of the age; that was the rank outsiders gave it.'],
      fall:['衰落是多因的:7世纪之后红海航路与港口逐渐由穆斯林商人掌握,阿杜利斯的中转地位被绕开,王国失去了最主要的现金来源;高原长期开垦与放牧可能已使地力下降(学界常见假说);政治重心随之南移内陆。10世纪前后传说中的古迪特女王起兵为乱,阿克苏姆城被废弃,王权转入内陆的新王朝手中。','Decline had several causes. After the seventh century Muslim merchants came to dominate Red Sea shipping and ports, Adulis was bypassed as a transit point, and the kingdom lost its main source of cash. Long cultivation and grazing on the highlands may already have exhausted the soil — a common scholarly hypothesis — and the political centre moved south into the interior. Around the tenth century a rebellion led by the queen remembered in legend as Gudit is said to have broken the kingdom; the city of Aksum was abandoned and kingship passed to new dynasties inland.'],
      legacy:['阿克苏姆是世界上最早把基督教立为国教的国家之一(亚美尼亚在同一世纪稍早,所以不宜说「第一个」),埃塞俄比亚正教会与格厄兹字母就此扎根,今天的阿姆哈拉文与提格里尼亚文都由它演变而来。所罗门王统的传说(自称示巴女王与所罗门之子的后裔)被写进1931年宪法,一直沿用到1974年末代皇帝被废;阿克苏姆方尖碑中的一根1937年被墨索里尼掠往罗马,2005年归还。','Aksum was among the earliest states in the world to adopt Christianity as its official religion — Armenia did so slightly earlier in the same century, so \'first\' is not the right word. The Ethiopian Orthodox church and the Ge\'ez script took root here, and today\'s Amharic and Tigrinya writing descend from it. The Solomonic legend, that the royal line descended from Solomon and the Queen of Sheba, was written into the constitution of 1931 and held until the last emperor was deposed in 1974. One of the Aksum obelisks was carried off to Rome by Mussolini in 1937 and returned in 2005.'] },
  d:'扼红海贸易咽喉,自铸金币行销印度洋;埃扎纳王皈依基督教比罗马定国教还早——埃塞俄比亚教会的源头即在于此。波斯与阿拉伯人控制红海后衰落,但其王统传说一直延续到1974年的末代皇帝。' },
{ l:'af', s:'africa', v:1, n:'卡涅姆·博尔努', k:[[700,0],[1250,.35],[1400,.28],[1580,.4],[1800,.2],[1900,0]], b:'乍得湖畔的千年王国:同一个王室换了两次地方,撑了一千多年。',
  e:{ n:'Kanem-Bornu', w:'Kanem–Bornu Empire', b:'A thousand-year kingdom by Lake Chad: one royal house, two countries, twelve centuries.', d:'Lake Chad has grass for horses, ground for grain, and sits where the trans-Saharan routes come down. From about the eighth century the Sayfawa built a kingship northeast of the lake and converted to Islam around 1075. Driven out at the end of the fourteenth century, the house crossed the water and rebuilt to the west as Bornu. Under Idris Alooma in the late sixteenth century it took in Ottoman muskets and Turkish instructors and walled its strongpoints. Fulani jihadists took the capital in 1808, the last Sayfawa mai was killed in 1846, the warlord Rabih conquered the country in 1893 — and after the French killed him in 1900 it was partitioned between France, Britain and Germany.', f:{ 'Peak':'late 16th c. (Idris Alooma)', 'Center':'Njimi → Ngazargamu', 'Figures':'Idris Alooma', 'Legacy':'The long Sayfawa succession, the eastern trans-Saharan route, the court chronicle' } },
  f:{ '鼎盛':'16世纪末(伊德里斯·阿洛马)', '中心':'恩吉米→比尔尼恩加扎尔加穆', '人物':'伊德里斯·阿洛马', '成就':'塞法瓦王朝的长期延续、跨撒哈拉商路东段、《宫廷编年史》' },
  qh:{ born:['重要的不是血统真假,是有话可说','What mattered was not the lineage but having one'],
       rule:['同一个家族,从11世纪坐到1846年','One family held the throne from the eleventh century to 1846'],
       money:['马靠贸易换,商路和军力就锁在一起','Horses came by trade, tying the route to the army'],
       power:['从奥斯曼买火枪,还请了土耳其教官','It bought Ottoman guns, and hired Turkish instructors'],
       fall:['它亡过一次,渡湖西迁又活了过来','It fell once, crossed the lake, and started again'],
       legacy:['一千二百年,完全在内陆,与海无关','Twelve centuries, entirely inland, nothing to do with the sea'] },
  q:{ born:['乍得湖是撒哈拉南缘最大的水面,湖周的草场能养马、能种粮,又正好是南北商路的落点。约8世纪起,湖东北的游牧集团在这里聚成一个王权,后世称卡涅姆。统治它的塞法瓦家族一直宣称自己出自也门的先祖,这类血统主张在西非王权里很常见——重要的不是它是否属实,而是它让这个王朝有了一套可以对外解释自己的说法。','Lake Chad is the largest body of water on the southern edge of the Sahara: the grass around it will keep horses and grow grain, and it sits exactly where the north-south trade routes come down. From about the eighth century nomadic groups northeast of the lake gathered into a kingship there, later called Kanem. The Sayfawa house that ruled it always claimed descent from a Yemeni ancestor — such claims are common among West African dynasties, and what matters is not whether it was true but that it gave the dynasty a way of explaining itself to outsiders.'],
      rule:['王称「迈」(Mai),被当作近乎神圣的人物,进食与出行都有帷幕遮挡,由长老会议辅政。约1075年迈·胡迈皈依伊斯兰,此后教法与本地习惯长期并行。最值得一提的是它的连续性:塞法瓦家族从11世纪一直统治到1846年,是非洲乃至世界上延续最久的王室之一——中间它被迫整体搬过一次家。','The king, called mai, was treated as near-sacred, screened by a curtain when he ate or travelled, and advised by a council of elders. Around 1075 Mai Hummay converted to Islam, and thereafter religious law and local custom ran side by side for centuries. What stands out is the continuity: the Sayfawa ruled from the eleventh century until 1846, among the longest-lasting royal houses anywhere — and in the middle of that run they had to move house entirely.'],
      money:['靠的是位置:跨撒哈拉商路的东段在这里落地,北去费赞、的黎波里,南接豪萨诸城与更南的森林地带。它出口的主要是奴隶、象牙与鸵鸟毛,换回马匹、盐、铜与火器——马是其中的关键,湖畔的草场养得起重骑兵,而马又要靠贸易补充,这条循环把商路与军力锁在了一起。','It lived on where it sat: the eastern arm of the trans-Saharan routes came down here, running north to Fezzan and Tripoli and south to the Hausa cities and the forest beyond. It sold slaves, ivory and ostrich feathers and bought horses, salt, copper and later firearms — and horses were the hinge: the lakeside pastures could keep heavy cavalry, while the horses themselves had to be replenished by trade, which locked the routes and the army together.'],
      power:['重骑兵是它的招牌,骑手与马都披甲。16世纪末伊德里斯·阿洛马在位时进行了一次彻底的军事改造:从奥斯曼帝国引进火枪并雇来土耳其教官,同时大量修筑带墙的据点,把游动的战争变成据点控制。他的宫廷史官艾哈迈德·本·福尔图为他写了两部战役编年史,是撒南非洲少见的、由当事一方留下的同时代文字记录。','Armoured cavalry, horse and rider both, was its signature. Under Idris Alooma at the end of the sixteenth century it was thoroughly rebuilt: muskets were brought in from the Ottomans along with Turkish instructors, and walled strongpoints were built in numbers, turning a war of movement into one of holding places. His court historian Ahmad ibn Furtu wrote two chronicles of his campaigns — a rare contemporary written record from inside a sub-Saharan African state.'],
      fall:['它其实亡过一次又活了过来:14世纪末,东边的布拉拉人把塞法瓦家族逐出卡涅姆,王室渡湖西迁,在博尔努重建,从此称博尔努。18世纪以后马匹与火器的优势不再独有,豪萨诸城与南方势力此消彼长;1808年富拉尼圣战军攻破都城,王室虽由学者卡内米扶起,实权已经旁落,1846年塞法瓦最后一位迈被杀。1893年苏丹军阀拉比赫征服全境,1900年他被法军击毙,此地随即被法、英、德三国瓜分。','It fell once and came back: at the end of the fourteenth century the Bulala drove the Sayfawa out of Kanem, and the house crossed the lake, rebuilt to the west in Bornu, and took that name. After the eighteenth century its edge in horses and guns was no longer its own; the Hausa cities and powers to the south rose and fell against it. In 1808 Fulani jihadists took the capital, and although the scholar al-Kanemi propped the state up, real power had passed; the last Sayfawa mai was killed in 1846. In 1893 the Sudanese warlord Rabih conquered the whole country, in 1900 French troops killed him, and the land was at once partitioned between France, Britain and Germany.'],
      legacy:['一千二百年、跨越两个都城、亡而复立——这种长度在世界史上都不多见,而它几乎完全在非洲内陆完成,与海洋无关。宫廷保存的《迪万》(编年史)记录了历代迈的世系与在位年数,是研究这一地区最重要的本土文献。今天的博尔努在尼日利亚东北部,谢胡(舍胡)一职仍在,作为传统权威延续至今;卡内米的后人至今担任这个位置。','Twelve centuries, two capitals, destroyed once and rebuilt — a run few states anywhere can match, and it was done almost entirely inland, with nothing to do with the sea. The court kept a chronicle, the Diwan, listing the line of mais and the length of each reign, and it remains the most important indigenous source for the region. Bornu today lies in northeastern Nigeria, where the office of Shehu still exists as a traditional authority, held by descendants of al-Kanemi.'] },
  d:'乍得湖畔养马、种粮,又正好是跨撒哈拉商路的落点。约8世纪起塞法瓦王朝在湖东北立国,1075年前后皈依伊斯兰。14世纪末被布拉拉人逐出,王室渡湖西迁重建于博尔努。16世纪末伊德里斯·阿洛马引进奥斯曼火枪与土耳其教官、广筑城寨,达到鼎盛。1808年富拉尼圣战军破都,1846年最后一位迈被杀;1893年拉比赫征服全境,1900年法军击毙他后,此地被法英德瓜分。' },
{ l:'af', s:'africa', v:0, n:'加纳帝国', k:[[700,0],[1000,.4],[1240,0]], b:'跨撒哈拉黄金贸易的最早霸主,"黄金之地"。',
  e:{ n:'Ghana Empire', b:'First lord of the gold-for-salt trade.', d:'Saharan caravans swapped northern salt for southern gold and the Ghana kings taxed the crossing — Arab traders wrote that even the king\'s dogs wore gold collars. Islam and literacy came south with the caravans.', f:{ 'Peak':'11th c. (Tunka Manin)', 'Center':'Koumbi Saleh', 'Figures':'Tunka Manin', 'Legacy':'Salt-gold trade system' } },
  f:{ '鼎盛':'11世纪(通卡·曼宁)', '中心':'昆比萨莱', '人物':'通卡·曼宁', '成就':'盐金贸易体系' },
  qh:{ born:['北边有盐没粮,南边有金没盐','North had salt, south had gold, and each needed the other'],
       rule:['「加纳」本是王的称号,被误当成国名','Ghana was the royal title, mistaken for the country name'],
       money:['它不掌握矿脉,掌握的是必经之路','It never held the mines, only the road they had to use'],
       power:['保护商队,商队缴税,税又养军队','Protect the caravans, they pay, and the pay buys protection'],
       fall:['教科书说被一战灭掉,学界已经不信','Textbooks say one conquest ended it; scholars now doubt that'],
       legacy:['靠收税而不是靠资源立国,后人照抄','A state built on tolls, not on resources, and copied after'] },
  q:{ born:['撒哈拉以南的萨赫勒地带有一条奇特的经济分界:北边的沙漠产盐不产粮,南边的森林边缘产金不产盐,两样东西谁都缺不了。骆驼在北非普及之后,穿越沙漠的商队变成常规交通,索宁凯人所在的位置恰好是金与盐交汇的地方——控制交汇点的政权自然强大起来。(顺带一提,这个加纳在今天的毛里塔尼亚与马里一带,和今天的加纳共和国相隔一千多公里。)','The Sahel has an unusual economic dividing line: the desert to the north produces salt but no grain, the forest edge to the south produces gold but no salt, and neither side can do without the other. Once camels came into general use in North Africa, trans-Saharan caravans became regular traffic, and the Soninke people happened to sit exactly where gold and salt met — whoever controlled that junction became powerful. (This Ghana lay in what is now Mauritania and Mali, more than a thousand kilometres from the modern Republic of Ghana.)'],
      rule:['统治者的称号是「加纳」,阿拉伯商人把这个王号误当成了国名,一直沿用至今。据当时的阿拉伯地理学家记载,王位按母系继承,传给国王姐妹的儿子而非自己的儿子;首都昆比萨莱分成两区,一区是王城与本地信仰的圣所,一区住穆斯林商人与学者,有十几座清真寺——两种秩序在一座城里并行不悖。','The ruler\'s title was ghana, which Arab merchants mistook for the country\'s name — and the mistake stuck. Arab geographers of the time record that the throne passed through the female line, to the king\'s sister\'s son rather than his own; and the capital at Koumbi Saleh was split in two, one quarter holding the royal court and the shrines of the local religion, the other housing Muslim merchants and scholars with a dozen or so mosques — two orders coexisting in one city.'],
      money:['核心机制不是采矿,而是收税:所有进出的盐与金按驮征税,进一次一个价、出一次一个价。金矿在更南的地方,由当地人开采并对来源严格保密,加纳王从不掌握矿脉——他掌握的是必经之路。据记载王室还垄断金块、只允许金砂在市面流通,以免金价被冲垮,这是很早的一种货币管理意识。','The core mechanism was not mining but taxation: every load of salt or gold paid duty on the way in and again on the way out. The goldfields lay further south, worked by local people who kept the sources strictly secret, and the king of Ghana never controlled the seams — he controlled the road they had to travel. Records also say the crown reserved gold nuggets for itself and let only gold dust circulate, so that the price would not collapse: an early instinct for currency management.'],
      power:['军力靠弓箭手与骑兵,铁制兵器相对邻邦有优势;更关键的是税收与安全之间的正循环——王保护商队不被劫掠,商队愿意走这条路并缴税,税又养得起保护商队的军队。阿拉伯史料称加纳王能出动二十万大军,这个数字明显有夸大成分,但它说明外来者对这个国家规模的印象。','Military strength rested on archers and cavalry, with an edge in iron weapons over neighbours. More important was the loop between revenue and security: the king protected caravans from raiders, caravans therefore used his road and paid duty, and the duty paid for the troops who protected them. Arab sources claim the king could field 200,000 men — plainly an exaggeration, but it shows the scale outsiders believed this state to have.'],
      fall:['衰落是多因的,而且史料很薄。旧教科书常说1076年北非的阿尔摩拉维德运动一举灭掉加纳,近几十年学界普遍质疑这个说法,认为更可能是长期的军事与宗教压力、加上王室与精英陆续皈依伊斯兰所带来的转型,而非一次征服。同时期黄金主产区南移到布雷一带,商路随之绕开加纳;牧场退化与干旱削弱了农牧基础;属邦纷纷自立,13世纪这片地区并入新兴的马里。','The decline had several causes and rests on thin evidence. Older textbooks say the Almoravid movement from North Africa destroyed Ghana in 1076; in recent decades scholars have widely questioned that, arguing for prolonged military and religious pressure plus the gradual conversion of the court and elite rather than a single conquest. In the same period the main goldfields shifted south toward Bure and the trade routes moved with them, bypassing Ghana; degraded pasture and drought weakened the farming and herding base; and vassals broke away until the region was absorbed by the rising Mali in the thirteenth century.'],
      legacy:['加纳把跨撒哈拉贸易变成了一套可以运营的制度:以税收而非资源立国,以保护商路换取财富——这个模板被马里和桑海直接继承并做大。伊斯兰教也由此在西非扎根:先是商人皈依,再是宫廷,书写与学术随之南来,西非从此进入有文献记载的历史。1957年独立的加纳共和国借用这个名字,正是为了接续这段非洲古国的记忆。','Ghana turned trans-Saharan trade into a workable institution: a state living on taxation rather than on resources, exchanging protection of the routes for wealth — a template Mali and Songhai inherited directly and scaled up. Islam took root in West Africa through the same channel, first among merchants, then at court, bringing writing and scholarship south and moving the region into documented history. The Republic of Ghana adopted the name at independence in 1957 precisely to claim that memory of an ancient African state.'] },
  d:'撒哈拉商队以北方的盐换南方的金,加纳王坐税其间,阿拉伯行商笔下"黄金之王"的狗都戴着金项圈;伊斯兰学者与文字随驼队南来,西非从此进入文字历史。' },
{ l:'af', s:'africa', v:1, n:'斯瓦希里城邦', k:[[800,0],[1200,.25],[1330,.3],[1500,.2],[1600,0]], b:'东非海岸城邦链,连接非洲内陆与印度洋世界。',
  e:{ n:'Swahili Coast', w:'Swahili coast', b:'City-states linking Africa to the Indian Ocean world.', d:'Bantu and Arab-Persian traders blended into the Swahili language and a chain of merchant cities shipping ivory and gold to India and China — Zheng He\'s fleet called here, and Kilwa still yields Chinese porcelain. The Portuguese ended the golden age.', f:{ 'Peak':'14th c. (Kilwa)', 'Center':'Kilwa, Mombasa, Zanzibar', 'Figures':'al-Hasan ibn Sulaiman', 'Legacy':'Swahili language, ocean trade net' } },
  f:{ '鼎盛':'14世纪(基尔瓦)', '中心':'基尔瓦、蒙巴萨、桑给巴尔', '人物':'哈桑·本·苏莱曼', '成就':'斯瓦希里语、印度洋商网' },
  co:[ { n:['基尔瓦','Kilwa'], c:['今坦桑尼亚南部','southern Tanzania today'], m:1, g:['海岸城邦','Coastal city-states'], x:['各城独立,谁也管不了谁;基尔瓦因控制索法拉的黄金出海口而最富,还铸了自己的铜币','each city was independent and none commanded the rest; Kilwa was the richest because it held the gold outlet at Sofala, and it even minted its own copper coins'] },
       { n:['蒙巴萨','Mombasa'], c:['今肯尼亚','Kenya today'], g:['海岸城邦','Coastal city-states'] },
       { n:['马林迪','Malindi'], c:['今肯尼亚','Kenya today'], g:['海岸城邦','Coastal city-states'] },
       { n:['拉穆','Lamu'], c:['今肯尼亚北部海岸','the northern Kenyan coast today'], g:['海岸城邦','Coastal city-states'] },
       { n:['帕泰','Pate'], c:['拉穆群岛','the Lamu archipelago'], g:['海岸城邦','Coastal city-states'] },
       { n:['桑给巴尔','Zanzibar'], c:['今坦桑尼亚外海岛屿','an island off Tanzania today'], g:['海岸城邦','Coastal city-states'] },
       { n:['摩加迪沙','Mogadishu'], c:['今索马里','Somalia today'], g:['海岸城邦','Coastal city-states'] },
       { n:['索法拉','Sofala'], c:['今莫桑比克','Mozambique today'], g:['内陆黄金的出海口','The outlet for inland gold'], x:['黄金来自内陆的大津巴布韦一带,经索法拉装船北运——这条链路把非洲腹地接进了印度洋','the gold came from the interior around Great Zimbabwe and was shipped north from Sofala — the link that tied inland Africa into the Indian Ocean'] } ],
  qh:{ born:['船要等半年,等出了商站,长成了城','Ships waited half a year, and the waiting grew into cities'],
       rule:['伊斯兰身份,是港口之间的通行证','Being Muslim was the passport between ports'],
       money:['遗址里挖出的中国瓷片,就是证据','Chinese porcelain shards in the ruins are the proof'],
       power:['力量来自懂海:季风、造船、各族规矩','The power was knowing the sea: monsoon, ships, and people'],
       fall:['开放的贸易,被改成了要通行证的','Open trade was turned into trade by permit'],
       legacy:['班图语的骨架,加大量阿拉伯语借词','A Bantu frame with a great many Arabic loanwords'] },
  q:{ born:['印度洋的季风每年半年吹向非洲、半年吹回阿拉伯与印度,这意味着商船到了东非必须等上几个月才能返航——等待催生了商站,商站长成了城市。过去常说这些城市是阿拉伯或波斯移民建立的,今天的考古与语言学研究已经修正了这个看法:斯瓦希里城邦的主体是本地班图人社会,在长期海外往来中逐渐形成了自己的城市文明。','The Indian Ocean monsoon blows toward Africa for half the year and back toward Arabia and India for the other half, which meant a ship reaching the East African coast had to wait months before it could sail home. The waiting produced trading stations, and the stations grew into cities. It used to be said that Arab or Persian settlers founded them; archaeology and linguistics have since corrected that: the Swahili city-states were fundamentally local Bantu societies that developed their own urban civilization through long overseas contact.'],
      rule:['这不是一个国家,而是一串各自为政的城邦——基尔瓦、蒙巴萨、拉穆、桑给巴尔、摩加迪沙彼此贸易也彼此竞争,谁也管不了谁。城内由苏丹或商人家族联合治理,权力来自商业信用与家族联姻;伊斯兰身份是通行证,让一个基尔瓦商人在从霍尔木兹到古吉拉特的港口都能被当作可信赖的交易对象。珊瑚石砌成的清真寺与宅邸是身份的可见证明。','This was not one state but a chain of self-governing city-states — Kilwa, Mombasa, Lamu, Zanzibar, Mogadishu traded with and competed against each other, none commanding the rest. Each was run by a sultan or by allied merchant families, with authority resting on commercial credit and marriage alliances. A Muslim identity worked as a passport, letting a Kilwa merchant be treated as a trustworthy counterparty in ports from Hormuz to Gujarat. Mosques and houses built of coral stone were the visible proof of standing.'],
      money:['赚的是转运的差价:内陆运来的黄金(经索法拉港出海)、象牙、龟甲与红树桩(当建材的木料),换进印度棉布、中东陶器与中国瓷器。基尔瓦因为控制了索法拉的黄金出口通道而成为最富的一座,还铸造了自己的铜币。今天在这些遗址里挖出的中国瓷片,就是这条链路曾经贯通的实物证据。','The profit was in transshipment: gold from the interior (shipped out through Sofala), ivory, tortoiseshell and mangrove poles going out; Indian cotton cloth, Middle Eastern ceramics and Chinese porcelain coming in. Kilwa became the richest of the cities because it controlled the gold route out of Sofala, and it minted its own copper coinage. The Chinese potsherds excavated at these sites today are physical proof that the chain once ran end to end.'],
      power:['这些城邦几乎不靠军事扩张,力量来自对节点的控制和对海的知识:懂季风的时序、懂缝合船的建造与修理、懂内陆各族的语言与规矩。财富靠信誉与信息积累,而不是靠占领土地——这是一种典型的商业型强大。','These cities barely expanded by force; their power came from holding the nodes and from knowledge of the sea: the timing of the monsoon, how to build and repair sewn-plank vessels, the languages and customs of inland peoples. Wealth accumulated through reputation and information rather than through taking land — strength of a distinctly commercial kind.'],
      fall:['1497年达伽马绕过好望角、次年抵达印度之后,葡萄牙人带着火炮进入印度洋,1505年攻掠基尔瓦与蒙巴萨并设立据点,把原本开放的贸易改造成需要通行证与缴税的武装垄断。衰落是多因的:城邦各自为政,无法联合抵抗;内陆的黄金流向与商路本就在变动;此后阿曼势力又与葡萄牙反复争夺这条海岸。斯瓦希里的城市并未消失,但主导权几度易手。','After Vasco da Gama rounded the Cape in 1497, the Portuguese entered the Indian Ocean with cannon, sacking Kilwa and Mombasa in 1505 and planting garrisons, converting an open trade into an armed monopoly requiring passes and payments. The decline had several causes: the city-states governed themselves separately and could not combine to resist; the inland gold flows and trade routes were already shifting; and Omani power later contested the coast with Portugal repeatedly. The Swahili cities did not vanish, but control of them changed hands more than once.'],
      legacy:['斯瓦希里语活了下来并且长大了:班图语的语法骨架加上大量阿拉伯语借词,如今是东非跨国界的通用语,使用者以亿计,也是非洲联盟的工作语言之一。基尔瓦与拉穆的遗址是世界文化遗产,遗址里的中国瓷器、波斯釉陶与印度玻璃珠共处一层,是印度洋作为一个跨大陆经济体的直接证据。','Swahili survived and grew: a Bantu grammatical frame carrying a large Arabic loan vocabulary, it is now the cross-border lingua franca of East Africa with speakers in the hundreds of millions and is one of the African Union\'s working languages. The ruins of Kilwa and Lamu are World Heritage sites, and the Chinese porcelain, Persian glazed ware and Indian glass beads found together in a single layer there are direct evidence of the Indian Ocean as a single trans-continental economy.'] },
  d:'班图人与阿拉伯-波斯商人混融出斯瓦希里语与一串商业城邦,象牙黄金输往印度与中国——郑和船队曾到访,基尔瓦遗址至今出土中国瓷器;葡萄牙人绕过好望角后渐衰。' },
{ l:'af', s:'africa', v:1, n:'大津巴布韦', k:[[1100,0],[1300,.3],[1450,0]], b:'南部非洲的石城文明,黄金与牛群的王国。',
  e:{ n:'Great Zimbabwe', b:'The stone city of the south; gold and cattle.', d:'Dry-stone walls without mortar form sub-Saharan Africa\'s largest ancient structure, a kingdom of gold and cattle trading to the Swahili coast. Colonial Europeans refused to believe Africans built it; today it names the nation.', f:{ 'Peak':'14th c. (the stone city at its height)', 'Center':'Great Zimbabwe', 'Legacy':'Largest ancient structure in sub-Saharan Africa' } },
  f:{ '鼎盛':'14世纪(石城全盛)', '中心':'大津巴布韦城', '成就':'撒南非洲最大古代建筑群' },
  qh:{ born:['高原上没有采采蝇,所以能大规模养牛','No tsetse fly on the plateau, so cattle could be kept'],
       rule:['能分配牛的人,就能聚拢人','Whoever could hand out cattle could gather people'],
       money:['一枚外来的钱币,证明它接在海上网里','One foreign coin proves it was plugged into the ocean web'],
       power:['石城本身,就是一份国力声明','The stone city was itself a statement of power'],
       fall:['三种假说并存,只有结果是确定的','Three theories stand; only the outcome is certain'],
       legacy:['殖民者不肯信这是非洲人自己盖的','Colonists refused to believe Africans had built it'] },
  q:{ born:['津巴布韦高原地势高、气候凉爽,没有致命的采采蝇,是南部非洲少见的适合大规模养牛的地方;它同时靠近金矿区,又在通往东海岸索法拉港的商道上。绍纳人先民在这里聚居,11世纪起开始用不加灰浆的干砌石墙标记等级与空间,最终形成了撒哈拉以南非洲最大的古代石构建筑群。','The Zimbabwe plateau is high and cool and free of the deadly tsetse fly, one of the few places in southern Africa suited to keeping cattle at scale; it also lies near the goldfields and on the road to the east coast port of Sofala. Ancestors of the Shona settled here, and from the eleventh century began marking rank and space with dry-stone walls laid without mortar, eventually building the largest ancient stone complex in sub-Saharan Africa.'],
      rule:['一般认为王权建立在牛群财富与宗教权威(尤其是求雨仪式)的结合之上:牛既是财富也是社会关系,聘礼、借牛、庇护都通过牛来完成,能分配牛的人就能聚拢人。石墙不设射孔与雉堞,主流看法是它们标记地位、隔出王室的仪式空间,而非用于防御。遗址出土的皂石鸟雕像可能象征王室或祖先,确切含义尚无定论。','Kingship is generally thought to have combined cattle wealth with religious authority, especially rainmaking. Cattle were both wealth and social relationship — bridewealth, loans of stock and patronage all ran through them, so whoever could distribute cattle could gather people. The walls have no loopholes or battlements, and the mainstream reading is that they marked status and enclosed royal ceremonial space rather than serving defence. The soapstone birds found at the site may represent the royal line or the ancestors; their exact meaning remains unsettled.'],
      money:['内需靠牛与农业,外汇靠黄金与象牙:高原的金经商道运到索法拉,装船进入印度洋世界,换回布匹、玻璃珠与瓷器。遗址中出土过中国瓷器残片、波斯陶器与阿拉伯玻璃珠,还有一枚基尔瓦的钱币——这些东西不会自己走过来,它们证明这座内陆石城真的接在印度洋的贸易网上。','Domestic wealth was cattle and farming; foreign earnings were gold and ivory. Plateau gold travelled the trade road to Sofala and was shipped into the Indian Ocean world in exchange for cloth, glass beads and porcelain. Excavations at the site have turned up Chinese porcelain fragments, Persian ceramics, Arab glass beads and a coin from Kilwa — objects that did not walk there by themselves, and that prove this inland stone city really was plugged into the Indian Ocean network.'],
      power:['力量来自三重叠加:能养大规模牛群的高原、能垄断黄金与象牙出口通道的位置,以及能调动大量劳动力砌起数十万块石头的组织能力。石城本身就是国力声明——能把这么多石头精确码放整齐的政权,不需要再向邻居解释自己有多强。估计全盛时有上万人在此聚居。','Power stacked in three layers: a plateau that could carry large herds, a position that let it monopolize the export route for gold and ivory, and the organizational capacity to mobilize the labour that stacked hundreds of thousands of stones. The stone city was itself a statement — a polity that could place that many stones that precisely did not need to explain its strength to its neighbours. Estimates put the population at its height in the tens of thousands.'],
      fall:['衰落尚无定论,因为几乎没有文字史料,只能靠考古推断。目前有三种主要假说并存:一是环境说,人口与牛群超过高原的承载力,木材与牧草被耗尽;二是贸易转移说,黄金产区与商路北移到赞比西河一带,由新兴的穆塔帕王国接手;三是内部分裂说,王室继承争夺导致人群另立中心。可以确定的只有结果——15世纪中叶前后,石城的人口大幅减少并最终被弃。','Why it declined is unsettled, because there are almost no written sources and everything must be inferred from archaeology. Three main hypotheses coexist. One is environmental: population and herds outgrew what the plateau could carry, exhausting timber and pasture. One is a shift in trade: the goldfields and routes moved north toward the Zambezi and were taken over by the rising Mutapa state. One is internal division: succession disputes led groups to found rival centres. Only the outcome is certain — around the middle of the fifteenth century the stone city\'s population fell sharply and it was eventually abandoned.'],
      legacy:['遗址是世界文化遗产,1980年独立的国家直接以它命名,皂石鸟的形象进了国旗与国徽。它还留下一段关于「知识如何被政治利用」的教训:殖民时代的欧洲人坚持这样的建筑不可能出自非洲人之手,把它归给腓尼基人或示巴女王,而20世纪初以来的考古工作早已确认它是本地绍纳人先民所建——这个结论在当时曾被压制,今天则是学界共识。','The site is a World Heritage site, the country that became independent in 1980 took its name directly from it, and the soapstone bird appears on the national flag and coat of arms. It also left a lesson in how knowledge gets used politically: colonial-era Europeans insisted Africans could not have built such a thing and credited Phoenicians or the Queen of Sheba, while archaeology from the early twentieth century onward established that it was built by ancestors of the local Shona — a conclusion that was suppressed at the time and is scholarly consensus today.'] },
  d:'不用灰浆干砌的巨石城墙,是撒哈拉以南非洲最大的古代建筑;以黄金与牛群立国,货通斯瓦希里海岸。殖民时代的欧洲人不肯相信这出自非洲人之手;如今它是津巴布韦的国名与国徽。' },
{ l:'af', s:'africa', v:2, n:'马里帝国', k:[[1235,0],[1324,.6],[1450,.4],[1600,0]], b:'曼萨·穆萨朝觐一路撒金;廷巴克图成为学术中心。',
  e:{ n:'Mali Empire', b:'Mansa Musa\'s gold; Timbuktu\'s manuscripts.', d:'Mansa Musa\'s pilgrimage scattered so much gold that Cairo\'s price sagged for years — often called the richest man ever; Timbuktu\'s colleges and hundreds of thousands of manuscripts prove sub-Saharan Africa was never "a continent without writing."', f:{ 'Peak':'Mansa Musa (1312–1337)', 'Center':'Niani, Timbuktu', 'Figures':'Sundiata, Mansa Musa', 'Legacy':'Timbuktu scholarship' } },
  f:{ '鼎盛':'曼萨·穆萨(1312—1337)', '中心':'尼亚尼、廷巴克图', '人物':'松迪亚塔、曼萨·穆萨', '成就':'廷巴克图经学院与手稿库' },
  qh:{ born:['一手金矿,一手粮仓,同时握住','Gold in one hand, the granary in the other'],
       rule:['去麦加朝觐,家里的传统仪式照办','It went on pilgrimage, and kept the old rites at home'],
       money:['一次朝觐撒出去的金,压了几年金价','Gold given away on one pilgrimage held prices down for years'],
       power:['真正的力量,是把几座商城连成网','The real power was linking the trading cities into a web'],
       fall:['货从海岸直接走了,老商路就不稀罕了','Goods left by the coast, and the old road lost its hold'],
       legacy:['廷巴克图留下了几十万册手稿','Timbuktu left hundreds of thousands of manuscripts'] },
  q:{ born:['加纳衰落后,尼日尔河上游的曼丁哥诸酋邦互相竞逐。据格里奥世代口传的《松迪亚塔史诗》与后世阿拉伯史家记载,松迪亚塔·凯塔约在1235年击败索索国王,建立马里。它比加纳更有利的一点是位置:既守着新兴的布雷金矿,又占着尼日尔河内陆三角洲这块粮仓——同时握住钱和粮。','After Ghana\'s decline the Mandinka chiefdoms of the upper Niger competed for primacy. According to the Sunjata epic, transmitted for generations by griots, and to later Arab historians, Sunjata Keita defeated the king of Sosso around 1235 and founded Mali. Its advantage over Ghana was location: it sat beside the newly important Bure goldfields and astride the inland Niger delta, the region\'s granary — holding the money and the food at once.'],
      rule:['曼萨(王)之下设省与属邦,各地原有的统治家族保留下来但须纳贡出兵,是一种成本较低的间接统治。文化上则是双轨并行:曼萨去麦加朝觐、宫廷任用穆斯林书记与法官,同时格里奥仍主持传统仪式、掌管口述史与氏族分工。口传的《库鲁坎富加宪章》被视为立国时的社会契约,不过其现存文本是20世纪整理成文的。','Under the mansa (king) sat provinces and tributary states whose existing ruling families were left in place but owed tribute and troops — a low-cost form of indirect rule. Culturally two tracks ran in parallel: the mansa made the pilgrimage to Mecca and the court employed Muslim secretaries and judges, while griots continued to conduct traditional ceremonies and to keep the oral history and the division of duties among clans. The orally transmitted Kurukan Fuga charter is regarded as the founding social contract, though the text we have was written down only in the twentieth century.'],
      money:['三条腿撑起财政:黄金的出口税、盐(尤其是撒哈拉深处塔加扎盐矿)的转运税,以及尼日尔河内陆三角洲的稻粟农业与渔业。1324年曼萨·穆萨朝觐途中大量施舍与消费黄金,据十四世纪的阿拉伯史家乌马里记载(他成书于此事十余年后),当地金价此后数年不振——所谓「史上最富之人」是现代媒体的排行说法,不是史学结论,但这段记载确实说明马里黄金的分量。','Three legs carried the treasury: export duty on gold, transit duty on salt (above all from the Taghaza mines deep in the Sahara), and the rice and millet farming and fishing of the inland Niger delta. When Mansa Musa made the pilgrimage in 1324 he gave away and spent gold on a scale that, according to contemporary accounts from Cairo, left the local gold price depressed for several years. Calling him the richest person in history is a modern media ranking rather than a historical judgment, but the account does show how much Malian gold weighed.'],
      power:['军事上靠常备军与从北非进口马匹组建的骑兵,加上尼日尔河上的独木舟船队运兵运粮。但马里真正的力量在于把商城连成网:廷巴克图、杰内、加奥、瓦拉塔各司其职,商队、学者与朝觐者沿同一条路走动,鼎盛时控制的疆域约一百一十万平方公里。','Militarily it relied on a standing army and cavalry mounted on horses imported from North Africa, plus canoe fleets on the Niger to move troops and supplies. But Mali\'s real strength was linking its trading towns into a network: Timbuktu, Djenné, Gao and Walata each played a role, and caravans, scholars and pilgrims moved along the same roads. At its height it controlled some 1.1 million square kilometres.'],
      fall:['解体是多因、长期的:14世纪后期王位继承屡起争斗,中央权威被削弱;1433年图阿雷格人夺走廷巴克图;东部属邦桑海不但独立,还反过来蚕食马里的核心区;南方莫西人不断袭扰。更深一层的变化在海上——欧洲人开辟了沿西非海岸的航线,黄金与象牙开始直接从海岸出口,穿越撒哈拉的老商路失去了不可替代性。16世纪马里退缩为地方王国,17世纪彻底解体。','Disintegration was long and multi-causal. Succession disputes recurred from the late fourteenth century and eroded central authority; the Tuareg took Timbuktu in 1433; the eastern vassal of Songhai not only broke away but began eating into Mali\'s core; and the Mossi raided from the south. A deeper change was happening at sea: as Europeans opened routes along the West African coast, gold and ivory began leaving directly from the shore, and the old trans-Saharan roads lost their monopoly. By the sixteenth century Mali had shrunk to a regional kingdom, and it dissolved entirely in the seventeenth.'],
      legacy:['廷巴克图的桑科雷等经学院与保存至今的数十万册手稿,是西非拥有深厚书写传统的直接证据(近年因战乱,大批手稿被抢救转移到巴马科)。《松迪亚塔史诗》与格里奥的口述史传统至今仍在传唱,是非洲口头文学的高峰之一;杰内大清真寺代表的泥砖建筑成了萨赫勒地区的标志性风格。1375年的加泰罗尼亚地图集上画着一位手持金块的西非君主,是中世纪欧洲地图对西非最著名的一次描绘。','The madrasas of Timbuktu, such as Sankore, and the hundreds of thousands of manuscripts still surviving are direct evidence of a deep West African tradition of writing (in recent years many were evacuated to Bamako to escape conflict). The Sunjata epic and the griots\' oral history are still performed and count among the summits of African oral literature, while the mud-brick architecture epitomized by the Great Mosque of Djenné became the signature Sahelian style. The Catalan Atlas of 1375 shows a West African ruler holding a gold nugget, the best-known depiction of West Africa on any medieval European map.'] },
  d:'曼萨·穆萨朝觐麦加沿途撒金,开罗金价数年不振,后世常称其为史上最富之人;廷巴克图的大学与数十万册手稿证明,撒哈拉以南绝非"没有文字的大陆"。' },
{ l:'af', s:'africa', v:0, n:'阿散蒂', k:[[1670,0],[1701,.2],[1820,.35],[1874,.2],[1902,0]], b:'黄金与金凳:西非内陆强权,与英国打了五次仗。',
  e:{ n:'Asante', b:'Gold and the golden stool: an inland West African power that fought Britain five times.', d:'By tradition a golden stool descended from the sky, and Osei Tutu used it to bind the Akan states into one, defeating their overlord Denkyira in 1701. Gold bought firearms, and in 1824 an Asante army killed a British governor in the field. After five Anglo-Asante wars the kingdom was annexed as a colony in 1902 — but the stool itself was never taken: when the governor announced in 1900 that he would sit on it, the sixty-year-old queen mother Yaa Asantewaa answered that there would be war.', f:{ 'Peak':'early 19th c.', 'Center':'Kumasi', 'Figures':'Osei Tutu, Yaa Asantewaa', 'Legacy':'The golden stool, kente cloth, gold weights' } },
  f:{ '鼎盛':'19世纪初', '中心':'库马西', '人物':'奥赛·图图、雅雅·阿散蒂瓦', '成就':'金凳、阿散蒂织锦、金衡器' },
  qh:{ born:['一张没人能坐的凳子,成了统一的凭据','A stool no one may sit on became the proof of unity'],
       rule:['王位走母系,王太后能提名也能否决','Succession ran through the mother; the queen mother could veto'],
       money:['称金的砝码,做成了谚语和动物','The weights for gold were cast as proverbs and animals'],
       power:['1824年,它阵斩了一位英国总督','In 1824 it killed a British governor in the field'],
       fall:['打了五次,差距一次比一次大','Five wars, and the gap widened each time'],
       legacy:['那张金凳,英国人始终没拿到','The golden stool was never taken'] },
  q:{ born:['西非森林带的阿肯人各邦长期臣服于登基拉,要向它纳贡。17世纪末奥赛·图图与祭司奥科姆福·阿诺基把分散的部族联合起来:相传一张金凳自天而降落在奥赛·图图膝上,被宣布为全体阿散蒂人灵魂的居所——它不是王座,没有人可以坐,却成了统一的凭据。1701年联军击败登基拉,阿散蒂由附庸变成主人。','The Akan states of the West African forest belt had long paid tribute to Denkyira. At the end of the seventeenth century Osei Tutu and the priest Okomfo Anokye welded the scattered clans together: by tradition a golden stool descended from the sky onto Osei Tutu\'s knees and was declared the dwelling place of the soul of the whole Asante people — not a throne, and no one may sit on it, but the token of their unity. In 1701 the allied forces beat Denkyira, and Asante went from vassal to master.'],
      rule:['结构是联邦式的:核心各邦保留自己的首领与军队,共同承认库马西的阿散蒂赫内(国王)为共主,重大事务由长老会议决定,国王并非独断。被征服的外围地区则派驻官员征贡。王位继承走母系:继承人从王太后所属的家族中选出,王太后有提名权与否决权——1900年那场对英战争,就是由埃吉苏的王太后雅雅·阿散蒂瓦号召发动的。','The structure was federal: the core states kept their own chiefs and levies while acknowledging the Asantehene at Kumasi as paramount, and major decisions went through a council of elders rather than the king alone. Conquered outlying districts were administered by appointed officials who collected tribute. Succession ran through the female line: the heir was chosen from the queen mother\'s family, and she held both the right to nominate and the right to veto — the war of 1900 against the British was raised by Yaa Asantewaa, queen mother of Ejisu.'],
      money:['两样东西:黄金与人。境内的金矿与河砂金支撑了整个国家,阿散蒂人发展出一套精细的黄铜砝码用来称金,砝码本身做成谚语与动物造型,是今天最有名的西非工艺品之一。同时它也是大西洋奴隶贸易的主要供应方之一,把战争俘虏卖到海岸换取火器与商品——这段历史在今天的加纳仍是公开讨论的话题。1807年英国禁止奴隶贸易后,它转向出口棕榈油与可乐果。','Two things: gold and people. Mines and river gold underwrote the state, and the Asante developed a precise system of brass weights for measuring it, cast as proverbs and animals and now among the best-known West African craft objects. It was also one of the main suppliers to the Atlantic slave trade, selling war captives at the coast for firearms and goods — a history still openly discussed in Ghana today. After Britain outlawed the trade in 1807 it turned to exporting palm oil and kola nuts.'],
      power:['靠火器与组织:用黄金从海岸的欧洲商站换来枪支,建立起纪律严整的步兵,战术上以中军、两翼、后备的阵形包抄,规模可达数万人。境内修筑了以库马西为中心的道路网,便于快速调兵。1824年在恩桑曼库战役中击败英军并阵斩总督查尔斯·麦卡锡,这是英国在西非最严重的败绩之一。','Firearms and organisation: gold bought guns from the European posts on the coast, funding a disciplined infantry that fought in a formation of centre, two wings and reserve designed to envelop, and could field tens of thousands. A road network centred on Kumasi allowed troops to be moved quickly. At Nsamankow in 1824 an Asante army defeated a British force and killed the governor, Charles MacCarthy — among the worst British reverses in West Africa.'],
      fall:['与英国的五次战争贯穿19世纪(1823—31、1863—64、1873—74、1895—96、1900)。前期互有胜负,但双方的技术差距在拉大:1874年英军带着后膛枪与火箭攻入库马西并将其焚毁,阿散蒂被迫割地赔款,属邦纷纷脱离。1896年英国以国王拒绝接受保护国地位为由再度出兵,流放国王普雷姆佩一世。1900年总督要求交出金凳并坐上去,王太后雅雅·阿散蒂瓦号召起兵,史称金凳之战,失败后被流放塞舌尔。1902年阿散蒂被并为英国殖民地。','Five wars with Britain ran through the nineteenth century. Early on the results were mixed, but the technological gap widened: in 1874 a British force with breech-loading rifles and rockets entered Kumasi and burned it, forcing cession of territory and an indemnity, and the tributary states fell away. In 1896 Britain moved again on the grounds that the king had refused protectorate status, and exiled King Prempeh I. In 1900 the governor demanded the golden stool and announced he would sit on it; the queen mother Yaa Asantewaa raised a revolt, known as the War of the Golden Stool, and was exiled to the Seychelles after its defeat. In 1902 Asante was annexed as a British colony.'],
      legacy:['金凳从未被英国人拿到——阿散蒂人把它藏了起来,1920年才被偶然发现,今天仍由阿散蒂王室保管,只在重大场合出现。王位本身也延续至今:1924年普雷姆佩一世获准回国,阿散蒂赫内在加纳作为传统君主继续存在。肯特织锦、黄金砝码与阿丁克拉符号成为加纳国家认同的一部分,雅雅·阿散蒂瓦则是西非最著名的女性抵抗象征之一。','The golden stool never fell into British hands — the Asante hid it, it was found by accident only in 1920, and it remains in the keeping of the royal house, brought out only on great occasions. The kingship also survives: Prempeh I was allowed home in 1924, and the Asantehene continues as a traditional ruler within Ghana. Kente cloth, the gold weights and the Adinkra symbols became part of Ghana\'s national identity, and Yaa Asantewaa is among the best-known symbols of women\'s resistance in West Africa.'] },
  d:'相传金凳自天而降,奥赛·图图借它把阿肯诸邦联成一体,1701年击败宗主登基拉;以黄金换火器,1824年阵斩英国总督。五次英阿战争后于1902年被并为殖民地,但金凳始终没被英国人拿到——1900年总督要坐上去,六十岁的王太后雅雅·阿散蒂瓦回答:那就打。' },
{ l:'af', s:'africa', v:1, n:'刚果王国', k:[[1390,0],[1490,.3],[1600,.25],[1700,.15],[1857,0]], b:'中部非洲的基督教王国,最早与欧洲君主平等通信的非洲政权。',
  e:{ n:'Kingdom of Kongo', w:'Kingdom of Kongo', b:'A Christian kingdom in central Africa — the first to correspond with European monarchs as an equal.', d:'When Portuguese ships reached the mouth of the Congo in 1483, the king sent envoys to Lisbon on his own initiative. His son Afonso I was baptized, learned Latin, and exchanged letters with the king of Portugal as "brother" for decades — that correspondence is among the earliest modern records written by an African in his own voice. But the same ships brought the slave trade. Afonso spent his last years writing letter after letter begging Lisbon to stop the taking of his people; none was answered. Hollowed out, the kingdom broke apart after its defeat at Mbwila in 1665.', f:{ 'Peak':'late 15th – early 16th c.', 'Center':'Mbanza Kongo', 'Figures':'Afonso I (Nzinga Mbemba)', 'Legacy':'State letters to Europe; written Kikongo' } },
  f:{ '鼎盛':'15世纪末—16世纪初', '中心':'姆班扎刚果', '人物':'阿方索一世(恩津加·姆本巴)', '成就':'与葡萄牙的往来国书、书面刚果语' },
  qh:{ born:['都城建在高地,既守得住又看得远','The capital sat high, easy to hold and to watch from'],
       rule:['国王是选出来的,省督可调可撤','The king was elected, and governors could be moved'],
       money:['谁控制货币发行,谁就控制经济','Whoever controls the issue controls the economy'],
       power:['忠诚是可以被购买、也需要续费的','Loyalty could be bought, and had to be renewed'],
       fall:['贵族绕开国王做生意,再分配就垮了','Nobles traded past the king, and redistribution collapsed'],
       legacy:['一位非洲国王的信,原件保存到今天','Letters from an African king survive in the original'] },
  q:{ born:['刚果河以南是一片农业条件不错的高地与河谷,能养活密集的人口。据传说,14世纪末卢肯尼·卢阿·尼米统一了周边诸酋邦,定都姆班扎刚果——这座都城选在高地上,既易守,又便于俯瞰和调度四方。到15世纪末葡萄牙船只抵达时,它已经是中部非洲组织程度最高的政权之一。','South of the Congo River lies highland and valley country good enough for farming to support a dense population. Tradition holds that Lukeni lua Nimi united the surrounding chiefdoms at the end of the fourteenth century and made his capital at Mbanza Kongo — a site on high ground, easy to defend and convenient for overseeing and directing the surrounding provinces. By the time Portuguese ships arrived at the end of the fifteenth century it was among the most highly organized states in Central Africa.'],
      rule:['刚果的政治设计相当精巧:国王不是父死子继,而是由王室各支系的选举团推举——这让有能力的人有机会上位,也让每次交接都可能变成竞争。六个省的总督由国王任命,可调可撤,而非世袭领主,中央因此保有实权。1491年国王受洗后,基督教被接入这套机器:教堂、识字的书吏与欧洲式头衔成了王权的新装备。','Kongo\'s political design was ingenious. The king was not succeeded by his son but chosen by an electoral council drawn from the branches of the royal house — which gave able men a chance and also made every succession a contest. The governors of the six provinces were appointed by the king and could be moved or removed rather than holding hereditary fiefs, so the centre kept real power. After the king was baptized in 1491 Christianity was plugged into this machine: churches, literate secretaries and European-style titles became new equipment of kingship.'],
      money:['货币是产自罗安达岛的 nzimbu 贝壳,采集权由王室垄断——谁控制发行,谁就控制经济,这一点刚果人做得很清楚。此外还有棕榈布充当通货,以及农业贡赋、铜、盐与象牙。与葡萄牙通商后,进口的布匹、酒与火器成为国王赏赐扈从的新资源;而正是这条进口通道,后来成了王国的软肋。','The currency was the nzimbu shell from Luanda island, and the right to harvest it was a royal monopoly — whoever controls issue controls the economy, a point the Kongo understood well. Palm cloth also served as money, alongside agricultural tribute, copper, salt and ivory. Once trade with Portugal opened, imported cloth, wine and firearms became a new resource for the king to distribute to his followers — and that import channel would become the kingdom\'s weak point.'],
      power:['国王的力量建立在再分配上:垄断货币与进口奢侈品,再把它们分给忠诚的贵族与省督,忠诚由此可以被购买和续费。省督可调动、不世袭的制度也减少了地方割据。有葡萄牙火枪手与火器加持的时期,刚果军队在区域内有明显优势。','The king\'s power rested on redistribution: monopolize the currency and the imported luxuries, then hand them out to loyal nobles and governors, so that loyalty could be bought and renewed. Governors who could be transferred and did not inherit their posts also limited regional entrenchment. In the periods when Portuguese musketeers and firearms were on hand, Kongo armies held a clear regional edge.'],
      fall:['王国的衰亡与大西洋奴隶贸易深度绑定,机制是结构性的:欧洲商人最想要的只有一种「商品」——被掳掠的人,而愿意用枪炮与布匹交换。于是贵族与省督可以绕开王室,直接与葡萄牙商人交易,获得独立的财源与武力,国王赖以维系忠诚的再分配垄断被瓦解;边境掳掠常态化,人口与社会秩序同时受损。阿方索一世1526年致葡萄牙国王的信要求停止在其境内掳人,原件保存至今,但没有换来改变。1568年外敌入侵后靠葡萄牙援军复国,代价是更深的依附;1665年姆布维拉战役国王战死于葡萄牙军队之手,此后王位争夺与内战不断,王国名义存续而实权分散,1857年与葡萄牙签订附庸条约。','The kingdom\'s decline was bound up with the Atlantic slave trade, and the mechanism was structural: the one commodity European merchants most wanted was captured people, and they would pay in guns and cloth. Nobles and provincial governors could therefore bypass the crown and deal with Portuguese traders directly, gaining independent revenue and independent force, which dissolved the redistribution monopoly the king depended on for loyalty. Raiding on the frontiers became routine, damaging both population and social order. Afonso I\'s 1526 letter to the king of Portugal demanding an end to the seizure of people in his territory survives in the original, but changed nothing. After an invasion in 1568 the kingdom was restored with Portuguese military help, at the cost of deeper dependence. In 1665 the king was killed fighting Portuguese forces at Mbwila, and repeated succession wars followed; the kingdom continued in name while real power fragmented, and in 1857 it signed a treaty of vassalage with Portugal.'],
      legacy:['阿方索一世的书信与刚果宫廷的文书,是非洲统治者以本方立场留下的最早一批近代文献,今天研究这段历史绕不开它们。刚果的基督教发展出鲜明的本土形态,1704年由基姆帕·维塔发起的宗教运动主张基督与使徒是刚果人、号召重建被战乱撕碎的王国,是非洲基督教本土化最早的重大事件之一。而被强行贩运到美洲的刚果地区人口极多,他们的语言、音乐与宗教在巴西、古巴与海地留下了清晰可辨的痕迹。','Afonso I\'s letters and the papers of the Kongo court are among the earliest modern documents written by Africans from their own point of view, and no study of this period can go around them. Kongo Christianity developed a distinctly local form: the religious movement launched by Kimpa Vita in 1704, which held that Christ and the apostles were Kongolese and called for rebuilding a kingdom torn apart by war, was one of the earliest major episodes of Christianity being made African. And because so many people from the Kongo region were carried by force to the Americas, their languages, music and religion left clearly traceable marks in Brazil, Cuba and Haiti.'] },
  d:'1483年葡萄牙船抵达刚果河口,国王主动遣使赴里斯本学习。其子阿方索一世受洗、通拉丁文,与葡萄牙国王以"兄弟"相称通信数十年——那批信件是非洲人用自己的视角写下的最早近代史料之一。但同一批船也带来了奴隶贸易:阿方索晚年一封封写信恳求葡王停止在他境内掳人,全部石沉大海。王国被掏空,1665年姆布维拉一战后分崩离析。' },
{ l:'af', s:'africa', v:0, n:'桑海帝国', k:[[1464,0],[1520,.5],[1591,0]], b:'西非最大帝国,亡于摩洛哥火枪远征。',
  e:{ n:'Songhai Empire', b:'West Africa\'s largest empire, felled by muskets.', d:'Successor to Mali and West Africa\'s largest empire, with provinces and a standing army; in 1591 a Moroccan force crossed the Sahara with firearms and broke it in one battle — a brutal footnote to the military revolution.', f:{ 'Peak':'Askia Muhammad (1493–1528)', 'Center':'Gao', 'Figures':'Sonni Ali, Askia Muhammad', 'Legacy':'Provincial administration' } },
  f:{ '鼎盛':'阿斯基亚·穆罕默德(1493—1528)', '中心':'加奥', '人物':'桑尼·阿里、阿斯基亚·穆罕默德', '成就':'行省与常备军制' },
  qh:{ born:['它不是沿沙漠打仗,是沿着河打仗','It fought along the river, not along the desert'],
       rule:['从一支军队,变成了一台行政机器','From an army into an administrative machine'],
       money:['模板照抄前两代,但做得更细','It copied the earlier template, and ran it finer'],
       power:['一支河上船队,能把军队送到任何一点','A river fleet could put the army anywhere on the water'],
       fall:['不是一场火枪战定的输赢','It was not one battle of muskets that decided it'],
       legacy:['两部编年史,是本地学者自己写的','Two chronicles, written by local scholars themselves'] },
  q:{ born:['加奥的桑海人原本是马里的属邦,居住在尼日尔河中游,以渔业和农业为生。马里的中央权威衰弱后,桑尼·阿里于1464年即位并转守为攻,利用尼日尔河作为运兵通道快速机动,1468年取廷巴克图、1473年取杰内——他不是沿着沙漠打仗,而是沿着河打仗,这是桑海比前两代帝国走得更远的原因之一。','The Songhai of Gao had been a vassal of Mali, living along the middle Niger by fishing and farming. As Mali\'s central authority weakened, Sunni Ali came to the throne in 1464 and went on the offensive, using the Niger as a troop corridor for rapid movement: Timbuktu fell in 1468 and Djenné in 1473. He fought along the river rather than along the desert, one reason Songhai reached further than either empire before it.'],
      rule:['两位创业者路线不同。桑尼·阿里靠军功与本地传统信仰立国,与廷巴克图的伊斯兰学者关系紧张。1493年阿斯基亚·穆罕默德夺权后改走伊斯兰正统路线:亲赴麦加朝觐取得宗教名分,设立管财政、农业、水军等事务的中央部门,任命省督、建立常备军与职业官僚层——从一支征服者的军队变成了一个有行政机器的帝国。','The two founders took different lines. Sunni Ali built his state on military success and the local traditional religion, and his relations with the Muslim scholars of Timbuktu were tense. After seizing power in 1493, Askia Muhammad turned to Islamic orthodoxy: he made the pilgrimage to Mecca to acquire religious standing, created central departments for finance, agriculture and the river fleet, appointed provincial governors, and built a standing army and a professional bureaucracy — turning an army of conquest into an empire with an administrative machine.'],
      money:['财政沿用了前两代的模板并做得更细:黄金的过境税、塔加扎等撒哈拉盐矿的盐,以及尼日尔河沿岸的农渔业;廷巴克图、杰内、加奥、瓦拉塔各大商城的市场税是稳定现金流。同时王室经营大型农庄供养军队与宫廷,农庄劳作大量依靠被奴役者——这是当时西非国家经济的一部分,如实记下。鼎盛时疆域估计从八十万到一百四十万平方公里不等。','The fiscal template came from its predecessors and was refined: transit duty on gold, salt from Saharan mines such as Taghaza, and farming and fishing along the Niger, with market taxes in the great trading towns of Timbuktu, Djenné, Gao and Walata providing steady cash. The crown also ran large estates to supply the army and court, and the labour on them depended heavily on enslaved people — part of the economy of West African states at the time, recorded here as it was. Estimates of its extent at the height run somewhere between 0.8 and 1.4 million square kilometres.'],
      power:['力量的三根支柱:尼日尔河船队(可以在旱季之外把军队快速投送到上下游任何一点)、职业常备军与骑兵,以及对盐矿和商城的连锁控制。桑海把西非的贸易体系纳入了比前代更统一的行政管理,这是它比加纳、马里更进一步的地方。','Three pillars: the Niger fleet, which could move the army quickly to any point up or down the river outside the dry season; a professional standing army with cavalry; and interlocking control of the salt mines and the trading towns. Songhai brought the West African trading system under a more unified administration than its predecessors had managed, which is where it went further than Ghana or Mali.'],
      fall:['崩溃不是「火枪一战定输赢」这么简单。阿斯基亚之后半个多世纪王位争夺频繁,1588年的内战严重削弱了国力;摩洛哥萨阿德王朝觊觎塔加扎盐矿与黄金源头,于1590至1591年派出约四千人的远征队穿越撒哈拉,其中包括火枪手。1591年通迪比一战,人数占优但只有冷兵器的桑海主力溃败。但摩洛哥人也无力真正统治这片土地,帝国碎成互相攻伐的小邦,商路与学术随之衰败,廷巴克图的学者(包括艾哈迈德·巴巴)被押往马拉喀什。同一时期,大西洋航线正把西非贸易的重心从沙漠拉向海岸。','The collapse was not simply a matter of muskets deciding one battle. For more than half a century after Askia Muhammad, succession fights recurred, and the civil war of 1588 badly weakened the state. The Saadi dynasty of Morocco wanted the Taghaza salt mines and the sources of gold, and in 1590–91 sent an expedition of about four thousand men, musketeers among them, across the Sahara. At Tondibi in 1591 the Songhai main force, more numerous but armed only with hand weapons, broke. Yet Morocco could not actually govern the land either: the empire fragmented into small warring states, the trade routes and the schools declined with them, and Timbuktu scholars including Ahmad Baba were carried off to Marrakesh. In the same decades, Atlantic shipping was pulling the centre of West African trade from the desert toward the coast.'],
      legacy:['通迪比之战常被引作火器改变军事格局的例子,但它只是当时众多因素之一,不宜当作单一解释。桑海留下的两部17世纪阿拉伯文编年史——《塔里赫·苏丹》与《塔里赫·法塔什》——由本地学者撰写,是今天研究西非史最重要的文献之一;廷巴克图的手稿传统与尼日尔河沿岸的城市网络也延续了下来。桑海语至今仍在尼日尔河中游一带使用。','Tondibi is often cited as an example of firearms changing the military balance, but it was one factor among many and should not be made the single explanation. Songhai left two seventeenth-century Arabic chronicles — the Tarikh al-Sudan and the Tarikh al-Fattash — written by local scholars, and they remain among the most important sources for West African history. The manuscript tradition of Timbuktu and the network of towns along the Niger continued as well, and the Songhai language is still spoken along the middle Niger today.'] },
  d:'继马里而起的西非最大帝国,行省与常备军制齐备;1591年摩洛哥远征军带着火枪穿越撒哈拉,冷兵器的桑海一战而溃——旧世界军事革命最残酷的注脚之一。' },
{ l:'af', s:'west', v:0, n:'欧洲殖民非洲', k:[[1650,0],[1800,.15],[1884,.4],[1914,.7],[1957,.5],[1975,0]], b:'三角贸易三百年后,柏林会议用直尺瓜分全洲。',
  e:{ n:'Colonial Africa', w:'Scramble for Africa', b:'Three slave-trade centuries, then the ruler-drawn carve-up.', d:'After three centuries of the slave trade took over ten million people, the 1884 Berlin Conference carved the continent with rulers — only Ethiopia and Liberia escaped. Under a century of rule redrew borders, languages and economies whose fault lines still run today.', f:{ 'Partition begins':'Berlin Conference 1884', 'Peak':'1914 (only two African states independent)', 'Center':'Cape Town, Algiers, Dakar', 'Figures':'Leopold II, Cecil Rhodes, Yaa Asantewaa, Sol Plaatje', 'Keywords':'Triangular trade, ruler borders' } },
  f:{ '瓜分起点':'1884年柏林会议', '鼎盛':'1914年(全洲仅两国独立)', '中心':'开普敦、阿尔及尔、达喀尔', '人物':'利奥波德二世、塞西尔·罗兹、雅雅·阿散蒂瓦、索尔·普拉杰', '关键词':'三角贸易、直尺边界' },
  qh:{ born:['奎宁、轮船和后膛枪,同时改变了平衡','Quinine, steamships and breech-loaders changed the balance at once'],
       rule:['原本流动的身份,被固化成了「部落」','Fluid identities were frozen, and sometimes invented, as tribes'],
       money:['铁路只通港口,不连内部市场','The railways ran to ports, not between markets'],
       power:['殖民军里,绝大部分士兵是非洲人','Most soldiers in the colonial armies were Africans'],
       fall:['几十万当过兵的人回来,带回了期待','Hundreds of thousands came home from war with expectations'],
       legacy:['欧洲语言,至今还是多数国家的官方语','European languages are still the official ones in most countries'] },
  q:{ born:['欧洲人从15世纪起就在西非沿海设商站,但四百年里始终进不去内陆:疟疾与黄热病让欧洲人的死亡率极高,非洲各政权也有能力抵抗。19世纪三件事同时改变了这个平衡——奎宁作为预防药大幅降低了欧洲人的死亡率,蒸汽轮船与后膛枪拉开了技术差距,工业化对棕榈油、橡胶、铜与棉花的需求急剧上升。1884至1885年的柏林会议为列强定下「有效占领」的规则,瓜分随即加速。','Europeans had kept trading posts on the West African coast since the fifteenth century, but for four hundred years they could not get inland: malaria and yellow fever killed them at appalling rates, and African states were able to resist. In the nineteenth century three things shifted the balance at once — quinine used prophylactically cut European mortality sharply, steamships and breech-loading rifles opened a technological gap, and industrial demand for palm oil, rubber, copper and cotton rose steeply. The Berlin Conference of 1884–85 set the powers\' rule of \'effective occupation\', and the partition accelerated from there.'],
      rule:['主要有两种模式。法国式直接统治派本土官员下去,推行同化政策与法语教育;英国式间接统治保留酋长做代理人,成本低,但也把原本流动的社会身份固化甚至发明成了固定的「部落」。两者的共同点是:行政边界按谈判桌上的方便划定而非依照当地社会,被统治者没有政治参与权,而武力与法律始终掌握在外来者手里。','There were two main models. French direct rule sent metropolitan officials down the chain and pursued assimilation and French-language schooling. British indirect rule kept chiefs on as intermediaries — cheaper, but it also hardened, and in places invented, fixed \'tribal\' identities out of what had been fluid social categories. What they shared: administrative boundaries drawn for convenience at the negotiating table rather than according to local society, no political participation for the governed, and force and law kept in outside hands throughout.'],
      money:['殖民经济是榨取型的:各殖民地被安排专产一两种出口作物或矿产(可可、花生、棕榈油、铜、金、钻石),铁路从矿区和产区直通港口,几乎不连接内部市场——这套布局是为运出去设计的,不是为本地流通设计的。人头税与小屋税迫使农民必须换取现金,从而进入种植园与矿场务工;土地征收与强制劳动普遍存在,刚果自由邦(利奥波德二世的私人领地)的橡胶配额制度造成了大规模死亡与残害,是记录最充分的殖民暴行之一(死亡人数的学界估计差异很大)。','The colonial economy was extractive: each colony was steered into producing one or two export crops or minerals — cocoa, groundnuts, palm oil, copper, gold, diamonds — and railways ran from the mines and growing areas straight to the ports, barely connecting internal markets. The layout was designed for shipping out, not for circulation within. Head taxes and hut taxes forced farmers to obtain cash and therefore to work on plantations and in mines; land expropriation and forced labour were widespread, and the rubber quota system in the Congo Free State caused death and mutilation on a large scale, one of the best-documented colonial atrocities (scholarly estimates of the death toll vary widely).'],
      power:['征服靠的是技术与组织的差距(连发与自动武器、电报、铁路、常备军),以及条约——不少「保护条约」的当地签署者并不了解其在欧洲法律中的含义。有一点常被忽略:欧洲人并不是靠欧洲士兵打下非洲的,殖民军的绝大部分兵员是非洲人,西非边防军与塞内加尔步兵都在殖民征服与两次世界大战中被大量使用。分而治之同样是核心手段。','Conquest rested on gaps in technology and organization — repeating and automatic weapons, the telegraph, railways, standing armies — and on treaties, many of whose African signatories did not understand what the documents meant in European law. One point is often missed: Europeans did not take Africa with European soldiers. The overwhelming majority of colonial troops were African, and forces such as the West African Frontier Force and the Senegalese tirailleurs were used heavily in the conquest and in both world wars. Divide and rule was equally central.'],
      fall:['殖民统治的终结是多因叠加。两次世界大战耗尽了宗主国的财力与威望,几十万在海外作战的非洲士兵带回了政治期待;《大西洋宪章》与联合国的民族自决话语让殖民统治在国际上越来越难辩护;城市化与教育培养出新的政治阶层,工会、报纸与政党把诉求组织成大规模运动(加纳恩克鲁玛的「正面行动」是典型);1952年起的肯尼亚茅茅起义、1954至1962年的阿尔及利亚战争等武装抵抗则把统治成本抬到难以承受。1960年一年之内有十七个国家独立,1975年葡萄牙的非洲殖民地独立,此后还有津巴布韦(1980)与纳米比亚(1990),1994年南非结束种族隔离。','The end of colonial rule came from several causes at once. Two world wars drained the metropolitan powers of money and prestige, and hundreds of thousands of African soldiers who fought overseas came home with political expectations. The Atlantic Charter and the United Nations\' language of self-determination made colonial rule steadily harder to defend internationally. Urbanization and education produced a new political class, and unions, newspapers and parties organized demands into mass movements — Nkrumah\'s \'Positive Action\' in Ghana is the classic case. Armed resistance, from the Mau Mau uprising in Kenya from 1952 to the Algerian war of 1954–62, pushed the cost of holding on beyond what was bearable. Seventeen countries became independent in 1960 alone, Portugal\'s African colonies became independent in 1975, with Zimbabwe following in 1980 and Namibia in 1990, and South Africa ended apartheid in 1994.'],
      legacy:['殖民时期划下的直线边界把同一族群切开、又把彼此陌生的群体放进同一个国家,主流看法认为这是后来许多冲突的结构性背景之一(但学界也强调不能把一切都归因于边界)。欧洲语言成为多数非洲国家的官方语言与教育媒介,法律与行政体系也保留了殖民底子;以出口原料为轴心的经济结构长期难以转型。同时,非洲的独立浪潮反过来推动了国际法上的民族自决原则,并催生了不结盟运动与后来的非洲联盟。','The straight borders drawn in the colonial period cut through peoples and placed strangers inside single states, which the mainstream view treats as one structural background to many later conflicts — though scholars also stress that not everything can be attributed to borders. European languages became the official languages and the medium of education in most African countries, and legal and administrative systems retain a colonial base. Economies built around exporting raw materials have proved hard to restructure. At the same time, Africa\'s wave of independence pushed self-determination forward in international law and gave rise to the Non-Aligned Movement and eventually the African Union.'] },
  d:'三角贸易三百年掠走上千万人口之后,1884年柏林会议用直尺瓜分全洲,仅埃塞俄比亚与利比里亚幸免;殖民统治不足百年,但它重划的边界、语言与经济结构,至今仍是非洲诸多冲突的底层原因。' },
{ l:'af', s:'africa', v:0, n:'现代非洲', k:[[1957,0],[1994,.35],[2025,.45]], b:'去殖民化后五十余国;世界上人口最年轻的大陆。',
  e:{ n:'Modern Africa', w:'Africa', b:'Fifty-plus states; the world\'s youngest continent.', d:'Ghana led in 1957 and seventeen states followed in 1960 alone; after Cold War proxy wars and adjustment pains, several of this century\'s fastest growers are African. Median age under 20 — the next demographic dividend lives here.', f:{ 'Independence wave':'"Year of Africa" 1960', 'Peak':'after 2000', 'Center':'Lagos, Nairobi, Johannesburg', 'Figures':'Nkrumah, Mandela' } },
  f:{ '独立浪潮':'1960"非洲年"', '鼎盛':'2000年后(人口与经济双增长)', '中心':'拉各斯、内罗毕、约翰内斯堡', '人物':'恩克鲁玛、曼德拉' },
  qh:{ born:['1960年一年里,十七个国家独立','In the single year 1960, seventeen countries became independent'],
       rule:['非盟总部的选址,本身就是一句话','Where the African Union sits is itself a statement'],
       money:['移动支付跳过了固定电话这一步','Mobile payment skipped the landline stage entirely'],
       power:['全世界最年轻的大陆,中位年龄不到二十','The youngest continent on earth, median age under twenty'],
       fall:['1994年,两件方向完全相反的事','In 1994, two things happened in opposite directions'],
       legacy:['全世界三分之一的语言,在这块大陆上','A third of all human languages are on this continent'] },
  q:{ born:['1884至1885年的柏林会议上,欧洲列强定下「有效占领」的规则,此后几十年里按自己的方便把整个非洲分完,边界多为直线,把同一族群切开、把敌对族群圈进同一国。1957年加纳成为撒哈拉以南第一个独立的殖民地(北非的埃及、利比亚、苏丹、摩洛哥、突尼斯更早),1960年一年之内有十七国独立,史称「非洲年」;到1970年代大陆基本完成去殖民化,南非的种族隔离制度则延续到1994年。','At the Berlin Conference of 1884–85 the European powers divided the continent for their own convenience, and the borders they drew were largely straight lines that cut through peoples and enclosed rivals in one state. Ghana was the first colony south of the Sahara to become independent, in 1957, seventeen countries followed in 1960 alone — remembered as the Year of Africa — and decolonisation was largely complete by the 1970s, though apartheid in South Africa lasted until 1994.'],
      rule:['五十四个国家,政体与处境差别极大。独立初期多国经历一党制或军人执政,1990年代后多党选举普遍推行,但巩固程度不一。非洲联盟(2002年由非洲统一组织改组)提供了区域框架,总部设在亚的斯亚贝巴——那是非洲仅有的两个未被长期殖民的国家之一(另一个是利比里亚),这个选址本身有意义。','Fifty-four countries, differing widely in system and circumstance. Many began independence under one-party or military rule; multiparty elections spread from the 1990s, though how firmly they have taken hold varies. The African Union, reorganised from the Organisation of African Unity in 2002, provides a continental frame, with its seat in Addis Ababa — one of only two African countries never lastingly colonised, the other being Liberia — and the choice of location says something.'],
      money:['长期以矿产与农产品出口为主:石油、铜、钴、黄金、钻石、可可、咖啡。钴与铂族金属的世界储量高度集中在这里,是电池与电子产业绕不开的一环。近二十年的变化是移动通信跳过了固定电话——移动支付在肯尼亚等国的普及程度一度领先发达国家,是「跨越式发展」最常被引用的例子。','Exports have long been minerals and farm goods: oil, copper, cobalt, gold, diamonds, cocoa, coffee. World reserves of cobalt and the platinum metals are heavily concentrated here, which the battery and electronics industries cannot go around. The change of the past twenty years is that mobile communications skipped the landline stage — mobile payments reached a level of everyday use in Kenya and elsewhere ahead of the developed world, the most cited example of leapfrogging.'],
      power:['人口结构是最确定的一项:非洲是全世界最年轻的大陆,中位年龄不到二十岁,预计到本世纪中叶每四个劳动年龄人口中就有一个在非洲。资源、可耕地与快速城市化是另外三项。区域一体化在推进——2021年正式开始贸易的非洲大陆自由贸易区,按参与国家数量算是世界最大的自由贸易区。','Its age structure is the most certain fact about it: Africa is the youngest continent, with a median age under twenty, and by mid-century roughly one in four working-age people in the world is expected to be African. Resources, arable land and rapid urbanisation are the other three. Integration is advancing — the African Continental Free Trade Area, in force since 2021, is the largest free-trade area in the world by number of member states.'],
      fall:['1994年是最近一次大的转折,同一年发生了两件方向相反的事:南非举行首次不分种族的全民选举,曼德拉当选总统,种族隔离制度终结;而在卢旺达,百日之内约八十万人在种族屠杀中遇难,国际社会未能阻止。这两件事此后长期塑造着非洲内部与外部对这块大陆的认识。','The year 1994 was the last great turning point, and two things happened in it that pointed in opposite directions: South Africa held its first non-racial election and Mandela became president, ending apartheid; and in Rwanda some eight hundred thousand people were killed in a genocide within a hundred days, which the outside world failed to stop. Both have shaped how the continent is understood, from within and without, ever since.'],
      legacy:['人类起源于此,今天非洲以外所有人的祖先都从这里走出去。语言上,非洲有约两千种语言,占全世界的三分之一。20世纪的文化输出规模巨大:爵士、蓝调、摇滚与几乎所有现代流行音乐的节奏基础都可以追到西非;毕加索等人对现代艺术的改造,直接受非洲雕刻启发。曼德拉主持的和解进程,则成为世界各地处理历史创伤时反复参照的做法。','Humanity began here, and everyone alive descends from people who walked out of it. Africa has around two thousand languages, a third of all those spoken. Its cultural export in the twentieth century was enormous: jazz, blues, rock and the rhythmic basis of nearly all modern popular music trace back to West Africa, and the remaking of modern art by Picasso and others drew directly on African sculpture. The reconciliation process Mandela oversaw is referred to repeatedly wherever societies deal with historical injury.'] },
  d:'1957年加纳成为撒南非洲第一个独立的殖民地,1960"非洲年"一年内十七国独立;冷战代理冲突与结构调整的阵痛之后,本世纪多国增速居世界前列。中位年龄不到20岁——人类下一波人口与市场红利所在。' },
/* 美洲 */
{ l:'am', s:'meso', v:0, n:'奥尔梅克', k:[[-1200,0],[-800,.35],[-400,0]], b:'中美洲"母文明",巨石头像;历法与球赛的源头。',
  e:{ n:'Olmec', b:'Mesoamerica\'s mother culture; the colossal heads.', d:'Out of jungle swamps rose the "mother civilization": ten-ton basalt heads carved for no one knows whom; calendar, ballgame and feathered-serpent belief all start here, inherited wholesale by Maya and Aztec.', f:{ 'Peak':'900-400 BCE (the La Venta era)', 'Center':'San Lorenzo, later La Venta', 'Legacy':'Colossal heads, calendar origins' } },
  f:{ '鼎盛':'前900—前400(拉文塔时期)', '中心':'圣洛伦索→拉文塔', '成就':'巨石头像、中美洲历法源头' },
  qh:{ born:['河水年年泛滥,玉米就年年丰收','The river flooded each year, and the maize came in'],
       rule:['把首领的脸刻进石头,就是权力宣言','Carving the chief into stone was the statement of power'],
       money:['几十吨的石头,是从几十公里外运来的','Stones of many tonnes came from tens of kilometres away'],
       power:['它的影响像辐射,不像征服','Its influence radiated rather than conquered'],
       fall:['石像被人有意砸过,原因至今没共识','The heads were deliberately damaged, and no one agrees why'],
       legacy:['叫它母文明还是姊妹文明,至今在争','Mother culture or sister culture is still argued'] },
  q:{ born:['墨西哥湾沿岸的河流每年泛滥,沃土让玉米连年丰收;富余的粮食养出人口稠密的聚落,和能调动成百上千劳力的首领。圣洛伦索与拉文塔先后崛起,成为中美洲最早的祭祀中心。','Along Mexico\'s Gulf coast, yearly floods renewed the soil and maize harvests multiplied. The surplus fed dense settlements and chiefs who could command labor by the hundreds; San Lorenzo and then La Venta rose as Mesoamerica\'s earliest ceremonial centres.'],
      rule:['直接证据有限,一般认为由集宗教与政治权威于一身的首领统治:那些十余吨重的玄武岩巨石头像,多数学者推测是统治者的肖像——把首领的脸刻进永恒,本身就是权力的宣言。','Direct evidence is thin; the prevailing view is rule by chiefs who fused religious and political authority. The colossal basalt heads, each weighing over ten tons, are thought by most scholars to portray rulers — carving a chief\'s face into permanence was itself a statement of power.'],
      money:['根基是玉米、豆类与河湖渔猎;对外经营远距离交换网,玉石、黑曜石与橡胶沿河流与小径流转。雕像巨石从数十公里外运来——这个社会已能组织可观的人力与物流。','The base was maize, beans and fishing in the rivers and lagoons; beyond that ran long-distance exchange networks moving jade, obsidian and rubber. The basalt for the great heads was hauled from dozens of kilometres away — proof of a society that could organize serious labor and logistics.'],
      power:['祭祀中心吸引朝拜,美术风格与信仰沿贸易网传遍中美洲。一般认为奥尔梅克并未建立帝国,靠的是宗教威望与交换网络的向心力。','The ceremonial centres drew pilgrims, and its art style and beliefs travelled the trade routes across Mesoamerica. Scholars generally hold that the Olmec built no empire — their pull came from religious prestige and the gravity of exchange networks.'],
      fall:['圣洛伦索约在前900年衰落,拉文塔约在前400年被废弃,原因尚无定论:河流改道、环境变化、内部动荡都是假说;不少石像曾被有意损毁,是仪式还是动乱同样没有共识。人群并未消失,他们和他们的传统融入了后来的文化。','San Lorenzo declined around 900 BC and La Venta was abandoned around 400 BC, for reasons still unsettled — shifting rivers, environmental change and internal upheaval are all hypotheses, and whether the deliberate defacing of monuments was ritual or revolt is equally undecided. The people did not vanish; they and their traditions flowed into the cultures that followed.'],
      legacy:['中美洲文明的许多母题在此定型:历法与球赛的源头、羽蛇形象的雏形、巨石纪念碑的传统,为后来的玛雅与阿兹特克所继承——不少考古学家因此称它「母文明」,也有人认为它更像与周邻并行发展的「姊妹文明」。','Many of Mesoamerica\'s master themes were set here: the roots of the calendar and the ballgame, early feathered-serpent imagery, the tradition of monumental stone — all inherited wholesale by the Maya and the Aztecs, which is why archaeologists call it the \'mother culture\'.'] },
  d:'雨林沼泽中拔起的中美洲"母文明":十余吨的玄武岩巨头像至今不知为谁而刻;历法、球赛、羽蛇神信仰皆肇端于此,被玛雅与阿兹特克整体继承。' },
{ l:'am', s:'meso', v:1, n:'查文文化', k:[[-900,0],[-700,.3],[-400,.35],[-250,.2],[-200,0]], b:'安第斯的"母文化",秘鲁诸文明的共同源头。',
  e:{ n:'Chavin', w:'Chavin culture', b:'The Andean mother culture — the common source of every Peruvian civilization after it.', d:'The Andean counterpart to the Olmec, and the common ancestor of everything that followed in Peru. Deep in the underground galleries of Chavin de Huantar stands the Lanzon, a deity fusing human, cat and serpent, revealed in darkness and the sound of water. That imagery spread along the coast and through the highlands — the first time the Andes shared a single religion across regions. Metalwork, weaving and irrigation techniques were fixed here too, and were still in use eighteen centuries later under the Inca.', f:{ 'Peak':'500–300 BCE', 'Center':'Chavin de Huantar', 'Legacy':'The first pan-regional religious art style in the Andes' } },
  f:{ '鼎盛':'前500—前300', '中心':'查文德万塔尔', '成就':'安第斯第一种跨地域的宗教艺术风格' },
  qh:{ born:['海岸、高原、雨林,三条路在这里交汇','Coast, highland and jungle met at this one point'],
       rule:['统治的工具是敬畏,不是刀剑','The instrument of rule was awe, not the blade'],
       money:['山上的、海里的、林子里的,在这交换','What came from mountain, sea and forest changed hands here'],
       power:['安第斯第一次有了跨地域的共同信仰','The Andes first shared one faith across regions'],
       fall:['不是被谁打败的,更像一场退潮','No one defeated it: more like a tide going out'],
       legacy:['它画下了后来所有安第斯文明的底稿','It drew the draft every later Andean culture worked from'] },
  q:{ born:['查文德万塔尔恰好卡在海岸、高原与雨林三条通道的交汇点。不同生态区的人带着各自的物产在此相遇,一座融合三方神祇意象的神庙应运而生,成为安第斯世界的朝圣中心。','Chavín de Huántar sat where routes from coast, highlands and jungle met. Peoples from different ecological zones converged here with their goods, and a temple fusing imagery from all three worlds arose — a pilgrimage centre for the Andean world.'],
      rule:['一般认为这里没有国王也没有军队,权威属于掌管神谕的祭司:地下回廊深处,兰松石柱在幽暗与水声中显形,致幻仙人掌的仪式让朝圣者亲历神明——统治的工具是敬畏,不是刀剑。','The prevailing view is that Chavín had no kings and no armies; authority belonged to the priests who kept the oracle. Deep in the underground galleries the Lanzón loomed out of darkness and the roar of water, and rituals with a hallucinogenic cactus let pilgrims meet the divine — the instrument of rule was awe, not the sword.'],
      money:['财富来自安第斯的垂直生态:海岸的鱼、高原的土豆与驼羊、雨林的作物在此交换;朝圣者带来的供品供养神庙,纺织、冶金与灌溉的技法也在这个枢纽上被打磨、传播。','Wealth came from the vertical ecology of the Andes: coastal fish, highland potatoes and llamas, jungle crops all changed hands here. Pilgrims\' offerings sustained the temple, and techniques of weaving, metalworking and irrigation were refined and passed on through this hub.'],
      power:['不靠征服,靠信仰:查文的图像风格沿贸易与朝圣路线传遍秘鲁的海岸与山地,是安第斯第一次出现跨地域的共同信仰——考古学家称之为第一个「地平线」。','Its power was faith, not conquest: the Chavín style spread along trade and pilgrimage routes across coastal and highland Peru, the first shared belief system to span the Andes — what archaeologists call the first \'horizon\'.'],
      fall:['约前200年,查文的影响力消退,各地重回本地风格,神庙渐被废弃。原因尚无定论,气候波动、路线变迁或信仰体系失去号召力都是假说。它不是被谁打败的——更像一场缓缓的退潮。','Around 200 BC Chavín\'s influence ebbed: regions returned to local styles and the temple slipped into disuse. The cause is unsettled — climate swings, shifting routes or a cult losing its hold are all hypotheses. It was defeated by no one; it receded slowly, like a tide going out.'],
      legacy:['它画下安第斯诸文明的共同底稿:跨地域的宗教艺术、冶金与纺织技法、以神庙聚拢多方人群的模式,此后被一代代安第斯文明沿用,直到近两千年后的印加。','It drafted the common blueprint of Andean civilization: a supra-regional religious art, techniques of metallurgy and weaving, and the model of gathering diverse peoples around a temple — carried on by successive Andean cultures down to the Inca nearly two thousand years later.'] },
  d:'与中美洲的奥尔梅克遥相对称:此后所有安第斯文明的共同源头。查文德万塔尔的地下回廊深处立着"兰松"石柱——人、猫科动物与蛇的混合形象,在幽暗与水声里显形。这套图像沿海岸与山地传遍秘鲁,是安第斯第一次出现跨地域的共同信仰;冶金、纺织与灌溉的许多技法也在此定型,一直用到一千八百年后的印加。' },
{ l:'am', s:'meso', v:2, n:'玛雅', k:[[-300,0],[250,.4],[700,.55],[900,.25],[1400,.15],[1521,0]], b:'精密历法、美洲唯一成熟文字、独立发明"零"。',
  e:{ n:'Maya', w:'Maya civilization', b:'Script, zero and precise calendars — without metal or the wheel.', d:'Without metal tools or the wheel they measured the year more precisely than the Julian calendar and invented zero independently; dozens of city-states rose and fell until the 9th-century classic collapse — still unexplained. The Maya never vanished: millions of descendants speak Mayan today.', f:{ 'Peak':'Classic (250–900)', 'Center':'Tikal, Palenque, Chichén Itzá', 'Figures':'Pakal the Great', 'Legacy':'The Americas\' only full script, zero' } },
  f:{ '鼎盛':'古典期(250—900)', '中心':'蒂卡尔、帕伦克、奇琴伊察', '人物':'帕卡尔大帝', '成就':'美洲唯一成熟文字、独立发明零' },
  ct:['各时期的主要城邦','Major city-states, period by period'],
  co:[ { n:['埃尔米拉多尔','El Mirador'], c:['佩滕北部','northern Petén'], g:['前古典期(至250年)','Preclassic (to 250)'], x:['这一期的城已经垒起巨型神庙台基,规模不输后来的古典期名城','the cities of this era already raised colossal temple platforms, on a scale matching the later Classic capitals'] },
       { n:['卡米纳尔胡尤','Kaminaljuyu'], c:['危地马拉高地','the Guatemalan highlands'], g:['前古典期(至250年)','Preclassic (to 250)'] },
       { n:['蒂卡尔','Tikal'], c:['佩滕','Petén'], g:['古典期(250—900)','Classic (250–900)'], x:['数十个城邦并立,蒂卡尔与卡拉克穆尔各领一个联盟,争了一百多年也没有谁统一','dozens of city-states stood side by side; Tikal and Calakmul each led an alliance in a rivalry that ran for centuries, and neither ever unified the rest'] },
       { n:['卡拉克穆尔','Calakmul'], c:['坎佩切','Campeche'], g:['古典期(250—900)','Classic (250–900)'] },
       { n:['帕伦克','Palenque'], c:['恰帕斯','Chiapas'], g:['古典期(250—900)','Classic (250–900)'] },
       { n:['科潘','Copán'], c:['今洪都拉斯西部','western Honduras today'], g:['古典期(250—900)','Classic (250–900)'] },
       { n:['卡拉科尔','Caracol'], c:['今伯利兹','Belize today'], g:['古典期(250—900)','Classic (250–900)'] },
       { n:['奇琴伊察','Chichén Itzá'], c:['尤卡坦北部','northern Yucatán'], g:['后古典期(900—1521)','Postclassic (900–1521)'], x:['南部低地的城废弃后,重心北移到尤卡坦,奇琴伊察与玛雅潘先后称雄;但西班牙人来时这两座城都已荒废,尤卡坦分成十几个小邦,只有高地的基切王国还是大国','after the southern lowland cities were abandoned the centre moved north to Yucatán, where Chichén Itzá and then Mayapán led in turn; both were already deserted when the Spanish came, Yucatán had split into a dozen-odd small states, and only the K\'iche\' kingdom in the highlands was still a major power'] },
       { n:['玛雅潘','Mayapán'], c:['尤卡坦北部','northern Yucatán'], g:['后古典期(900—1521)','Postclassic (900–1521)'] },
       { n:['基切王国','the K\'iche\' kingdom'], c:['危地马拉高地','the Guatemalan highlands'], g:['后古典期(900—1521)','Postclassic (900–1521)'] } ],
  qh:{ born:['蓄水池熬旱季,台田精耕细作','Reservoirs for the dry season, raised fields for the rest'],
       rule:['从未统一,像一盘下了几百年的棋','Never unified: a chess game played for centuries'],
       money:['可可豆本身,就能当钱花','The cacao bean itself worked as money'],
       power:['没有金属工具,也没有车轮','No metal tools, and no wheel'],
       fall:['城废了,人没有绝','The cities emptied; the people did not end'],
       legacy:['它算的太阳年,比同期的儒略历还准','Its solar year was closer than the Julian calendar of the day'] },
  q:{ born:['玛雅人在雨林里解决了养活城市的难题:蓄水池熬过旱季,台田与园圃精耕细作。他们承接奥尔梅克传下的历法与信仰,数十个围绕神庙金字塔的城邦在低地各自生长。','The Maya solved the problem of feeding cities in a rainforest: reservoirs to survive the dry season, raised fields and garden plots farmed intensively. Inheriting the calendar and beliefs passed down from the Olmec, dozens of city-states grew up across the lowlands, each around its temple pyramids.'],
      rule:['每个城邦由自称「神圣君主」的国王统治,以放血献祭等仪式沟通神明,换取统治的合法性。玛雅从未统一:蒂卡尔与卡拉克穆尔两大集团的争霸贯穿古典期,像一盘下了几百年的棋。','Each city-state was ruled by a king styled \'holy lord\', who earned legitimacy by communing with the gods through bloodletting and other rituals. The Maya never unified: the rivalry between Tikal, Calakmul and their allies ran through the Classic period like a chess match played over centuries.'],
      money:['底盘是玉米农业;城邦之间由集市与长途商路相连,玉石、黑曜石、盐、羽毛与可可流转其间——可可豆本身就能当钱用。','Maize farming was the foundation, with city-states linked by markets and long-distance trade in jade, obsidian, salt, feathers and cacao — cacao beans themselves served as money.'],
      power:['知识就是王权:祭司天文学家精确追踪日月与金星,历法预告雨季与仪式吉日,文字把国王的功业刻上石碑。没有金属工具也没有车轮,靠组织力支撑起人口众多的城邦网络。','Knowledge was royal power: priest-astronomers tracked the sun, moon and Venus with precision, the calendar announced the rains and the ritual days, and writing carved kings\' deeds into stelae. Without metal tools or the wheel, sheer organization sustained a populous network of cities.'],
      fall:['9世纪前后,南部低地的城市在百余年间相继停建、废弃,王朝纪年中断——古典期崩溃的原因至今尚无定论,持续大旱、人口超载与生态压力、连绵战争、贸易路线转移等假说并存,多数学者认为是多因叠加。但这不是灭绝:北部的奇琴伊察等城随后兴起;西班牙人到来后,玛雅人又抵抗了一个多世纪。','Around the 9th century the cities of the southern lowlands stopped building and were abandoned one after another over a century or so, and the dynastic count fell silent. The cause of the Classic collapse remains unsettled — prolonged droughts, overpopulation and environmental strain, chronic warfare and shifting trade routes are competing hypotheses, and most scholars see several causes compounding. But it was no extinction: northern cities like Chichén Itzá rose afterwards, and once the Spanish arrived, the Maya resisted for more than a century longer.'],
      legacy:['美洲唯一的成熟文字体系、独立发明的「零」、算出的太阳年与金星周期比同时代儒略历更接近真值;20世纪的铭文破译让沉默的石碑重新开口。数百万玛雅后裔今天仍在中美洲说着玛雅语——文明换了形态,人一直都在。','The Americas\' only fully developed writing system, an independently invented zero, and solar-year and Venus cycles computed closer to the truth than the Julian calendar of the same era; twentieth-century decipherment let the silent stelae speak again. Millions of Maya descendants still speak Mayan languages in Central America today — the civilization changed form, but the people never left.'] },
  d:'没有金属工具、没有车轮,却算出比儒略历更精确的年长,并独立发明了"零";数十城邦兴衰更替,9世纪古典期城市集体废弃至今成谜。但玛雅人从未"消失"——数百万后裔今日仍在说玛雅语。' },
{ l:'am', s:'meso', v:1, n:'特奥蒂瓦坎', k:[[-100,0],[300,.4],[450,.5],[550,0]], b:'"众神之城",鼎盛时是美洲最大城市。',
  e:{ n:'Teotihuacan', b:'"City of the gods", the Americas\' metropolis.', d:'At peak perhaps 100,000+ people — among the world\'s largest cities of its day, its influence reaching Maya courts hundreds of kilometers away; its builders remain unidentified. The Aztecs, finding ruins, named it "where the gods were born."', f:{ 'Peak':'c. 450', 'Center':'Teotihuacan', 'Figures':'Siyaj K\'ak\'', 'Legacy':'Sun & Moon pyramids, grid city' } },
  f:{ '鼎盛':'450年前后', '中心':'特奥蒂瓦坎', '人物':'火之生', '成就':'日月金字塔、网格都市' },
  qh:{ born:['对手毁于火山,它就此一城独大','A volcano took its rival, and it stood alone'],
       rule:['没有王陵,没有帝王像,也没有名字','No royal tomb, no royal statue, and no name'],
       money:['城里有外邦人的街区,商路四通八达','It had foreign quarters, and roads running everywhere'],
       power:['它的手伸到了玛雅腹地的王位更替','Its hand reached into a Maya succession far away'],
       fall:['烧的是神庙和权贵区,平民区没事','The temples and elite houses burned; the common streets did not'],
       legacy:['「特奥蒂瓦坎」这名字,是后人起的','Even the name we use was given by later people'] },
  q:{ born:['湖畔沃土与优质黑曜石矿脉让它迅速膨胀,谷地南边的竞争者库伊库尔科先后毁于火山活动,它从此一城独大。它按整体规划铺开棋盘式街道,亡者大道两侧立起日月金字塔。','After volcanic eruptions wrecked rival centres in the Valley of Mexico, refugees and migrants streamed into the new city. Sitting on prime obsidian deposits and fertile lakeside land, it was laid out on a master grid, the Avenue of the Dead flanked by the Pyramids of the Sun and Moon.'],
      rule:['谁统治这座城,至今成谜:没有王陵,没有帝王雕像,壁画里也找不到君主的名字——与同时代把国王刻满石碑的玛雅恰成对照。学者推测可能由多个家族或团体共治,尚无定论。','Who ruled the city remains a mystery: no royal tombs, no ruler statues, no kings named in its murals — a striking contrast with the stela-carving Maya of the same era. Scholars conjecture rule by several lineages or corporate groups, but nothing is settled.'],
      money:['城内作坊数以百计,把优质黑曜石加工成刀刃器物,销往整个中美洲;城市本身就是大市场,萨波特克人、玛雅人聚居的外邦人街区,说明商路四通八达。','Hundreds of workshops in the city worked prime obsidian into blades traded across Mesoamerica. The city itself was a great marketplace — the foreign quarters where Zapotecs and Maya lived show how far its trade routes reached.'],
      power:['鼎盛期人口或逾十万,体量在当时的美洲无可匹敌,宗教威望与商业网络辐射数百公里;据玛雅铭文记载,378年它的势力介入了蒂卡尔的王位更替——影响力直抵玛雅腹地。','At its height its population may have exceeded a hundred thousand, unmatched in the Americas of its day, its religious prestige and commercial network radiating for hundreds of kilometres. Maya inscriptions record that in AD 378 its forces intervened in Tikal\'s royal succession — reach extending into the Maya heartland.'],
      fall:['6世纪中叶,城中心遭系统性焚毁——烧的主要是神庙与权贵建筑,平民街区大多无恙,因此一般认为更像内部起义,而非外敌入侵;背后或有旱灾与民生恶化积下的怨气,确切原因尚无定论。此后人口散去,大城退成村落。','In the mid-6th century the city\'s core was systematically burned — mainly temples and elite buildings, while commoner districts were largely spared — so the prevailing reading is internal uprising rather than foreign invasion, perhaps fed by drought and worsening hardship, though the exact cause remains unsettled. The population dispersed, and the metropolis dwindled into villages.'],
      legacy:['后来者都认它作祖师:托尔特克与阿兹特克的建筑和羽蛇崇拜承其衣钵;阿兹特克人面对废墟,敬畏地称之为「众神诞生之地」——特奥蒂瓦坎这个名字本身就是他们起的。日月金字塔至今仍是墨西哥的地标。','Later peoples claimed it as their ancestor: Toltec and Aztec architecture and the Feathered Serpent cult carried its mantle, and the Aztecs, awed by the ruins, named it \'the place where the gods were born\' — Teotihuacan is their word for it, not its own. The Pyramids of the Sun and Moon remain landmarks of Mexico today.'] },
  d:'鼎盛期人口或逾十万,是同期世界最大城市之一,影响远及数百公里外的玛雅城邦;建造者族属成谜。后来的阿兹特克人见到废墟时敬畏地称之为"众神诞生之地"。' },
{ l:'am', s:'meso', v:2, n:'帕查卡马克与中部海岸', k:[[-200,0],[200,.15],[600,.2],[900,.18],[1200,.24],[1470,.16],[1533,0]], b:'秘鲁中部海岸的一座神庙用了一千三百年:换了好几个主人,每个新主人来了都先拜它,最后一个把它抢了。',
  d:'秘鲁中部海岸这条窄窄的绿洲地带,从公元前后一直有人经营。约 200 年起,今天利马以南三十公里的帕查卡马克建起神庙,此后一千三百年不断扩建:利马文化、瓦里帝国、以它为中心的伊奇马王国先后经手。它是海岸上最大的朝圣地、安第斯最重要的圣所之一,各地的人长途赶来求神谕,连远在北方的部族也派人来问事。1470 年前后印加征服这一带,却没有拆掉它——印加人在旁边加建了太阳神庙与「太阳贞女」的院子,让原来的神谕继续开口。1533 年西班牙人循着黄金的传闻找来,把神庙洗劫一空;记载说他们打开至圣所,里面只是一根粗糙的木桩,大失所望。',
  e:{ n:'Pachacamac and the Central Coast', w:'Pachacamac', b:'One temple on the central coast of Peru was in use for thirteen centuries — each new master came to worship at it, and the last one looted it.', d:'The narrow oasis strip of the central Peruvian coast was continuously worked from around the turn of the era. From about 200 CE a temple complex rose at Pachacamac, thirty kilometres south of today\'s Lima, and was enlarged for the next thirteen centuries in turn by the Lima culture, the Wari empire and the Ychsma kingdom that grew up around it. It was the largest pilgrimage site on the coast and one of the most important sanctuaries in the Andes: people travelled from far away to consult its oracle, and even peoples in the far north sent to ask it questions. When the Inca conquered the coast around 1470 they did not pull it down — they added a sun temple and a compound for the chosen women beside it and let the oracle go on speaking. In 1533 the Spanish came following rumours of gold and stripped the place; the chronicles say they forced the sanctuary and found only a roughly carved wooden post, to their great disappointment.', f:{ 'Peak':'Ychsma and Inca rule (1100—1533)', 'Center':'Pachacamac', 'Legacy':'A temple in use for thirteen centuries; the great oracle of the Andes' } },
  f:{ '鼎盛':'伊奇马与印加治下(1100—1533)', '中心':'帕查卡马克', '成就':'用了一千三百年的神庙、安第斯最大的神谕所' },
  qh:{ born:['海边一条窄绿洲,靠河谷养活一切','A narrow oasis by the sea, fed by its river valleys'],
       rule:['神庙比王朝活得久,谁来了都得拜','The temple outlived the dynasties; each new ruler worshipped'],
       money:['棉花、鱼干与朝圣的人流','Cotton, dried fish, and a steady flow of pilgrims'],
       power:['靠的不是军队,是别人有事要来问','Its power lay not in armies but in people needing answers'],
       fall:['西班牙人循着黄金的传闻找来了','The Spanish came following rumours of gold'],
       legacy:['印加征服之后,没有拆它,反而加盖','The Inca conquered it and built beside it instead'] },
  q:{ born:['秘鲁中部海岸几乎不下雨,能住人的只有几条从安第斯山下来的河谷。人们在这些绿洲上修渠种地、下海捕鱼,从公元前后一直经营下去。约 200 年起,今天利马以南三十公里的地方开始建起一片神庙,这就是帕查卡马克——名字的意思是「创造大地的那一位」。','It almost never rains on the central coast of Peru; the only habitable ground is a handful of river valleys coming down from the Andes. People built canals and farmed these oases and fished the sea, continuously from about the turn of the era. Around 200 CE a temple complex began to rise thirty kilometres south of today\'s Lima — Pachacamac, a name meaning "the earth-maker".'],
      rule:['这一带的政治史是一段接一段的:利马文化、瓦里帝国、伊奇马王国、印加,前后换了四拨人。而神庙一直在,每一拨新来的都要扩建它、供奉它——权力换手的速度,比一座神庙的寿命快得多。伊奇马王国干脆就以它为中心,把周围河谷的聚落组织起来。','The political history here comes in segments: the Lima culture, the Wari empire, the Ychsma kingdom, then the Inca — four sets of masters in turn. The temple stayed through all of them, and each new arrival enlarged and honoured it. Power changed hands far faster than a temple\'s working life. The Ychsma kingdom simply organised itself around the sanctuary and the valley settlements near it.'],
      money:['海岸绿洲产棉花与玉米,近海的洪堡寒流是世界上最富的渔场之一,鱼晒干了往山里运,换回山区的土豆与羊毛。而帕查卡马克本身也是一门生意:朝圣的人要献供品,神庙周围形成了作坊、客舍与市集,考古在这里挖出过来自厄瓜多尔的海菊蛤壳——那是安第斯最贵重的祭品之一,得走上千公里运来。','The coastal oases grew cotton and maize, and the Humboldt current offshore is one of the richest fisheries on earth; dried fish went up into the mountains and came back as potatoes and wool. Pachacamac itself was also a business: pilgrims brought offerings, and workshops, lodgings and markets grew up around the sanctuary. Excavation there has turned up Spondylus shell from Ecuador — among the most precious of Andean offerings, carried more than a thousand kilometres.'],
      power:['它的分量不来自军队,来自别人有事要问。神庙里有神谕,各地的人长途赶来求问收成、疾病与战争;求过的人回去还要供养它,于是帕查卡马克在远处也有一批「分庙」。一个不靠打仗的地方,影响力却铺得比很多王国还远。','Its weight came not from armies but from people who needed answers. The sanctuary held an oracle, and people travelled long distances to ask about harvests, sickness and war; those who had consulted it went on supporting it afterwards, so Pachacamac maintained branch shrines far away. A place that fought nobody reached further than many kingdoms did.'],
      fall:['1470 年前后印加征服中部海岸。他们没有拆掉这座神庙——印加的做法是在旁边加建自己的太阳神庙与「太阳贞女」的院子,让原来的神谕继续开口,同时把它纳入自己的体系。真正的终点是 1533 年:西班牙人循着黄金的传闻赶来,洗劫神庙;记载说他们撬开至圣所,里面只是一根粗糙的木桩,让他们大失所望。','The Inca conquered the central coast around 1470. They did not pull the sanctuary down — their method was to build their own sun temple and a compound for the chosen women beside it, letting the old oracle go on speaking while folding it into their own system. The real end came in 1533, when the Spanish arrived following rumours of gold and stripped the place. The chronicles say they broke open the sanctuary and found only a roughly carved wooden post, to their great disappointment.'],
      legacy:['帕查卡马克今天是一片土黄色的台地遗址,就在利马南边,城市几乎已经长到它脚下。它留下的问题比答案多:那尊被撬开的木像现在还在,雕着两面的人形,而神谕怎么运作、由谁代言,记载语焉不详。一座建筑用了一千三百年,经历四拨统治者,最后毁在第五拨手里——而它从来不是首都,只是一个大家都要来问事的地方。','Pachacamac today is a spread of ochre terraces just south of Lima, with the city almost grown up to its edge. It leaves more questions than answers: the wooden image they broke open survives, carved with figures on two sides, but how the oracle worked and who spoke for it the sources barely explain. A single complex in use for thirteen centuries, through four sets of rulers, destroyed by the fifth — and it was never a capital, only the place everyone came to ask.'] } },
{ l:'am', s:'meso', v:0, n:'莫切', k:[[100,0],[400,.3],[600,.28],[800,0]], b:'秘鲁北岸的绿谷社会:写实陶器与金铜冶炼,奇穆的前身。',
  e:{ n:'the Moche', w:'Moche culture', b:'Green-valley society on the north coast of Peru: portrait pottery, gold-copper metalwork, forerunners of the Chimú.', d:'The north coast of Peru hardly ever rains and depends entirely on the valleys cut by rivers coming off the Andes. From the first century AD settlements around the Moche valley extended canals and raised adobe platforms into a ranked society — though probably not one state, more likely several independent polities north and south sharing one body of imagery. It left no writing, so everything known comes from pottery, murals and burials: the gold and silver in the tomb at Sipán matches the priest painted on the pots piece for piece, and human bone under the plaza of the Huaca de la Luna matches the sacrifices in the murals. Floods and drought alternated in the sixth and seventh centuries, the great platforms stopped going up, and the centres moved north.', f:{ 'Peak':'AD 400–600', 'Center':'Moche valley, Lambayeque valley', 'Figures':'Lord of Sipán', 'Legacy':'Portrait vessels, gold-copper alloys, the Huacas of the Sun and Moon' } },
  f:{ '鼎盛':'公元400—600年', '中心':'莫切谷、兰巴耶克谷', '人物':'西潘王', '成就':'肖像陶器、金铜合金冶炼、太阳与月亮神庙(瓦卡)' },
  qh:{ born:['没有文字,一切都靠陶器和墓葬来读','No writing: everything is read from pots and graves'],
       rule:['壁画上的那个角色,在墓里找到了本人','The figure painted on the pots was found in a tomb'],
       money:['一边是渠灌的谷地,一边是最富的渔场','Irrigated valleys on one side, a rich fishery on the other'],
       power:['图像画的献祭,在地层里找到了人骨','The sacrifice in the paintings was found in the ground'],
       fall:['先洪水后干旱,但不能全算气候的账','Flood then drought, but the climate is not the whole account'],
       legacy:['肖像瓶上的脸,一张一张都不一样','Every face on the portrait vessels is different'] },
  q:{ born:['秘鲁北岸是世界上最干旱的海岸之一,几乎不下雨,但从安第斯山流下的几十条小河每隔一段就切出一条绿谷。公元后最初的一两百年,莫切谷与周边河谷的聚落开始扩大灌溉渠、修筑土坯高台,形成有等级的社会。它没有留下文字,今天关于它的一切了解都来自陶器、壁画、墓葬与渠道遗迹——这一点决定了下面每一条能说到什么程度。','The north coast of Peru is among the driest coastlines on earth and it hardly rains, but dozens of rivers coming down from the Andes cut a green valley every so often. In the first century or two AD, settlements in the Moche valley and its neighbours began extending irrigation canals and raising adobe platforms, and a ranked society took shape. It left no writing, so everything known about it today comes from pottery, murals, burials and the traces of its canals — which sets the limit on how much each of the answers below can say.'],
      rule:['早期研究把它当成一个统一的国家,现在多数学者认为更像是南北两片、各自独立的若干政权,共享同一套宗教图像与陶器风格,而不受同一个王统辖。领袖同时是祭司:1987年发掘的西潘王墓里,墓主戴着金面具,两手各握一枚金锭与银锭,另有耳饰与权杖,这些器物的组合与陶器壁画上主持仪式的人物一一对应——图像里的那个角色,在墓里被找到了本人。','Early work treated it as a single state; most scholars now think it was more like a number of independent polities in two groups, north and south, sharing a body of religious imagery and a pottery style rather than a single ruler. Leaders were also priests: in the tomb at Sipán excavated in 1987 the occupant wore a gold mask and held ingots of gold and silver, with ear ornaments and a sceptre whose combination matches, piece for piece, the figure shown presiding over ceremonies on painted pots — the character in the pictures was found in person in the grave.'],
      money:['靠渠灌农业:玉米、豆类、南瓜、辣椒,加上太平洋沿岸极其丰饶的渔业——秘鲁寒流带来的鱼群是这条海岸最稳定的蛋白质来源。海与谷的结合是这一带文明反复出现的底盘,后来的奇穆与印加沿海部分用的是同一套。渠道要跨过好几段荒漠扇地才够用,而维护渠道需要跨聚落的协作,这本身就是社会复杂化的动力。','It ran on canal farming — maize, beans, squash, chillies — plus the extraordinary fisheries of the Pacific coast, where the cold Peru current makes fish the steadiest protein on this shoreline. Sea plus valley is the foundation that keeps reappearing here; the Chimú and the coastal Inca later ran on the same combination. Canals had to run across long stretches of desert fan to be worth building, and keeping them up required cooperation between settlements, which is itself an engine of social complexity.'],
      power:['没有证据表明它是一个靠征服扩张的帝国。被反复描绘的是仪式:壁画与陶器上大量出现俘虏被押解、献祭的场面,而月亮金字塔的发掘在广场地层里找到了对应的人骨堆积——图像与遗骸互相印证。这在没有文字的文明里是难得的双重证据,也是为数不多可以说得比较肯定的事。','There is no evidence it was an empire that grew by conquest. What is depicted over and over is ritual: murals and pots show prisoners led away and sacrificed, and excavation at the Huaca de la Luna found matching deposits of human bone in the plaza layers — image and remains confirming each other. For a civilisation without writing that is a rare double line of evidence, and one of the few things that can be said with some confidence.'],
      fall:['公元6至7世纪之间这一带经历了剧烈的气候波动:先是厄尔尼诺带来的洪水冲毁渠道与土坯建筑,随后是长期干旱。同一时期大型高台停止营建,人口向内陆上游迁移,晚期中心转到北面的兰巴耶克一带。不过把衰落全部归给气候是过于简单的说法——学界普遍认为是社会内部的变化与气候压力叠加,具体各占多少至今没有定论。','Between the sixth and seventh centuries the region went through violent swings of climate: first El Niño floods that wrecked canals and adobe buildings, then a long drought. In the same period work on the great platforms stopped, people moved inland and upriver, and the later centres shifted north towards Lambayeque. But blaming the collapse entirely on climate is too simple — the general view is that internal social change and climate stress compounded each other, and how much weight each carries is still unsettled.'],
      legacy:['它留下的是这一带此后一千年的模板:绿谷—渠道—土坯高台这套组织方式,被后来的兰巴耶克、奇穆一路沿用到印加。金属工艺尤其突出,用金铜合金做出表面富金的效果,技术在安第斯地区长期传承。写实陶器则让它成为前哥伦布时期少有的、能看见具体人脸的文明——肖像瓶上的面孔各不相同,有病容,有缺齿,有老人。太阳金字塔在17世纪被殖民者引莫切河冲刷以便淘金,毁去大半;月亮神庙则是逐层叠建的,新的一层把旧的一层连壁画一起封在里面,壁画因此保存了下来。','What it left is the template for the next thousand years here: green valley, canal, adobe platform — an arrangement Lambayeque and the Chimú used in turn and the Inca inherited. Its metalwork stands out, using gold-copper alloys to produce a gold-rich surface, and that technique had a long life in the Andes. Its realistic pottery makes it one of the few pre-Columbian cultures where individual human faces can be seen — the portrait vessels are all different, some sick, some missing teeth, some old. The Huaca del Sol was largely destroyed in the seventeenth century when colonists diverted the Moche river across it to wash out gold; the Huaca de la Luna was built up in layers, each new one sealing the older murals inside, which is why they survived.'] },
  d:'秘鲁北岸几乎不下雨,全靠安第斯山下来的小河切出的绿谷。公元1世纪起,莫切谷一带扩渠、筑土坯高台,形成有等级的社会——但很可能不是一个国家,而是南北各自独立的若干政权,共享同一套图像。它没有文字,今天的了解全部来自陶器、壁画与墓葬:西潘王墓里的金银器与陶画上的祭司一一对应,月亮金字塔广场下的人骨与壁画上的献祭场面互相印证。6至7世纪洪水与干旱交替,大型营建停止,中心北移。' },
{ l:'am', s:'meso', v:1, n:'瓦里·蒂瓦纳科', k:[[600,0],[800,.3],[1000,0]], b:'安第斯高原双雄,梯田与道路网为印加打下底稿。',
  e:{ n:'Wari & Tiwanaku', w:'Tiwanaku', b:'Andean twin powers; the Inca\'s rough draft.', d:'The Andean twin powers fed high-altitude populations with terraces and raised fields; their roads and administration were the draft the Inca later wrote over.', f:{ 'Peak':'8th–9th c.', 'Center':'Wari; Lake Titicaca', 'Legacy':'Highland terraces, road networks' } },
  f:{ '鼎盛':'8—9世纪', '中心':'瓦里、的喀喀湖畔', '成就':'高山梯田、道路网' },
  qh:{ born:['高海拔第一次养得起大规模人口','High altitude could feed a large population at last'],
       rule:['一个像帝国,一个像宗教中心','One behaved like an empire, the other like a shrine'],
       money:['在不同海拔各设据点,各取所长','Outposts at different altitudes, each for what it grew'],
       power:['一刚一柔,却共用同一套宗教图像','One hard, one soft, and both sharing the same images'],
       fall:['湖底沉积和冰芯都指向同一场大旱','Lake beds and ice cores both point to one long drought'],
       legacy:['印加把自己的创世神话,安在这里','The Inca placed their creation story here'] },
  q:{ born:['两套高原生存术各自开花:瓦里在秘鲁山地把坡地修成层层梯田;蒂瓦纳科在的喀喀湖畔筑起垛田,白天蓄热、夜里防霜。高海拔第一次养得起大规模人口,两个中心随之崛起。','Two arts of highland survival flowered separately: Wari terraced the slopes of the Peruvian Andes, while Tiwanaku built raised fields by Lake Titicaca that stored daytime heat against the night frosts. For the first time high altitude could feed large populations, and two great centres rose on that foundation.'],
      rule:['瓦里更像帝国:修路、设行政中心、迁移人口,把征服地纳入统一管理,还用结绳记录物资——印加行政术的雏形。蒂瓦纳科则一般认为更像宗教中心与联盟,靠神庙威望与盛宴款待凝聚各方。','Wari looks more like an empire: roads, provincial administrative centres, resettled populations, and knotted cords for keeping records — a rough draft of Inca statecraft. Tiwanaku, by the prevailing view, was more a religious centre and confederation, binding its followers through temple prestige and great feasts.'],
      money:['两者都用「垂直群岛」的策略:在不同海拔设据点,土豆、玉米、驼羊毛各取所长,骆马商队穿梭其间;在蒂瓦纳科的神庙经济里,玉米酒盛宴既是祭祀,也是给劳作者的报酬。','Both ran the \'vertical archipelago\' strategy: outposts at different altitudes harvesting potatoes, maize and llama wool, with llama caravans shuttling between them. In Tiwanaku\'s temple economy, maize-beer feasts were at once worship and payment for labor.'],
      power:['瓦里靠军政机器扩张,行政城与道路网把势力铺满秘鲁山地;蒂瓦纳科靠信仰辐射,石门上的持杖神像回响在南安第斯各地。一刚一柔,数百年间共享同一套宗教图像。','Wari expanded through its military-administrative machine, its roads and garrison towns spreading across highland Peru; Tiwanaku radiated through faith, the staff-bearing god on its stone gateways echoed across the southern Andes. Hard power and soft, sharing one religious iconography for centuries.'],
      fall:['约1000年前后,两大中心相继衰落、废弃。主流假说指向长期大旱:湖泊沉积与冰芯显示降水锐减,垛田与梯田体系难以为继,内部纷争可能随之而起;确切过程尚无定论。此后安第斯高原分裂为割据的小邦,数百年后才由印加重新整合。','Around AD 1000 both centres declined and were abandoned. The leading hypothesis is prolonged drought — lake sediments and ice cores show rainfall collapsing, undermining the raised-field and terrace systems, with internal strife likely following — though the exact course is unsettled. The highlands then splintered into petty states, reunited only centuries later by the Inca.'],
      legacy:['它们给印加打下底稿:梯田、道路、结绳记事、迁移人口的行政手法都被直接续写;印加王室更把创世神话安放在的喀喀湖与蒂瓦纳科的废墟,认它作文明的源头。','They drafted the blueprint the Inca would inherit: terraces, roads, knotted-cord records and the administrative art of resettling populations were all carried straight on. The Inca royal house even set its creation myth at Lake Titicaca and the ruins of Tiwanaku, honoring it as the fountainhead of civilization.'] },
  d:'安第斯高原的双雄:梯田、垛田与道路网养活了高海拔人口;其行政传统与路网遗产,数百年后被印加直接续写。' },
{ l:'am', s:'meso', v:1, n:'奇穆', k:[[900,0],[1200,.3],[1400,.35],[1470,0]], b:'印加之前安第斯最大的国家,都城是美洲最大的土坯城。',
  e:{ n:'Chimor', b:'The largest Andean state before the Inca; its capital is the biggest adobe city in the world.', d:'On a coast that barely rains, Chimor cut long canals across the divides to carry one river\'s water into the next valley, feeding the largest state in the Andes before the Inca; its capital Chan Chan is the biggest adobe city in the world. Around 1470 the Inca cut the capital\'s water and took it after a siege of about six months. The last king and the craftsmen were resettled, and Chimú metalwork spread through the Inca realm.', f:{ 'Peak':'14th-15th c.', 'Center':'Chan Chan', 'Figures':'Taycanamu (founder of tradition)', 'Legacy':'Chan Chan, inter-valley canals, gold and silver work' } },
  f:{ '鼎盛':'14—15世纪', '中心':'昌昌', '人物':'塔卡伊纳莫(传说中的建国者)', '成就':'昌昌土坯城、跨谷灌溉渠、金银器' },
  qh:{ born:['建国者的故事是口传的,没有别的证据','The founder story is oral, with nothing else behind it'],
       rule:['一位国王建一座大院,死后就封成陵','Each king built one compound, and was sealed in it'],
       money:['命脉是水,农田远超自然绿洲的规模','Water was the lifeline, and the fields outgrew the oasis'],
       power:['占住上游的渠首,下游就得听话','Hold the head of the canal and the valley obeys'],
       fall:['印加断了它的水,但还是打了几年','The Inca cut its water, and still fought for years'],
       legacy:['一座土做的城,最怕的东西是雨','A city built of earth, and what it fears is rain'] },
  q:{ born:['秘鲁北岸是世界上最干旱的海岸之一,几乎不下雨,但从安第斯山流下的河流每隔一段就切出一条绿谷。莫切文化在公元800年前后衰落后,莫切谷一带重新聚合起一个政权,以昌昌为中心向南北扩张,沿海岸把一条条绿谷串了起来。关于建国者,当地传说讲的是一位名叫塔卡伊纳莫的人乘木筏渡海而来——这是口传,没有别的证据。','The north coast of Peru is among the driest shorelines on earth, almost rainless, but rivers coming down from the Andes cut a green valley every so often. After the Moche culture declined around 800, a state re-formed around the Moche valley, spread north and south from its capital at Chan Chan, and strung the coastal valleys together. Local tradition says the founder, Taycanamu, arrived by raft from the sea — that is oral tradition, and there is no other evidence for it.'],
      rule:['统治的办法是把征服来的每一条河谷保留原样、只换上层:当地首领继续管事,向昌昌纳贡并出劳力。都城昌昌本身由十座左右带高墙的大院(西班牙人称之为 ciudadela)组成,每一座都有自己的广场、仓库、水井与王陵。一般认为一位国王建一座、死后封存作陵墓,继任者另建新的——权力更替在城市平面图上留下了痕迹。','It ruled by leaving each conquered valley as it was and replacing only the top: local lords went on governing, sending tribute and labour to Chan Chan. The capital itself was built of some ten high-walled compounds, each with its own plaza, storerooms, well and royal tomb. The usual reading is that each king built one, it was sealed as his tomb when he died, and his successor built another — so the succession of rulers is legible in the city plan.'],
      money:['命脉是水。奇穆修建了美洲规模最大的一批灌溉工程,包括跨越河谷分水岭、把一条河的水引到另一条谷地去的长渠(其中最著名的一条是否真正通过水,学界争论至今)。农田面积远超自然绿洲所能支撑的规模。海岸提供另一半:秘鲁寒流是世界上最富饶的渔场之一。手工业以金银器与纺织闻名,匠人集中居住、按行当组织,西班牙人到来后从昌昌一带掠走的金器数量在记载里极为可观。','Water was the lifeline. Chimú built some of the largest irrigation works in the Americas, including long canals that crossed a divide to carry one river\'s water into the next valley — whether the most famous of them ever actually carried water is still argued over. Farmland far exceeded what the natural oases could support. The coast supplied the other half: the Peru Current is one of the richest fisheries in the world. Its crafts were known for goldwork, silverwork and textiles, with artisans living in quarters and organised by trade; Spanish accounts of the gold carried off from Chan Chan run to remarkable quantities.'],
      power:['扩张靠的是控制水与路,而不是大规模野战:占住上游渠首,下游的谷地就得听话;沿海岸修路把各谷连成一线,调兵与运贡都快。全盛时它沿海岸控制约一千公里,是印加之前安第斯地区疆域最大的国家。','It expanded by holding water and roads rather than by great pitched battles: take the canal intakes upstream and the valleys below must comply, and a coastal road tied the valleys into one line so that troops and tribute moved fast. At its height it held roughly a thousand kilometres of coast, the largest state in the Andes before the Inca.'],
      fall:['1470年前后被印加所灭。印加的打法正对着奇穆的软肋:切断莫切河的引水渠,断掉都城的水。但这不是不战而胜——双方在帕拉蒙加等地打了数年,昌昌本身又坚守了约半年才开城。末代国王被带到库斯科,昌昌的工匠也被大批迁往印加各地,金银器的手艺因此散布到整个帝国。','It was conquered by the Inca around 1470. The Inca method went straight at the weakness: they cut the canal that fed the capital from the Moche river. It was not a bloodless win, though — the two sides fought for years at Paramonga and elsewhere, and Chan Chan itself held out about six months before opening its gates. The last king was taken to Cuzco and Chan Chan\'s craftsmen were resettled across the Inca realm, spreading their metalworking through the empire.'],
      legacy:['昌昌是美洲最大的土坯城,遗址约二十平方公里,1986年列入世界文化遗产,同时列入濒危名单——土坯几乎不耐雨,而厄尔尼诺年份的暴雨正在一年年侵蚀它。奇穆的金属工艺被印加继承并推广;而它靠灌溉在极旱海岸养活大量人口这件事本身,至今仍是干旱地区水利研究会引用的案例。','Chan Chan is the largest adobe city in the Americas, its ruins covering some twenty square kilometres; it was inscribed as a World Heritage site in 1986 and placed on the endangered list at the same time — adobe barely withstands rain, and the downpours of El Niño years are eating it away. Chimú metalwork was taken up and spread by the Inca, and the fact that irrigation let it feed a large population on an almost rainless coast is still cited in the study of water management in dry lands.'] },
  d:'秘鲁北岸几乎不下雨,奇穆靠跨谷长渠把一条河的水引到另一条谷地,在沙漠海岸上养出安第斯印加之前最大的国家;都城昌昌是美洲最大的土坯城。1470年前后印加切断都城的引水渠,又围了约半年才破城——末代国王与工匠一并被迁走,金银手艺就此散入印加全境。' },
{ l:'am', s:'meso', v:0, n:'密西西比文化·卡霍基亚', k:[[800,0],[1100,.3],[1350,.12],[1600,0]], b:'北美的土丘之城,墨西哥以北一度最大的聚落。',
  e:{ n:'Cahokia and the Mississippian world', b:'A city of mounds in North America, once the largest settlement north of Mexico.', d:'Once maize had spread north, the fertile floodplain near where the Mississippi meets the Missouri grew the largest settlement in North America; Monks Mound was raised basketload by basketload to some 620,000 cubic metres, the biggest earthwork north of Mexico. Marine shell came from the Gulf and copper from the Great Lakes — an exchange network across the middle of the continent. It was abandoned around 1350, with flooding and rising conflict running together, while the once-popular deforestation theory was tested in 2021 and found wanting.', f:{ 'Peak':'11th-12th c.', 'Center':'Cahokia in Illinois', 'Legacy':'Monks Mound, the woodhenge, a continental trade network' } },
  f:{ '鼎盛':'11—12世纪', '中心':'卡霍基亚(今美国伊利诺伊州)', '成就':'僧侣丘、木阵、跨大陆贸易网' },
  qh:{ born:['1050年前后突然膨胀,像一次爆炸','Around 1050 it swelled suddenly, like an explosion'],
       rule:['地图上那片范围是影响,不是国界','The area on the map is influence, not a border'],
       money:['贝壳来自墨西哥湾,铜来自五大湖','Shells from the Gulf, copper from the Great Lakes'],
       power:['一筐一筐堆起来的土丘,就是权力证明','A mound raised basket by basket was the proof of power'],
       fall:['一个流行的解释,2021年实测没能证实','A popular explanation failed a field test in 2021'],
       legacy:['有人编出「消失的筑丘人种」来解释它','Some invented a vanished race of mound builders to explain it'] },
  q:{ born:['玉米从中美洲一路北传,大约在公元800年前后与豆类、南瓜一起在密西西比河中下游形成稳定的农业组合,粮食产量足以供养定居的大聚落。这片被考古学界称作 American Bottom 的河边低地土壤极肥,又正处在密西西比河与密苏里河、俄亥俄河的交汇附近——水路四通。卡霍基亚在1050年前后经历了一次急速扩张,考古学家称之为「大爆炸」。','Maize spread north from Mesoamerica and, around 800, settled into a stable farming package with beans and squash in the middle and lower Mississippi valley, yielding enough to support large permanent settlements. The floodplain there is exceptionally fertile and sits near where the Mississippi meets the Missouri and the Ohio — water routes in every direction. Around 1050 Cahokia expanded very fast, an episode archaeologists call its big bang.'],
      rule:['没有文字,所以政治结构只能靠遗迹推断,学界至今争论它是一个有强制力的酋邦、一个早期国家,还是若干群体的联合——所以图上那片范围是文化影响所及,不是国界。可以确定的是存在明显的等级:精英居于土丘顶上的建筑,平民住在平地;大型墓葬里有随葬的人牲与远方运来的珍品。城市有统一规划,主广场、土丘与住宅区按方位排布,还建有以立柱围成的圆阵(俗称「木阵」),用于观测日出方位、标定节气。','There is no writing, so its politics can only be inferred from what was built, and scholars still argue whether it was a coercive chiefdom, an early state, or a coalition of groups — so the area shaded on the map is the reach of a culture, not a border. What is clear is that rank existed: elites lived in buildings on top of the mounds and commoners on the flat, and large burials contain sacrificed retainers and prized goods brought from far away. The city was planned, with plaza, mounds and housing laid out on a common orientation, and it included rings of upright posts — a woodhenge — used to sight the sunrise and mark the turning of the year.'],
      money:['底盘是玉米农业,辅以采集与渔猎。真正让它显眼的是交换网:遗址里出土的贝壳来自墨西哥湾,铜来自五大湖上游,云母来自南阿巴拉契亚山一带,而卡霍基亚风格的陶器与人像则出现在数百公里外——这是一张覆盖北美大陆中部的交换网络,货物流动靠河与人力,当地既没有驮兽也没有车轮。','The base was maize farming with gathering, fishing and hunting alongside. What makes it stand out is exchange: the site has yielded marine shell from the Gulf of Mexico, copper from the upper Great Lakes and mica from the southern Appalachians, while pottery and figurines in Cahokian style turn up hundreds of kilometres away. This was an exchange network across the middle of the continent, moved by river and on foot, with neither draught animals nor the wheel.'],
      power:['力量的形式是组织而不是军队。僧侣丘用篮子一筐一筐堆起来,体积约六十二万立方米,是墨西哥以北最大的史前土方工程;这样的工程需要长期、有节奏地调动大量劳力,本身就是权力的证明。城外后来筑起两英里长的木栅,说明局势曾经紧张。全盛时的人口估计在一万到二万之间(低到六千、高到四万的估法都有,争议不小),按当时北美的标准是绝无仅有的规模。','Its power took the form of organisation rather than armies. Monks Mound was raised basketload by basketload to some 620,000 cubic metres, the largest earthwork north of Mexico; building it required moving a great deal of labour on a sustained schedule, which is itself the evidence of authority. A palisade two miles long was later thrown up around the centre, which says the times had turned tense. Population at its height is estimated between ten and twenty thousand, with figures as low as six thousand and as high as forty thousand also argued for — a scale unmatched anywhere in North America then.'],
      fall:['1350年前后卡霍基亚被基本废弃,原因尚无定论,几条线索并存:密西西比河的洪水在这一时期变得频繁;曾有观点认为建城与取薪的砍伐加剧了水患,但2021年对泛滥平原剖面的实测未能证实;气候在中世纪暖期之后转冷,玉米产量下降;木栅的出现说明冲突增加。多数研究者认为是这些因素叠加,而不是某一场灾难。密西西比文化本身并未随之消失,沿河的土丘聚落一直延续到欧洲人到来。','Cahokia was largely abandoned around 1350, and the cause remains unsettled, with several threads running together: flooding on the Mississippi became more frequent in this period; clearing woodland for building and fuel was long thought to have worsened the floods, but a 2021 study of the floodplain sediments found no evidence for it; the climate turned cooler after the Medieval Warm Period, cutting maize yields; and the palisade suggests conflict was rising. Most researchers see these compounding rather than a single catastrophe. The Mississippian world itself did not end with it — mound towns along the rivers continued until Europeans arrived.'],
      legacy:['16世纪德索托的远征队沿途仍见到成规模的土丘城镇与酋长,那是这一传统最早的欧洲文字记录之一;到18世纪初,法国人还在纳奇兹见到活着的大丘与酋长;随后欧洲传入的传染病使人口锐减。19世纪的美国人一度不肯相信这些土丘出自本地原住民之手,编造出「消失的筑丘人种」之说,史密森学会的系统调查最终否定了它——这段公案本身是北美考古史上的重要一页。卡霍基亚1982年列入世界文化遗产;僧侣丘至今仍立在圣路易斯城郊,可以走上去。','A sixteenth-century Spanish expedition still passed mound towns and paramount chiefs on its march, among the earliest European records of the tradition — and as late as the early eighteenth century the French still found living mounds and chiefs among the Natchez; introduced epidemics then cut the population sharply. In the nineteenth century Americans were widely unwilling to credit these mounds to the ancestors of Native peoples and invented a vanished race of mound builders, a claim the Smithsonian\'s surveys finally disposed of — an episode that is itself an important page in the history of North American archaeology. Cahokia was inscribed as a World Heritage site in 1982; Monks Mound still stands on the edge of St Louis, and you can walk up it.'] },
  d:'玉米北传之后,密西西比河与密苏里河交汇处的肥沃泛滥平原上长出北美最大的聚落;僧侣丘用篮子堆出六十二万立方米,是墨西哥以北最大的史前土方工程。贝壳来自墨西哥湾、铜来自五大湖——一张横跨北美中部的交换网。1350年前后废弃,洪水与冲突加剧几条线索并存,而流传很广的「砍伐导致水患」说已被2021年的实测否掉。' },
{ l:'am', s:'meso', v:2, n:'托尔特克与谷地诸邦', k:[[550,0],[900,.22],[1000,.3],[1150,.25],[1300,.2],[1428,0]], b:'特奥蒂瓦坎烧掉之后,墨西哥谷地换了一批小城主;其中图拉的托尔特克人后来被阿兹特克人当成文明本身的标准。',
  d:'550 年前后特奥蒂瓦坎的城中心被焚,墨西哥谷地此后三百年没有再出现压倒性的大城,取而代之的是一批各据山头的城邦。10 世纪前后,谷地西北的图拉成为新的中心,那里的人被后世称作托尔特克人;他们的金字塔顶上立着四米多高的石武士,而在一千公里外的尤卡坦,奇琴伊察有几乎一模一样的建筑与雕刻——两地谁影响了谁,争了一百多年仍无定论。图拉在 12 世纪中叶衰落,谷地重新碎成一堆互相攻伐的城邦,直到 1428 年阿兹特克人建立三方同盟。「托尔特克」这个词后来在纳瓦特尔语里变成了「工匠、有本事的人」的意思:阿兹特克贵族争相自称是托尔特克人的后代,把那个已经消失的城当作文明本身的标准。',
  e:{ n:'Toltecs and the Valley States', w:'Toltec', b:'After Teotihuacan burned the Valley of Mexico broke into small city-states — and the Toltecs of Tula became the Aztecs\' idea of civilization itself.', d:'Around 550 the centre of Teotihuacan was burned, and for three centuries no single city dominated the Valley of Mexico; a scatter of city-states held the ground instead. By about the tenth century Tula, northwest of the valley, had become the new centre, and its people are known as the Toltecs. Stone warriors more than four metres tall stand on top of its pyramid — and a thousand kilometres away in Yucatan, Chichen Itza has almost identical architecture and carving. Which place influenced which has been argued for over a century without resolution. Tula declined in the mid-twelfth century and the valley fragmented again until the Aztecs formed their triple alliance in 1428. The word "Toltec" later came to mean "craftsman, a person of skill" in Nahuatl: Aztec nobles competed to claim Toltec descent, taking a vanished city as the measure of civilization itself.', f:{ 'Peak':'Tula, 10th—12th c.', 'Center':'Tula; Cholula', 'Figures':'Ce Acatl Topiltzin (a king of legend)', 'Legacy':'The Atlantean warriors of Tula; "Toltec" as a word for skill' } },
  f:{ '鼎盛':'图拉(10—12世纪)', '中心':'图拉、乔卢拉', '人物':'塞·阿卡特尔·托皮尔岑(传说中的王)', '成就':'图拉的石武士、「托尔特克」成为「技艺」的代名词' },
  qh:{ born:['大城烧掉之后,谷地换成了一堆小城','After the great city burned, the valley became many small ones'],
       rule:['谁也压不住谁,联盟比征服有用','No one could dominate; alliance beat conquest'],
       money:['黑曜石、棉花与可可,靠背着走','Obsidian, cotton and cacao — all carried on backs'],
       power:['一千公里外,有一座几乎一样的城','A thousand kilometres away stands an almost identical city'],
       fall:['图拉散了,谷地又碎回一堆城邦','Tula came apart and the valley fragmented again'],
       legacy:['「托尔特克」后来的意思是「有本事的人」','"Toltec" came to mean "someone with skill"'] },
  q:{ born:['550 年前后特奥蒂瓦坎的城中心被焚,人口散去。此后三百年墨西哥谷地没有再出现压倒性的大城,取而代之的是一批各据一方的城邦——霍奇卡尔科、卡卡希特拉这样一批城在这一时期新起,而乔卢拉在特奥蒂瓦坎还在的时候就已经是大城。一座巨城消失之后,填进来的不是另一座巨城,而是许多座小城。','Around 550 the centre of Teotihuacan was burned and its population dispersed. For three centuries afterwards no city dominated the Valley of Mexico; instead a set of city-states rose in its place — Xochicalco and Cacaxtla newly, while Cholula had already been a large city while Teotihuacan still stood. What filled the space left by one huge city was not another huge city but many small ones.'],
      rule:['这几百年里没有一个能号令全谷地的政权,城邦之间靠联姻、结盟与朝贡维持局面,打起来也多是为了贡赋而不是灭国。10 世纪前后图拉成为最强的一个,但它的影响更像盟主而非帝国——阿兹特克人后来的三方同盟,用的还是这套办法。','For these centuries no single power commanded the whole valley; the city-states held together by marriage, alliance and tribute, and when they fought it was usually over tribute rather than to destroy one another. Tula became the strongest around the tenth century, but its reach looks more like leadership of a league than an empire — the Aztec triple alliance later worked the same way.'],
      money:['谷地没有大牲畜也没有轮子运货,一切靠人背。绿松石与黑曜石从北边来,可可与棉花从南边的低地来,盐、陶器与羽毛在城邦之间流转。图拉的位置正好卡在谷地与北方沙漠的交界,既做转口,也把农耕的边界往北推了一段——那条边界后来又退了回来。','The valley had no draft animals and no wheeled transport: everything moved on human backs. Turquoise and obsidian came from the north, cacao and cotton from the southern lowlands, while salt, pottery and feathers circulated among the city-states. Tula sat exactly where the valley meets the northern desert, handling that traffic and pushing the farming frontier north for a while — a frontier that later retreated again.'],
      power:['图拉的金字塔顶上立着四根石柱,雕成四米多高的武士,手里握着投矛器。奇怪的是在一千公里外的尤卡坦,奇琴伊察有几乎一模一样的柱廊、球场与雕刻——是托尔特克人打过去了,还是玛雅人学过来了,或者两边共享同一套东西?这个问题争了一百多年,至今没有定论。','Four stone columns carved as warriors over four metres tall, holding spear-throwers, stand on top of Tula\'s pyramid. Oddly, a thousand kilometres away in Yucatan, Chichen Itza has almost identical colonnades, ball courts and carving. Did Toltecs go there, did Maya borrow from here, or did both share one repertoire? The question has been argued for more than a century and is still open.'],
      fall:['12 世纪中叶图拉衰落,城被焚毁一部分,人口外流。谷地重新碎成一堆互相攻伐的城邦,北方的干旱又把一批批操纳瓦特尔语的人推进谷地——阿兹特克人正是最后到的一批。1428 年他们与另外两座城结成三方同盟,谷地才重新有了统一的主人。','Tula declined in the mid-twelfth century, part of it burned and its people drifted away. The valley broke up again into warring city-states, while drought to the north kept pushing Nahuatl-speaking groups down into it — the Aztecs were the last of these to arrive. Only in 1428, when they joined two other cities in a triple alliance, did the valley have a single master again.'],
      legacy:['最有意思的遗产是一个词。「托尔特克」(Tolteca)在纳瓦特尔语里后来不再只指一个族群,而是「工匠、有本事的人」的意思,「托尔特克性」几乎等于「文明」本身。阿兹特克的贵族争相声称自己是托尔特克人的后代,把王室世系往图拉上接;他们追记里那位托尔特克国王塞·阿卡特尔·托皮尔岑,连是不是真有其人学界都没有定论——一个后来者需要的古典时代,连国王都可以是补出来的。这件事在别处也发生过:后来者总要给自己找一个古典时代。','The most interesting legacy is a word. In Nahuatl "Tolteca" came to mean not only a people but a craftsman, someone of skill; "Toltecayotl" was close to "civilization" itself. Aztec nobles competed to claim Toltec descent and traced their royal lines back to Tula; Ce Acatl Topiltzin, the Toltec king of their accounts, may not have existed at all — scholars still argue it. A classical age a latecomer needs can be supplied, kings included. The pattern is not unique: latecomers everywhere look for a classical age to descend from.'] } },
{ l:'am', s:'meso', v:0, n:'阿兹特克', k:[[1428,0],[1500,.55],[1521,0]], b:'湖上都城堪比同期欧洲大城;亡于西班牙人与天花。',
  e:{ n:'Aztec', w:'Aztec Empire', b:'The lake city that stunned the conquistadors; felled by steel and smallpox.', d:'The island capital fed 200,000+ on floating gardens — the Spanish thought of Venice; but an empire that fed on war and sacrifice made enemies, and Cortés with 600 men, native allies and smallpox destroyed it in two years. Mexico City stands on its ruins; the eagle and serpent are its founding vision.', f:{ 'Peak':'Moctezuma II (1502–1520)', 'Center':'Tenochtitlan', 'Figures':'Moctezuma II', 'Legacy':'Chinampa agriculture, the lake capital' } },
  f:{ '鼎盛':'蒙特祖马二世(1502—1520)', '中心':'特诺奇蒂特兰', '人物':'蒙特祖马二世', '成就':'浮田农业、湖上都城' },
  qh:{ born:['来晚了,只分到湖里没人要的小岛','Latecomers, given only an island nobody wanted'],
       rule:['献祭既是信仰,也是震慑,也是祸根','Sacrifice was faith, and threat, and the seed of ruin'],
       money:['湖上堆出来的田,养活了二十多万人','Fields built out on the lake fed over two hundred thousand'],
       power:['它的强大和脆弱,是同一枚硬币两面','Its strength and its fragility were the same coin'],
       fall:['压垮它的是疫病和众叛亲离,不是枪炮','What broke it was disease and defection, not guns'],
       legacy:['巧克力、番茄、牛油果,都是那门语言的词','Chocolate, tomato and avocado are words from that language'] },
  q:{ born:['作为迟来者,墨西卡人只分到湖中无人要的小岛:他们按鹰立仙人掌的神谕在特斯科科湖心建城,先给强邻当雇佣兵;1428年与两个盟邦联手推翻旧霸主,三方同盟从此主宰墨西哥谷地。','Latecomers to the valley, the Mexica got only an unwanted island: following the omen of an eagle perched on a cactus, they built their city in Lake Texcoco and first hired out as mercenaries to stronger neighbors. In 1428 they joined two allied cities to overthrow the reigning power, and the Triple Alliance came to dominate the Valley of Mexico.'],
      rule:['这是一个贡赋帝国:被征服的城邦保留本地首领,按册缴纳棉布、可可与羽毛;君主「特拉托阿尼」从王族中推选产生。宗教把战争写进世界观——太阳需要人牲喂养,献祭既是信仰也是震慑,却也埋下众叛亲离的种子。','It was a tribute empire: conquered cities kept their own lords and paid scheduled tribute of cotton cloth, cacao and feathers, while the ruler, the tlatoani, was chosen from within the royal line. Religion wrote war into the cosmos — the sun had to be fed with human sacrifice, at once faith and terror — and that sowed the seeds of mass defection.'],
      money:['浮田是农业奇迹:湖上堆出的水上田一年多熟,养活都城二十余万人。特拉特洛尔科大市场据西班牙人记载每日数万人赶集,可可豆与棉布充当货币;「波奇特卡」商队远行千里,兼作帝国的耳目。','The chinampas were an agricultural marvel: fields built up on the lake yielded several harvests a year and fed a capital of over two hundred thousand. The great market of Tlatelolco drew crowds the Spanish reckoned in the tens of thousands daily, with cacao beans and cotton cloth serving as money; pochteca merchant caravans ranged far afield, doubling as the empire\'s eyes and ears.'],
      power:['靠武力与威慑:贵族战团以生擒俘虏论功,「荣冠战争」既练兵又补充人牲。但帝国只是一张松散的贡赋网——不驻军、不同化,臣服者恨而不服;它的强大与脆弱,是同一枚硬币的两面。','Force and fear: noble warrior orders won rank by taking captives alive, and the \'flower wars\' kept armies trained and altars supplied. Yet the empire was only a loose web of tribute — no garrisons, no assimilation — its subjects obedient and resentful at once. Its strength and its fragility were two faces of the same coin.'],
      fall:['单靠枪炮讲不通:科尔特斯的数百人之所以能成事,靠的是特拉斯卡拉等宿敌与心怀怨恨的附庸倒戈,土著盟军数以万计;1520年天花疫症席卷都城,连新即位的君主也病亡;1521年围城战切断水粮,特诺奇蒂特兰在饥饿与瘟疫中陷落。钢铁与马匹有作用,但主流叙事的核心是疫病与众叛亲离压垮了帝国。','Guns alone do not explain it: Cortés\'s few hundred men prevailed because old enemies like Tlaxcala and resentful subject cities switched sides, supplying tens of thousands of allied warriors. In 1520 smallpox swept the capital, killing even the newly installed ruler; in 1521 siege cut off water and food, and Tenochtitlan fell amid famine and plague. Steel and horses mattered, but in the mainstream account it was disease and mass defection that broke the empire.'],
      legacy:['墨西哥城就叠在都城的废墟上,国旗上的鹰蛇图腾来自建城传说;chocolate、tomato、avocado 这些词都源自纳瓦特语,今天仍有上百万人说这门语言;霍奇米尔科的水上花田,是浮田农业的活遗存。','Mexico City stands on the ruins of the old capital, and the eagle and serpent on the national flag come from the founding legend. Chocolate, tomato and avocado all entered our vocabulary from Nahuatl, a language over a million people still speak today; the floating gardens of Xochimilco are the chinampas\' living remnant.'] },
  d:'湖心岛都城以浮田农业养活二十余万人,规模令初见的西班牙人惊为威尼斯;以战养祭的帝国树敌过多,科尔特斯以六百人借土著盟军与天花之力,两年灭其国。今日墨西哥城就建在其废墟之上,国旗上的鹰蛇图腾即其建城传说。' },
{ l:'am', s:'meso', v:2, n:'印加', k:[[1438,0],[1520,.6],[1533,0]], b:'安第斯大帝国,南北纵贯四千公里;骤亡于征服者。',
  e:{ n:'Inca', w:'Inca Empire', b:'Four thousand km of empire run on knots and roads.', d:'No writing, no wheel, no iron — yet quipu knots and 30,000 km of stone roads governed 4,000 km and perhaps ten million people. Pizarro\'s 168 men, arriving amid civil war and smallpox, trapped and killed the emperor after taking his golden ransom. Machu Picchu survived intact, off the conquerors\' route.', f:{ 'Peak':'Huayna Capac (1493–1527)', 'Center':'Cusco', 'Figures':'Pachacuti, Atahualpa', 'Legacy':'Royal roads, Machu Picchu, quipu' } },
  f:{ '鼎盛':'瓦伊纳·卡帕克(1493—1527)', '中心':'库斯科', '人物':'帕查库特克、阿塔瓦尔帕', '成就':'约三万公里驿道、马丘比丘、结绳记事' },
  qh:{ born:['它没另起炉灶,接过了前人的东西','It did not start over: it took up what others had left'],
       rule:['统治的本质,是登记和再分配','The essence of rule was the register and the redistribution'],
       money:['几乎不用钱,也几乎没有市场','Almost no money, and almost no market'],
       power:['三万公里驿道,是这个帝国的神经','Thirty thousand kilometres of road were its nerves'],
       fall:['西班牙人还没到,天花已经先到了','Smallpox arrived before the Spaniards did'],
       legacy:['克丘亚语,今天还有几百万人在说','Quechua is still spoken by millions today'] },
  q:{ born:['库斯科谷地的一个山地小邦,据印加口述传统,在击退强敌昌卡人后由帕查库特克改制并开启扩张。它没有另起炉灶,而是接过瓦里等前人留下的梯田、道路与行政传统,在约一百年间把安第斯缝成一个帝国。','It began as a small highland polity in the Cusco valley — by Inca oral tradition, it was Pachacuti who, after repelling the Chanka, rebuilt the state and launched its expansion. Rather than starting from scratch, it picked up the terraces, roads and administrative traditions left by Wari and others, and in roughly a century stitched the Andes into an empire.'],
      rule:['萨帕·印卡自称太阳之子,帝国分为四方,官吏层层统辖直到户口;没有文字,结绳记事却把人口、粮仓与劳役记得清清楚楚;整村迁移的「米特马」制把新征服的人群掺进归顺已久的地区,防范反叛。统治的本质,是登记与再分配。','The Sapa Inca ruled as son of the Sun over an empire divided into four quarters, with officials administering down to the household. There was no writing, yet the khipu\'s knotted cords kept exact records of people, granaries and labor dues; under the mitmaq policy whole villages were resettled, mixing newly conquered peoples among long-loyal ones to forestall revolt. Rule, in essence, was registration and redistribution.'],
      money:['帝国几乎不用货币与市场:土地分属王室、神庙与村社,百姓以「米塔」轮班劳役代税——修路、耕种公田、从军;国家粮仓遍布全国,灾年开仓赈济,大军远征沿途取给。财政就是仓库与人力簿。','It ran almost without money or markets: land was divided among crown, temple and community, and people paid their tax in rotating mit\'a labor — building roads, farming state fields, serving in the army. State storehouses dotted the realm, opened in famine and provisioning armies on the march; the treasury was warehouses and labor rolls.'],
      power:['接力信使一日数百里传递王命,军队沿路进发,仓库随处补给。扩张先礼后兵——归顺者保留首领、并入帝国秩序,顽抗者才遭大军压境。','Relay runners carried royal orders hundreds of kilometres a day, and armies marched with storehouses waiting along the route. Expansion led with an offer before a threat — submit and keep your chiefs within the imperial order, or face the army.'],
      fall:['多因叠加:西班牙人尚未到达,天花已沿交通线先行传入,一般认为瓦伊纳·卡帕克即死于此疫;随之引爆阿塔瓦尔帕与瓦斯卡尔的继承内战,帝国自断筋骨。皮萨罗率168人趁乱在卡哈马卡设伏生擒阿塔瓦尔帕、次年将其处死,不少怨恨印加的族群倒向西班牙一方;此后抵抗仍延续数十年,比尔卡班巴的末代政权到1572年才覆灭。','The causes compounded: smallpox travelled ahead of the Spaniards along the routes of contact, and Huayna Capac is generally thought to have died of it, igniting the succession war between Atahualpa and Huascar that tore the empire\'s own sinews. Pizarro\'s 168 men exploited the chaos to ambush and later execute Atahualpa at Cajamarca, while peoples resentful of Inca rule sided with the Spanish; resistance still lasted decades, the last Inca state at Vilcabamba falling only in 1572.'],
      legacy:['石砌驿道至今仍有路段在使用,马丘比丘完整幸存,成为世界奇观;克丘亚语今天仍是数百万安第斯人的母语;梯田、驼羊与种土豆的农艺,连同尚未完全破解的结绳记事,都留给了后世。','Stretches of the stone roads are still walked today, and Machu Picchu survives intact as a wonder of the world. Quechua remains the mother tongue of millions across the Andes, and the terraces, the llamas and the art of potato farming — along with the still-undeciphered khipu — passed down to later generations.'] },
  d:'无文字、无车轮、无铁器,却以结绳记事与约三万公里的驿道网,治理南北四千公里、上千万人口;皮萨罗一百六十八人趁其内战与天花肆虐设局擒杀皇帝,黄金赎金到手后仍将其绞死。马丘比丘因不在征服者的路线上而完整幸存。' },
{ l:'am', s:'west', v:1, n:'西葡殖民美洲', k:[[1521,0],[1600,.6],[1700,.55],[1810,.4],[1826,0]], b:'白银、庄园与传教:三百年殖民重塑两个大陆。',
  e:{ n:'Iberian America', w:'Spanish colonization of the Americas', b:'Silver, haciendas and missions; the first global trade loop.', d:'Potosí\'s silver flowed to China by the Manila galleons and to Europe via Seville — the first truly global trade circuit; meanwhile epidemic and forced labor cut indigenous populations by perhaps ninety percent, among history\'s deepest demographic catastrophes.', f:{ 'Peak':'early 17th c. (Potosí silver at its height)', 'Center':'Mexico City, Lima', 'Figures':'Cortés, Las Casas', 'Keywords':'Potosí, galleon trade' } },
  f:{ '鼎盛':'17世纪前期(波托西白银顶峰)', '中心':'墨西哥城、利马', '人物':'科尔特斯、拉斯·卡萨斯', '关键词':'波托西银山、大帆船贸易' },
  qh:{ born:['原住民人口,一个多世纪里少了约九成','The native population fell by some nine tenths in a century'],
       rule:['按出身分层,这套等级维持了三百年','Ranked by birth, and it held for three hundred years'],
       money:['白银一头去欧洲,一头去中国','The silver went one way to Europe, the other to China'],
       power:['帝国的强大,是从矿井里挖出来的','The strength of the empire came out of the mines'],
       fall:['宗主国自己先垮了,美洲才走得掉','The mother country collapsed first, and America could leave'],
       legacy:['土地集中和阶层分化,一直留到今天','Concentrated land and layered class have lasted to this day'] },
  q:{ born:['征服之后是接管:西班牙在阿兹特克与印加的废墟上设立总督区,葡萄牙沿巴西海岸铺开种植园。殖民秩序建立在一场浩劫之上——旧大陆带来的天花、麻疹等疫病一波波扫过,加上战乱与强制劳役,原住民人口在一个多世纪里锐减约九成。','After conquest came administration: Spain set up viceroyalties on the ruins of the Aztec and Inca worlds, while Portugal spread plantations along the Brazilian coast. The colonial order rose upon a catastrophe — waves of Old World diseases such as smallpox and measles, compounded by war and forced labor, cut the indigenous population by roughly ninety percent within little more than a century.'],
      rule:['国王透过副王与王室法庭遥控万里之外的领地,印度群岛议事会统筹一切;教会与传教团既传教也治理,是另一套行政网络。社会按出身分层:半岛人居顶,土生白人次之,混血者、原住民与被贩来的非洲奴隶居于底层——这套等级维持了三百年。','The king governed from an ocean away through viceroys and royal courts, with the Council of the Indies overseeing it all; the church and its missions formed a second administration, converting and governing at once. Society was ranked by birth: peninsular Spaniards on top, American-born creoles next, with people of mixed descent, indigenous peoples and enslaved Africans below — a hierarchy that held for three centuries.'],
      money:['白银是这套体系的心脏:波托西与萨卡特卡斯的矿山靠强征原住民轮班劳役开采,白银经塞维利亚流入欧洲、经马尼拉大帆船流入中国——第一个真正的全球贸易循环由此成形。巴西的糖园则依赖被贩运的非洲奴隶,大庄园垄断着土地。','Silver was the heart of the system: the mines of Potosí and Zacatecas, worked by conscripted indigenous labor, sent bullion to Europe via Seville and to China via the Manila galleons — the first truly global trade circuit took shape around it. Brazil\'s sugar plantations ran on enslaved Africans shipped across the Atlantic, while great estates monopolized the land.'],
      power:['体系靠垄断与等级维持:王室垄断贸易航线,珍宝船队结队护航;教会规训人心;各阶层被出身钉在原位。对宗主国而言,美洲白银是欧洲争霸战争的军费——帝国的强大,直接从殖民地的矿井里挖出来。','The system held through monopoly and hierarchy: the crown monopolized the trade routes and sailed its treasure fleets in convoy, the church disciplined minds, and birth fixed each group in its place. For the mother countries, American silver bankrolled their wars in Europe — imperial power was dug straight out of colonial mines.'],
      fall:['三百年的积怨遇上外部震荡:土生白人不满官职与贸易被半岛人垄断,启蒙思想与美国、法国革命提供了榜样;1808年拿破仑入侵伊比利亚,王权的合法性随之崩解。玻利瓦尔与圣马丁领导的独立战争席卷大陆,巴西于1822年独立,到1826年,大陆上的殖民地已尽数脱离。','Three centuries of grievance met external shock: creoles resented the peninsular monopoly on office and trade, while the Enlightenment and the American and French revolutions offered a script. Napoleon\'s invasion of Iberia in 1808 shattered royal legitimacy; the independence wars led by Bolívar and San Martín swept the continent, Brazil declared independence in 1822, and by 1826 the mainland colonies were gone.'],
      legacy:['今日拉丁美洲的版图、语言与宗教,都定型于这三百年;作物与人群的洲际大交换改写了全世界的餐桌。混血社会由此而生;而殖民时代的土地集中与阶层分化,也被主流史学视为这片大陆长期不平等的历史根源。','The map, languages and religion of today\'s Latin America were all set in these three centuries, and the intercontinental exchange of crops and peoples rewrote diets across the world. Mixed societies were born here — and so were the concentrated landholding and social stratification that mainstream historians regard as deep roots of the continent\'s enduring inequality.'] },
  d:'波托西银山的白银,经马尼拉大帆船流入中国、经塞维利亚流入欧洲——第一次真正的全球贸易循环成形;而原住民人口因瘟疫与劳役锐减约九成,是人类史上最深的人口灾难之一。' },
{ l:'am', s:'west', v:2, n:'美国', k:[[1776,0],[1865,.4],[1918,.7],[1945,1],[1991,1],[2025,.95]], b:'两次大战后登顶,冷战胜出后独步全球至今。',
  e:{ n:'United States', b:'Enlightenment republic to sole superpower.', d:'Thirteen colonies founded a republic on Enlightenment ideas; expansion, immigration and the Civil War\'s aftermath made it the world\'s largest industrial power. Undamaged through two world wars, it topped the order it then built — dollar, carriers, alliances, Silicon Valley — and now faces China in renewed great-power competition.', f:{ 'Peak':'post-1945', 'Center':'Washington, New York, Silicon Valley', 'Figures':'Washington, Lincoln, FDR, Thomas Edison, Martin Luther King Jr., Grace Hopper', 'Legacy':'Written constitution, the Moon, the Internet' } },
  f:{ '鼎盛':'1945年后', '中心':'华盛顿、纽约、硅谷', '人物':'华盛顿、林肯、罗斯福、爱迪生、马丁·路德·金、格蕾丝·霍珀', '成就':'成文宪法、登月、互联网' },
  qh:{ born:['扩张成本极低,代价记在别人身上','Expansion came cheap, and someone else paid'],
       rule:['制度能容下谁,是一次次争来的','Who the system included was won, again and again'],
       money:['它掌握的是标准和规模,不只是产品','What it held was the standard and the scale'],
       power:['战后一度占了世界工业产出的一半','After the war it made about half the world output'],
       fall:['顶点同时也是争论的起点','The peak was also where the arguing began'],
       legacy:['月球至今是人唯一踏上过的另一个天体','The moon is still the only other world people have walked'] },
  q:{ born:['十三个英属殖民地因税收与代表权问题与母国决裂,1776年宣布独立,1783年获承认。它的起点有两个别处少见的条件:一是隔着大西洋,欧洲强权难以持续干预;二是一块面积巨大、资源齐备而原住民在建国前后被疾病、战争,以及此后一个世纪的驱逐与保留地制度大幅削弱的土地——这后一点是它扩张成本极低的原因,也是它历史上最沉重的部分。','Thirteen British colonies broke with the mother country over taxation and representation, declared independence in 1776 and were recognised in 1783. Two conditions at the start were unusual: an ocean that made sustained European interference hard, and a vast, well-endowed land whose native peoples were gravely reduced around and after its founding — by disease and war, and then by a century of removal and the reservation system — the second is why expansion cost it so little, and it is also the heaviest part of its history.'],
      rule:['1787年的宪法是今天仍在施行的成文国家宪法里最早的一部:三权分立、联邦与州分权、可以修改但门槛很高。这套设计刻意让决策变慢,以换取权力不集中。它并非一开始就适用于所有人——奴隶制到1865年才废除,种族隔离到1960年代才在法律上终结,妇女1920年才有全国选举权。制度的容纳范围是被一次次争取扩大的。','The constitution of 1787 is the oldest written national constitution still in force: separated powers, authority divided between federation and states, amendable but only with difficulty. The design deliberately makes decisions slow in exchange for keeping power dispersed. It did not apply to everyone from the start — slavery ended only in 1865, legal segregation only in the 1960s, and women gained the national vote in 1920. The range of people the system covered was widened by struggle, again and again.'],
      money:['先是农业与原料出口,内战后转向工业:铁路、钢铁、石油、汽车。20世纪它掌握的是另一样东西——标准与规模:流水线、连锁经营、信用消费,把「大批量、低成本」做成了方法。二战后美元成为国际储备货币,金融本身成为一项收入;近几十年则是软件、半导体设计与互联网平台。','First farming and raw exports; after the Civil War, industry — railways, steel, oil, cars. In the twentieth century what it commanded was something else: standards and scale. The assembly line, the chain store and consumer credit turned high volume at low cost into a method. After 1945 the dollar became the world\'s reserve currency and finance itself became a source of income; in recent decades it has been software, chip design and internet platforms.'],
      power:['资源与人口是底子,但决定性的是两次世界大战:本土未受战火,工业却全力开动,战后它占世界工业产出的一半左右。此后力量有三根支柱——遍布全球的军事基地与同盟体系、美元与美国主导的国际金融机构、以及大学与移民构成的科研体系(二战前后大批欧洲科学家迁入,直接改变了物理学与数学的重心)。','Resources and population were the base, but the two world wars were decisive: its homeland untouched while its industry ran flat out, it emerged with something like half the world\'s industrial output. Since then its strength has rested on three pillars — a global network of bases and alliances, the dollar and the institutions built around it, and a research system made of universities and immigration, into which a great wave of European scientists moved around the Second World War, shifting the centre of gravity of physics and mathematics.'],
      fall:['1991年苏联解体,冷战结束,美国成为唯一的超级大国——这既是它影响力的顶点,也是此后一切争论的起点:该不该、能不能长期扮演这个角色。此后三十年里,海外军事介入的代价、2008年的金融危机与国内政治的深度分裂,都与这个位置有关。','The Soviet Union dissolved in 1991 and the Cold War ended, leaving the United States the only superpower — at once the height of its influence and the starting point of every argument since about whether it should, or could, hold that position for long. The costs of military intervention abroad, the financial crisis of 2008 and a deepening split in domestic politics have all followed from it over the thirty years since.'],
      legacy:['成文宪法与联邦制被许多国家借鉴。技术上的一长串:电灯与电网、飞机、流水线、晶体管、集成电路、互联网、GPS——其中不少出自政府资助的研究再转为民用。文化输出的规模同样罕见:电影、爵士与摇滚、牛仔裤与快餐。月球至今是人类唯一踏上过的另一个天体——1969至1972年间共六次登月成功,12人走在月面上。','Written constitutions and federalism have been borrowed widely. The list of technologies is long: electric light and power grids, the aeroplane, the assembly line, the transistor, the integrated circuit, the internet, satellite navigation — many of them from government-funded research later turned to civilian use. Its cultural reach is of a scale few countries have matched: film, jazz and rock, blue jeans and fast food. The Moon is still the only other world human beings have set foot on: six landings between 1969 and 1972 put twelve people on its surface.'] },
  d:'十三州殖民地以启蒙理念立国,西进、移民与内战后工业产值跃居世界第一;两次大战本土无损而登顶,美元、航母、盟约与硅谷构成其霸权支柱。冷战胜出后独步三十年,如今与中国重新进入大国竞争时代。' },
{ l:'am', s:'west', v:1, n:'拉丁美洲诸国', k:[[1810,0],[1900,.3],[2025,.35]], b:'19世纪初相继独立;资源丰饶而发展曲折。',
  e:{ n:'Latin America', b:'Independence won, integration unfinished; culture abundant.', d:'The Bolívars won independence in Napoleon\'s shadow but not integration: caudillos, commodity dependence and debt cycles entangled two centuries. Culturally it never stopped producing — tango to magical realism.', f:{ 'Figures':'Bolívar, San Martín', 'Peak':'c. 1900 (export boom)', 'Center':'Mexico City, São Paulo, Buenos Aires' } },
  f:{ '人物':'玻利瓦尔、圣马丁', '鼎盛':'1900年前后(出口繁荣)', '中心':'墨西哥城、圣保罗、布宜诺斯艾利斯' },
  qh:{ born:['独立来得快,接手的却是旧的结构','Independence came fast; what it inherited was the old structure'],
       rule:['没有合成一个国家,散成十几个共和国','It never became one country, but a dozen republics'],
       money:['靠卖原料,价格一跌就是危机','Selling raw materials means a crisis whenever prices fall'],
       power:['长期是别人博弈的场所,不是主导者','Long a place where others contended, not a contender'],
       fall:['债务危机拖垮了经济,也拖垮了军政府','The debt crisis broke the economy, and the juntas with it'],
       legacy:['玉米、土豆、番茄、可可,都出自这里','Maize, potato, tomato and cacao all came from here'] },
  q:{ born:['1808年拿破仑入侵西班牙,把宗主国的权威打断了,美洲各殖民地趁机自立;玻利瓦尔与圣马丁分别从南北两端发动战争,到1825年西属美洲基本独立,巴西则由葡萄牙王子宣布独立,过程相对平和但仍有战事。独立来得快,但接手的是殖民时期留下的大地产制与阶层结构,这是此后两百年许多问题的起点。','When Napoleon invaded Spain in 1808 the authority of the mother country broke, and the American colonies moved to govern themselves; Bolívar and San Martín campaigned from the north and the south, and by 1825 Spanish America was largely independent, while Brazil separated peacefully under a Portuguese prince. Independence came quickly, but what it inherited were the great estates and the social ranks of the colonial era — the starting point of much that followed.'],
      rule:['独立后没有形成一个统一的国家,而是十几个共和国,边界多沿袭殖民时期的行政区划。19世纪普遍经历考迪罗(地方军事强人)统治与内战;20世纪多国在民选政府与军事政变之间反复,1980年代后普遍回到选举政治。巴西的帝制维持得最久(1822至1889年);墨西哥与海地也都短暂出现过皇帝。','Independence produced not one state but a dozen-odd republics, their borders largely those of colonial administrative divisions. The nineteenth century brought caudillo strongmen and civil wars almost everywhere; the twentieth saw many countries swing between elected governments and military coups, with a general return to electoral politics after the 1980s. Brazil\'s monarchy lasted longest, an empire from 1822 to 1889; Mexico and Haiti each had emperors briefly too.'],
      money:['长期是原料出口区:白银、硝石、咖啡、糖、香蕉、铜、石油、大豆。这条路径带来过繁荣——1900年前后阿根廷的人均收入一度接近西欧;但它也把经济绑在国际价格上,价格一跌就是危机。20世纪中期各国普遍尝试「进口替代工业化」,自己造原来要进口的东西,成效不一。','It has long been an exporter of raw materials: silver, nitrates, coffee, sugar, bananas, copper, oil, soy. That brought real prosperity — around 1900 Argentina\'s income per head approached western Europe\'s — but it also tied the economy to world prices, and a fall in prices meant a crisis. In the mid-twentieth century most countries tried import-substituting industrialisation, making at home what they had been buying, with mixed results.'],
      power:['资源与农业产能是它在世界经济中的位置:巴西、阿根廷是全球最大的农产品出口国之一,智利的铜、委内瑞拉的石油都曾举足轻重。政治上它长期是外部力量博弈的场所而非主导者;文化上则输出极多——魔幻现实主义文学、足球、探戈、桑巴与雷鬼顿。','Its place in the world economy rests on resources and farm output: Brazil and Argentina are among the largest agricultural exporters on earth, Chilean copper and Venezuelan oil have both counted heavily. Politically it has more often been the ground on which outside powers contended than a mover itself; culturally its exports are large out of all proportion — magical realist fiction, football, tango, samba and reggaeton.'],
      fall:['1980年代的债务危机是最近一次大的转折,通常被称作「失去的十年」:1982年墨西哥宣布无力偿债,危机迅速蔓延,多国出现恶性通货膨胀与经济倒退。代价之外也有一个后果——军政府普遍在这段时间失去合法性,阿根廷、巴西、智利先后回到选举政治,这一波民主化延续至今。','The debt crisis of the 1980s was the last great turning point, usually called the lost decade: Mexico declared in 1982 that it could not pay, the crisis spread quickly, and several countries went through hyperinflation and years of contraction. Alongside the cost came a consequence — military governments generally lost their legitimacy in these years, and Argentina, Brazil and Chile returned to electoral politics in a wave of democratisation that has held.'],
      legacy:['20世纪的文学「爆炸」把马尔克斯、略萨、科塔萨尔送进世界文学的中心,更早的博尔赫斯与诗人聂鲁达同样如此。足球在这里被改造成另一种踢法。农业上,原产于美洲的玉米、马铃薯、番茄、辣椒、可可与橡胶早已改变了全世界的饮食与工业。「解放神学」与参与式预算这类社会实验,也从这里传向别处。','The literary boom of the twentieth century put García Márquez, Borges and Neruda at the centre of world literature. Football was remade here into another way of playing the game. In agriculture, maize, the potato, the tomato, chilli, cacao and rubber all came from the Americas and long ago changed how the world eats and manufactures. Social experiments such as liberation theology and participatory budgeting have travelled outward from here too.'] },
  d:'玻利瓦尔们在拿破仑战争的间隙赢得独立,却未能赢得整合:强人政治、原料依赖与债务循环缠绕两百年;文化上却极为丰饶——从探戈到魔幻现实主义,拉美始终在输出想象力。' },
/* 大洋洲(v189 新泳道) */
{ l:'oc', s:'oceania', v:0, n:'澳大利亚原住民', k:[[-3500,0],[-3000,.62],[1000,.66],[1788,.64],[1830,.34],[1900,.1],[1967,.12],[2025,.18]], b:'已知延续最久的活文化,一条从图左边一直走到今天的带。',
  e:{ n:'Aboriginal Australians', b:'The longest continuing living culture known, a band running from the left edge of this chart to today.', d:'People reached Australia at least 65,000 years ago, crossing water to do it — the Madjedbebe rock shelter in Arnhem Land carries the oldest firm date, and some archaeologists argue for a later arrival nearer 50,000. There was no single people: at contact in 1788 the continent held something like 250 languages and many hundreds of dialects, each belonging to a Country. Knowledge travelled as songlines, sung routes that work as maps, law and history at once; at Budj Bim in what is now Victoria, channels and weirs cut into lava flows to farm eels have been dated to around 6,600 years ago, older than the pyramids of Giza. The British landing of 1788 was catastrophic — smallpox within a year, then land taken and frontier killings — and the population fell sharply. The band narrows but never ends: the 1967 referendum counted Aboriginal people in the census, the Mabo judgment of 1992 overturned the doctrine that the continent had belonged to no one, and languages are being brought back.', f:{ 'Span':'at least 65,000 years, still here', 'Centre':'the whole of Australia; Budj Bim (Victoria)', 'Legacy':'songlines, Budj Bim eel farming, the world\'s oldest continuing cultures' } },
  f:{ '鼎盛':'不以某一朝为盛,六万五千年不断', '中心':'澳大利亚全境;布吉毕姆(今维多利亚州)', '成就':'歌之途、布吉毕姆养鳗水渠、已知延续最久的活文化' },
  qh:{ born:['来的时候,得先渡过一片深海','They had to cross deep sea to get here'],
       rule:['几百个群体,每一群属于一片自己的地方','Hundreds of groups, each belonging to its own Country'],
       money:['六千六百年前就在挖水渠养鳗鱼','They were cutting channels to farm eels 6,600 years ago'],
       power:['歌能当地图用,唱着就知道往哪走','Songs that work as maps — you sing your way across'],
       fall:['1788年之后一年,天花就到了','Smallpox arrived within a year of 1788'],
       legacy:['1992年,法院推翻了「这块地本来没有主人」','In 1992 a court struck down the idea of empty land'] },
  q:{ born:['人类到达澳大利亚至少在六万五千年前——阿纳姆地的马杰德贝(Madjedbebe)岩厦给出了目前最硬的年代,也有考古学家主张更晚、接近五万年,这个争论还没结束。无论取哪个数,他们都是渡海来的:即使在海平面最低的冰期,澳大利亚与东南亚之间也始终隔着深海,必须靠某种船。这比已知最早的农业早了五万年,比金字塔早了六万年。「已知延续最久的活文化」是澳大利亚官方与学界的通行说法,也有人指出「连续性」很难度量、南部非洲的桑人同样古老——所以这里说的是「已知」。','People reached Australia at least 65,000 years ago — the Madjedbebe rock shelter in Arnhem Land gives the firmest date, though some archaeologists argue for a later arrival nearer 50,000, and the argument is not settled. Either way they came across water: even at the lowest sea levels of the ice ages, deep sea always lay between Australia and Southeast Asia, so some kind of boat was needed. That is fifty thousand years before the earliest known farming and sixty thousand before the pyramids. Calling it the longest continuing living culture is the standard phrase in Australia and among scholars, though others point out that continuity is hard to measure and that the San of southern Africa are just as old — which is why the word known is doing work here.'],
      rule:['这里从来不是一个国家,所以图上那条带是「这片大陆上的人」,不是一个政权。1788年英国人到来时,大陆上约有 250 种语言、数百种方言,每一群人属于一片被称作 Country 的地方——那个词不只是土地,还包含水、天空、生灵与对它们的责任。群体之间靠亲属制度、通婚与仪式交换连成网络,没有王也没有都城,规矩由长者与法(Law)来定。','This was never one state, so the band on the chart means the people of the continent, not a government. When the British arrived in 1788 there were something like 250 languages and many hundreds of dialects, and each group belonged to a place called Country — a word that covers water, sky and living things as well as land, and the duty of care owed to them. Groups were linked by kinship, marriage and ceremonial exchange rather than by kings or capitals, and the rules were held by elders and by Law.'],
      money:['过去常被简单说成「狩猎采集」,但近二十年的考古把这个说法改写了。维多利亚州西南的布吉毕姆(Budj Bim),贡迪杰马拉人在火山熔岩地上开凿水渠、筑坝、设置编织鱼笼来蓄养和捕捞短鳍鳗,已测定的年代约六千六百年前——比吉萨金字塔还早,是世界上已知最早的水产养殖系统之一,2019年列入世界文化遗产。另一项被长期低估的是「火棒农业」:有计划地小面积焚烧,既催生嫩草引来猎物,又减少大火的燃料积累。','It used to be summed up as hunter-gathering, but twenty years of archaeology has rewritten that. At Budj Bim in south-western Victoria the Gunditjmara cut channels through lava flows, built weirs and set woven traps to hold and harvest short-finned eels; the dated remains go back about 6,600 years — older than the pyramids at Giza — making it one of the earliest aquaculture systems known anywhere, and it was inscribed as a World Heritage site in 2019. The other long-underrated practice is fire-stick farming: planned small burns that brought fresh growth to draw game and kept fuel from building up for the big fires.'],
      power:['最惊人的技术不是器物,是记忆的组织方式。歌之途(songlines)是一串按顺序唱的歌,每一句对应路上的一处地形——唱完一段就走完一段路。同一条途可能跨越上千公里、经过多个语言群体,各段由不同的人保管,接力唱下去。它同时是地图、法典和史书。有研究者认为一些沿海故事保留了约一万年前海平面上升淹没海岸的记忆,这个解读有争议,但被认真讨论。','The most striking technology here is not an object but a way of organising memory. A songline is a sequence of verses sung in order, each matching a feature along a route — sing the section and you have travelled it. One line may run a thousand kilometres across several language groups, each stretch kept by different custodians and handed on. It is map, law code and history at once. Some researchers argue that certain coastal stories preserve the memory of seas rising and drowning the shore around ten thousand years ago; the reading is contested, but it is taken seriously.'],
      fall:['1788年第一舰队在悉尼湾登陆,一年之内天花就出现在原住民人群中,死亡极重(病毒来源至今有争论)。随后是土地被占、水源被断,以及持续百余年的边疆屠杀。1788年前的人口估计从三十万到超过一百万不等,分歧很大;可以确定的是二十世纪初降到了历史最低点。二十世纪还有「被偷走的一代」——儿童被政府依法从家庭带走,这项政策持续到1970年代。','The First Fleet landed at Sydney Cove in 1788 and within a year smallpox appeared among Aboriginal people, killing on a terrible scale (where the virus came from is still argued about). Land was taken and water sources cut off, and frontier killings went on for more than a century. Estimates of the population before 1788 range from three hundred thousand to over a million, and they differ sharply; what is certain is that it reached its lowest point in the early twentieth century. That century also brought the Stolen Generations — children removed from their families under law, a policy that ran into the 1970s.'],
      legacy:['这条带没有断过,这正是它最重要的地方。1967年公投以九成赞成票通过,原住民得以计入人口普查;1992年马博案判决推翻了「无主地(terra nullius)」原则——法院承认这块大陆在英国人到来之前是有主人的;2008年联邦政府就「被偷走的一代」正式道歉。今天约有 250 种语言中的一部分正在被重新教回给孩子,当代原住民艺术已成为国际艺术市场上重要的一支。','That the band never breaks is the most important thing about it. A referendum in 1967 passed with about ninety per cent in favour and Aboriginal people were counted in the census; the Mabo judgment of 1992 overturned the doctrine of terra nullius, with the court accepting that the continent had owners before the British came; and in 2008 the federal government formally apologised for the Stolen Generations. Some of those 250 languages are now being taught back to children, and contemporary Aboriginal art has become a significant presence in the international art market.'] },
  d:'至少六万五千年前渡海而来,已知延续最久的活文化——阿纳姆地的马杰德贝岩棚给出目前最早的确证年代,也有考古学家主张更接近五万年。不是一个国家,而是约 250 种语言、各有其地的数百个群体;歌之途既是地图也是法典,布吉毕姆的养鳗水渠比金字塔还早。1788年英国人登陆之后,天花在一年内传开,继以夺地与边疆屠杀,人口跌至谷底。1967年公投把原住民正式计入人口普查,1992年马博案推翻了「这片大陆原本无主」的法律说法,2008年政府道歉;色带变细却从未中断,失传的语言正在一门门被找回来。' },

{ l:'oc', s:'oceania', v:1, n:'拉皮塔·南岛航海者', k:[[-1500,0],[-1000,.34],[-800,.3],[-500,.12],[-200,0]], b:'带着猪、狗、鸡和作物上船,一路铺到无人的岛上。',
  e:{ n:'The Lapita voyagers', b:'They sailed with pigs, dogs, chickens and crops aboard, settling islands where no one lived.', d:'Around 1500 BC a distinctive dentate-stamped pottery appears in the Bismarck Archipelago and then spreads east astonishingly fast — Vanuatu, New Caledonia and Fiji by about 1000 BC, Tonga and Samoa a century or so later. The people who carried it spoke Austronesian languages whose deepest roots lie in Taiwan, and they did not travel light: pigs, dogs, chickens, taro, yam and breadfruit went aboard, which is why these were settlement voyages rather than exploration. They sailed outrigger and double-hulled canoes and navigated by stars, swells, cloud and birds. Then the expansion stopped for roughly 1,800 years — the long pause — before East Polynesia was reached after 1000 AD. Why it stopped, and why it started again, is one of the open questions of Pacific archaeology.', f:{ 'Peak':'c. 1000 BC', 'Centre':'the Bismarck Archipelago; Tonga and Samoa', 'Legacy':'dentate-stamped pottery, the sailing canoe, a transplanted farm' } },
  f:{ '鼎盛':'约公元前1000年', '中心':'俾斯麦群岛;汤加·萨摩亚', '成就':'齿印纹陶、远洋独木舟、把整座农场搬上船' },
  qh:{ born:['一种带齿印花纹的陶器,顺着太平洋一路出现','A pottery stamped with tiny teeth marks, right across the Pacific'],
       rule:['不是征服,他们去的岛上本来没有人','Not conquest — the islands they reached had no one on them'],
       money:['猪、狗、鸡、芋头、山药,全都上了船','Pigs, dogs, chickens, taro and yam all went aboard'],
       power:['靠星星、涌浪、云和鸟找路','They found their way by stars, swells, cloud and birds'],
       fall:['为什么停、又为什么重新开始,至今没答案','Why it stopped and why it began again is still unanswered'],
       legacy:['今天太平洋一千多种语言,源头在这条线上','More than a thousand Pacific languages trace back along this line'] },
  q:{ born:['公元前1500年前后,俾斯麦群岛(今巴布亚新几内亚东北)出现一种极有辨识度的陶器:用小齿状工具在湿陶上压出细密的几何纹样,考古学上按新喀里多尼亚的一处遗址命名为拉皮塔(Lapita)。这种陶器随后向东扩散的速度令人吃惊——约公元前1100年抵达瓦努阿图与新喀里多尼亚、前1000年前后到斐济,再过一两百年到达汤加与萨摩亚。','Around 1500 BC a highly recognisable pottery appears in the Bismarck Archipelago, north-east of today\'s Papua New Guinea: fine geometric patterns pressed into wet clay with a small toothed tool. Archaeologists named it Lapita after a site in New Caledonia. It then spread east at a startling pace — Vanuatu and New Caledonia by about 1100 BC and Fiji around 1000 BC, Tonga and Samoa a century or two after that.'],
      rule:['和站里其他几条人口流最不一样的地方在这里:他们迁入的是无人之地。班图人、突厥人、下南洋的华人,目的地都已经有人烟;而汤加、萨摩亚以东的岛屿在他们到达之前从没有人类居住。所以这不是征服也不是融合,是「人类第一次去到那里」。西边的美拉尼西亚情况不同,那里早有人住了几万年,拉皮塔人是与当地人混居、通婚的——今天该地区的遗传与语言构成保留着这次相遇。','This is where it differs most from the other migrations on this site: they moved into empty land. The Bantu, the Turks and the Chinese going south all arrived where people already lived; the islands east of Tonga and Samoa had never held a human being before they came. So this is neither conquest nor absorption — it is people reaching somewhere for the first time. Melanesia to the west was different: it had been inhabited for tens of thousands of years, and the Lapita people settled among the locals and married into them, which the genetics and languages of the region still record.'],
      money:['他们把一整座农场搬上了船。猪、狗、鸡这三种家畜,加上芋头、山药、面包果、香蕉、椰子——凡是能靠一段插条或一块块茎活下来的作物都带着。这不是探险的装备,是定居的装备:一艘船上装的是「到了就能开始过日子」的全套。也正因如此,这些作物与家畜今天在太平洋各岛的分布,本身就是这次扩散的地图。','They put an entire farm aboard. Pigs, dogs and chickens, together with taro, yam, breadfruit, banana and coconut — anything that could travel as a cutting or a tuber. This is not the kit of an expedition but of a settlement: what a canoe carried was everything needed to start living on arrival. Which is why the spread of those crops and animals across the Pacific islands today is itself a map of the migration.'],
      power:['船是双体或带舷外浮杆的独木舟,能顶风走之字。导航不靠仪器:记住星星升落的方位当罗盘用,读涌浪被岛屿折射后的形状判断陆地方向,看云底的颜色(泻湖会把绿反上去),跟着傍晚归巢的海鸟找岛。这套本领在二十世纪几乎失传,1976年复原的双体舟「Hōkūleʻa」号仅靠传统导航从夏威夷航抵塔希提,证明它确实可行——那次航行也点燃了太平洋的文化复兴。','The canoes were double-hulled or fitted with an outrigger and could work to windward on a zigzag. Navigation used no instruments: the rising and setting points of stars served as a compass, the shape of swells bending round an island pointed to land, the colour under a cloud betrayed a lagoon reflecting green, and seabirds heading home at dusk led to an island. The skill nearly died out in the twentieth century; in 1976 the rebuilt double canoe Hōkūleʻa sailed from Hawaii to Tahiti by traditional navigation alone and proved it worked — a voyage that also lit the Pacific cultural revival.'],
      fall:['到达汤加、萨摩亚之后,扩散停了大约一千八百年——考古学上称为「长停顿(the long pause)」。东波利尼西亚(社会群岛、马克萨斯等)直到公元1000年之后才有人定居。为什么停、为什么又重新开始,是太平洋考古最大的未解问题之一:一说再往东要顶信风、航程更长,需要船与导航的进一步改良;一说与厄尔尼诺带来的西风窗口有关。齿印纹陶本身在扩散途中逐渐简化、最终消失。','After Tonga and Samoa the expansion stopped for roughly eighteen hundred years — archaeologists call it the long pause. East Polynesia, the Society and Marquesas Islands, was not settled until after 1000 AD. Why it stopped and why it resumed is one of the biggest open questions in Pacific archaeology: one line of argument is that going further east meant beating against the trade winds over longer distances and needed better canoes and navigation; another points to westerly windows opened by El Niño. The dentate stamping itself grew simpler along the way and eventually disappeared.'],
      legacy:['这条线是南岛语族(Austronesian)扩散的东半段——语族最深的根系一般定在台湾,也有学者主张源头更靠南、过程更缓,这一点仍有争论。同一个语族的另一支向西航行,在公元500至800年间抵达马达加斯加——今天马达加斯加语仍属南岛语族,源头在婆罗洲。也就是说,同一群人的后代最东到了复活节岛、最西到了非洲东岸,横跨大半个地球。太平洋今天一千多种语言、以及后来的汤加、毛利、夏威夷,都在这条线的下游。','This line is the eastern half of the Austronesian expansion — the deepest roots of the family are usually placed in Taiwan, though some scholars argue for a source further south and a slower process, and it is not settled. Another branch of the same language family sailed west and reached Madagascar between about 500 and 800 AD — Malagasy is still an Austronesian language, with its roots in Borneo. The descendants of one people therefore ended up as far east as Easter Island and as far west as the coast of Africa, across most of the globe. The thousand-odd languages of the Pacific today, and Tonga, the Māori and Hawaii later on, all lie downstream of this line.'] },
  d:'公元前1500年前后,一种齿印纹陶在俾斯麦群岛出现,随即快得惊人地一路向东:约前1000年到瓦努阿图、新喀里多尼亚与斐济,再过百余年到汤加、萨摩亚。带着它走的人说南岛语,这支语言最深的根在台湾。与站里其他人口流最不同的一点:他们迁入的是无人之地。猪狗鸡与芋头山药全部上船,是定居而非探险;导航靠星、涌浪、云与海鸟。他们划的是舷外浮杆独木舟与双体舟。到汤加之后扩张停了约一千八百年(史称「长停顿」),要到公元1000年以后才进入东波利尼西亚——为什么停、又为什么重新开始,至今是太平洋考古没有答案的问题之一。' },

{ l:'oc', s:'oceania', v:2, n:'汤加帝国', k:[[900,0],[1250,.3],[1450,.26],[1600,.1],[1800,0]], b:'太平洋上靠船连起来的势力,首都有巨石门与石砌王陵。',
  e:{ n:'The Tuʻi Tonga', b:'A power held together by canoes, with a stone trilithon and terraced royal tombs at its capital.', d:'Tongan tradition dates the first Tuʻi Tonga to about 950 AD, and between roughly 1200 and 1500 the line drew Samoa, Fiji, Futuna and ʻUvea into a network held together by voyaging, tribute, marriage and ceremony. The capital at Muʻa on Tongatapu has terraced stone tombs, the langi, and the Haʻamonga ʻa Maui — three coral limestone slabs, the uprights weighing perhaps thirty to forty tonnes, raised around 1200. Historians disagree about the word empire: there were no garrisons and no governors, and influence was carried by prestige and exchange more than by force, so many prefer maritime chiefdom or network. Its reach contracted through the 1500s and 1600s, and the ceremonial title survived until 1865, long after the power behind it had gone.', f:{ 'Peak':'13th-15th c.', 'Centre':'Muʻa on Tongatapu; Tonga and Samoa', 'Legacy':'the Haʻamonga ʻa Maui trilithon, the langi tombs, a sea-borne network' } },
  f:{ '鼎盛':'13—15世纪', '中心':'穆阿(汤加塔布岛);汤加·萨摩亚', '成就':'哈阿蒙加巨石门、石砌梯形王陵、靠航海维持的联系网' },
  qh:{ born:['传说里第一位图伊汤加是天神的儿子','In the tradition the first Tuʻi Tonga was a god\'s son'],
       rule:['没有驻军也没有总督,靠船、联姻和仪式','No garrisons, no governors — canoes, marriages and ceremony'],
       money:['朝贡的东西自己会游、会长','What came as tribute could swim, or grow'],
       power:['三块几十吨的珊瑚石灰岩,一千年前立起来的','Three coral limestone slabs, tens of tonnes, raised around 1200'],
       fall:['名号留到1865年,权力早就没了','The title lasted until 1865; the power was long gone'],
       legacy:['别的岛都被人占过,它没有','Every other island group was taken; this one never was'] },
  q:{ born:['汤加口传史把第一位图伊汤加(Tuʻi Tonga)阿霍埃图定在公元950年前后,称他是天神与凡人女子之子——这类神圣王权的起源叙事在波利尼西亚很常见。考古上,汤加塔布岛的大型石构与聚落扩张确实集中在此后的两三百年,与口传的时间框架大体对得上。','Tongan oral history places the first Tuʻi Tonga, ʻAhoʻeitu, at around 950 AD and calls him the son of a god by a mortal woman — an origin of sacred kingship of a kind common in Polynesia. Archaeologically the large stone works and the growth of settlement on Tongatapu do cluster in the two or three centuries after that, which fits the oral timeframe well enough.'],
      rule:['「帝国」这个词要打个折扣。大约1200到1500年间,图伊汤加的影响确实覆盖了萨摩亚、斐济东部、富图纳与瓦利斯,但没有驻军,也没有派出去的总督;维系靠的是航海往来、朝贡、跨岛联姻和仪式上的尊崇。所以不少历史学家更愿意称它「海上酋邦」或「交换网络」而不是帝国。后来王权一分为三:图伊汤加保留神圣地位,实际统治交给另外两支——这是一次相当精巧的制度设计。','The word empire needs discounting. Between roughly 1200 and 1500 the Tuʻi Tonga\'s influence did cover Samoa, eastern Fiji, Futuna and ʻUvea, but there were no garrisons and no governors sent out; what held it together was voyaging, tribute, marriage across islands and ceremonial deference. Many historians therefore prefer maritime chiefdom or exchange network to empire. The kingship was later split three ways, the Tuʻi Tonga keeping the sacred standing while actual rule passed to two other lines — a rather elegant piece of institutional design.'],
      money:['财富的形式和大陆国家很不一样:朝贡的是芋头、鱼、树皮布(tapa)、编席、独木舟、红羽毛与鲸牙。斐济出产上好的硬木与独木舟,萨摩亚出细编席,汤加是中心节点——这是一张靠季风与洋流运转的物流网,而不是靠道路与仓库。所以它的强弱直接取决于航海能力,航海一衰,网络就散。','Wealth took a very different form from that of continental states: tribute came as taro, fish, bark cloth, fine mats, canoes, red feathers and whale teeth. Fiji supplied good hardwood and canoes, Samoa the finest mats, and Tonga was the hub — a logistics network run on winds and currents rather than roads and warehouses. Its strength therefore depended directly on seafaring, and when the voyaging weakened the network came apart.'],
      power:['穆阿的朗吉(langi)是石砌的梯形王陵,巨大的珊瑚石灰岩块经过切割拼接,至今仍在。更著名的是哈阿蒙加·阿·毛伊(Haʻamonga ʻa Maui)——两根立柱上架一根横梁的三石门,立柱重约三四十吨,约建于1200年,石材需从海边采出并运来。当地传说它是国王用来标定至日方位的,这个说法在1960年代经实测得到部分支持,但仍有争议。','At Muʻa the langi are terraced royal tombs of cut and fitted coral limestone, still standing. Better known is the Haʻamonga ʻa Maui, a trilithon of two uprights carrying a lintel, the uprights weighing perhaps thirty to forty tonnes and raised around 1200, the stone quarried at the shore and hauled inland. Local tradition says a king used it to mark the solstices, a claim partly supported by survey work in the 1960s but still argued over.'],
      fall:['16、17世纪影响范围逐步收缩:萨摩亚脱离,斐济各邦独立行事,远洋航行减少,内部王权分裂后又发生长期内战。神圣名号一直保留到1865年最后一位图伊汤加去世,但那时它早已只剩仪式意义。1845年图普一世统一各岛建立现代汤加王国,1875年颁布宪法。','Through the sixteenth and seventeenth centuries the reach contracted: Samoa broke away, the Fijian polities went their own way, long-distance voyaging fell off, and the divided kingship was followed by long civil wars. The sacred title survived until the last Tuʻi Tonga died in 1865, by which time it was purely ceremonial. In 1845 Tāufaʻāhau, as George Tupou I, united the islands into the modern Kingdom of Tonga and a constitution followed in 1875.'],
      legacy:['汤加是太平洋岛国中唯一从未被殖民的国家——1900至1970年间是英国的保护国,但始终保有自己的王室与内政,王统至今延续。穆阿的王陵与哈阿蒙加巨石门仍立在原处。萨摩亚、斐济的一些头衔与仪式至今保留着当年网络的痕迹,汤加的细编席在整个西波利尼西亚仍是最高规格的礼物。','Tonga is the only Pacific island nation never colonised — a British protectorate between 1900 and 1970, but it kept its own monarchy and ran its own internal affairs, and the line continues today. The royal tombs at Muʻa and the Haʻamonga ʻa Maui still stand where they were raised. Titles and ceremonies in Samoa and Fiji still carry traces of the old network, and Tongan fine mats remain the highest form of gift across western Polynesia.'] },
  d:'口传史把第一位图伊汤加定在约950年;1200—1500年间影响覆盖萨摩亚、斐济东部与瓦利斯,但没有驻军也没有总督,靠航海、朝贡、联姻与仪式维系,故「帝国」一词要打折扣。都城穆阿在汤加塔布岛上,留着层叠的石砌王陵(朗吉)与约1200年立起的哈阿蒙加巨石门——三块珊瑚灰岩,立柱一块估计三四十吨。史家为此更愿意称它「海上酋邦」或「网络」而不是帝国。16、17 世纪一路收缩,仪式性的名号一直留到1865年,那时它背后的实力早已不在;汤加是太平洋唯一未被殖民的国家。' },
{ l:'oc', s:'oceania', v:0, n:'南马都尔', k:[[900,0],[1200,.14],[1400,.2],[1550,.16],[1628,0]], b:'珊瑚礁上用玄武岩柱垒起来的石城,近百座人工小岛靠潮水水道相连。',
  e:{ n:'Nan Madol (the Saudeleur)', w:'Nan Madol', b:'A stone city stacked from basalt columns on a coral reef, close to a hundred man-made islets joined by tidal channels.', d:'Nan Madol sits on the reef flat off Temwen island on the south-east coast of Pohnpei, in what is now the Federated States of Micronesia. Close to a hundred artificial islets were built up from coral rubble and faced with columnar basalt laid log-cabin fashion, with channels between them that fill at high tide — the reason for the nickname Venice of the Pacific. Islet-building on the reef began around 900 AD, and dating of coral in the walls of the royal tomb Nandauwas puts the start of the great stone building at about 1180-1200. From here the Saudeleur, the Lords of Deleur, ruled the whole island of Pohnpei; tradition has the last of them overthrown around 1628 by Isokelekel from Kosrae, who set up the chiefly system Pohnpei still uses. No one wrote anything down at the time, so the story rests on archaeology and oral tradition. Nan Madol became a World Heritage site in 2016.', f:{ 'Peak':'13th-16th c.', 'Centre':'Nan Madol on Pohnpei', 'Legacy':'islets stacked from basalt columns, the Nandauwas tomb, a city on a reef' } },
  f:{ '鼎盛':'13—16世纪', '中心':'南马都尔(波纳佩岛)', '成就':'玄武岩柱垒成的人工岛群、南道瓦斯王陵、建在礁盘上的水道之城' },
  qh:{ born:['先在礁上填出小岛,再在岛上垒石头','First islets filled in on the reef, then stone stacked on top'],
       rule:['一个王朝管整座岛,首领们被要求住进石城','One dynasty ruled the island; its chiefs lived in the city'],
       money:['城里没有淡水也不种地,吃的全靠独木舟运来','No fresh water and no fields — everything came in by canoe'],
       power:['石柱像木头一样一层层横竖交叠','Basalt columns laid crosswise, layer on layer, like logs'],
       fall:['传说里三百三十三名战士渡海而来','In the story, three hundred and thirty-three warriors came over the sea'],
       legacy:['那套酋长制度,今天的波纳佩还在用','The chiefly system it left is still in use on Pohnpei'] },
  q:{ born:['波纳佩是加罗林群岛里的一座火山岛,东南岸的礁坪上先被人用珊瑚碎块填出一座座小岛,考古测年把这一步放在公元900年前后;再往上垒大石头,是约1180到1200年以后的事——这个年份来自对南道瓦斯王陵墙里珊瑚填料的铀钍测年。口传史说建城的是从西方来的两兄弟,试了好几处地方才选定这片礁盘。','Pohnpei is a volcanic island in the Carolines. On the reef flat off its south-east coast people first built up islets from coral rubble, a step that archaeological dating puts at around 900 AD; stacking the great stones on top came later, from about 1180-1200 — a date taken from uranium-thorium dating of the coral fill inside the walls of the royal tomb Nandauwas. Oral history says the city was founded by two brothers who came from the west and tried several sites before settling on this stretch of reef.'],
      rule:['统治者称绍德勒尔,意思是「德勒尔之主」,一个王朝从这座石城管着整座波纳佩岛——在密克罗尼西亚,这样把一整座大岛并在一个中心之下的例子不多。各地首领被要求住到南马都尔来,便于看管。城分两半:上城以祭祀与墓葬为主,下城管行政与居住,岛与岛之间靠涨潮时能行船的水道相连,所以有「太平洋的威尼斯」这个绰号。后来的绍德勒尔在口传里名声不好,被记成苛刻的暴君——这也是传说里他们被推翻的理由。','The rulers were called Saudeleur, Lords of Deleur, and from this stone city one dynasty governed the whole of Pohnpei — in Micronesia there are few cases of a large island held together under a single centre like this. The local chiefs were required to live at Nan Madol, where they could be watched. The city had two halves, an upper town of ritual and burial and a lower town of administration and dwelling, with channels between the islets that canoes could use at high tide — hence the nickname Venice of the Pacific. The later Saudeleur are remembered in tradition as harsh, and that is the reason the story gives for their fall.'],
      money:['礁盘上没有淡水,也没有可以种芋头和面包果的土地——支撑这座城的是全岛的贡赋,一船一船从波纳佩本岛运过来。有一座小岛专门养海鳗,当作神圣的动物,传说用海龟喂它们。所以南马都尔的存在本身就是一种权力展示:能让一整座岛养活一座不产粮的城。','The reef had no fresh water and no soil for taro or breadfruit — what kept the city going was tribute from the whole of Pohnpei, brought over canoe-load by canoe-load from the main island. One islet was kept for sacred eels, which tradition says were fed on turtle. Nan Madol was in that sense a display of power in itself: an entire island made to feed a city that grew no food.'],
      power:['建材是柱状玄武岩——火山岩冷却时自然裂成的多棱长柱,像一根根石头木料。工匠把它们横竖交叠着垒起来,和搭木屋一个办法。全城的石料据估计有七十多万吨,最大的一根柱子重达数十吨;南道瓦斯王陵的外墙至今最高处有七米多。石料从波纳佩岛别处的采石场运来,怎么运的至今没有定论:主流看法是用竹筏或独木舟趁涨潮浮运,岛上的传说则说是两兄弟念咒让石头自己飞过来的。','The building material was columnar basalt — volcanic rock that cracks naturally into long many-sided columns, like logs of stone. Builders laid them crosswise in alternating layers, the way a log cabin is built. The stone in the whole city is estimated at more than seven hundred thousand tonnes, the largest single columns weighing tens of tonnes, and the outer walls of the Nandauwas tomb still rise to more than seven metres at their highest. The stone came from quarries elsewhere on Pohnpei; how it was moved is not settled — the usual view is that it was floated on rafts or canoes at high tide, while island tradition says the two founding brothers made the stones fly by magic.'],
      fall:['口传史说,来自东边科斯雷岛的伊索克莱克尔带着三百三十三名战士渡海而来,推翻了最后一位绍德勒尔——这个数字是故事的一部分,不必当成统计。年份约1628年,是二十世纪初的民族学者按酋长世系一代代往回推算出来的,只能算大致。伊索克莱克尔建立了称作「南姆瓦基」的酋长制度,把岛分成几个酋邦;南马都尔此后仍被用于仪式,但慢慢没有人常住了,等欧洲人来到时,石城已大半荒废。','Oral history says Isokelekel came over the sea from Kosrae to the east with three hundred and thirty-three warriors and overthrew the last Saudeleur — the number is part of the story, not a count. The date, around 1628, was worked back generation by generation from chiefly genealogies by ethnographers in the early twentieth century, and is only rough. Isokelekel set up the chiefly system called the Nahnmwarki and divided the island into several chiefdoms; Nan Madol was still used for ceremony afterwards but slowly ceased to be lived in, and by the time Europeans arrived the stone city was largely deserted.'],
      legacy:['波纳佩的几个传统酋邦至今各有自己的南姆瓦基,和现代政府并行——这是伊索克莱克尔留下的。这座岛在1986年随密克罗尼西亚联邦独立。石城本身被红树林慢慢长满,2016年列入世界遗产,同时因为植被侵蚀与海水冲刷被列进濒危名录。对孩子来说最好记的一点是:这里的人没有金属工具,也没有轮子和役畜,却在海里垒起了一座城。','The traditional chiefdoms of Pohnpei each still keep their own Nahnmwarki, alongside the modern government — Isokelekel\'s legacy. The island became part of the independent Federated States of Micronesia in 1986. The stone city itself has slowly been overgrown by mangroves; it was listed as World Heritage in 2016 and, at the same time, put on the danger list because of the vegetation and the sea. The thing for a child to remember is this: the people here had no metal tools, no wheels and no draught animals, and they built a city in the sea.'] },
  d:'波纳佩岛东南礁坪上的石城:公元900年前后开始在礁上填出人工小岛,约1180年后用柱状玄武岩横竖交叠垒起高墙,近百座小岛靠涨潮时灌满的水道相连,因此得了个「太平洋的威尼斯」的别称;王陵南道瓦斯墙体里珊瑚的测年,把大规模石构的起点定在约1180—1200年。绍德勒尔王朝从这里统治整座岛,城里不产粮,全靠贡赋;传说约1628年被来自科斯雷的伊索克莱克尔推翻,他留下的酋长制度沿用至今。当时无人把这些写下来,整段故事靠考古与口传撑着。2016年列入世界遗产。' },
{ l:'oc', s:'oceania', v:1, n:'拉帕努伊·复活节岛', k:[[1150,0],[1400,.14],[1650,.18],[1722,.14],[1862,.06],[1888,0]], b:'世界上最偏远的有人岛之一,立起了近千尊石像。',
  e:{ n:'Rapa Nui (Easter Island)', b:'One of the most remote inhabited islands on earth, where close to a thousand stone figures were raised.', d:'Rapa Nui lies 3,500 km from the nearest continent and 2,000 km from the nearest inhabited island — one of the remotest inhabited places anywhere. Radiocarbon work since 2006 places settlement around 1200 AD, much later than the older estimates of 400-800 that are now largely set aside. Close to a thousand moai were carved from volcanic tuff at the Rano Raraku quarry, the largest raised one about ten metres tall, and moved across the island by means still argued over — the islanders say the statues walked, and experiments in 2012 showed that upright rocking with ropes can indeed move one. The island also produced rongorongo, the only writing system known from Oceania, still undeciphered. The story that the islanders destroyed their own environment and collapsed is popular but heavily contested: recent work argues that rats eating palm seeds, and then European contact — smallpox and the Peruvian slave raids of 1862-63, which took perhaps half the remaining population — did the decisive damage. Chile annexed the island in 1888.', f:{ 'Peak':'15th-17th c.', 'Centre':'Rapa Nui (Easter Island)', 'Legacy':'the moai, rongorongo, a settlement 3500 km from any continent' } },
  f:{ '鼎盛':'15—17世纪', '中心':'拉帕努伊(复活节岛)', '成就':'摩艾石像、朗格朗格文字、离大陆三千五百公里的定居点' },
  qh:{ born:['最近的邻居,在两千公里外','The nearest neighbours are two thousand kilometres away'],
       rule:['近千尊石像,最大的一尊十米高','Close to a thousand statues, the tallest about ten metres'],
       money:['岛上人说,石像是自己走过去的','The islanders say the statues walked there'],
       power:['大洋洲唯一的文字,至今没人读得懂','The only writing in Oceania, and no one can read it'],
       fall:['「自己毁掉环境」这个说法,争议很大','That they wrecked their own island is a much-disputed story'],
       legacy:['1862年的一次绑架,几乎带走了一半人','A raid in 1862 carried off perhaps half of those left'] },
  q:{ born:['拉帕努伊离最近的大陆(南美)约三千五百公里,离最近的有人岛也有两千公里,是世界上最偏远的有人岛之一。定居年代经过一次重要修正:早期估计在公元400至800年,而2006年以后一批更严格的碳十四测年把它推到约1200年,现在这个晚近的年代是主流。能在这样的距离上找到这么小的一个点,本身就是波利尼西亚导航术的极限证明。','Rapa Nui lies about 3,500 km from the nearest continent, South America, and 2,000 km from the nearest inhabited island — one of the most remote inhabited places on earth. The date of settlement has been substantially revised: early estimates ran from 400 to 800 AD, but a set of stricter radiocarbon dates from 2006 onward moved it to around 1200, and that later date is now mainstream. That anyone found so small a target at such a distance is itself proof of how far Polynesian navigation could reach.'],
      rule:['社会按亲属集团(mata)划分地界,各占一段海岸,首领世袭。摩艾(moai)几乎都立在海边的石台(ahu)上,面朝内陆而不是大海——它们看的是自己的村子,通常认为代表已故的祖先,守护着后人。近千尊石像里有近一半仍留在采石场,雕到一半就停了。','Society was organised into kin groups, each holding a stretch of coast under a hereditary chief. Almost all the moai stand on stone platforms near the shore and face inland rather than out to sea — they look at their own village, and are generally understood to represent ancestors watching over their descendants. Of the close to a thousand figures, nearly half remain in the quarry, abandoned part-carved.'],
      money:['岛上靠番薯、芋头与鸡过活,还发展出用碎石覆盖地面保墒的旱地耕作(lithic mulching)来对付缺水。石像用拉诺拉拉库火山口的凝灰岩雕成,最大的一尊立起来的约十米高、近八十吨。怎么搬过去的是最有名的谜:岛上口传一直说石像是「走」过去的。2012年一次实验用三组绳索让复制品左右摇摆前行,确实走动了,与口传吻合;另一派主张是放倒后用木橇拖运。两说至今并存。','The island lived on sweet potato, taro and chickens, and developed a dryland farming method of covering the ground with broken stone to hold moisture. The figures were carved from volcanic tuff in the crater of Rano Raraku, the largest one raised standing about ten metres and weighing close to eighty tonnes. How they were moved is the famous puzzle: island tradition has always said the statues walked. An experiment in 2012 used three teams with ropes to rock a replica from side to side and it did indeed walk forward, matching the tradition; others argue they were laid down and dragged on wooden sledges. Both readings are still alive.'],
      power:['岛上产生了朗格朗格(rongorongo)——木板上刻的成行符号,是大洋洲已知唯一的书写系统。存世仅二十余件,至今没有被释读,甚至它究竟是完整的文字、还是记忆辅助的符号系统,都还没有定论。最后一批能读它的人在19世纪的灾难中死去或被掳走,线索就此断了。','The island produced rongorongo — rows of signs carved on wooden boards, the only writing system known from Oceania. Just over twenty pieces survive, none of them deciphered, and it is not even settled whether it is full writing or a system of memory prompts. The last people who could read it died or were carried off in the disasters of the nineteenth century, and the thread was cut.'],
      fall:['流传最广的说法是:岛民砍光了棕榈林去运石像,导致土壤流失、社会崩溃、自相残杀——这个「生态自毁」的故事很有名,但争议极大。近二十年的研究提出另一条线索:随人上岛的波利尼西亚鼠啃食棕榈种子,使森林无法更新,而岛民其实发展出了石堆覆盖(lithic mulching)等应对旱地的耕作办法,人口未必崩溃。真正致命的是欧洲人到来之后:天花等疾病,以及1862—63年秘鲁的绑架船掳走了可能一半的人口,归还者又带回天花。','The best-known version says the islanders felled the palm forest to move statues, lost their soil, collapsed and turned on each other — a famous story of ecological self-destruction, and a much-disputed one. Twenty years of work has offered another thread: the Polynesian rat, which arrived with people, ate the palm seeds so the forest could not renew itself, while the islanders in fact developed dryland farming methods such as covering ground with stones, and the population need not have collapsed. What was decisive came with Europeans: disease, and then the Peruvian slaving raids of 1862-63, which carried off perhaps half of those remaining, with the few who returned bringing smallpox back.'],
      legacy:['1722年荷兰人罗赫芬在复活节当天到达,岛因此得名。1888年智利兼并该岛,岛民直到1966年才获得智利公民权。今天约有八千人居住,拉帕努伊语仍在使用,岛屿1995年列入世界文化遗产。它的名声与它被讲述的方式一样值得注意:「一个社会毁掉自己家园」的寓言在二十世纪被反复引用,而当代拉帕努伊人一直指出,真正毁掉他们的是外面来的船。','The Dutchman Roggeveen arrived on Easter Sunday 1722, which is how the island got its European name. Chile annexed it in 1888 and the islanders did not receive Chilean citizenship until 1966. About eight thousand people live there now, the Rapa Nui language is still spoken, and the island was inscribed as a World Heritage site in 1995. Its fame is as notable as the way it has been told: the parable of a society wrecking its own home was quoted again and again through the twentieth century, while Rapa Nui people have kept pointing out that what wrecked them arrived by ship.'] },
  d:'离最近大陆三千五百公里、离最近的有人岛两千公里,是世界上最偏远的有人岛之一。定居年代经2006年之后的碳十四工作修正为约1200年,早先400—800年的估计已基本弃用。近千尊摩艾在拉诺拉拉库采石场用火山凝灰岩凿出,面朝内陆守护村落,立起来最高的一尊约十米;怎么搬到位至今两说并存——岛民自己的说法是石像「走过去」的,2012年的实验证明用绳子左右摇晃确实能让它走。朗格朗格是大洋洲唯一的文字,至今未释读。「生态自毁」的流行叙事争议极大,近年的研究认为真正致命的是老鼠吃掉棕榈种子、以及欧洲人带来的天花——加上1862—63年秘鲁绑架船掳走可能一半人口,这一条是确凿的。1888年智利吞并该岛。' },

{ l:'oc', s:'oceania', v:0, n:'毛利', k:[[1250,0],[1500,.3],[1769,.4],[1840,.32],[1900,.12],[1975,.16],[2025,.24]], b:'最后被人类定居的大片土地,七百年就写出一部完整的历史。',
  e:{ n:'Māori', b:'The last large landmass humans settled, with a full history written in seven hundred years.', d:'New Zealand was the last sizeable habitable land on earth to be settled, reached from East Polynesia around 1280-1320 — so recently that the date can be fixed within a few decades. The newcomers found a country of birds with no land mammals but bats; the moa, up to 3.6 metres tall, was hunted out within roughly 150 years, and the giant eagle that preyed on it went with them. Māori built fortified pā, developed a distinctive carving tradition, and made the first sustained European contact with Cook in 1769. The Treaty of Waitangi of 1840 was signed in two versions whose wording differs at the decisive point — the English text cedes sovereignty, the Māori text cedes kāwanatanga, governance, while keeping tino rangatiratanga, full chieftainship — and that gap has driven New Zealand politics ever since. Land wars, confiscation and a population low point followed; then a revival. Te reo Māori became an official language in 1987 and the Waitangi Tribunal has been settling historical claims since 1975.', f:{ 'Peak':'16th-18th c.', 'Centre':'Aotearoa (New Zealand); Waitangi', 'Legacy':'the pā, whakairo carving, the haka, te reo Māori' } },
  f:{ '鼎盛':'16—18世纪', '中心':'奥特亚罗瓦(新西兰);怀唐伊', '成就':'帕堡寨、木雕传统、哈卡、毛利语' },
  qh:{ born:['人类最后住上的一块大地方,就是这里','The last big land people ever moved into'],
       rule:['到的时候,这里只有鸟,没有走兽','They arrived to a country of birds and no land mammals'],
       money:['三米六高的恐鸟,一百五十年就没了','The moa stood 3.6 metres tall and was gone in 150 years'],
       power:['山头上的帕堡,一层壕沟一层栅栏','Pā on the hilltops, ditch behind bank behind palisade'],
       fall:['同一份条约,两种文字写的不是一回事','One treaty, two texts, and they do not agree'],
       legacy:['1987年,毛利语成了官方语言','In 1987 te reo Māori became an official language'] },
  q:{ born:['新西兰是地球上最后一块被人类定居的大片宜居陆地。来自东波利尼西亚(社会群岛、库克群岛一带)的航海者约在1280至1320年间抵达——近到可以把年代定到几十年之内,靠的是火山灰层、鼠骨与树轮的交叉定年。他们把这片地方叫奥特亚罗瓦(Aotearoa)。与热带岛屿相比这里冷得多,带来的芋头、番薯只有部分能种活,番薯(kūmara)后来成了主粮,需要挖储藏窖过冬——这是一次真正的重新适应。','New Zealand was the last sizeable habitable land on earth that people moved into. Voyagers from East Polynesia, the Society and Cook Islands, arrived between about 1280 and 1320 — recently enough that the date can be pinned within a few decades, using volcanic ash layers, rat bones and tree rings together. They called the place Aotearoa. It was far colder than the tropical islands, only some of the crops they brought would grow, and the kūmara or sweet potato became the staple, needing storage pits to get through winter — a genuine readaptation.'],
      rule:['社会以部落(iwi)与亚部落(hapū)为单位,首领(rangatira)靠出身与实绩共同确立,重大事情在集会场(marae)上当众商议。没有全岛统一的政权,所以图上那条带指的是这片土地上的毛利世界。系谱(whakapapa)是社会的骨架:一个人是谁,取决于他能把自己接到哪条祖先线上。','Society was built on iwi and hapū, tribe and sub-tribe, with rangatira whose standing rested on both descent and achievement, and matters of weight settled in public on the marae. There was no single authority over the islands, so the band on the chart means the Māori world across this land. Whakapapa, genealogy, is the frame of the whole society: who a person is depends on the ancestral line they can trace themselves to.'],
      money:['他们到达的是一个只有鸟的国度——除蝙蝠外没有陆生哺乳动物,鸟类因此长得又大又不会飞。最大的恐鸟(moa)站起来可达三米六。这些鸟从未遇到过人类这样的捕食者,约一百五十年内九种恐鸟全部灭绝,以恐鸟为食的哈斯特鹰(翼展近三米,世界上已知最大的鹰)随之消失。这是人类到达一片新土地之后最快、最彻底的一次生态改变之一,毛利口传中也保留着「祖先吃光了大鸟」的记忆。','They arrived in a country of birds — no land mammals except bats, so birds had grown large and flightless. The biggest, the moa, stood up to 3.6 metres. These birds had never met a predator like people, and within roughly 150 years all nine moa species were extinct, taking with them Haast\'s eagle, which hunted them and had a wingspan of nearly three metres, the largest eagle known. It was one of the fastest and most complete ecological changes anywhere after people arrived, and Māori tradition itself keeps the memory that the ancestors ate the great birds.'],
      power:['帕(pā)是筑在山脊与高地上的设防聚落,靠壕沟、土垒与木栅层层设防,全国已记录五千座以上,密度极高——说明部落之间的竞争长期存在。工艺上,木雕(whakairo)、绿石(pounamu)器与编织自成体系;哈卡(haka)是仪式性的挑战与致敬,今天因橄榄球队而全世界都认识。1807至1837年的「火枪战争」是一次剧变:少数部落先拿到欧洲火枪,战争烈度骤增,死者数以万计,部落格局被彻底改写。','A pā was a fortified settlement on a ridge or high ground, defended by successive ditches, banks and palisades; over five thousand have been recorded across the country, a very high density, which says competition between tribes was long-running. In craft, whakairo carving, pounamu greenstone work and weaving formed traditions of their own, and the haka is a ceremonial challenge and salute, known worldwide today through rugby. The Musket Wars of 1807-37 were a violent upheaval: a few tribes obtained European guns first, the intensity of warfare jumped, tens of thousands died and the tribal map was rewritten.'],
      fall:['1840年的怀唐伊条约是新西兰历史的枢纽,也是它最大的争点:条约有英文与毛利文两个文本,关键处说的不是一回事。英文本写的是各部落把主权(sovereignty)让与英王;毛利文本让出的是 kāwanatanga(治理权),同时明确保留 tino rangatiratanga(完全的酋长权)。多数首领签的是毛利文本。此后是土地大量流失、1845至1872年的新西兰土地战争、以及对「叛乱」部落的土地没收;毛利人口在1890年代跌至约四万的低点。','The Treaty of Waitangi of 1840 is the hinge of New Zealand history and its largest dispute: it exists in an English and a Māori text, and at the decisive point they do not say the same thing. The English text has the chiefs cede sovereignty to the Crown; the Māori text cedes kāwanatanga, governance, while expressly retaining tino rangatiratanga, full chieftainship. Most chiefs signed the Māori text. What followed was heavy loss of land, the New Zealand Wars of 1845-72, and confiscation from tribes deemed to be in rebellion; the Māori population fell to a low of about forty thousand in the 1890s.'],
      legacy:['这条带没有终点。1975年设立怀唐伊仲裁庭,专门审理历史索赔并促成和解,已有多起大宗和解达成并附有官方道歉;1987年毛利语成为官方语言,「语言巢」幼儿园把语言教回给孩子。今天约百分之十七的新西兰人认同为毛利人。国名 Aotearoa 与英文名并用,议会有保留席位,而毛利文本与英文本之间那道缝隙,至今仍是这个国家政治的中心议题之一。','The band has no end point. The Waitangi Tribunal was set up in 1975 to hear historical claims and drive settlements, and several large settlements have been reached with formal apologies attached; te reo Māori became an official language in 1987, and language-nest preschools have been teaching it back to children. About seventeen per cent of New Zealanders now identify as Māori. Aotearoa is used alongside the English name, parliament has reserved seats, and the gap between the Māori and English texts remains one of the central questions in the country\'s politics.'] },
  d:'地球上最后一块被人类定居的大片陆地,约1280—1320年从东波利尼西亚抵达,年代近到能定到几十年内。到达时这里除蝙蝠外没有陆生哺乳动物,满地是鸟:三米六高的恐鸟在约一百五十年内被猎绝,以它为食的巨鹰也跟着消失。1769年库克到访,是与欧洲人第一次持续的接触。帕堡遍布全国;1807—37年火枪战争改写部落格局。1840年怀唐伊条约的英文本与毛利文本在「主权」与「治理权」上说的不是一回事,英文本让渡的是主权,毛利文本让渡的是「治理权」而保留「完全的酋长权」,这道缝隙至今是新西兰政治的中心议题。此后是土地战争、没收与人口低谷,再之后是复兴:1975年起怀唐伊法庭受理历史索赔,1987年毛利语成为官方语言。' },

{ l:'oc', s:'oceania', v:2, n:'夏威夷王国', k:[[1780,0],[1810,.3],[1850,.34],[1880,.28],[1893,.12],[1898,0]], b:'太平洋上被国际承认的独立王国,亡于一场由种植园主发动的政变。',
  e:{ n:'The Kingdom of Hawaiʻi', b:'An independent kingdom recognised by the powers, ended by a coup of planters.', d:'Kamehameha I unified the islands by 1795 (Kauaʻi joining by agreement in 1810), using European guns and advisers alongside Hawaiian organisation. The kingdom won recognition from Britain, France and the United States in the 1840s and ran embassies and treaties like any other state. Disease was catastrophic — a population of several hundred thousand at contact in 1778 fell to about forty thousand by the 1890s. The Māhele land division of 1848 opened land to private ownership and much of it passed to sugar planters; the 1887 Bayonet Constitution was forced on the king at gunpoint. In 1893 a committee of mostly American planters, with US marines landed in support, deposed Queen Liliʻuokalani. President Cleveland investigated and called it unlawful, but Congress annexed the islands in 1898. In 1993 the United States formally apologised for the overthrow.', f:{ 'Peak':'19th c.', 'Centre':'the Hawaiian Islands', 'Figures':'Kamehameha I, Liliʻuokalani', 'Legacy':'hula, the Hawaiian language, a case of annexation the United States later apologised for' } },
  f:{ '鼎盛':'19世纪', '中心':'夏威夷群岛', '人物':'卡美哈梅哈一世、莉莉乌欧卡拉尼', '成就':'呼拉舞、夏威夷语、一桩美国后来正式道歉的兼并' },
  qh:{ born:['一个人用了十几年,把散着的岛并成一国','One man spent a dozen years making scattered islands into one state'],
       rule:['有大使、有条约,列强都承认它','It had ambassadors and treaties, and the powers recognised it'],
       money:['土地一改成私产,大半就到了糖厂主手里','Once land could be sold, the planters got most of it'],
       power:['1887年那部宪法,是拿枪逼着国王签的','The 1887 constitution was signed at gunpoint'],
       fall:['1893年政变,美国军舰就在港里','In 1893 the coup came with a US warship in the harbour'],
       legacy:['1993年,美国国会为这件事正式道歉','In 1993 the US Congress formally apologised for it'] },
  q:{ born:['1778年库克到达时,夏威夷群岛分属几位互相争战的酋长。卡美哈梅哈一世用了十余年,把欧洲火枪、火炮与顾问同夏威夷自身的组织方式结合起来,1795年基本统一各岛,考艾岛于1810年以协议方式加入。这是波利尼西亚少见的由分立酋邦走向统一王国的案例。','When Cook arrived in 1778 the Hawaiian islands were held by several chiefs at war with one another. Kamehameha I spent a dozen years combining European guns, cannon and advisers with Hawaiian ways of organising, and by 1795 had unified most of the group, with Kauaʻi joining by agreement in 1810. It is an uncommon Polynesian case of separate chiefdoms becoming a single kingdom.'],
      rule:['王国有成文宪法(1840年起)、议会、最高法院与常驻外交使节。1840年代,英国、法国与美国先后承认夏威夷为独立国家,它与二十多个国家签有条约——按当时的国际法,这是一个正常的主权国家,不是保护地也不是殖民地。这一点在后来的争论中至关重要。','The kingdom had a written constitution from 1840, a legislature, a supreme court and resident diplomats abroad. In the 1840s Britain, France and the United States each recognised Hawaii as an independent state, and it held treaties with more than twenty countries — by the international law of the day an ordinary sovereign state, not a protectorate or a colony. That point matters greatly in the arguments that followed.'],
      money:['经济的转折是1848年的「大分地(Māhele)」:传统上土地由酋长按等级分配、平民有使用权,改革把土地变成可买卖的私产。用意之一是防止外人整片夺占,结果却相反——多数平民没能完成登记,而1850年又立法允许外国人取得永久业权,大片土地在数十年内落入制糖种植园主手中,其中许多是美国人后裔。糖业随后主导了整个经济,并带来了来自中国、日本、葡萄牙与菲律宾的契约劳工,夏威夷的人口构成从此改变。','The economic turning point was the Māhele of 1848: land had traditionally been allotted by chiefs in a hierarchy with commoners holding use rights, and the reform turned it into property that could be bought and sold. One aim was to stop outsiders seizing it wholesale; the effect was the opposite — most commoners never completed their registrations, a law of 1850 let foreigners hold land outright, and within decades much of it had passed to sugar planters, many of them of American descent. Sugar then dominated the economy and brought indentured labourers from China, Japan, Portugal and the Philippines, changing the make-up of the population for good.'],
      power:['1887年的「刺刀宪法」是转折点:一批以种植园主与商人为主的势力以武力相胁,迫使卡拉卡瓦国王签署新宪法,大幅削夺王权,并按财产资格限制选举权——多数原住民与亚裔劳工因此失去投票权。名字本身就说明了性质:那是拿枪逼着签的。','The Bayonet Constitution of 1887 was the turn: a group made up largely of planters and merchants forced King Kalākaua at gunpoint to sign a new constitution that stripped much of the crown\'s power and set property qualifications for voting, which removed the franchise from most Native Hawaiians and Asian labourers. The name says what it was: signed under the gun.'],
      fall:['1893年1月,莉莉乌欧卡拉尼女王试图颁布新宪法恢复王权,一个以美国人为主的「安全委员会」随即发动政变,美国军舰「波士顿」号的陆战队登陆「护侨」,女王为避免流血而让权。美国总统克利夫兰派人调查后认定这次推翻不合法,主张恢复王位,但国会未予配合;1898年美西战争期间,美国以国会联合决议兼并夏威夷。1959年成为第五十个州。','In January 1893 Queen Liliʻuokalani tried to promulgate a new constitution restoring the crown\'s power, and a Committee of Safety made up largely of Americans launched a coup; marines from the USS Boston landed to protect American interests, and the queen yielded rather than have blood shed. President Cleveland sent an investigator, concluded the overthrow was unlawful and pressed for the monarchy to be restored, but Congress would not follow; in 1898, during the Spanish-American War, the United States annexed the islands by joint resolution. Hawaii became the fiftieth state in 1959.'],
      legacy:['疾病的打击贯穿始终:1778年接触时人口估计在数十万(具体数字争议大),到1890年代原住民人口约剩四万。1993年,美国国会通过「道歉决议」,由克林顿总统签署,正式为1893年推翻夏威夷王国道歉,并承认夏威夷人从未通过公投放弃主权——这在美国史上极罕见。夏威夷语在1978年重获官方地位,沉浸式学校把它教回给孩子;呼拉舞与航海传统在二十世纪的文化复兴中重新兴盛,复原双体舟「Hōkūleʻa」号正是从这里出发的。','Disease ran through the whole story: the population at contact in 1778 is estimated in the hundreds of thousands, with the figure much argued over, and by the 1890s about forty thousand Native Hawaiians remained. In 1993 Congress passed an Apology Resolution, signed by President Clinton, formally apologising for the 1893 overthrow and acknowledging that Hawaiians had never surrendered their sovereignty by plebiscite — something very rare in American history. Hawaiian regained official status in 1978 and immersion schools have been teaching it back to children; hula and the voyaging tradition revived in the twentieth century, and the rebuilt double canoe Hōkūleʻa set out from here.'] },
  d:'卡美哈梅哈一世1795年统一各岛(考艾岛1810年以协议归附),靠的是夏威夷自己的组织加上欧洲的火器与顾问;1840年代获英法美承认为独立国家,有宪法、议会与使节。1848年大分地把土地变为私产,大片落入制糖种植园主之手;1887年「刺刀宪法」以武力削夺王权;1893年以美国种植园主为主的委员会在美军陆战队登陆配合下推翻了莉莉乌欧卡拉尼女王。疾病的打击比这一切都大:1778年欧洲人到达时岛上有几十万人,到1890年代只剩约四万。克利夫兰总统认定不合法,国会仍于1898年兼并。1993年美国国会正式道歉。' },
{ l:'oc', s:'oceania', v:1, n:'汤加王国', k:[[1826,0],[1845,.1],[1875,.14],[1900,.12],[1970,.14],[2025,.14]], b:'图普一世统一各岛建起的现代王国,1875年有了宪法,至今仍由同一王室统治。',
  e:{ n:'The Kingdom of Tonga', w:'Tonga', b:'The modern kingdom Tupou I built by uniting the islands, with a constitution from 1875 and the same royal house on the throne today.', d:'After the old Tuʻi Tonga network had faded the islands fell into decades of civil war. A chief of Haʻapai, Tāufaʻāhau, won them one group at a time from the 1820s, was baptised in 1831 as Siaosi — George — and in 1845 took the Tuʻi Kanokupolu title, the one that carried real power, the date usually given for the start of the modern kingdom. As George Tupou I he issued a code of laws in 1862 that freed commoners from arbitrary service to the chiefs, and in 1875 a written constitution with a parliament. A treaty of friendship with Britain in 1900 made Tonga a protected state — Britain handled its foreign affairs while the king kept the throne and the running of the country — and full independence came in 1970. Queen Sālote Tupou III reigned from 1918 to 1965; reforms in 2010 gave the parliament an elected majority for the first time. Tonga has about a hundred thousand people at home and roughly as many living abroad.', f:{ 'Peak':'19th c. to today', 'Centre':'Nukuʻalofa on Tongatapu', 'Figures':'George Tupou I, Sālote Tupou III', 'Legacy':'a Pacific monarchy that was never colonised, a constitution of 1875, the Tongan fine mat and rugby' } },
  f:{ '鼎盛':'19世纪至今', '中心':'努库阿洛法(汤加塔布岛)', '人物':'乔治·图普一世、萨洛特·图普三世', '成就':'从未被殖民的太平洋王国、1875年宪法、汤加细编席与橄榄球' },
  qh:{ born:['打了几十年仗,一个酋长把各岛并成一国','Decades of war, and one chief made the islands one country'],
       rule:['1875年的宪法,今天还在用','The constitution of 1875 is still in force'],
       money:['海外汤加人寄回来的钱,撑起了很大一块经济','Money sent home by Tongans abroad carries much of the economy'],
       power:['英国管了七十年外交,王位始终是自己的','From 1900 Britain ran the foreign affairs; the throne stayed Tongan'],
       fall:['这条色带没有终点——王国今天还在','This band has no end: the kingdom is still there'],
       legacy:['2022年那次喷发,全世界的气压计都记下了','The 2022 eruption registered on barometers around the world'] },
  q:{ born:['图伊汤加的网络散掉以后,汤加各岛打了几十年内战。哈阿派群岛的一位酋长陶法阿豪从1820年代起一个群岛一个群岛地打下去,1831年受洗改名为乔治(汤加语作西奥西),1845年接过「图伊卡诺库波卢」这个掌实权的头衔——通常把这一年当作现代汤加王国的开始。他就是乔治·图普一世,统治到1893年去世,活了九十多岁。','After the Tuʻi Tonga network came apart the islands fought decades of civil war. A chief of the Haʻapai group, Tāufaʻāhau, won them one group at a time from the 1820s, was baptised in 1831 as George — Siaosi in Tongan — and in 1845 took the ruling title, Tuʻi Kanokupolu; that year is usually taken as the beginning of the modern kingdom. He reigned as George Tupou I until his death in 1893, aged over ninety.'],
      rule:['1862年他颁布法典,解除平民对酋长的人身依附——平民不再无偿为酋长劳作,土地由王室分配。1875年颁布成文宪法,设立议会,议席由世袭贵族与民选代表分担;这部宪法经过多次修订,今天仍是汤加的根本法。一位英国出生的传教士帮着起草,但王权始终握在图普家族手里。','In 1862 he issued a code of laws that ended commoners\' personal bondage to the chiefs — they no longer owed unpaid labour, and land was allotted by the crown. In 1875 came a written constitution with a parliament whose seats were shared between hereditary nobles and elected representatives; much amended, it is still Tonga\'s basic law. A British-born missionary, Shirley Baker, helped draft it, but the crown stayed with the Tupou family.'],
      money:['汤加陆地不大,散在一百七十来座岛上,可耕地少,主要出口是南瓜、香草与鱼;真正撑起经济的是在新西兰、澳大利亚和美国的汤加人寄回来的钱,占国内生产总值的比重在世界上属于最高的一档。海外汤加人的数量与国内相当。','Tonga\'s land is small and spread over some hundred and seventy islands, farmland is scarce, and the main exports are squash, vanilla and fish; what really carries the economy is money sent home by Tongans in New Zealand, Australia and the United States, a share of national output among the highest in the world. About as many Tongans live abroad as at home.'],
      power:['1900年汤加与英国签订友好条约,成为受英国保护的国家:外交由英国代管,但国王仍是国王,内政自己管——这就是「太平洋岛国中唯一没有被殖民」这一说法的依据。1970年6月4日恢复完全独立,加入英联邦。萨洛特·图普三世女王在位四十七年(1918—1965),1953年到伦敦参加英国女王加冕典礼,大雨中坚持坐敞篷马车向人群致意,成了那天最出名的一幕。','In 1900 Tonga signed a treaty of friendship with Britain and became a protected state: Britain handled foreign affairs, but the king remained king and internal government stayed Tongan — which is the basis of the statement that Tonga is the one Pacific island nation never colonised. Full independence returned on 4 June 1970, within the Commonwealth. Queen Sālote Tupou III reigned for forty-seven years, 1918-1965; at the coronation in London in 1953 she rode through the pouring rain in an open carriage, waving to the crowds, and became the most talked-about figure of the day.'],
      fall:['2006年首都努库阿洛法发生要求民主的骚乱,中心城区大片被烧;乔治·图普五世随后推动改革,2010年举行了首次由民选议员占多数的选举,国王主动交出大部分行政权力。2012年起在位的是图普六世。','In 2006 riots calling for democracy burned much of central Nukuʻalofa; George Tupou V then pushed through reforms, and in 2010 came the first election in which popularly elected members formed a majority of parliament, the king giving up most of his executive power. Tupou VI has reigned since 2012.'],
      legacy:['2022年1月15日,首都以北约六十多公里的洪阿汤加—洪阿哈阿帕伊海底火山喷发,喷发柱冲到五十多公里高,冲击波绕地球传了好几圈,全世界的气压计都记下了它;海底电缆被震断,汤加与外界失联好几天,电缆修好用了约五个星期。汤加的橄榄球在国际上很有名,「西帕陶」战舞是国家队赛前的固定仪式;细编席仍是最高规格的礼物,汤加帝国时代传下来的这一条一直没断。','On 15 January 2022 the undersea volcano Hunga Tonga-Hunga Haʻapai, some sixty-odd kilometres north of the capital, erupted; the plume rose more than fifty kilometres, the pressure wave went round the earth several times and was recorded on barometers everywhere, and the cut of the undersea cable left Tonga out of contact for days; it took some five weeks to repair. Tongan rugby is known worldwide, and the sipi tau war dance opens the national team\'s matches; the fine mat is still the highest form of gift, one thread from the days of the Tuʻi Tonga that never broke.'] },
  d:'旧的图伊汤加网络衰落后,各岛内战数十年。哈派的酋长陶法阿豪从1820年代起一片一片地把它们打下来,1831年受洗取教名西奥西(即乔治),1845年接过最高头衔,是为乔治·图普一世;1862年法典解除平民对酋长的依附,1875年颁布宪法。1900年与英国签友好条约成为受保护国,外交由英国代管、王位与内政自主,1970年恢复完全独立。萨洛特·图普三世女王在位从1918年到1965年;2010年改革后议会多数首次由民选产生。王国至今由同一王室统治,本土约十万人,住在海外的差不多同样多。' },
{ l:'oc', s:'west', v:2, n:'欧洲殖民大洋洲', k:[[1788,0],[1850,.34],[1900,.56],[1940,.4],[1975,.08],[1990,0]], b:'从一座流放犯的营地开始,一百年里整片大洋被瓜分完毕。',
  e:{ n:'Colonial Oceania', b:'It began as a convict camp and within a century the whole ocean had been divided up.', d:'The First Fleet landed eleven ships of convicts at Sydney Cove in 1788, and the settlement that began as a prison became the base from which Britain took the continent. New Zealand followed in 1840, Fiji in 1874, and in the 1880s and 1890s Britain, France, Germany and the United States partitioned nearly every remaining island group between them. Missionaries arrived ahead of or alongside the flags and reshaped island societies at least as much. From the 1860s the labour trade known as blackbirding carried some sixty-two thousand Pacific Islanders to the cane fields of Queensland and twenty-seven thousand more to Fiji, some recruited and many deceived or seized. Introduced disease killed on a larger scale than anything else throughout, as it did across the Pacific. Decolonisation began with Samoa in 1962, and by 1980 most of the Pacific was independent — though France retains New Caledonia and French Polynesia to this day.', f:{ 'Peak':'19th c. to early 20th', 'Centre':'Sydney Cove; Aotearoa (New Zealand)', 'Legacy':'redrawn borders, plantation economies, the churches and the languages left behind' } },
  f:{ '鼎盛':'19世纪至20世纪初', '中心':'悉尼湾;奥特亚罗瓦(新西兰)', '成就':'重画的边界、种植园经济、留下的教会与语言' },
  qh:{ born:['第一批船装的是犯人,不是移民','The first ships carried convicts, not settlers'],
       rule:['国旗到之前,教堂常常已经建好了','The church was often built before the flag arrived'],
       money:['甘蔗田要人手,就有了「捉黑鸟」','The cane fields needed hands, so came blackbirding'],
       power:['1880年代,几个国家把整片大洋分完了','In the 1880s a handful of states carved up an entire ocean'],
       fall:['1962年萨摩亚独立,是太平洋第一个','Samoa in 1962 was the first Pacific nation to go free'],
       legacy:['法国至今还留着新喀里多尼亚','France still holds New Caledonia today'] },
  q:{ born:['1788年1月,第一舰队十一艘船在悉尼湾登陆,船上装的主要是流放犯——美洲独立之后,英国需要新的流放地。这块地上本来住着人:占地、断水源与持续百余年的边疆屠杀,是这条带从头到尾都在做的事,只是记在了另一条带的账上。这个开端很特别:大洋洲的殖民不是从商站或传教站开始的,是从一座监狱开始的。营地随后变成据点,再变成占领整块大陆的基地。英国宣称对澳大利亚的主权所依据的正是「无主地」原则,这一原则直到1992年才被马博案推翻。','In January 1788 the First Fleet landed eleven ships at Sydney Cove carrying mostly convicts — after American independence Britain needed somewhere new to send them. People already lived on this land: taking it, cutting off water and more than a century of frontier killing is what this band did throughout, though the cost is written on another band. The beginning is unusual: colonisation in Oceania started not from a trading post or a mission but from a prison. The camp became a foothold and then the base from which a continent was taken. Britain\'s claim to Australia rested on the doctrine of terra nullius, land belonging to no one, which stood until the Mabo judgment of 1992.'],
      rule:['传教士常常比国旗先到。伦敦传道会、卫理公会与天主教各修会自19世纪初起进入各岛,带来文字(许多太平洋语言的第一套拼写法出自传教士之手)、学校与新的服饰、婚姻与安息日规矩,也压制了大量本地仪式与舞蹈。今天太平洋岛国普遍高度基督教化,这个格局就是那时定下的。评价上要两面看:同一批人既记录并保存了语言,也断掉了许多传统。','The missionaries often arrived before the flags. The London Missionary Society, the Methodists and the Catholic orders moved into the islands from the early nineteenth century, bringing writing — the first orthography for many Pacific languages was a missionary\'s work — along with schools and new rules about dress, marriage and the Sabbath, while suppressing a great deal of local ceremony and dance. That the Pacific island nations are strongly Christian today was settled then. It has to be read both ways: the same people who recorded and preserved languages also cut off many traditions.'],
      money:['昆士兰与斐济的甘蔗园需要大量劳力,于是有了「捉黑鸟(blackbirding)」:1863年起约六万二千名太平洋岛民被运往昆士兰的种植园、另有两万七千人以上被运往斐济,其中有自愿受雇的,也有大量被欺骗、诱拐甚至武力掳走的。1872年后英国立法管制,但滥用持续多年。这条产业链把美拉尼西亚的人口结构、语言(皮钦语的形成)与岛屿社会一并改变了。','The cane plantations of Queensland and Fiji needed labour in quantity, and blackbirding followed: from 1863 about sixty-two thousand Pacific Islanders were carried to Queensland and twenty-seven thousand more to Fiji, some signing on willingly and many deceived, lured or taken by force. Britain legislated to control it after 1872, but abuses continued for years. The trade changed the population, the languages — this is where Pacific pidgins formed — and the societies of Melanesia together.'],
      power:['1880至1900这二十年间,整片太平洋被分完了。英国、法国、德国、美国按势力范围切分:斐济1874年成为英国殖民地,新几内亚东北归德国、东南归英国,萨摩亚1899年由德美两国分割,法国拿下新喀里多尼亚与波利尼西亚,美国取得夏威夷(1898)与关岛、东萨摩亚。这个过程和同期的非洲瓜分是同一件事的两个战场,只是海面比陆地更容易被地图上的直线切开。','Between 1880 and 1900 the entire Pacific was divided. Britain, France, Germany and the United States carved it into spheres: Fiji became a British colony in 1874, north-east New Guinea went to Germany and the south-east to Britain, Samoa was split between Germany and the United States in 1899, France took New Caledonia and Polynesia, and the United States acquired Hawaii in 1898 along with Guam and eastern Samoa. This was the same event as the scramble for Africa on a second front, except that an ocean is even easier to cut with straight lines on a map.'],
      fall:['太平洋战争把这套秩序打散:1942至1945年间美日在此鏖战,日本一度占领大片岛屿,战后美国接管了原德属、日属的密克罗尼西亚。去殖民化从1962年萨摩亚独立开始——太平洋第一个,随后是瑙鲁1968、斐济与汤加1970、巴布亚新几内亚1975、所罗门群岛与图瓦卢1978、基里巴斯1979、瓦努阿图1980。','The Pacific War broke the arrangement apart: American and Japanese forces fought across it between 1942 and 1945, Japan held large stretches of it for a time, and after the war the United States took over the former German and Japanese Micronesia. Decolonisation began with Samoa in 1962, the first in the Pacific, followed by Nauru in 1968, Fiji and Tonga in 1970, Papua New Guinea in 1975, Solomon Islands and Tuvalu in 1978, Kiribati in 1979 and Vanuatu in 1980.'],
      legacy:['这条带并没有完全归零。法国至今保有新喀里多尼亚与法属波利尼西亚(新喀里多尼亚2018至2021年间举行了三次独立公投,均未通过,最后一次因当地反对而遭抵制);美国保有关岛、东萨摩亚与北马里亚纳。核试验是另一笔遗产:美国1946至1958年在比基尼与埃内韦塔克试爆67次,法国1966至1996年在穆鲁罗瓦等地试爆193次,受影响的社区至今仍在索赔。','The band does not fall to zero. France still holds New Caledonia and French Polynesia — New Caledonia held three independence referendums between 2018 and 2021, all of which failed, the last boycotted by much of the local movement — and the United States holds Guam, American Samoa and the Northern Marianas. Nuclear testing is the other legacy: the United States detonated 67 devices at Bikini and Enewetak between 1946 and 1958 and France 193 at Moruroa and elsewhere between 1966 and 1996, and the affected communities are still seeking redress.'] },
  d:'1788年第一舰队十一条船把流放犯送上悉尼湾——大洋洲的殖民从一座监狱开始,那座监狱后来成了英国拿下整块大陆的基地。新西兰1840年、斐济1874年接着被并入。传教士常比国旗先到,重塑了岛屿社会;1860年代起的劳工贸易「捉黑鸟」把约六万二千名太平洋岛民运往昆士兰的甘蔗园、另有两万七千人运往斐济,有的是招募,更多是被骗或被抓。而自始至终杀人最多的是外来传染病。1880—1900年间英法德美把整片太平洋分完。去殖民化自1962年萨摩亚起,但法国至今保有新喀里多尼亚与法属波利尼西亚,核试验的赔偿争议仍未了结。' },

{ l:'oc', s:'west', v:0, n:'澳新与太平洋岛国', k:[[1901,0],[1950,.4],[1990,.56],[2025,.6]], b:'两个移民国家,加上十几个被海平面推到谈判桌前的小国。',
  e:{ n:'Australia, New Zealand and the Pacific states', b:'Two settler nations, and a dozen small states pushed to the negotiating table by a rising sea.', d:'Australia federated in 1901 and New Zealand became a dominion in 1907, both opening with racial immigration restrictions — the White Australia policy lasted until 1973. The Pacific island states became independent from 1962 onward, and although they are small in population they hold enormous exclusive economic zones: Kiribati alone governs an ocean area larger than India. That combination has made them unusually effective diplomatically, and the 1.5°C target in the Paris Agreement was pushed hardest by them, because for Tuvalu and Kiribati sea level is not a projection but a survival question. Reckoning with the past has run in parallel: the 1967 referendum and the Mabo judgment in Australia, the Waitangi Tribunal in New Zealand from 1975, and a formal apology to the Stolen Generations in 2008.', f:{ 'Peak':'20th c. to now', 'Centre':'Canberra; Wellington', 'Legacy':'the 1.5°C target, the Pacific Islands Forum, multicultural settler societies' } },
  f:{ '鼎盛':'20世纪至今', '中心':'堪培拉;惠灵顿', '成就':'1.5℃ 目标、太平洋岛国论坛、多族裔的移民社会' },
  qh:{ born:['1901年建国,同一年就立法把非欧洲人挡在门外','Federated in 1901, and that same year legislated to keep non-Europeans out'],
       rule:['基里巴斯管的海,比印度整个国家还大','Kiribati governs an ocean bigger than the whole of India'],
       money:['铁矿石装上船,多半开往东亚','The iron ore sails to East Asia'],
       power:['巴黎协定里那个1.5℃,是他们逼出来的','The 1.5°C in the Paris Agreement is there because they pushed'],
       fall:['对图瓦卢来说,海平面不是预测','For Tuvalu, sea level is not a projection'],
       legacy:['太平洋不是「大洋里的小岛」,是「岛屿之海」','Not small islands in a far sea, but a sea of islands'] },
  q:{ born:['1901年澳大利亚六个殖民地联邦建国,1907年新西兰成为自治领。两国建国之初都以种族限制移民:澳大利亚联邦成立当年就通过《移民限制法》,即后来所称的「白澳政策」,以「听写测验」为工具把非欧洲移民挡在门外,该政策直到1973年才被完全废除。新西兰亦有类似的人头税等限制。今天两国都是高度多元的移民社会,这个转变发生在半个世纪之内。','Australia federated from six colonies in 1901 and New Zealand became a dominion in 1907. Both began with racial restrictions on immigration: in its first year the Australian Commonwealth passed the Immigration Restriction Act, later known as the White Australia policy, which used a dictation test to keep non-Europeans out and was not fully dismantled until 1973. New Zealand had comparable measures, including a poll tax. Both are now highly diverse immigrant societies, a change that happened inside half a century.'],
      rule:['太平洋岛国人口很小——图瓦卢约一万一千人,瑙鲁约一万二千人——但它们管辖的专属经济区极其辽阔:基里巴斯的海域面积超过三百五十万平方公里,比印度整个国家还大。金枪鱼渔业许可是许多国家的主要财政来源,「瑙鲁协定」缔约方联合管理西太平洋金枪鱼,是小国联合起来提高议价能力的成功案例。','The Pacific states are tiny in population — Tuvalu about eleven thousand people, Nauru about twelve — but the exclusive economic zones they administer are vast: Kiribati\'s ocean area is over 3.5 million square kilometres, larger than the whole of India. Licensing tuna fishing is the main public revenue for several of them, and the Parties to the Nauru Agreement, who jointly manage western Pacific tuna, are a successful case of small states combining to raise their bargaining power.'],
      money:['澳大利亚的经济长期建立在矿产与农业出口上,如今铁矿石、煤与液化天然气的最大买家在东亚——这条带与东亚那条带之间的联系,比地图上看起来紧密得多。新西兰以乳制品、肉类与旅游为主。岛国则普遍依赖渔业许可、侨汇与援助,经济体量小且对外部冲击极敏感。','Australia\'s economy has long rested on mineral and farm exports, and the largest buyers of its iron ore, coal and LNG are now in East Asia — the link between this band and the East Asian one is much closer than the map suggests. New Zealand runs on dairy, meat and tourism. The island states depend largely on fishing licences, remittances and aid, with small economies that are highly exposed to outside shocks.'],
      power:['这些小国在气候谈判上的分量远超它们的体量。2015年巴黎协定里那句「努力将升温控制在 1.5℃ 以内」,主要是由小岛屿国家联盟(AOSIS)推动写入的——对图瓦卢、基里巴斯、马绍尔群岛这些平均海拔只有两三米的国家来说,海平面上升不是一个预测模型,是国家能否存在的问题。图瓦卢已在筹划法律与数字形态的「国家延续」方案,以应对领土可能不再宜居的情形。','These small states carry far more weight in climate negotiations than their size suggests. The line in the 2015 Paris Agreement about pursuing efforts to limit warming to 1.5°C is there largely because the Alliance of Small Island States pushed it in — for Tuvalu, Kiribati and the Marshall Islands, averaging two or three metres above sea level, rising seas are not a modelling exercise but a question of whether the country continues to exist. Tuvalu has begun planning for legal and digital forms of statehood should its territory cease to be habitable.'],
      fall:['这条带没有终点,但它一直在和过去清账。澳大利亚:1967年公投将原住民计入人口普查,1992年马博案推翻「无主地」,2008年陆克文总理代表议会就「被偷走的一代」道歉,2023年「原住民之声」入宪公投未获通过。新西兰:1975年设怀唐伊仲裁庭处理历史索赔,多起大宗和解附有官方道歉,1987年毛利语成为官方语言。','The band has no end point, and it keeps settling accounts with the past. In Australia the 1967 referendum brought Aboriginal people into the census, the Mabo judgment overturned terra nullius in 1992, Prime Minister Rudd apologised to the Stolen Generations on behalf of parliament in 2008, and a 2023 referendum on an Indigenous Voice in the constitution was not carried. In New Zealand the Waitangi Tribunal has handled historical claims since 1975, several large settlements have come with formal apologies, and te reo Māori became an official language in 1987.'],
      legacy:['太平洋岛国论坛是本区域的主要政治平台,近年成为大国竞逐影响力的场所。区域内部也在重新定义自己:学者埃佩利·豪奥法(Epeli Hauʻofa)提出,不该把太平洋看作「大洋里的一些小岛」,而应看作「岛屿之海」——把海洋视为连接而非隔绝,这正是拉皮塔航海者、汤加人与毛利人一直以来的看法。这个观念今天已经成为区域身份的基础。','The Pacific Islands Forum is the main political platform of the region and has lately become a place where larger powers compete for influence. The region is also redefining itself: the scholar Epeli Hauʻofa argued that the Pacific should not be seen as a few small islands in a far sea but as a sea of islands — the ocean as what connects rather than what separates, which is exactly how the Lapita voyagers, the Tongans and the Māori always saw it. That idea is now the basis of a regional identity.'] },
  d:'1901年澳大利亚联邦、1907年新西兰自治领,两国开局都以种族限制移民,「白澳政策」直到1973年才废除。太平洋岛国自1962年起陆续独立,人口极小但专属经济区极大(基里巴斯的海域比印度还大)。地小而海大这一条让它们在外交上格外有力:巴黎协定里的 1.5℃ 目标主要由小岛屿国家推动写入,因为对图瓦卢和基里巴斯来说,海平面不是一项预测而是一个生存问题。清账与这一切同时进行:澳大利亚的1967年公投与马博案、新西兰1975年起的怀唐伊仲裁庭,以及2008年对「被偷走的一代」的正式道歉。' },
];
